#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// ADS1115 I2C address
#define ADS1115_ADDR 0x48

// ADS1115 register addresses
#define ADS1115_REG_CONFIG 0x01
#define ADS1115_REG_CONVERT 0x00

// ADS1115 configuration values
#define ADS1115_CONFIG_OS_SINGLE 0x8000  // Start single conversion
#define ADS1115_CONFIG_MUX_SINGLE_0 0x4000 // AIN0 single-ended
#define ADS1115_CONFIG_PGA_4_096V 0x0200  // PGA ±4.096V
#define ADS1115_CONFIG_DR_128SPS 0x0080   // 128 SPS
#define ADS1115_CONFIG_COMP_MODE_TRAD 0x0000 // Traditional comparator
#define ADS1115_CONFIG_COMP_POL_LOW 0x0000 // Comparator polarity low
#define ADS1115_CONFIG_COMP_LAT_NON 0x0000 // Non-latching comparator
#define ADS1115_CONFIG_COMP_QUE_DISABLE 0x0003 // Disable comparator

// MLX91219 sensitivity (mV/A)
#define MLX91219_SENSITIVITY 40.0

// Zero-current offset (V)
#define MLX91219_ZERO_CURRENT_OFFSET 2.5

// I2C bus
#define I2C_BUS 1

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Signal handler for SIGINT
void sigint_handler(int signal)
{
    terminate = 1;
}

// Function to write a 16-bit value to an ADS1115 register
int write_register(int handle, uint16_t reg, uint16_t value)
{
    char buf[3];
    buf[0] = reg;
    buf[1] = (value >> 8) & 0xFF; // MSB
    buf[2] = value & 0xFF;      // LSB

    int result = i2cWriteI2CBlockData(handle, reg, buf + 1, 2); // Write MSB and LSB
    if (result != 2) {
        fprintf(stderr, "Error writing to register 0x%04X: %d\n", reg, result);
        return -1;
    }
    return 0;
}

// Function to read a 16-bit value from an ADS1115 register
int read_register(int handle, uint16_t reg, uint16_t *value)
{
    char buf[1];
    buf[0] = reg;

    int result = i2cWriteI2CBlockData(handle, reg, buf, 1); // Write register address
    if (result != 1) {
        fprintf(stderr, "Error writing register address for read: %d\n", result);
        return -1;
    }

    char read_buf[2];
    result = i2cReadI2CBlockData(handle, reg, read_buf, 2); // Read 2 bytes
    if (result != 2) {
        fprintf(stderr, "Error reading from register 0x%04X: %d\n", reg, result);
        return -1;
    }

    *value = (read_buf[0] << 8) | read_buf[1]; // Combine MSB and LSB
    return 0;
}

// Function to read the current from the MLX91219 sensor
float read_current(int handle)
{
    uint16_t config_value = ADS1115_CONFIG_OS_SINGLE | ADS1115_CONFIG_MUX_SINGLE_0 | ADS1115_CONFIG_PGA_4_096V | ADS1115_CONFIG_DR_128SPS | ADS1115_CONFIG_COMP_MODE_TRAD | ADS1115_CONFIG_COMP_POL_LOW | ADS1115_CONFIG_COMP_LAT_NON | ADS1115_CONFIG_COMP_QUE_DISABLE;

    if (write_register(handle, ADS1115_REG_CONFIG, config_value) != 0) {
        fprintf(stderr, "Error configuring ADS1115\n");
        return -1.0;
    }

    // Wait for conversion to complete (at least 8ms for 128 SPS)
    gpioDelay(10000); // 10ms

    uint16_t conversion_value;
    if (read_register(handle, ADS1115_REG_CONVERT, &conversion_value) != 0) {
        fprintf(stderr, "Error reading conversion value\n");
        return -1.0;
    }

    // Convert ADC value to voltage
    float voltage = (float)conversion_value * 4.096 / 32768.0;

    // Convert voltage to current
    float current = (voltage - MLX91219_ZERO_CURRENT_OFFSET) / (MLX91219_SENSITIVITY / 1000.0);

    return current;
}

int main()
{
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for SIGINT
    signal(SIGINT, sigint_handler);

    // Main loop
    while (!terminate) {
        float current = read_current(i2c_handle);

        if (current >= 0) {
            printf("Current: %.2f A\n", current);
        } else {
            fprintf(stderr, "Error reading current\n");
        }

        gpioDelay(500000); // 500ms
    }

    // Close I2C bus and terminate pigpio
    i2cClose(i2c_handle);
    gpioTerminate();

    printf("Program terminated gracefully.\n");
    return 0;
}

