#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Define constants
#define FLAME_SENSOR_GPIO 4
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define MCP3008_CHANNEL 0
#define TEMPERATURE_MIN 10.0
#define TEMPERATURE_MAX 40.0
#define ADC_MAX 1023

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_pigpio();
int initialize_spi();
int read_flame_sensor();
int read_mcp3008(int channel);
float convert_adc_to_temperature(int adc_value);
int log_data(int flame_detected, float temperature);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Initializes the pigpio library
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Initializes the SPI interface
int initialize_spi() {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // CE0, 1MHz, Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI initialisation failed: %d\n", spi_handle);
        return -1;
    }
    return 0;
}

// Reads the flame sensor's digital output
int read_flame_sensor() {
    return gpioRead(FLAME_SENSOR_GPIO);
}

// Reads the analog value from the MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    unsigned char spi_tx_buf[3];
    unsigned char spi_rx_buf[3];

    // Construct SPI message (MCP3008 datasheet)
    spi_tx_buf[0] = 0x01; // Start bit
    spi_tx_buf[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    spi_tx_buf[2] = 0x00; // Don't care

    if (spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3) != 0) {
        fprintf(stderr, "SPI transfer failed\n");
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];
    return adc_value;
}

// Converts the ADC value to an approximate temperature
float convert_adc_to_temperature(int adc_value) {
    if (adc_value < 0 || adc_value > ADC_MAX) {
        fprintf(stderr, "Invalid ADC value: %d\n", adc_value);
        return -1.0; // Indicate error
    }

    float temperature = TEMPERATURE_MIN + (float)adc_value * (TEMPERATURE_MAX - TEMPERATURE_MIN) / ADC_MAX;
    return temperature;
}

// Logs the data to a CSV file
int log_data(int flame_detected, float temperature) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%d,%.2f\n", timestamp, flame_detected, temperature);
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

int main() {
    // Install signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize pigpio
    if (initialize_pigpio() != 0) {
        return 1;
    }

    // Initialize SPI
    if (initialize_spi() != 0) {
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("flame_data.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Read flame sensor
        int flame_detected = read_flame_sensor();

        // Read MCP3008
        int adc_value = read_mcp3008(MCP3008_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Failed to read MCP3008, skipping log entry\n");
            gpioDelay(1000); // Wait 1 second
            continue;
        }

        // Convert ADC value to temperature
        float temperature = convert_adc_to_temperature(adc_value);
        if (temperature < 0) {
            fprintf(stderr, "Failed to convert ADC to temperature, skipping log entry\n");
            gpioDelay(1000); // Wait 1 second
            continue;
        }

        // Log data
        if (log_data(flame_detected, temperature) != 0) {
            fprintf(stderr, "Failed to log data\n");
        }

        // Wait 1 second
        gpioDelay(1000);
    }

    // Cleanup
    fclose(log_file);
    spiClose(spi_handle);
    gpioTerminate();

    return 0;
}

