#define ADS1115_REG_CONVERT 0x00
#define CONFIG_SINGLE_SHOT 0x8329 // Single-shot, AIN0, +/-4.096V, 128 SPS
#define CONFIG_CONT_MODE 0x8343 // Continuous, AIN0, +/-4.096V, 128 SPS
#define CONFIG_CONT_MODE_DRIVE 0x8363 // Continuous, AIN0, +/-4.096V, 250 SPS

// Global variables
static volatile int running = 1;
static int i2c_handle;
static FILE *log_file;
static time_t last_flame_time = 0;

// Function prototypes
int init_gpio();
int init_i2c();
int read_temperature();
void flame_detected_isr(int gpio, int level, uint32_t tick, void *user_data);
void log_event(const char *message);
