int init_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(FLAME_SENSOR_GPIO, PI_INPUT);
    gpioSetPullUpDown(FLAME_SENSOR_GPIO, PI_PUD_UP);
    gpioSetMode(BUZZER_GPIO, PI_OUTPUT);

    // Set up ISR for flame sensor
    if (gpioSetISRFuncEx(FLAME_SENSOR_GPIO, FALLING_EDGE, 0, flame_detected_isr, NULL) != 0) {
        fprintf(stderr, "Failed to set ISR for flame sensor\n");
        gpioTerminate();
        return 1;
    }

    return 0;
}

// Function to initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        return 1;
    }

    // Configure ADS1115 for single-shot mode
    char config_data[3];
    config_data[0] = ADS1115_REG_CONFIG;
    config_data[1] = (CONFIG_SINGLE_SHOT >> 8) & 0xFF;
    config_data[2] = CONFIG_SINGLE_SHOT & 0xFF;

    if (i2cWriteDevice(i2c_handle, config_data, 3) != 0) {
        fprintf(stderr, "Failed to write to I2C device\n");
        i2cClose(i2c_handle);
        return 1;
