    if (i2cReadDevice(i2c_handle, data, 2) != 2) {
        fprintf(stderr, "Failed to read from I2C device\n");
        return -1;
    }

    int16_t raw_value = (data[0] << 8) | data[1];
    raw_value = raw_value >> 4; // Remove the 4 least significant bits

    // Convert raw value to voltage (assuming +/-4.096V range)
    float voltage = (float)raw_value * 4.096 / 32768.0;

