    // Set up signal handling
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (init_gpio() != 0) {
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("fire_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    printf("Fire detection system started. Press Ctrl+C to exit.\n");

    while (running) {
        // Read temperature
        int temperature = read_temperature();
        if (temperature > 0) {
            if (temperature > 60) {
                log_event("Temperature above 60°C!");
                gpioWrite(BUZZER_GPIO, 1); // Activate buzzer
                gpioDelay(2000); // Keep buzzer on for 2 seconds
                gpioWrite(BUZZER_GPIO, 0); // Deactivate buzzer
            } else {
                char temp_str[20];
                snprintf(temp_str, sizeof(temp_str), "Temperature: %d°C", temperature);
                log_event(temp_str);
            }
        } else {
            log_event("Failed to read temperature.");
        }

        gpioDelay(100); // Poll every 100ms
    }

    // Cleanup
    gpioWrite(BUZZER_GPIO, 0); // Ensure buzzer is off
    gpioSetISRFuncEx(FLAME_SENSOR_GPIO, FALLING_EDGE, 0, NULL, NULL); // Deregister ISR
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    printf("Exiting.\n");
    return 0;
}

