#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

// Configuration
#define SPI_DEVICE "/dev/spidev0.0"
#define GPIO_CHIP "gpiochip4" // Try this first, fall back to 0 if needed
#define GPIO_CHIP_BACKUP "gpiochip0"
#define FAN_GPIO 18
#define SAMPLE_RATE_HZ 1
#define SAMPLE_PERIOD_US (1000000 / SAMPLE_RATE_HZ)
#define VREF 3.3f
#define DEFAULT_SENSITIVITY 0.1f // 100 mV/A = 0.1 V/A
#define DEFAULT_THRESHOLD 5.0f

// Global variables (minimize usage)
static int spi_fd = -1;
static struct gpiod_chip *gpio_chip = NULL;
static struct gpiod_line *fan_line = NULL;
static FILE *log_file = NULL;
static float sensitivity = DEFAULT_SENSITIVITY;
static float threshold = DEFAULT_THRESHOLD;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int spi_init(void);
int gpio_init(void);
int read_adc(int channel);
float adc_to_voltage(int adc_value);
float voltage_to_current(float voltage);
void control_fan(float current);
void log_data(float current);
void signal_handler(int sig);
void cleanup(void);

// SPI Initialization
int spi_init(void) {
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }

    // Configure SPI mode
    uint8_t mode = 0; // SPI mode 0
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("Error setting SPI mode");
        close(spi_fd);
        return -1;
    }

    // Configure SPI bits per word
    uint8_t bits = 8;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        perror("Error setting SPI bits per word");
        close(spi_fd);
        return -1;
    }

    // Configure SPI max speed
    uint32_t speed = 1000000; // 1 MHz
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("Error setting SPI max speed");
        close(spi_fd);
        return -1;
    }

    return 0;
}

// GPIO Initialization
int gpio_init(void) {
    gpio_chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!gpio_chip) {
        fprintf(stderr, "Error opening GPIO chip %s\n", GPIO_CHIP);
        gpio_chip = gpiod_chip_open_by_name(GPIO_CHIP_BACKUP);
        if (!gpio_chip) {
            fprintf(stderr, "Error opening GPIO chip %s\n", GPIO_CHIP_BACKUP);
            return -1;
        }
        printf("Using GPIO chip %s as backup.\n", GPIO_CHIP_BACKUP);
    }

    fan_line = gpiod_chip_get_line(gpio_chip, FAN_GPIO);
    if (!fan_line) {
        fprintf(stderr, "Error getting GPIO line %d\n", FAN_GPIO);
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    if (gpiod_line_request_output(fan_line, "current_sensor", 0) < 0) {
        fprintf(stderr, "Error requesting GPIO line %d as output\n", FAN_GPIO);
        gpiod_line_release(fan_line);
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    return 0;
}

// ADC Read
int read_adc(int channel) {
    uint8_t tx_buf[3];
    uint8_t rx_buf[3];

    // Construct SPI command (MCP3008 single-ended read)
    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = (0x08 | (channel << 4)); // Single-ended, channel select
    tx_buf[2] = 0x00; // Don't care

    struct spi_ioc_transfer transfer = {
        .tx_buf = (unsigned long)tx_buf,
        .rx_buf = (unsigned long)rx_buf,
        .len = 3,
        .speed_hz = 1000000, // 1 MHz
        .delay_usecs = 0,
        .bits_per_word = 8,
    };

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &transfer) < 0) {
        perror("Error sending SPI message");
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((rx_buf[1] & 0x03) << 8) | rx_buf[2];

    // Check for sensor-absent condition
    if (adc_value == 0 || adc_value == 1023) {
        fprintf(stderr, "Sensor-absent condition detected (ADC value: %d)\n", adc_value);
        return -1; // Indicate error
    }

    return adc_value;
}

// ADC to Voltage Conversion
float adc_to_voltage(int adc_value) {
    return ((float)adc_value / 1023.0f) * VREF;
}

// Voltage to Current Conversion
float voltage_to_current(float voltage) {
    return voltage / sensitivity;
}

// Fan Control
void control_fan(float current) {
    if (current > threshold) {
        gpiod_line_set_value(fan_line, 1); // Turn fan ON
    } else {
        gpiod_line_set_value(fan_line, 0); // Turn fan OFF
    }
}

// Data Logging
void log_data(float current) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    fprintf(log_file, "%s, %.3f\n", timestamp, current);
    fflush(log_file); // Ensure data is written to file immediately
}

// Signal Handler
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Cleanup
void cleanup(void) {
    if (spi_fd != -1) {
        close(spi_fd);
    }
    if (fan_line) {
        gpiod_line_release(fan_line);
    }
    if (gpio_chip) {
        gpiod_chip_close(gpio_chip);
    }
    if (log_file) {
        fclose(log_file);
    }
    printf("Cleanup complete.\n");
}

int main(int argc, char *argv[]) {
    // Parse command-line arguments
    int opt;
    while ((opt = getopt(argc, argv, "s:t:")) != -1) {
        switch (opt) {
            case 's':
                sensitivity = atof(optarg);
                break;
            case 't':
                threshold = atof(optarg);
                break;
            default:
                fprintf(stderr, "Usage: %s [-s sensitivity] [-t threshold]\n", argv[0]);
                return 1;
        }
    }

    // Initialize logging
    log_file = fopen("current_log.txt", "a");
    if (!log_file) {
        perror("Error opening log file");
        return 1;
    }

    // Initialize SPI
    if (spi_init() < 0) {
        fprintf(stderr, "SPI initialization failed\n");
        cleanup();
        return 1;
    }

    // Initialize GPIO
    if (gpio_init() < 0) {
        fprintf(stderr, "GPIO initialization failed\n");
        cleanup();
        return 1;
    }

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Current sensor monitoring started. Press Ctrl+C to exit.\n");
    printf("Sensitivity: %.3f V/A, Threshold: %.3f A\n", sensitivity, threshold);

    // Main loop
    while (!terminate) {
        int adc_value = read_adc(0); // Read from channel 0
        if (adc_value < 0) {
            fprintf(stderr, "Error reading ADC, skipping sample\n");
            usleep(SAMPLE_PERIOD_US);
            continue;
        }

        float voltage = adc_to_voltage(adc_value);
        float current = voltage_to_current(voltage);

        control_fan(current);
        log_data(current);

        usleep(SAMPLE_PERIOD_US);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

