#include <time.h>
#include <signal.h>
#include <string.h>

// Constants
#define I2C_BUS 1
#define I2C_ADDRESS 0x49
#define CO_THRESHOLD 25.0
#define LOG_INTERVAL_SEC 5

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Structure for sensor data
typedef struct {
    uint16_t co;
    uint16_t no2;
} sensor_data_t;

// Function prototypes
int initialize_i2c();
sensor_data_t read_sensor_data();
float calculate_co_ppm(uint16_t co_raw);
void log_co_level(float co_ppm);
void log_alert(float co_ppm);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Signal received, cleaning up...\n");
}

// I2C initialization function
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to read sensor data
sensor_data_t read_sensor_data() {
    char buffer[4];
    sensor_data_t data;
    int result = i2cReadDevice(i2c_handle, buffer, 4);

    if (result != 4) {
        fprintf(stderr, "Error reading sensor data: %d\n", result);
        data.co = 0; // Set default values in case of error
        data.no2 = 0;
        return data;
    }

    data.co = (buffer[0] << 8) | buffer[1];
    data.no2 = (buffer[2] << 8) | buffer[3];

    return data;
}

// Function to calculate CO level in PPM (example calibration)
float calculate_co_ppm(uint16_t co_raw) {
    // This is a placeholder.  You MUST calibrate this function
    // using the sensor's datasheet and your specific setup.
    // The following is just an example and will likely be inaccurate.
    return (float)co_raw * 0.01; // Example conversion
}

// Function to log CO level to file
void log_co_level(float co_ppm) {
    FILE *fp = fopen("co_log.txt", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening co_log.txt\n");
        return;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d, CO: %.2f PPM\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, co_ppm);
