#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Define I2C addresses for the microphones
#define MIC1_ADDR 0x48
#define MIC2_ADDR 0x49

// Define I2C bus
#define I2C_BUS 1

// Define GPIO pins for I2C (BCM numbering)
#define SDA_PIN 2
#define SCL_PIN 3

// Define sampling interval (100ms = 10Hz)
#define SAMPLE_INTERVAL_MS 100

// Define microphone sensitivity (dBV/Pa)
#define MIC_SENSITIVITY -38.0

// Define reference pressure (Pa)
#define REF_PRESSURE 20e-6

// Define error value for sound pressure level
#define ERROR_SPL -999.0

// Global variables for I2C handles and file pointer
int i2c_handle1 = -1;
int i2c_handle2 = -1;
FILE *log_file = NULL;

// Function prototypes
int read_microphone(int i2c_handle);
double convert_to_spl(int16_t raw_data);
double calculate_average_spl(double spl1, double spl2);
void log_data(double average_spl);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);

    // Close I2C handles if they are open
    if (i2c_handle1 >= 0) {
        i2cClose(i2c_handle1);
    }
    if (i2c_handle2 >= 0) {
        i2cClose(i2c_handle2);
    }

    // Close log file if it is open
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate pigpio
    gpioTerminate();

    exit(0);
}

// Function to read microphone data
int read_microphone(int i2c_handle) {
    char buf[2];
    int result = i2cReadDevice(i2c_handle, buf, 2);

    if (result != 2) {
        fprintf(stderr, "Error reading from I2C device: %d\n", result);
        return -1; // Indicate error
    }

    // Combine the two bytes into a 16-bit signed integer
    int16_t raw_data = (int16_t)((buf[0] << 8) | buf[1]);
    return raw_data;
}

// Function to convert raw data to sound pressure level (dB)
double convert_to_spl(int16_t raw_data) {
    // Convert raw data to voltage (assuming 3.3V reference)
    double voltage = (double)raw_data / 32767.0 * 3.3;

    // Convert voltage to pressure (Pa) using microphone sensitivity
    double pressure = pow(10.0, (voltage * 1000.0 - MIC_SENSITIVITY) / 20.0);

    // Convert pressure to SPL (dB) using reference pressure
    double spl = 20.0 * log10(pressure / REF_PRESSURE);

    return spl;
}

// Function to calculate the average SPL
double calculate_average_spl(double spl1, double spl2) {
    return (spl1 + spl2) / 2.0;
}

// Function to log data to file
void log_data(double average_spl) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, %.2f\n", timestamp, average_spl);
    fflush(log_file); // Ensure data is written to file immediately
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus for both microphones
    i2c_handle1 = i2cOpen(I2C_BUS, MIC1_ADDR, 0);
    if (i2c_handle1 < 0) {
        fprintf(stderr, "Error opening I2C device 1: %d\n", i2c_handle1);
        gpioTerminate();
        return 1;
    }

    i2c_handle2 = i2cOpen(I2C_BUS, MIC2_ADDR, 0);
    if (i2c_handle2 < 0) {
        fprintf(stderr, "Error opening I2C device 2: %d\n", i2c_handle2);
        i2cClose(i2c_handle1);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("audio_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        i2cClose(i2c_handle1);
        i2cClose(i2c_handle2);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (1) {
        // Read microphone data
        int16_t raw_data1 = read_microphone(i2c_handle1);
        int16_t raw_data2 = read_microphone(i2c_handle2);

        // Convert raw data to SPL
        double spl1 = ERROR_SPL;
        double spl2 = ERROR_SPL;

        if (raw_data1 != -1) {
            spl1 = convert_to_spl(raw_data1);
        }
        if (raw_data2 != -1) {
            spl2 = convert_to_spl(raw_data2);
        }

        // Calculate average SPL
        double average_spl = calculate_average_spl(spl1, spl2);

        // Log data
        log_data(average_spl);

        // Sleep for the specified interval
        gpioDelay(SAMPLE_INTERVAL_MS * 1000); // pigpioDelay takes microseconds
    }

    return 0;
}

