    spi_handle = spiOpen(0, SPI_SPEED, 0); // SPI channel 0, 1 MHz, mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI initialisation failed: %d\n", spi_handle);
        return 1;
    }
    return 0;
}

// Read ADC value from MCP3008
int read_adc(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel: %d\n", channel);
        return -1;
    }

    unsigned char spi_tx_buf[3];
    unsigned char spi_rx_buf[3];

    // Construct SPI message (MCP3008 datasheet)
    spi_tx_buf[0] = 0x01; // Start bit
    spi_tx_buf[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    spi_tx_buf[2] = 0x00; // Don't care

    if (spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3) != 0) {
        fprintf(stderr, "SPI transfer failed\n");
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];
    return adc_value;
}

// Calculate RMS value
double calculate_rms(int *samples, int num_samples) {
    double sum_of_squares = 0.0;
    for (int i = 0; i < num_samples; i++) {
        sum_of_squares += (double)samples[i] * samples[i];
    }
    double mean_square = sum_of_squares / num_samples;
    return sqrt(mean_square);
}

// Control LED
void control_led(int state) {
    gpioWrite(LED_PIN, state);
}

// Log data to CSV file
void log_data(double mic1_rms, double mic2_rms) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.6f,%.6f\n", timestamp, mic1_rms, mic2_rms);
    fflush(log_file); // Ensure data is written to file immediately
}

// Cleanup resources before exiting
void cleanup() {
    printf("Cleaning up...\n");
    gpioWrite(LED_PIN, 0); // Turn off LED
    spiClose(spi_handle);
    gpioTerminate();
    if (log_file != NULL) {
        fclose(log_file);
    }
}

int main() {
    // Install signal handler
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Initialize SPI
    if (initialize_spi() != 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen("audio_events.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        cleanup();
        return 1;
    }

    // Write header if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Mic1_RMS,Mic2_RMS\n");
    }

    MicrophoneData mic_data;

    printf("Sampling audio... Press Ctrl+C to exit.\n");

    while (!terminate) {
        // Sample audio
        for (int i = 0; i < NUM_SAMPLES; i++) {
            int mic1_value = read_adc(SPI_CHANNEL);
            int mic2_value = read_adc(SPI_CHANNEL);

            if (mic1_value == -1 || mic2_value == -1) {
                fprintf(stderr, "Error reading ADC values, exiting...\n");
                terminate = 1;
                break;
            }

            mic_data.mic1_samples[i] = mic1_value;
            mic_data.mic2_samples[i] = mic2_value;

            gpioDelay(SAMPLE_INTERVAL_US); // Delay for 1 ms
        }

        if (terminate) break;

        // Calculate RMS values
        double mic1_rms = calculate_rms(mic_data.mic1_samples, NUM_SAMPLES);
        double mic2_rms = calculate_rms(mic_data.mic2_samples, NUM_SAMPLES);

        // Normalize RMS values (assuming ADC range is 0-1023)
        mic1_rms /= 1023.0;
        mic2_rms /= 1023.0;

        // Log data
        log_data(mic1_rms, mic2_rms);

        // Check threshold and control LED
        if (mic1_rms > RMS_THRESHOLD || mic2_rms > RMS_THRESHOLD) {
            control_led(1); // Turn on LED
            gpioDelay(LED_ON_TIME_MS * 1000); // Wait for 500 ms
            control_led(0); // Turn off LED
        }
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

