#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <math.h>

// Constants
#define I2C_BUS 1
#define ADS1115_ADDR 0x48
#define ADS1115_REG_CONFIG 0x01
#define ADS1115_REG_CONVERT 0x00
#define CONFIG_REG_DEFAULT 0x4003 // Single-ended A0, +/-4.096V, 128 SPS, Continuous
#define LED_GPIO 17
#define SAMPLE_RATE 10 // Hz
#define BUFFER_SIZE 100
#define CURRENT_THRESHOLD 50.0 // Amperes

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Circular buffer
float current_buffer[BUFFER_SIZE];
int buffer_index = 0;

// Function prototypes
int initialize_pigpio();
int initialize_i2c();
int read_ads1115(int *raw_value);
float convert_to_current(int raw_value);
void update_circular_buffer(float current);
float calculate_average_current();
void control_led(float average_current);
void signal_handler(int signal);
void cleanup();

// Function to initialize pigpio
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Function to initialize I2C
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to read from ADS1115
int read_ads1115(int *raw_value) {
    char config_data[3];
    config_data[0] = ADS1115_REG_CONFIG;
    config_data[1] = (CONFIG_REG_DEFAULT >> 8) & 0xFF; // MSB
    config_data[2] = CONFIG_REG_DEFAULT & 0xFF;      // LSB

    if (i2cWriteDevice(i2c_handle, config_data, 3) != 0) {
        fprintf(stderr, "Failed to write to ADS1115 config register\n");
        return -1;
    }

    gpioDelay(10); // Wait for conversion

    char convert_data[1];
    convert_data[0] = ADS1115_REG_CONVERT;

    if (i2cWriteDevice(i2c_handle, convert_data, 1) != 0) {
        fprintf(stderr, "Failed to write to ADS1115 convert register\n");
        return -1;
    }

    char read_data[2];
    if (i2cReadDevice(i2c_handle, read_data, 2) != 2) {
        fprintf(stderr, "Failed to read from ADS1115\n");
        return -1;
    }

    *raw_value = (read_data[0] << 8) | read_data[1];
    *raw_value = (*raw_value ^ 0x8000) - 0x8000; // Sign extend

    return 0;
}

// Function to convert raw ADC value to current
float convert_to_current(int raw_value) {
    float voltage = (float)raw_value * 4.096 / 32768.0; // Assuming +/-4.096V range
    float current = (voltage - 0.5) / (4.5 - 0.5) * 100.0; // 0.5V to 4.5V = 0A to 100A
    return current;
}

// Function to update the circular buffer
void update_circular_buffer(float current) {
    current_buffer[buffer_index] = current;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

// Function to calculate the average current
float calculate_average_current() {
    float sum = 0.0;
    for (int i = 0; i < BUFFER_SIZE; i++) {
        sum += current_buffer[i];
    }
    return sum / BUFFER_SIZE;
}

// Function to control the LED based on the average current
void control_led(float average_current) {
    if (average_current > CURRENT_THRESHOLD) {
        gpioWrite(LED_GPIO, 1); // Turn LED on
    } else {
        gpioWrite(LED_GPIO, 0); // Turn LED off
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup function to release resources
void cleanup() {
    gpioWrite(LED_GPIO, 0); // Turn off LED
    i2cClose(i2c_handle);
    gpioTerminate();
}

int main() {
    // Register signal handler
    signal(SIGINT, signal_handler);

    // Initialize pigpio
    if (initialize_pigpio() != 0) {
        return 1;
    }

    // Initialize I2C
    if (initialize_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Set LED GPIO as output
    gpioSetMode(LED_GPIO, PI_OUTPUT);

    int raw_value;
    float current;
    float average_current;

    // Main loop
    while (!terminate) {
        // Read ADC value
        if (read_ads1115(&raw_value) == 0) {
            // Convert to current
            current = convert_to_current(raw_value);

            // Update circular buffer
            update_circular_buffer(current);

            // Calculate average current
            average_current = calculate_average_current();

            // Control LED
            control_led(average_current);

            printf("Current: %.2f A, Average Current: %.2f A\n", current, average_current);
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }

        gpioDelay(1000 / SAMPLE_RATE); // Sample at 10Hz
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

