#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// TCS34725 I2C address
#define TCS34725_ADDRESS 0x29

// TCS34725 Registers
#define TCS34725_ENABLE 0x00
#define TCS34725_ATIME 0x01
#define TCS34725_CONTROL 0x0F
#define TCS34725_ID 0x12

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_pigpio();
int initialize_i2c();
int verify_sensor();
int configure_sensor();
int read_sensor_data(uint16_t *clear, uint16_t *red, uint16_t *green, uint16_t *blue);
int log_data(uint16_t clear, uint16_t red, uint16_t green, uint16_t blue);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating gracefully...\n", signal);
}

// Initialize pigpio library
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Initialize I2C communication
int initialize_i2c() {
    i2c_handle = i2cOpen(1, TCS34725_ADDRESS, 0); // Bus 1, address 0x29, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Verify the TCS34725 sensor is present
int verify_sensor() {
    int id;
    id = i2cReadByteData(i2c_handle, TCS34725_ID);
    if (id < 0) {
        fprintf(stderr, "Failed to read sensor ID: %d\n", id);
        return -1;
    }

    if ((id & 0x0F) != 0x44) {
        fprintf(stderr, "Incorrect sensor ID: 0x%02X\n", id);
        return -1;
    }

    return 0;
}

// Configure the TCS34725 sensor
int configure_sensor() {
    // Set integration time (ATIME) to 2.4ms (0xFF)
    if (i2cWriteByteData(i2c_handle, TCS34725_ATIME, 0xFF) < 0) {
        fprintf(stderr, "Failed to write ATIME register\n");
        return -1;
    }

    // Set gain (CONTROL) to 4x (0x01)
    if (i2cWriteByteData(i2c_handle, TCS34725_CONTROL, 0x01) < 0) {
        fprintf(stderr, "Failed to write CONTROL register\n");
        return -1;
    }

    // Power on and enable the ADC (ENABLE)
    if (i2cWriteByteData(i2c_handle, TCS34725_ENABLE, 0x01 | 0x02) < 0) {
        fprintf(stderr, "Failed to write ENABLE register\n");
        return -1;
    }

    gpioDelay(3000); // Wait 3ms after power-on

    return 0;
}

// Read color data from the TCS34725 sensor
int read_sensor_data(uint16_t *clear, uint16_t *red, uint16_t *green, uint16_t *blue) {
    char buffer[8];
    int result = i2cReadI2CBlockData(i2c_handle, 0x14, buffer, 8);

    if (result < 0) {
        fprintf(stderr, "Failed to read sensor data: %d\n", result);
        return -1;
    }

    *clear = (buffer[1] << 8) | buffer[0];
    *red   = (buffer[3] << 8) | buffer[2];
    *green = (buffer[5] << 8) | buffer[4];
    *blue  = (buffer[7] << 8) | buffer[6];

    return 0;
}

// Log data to a CSV file
int log_data(uint16_t clear, uint16_t red, uint16_t green, uint16_t blue) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%u,%u,%u,%u\n", timestamp, clear, red, green, blue);
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

int main() {
    // Install signal handler for clean shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (initialize_pigpio() != 0) {
        return 1;
    }

    // Initialize I2C
    if (initialize_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Verify sensor
    if (verify_sensor() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Configure sensor
    if (configure_sensor() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("color_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Check if the file is newly created and write the header
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Clear,Red,Green,Blue\n");
    }
    rewind(log_file);

    uint16_t clear, red, green, blue;
    int read_attempts = 0;

    // Main loop
    while (!terminate) {
        if (read_sensor_data(&clear, &red, &green, &blue) == 0) {
            log_data(clear, red, green, blue);
            read_attempts = 0; // Reset read attempts on success
        } else {
            fprintf(stderr, "Sensor read failed. Attempt: %d\n", read_attempts + 1);
            read_attempts++;
            if (read_attempts >= 3) {
                fprintf(stderr, "Too many consecutive sensor read failures. Exiting.\n");
                break;
            }
        }

        gpioDelay(1000); // Wait 1 second
    }

    // Clean up
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

