float map_moisture(int raw_value, int dry_value, int wet_value) {
    float moisture = 100.0 - ((float)(raw_value - wet_value) / (float)(dry_value - wet_value) * 100.0);
    if (moisture < 0.0) moisture = 0.0;
    if (moisture > 100.0) moisture = 100.0;
