    sensor_config_t sensor1_config = {0, DRY_VALUE_1, WET_VALUE_1};
    sensor_config_t sensor2_config = {1, DRY_VALUE_2, WET_VALUE_2};

    // Main loop
    while (!terminate) {
        // Read sensor values
        int raw_value1 = read_mcp3008(sensor1_config.channel);
        int raw_value2 = read_mcp3008(sensor2_config.channel);

        if (raw_value1 == -1 || raw_value2 == -1) {
            fprintf(stderr, "Error reading sensor data. Retrying in 5 seconds.\n");
            gpioDelay(5000); // Wait 5 seconds before retrying
            continue;
        }

        // Map to moisture percentage
        float moisture1 = map_moisture(raw_value1, sensor1_config.dry_value, sensor1_config.wet_value);
        float moisture2 = map_moisture(raw_value2, sensor2_config.dry_value, sensor2_config.wet_value);

        // Log data
        if (log_data(moisture1, moisture2) != 0) {
            fprintf(stderr, "Error logging data.\n");
        }

        // Wait 5 seconds
        gpioDelay(5000);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

