#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <fcntl.h>
#include <errno.h>

// Configuration
#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE SPI_MODE_0
#define SPI_BITS_PER_WORD 8
#define SPI_SPEED 1000000 // 1 MHz
#define MCP3008_CHANNEL 0
#define MOTOR_SHUTDOWN_PIN 17
#define OVERCURRENT_THRESHOLD 10.0
#define SAMPLE_INTERVAL 1 // seconds
#define VREF 3.3 // Reference voltage for MCP3008
#define SENSITIVITY 0.1 // V/A
#define OFFSET 0.05 // V

// Global variables
int spi_fd = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int spi_init(const char *device, int mode, int bits_per_word, int speed);
int spi_read_adc(int spi_fd, int channel);
float adc_to_voltage(int adc_value, float vref);
float voltage_to_current(float voltage, float sensitivity, float offset);
void log_current(FILE *fp, float current);
void overcurrent_shutdown(int shutdown_pin, float current);
void signal_handler(int signal);

// SPI Initialization function
int spi_init(const char *device, int mode, int bits_per_word, int speed) {
    int fd = open(device, O_RDWR);
    if (fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }

    // Set SPI mode
    int mode_set = SPI_IOC_WR_MODE;
    if (ioctl(fd, mode_set, &mode) < 0) {
        perror("Error setting SPI mode");
        close(fd);
        return -1;
    }

    // Set bits per word
    int bits_set = SPI_IOC_WR_BITS_PER_WORD;
    if (ioctl(fd, bits_set, &bits_per_word) < 0) {
        perror("Error setting bits per word");
        close(fd);
        return -1;
    }

    // Set SPI speed
    int speed_set = SPI_IOC_WR_MAX_SPEED_HZ;
    if (ioctl(fd, speed_set, &speed) < 0) {
        perror("Error setting SPI speed");
        close(fd);
        return -1;
    }

    return fd;
}

// SPI Read ADC function
int spi_read_adc(int spi_fd, int channel) {
    unsigned char tx_buf[3];
    unsigned char rx_buf[3];
    struct spi_ioc_transfer transfer[1];

    // MCP3008 command: start bit (1), single-ended mode (1), channel (3 bits), don't care (3 bits)
    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = (0x08 | (channel & 0x07)) << 4; // Single-ended, channel select
    tx_buf[2] = 0x00; // Don't care

    memset(transfer, 0, sizeof(transfer));

    transfer[0].tx_buf = (unsigned long)tx_buf;
    transfer[0].rx_buf = (unsigned long)rx_buf;
    transfer[0].len = 3;
    transfer[0].speed_hz = SPI_SPEED;
    transfer[0].bits_per_word = SPI_BITS_PER_WORD;

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), transfer) < 0) {
        perror("Error sending SPI message");
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((rx_buf[1] & 0x03) << 8) + rx_buf[2];
    return adc_value;
}

// ADC to Voltage conversion function
float adc_to_voltage(int adc_value, float vref) {
    return ((float)adc_value / 1023.0) * vref;
}

// Voltage to Current conversion function
float voltage_to_current(float voltage, float sensitivity, float offset) {
    return (voltage - offset) / sensitivity;
}

// Logging function
void log_current(FILE *fp, float current) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d,%.3f\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, current);
    fflush(fp); // Ensure data is written to file immediately
}

// Overcurrent shutdown function
void overcurrent_shutdown(int shutdown_pin, float current) {
    if (current > OVERCURRENT_THRESHOLD) {
        gpioWrite(shutdown_pin, 0); // Disable motor
        fprintf(stderr, "Overcurrent detected! Shutting down motor.\n");
        log_current(log_file, current);
        gpioDelay(1000); // Wait 1 second
        gpioWrite(shutdown_pin, 1); // Re-enable motor
        fprintf(stderr, "Motor re-enabled.\n");
    }
}

// Signal handler function
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating program...\n");
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize SPI
    spi_fd = spi_init(SPI_DEVICE, SPI_MODE, SPI_BITS_PER_WORD, SPI_SPEED);
    if (spi_fd < 0) {
        gpioTerminate();
        return 1;
    }

    // Set motor shutdown pin as output
    gpioSetMode(MOTOR_SHUTDOWN_PIN, PI_OUTPUT);
    gpioWrite(MOTOR_SHUTDOWN_PIN, 1); // Initially enable the motor

    // Open log file
    log_file = fopen("current_log.csv", "a+");
    if (log_file == NULL) {
        perror("Error opening log file");
        close(spi_fd);
        gpioTerminate();
        return 1;
    }

    // Check if the file is empty, if so, write the header
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Current (A)\n");
    }
    fseek(log_file, 0, SEEK_END); // Reset file pointer to the end

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        // Read ADC value
        int adc_value = spi_read_adc(spi_fd, MCP3008_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Error reading ADC value, retrying...\n");
            gpioDelay(100); // Small delay before retry
            continue; // Skip to the next iteration
        }

        // Convert ADC value to voltage
        float voltage = adc_to_voltage(adc_value, VREF);

        // Convert voltage to current
        float current = voltage_to_current(voltage, SENSITIVITY, OFFSET);

        // Log current reading
        log_current(log_file, current);

        // Check for overcurrent condition
        overcurrent_shutdown(MOTOR_SHUTDOWN_PIN, current);

        // Wait for the next sample
        gpioDelay(SAMPLE_INTERVAL * 1000); // Convert seconds to milliseconds
    }

    // Cleanup
    close(spi_fd);
    fclose(log_file);
    gpioWrite(MOTOR_SHUTDOWN_PIN, 1); // Ensure motor is enabled on exit
    gpioTerminate();

    return 0;
}

