    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d,%.3f\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, current);
    fflush(fp); // Ensure data is written to file immediately
}

// Overcurrent shutdown function
void overcurrent_shutdown(int shutdown_pin, float current) {
    if (current > OVERCURRENT_THRESHOLD) {
        gpioWrite(shutdown_pin, 0); // Disable motor
        fprintf(stderr, "Overcurrent detected! Shutting down motor.\n");
        log_current(log_file, current);
        gpioDelay(1000); // Wait 1 second
        gpioWrite(shutdown_pin, 1); // Re-enable motor
        fprintf(stderr, "Motor re-enabled.\n");
    }
}

// Signal handler function
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating program...\n");
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize SPI
    spi_fd = spi_init(SPI_DEVICE, SPI_MODE, SPI_BITS_PER_WORD, SPI_SPEED);
    if (spi_fd < 0) {
        gpioTerminate();
        return 1;
    }

    // Set motor shutdown pin as output
    gpioSetMode(MOTOR_SHUTDOWN_PIN, PI_OUTPUT);
    gpioWrite(MOTOR_SHUTDOWN_PIN, 1); // Initially enable the motor

    // Open log file
    log_file = fopen("current_log.csv", "a+");
    if (log_file == NULL) {
        perror("Error opening log file");
        close(spi_fd);
        gpioTerminate();
        return 1;
    }

    // Check if the file is empty, if so, write the header
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Current (A)\n");
    }
    fseek(log_file, 0, SEEK_END); // Reset file pointer to the end

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        // Read ADC value
        int adc_value = spi_read_adc(spi_fd, MCP3008_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Error reading ADC value, retrying...\n");
            gpioDelay(100); // Small delay before retry
            continue; // Skip to the next iteration
        }

        // Convert ADC value to voltage
        float voltage = adc_to_voltage(adc_value, VREF);

        // Convert voltage to current
        float current = voltage_to_current(voltage, SENSITIVITY, OFFSET);

        // Log current reading
        log_current(log_file, current);

        // Check for overcurrent condition
        overcurrent_shutdown(MOTOR_SHUTDOWN_PIN, current);

        // Wait for the next sample
        gpioDelay(SAMPLE_INTERVAL * 1000); // Convert seconds to milliseconds
    }

    // Cleanup
    close(spi_fd);
    fclose(log_file);
    gpioWrite(MOTOR_SHUTDOWN_PIN, 1); // Ensure motor is enabled on exit
    gpioTerminate();

    return 0;
}

