#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define MLX90817_ADDR 0x40
#define PRESSURE_REG 0x00
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 100
#define LOG_FILE "pressure_log.csv"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure for sensor data
typedef struct {
    double pressure_kPa;
    char timestamp[32];
} sensor_data_t;

// Function prototypes
int init_i2c();
int read_pressure(int *raw_value);
double convert_to_kPa(int raw_value);
char* get_iso8601_timestamp(char *timestamp_str, size_t size);
int log_data(double pressure_kPa);
void signal_handler(int signal);
void cleanup();

// Signal handler
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, MLX90817_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read pressure data from the sensor
int read_pressure(int *raw_value) {
    char buf[2];
    int result;
    int retries = 0;

    while (retries < MAX_RETRIES) {
        result = i2cReadI2CBlockData(i2c_handle, PRESSURE_REG, buf, 2);
        if (result == 2) {
            *raw_value = (buf[0] << 8) | buf[1];
            return 0; // Success
        } else {
            fprintf(stderr, "I2C read error (register 0x%02X): %d, retry %d\n", PRESSURE_REG, result, retries + 1);
            retries++;
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
        }
    }

    fprintf(stderr, "Failed to read pressure after %d retries.\n", MAX_RETRIES);
    return -1; // Failure
}

// Convert raw value to kPa
double convert_to_kPa(int raw_value) {
    return ((double)raw_value / 65535.0) * 500.0;
}

// Get ISO 8601 UTC timestamp
char* get_iso8601_timestamp(char *timestamp_str, size_t size) {
    time_t rawtime;
    struct tm *info;
    time(&rawtime);
    info = gmtime(&rawtime);
    strftime(timestamp_str, size, "%Y-%m-%dT%H:%M:%SZ", info);
    return timestamp_str;
}

// Log data to file
int log_data(double pressure_kPa) {
    char timestamp[32];
    get_iso8601_timestamp(timestamp, sizeof(timestamp));

    if (log_file == NULL) {
        fprintf(stderr, "Error: Log file is not open.\n");
        return -1;
    }

    if (fprintf(log_file, "%s,%.2f\n", timestamp, pressure_kPa) < 0) {
        fprintf(stderr, "Error writing to log file.\n");
        return -1;
    }

    fflush(log_file);
    return 0;
}

// Cleanup resources
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fflush(log_file);
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a+");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        cleanup();
        return 1;
    }

    // Write header if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "timestamp,pressure_kPa\n");
        fflush(log_file);
    }

    int raw_value;
    double pressure_kPa;

    // Main loop
    while (!terminate) {
        if (read_pressure(&raw_value) == 0) {
            pressure_kPa = convert_to_kPa(raw_value);
            if (log_data(pressure_kPa) != 0) {
                fprintf(stderr, "Error logging data.\n");
            }
        } else {
            fprintf(stderr, "Failed to read pressure.\n");
        }

        sleep(1);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

