#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define ADS1115_ADDR 0x48
#define CONFIG_REG 0x01
#define CONVERSION_REG 0x00
#define LED_GPIO 17
#define PRESSURE_THRESHOLD 105.0

// ADS1115 Configuration Register Values
#define CONFIG_OS_SINGLE 0x8000  // Start single conversion
#define CONFIG_MUX_AIN0_SINGLE 0x4000 // AIN0 single-ended
#define CONFIG_PGA_2_3 0x0040    // +/- 6.144V range (2/3 gain)
#define CONFIG_MODE_SINGLE 0x0100 // Single-shot mode
#define CONFIG_DR_128SPS 0x0080  // 128 SPS
#define CONFIG_COMP_MODE_TRAD 0x0000 // Traditional comparator
#define CONFIG_COMP_POL_LOW 0x0000 // Active low comparator
#define CONFIG_COMP_LAT_NON 0x0000 // Non-latching comparator
#define CONFIG_COMP_QUE_DISABLE 0x0003 // Disable comparator

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_pigpio();
int init_i2c();
int read_ads1115(int *pressure_adc, int *temperature_adc);
float convert_adc_to_pressure(int adc_value);
float convert_adc_to_temperature(int adc_value);
void control_led(float pressure);
void signal_handler(int signal);

// Structure to hold configuration data
typedef struct {
    int i2c_address;
    int led_gpio;
    float pressure_threshold;
} Config;

Config config = {ADS1115_ADDR, LED_GPIO, PRESSURE_THRESHOLD};

int main() {
    int pressure_adc, temperature_adc;
    float pressure, temperature;

    // Initialize pigpio
    if (init_pigpio() != 0) {
        fprintf(stderr, "Failed to initialize pigpio. Exiting.\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        fprintf(stderr, "Failed to initialize I2C. Exiting.\n");
        gpioTerminate();
        return 1;
    }

    // Set signal handler for graceful shutdown
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        // Read ADC values
        if (read_ads1115(&pressure_adc, &temperature_adc) != 0) {
            fprintf(stderr, "Failed to read ADC values. Retrying.\n");
            gpioDelay(100); // Wait before retrying
            continue;
        }

        // Convert ADC values to pressure and temperature
        pressure = convert_adc_to_pressure(pressure_adc);
        temperature = convert_adc_to_temperature(temperature_adc);

        // Display pressure and temperature
        printf("Pressure: %.2f kPa, Temperature: %.2f °C\n", pressure, temperature);

        // Control LED based on pressure
        control_led(pressure);

        // Wait for 1 second
        gpioDelay(1000);
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

// Initialize pigpio library
int init_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }
    return 0;
}

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(1, config.i2c_address, 0); // Bus 1, address 0x48, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        return 1;
    }

    // Configure ADS1115 for single-ended AIN0 and AIN1, 128 SPS, +/- 6.144V range
    int config_value = CONFIG_OS_SINGLE | CONFIG_MUX_AIN0_SINGLE | CONFIG_PGA_2_3 | CONFIG_MODE_SINGLE | CONFIG_DR_128SPS | CONFIG_COMP_MODE_TRAD | CONFIG_COMP_POL_LOW | CONFIG_COMP_LAT_NON | CONFIG_COMP_QUE_DISABLE;
    char buf[3];
    buf[0] = CONFIG_REG;
    buf[1] = (config_value >> 8) & 0xFF; // MSB
    buf[2] = config_value & 0xFF;        // LSB

    int result = i2cWriteDevice(i2c_handle, buf, 3);
    if (result != 0) {
        fprintf(stderr, "Failed to write to I2C device: %d\n", result);
        i2cClose(i2c_handle);
        return 1;
    }

    return 0;
}

// Read pressure and temperature data from ADS1115
int read_ads1115(int *pressure_adc, int *temperature_adc) {
    char buf[1];
    char read_buf[2];
    int retries = 3;
    int result;

    buf[0] = CONVERSION_REG;

    while (retries > 0) {
        result = i2cWriteDevice(i2c_handle, buf, 1);
        if (result == 0) {
            break;
        } else {
            fprintf(stderr, "I2C write error (conversion register): %d, retries remaining: %d\n", result, retries);
            gpioDelay(10); // Small delay before retrying
            retries--;
        }
    }

    if (retries == 0) {
        fprintf(stderr, "Failed to write to conversion register after multiple retries.\n");
        return 1;
    }

    gpioDelay(10); // Wait for conversion to complete (adjust as needed)

    retries = 3;
    while (retries > 0) {
        result = i2cReadDevice(i2c_handle, read_buf, 2);
        if (result == 2) {
            break;
        } else {
            fprintf(stderr, "I2C read error: %d, retries remaining: %d\n", result, retries);
            gpioDelay(10); // Small delay before retrying
            retries--;
        }
    }

    if (retries == 0) {
        fprintf(stderr, "Failed to read from conversion register after multiple retries.\n");
        return 1;
    }

    // Combine the two bytes to form the 16-bit ADC value
    *pressure_adc = (read_buf[0] << 8) | read_buf[1];

    retries = 3;
    while (retries > 0) {
        result = i2cWriteDevice(i2c_handle, buf, 1);
        if (result == 0) {
            break;
        } else {
            fprintf(stderr, "I2C write error (conversion register): %d, retries remaining: %d\n", result, retries);
            gpioDelay(10); // Small delay before retrying
            retries--;
        }
    }

    if (retries == 0) {
        fprintf(stderr, "Failed to write to conversion register after multiple retries.\n");
        return 1;
    }

    gpioDelay(10); // Wait for conversion to complete (adjust as needed)

    retries = 3;
    while (retries > 0) {
        result = i2cReadDevice(i2c_handle, read_buf, 2);
        if (result == 2) {
            break;
        } else {
            fprintf(stderr, "I2C read error: %d, retries remaining: %d\n", result, retries);
            gpioDelay(10); // Small delay before retrying
            retries--;
        }
    }

    if (retries == 0) {
        fprintf(stderr, "Failed to read from conversion register after multiple retries.\n");
        return 1;
    }

    *temperature_adc = (read_buf[0] << 8) | read_buf[1];

    return 0;
}

// Convert ADC value to pressure (kPa)
float convert_adc_to_pressure(int adc_value) {
    float voltage = (float)adc_value / 32767.0 * 6.144; // Assuming 16-bit ADC and +/- 6.144V range
    float pressure = (voltage / 5.0) * 400.0;
    return pressure;
}

// Convert ADC value to temperature (°C)
float convert_adc_to_temperature(int adc_value) {
    float voltage = (float)adc_value / 32767.0 * 6.144; // Assuming 16-bit ADC and +/- 6.144V range
    float temperature = (voltage - 1.0) * 100.0;
    return temperature;
}

// Control LED based on pressure
void control_led(float pressure) {
    if (pressure > config.pressure_threshold) {
        gpioWrite(config.led_gpio, 1); // Turn LED on
    } else {
        gpioWrite(config.led_gpio, 0); // Turn LED off
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

