#include <signal.h>
#include <pigpio.h>

// Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define MCP3008_CHANNEL 0
#define VREF 3.3 // Reference voltage
#define MAX_PPM 5000.0 // Maximum PPM value
#define LOG_FILE "methane_log.txt"

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
float adc_to_ppm(int adc_value);
void log_data(int adc_value, float ppm);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating gracefully...\n", signal);
}

// Function to read data from MCP3008 ADC
int read_mcp3008(int channel) {
    unsigned char tx_buffer[3];
    unsigned char rx_buffer[3];

    // Construct SPI command (single-ended, channel 0)
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | (channel << 4)); // Single-ended, channel select
    tx_buffer[2] = 0x00; // Dummy byte

    if (spiXfer(spi_handle, tx_buffer, rx_buffer, 3) != 0) {
        fprintf(stderr, "Error: SPI transfer failed\n");
        return -1; // Indicate error
    }

    // Extract 10-bit ADC value
    int adc_value = ((rx_buffer[1] & 0x03) << 8) | rx_buffer[2];
    return adc_value;
}

