#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define ADS1115_ADDR 0x48
#define ADS1115_REG_CONFIG 0x01
#define ADS1115_REG_CONVERT 0x00
#define ADS1115_CONFIG_REG_DEFAULT 0x4003 // Single-shot mode, AIN0, 4.096V, 128 SPS
#define VREF 4.096 // ADC reference voltage
#define OFFSET_VOLTAGE 0.5 // Offset voltage in volts
#define SENSITIVITY 0.1 // Sensitivity in V/kPa
#define LOG_FILE "pressure_log.txt"

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_i2c();
int read_adc(int handle);
float convert_to_voltage(int raw_value);
float convert_to_pressure(float voltage);
int log_pressure(float pressure);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initializes the I2C connection to the ADS1115
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        return -1;
    }

    // Configure ADS1115 for single-shot mode, AIN0, 4.096V, 128 SPS
    int config_value = ADS1115_CONFIG_REG_DEFAULT;
    char buf[3];
    buf[0] = ADS1115_REG_CONFIG;
    buf[1] = (config_value >> 8) & 0xFF; // MSB
    buf[2] = config_value & 0xFF;        // LSB

    int result = i2cWriteDevice(i2c_handle, buf, 3);
    if (result != 0) {
        fprintf(stderr, "Error writing to I2C device: %d\n", result);
        i2cClose(i2c_handle);
        return -1;
    }

    return 0;
}

// Reads the ADC value from the ADS1115
int read_adc(int handle) {
    char buf[1];
    buf[0] = ADS1115_REG_CONVERT;

    int result = i2cWriteDevice(handle, buf, 1);
    if (result != 0) {
        fprintf(stderr, "Error writing to I2C device for conversion start: %d\n", result);
        return -1;
    }

    // Wait for conversion to complete (at least 8ms for 128 SPS)
    gpioDelay(10000); // 10ms

    char read_buf[2];
    result = i2cReadDevice(handle, read_buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading from I2C device: %d\n", result);
        return -1;
    }

    int16_t raw_value = (read_buf[0] << 8) | read_buf[1];
    return raw_value;
}

// Converts the raw ADC value to a voltage
float convert_to_voltage(int raw_value) {
    float voltage = (float)raw_value * VREF / 32768.0;
    return voltage;
}

// Converts the voltage to pressure in kPa
float convert_to_pressure(float voltage) {
    float pressure = (voltage - OFFSET_VOLTAGE) / SENSITIVITY;
    return pressure;
}

// Logs the pressure reading to a file with an ISO-8601 timestamp
int log_pressure(float pressure) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        return -1;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", tm);

    fprintf(fp, "%s, %.2f kPa\n", timestamp, pressure);
    fclose(fp);
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handling for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize I2C
    if (initialize_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    printf("Pressure sensor data logging started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        int raw_value = read_adc(i2c_handle);
        if (raw_value < 0) {
            fprintf(stderr, "Error reading ADC value, retrying...\n");
            gpioDelay(100000); // Wait 0.1 seconds before retrying
            continue;
        }

        float voltage = convert_to_voltage(raw_value);
        float pressure = convert_to_pressure(voltage);

        // Validate pressure range
        if (pressure >= 0 && pressure <= 100) {
            if (log_pressure(pressure) != 0) {
                fprintf(stderr, "Error logging pressure data\n");
            }
        } else {
            fprintf(stderr, "Pressure value out of range: %.2f kPa\n", pressure);
        }

        gpioDelay(1000000); // Wait 1 second
    }

    // Clean up
    i2cClose(i2c_handle);
    gpioTerminate();

    printf("Program terminated.\n");
    return 0;
}

