#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define MCP3208_CHANNEL_HUMIDITY 0
#define MCP3208_CHANNEL_TEMPERATURE 1
#define HUMIDITY_THRESHOLD 80.0
#define VREF 5.0
#define R0 10000.0 // 10kΩ
#define BETA 3950.0
#define TEMPERATURE_OFFSET 25.0

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3208(int channel);
float calculate_humidity(int adc_value);
float calculate_temperature(int adc_value);
void log_data(float humidity, float temperature);
void send_email_alert(float humidity, float temperature);
void signal_handler(int signal);

// Function to read data from MCP3208 ADC
int read_mcp3208(int channel) {
    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel selection
    tx_buffer[2] = 0x00; // Don't care

    // Transfer SPI data
    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    if (result != 0) {
        fprintf(stderr, "Error: SPI transfer failed (channel %d): %d\n", channel, result);
        return -1; // Indicate error
    }

    // Extract ADC value (10 bits)
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
    return adc_value;
}

// Function to calculate relative humidity
float calculate_humidity(int adc_value) {
    float voltage = (float)adc_value / 1023.0 * VREF;
    float humidity = (voltage - 0.824) / 0.0315;
    return humidity;
}

// Function to calculate temperature
float calculate_temperature(int adc_value) {
    float voltage = (float)adc_value / 1023.0 * VREF;
    float r_thermistor = (VREF * 10000.0) / voltage - 10000.0; // 10kΩ resistor in series
    float temperature = (1.0 / (1.0 / (TEMPERATURE_OFFSET + 273.15) + (1.0 / BETA) * log(r_thermistor / R0))) - 273.15;
    return temperature;
}

// Function to log data to file
void log_data(float humidity, float temperature) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, humidity, temperature);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Function to send email alert
void send_email_alert(float humidity, float temperature) {
    char command[256];
    snprintf(command, sizeof(command), "echo \"Subject: Humidity Alert\n\nHumidity: %.2f%%, Temperature: %.2f°C\" | ssmtp recipient@example.com", humidity, temperature);
    int result = system(command);
    if (result != 0) {
        fprintf(stderr, "Error: Email sending failed (return code: %d)\n", result);
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // CE0, 1MHz, Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("humidity_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        // Read ADC values
        int humidity_adc = read_mcp3208(MCP3208_CHANNEL_HUMIDITY);
        int temperature_adc = read_mcp3208(MCP3208_CHANNEL_TEMPERATURE);

        if (humidity_adc == -1 || temperature_adc == -1) {
            fprintf(stderr, "Error: Failed to read ADC values, retrying...\n");
            gpioDelay(1000); // Wait 1 second before retrying
            continue;
        }

        // Calculate humidity and temperature
        float humidity = calculate_humidity(humidity_adc);
        float temperature = calculate_temperature(temperature_adc);

        // Log data
        log_data(humidity, temperature);

        // Check humidity threshold and send email alert
        if (humidity > HUMIDITY_THRESHOLD) {
            send_email_alert(humidity, temperature);
        }

        // Wait 5 seconds
        gpioDelay(5000);
    }

    // Cleanup
    spiClose(spi_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

