#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 0
#define CS_PIN 8
#define SAMPLE_RATE 100 // Hz
#define IMPACT_THRESHOLD 2.0 // g
#define ADC_VREF 3.3 // ADC reference voltage
#define ADC_RESOLUTION 1024.0 // 2^10
#define ADXL335_0G_VOLTAGE 1.65 // 3.3V / 2
#define ADXL335_SENSITIVITY 0.3 // 300 mV/g

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_pigpio();
int initialize_spi();
int read_adc_channel(int channel);
void log_data(int x, int y, int z);
double calculate_acceleration_magnitude(int x, int y, int z);
void detect_impact(double magnitude);
void signal_handler(int signal);
void cleanup();

// Structure to hold accelerometer data
typedef struct {
    int x;
    int y;
    int z;
} accelerometer_data_t;

// Function to initialize pigpio
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Function to initialize SPI
int initialize_spi() {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        return -1;
    }
    return 0;
}

// Function to read ADC channel
int read_adc_channel(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel: %d\n", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message (MCP3008 datasheet)
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Don't care

    gpioWrite(CS_PIN, 0); // Select the MCP3008
    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    gpioWrite(CS_PIN, 1); // Deselect the MCP3008

    if (result != 3) {
        fprintf(stderr, "SPI transfer failed: %d\n", result);
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];

    return adc_value;
}

// Function to log data to file
void log_data(int x, int y, int z) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%d,%d,%d\n", timestamp, x, y, z);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Function to calculate acceleration magnitude
double calculate_acceleration_magnitude(int x, int y, int z) {
    double x_g = ((double)x / ADC_RESOLUTION * ADC_VREF - ADXL335_0G_VOLTAGE) / ADXL335_SENSITIVITY;
    double y_g = ((double)y / ADC_RESOLUTION * ADC_VREF - ADXL335_0G_VOLTAGE) / ADXL335_SENSITIVITY;
    double z_g = ((double)z / ADC_RESOLUTION * ADC_VREF - ADXL335_0G_VOLTAGE) / ADXL335_SENSITIVITY;

    return sqrt(x_g * x_g + y_g * y_g + z_g * z_g);
}

// Function to detect impact
void detect_impact(double magnitude) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (magnitude > IMPACT_THRESHOLD) {
        fprintf(log_file, "%s,IMPACT DETECTED\n", timestamp);
        fflush(log_file);
    }
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

// Cleanup function
void cleanup() {
    printf("Cleaning up...\n");
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Register signal handler
    signal(SIGINT, signal_handler);

    // Initialize pigpio
    if (initialize_pigpio() != 0) {
        return 1;
    }

    // Initialize SPI
    if (initialize_spi() != 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen("impact_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup();
        return 1;
    }

    // Set CS pin as output
    gpioSetMode(CS_PIN, PI_OUTPUT);
    gpioWrite(CS_PIN, 1); // Deselect MCP3008 initially

    printf("Starting data acquisition...\n");

    while (!terminate) {
        // Read ADC values
        int x = read_adc_channel(0);
        int y = read_adc_channel(1);
        int z = read_adc_channel(2);

        if (x < 0 || y < 0 || z < 0) {
            fprintf(stderr, "Error reading ADC values, retrying...\n");
            gpioDelay(100000); // 100ms delay
            continue;
        }

        // Log data
        log_data(x, y, z);

        // Calculate acceleration magnitude
        double magnitude = calculate_acceleration_magnitude(x, y, z);

        // Detect impact
        detect_impact(magnitude);

        // Delay for 10ms (100Hz sample rate)
        gpioDelay(10000); // 10ms
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

