#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define SI1172_ADDR 0x49
#define COMMAND_REG 0xC0
#define FIFO_REG 0xC1
#define FIFO_SIZE 4 // Number of bytes to read from FIFO
#define LOG_FILE "biometric_log.csv"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    long timestamp;
    int ir_adc;
    int red_adc;
    int error_flag;
} sensor_data_t;

// Function prototypes
int initialize_sensor();
int read_sensor_data(int *ir_adc, int *red_adc);
int log_data(sensor_data_t data);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initializes the Si1172 sensor
int initialize_sensor() {
    // No specific initialization needed for this example, as the sensor
    // is assumed to be ready upon connection.
    return 0; // Return 0 for success, -1 for failure
}

// Reads raw data from the Si1172 sensor
int read_sensor_data(int *ir_adc, int *red_adc) {
    char cmd[1] = {COMMAND_REG};
    char buffer[FIFO_SIZE];
    int result;

    // Trigger a measurement by writing to the command register
    result = i2cWriteDevice(i2c_handle, cmd, 1);
    if (result != 0) {
        fprintf(stderr, "Error writing to command register: %d\n", result);
        return -1;
    }

    // Read data from the FIFO
    result = i2cReadDevice(i2c_handle, buffer, FIFO_SIZE);
    if (result != FIFO_SIZE) {
        fprintf(stderr, "Error reading from FIFO: %d\n", result);
        return -1;
    }

    // Extract IR and RED ADC values from the buffer
    *ir_adc = (buffer[0] << 8) | buffer[1];
    *red_adc = (buffer[2] << 8) | buffer[3];

    return 0;
}

// Logs the sensor data to a CSV file
int log_data(sensor_data_t data) {
    if (log_file == NULL) {
        fprintf(stderr, "Error: Log file is not open.\n");
        return -1;
    }

    fprintf(log_file, "%ld,%d,%d,%d\n", data.timestamp, data.ir_adc, data.red_adc, data.error_flag);
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

int main() {
    sensor_data_t sensor_data;
    int ir_adc, red_adc;
    int result;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C connection
    i2c_handle = i2cOpen(I2C_BUS, SI1172_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize the sensor
    if (initialize_sensor() != 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open the log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Write the header row if the file is new
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
