#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

// Constants
#define I2C_BUS 1
#define I2C_ADDRESS 0x67
#define MEASUREMENT_COMMAND 0x6845
#define DATA_LENGTH 6
#define SAMPLE_INTERVAL_SEC 5

// Global variables
int i2c_fd = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Calibration parameters (replace with actual values from your sensor)
#define SENSITIVITY_SCALE_FACTOR 1.0  // Example value
#define OFFSET_TEMPERATURE 0.0       // Example value
#define OFFSET_PRESSURE 0.0          // Example value

// Function prototypes
int i2c_open(int bus, int addr);
int i2c_write_bytes(int fd, uint8_t *buf, int len);
int i2c_read_bytes(int fd, uint8_t *buf, int len);
int i2c_close(int fd);
int read_sensor_data(int fd, float *temperature, float *pressure);
int log_data(float temperature, float pressure);
void display_data(float temperature, float pressure);
void signal_handler(int sig);

// I2C open function
int i2c_open(int bus, int addr) {
    char filename[20];
    snprintf(filename, 19, "/dev/i2c-%d", bus);
    int fd = open(filename, O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C bus");
        return -1;
    }
    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        perror("Error setting I2C slave address");
        close(fd);
        return -1;
    }
    return fd;
}

// I2C write bytes function
int i2c_write_bytes(int fd, uint8_t *buf, int len) {
    ssize_t bytes_written = write(fd, buf, len);
    if (bytes_written != len) {
        perror("Error writing to I2C device");
        return -1;
    }
    return 0;
}

// I2C read bytes function
int i2c_read_bytes(int fd, uint8_t *buf, int len) {
    ssize_t bytes_read = read(fd, buf, len);
    if (bytes_read != len) {
        perror("Error reading from I2C device");
        return -1;
    }
    return 0;
}

// I2C close function
int i2c_close(int fd) {
    if (close(fd) < 0) {
        perror("Error closing I2C device");
        return -1;
    }
    return 0;
}

// Read sensor data function
int read_sensor_data(int fd, float *temperature, float *pressure) {
    uint8_t cmd[2] = {(MEASUREMENT_COMMAND >> 8) & 0xFF, MEASUREMENT_COMMAND & 0xFF};
    uint8_t data[DATA_LENGTH];
    int retries = 3;

    while (retries > 0) {
        if (i2c_write_bytes(fd, cmd, 2) == 0) {
            usleep(100000); // Wait for conversion (adjust as needed)
            if (i2c_read_bytes(fd, data, DATA_LENGTH) == 0) {
                // Convert raw data to pressure and temperature
                int32_t raw_pressure = (data[0] << 16) | (data[1] << 8) | data[2];
                int32_t raw_temperature = (data[3] << 16) | (data[4] << 8) | data[5];

                // Apply calibration formulas (replace with actual formulas from datasheet)
                *pressure = (float)raw_pressure * SENSITIVITY_SCALE_FACTOR + OFFSET_PRESSURE;
                *temperature = (float)raw_temperature * SENSITIVITY_SCALE_FACTOR + OFFSET_TEMPERATURE;

                return 0; // Success
            } else {
                fprintf(stderr, "Error reading sensor data, retrying...\n");
            }
        } else {
            fprintf(stderr, "Error writing measurement command, retrying...\n");
        }
        retries--;
        sleep(5); // Wait before retrying
    }

    fprintf(stderr, "Failed to read sensor data after multiple retries.\n");
    return -1; // Failure
}

// Log data to CSV file function
int log_data(float temperature, float pressure) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, temperature, pressure);
    fflush(log_file); // Ensure data is written to disk
    return 0;
}

// Display data on console function
void display_data(float temperature, float pressure) {
    printf("Temperature: %.2f °C, Pressure: %.2f Pa\n", temperature, pressure);
}

// Signal handler function
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, exiting...\n");
    terminate = 1;
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C bus
    i2c_fd = i2c_open(I2C_BUS, I2C_ADDRESS);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus. Exiting.\n");
        return 1;
    }

    // Open log file
    log_file = fopen("environmental_data.csv", "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        i2c_close(i2c_fd);
        return 1;
    }

    // Write header to log file if it's a new file
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Temperature (C),Pressure (Pa)\n");
    }
    rewind(log_file);

    float temperature, pressure;

    // Main loop
    while (!terminate) {
        if (read_sensor_data(i2c_fd, &temperature, &pressure) == 0) {
            log_data(temperature, pressure);
            display_data(temperature, pressure);
        } else {
            fprintf(stderr, "Failed to read sensor data.\n");
        }
        sleep(SAMPLE_INTERVAL_SEC);
    }

    // Cleanup
    i2c_close(i2c_fd);
    fclose(log_file);

    return 0;
}

