#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define constants
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define SAMPLE_RATE 16000
#define NUM_CHANNELS 2
#define GAIN_DEFAULT 1.0
#define ADC_CHANNEL_0 0
#define ADC_CHANNEL_1 1

// Global variables
int spi_handle;
volatile sig_atomic_t terminate = 0;

// Structure to hold audio data
typedef struct {
    int16_t channel1;
    int16_t channel2;
} AudioData;

// Function prototypes
int initialize_pigpio();
int initialize_spi();
int read_adc(int channel);
AudioData process_audio(int adc_value1, int adc_value2, float gain);
void output_csv(AudioData audio_data);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Initialize pigpio library
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }
    return 0;
}

// Initialize SPI communication
int initialize_spi() {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI initialisation failed: %d\n", spi_handle);
        return 1;
    }
    return 0;
}

// Read analog value from MCP3008 ADC
int read_adc(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel: %d\n", channel);
        return -1;
    }

    unsigned char spi_tx_buf[3];
    unsigned char spi_rx_buf[3];

    // Construct SPI message (MCP3008 datasheet)
    spi_tx_buf[0] = 0x01; // Start bit
    spi_tx_buf[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    spi_tx_buf[2] = 0x00; // Don't care

    if (spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3) != 0) {
        fprintf(stderr, "SPI transfer failed\n");
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];
    return adc_value;
}

// Process audio data (subtract channels and apply gain)
AudioData process_audio(int adc_value1, int adc_value2, float gain) {
    AudioData audio_data;
    int16_t diff = (int16_t)(adc_value1 - adc_value2);
    audio_data.channel1 = (int16_t)(diff * gain); // Apply gain to the difference
    audio_data.channel2 = (int16_t)(diff * gain); // Apply gain to the difference
    return audio_data;
}

// Output audio data to CSV format
void output_csv(AudioData audio_data) {
    printf("%d,%d\n", audio_data.channel1, audio_data.channel2);
}

// Cleanup resources before exiting
void cleanup() {
    printf("Cleaning up...\n");
    spiClose(spi_handle);
    gpioTerminate();
}

int main(int argc, char *argv[]) {
    float gain = GAIN_DEFAULT;

    // Parse command-line arguments
    if (argc > 1) {
        gain = atof(argv[1]);
        if (gain <= 0) {
            fprintf(stderr, "Invalid gain value. Using default gain of 1.0\n");
            gain = GAIN_DEFAULT;
        }
    }

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize pigpio
    if (initialize_pigpio()) {
        return 1;
    }

    // Initialize SPI
    if (initialize_spi()) {
        cleanup();
        return 1;
    }

    printf("Audio sampling started. Press Ctrl+C to exit.\n");
    printf("Gain: %.2f\n", gain);

    // Main loop
    while (!terminate) {
        // Read ADC values from both microphones
        int adc_value1 = read_adc(ADC_CHANNEL_0);
        int adc_value2 = read_adc(ADC_CHANNEL_1);

        if (adc_value1 == -1 || adc_value2 == -1) {
            fprintf(stderr, "Error reading ADC values. Retrying...\n");
            gpioDelay(1000); // Wait 1ms before retrying
            continue;
        }

        // Process audio data
        AudioData audio_data = process_audio(adc_value1, adc_value2, gain);

        // Output audio data to CSV
        output_csv(audio_data);

        // Delay to achieve desired sampling rate
        gpioDelay(1000000 / SAMPLE_RATE); // Delay in microseconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

