#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define BUZZER_GPIO 18
#define FLAME_THRESHOLD 1.0
#define TEMPERATURE_FILE "ambient_temp.txt"
#define LOG_FILE "flame_log.txt"
#define MAX_RETRIES 3

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
float read_temperature();
float voltage_to_adc(int adc_value);
float temperature_compensation(float voltage, float temperature);
int detect_flame(float compensated_voltage);
void control_buzzer(int flame_detected);
void log_data(int adc_value, float voltage, float compensated_voltage, float temperature, int flame_detected);
void signal_handler(int signal);

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    char tx_buf[3];
    char rx_buf[3];
    int adc_value;
    int retries = 0;

    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = (0x08 | (channel << 4)); // Single-ended mode, channel selection
    tx_buf[2] = 0x00; // Dummy byte

    while (retries < MAX_RETRIES) {
        if (spiXfer(spi_handle, tx_buf, rx_buf, 3) == 0) {
            adc_value = ((rx_buf[1] & 0x03) << 8) + rx_buf[2];
            return adc_value;
        } else {
            fprintf(stderr, "SPI transfer failed (attempt %d). Retrying...\n", retries + 1);
            log_data(-1, -1.0, -1.0, -1.0, -1); // Log SPI error
            gpioWrite(BUZZER_GPIO, 0); // Turn off buzzer on error
            gpioDelay(100); // Small delay before retry
            retries++;
        }
    }

    fprintf(stderr, "SPI transfer failed after %d retries. Skipping iteration.\n", MAX_RETRIES);
    log_data(-1, -1.0, -1.0, -1.0, -1); // Log SPI error
    gpioWrite(BUZZER_GPIO, 0); // Turn off buzzer on error
    return -1; // Indicate failure
}

// Function to read ambient temperature from file
float read_temperature() {
    FILE *fp;
    float temperature = 25.0; // Default temperature

    fp = fopen(TEMPERATURE_FILE, "r");
    if (fp != NULL) {
        if (fscanf(fp, "%f", &temperature) != 1) {
            fprintf(stderr, "Error reading temperature from file. Using default value.\n");
            temperature = 25.0;
        }
        fclose(fp);
    } else {
        fprintf(stderr, "Temperature file not found. Using default value.\n");
    }

    return temperature;
}

// Function to convert ADC value to voltage (assuming 3.3V reference)
float voltage_to_adc(int adc_value) {
    return (float)adc_value * 3.3 / 1024.0;
}

// Function to apply temperature compensation
float temperature_compensation(float voltage, float temperature) {
    return voltage + (temperature - 25.0) * 0.001;
}

// Function to detect flame based on compensated voltage
int detect_flame(float compensated_voltage) {
    return (compensated_voltage > FLAME_THRESHOLD) ? 1 : 0;
}

// Function to control the buzzer
void control_buzzer(int flame_detected) {
    gpioWrite(BUZZER_GPIO, flame_detected);
}

