#include <linux/spi/spidev.h>
#include <gpiod.h>
#include <signal.h>
#include <time.h>

// Define SPI device and clock speed
#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE SPI_MODE_0
#define SPI_BITS_PER_WORD 8
#define SPI_SPEED 1000000 // 1 MHz

// Define MCP3008 channel
#define MCP3008_CHANNEL 0

// Define dry and wet calibration ADC values
#define DRY_ADC_VALUE 700
#define WET_ADC_VALUE 300

// Global variables
int spi_fd = -1;
struct gpiod_chip *chip = NULL;
struct gpiod_line *ce_line = NULL;

// Function prototypes
int spi_init(void);
int read_mcp3008(int channel);
float calculate_moisture_percentage(int adc_value);
void log_data(int adc_value, float moisture_percentage);
void signal_handler(int sig);

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);
    if (spi_fd != -1) {
        close(spi_fd);
    }
    if (chip != NULL) {
        gpiod_line_release(ce_line);
        gpiod_chip_close(chip);
    }
    exit(0);
}

// Initialize SPI interface
int spi_init(void) {
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }

    // Set SPI mode
    int mode = SPI_MODE;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("Error setting SPI mode");
        close(spi_fd);
        return -1;
    }

    // Set bits per word
    int bits = SPI_BITS_PER_WORD;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        perror("Error setting bits per word");
        close(spi_fd);
        return -1;
    }

    // Set SPI speed
    int speed = SPI_SPEED;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("Error setting SPI speed");
        close(spi_fd);
        return -1;
    }

    // Open GPIO chip for CE0 line
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Error opening GPIO chip");
        close(spi_fd);
        return -1;
    }

    // Get CE0 line
    ce_line = gpiod_chip_get_line(chip, 8); // GPIO8
    if (!ce_line) {
        perror("Error getting CE0 line");
        gpiod_chip_close(chip);
        close(spi_fd);
        return -1;
    }

    // Request CE0 line for output
    if (gpiod_line_request_output(ce_line, "soil_moisture", 0) < 0) {
        perror("Error requesting CE0 line for output");
        gpiod_chip_close(chip);
        close(spi_fd);
        return -1;
    }

    return 0;
}

// Read data from MCP3008 ADC
int read_mcp3008(int channel) {
    unsigned char tx_buf[3];
    unsigned char rx_buf[3];
    struct spi_ioc_transfer transfer[1];

    // Construct SPI message
    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = (0x08 | (channel << 4)) << 4; // Single-ended mode, channel select
    tx_buf[2] = 0x00; // Don't care

    memset(transfer, 0, sizeof(transfer));

    transfer[0].tx_buf = (unsigned long)tx_buf;
    transfer[0].rx_buf = (unsigned long)rx_buf;
    transfer[0].len = 3;
    transfer[0].delay_usecs = 0;
    transfer[0].speed_hz = SPI_SPEED;
    transfer[0].bits_per_word = SPI_BITS_PER_WORD;

    // Activate CE0 line
    if (gpiod_line_set_value(ce_line, 0) < 0) {
        perror("Error setting CE0 line");
        return -1;
    }

    // Perform SPI transfer
    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), transfer) < 0) {
        perror("Error performing SPI transfer");
        if (gpiod_line_set_value(ce_line, 1) < 0) {
            perror("Error setting CE0 line");
        }
        return -1;
    }

    // Deactivate CE0 line
    if (gpiod_line_set_value(ce_line, 1) < 0) {
        perror("Error setting CE0 line");
        return -1;
    }

    // Extract ADC value
    int adc_value = ((rx_buf[1] & 0x03) << 8) + rx_buf[2];

    return adc_value;
}

// Calculate moisture percentage
float calculate_moisture_percentage(int adc_value) {
    float percentage = 100.0 - ((float)(adc_value - WET_ADC_VALUE) / (float)(DRY_ADC_VALUE - WET_ADC_VALUE)) * 100.0;

    // Clamp percentage between 0 and 100
    if (percentage < 0.0) {
        percentage = 0.0;
    } else if (percentage > 100.0) {
        percentage = 100.0;
    }

    return percentage;
}

// Log data to console
void log_data(int adc_value, float moisture_percentage) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("[%s] ADC Value: %d, Moisture: %.2f%%\n", timestamp, adc_value, moisture_percentage);
}

int main(void) {
    // Register signal handler for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize SPI interface
    if (spi_init() < 0) {
        fprintf(stderr, "SPI initialization failed. Exiting.\n");
        return 1;
    }

    // Main loop
    while (1) {
        // Read ADC value from MCP3008
        int adc_value = read_mcp3008(MCP3008_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Error reading ADC value. Retrying in 5 seconds.\n");
            sleep(5);
            continue;
        }

        // Calculate moisture percentage
        float moisture_percentage = calculate_moisture_percentage(adc_value);

        // Log data
        log_data(adc_value, moisture_percentage);

        // Wait for 5 seconds
        sleep(5);
    }

    return 0;
}

