// Define SPI parameters
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 0

// Define MCP3008 channel
#define MCP3008_CHANNEL 0

// Define pressure range
#define MIN_PRESSURE 10.0  // kPa
#define MAX_PRESSURE 150.0 // kPa

// Define voltage range
#define MIN_VOLTAGE 0.5   // V
#define MAX_VOLTAGE 4.5   // V

// Global variable for SPI handle
int spi_handle;

// Function prototypes
int read_mcp3008(int channel);
float adc_to_voltage(int adc_value);
float voltage_to_pressure(float voltage);
void log_data(float pressure);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    spiClose(spi_handle);
    gpioTerminate();
    exit(0);
}

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    // Construct SPI message (MCP3008 datasheet)
    unsigned char spi_tx_buf[3];
    unsigned char spi_rx_buf[3];

    spi_tx_buf[0] = 0x01;                           // Start bit
    spi_tx_buf[1] = ((channel & 0x07) << 4) | 0x80; // Single-ended mode, channel select
    spi_tx_buf[2] = 0x00;                           // Don't care

    // Transfer SPI data
    int result = spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3);
    if (result != 0) {
        fprintf(stderr, "Error: SPI transfer failed: %d\n", result);
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];

    return adc_value;
}

// Function to convert ADC value to voltage
float adc_to_voltage(int adc_value) {
    if (adc_value < 0 || adc_value > 1023) {
        fprintf(stderr, "Error: Invalid ADC value: %d\n", adc_value);
        return -1.0;
    }

    float voltage = (float)adc_value * 3.3 / 1024.0;
    return voltage;
}

// Function to convert voltage to pressure
float voltage_to_pressure(float voltage) {
    if (voltage < MIN_VOLTAGE || voltage > MAX_VOLTAGE) {
        fprintf(stderr, "Error: Voltage out of range: %.2f V\n", voltage);
        return -1.0;
    }

    float pressure = MIN_PRESSURE + (voltage - MIN_VOLTAGE) * (MAX_PRESSURE - MIN_PRESSURE) / (MAX_VOLTAGE - MIN_VOLTAGE);
    return pressure;
}

// Function to log data with ISO-8601 timestamp
void log_data(float pressure) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    printf("%s Pressure: %.2f kPa\n", timestamp, pressure);
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handling for Ctrl+C and termination signals
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (1) {
        // Read ADC value
        int adc_value = read_mcp3008(MCP3008_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Error: Failed to read ADC value\n");
            continue; // Skip to the next iteration
        }

        // Convert ADC value to voltage
        float voltage = adc_to_voltage(adc_value);
        if (voltage < 0) {
            fprintf(stderr, "Error: Failed to convert ADC value to voltage\n");
            continue; // Skip to the next iteration
        }

        // Convert voltage to pressure
        float pressure = voltage_to_pressure(voltage);
        if (pressure < 0) {
            fprintf(stderr, "Error: Failed to convert voltage to pressure\n");
            continue; // Skip to the next iteration
        }

        // Log the data
        log_data(pressure);

        // Wait for 1 second
        gpioDelay(1000); // Delay in milliseconds
    }

    // The following lines will never be reached due to the infinite loop,
    // but are included for completeness.
    spiClose(spi_handle);
    gpioTerminate();
    return 0;
}

