#include <pigpio.h>

// Define GPIO pins
#define SPI_CE0 0
#define SPI_MOSI 10
#define SPI_MISO 9
#define SPI_SCLK 11
#define PUMP_GPIO 17

// Define SPI parameters
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 0

// Define moisture thresholds
#define MOISTURE_LOW_THRESHOLD 300
#define MOISTURE_HIGH_THRESHOLD 600

// Define pump activation duration
#define PUMP_DURATION 5 // seconds

// Define circular buffer size
#define BUFFER_SIZE 20

// Structure to store log entries
typedef struct {
    time_t timestamp;
    int moisture_level;
    int pump_state;
} LogEntry;

// Global variables
int spi_handle;
int pump_state = 0; // 0 = off, 1 = on
int buffer_index = 0;
LogEntry log_buffer[BUFFER_SIZE];

// Function prototypes
int read_mcp3008(int channel);
void control_pump(int moisture_level);
void add_log_entry(int moisture_level, int pump_state);
void print_log_buffer();
void signal_handler(int signal);

// Function to read data from MCP3008 ADC
int read_mcp3008(int channel) {
    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message (MCP3008 datasheet)
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | (channel << 4)); // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Don't care

    // Perform SPI transfer
    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);

    if (result != 3) {
        fprintf(stderr, "Error: SPI transfer failed (read_mcp3008). Result: %d\n", result);
        return -1; // Indicate error
    }

    // Extract ADC value (10 bits)
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];

    return adc_value;
}

// Function to control the water pump
void control_pump(int moisture_level) {
    if (moisture_level < MOISTURE_LOW_THRESHOLD && pump_state == 0) {
        // Turn pump on
        gpioWrite(PUMP_GPIO, 1);
        pump_state = 1;
        printf("Turning pump ON\n");
    } else if (moisture_level > MOISTURE_HIGH_THRESHOLD && pump_state == 1) {
        // Turn pump off
        gpioWrite(PUMP_GPIO, 0);
        pump_state = 0;
        printf("Turning pump OFF\n");
    }
