#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define MAX30102_ADDR 0x57
#define PART_ID_REG 0xFF
#define MODE_CONFIG_REG 0x06
#define SPO2_CONFIG_REG 0x08
#define LED1_PA_REG 0x09
#define LED2_PA_REG 0x0A
#define FIFO_DATA_REG 0x07
#define FIFO_RD_PTR_REG 0x0B
#define FIFO_WR_PTR_REG 0x0C
#define FIFO_CONFIG_REG 0x0D
#define FIFO_OVERFLOW_REG 0x0E
#define INT_CONFIG_REG 0x0F
#define INT_SOURCE_REG 0x10
#define INTERRUPT_GPIO 4

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_max30102();
int read_fifo_data(uint8_t *data, int num_bytes);
int process_fifo_data(uint8_t *data, int num_bytes, int *red_values, int *ir_values, int *num_samples);
float calculate_spo2(int *red_values, int *ir_values, int num_samples);
int calculate_heart_rate(int *ir_values, int num_samples, int sample_rate_hz);
void log_data(float spo2, int heart_rate);
void signal_handler(int signal);

// Signal handler
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Initialize MAX30102 sensor
int init_max30102() {
    int part_id;

    // Check sensor presence
    part_id = i2cReadByteData(i2c_handle, PART_ID_REG);
    if (part_id < 0) {
        fprintf(stderr, "Error reading Part ID: %d\n", part_id);
        return -1;
    }
    if (part_id != 0x15) {
        fprintf(stderr, "Incorrect Part ID: 0x%02X (expected 0x15)\n", part_id);
        return -1;
    }
    printf("MAX30102 sensor found with Part ID: 0x%02X\n", part_id);

    // Reset sensor
    if (i2cWriteByteData(i2c_handle, MODE_CONFIG_REG, 0x40) < 0) {
        fprintf(stderr, "Error resetting sensor\n");
        return -1;
    }
    gpioDelay(100); // Wait for reset

    // Clear interrupts
    if (i2cWriteByteData(i2c_handle, INT_CONFIG_REG, 0x00) < 0) {
        fprintf(stderr, "Error clearing interrupts\n");
        return -1;
    }

    // Configure SpO2 mode
    if (i2cWriteByteData(i2c_handle, MODE_CONFIG_REG, 0x03) < 0) {
        fprintf(stderr, "Error configuring SpO2 mode\n");
        return -1;
    }

    // Configure SPO2_CONFIG register
    if (i2cWriteByteData(i2c_handle, SPO2_CONFIG_REG, 0x27) < 0) {
        fprintf(stderr, "Error configuring SPO2_CONFIG register\n");
        return -1;
    }

    // Configure LED pulse amplitudes
    if (i2cWriteByteData(i2c_handle, LED1_PA_REG, 0x24) < 0) {
        fprintf(stderr, "Error configuring LED1_PA register\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, LED2_PA_REG, 0x24) < 0) {
        fprintf(stderr, "Error configuring LED2_PA register\n");
        return -1;
    }

    return 0;
}

// Read data from FIFO
int read_fifo_data(uint8_t *data, int num_bytes) {
    int bytes_read = i2cReadI2CBlockData(i2c_handle, FIFO_DATA_REG, (char *)data, num_bytes);
    if (bytes_read < 0) {
        fprintf(stderr, "Error reading FIFO data: %d\n", bytes_read);
        return -1;
    }
    return bytes_read;
}

// Process FIFO data
int process_fifo_data(uint8_t *data, int num_bytes, int *red_values, int *ir_values, int *num_samples) {
    int red_index = 0;
    int ir_index = 0;

    for (int i = 0; i < num_bytes; i += 6) {
        red_values[red_index++] = (data[i] << 8) | data[i + 1];
        ir_values[ir_index++] = (data[i + 3] << 8) | data[i + 4];
    }

    *num_samples = red_index; // Number of samples is the number of red values
    return 0;
}

// Calculate SpO2 using ratio-of-ratios method
float calculate_spo2(int *red_values, int *ir_values, int num_samples) {
    // Simple moving average for demonstration purposes
    float red_avg = 0.0;
    float ir_avg = 0.0;
    for (int i = 0; i < num_samples; i++) {
        red_avg += red_values[i];
        ir_avg += ir_values[i];
    }
    red_avg /= num_samples;
    ir_avg /= num_samples;

    // Ratio of ratios (simplified)
    float ratio = (float)red_avg / (float)ir_avg;

    // Empirical SpO2 calculation (replace with a more accurate model)
    float spo2 = 110.0 - 25.0 * ratio; // Example linear relationship
    if (spo2 < 90.0) spo2 = 90.0;
    if (spo2 > 100.0) spo2 = 100.0;

    return spo2;
}

// Calculate heart rate via peak detection
int calculate_heart_rate(int *ir_values, int num_samples, int sample_rate_hz) {
    int num_peaks = 0;
    int peak_indices[100]; // Assuming max 100 peaks

    // Simple peak detection algorithm
    for (int i = 1; i < num_samples - 1; i++) {
        if (ir_values[i] > ir_values[i - 1] && ir_values[i] > ir_values[i + 1]) {
            peak_indices[num_peaks++] = i;
            if (num_peaks >= 100) break; // Limit the number of peaks
        }
    }

    if (num_peaks < 2) return 0; // Not enough peaks to calculate HR

    // Calculate average peak-to-peak interval
    double sum_intervals = 0.0;
    for (int i = 1; i < num_peaks; i++) {
        sum_intervals += (double)(peak_indices[i] - peak_indices[i - 1]);
    }
    double avg_interval = sum_intervals / (num_peaks - 1);

    // Calculate heart rate (BPM)
    int heart_rate = (int)(sample_rate_hz / avg_interval);

    return heart_rate;
}

// Log data to file
void log_data(float spo2, int heart_rate) {
    FILE *fp = fopen("health_log.txt", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file\n");
        return;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", &tm);

    fprintf(fp, "%s, SpO2: %.2f%%, HR: %d BPM\n", timestamp, spo2, heart_rate);
    fclose(fp);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, MAX30102_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize MAX30102 sensor
    if (init_max30102() != 0) {
        fprintf(stderr, "MAX30102 initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Data buffers
    uint8_t fifo_data[18]; // 6 bytes * 3 samples
    int red_values[3];
    int ir_values[3];
    int num_samples;

    // Main loop
    while (!terminate) {
        // Read FIFO data
        if (read_fifo_data(fifo_data, sizeof(fifo_data)) > 0) {
            // Process FIFO data
            if (process_fifo_data(fifo_data, sizeof(fifo_data), red_values, ir_values, &num_samples) == 0) {
                // Calculate SpO2 and heart rate
                float spo2 = calculate_spo2(red_values, ir_values, num_samples);
                int heart_rate = calculate_heart_rate(ir_values, num_samples, 100); // Sample rate = 100 Hz

                // Log data
                log_data(spo2, heart_rate);

                printf("SpO2: %.2f%%, HR: %d BPM\n", spo2, heart_rate);

                // Check for anomalies
                if (spo2 < 95.0 || heart_rate > 100) {
                    FILE *fp = fopen("health_log.txt", "a");
                    if (fp != NULL) {
                        time_t t = time(NULL);
                        struct tm tm = *localtime(&t);
                        char timestamp[30];
                        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", &tm);
                        fprintf(fp, "%s, WARNING: SpO2 = %.2f, HR = %d\n", timestamp, spo2, heart_rate);
                        fclose(fp);
                    }
                }
            }
        }

        gpioDelay(100); // Sample every 100ms (10Hz)
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

