#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define VREF 3.3f
#define NUM_CHANNELS 3
#define LOG_INTERVAL_MS 500
#define MAX_RETRIES 3

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold SPI configuration
typedef struct {
    int channel;
    int speed;
} spi_config_t;

// Function prototypes
int spi_transfer(int spi_handle, unsigned char *tx_buf, unsigned char *rx_buf, int len);
int read_mcp3008(int spi_handle, int channel);
float calculate_voltage(int adc_value, float vref);
char* get_iso8601_timestamp();
int log_data(FILE *fp, int channel, float voltage);
void signal_handler(int signal);

// SPI transfer function with retry mechanism
int spi_transfer(int spi_handle, unsigned char *tx_buf, unsigned char *rx_buf, int len) {
    int retries = 0;
    int result;

    while (retries < MAX_RETRIES) {
        result = spiXfer(spi_handle, tx_buf, rx_buf, len);
        if (result == len) {
            return 0; // Success
        } else {
            fprintf(stderr, "SPI transfer failed (attempt %d): %d\n", retries + 1, result);
            retries++;
            gpioDelay(1000); // Wait 1 ms before retrying
        }
    }

    fprintf(stderr, "SPI transfer failed after %d retries.\n", MAX_RETRIES);
    return -1; // Failure
}

// Function to read from MCP3008 ADC
int read_mcp3008(int spi_handle, int channel) {
    unsigned char tx_buf[3];
    unsigned char rx_buf[3];

    // Construct SPI message
    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = (0x08 | (channel & 0x07)) << 4; // Single-ended, channel select
    tx_buf[2] = 0x00; // Dummy byte

    // Perform SPI transfer
    if (spi_transfer(spi_handle, tx_buf, rx_buf, 3) != 0) {
        fprintf(stderr, "SPI transfer failed during MCP3008 read.\n");
        return -1; // Indicate error
    }

    // Extract ADC value from response
    int adc_value = ((rx_buf[1] & 0x03) << 8) + rx_buf[2];

    return adc_value;
}

// Function to calculate voltage from ADC value
float calculate_voltage(int adc_value, float vref) {
    return ((float)adc_value / 1023.0f) * vref;
}

// Function to get current timestamp in ISO 8601 format
char* get_iso8601_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    char *timestamp = (char*)malloc(25 * sizeof(char)); // Allocate memory for timestamp

    time(&rawtime);
    timeinfo = gmtime(&rawtime); // Use gmtime for UTC time

    strftime(timestamp, 25, "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    return timestamp;
}

// Function to log data to CSV file
int log_data(FILE *fp, int channel, float voltage) {
    char *timestamp = get_iso8601_timestamp();
    if (fprintf(fp, "%s,%d,%.3f\n", timestamp, channel, voltage) < 0) {
        fprintf(stderr, "Error writing to log file.\n");
        free(timestamp);
        return -1;
    }
    free(timestamp);
    fflush(fp); // Flush the buffer to ensure data is written to file
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // SPI mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("analog_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Write header row if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Channel,Voltage\n");
    }
    rewind(log_file);

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        for (int channel = 0; channel < NUM_CHANNELS; channel++) {
            int adc_value = read_mcp3008(spi_handle, channel);
            if (adc_value >= 0) {
                float voltage = calculate_voltage(adc_value, VREF);
                if (log_data(log_file, channel, voltage) != 0) {
                    fprintf(stderr, "Failed to log data for channel %d\n", channel);
                }
            } else {
                fprintf(stderr, "Failed to read from channel %d\n", channel);
            }
        }
        gpioDelay(LOG_INTERVAL_MS); // Wait before next reading
    }

    // Cleanup
    spiClose(spi_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

