    signal(SIGINT, signal_handler);

    printf("Gas sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        // Read ADC value from MQ-2 sensor
        int adc_value = read_mcp3008(MCP3008_CHANNEL);
