            fprintf(stderr, "Error: Failed to read ADC value\n");
            break; // Exit loop on error
        }

        // Control buzzer based on gas concentration
        if (adc_value < GAS_THRESHOLD) {
            control_buzzer(BUZZER_GPIO, 0); // Turn buzzer OFF
        } else {
            control_buzzer(BUZZER_GPIO, 1); // Turn buzzer ON
        }

        // Print ADC value (for debugging)
        printf("ADC Value: %d\n", adc_value);

        // Wait for the next sample
        gpioDelay(SAMPLE_INTERVAL_MS * 1000); // Convert ms to microseconds
    }

    // Cleanup before exiting
    printf("Cleaning up...\n");
    spiClose(spi_handle);
    control_buzzer(BUZZER_GPIO, 0); // Ensure buzzer is OFF
    gpioTerminate();

    printf("Exiting.\n");
    return 0;
}

