#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>
#include <errno.h>

// Constants
#define I2C_BUS "/dev/i2c-1"
#define I2C_ADDR 0x48
#define RELAY_GPIO 17
#define REED_SENSOR_GPIO 27
#define NUM_SAMPLES 10
#define SAMPLE_DELAY_MS 50
#define THRESHOLD_PERCENTAGE 0.8
#define RELAY_DURATION_S 3
#define POLLING_INTERVAL_MS 200

// Global variables (minimize usage)
static int i2c_fd = -1;
static struct gpiod_chip *gpio_chip = NULL;
static struct gpiod_line *relay_line = NULL;
static struct gpiod_line *reed_sensor_line = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c(const char *bus, int addr);
int init_gpio(int gpio);
int init_gpio_line(struct gpiod_chip *chip, int gpio, const char *consumer, int flags);
int read_ads1115(int fd);
float calibrate_threshold(int *samples, int num_samples);
void control_relay(int state);
int read_reed_sensor(int gpio);
void log_event(const char *message);
void signal_handler(int sig);
void cleanup();

// I2C Initialization
int init_i2c(const char *bus, int addr) {
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C bus");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        perror("Error setting I2C slave address");
        close(fd);
        return -1;
    }

    return fd;
}

// GPIO Initialization
int init_gpio(int gpio) {
    gpio_chip = gpiod_chip_open_by_name("gpiochip0");
    if (!gpio_chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    return 0;
}

// GPIO Line Initialization
int init_gpio_line(struct gpiod_chip *chip, int gpio, const char *consumer, int flags) {
    struct gpiod_line *line = gpiod_chip_get_line(chip, gpio);
    if (!line) {
        perror("Error getting GPIO line");
        return -1;
    }

    if (gpiod_line_request_output(line, consumer, flags) < 0) {
        perror("Error requesting GPIO line as output");
        gpiod_line_release(line);
        return -1;
    }

    return 0;
}

// ADS1115 Reading
int read_ads1115(int fd) {
    unsigned char buf[3];
    int16_t raw_value;

    // Configuration register value for single-ended A0, 4.096V, single conversion
    unsigned char config[3] = {0x01, 0x83, 0x83}; // Start single conversion

    if (write(fd, config, 3) != 3) {
        perror("Error writing to I2C device");
        log_event("Error writing to I2C device");
        return -1;
    }

    // Wait for conversion to complete (at least 125ms for 128 SPS)
    usleep(150000); // 150ms

    buf[0] = 0x00; // Dummy byte for reading
    if (read(fd, buf, 3) != 3) {
        perror("Error reading from I2C device");
        log_event("Error reading from I2C device");
        return -1;
    }

    raw_value = (buf[1] << 8) | buf[2];
    return raw_value;
}

// Threshold Calibration
float calibrate_threshold(int *samples, int num_samples) {
    double sum = 0.0;
    for (int i = 0; i < num_samples; i++) {
        sum += samples[i];
    }
    double average = sum / num_samples;
    return average * THRESHOLD_PERCENTAGE;
}

// Relay Control
void control_relay(int state) {
    if (relay_line) {
        gpiod_line_set_value(relay_line, state);
    } else {
        fprintf(stderr, "Relay line not initialized.\n");
    }
}

// Reed Sensor Reading
int read_reed_sensor(int gpio) {
    if (reed_sensor_line) {
        return gpiod_line_get_value(reed_sensor_line);
    } else {
        fprintf(stderr, "Reed sensor line not initialized.\n");
        return -1; // Indicate error
    }
}

// Event Logging
void log_event(const char *message) {
    FILE *fp = fopen("/var/log/door_events.log", "a");
    if (fp) {
        time_t t = time(NULL);
        struct tm tm = *localtime(&t);
        fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d.%03d: %s\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, usleep(1000), message);
        fclose(fp);
    } else {
        perror("Error opening log file");
    }
}

// Signal Handler
void signal_handler(int sig) {
    terminate = 1;
    printf("Signal received, exiting...\n");
}

// Cleanup
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (relay_line) {
        gpiod_line_release(relay_line);
    }
    if (reed_sensor_line) {
        gpiod_line_release(reed_sensor_line);
    }
    if (gpio_chip) {
        gpiod_chip_close(gpio_chip);
    }
