#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>
#include <errno.h>

// Configuration
#define SPI_BUS 0
#define SPI_DEVICE 0
#define SPI_SPEED 1000000 // 1 MHz
#define CS0_GPIO 8
#define CS1_GPIO 7
#define CS2_GPIO 25
#define LOG_FILE "soil_moisture_log.csv"
#define SAMPLE_INTERVAL 5 // seconds

// Global variables (to be cleaned up on exit)
static int spi_fd = -1;
static struct gpiod_chip *cs0_chip = NULL;
static struct gpiod_line *cs0_line = NULL;
static struct gpiod_chip *cs1_chip = NULL;
static struct gpiod_line *cs1_line = NULL;
static struct gpiod_chip *cs2_chip = NULL;
static struct gpiod_line *cs2_line = NULL;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int spi_init(int bus, int device, int speed);
int spi_transfer(int fd, unsigned char *tx_buf, unsigned char *rx_buf, int len);
int read_mcp3008(int spi_fd, int channel);
int log_data(FILE *fp, int sensor1, int sensor2, int sensor3);
void signal_handler(int sig);
void cleanup();

// SPI Initialization
int spi_init(int bus, int device, int speed) {
    char spi_dev[20];
    snprintf(spi_dev, sizeof(spi_dev), "/dev/spidev%d.%d", bus, device);

    int fd = open(spi_dev, O_RDWR);
    if (fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }

    // Configure SPI mode
    int mode = 0; // SPI_MODE_0
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("Error setting SPI mode");
        close(fd);
        return -1;
    }

    // Configure SPI speed
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("Error setting SPI speed");
        close(fd);
        return -1;
    }

    return fd;
}

// SPI Transfer
int spi_transfer(int fd, unsigned char *tx_buf, unsigned char *rx_buf, int len) {
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx_buf,
        .rx_buf = (unsigned long)rx_buf,
        .len = len,
        .delay_usecs = 0,
        .speed_hz = SPI_SPEED,
        .bits_per_word = 8,
    };

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("Error during SPI transfer");
        return -1;
    }

    return 0;
}

// MCP3008 Read
int read_mcp3008(int spi_fd, int channel) {
    unsigned char tx_buf[3];
    unsigned char rx_buf[3];

    // Construct SPI message
    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = (0x08 | (channel & 0x07)) << 4; // Single-ended, channel select
    tx_buf[2] = 0x00; // Don't care

    // Perform SPI transfer
    if (spi_transfer(spi_fd, tx_buf, rx_buf, 3) < 0) {
        return -1; // Indicate error
    }

    // Extract ADC value
    int adc_value = ((rx_buf[1] & 0x03) << 8) | rx_buf[2];

    return adc_value;
}

// Data Logging
int log_data(FILE *fp, int sensor1, int sensor2, int sensor3) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (fprintf(fp, "%s,%d,%d,%d\n", timestamp, sensor1, sensor2, sensor3) < 0) {
        perror("Error writing to log file");
        return -1;
    }

    fflush(fp); // Ensure data is written to disk
    return 0;
}

// Signal Handler
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Cleanup function
void cleanup() {
    fprintf(stderr, "Cleaning up resources...\n");

    // Close SPI device
    if (spi_fd != -1) {
        close(spi_fd);
    }

    // Release libgpiod lines and chips
    if (cs0_line) {
        gpiod_line_release(cs0_line);
    }
    if (cs0_chip) {
        gpiod_chip_close(cs0_chip);
    }

    if (cs1_line) {
        gpiod_line_release(cs1_line);
    }
    if (cs1_chip) {
        gpiod_chip_close(cs1_chip);
    }

    if (cs2_line) {
        gpiod_line_release(cs2_line);
    }
    if (cs2_chip) {
        gpiod_chip_close(cs2_chip);
    }

    // Close log file
    if (log_file) {
        fclose(log_file);
    }

    fprintf(stderr, "Cleanup complete. Exiting.\n");
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize SPI
    spi_fd = spi_init(SPI_BUS, SPI_DEVICE, SPI_SPEED);
    if (spi_fd < 0) {
        fprintf(stderr, "SPI initialization failed. Exiting.\n");
        return 1;
    }

    // Initialize libgpiod for CS lines
    cs0_chip = gpiod_chip_open_by_name("gpiochip0");
    if (!cs0_chip) {
        perror("Error opening GPIO chip for CS0");
        cleanup();
        return 1;
    }

    cs0_line = gpiod_chip_get_line(cs0_chip, CS0_GPIO);
    if (!cs0_line) {
        perror("Error getting GPIO line for CS0");
        cleanup();
        return 1;
    }

    if (gpiod_line_request_output(cs0_line, "soil_moisture", 1) < 0) {
        perror("Error requesting GPIO line for CS0");
        cleanup();
        return 1;
    }

    cs1_chip = gpiod_chip_open_by_name("gpiochip0");
    if (!cs1_chip) {
        perror("Error opening GPIO chip for CS1");
        cleanup();
        return 1;
    }

    cs1_line = gpiod_chip_get_line(cs1_chip, CS1_GPIO);
    if (!cs1_line) {
        perror("Error getting GPIO line for CS1");
        cleanup();
        return 1;
    }

    if (gpiod_line_request_output(cs1_line, "soil_moisture", 1) < 0) {
        perror("Error requesting GPIO line for CS1");
        cleanup();
        return 1;
    }

    cs2_chip = gpiod_chip_open_by_name("gpiochip0");
    if (!cs2_chip) {
        perror("Error opening GPIO chip for CS2");
        cleanup();
        return 1;
    }

    cs2_line = gpiod_chip_get_line(cs2_chip, CS2_GPIO);
    if (!cs2_line) {
        perror("Error getting GPIO line for CS2");
        cleanup();
        return 1;
    }

    if (gpiod_line_request_output(cs2_line, "soil_moisture", 1) < 0) {
        perror("Error requesting GPIO line for CS2");
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        cleanup();
        return 1;
    }

    // Check if the file is newly created and write the header
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "timestamp,sensor1,sensor2,sensor3\n");
    }
    rewind(log_file);

    // Main loop
    while (!terminate) {
        // Read sensor values
        int sensor1 = read_mcp3008(spi_fd, 0);
        int sensor2 = read_mcp3008(spi_fd, 0);
        int sensor3 = read_mcp3008(spi_fd, 0);

        // Log data
        if (log_data(log_file, sensor1, sensor2, sensor3) < 0) {
            fprintf(stderr, "Error logging data. Continuing...\n");
        }

        // Wait for the next sample
        sleep(SAMPLE_INTERVAL);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

