#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define PUMP_GPIO 18
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define MCP3008_CS 8
#define NUM_SENSORS 3
#define NUM_RETRIES 3

// Default values
#define DEFAULT_THRESHOLD 30.0
#define DEFAULT_DURATION 10
#define DEFAULT_INTERVAL 60

// Global variables
int spi_handle;
FILE *log_file;
double dry_bound[NUM_SENSORS];
double wet_bound[NUM_SENSORS];
double moisture_threshold;
int pump_duration;
int sleep_interval;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
double calculate_moisture(int raw_value, double dry_bound, double wet_bound);
void control_pump(int pump_state);
void log_data(int sensor_id, double moisture_percentage, int pump_state);
void signal_handler(int signal);
void parse_arguments(int argc, char *argv[]);

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = ((channel & 0x07) << 4) | 0x80; // Single-ended mode, channel select
    tx_buffer[2] = 0x00;

    for (int i = 0; i < NUM_RETRIES; ++i) {
        gpioWrite(MCP3008_CS, 0); // Select MCP3008
        int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
        gpioWrite(MCP3008_CS, 1); // Deselect MCP3008

        if (result == 3) {
            // Extract ADC value (10 bits)
            int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
            return adc_value;
        } else {
            fprintf(stderr, "Error: SPI read failed (attempt %d): %d\n", i + 1, result);
            gpioDelay(1000); // Wait before retrying
        }
    }

    fprintf(stderr, "Error: SPI read failed after %d retries.\n", NUM_RETRIES);
    return -1; // Indicate failure
}

// Function to calculate moisture percentage
double calculate_moisture(int raw_value, double dry_bound, double wet_bound) {
    double moisture = (double)(raw_value - dry_bound) / (wet_bound - dry_bound) * 100.0;

    // Clamp moisture percentage to 0-100%
    if (moisture < 0.0) {
        moisture = 0.0;
    } else if (moisture > 100.0) {
        moisture = 100.0;
    }

    return moisture;
}

// Function to control the water pump
void control_pump(int pump_state) {
    gpioWrite(PUMP_GPIO, pump_state);
}

// Function to log data to file
void log_data(int sensor_id, double moisture_percentage, int pump_state) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s - Sensor %d: Moisture = %.2f%%, Pump = %s\n",
            timestamp, sensor_id, moisture_percentage, pump_state ? "ON" : "OFF");
    fflush(log_file); // Ensure data is written to disk immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, shutting down...\n");
    terminate = 1;
}

// Function to parse command-line arguments
void parse_arguments(int argc, char *argv[]) {
    int opt;

    while ((opt = getopt(argc, argv, "t:d:s:")) != -1) {
        switch (opt) {
            case 't':
                moisture_threshold = atof(optarg);
                break;
            case 'd':
                pump_duration = atoi(optarg);
                break;
            case 's':
                sleep_interval = atoi(optarg);
                break;
            default:
                fprintf(stderr, "Usage: %s [-t threshold] [-d duration_seconds] [-s sleep_interval]\n", argv[0]);
                exit(EXIT_FAILURE);
        }
    }
}

int main(int argc, char *argv[]) {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Parse command-line arguments
    parse_arguments(argc, argv);

    // Set GPIO modes
    gpioSetMode(PUMP_GPIO, PI_OUTPUT);
    gpioSetMode(MCP3008_CS, PI_OUTPUT);

    // Initialize SPI
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // SPI0, 1MHz, Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI initialisation failed\n");
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("irrigation.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        for (int i = 0; i < NUM_SENSORS; ++i) {
            // Read raw ADC value
            int raw_value = read_mcp3008(i);
            if (raw_value < 0) {
                fprintf(stderr, "Error: Failed to read sensor %d\n", i);
                continue; // Skip to the next sensor
            }

            // Calculate moisture percentage
            double moisture_percentage = calculate_moisture(raw_value, dry_bound[i], wet_bound[i]);

            // Log data
            log_data(i, moisture_percentage, 0); // Log before pump control

            // Control pump based on moisture threshold
            if (moisture_percentage < moisture_threshold) {
                control_pump(1); // Turn pump ON
                log_data(i, moisture_percentage, 1); // Log pump ON
                gpioDelay(pump_duration * 1000); // Wait for pump duration
                control_pump(0); // Turn pump OFF
                log_data(i, moisture_percentage, 0); // Log pump OFF
            }
        }

        gpioDelay(sleep_interval * 1000); // Wait before next cycle
    }

    // Cleanup
    control_pump(0); // Ensure pump is OFF
    spiClose(spi_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

