#include <unistd.h>
#include <pigpio.h>

// Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define ADC_CHANNEL 0
#define EMA_ALPHA 0.1
#define PEAK_THRESHOLD 1.2
#define LOG_FILE "/var/log/sound_events.log"

// Global variables
int spi_handle;
double ema = 0.0;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize();
int read_adc(int channel);
double update_ema(double new_value, double current_ema);
int detect_peak(int raw_value, double ema);
int log_event(int raw_value);
void signal_handler(int signal);

// Structure for SPI configuration (optional)
typedef struct {
    int channel;
    int speed;
} spi_config_t;

// Function to initialize the pigpio library and SPI
int initialize() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // SPI mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    return 0;
}

// Function to read from the MCP3008 ADC
int read_adc(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel\n");
        return -1;
    }

    unsigned char spi_tx_buf[3];
    unsigned char spi_rx_buf[3];

    // Construct SPI message (MCP3008 datasheet)
    spi_tx_buf[0] = 0x01; // Start bit
    spi_tx_buf[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    spi_tx_buf[2] = 0x00; // Don't care

    if (spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3) != 0) {
        fprintf(stderr, "SPI transfer failed\n");
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];
    return adc_value;
}

// Function to update the exponential moving average
double update_ema(double new_value, double current_ema) {
    return EMA_ALPHA * new_value + (1 - EMA_ALPHA) * current_ema;
}

// Function to detect a peak based on the threshold margin
int detect_peak(int raw_value, double ema) {
    double threshold = ema * PEAK_THRESHOLD;
    return (raw_value > threshold);
}

// Function to log a sound event to a file
int log_event(int raw_value) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        return 1;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", tm);

    fprintf(fp, "%s, %d\n", timestamp, raw_value);
    fclose(fp);
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Received signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize
    if (initialize()) {
        return 1;
    }

    // Main loop
    while (!terminate) {
        int raw_value = read_adc(ADC_CHANNEL);
        if (raw_value < 0) {
            fprintf(stderr, "Failed to read ADC value\n");
            continue; // Or exit, depending on error handling strategy
        }

        ema = update_ema(raw_value, ema);

        if (detect_peak(raw_value, ema)) {
            if (log_event(raw_value)) {
                fprintf(stderr, "Failed to log event\n");
            }
        }

        gpioDelay(10); // Sample every 10 ms
    }

    // Cleanup
    spiClose(spi_handle);
    gpioTerminate();

    return 0;
}

