#include <stdio.h>
#include <stdlib.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <errno.h>

#define I2C_BUS "/dev/i2c-1"
#define PCF8591_ADDR 0x48
#define CONTROL_BYTE 0x40 // Single-ended, AIN0, no output

int i2c_fd;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    printf("\nCaught signal %d, exiting gracefully.\n", sig);
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    exit(0);
}

// Function to read the analog value from the PCF8591
int read_pcf8591() {
    unsigned char data;

    // Write the control byte to the PCF8591
    if (write(i2c_fd, &CONTROL_BYTE, 1) != 1) {
        perror("Failed to write control byte");
        return -1;
    }

    // Read the analog value
    if (read(i2c_fd, &data, 1) != 1) {
        perror("Failed to read analog value");
        return -1;
    }

    return data;
}

int main() {
    // Register the signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Open the I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    // Specify the address of the slave device
    if (ioctl(i2c_fd, I2C_SLAVE, PCF8591_ADDR) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        close(i2c_fd);
        return 1;
    }

