#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <syslog.h>
#include <unistd.h>
#include <pigpio.h>
#include <math.h>

// Configuration
#define I2C_BUS 1
#define ADS1115_ADDR 0x48
#define ADS1115_REG_CONFIG 0x01
#define ADS1115_REG_CONVERT 0x00
#define ADS1115_CONFIG_REG 0x4303 // Single-ended AIN0, +/-4.096V, 128 SPS, Continuous
#define GPIO_SHUTDOWN 27
#define THRESHOLD_GAUSS 500.0
#define BUFFER_SIZE 10
#define SAMPLE_RATE_HZ 1
#define SAMPLE_PERIOD_US (1000000 / SAMPLE_RATE_HZ)

// Global variables
static int i2c_handle;
static volatile sig_atomic_t terminate = 0;

// Circular buffer structure
typedef struct {
    float buffer[BUFFER_SIZE];
    int head;
    int count;
} CircularBuffer;

// Function prototypes
int init_pigpio();
int init_i2c();
int read_ads1115(int16_t *raw_value);
float convert_to_gauss(int16_t raw_value);
void update_circular_buffer(CircularBuffer *cb, float value);
float calculate_rolling_average(CircularBuffer *cb);
void control_shutdown_gpio(float rolling_average);
void log_message(const char *message);
void signal_handler(int signal);
void cleanup();

// Initialize circular buffer
void init_circular_buffer(CircularBuffer *cb) {
    cb->head = 0;
    cb->count = 0;
}

// Initialize pigpio library
int init_pigpio() {
    if (gpioInitialise() < 0) {
        log_message("pigpio initialisation failed");
        return -1;
    }
    gpioSetMode(GPIO_SHUTDOWN, PI_OUTPUT);
    gpioWrite(GPIO_SHUTDOWN, PI_LOW);
    return 0;
}

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (i2c_handle < 0) {
        log_message("Failed to open I2C device");
        return -1;
    }
    return 0;
}

// Read raw ADC value from ADS1115
int read_ads1115(int16_t *raw_value) {
    char buf[2];
    if (i2cWriteByteData(i2c_handle, ADS1115_REG_CONFIG, ADS1115_CONFIG_REG) < 0) {
        log_message("Failed to write config to ADS1115");
        return -1;
    }
    gpioDelay(100); // Wait for conversion

    if (i2cReadI2CBlockData(i2c_handle, ADS1115_REG_CONVERT, buf, 2) != 2) {
        log_message("Failed to read data from ADS1115");
        return -1;
    }

    *raw_value = (int16_t)((buf[0] << 8) | buf[1]);
    return 0;
}

// Convert raw ADC value to magnetic field strength in Gauss
float convert_to_gauss(int16_t raw_value) {
    float voltage = (float)raw_value * 3.3 / 32768.0; // Assuming 12-bit ADC
    float gauss = (voltage - 2.5) / 0.0014; // Sensitivity is 1.4 mV/Gauss
    return gauss;
}

// Update circular buffer with new value
void update_circular_buffer(CircularBuffer *cb, float value) {
    cb->buffer[cb->head] = value;
    cb->head = (cb->head + 1) % BUFFER_SIZE;
    if (cb->count < BUFFER_SIZE) {
        cb->count++;
    }
}

// Calculate rolling average of the circular buffer
float calculate_rolling_average(CircularBuffer *cb) {
    if (cb->count == 0) {
        return 0.0;
    }
    float sum = 0.0;
    for (int i = 0; i < cb->count; i++) {
        sum += cb->buffer[i];
    }
    return sum / cb->count;
}

// Control GPIO for motor shutdown
void control_shutdown_gpio(float rolling_average) {
    if (rolling_average > THRESHOLD_GAUSS) {
        gpioWrite(GPIO_SHUTDOWN, PI_HIGH);
        log_message("Threshold exceeded, shutting down motor");
    } else {
        gpioWrite(GPIO_SHUTDOWN, PI_LOW);
    }
}

// Log messages to syslog
void log_message(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    syslog(LOG_INFO, "%s: %s", timestamp, message);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    log_message("Received signal, terminating...");
}

// Cleanup resources before exiting
void cleanup() {
    i2cClose(i2c_handle);
    gpioWrite(GPIO_SHUTDOWN, PI_LOW);
    gpioTerminate();
    closelog();
}

int main() {
    openlog("motor_shutdown", LOG_PID | LOG_CONS, LOG_USER);

    if (init_pigpio() != 0) {
        return 1;
    }

    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    CircularBuffer gauss_buffer;
    init_circular_buffer(&gauss_buffer);

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int16_t raw_value;
    float gauss;
    float rolling_average;

    while (!terminate) {
        if (read_ads1115(&raw_value) == 0) {
            gauss = convert_to_gauss(raw_value);
            update_circular_buffer(&gauss_buffer, gauss);
            rolling_average = calculate_rolling_average(&gauss_buffer);
            char log_message_buffer[100];
            snprintf(log_message_buffer, sizeof(log_message_buffer), "Raw: %d, Gauss: %.2f, Rolling Avg: %.2f", raw_value, gauss, rolling_average);
            log_message(log_message_buffer);
            control_shutdown_gpio(rolling_average);
        } else {
            log_message("Failed to read sensor data");
        }
        gpioDelay(SAMPLE_PERIOD_US);
    }

    cleanup();
    return 0;
}

