#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <stdint.h>

// Constants
#define I2C_BUS 1
#define ADS1115_ADDR 0x48
#define CONFIG_REG 0x01
#define CONVERSION_REG 0x00
#define LED_GPIO 17
#define THRESHOLD_DEFAULT 100.0
#define SAMPLE_RATE 10000 // 10 kHz
#define GAIN 4.096
#define ZERO_GAUSS_VOLTAGE 1.65

// Global variables
int i2c_handle;
double threshold = THRESHOLD_DEFAULT;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_pigpio();
int initialize_i2c();
int configure_ads1115();
int16_t read_ads1115();
double convert_to_gauss(int16_t adc_value);
void blink_led(int duration_ms);
void signal_handler(int signal);
void cleanup();

// Structure to hold configuration data
typedef struct {
    int i2c_bus;
    int ads1115_address;
    int led_gpio;
    double threshold;
} Config;

// Function to parse command-line arguments
int parse_arguments(int argc, char *argv[], Config *config) {
    for (int i = 1; i < argc; i++) {
        if (strcmp(argv[i], "-t") == 0 && i + 1 < argc) {
            config->threshold = atof(argv[i + 1]);
            i++; // Skip the value
        } else {
            fprintf(stderr, "Usage: %s [-t threshold]\n", argv[0]);
            return 1; // Indicate an error
        }
    }
    return 0; // Indicate success
}

int main(int argc, char *argv[]) {
    Config config = {I2C_BUS, ADS1115_ADDR, LED_GPIO, THRESHOLD_DEFAULT};

    if (parse_arguments(argc, argv, &config) != 0) {
        return 1;
    }
    threshold = config.threshold;

    // Initialize pigpio
    if (initialize_pigpio() != 0) {
        return 1;
    }

    // Initialize I2C
    if (initialize_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Configure ADS1115
    if (configure_ads1115() != 0) {
        cleanup();
        return 1;
    }

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        // Read ADC value
        int16_t adc_value = read_ads1115();

        // Convert to Gauss
        double gauss = convert_to_gauss(adc_value);

        // Print the magnetic field strength
        printf("Magnetic Field: %.2f Gauss\n", gauss);

        // Check if the threshold is exceeded
        if (gauss > threshold) {
            blink_led(1000); // Blink for 1 second
        }

        // Wait 100 ms
        gpioDelay(100000); // 100 ms = 100000 us
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

// Initialize pigpio
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }
    return 0;
}

// Initialize I2C
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        return 1;
    }
    return 0;
}

// Configure ADS1115
int configure_ads1115() {
    // Configuration register value for single-ended AIN0, 128 SPS, +/-4.096V, start single conversion
    uint16_t config_value = 0x4003; // Single-ended AIN0, 128 SPS, +/-4.096V, start single conversion

    // Write the configuration value to the configuration register
    char buf[3];
    buf[0] = CONFIG_REG;
    buf[1] = (config_value >> 8) & 0xFF; // MSB
    buf[2] = config_value & 0xFF;      // LSB

    int result = i2cWriteDevice(i2c_handle, buf, 3);
    if (result != 0) {
        fprintf(stderr, "Failed to write to I2C device: %d\n", result);
        return 1;
    }

    return 0;
}

// Read ADS1115
int16_t read_ads1115() {
    // Read the conversion register (2 bytes)
    char buf[2];
    int result = i2cReadDevice(i2c_handle, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Failed to read from I2C device: %d\n", result);
        return 0; // Return 0 on error
    }

    // Combine the two bytes into a 16-bit value
    int16_t adc_value = (buf[0] << 8) | buf[1];

    // Sign extend if necessary (ADS1115 is a 16-bit ADC)
    if (adc_value & 0x8000) {
        adc_value |= 0xFFFF0000; // Sign extend
    }

    return adc_value;
}

// Convert ADC value to Gauss
double convert_to_gauss(int16_t adc_value) {
    double voltage = (adc_value * GAIN) / 32768.0; // Assuming 16-bit ADC
    double gauss = (voltage - ZERO_GAUSS_VOLTAGE) / 0.001;
    return gauss;
}

// Blink LED
void blink_led(int duration_ms) {
    gpioSetMode(LED_GPIO, PI_OUTPUT);
    int on_off_cycles = duration_ms * 20; // 50ms on, 50ms off = 100ms cycle
    for (int i = 0; i < on_off_cycles; i++) {
        gpioWrite(LED_GPIO, 1); // Turn LED on
        gpioDelay(50000);       // Wait 50 ms
        gpioWrite(LED_GPIO, 0); // Turn LED off
        gpioDelay(50000);       // Wait 50 ms
    }
}

// Signal handler
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup function
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
}

