// Define GPIO pins for the vibration motors
#define MOTOR1_GPIO 17
#define MOTOR2_GPIO 27

// Define SPI parameters
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 0

// Define noise threshold
#define NOISE_THRESHOLD 500

// Define PWM frequency
#define PWM_FREQUENCY 100 // Hz

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
void control_motor(int gpio, int duty_cycle);
void log_event(int noise_level, int duty_cycle);
void signal_handler(int signal);

// Function to read data from MCP3008 ADC
int read_mcp3008(int channel) {
    unsigned char tx_buffer[3];
    unsigned char rx_buffer[3];

    // Construct SPI message
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = ((channel & 0x07) << 4) | 0x80; // Single-ended mode, channel select
    tx_buffer[2] = 0x00;

    // Transfer SPI data
    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    if (result != 0) {
        fprintf(stderr, "SPI transfer failed: %d\n", result);
        return -1; // Indicate error
    }

    // Extract ADC value
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
    return adc_value;
}

// Function to control the vibration motor using PWM
void control_motor(int gpio, int duty_cycle) {
    gpioPWM(gpio, duty_cycle);
}

// Function to log events to a file
void log_event(int noise_level, int duty_cycle) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s - Noise Level: %d, Duty Cycle: %d\n", timestamp, noise_level, duty_cycle);
    fflush(log_file); // Ensure data is written to file immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as outputs
    gpioSetMode(MOTOR1_GPIO, PI_OUTPUT);
    gpioSetMode(MOTOR2_GPIO, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(MOTOR1_GPIO, PWM_FREQUENCY);
    gpioSetPWMfrequency(MOTOR2_GPIO, PWM_FREQUENCY);

    // Open SPI device
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("vibration_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Vibration control system started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        // Read noise level from MCP3008
        int noise_level = read_mcp3008(0);
        if (noise_level < 0) {
            fprintf(stderr, "Failed to read noise level\n");
            gpioDelay(10); // Wait 10ms before retrying
            continue;
        }

        // Calculate duty cycle based on noise level
        int duty_cycle = 0;
        if (noise_level > NOISE_THRESHOLD) {
            duty_cycle = (noise_level - NOISE_THRESHOLD) * 255 / (1023 - NOISE_THRESHOLD);
            if (duty_cycle > 255) {
                duty_cycle = 255;
            }
        }

        // Control vibration motors
        control_motor(MOTOR1_GPIO, duty_cycle);
        control_motor(MOTOR2_GPIO, duty_cycle);

        // Log event
        log_event(noise_level, duty_cycle);

        // Wait 10 ms
        gpioDelay(10);
    }

    // Graceful shutdown
    printf("Stopping motors...\n");
    control_motor(MOTOR1_GPIO, 0);
    control_motor(MOTOR2_GPIO, 0);

    printf("Closing SPI device...\n");
    spiClose(spi_handle);

    printf("Closing log file...\n");
    fclose(log_file);

    printf("Terminating pigpio...\n");
    gpioTerminate();

    printf("Exiting.\n");
    return 0;
}

