            fprintf(stderr, "Error: Failed to set BH1750 mode (attempt %d)\n", retries + 1);
            retries++;
            gpioDelay(10000); // Wait 10ms before retrying
            continue;
        }

        gpioDelay(180000); // Wait 180ms for measurement

        if (i2cReadI2CBlockData(i2c_fd, 0x00, buf, 2) == 2) {
            light_level = (buf[0] << 8) | buf[1];
            return light_level;
        } else {
            fprintf(stderr, "Error: Failed to read BH1750 data (attempt %d)\n", retries + 1);
            retries++;
            gpioDelay(10000); // Wait 10ms before retrying
        }
    }

    fprintf(stderr, "Error: Failed to read BH1750 after %d retries\n", MAX_RETRIES);
    return -1;
}

// Function to log data to CSV file
void log_data(float sound_level_db, int light_level_lux, int error_code) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f,%d,%d\n", timestamp, sound_level_db, light_level_lux, error_code);
    fflush(log_file); // Ensure data is written to file immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_fd = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // CE0, 1MHz, Mode 0
    if (spi_fd < 0) {
        fprintf(stderr, "Error: SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Open I2C device
    i2c_fd = i2cOpen(1, BH1750_ADDR, 0); // Bus 1, address 0x23, no flags
    if (i2c_fd < 0) {
        fprintf(stderr, "Error: I2C open failed\n");
        spiClose(spi_fd);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("tamper_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file\n");
        i2cClose(i2c_fd);
        spiClose(spi_fd);
        gpioTerminate();
        return 1;
    }

    // Write header if the file is new
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "timestamp,sound_level_db,light_level_lux,error_code\n");
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        int adc_value = read_mcp3008(MCP3008_CHANNEL);
        float sound_level_db = 0.0;
        int light_level_lux = -1;
        int error_code = 0;

        if (adc_value < 0) {
            fprintf(stderr, "Error: Failed to read MCP3008\n");
            error_code = -1; // Indicate ADC read failure
        } else {
            sound_level_db = convert_to_db(adc_value);
        }

        light_level_lux = read_bh1750();
        if (light_level_lux < 0) {
            fprintf(stderr, "Error: Failed to read BH1750\n");
            error_code = -2; // Indicate BH1750 read failure
        }

        log_data(sound_level_db, light_level_lux, error_code);

        gpioDelay(SLEEP_DURATION * 1000000); // Sleep for 5 seconds
    }

    // Cleanup
    fclose(log_file);
    i2cClose(i2c_fd);
    spiClose(spi_fd);
    gpioTerminate();

    return 0;
}

