#define SPI_MODE 0

// Define PWM parameters
#define PWM_FREQUENCY 100 // Hz
#define PWM_RANGE 100

// Define log file name
#define LOG_FILE "irrigation.log"

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
float average_sensor_readings(int sensor1, int sensor2, int sensor3);
int map_moisture_to_duty_cycle(float average_moisture);
void log_data(int sensor1, int sensor2, int sensor3, float average_moisture, int duty_cycle);
void signal_handler(int signal);

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid ADC channel %d\n", channel);
        return -1; // Indicate error
    }

    unsigned char spi_tx_buf[3];
    unsigned char spi_rx_buf[3];

    // Construct SPI message (MCP3008 datasheet)
    spi_tx_buf[0] = 0x01; // Start bit
    spi_tx_buf[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    spi_tx_buf[2] = 0x00; // Don't care

    if (spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3) != 0) {
        fprintf(stderr, "Error: SPI transfer failed\n");
        return -1; // Indicate error
    }

    // Extract ADC value from response
    int adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];

    return adc_value;
}

// Function to average sensor readings
float average_sensor_readings(int sensor1, int sensor2, int sensor3) {
    int valid_readings = 0;
    int sum = 0;

    if (sensor1 != -1) {
        sum += sensor1;
        valid_readings++;
    }
    if (sensor2 != -1) {
        sum += sensor2;
        valid_readings++;
    }
    if (sensor3 != -1) {
        sum += sensor3;
        valid_readings++;
    }

    if (valid_readings > 0) {
        return (float)sum / valid_readings;
    } else {
        return -1.0; // Indicate error if all readings are invalid
    }
}

// Function to map moisture level to duty cycle
int map_moisture_to_duty_cycle(float average_moisture) {
    // Invert the moisture level and scale to 0-100
    float duty_cycle = 100.0 - ((average_moisture / 1023.0) * 100.0);

    // Clamp the duty cycle to the valid range
    if (duty_cycle < 0.0) {
        duty_cycle = 0.0;
    } else if (duty_cycle > 100.0) {
        duty_cycle = 100.0;
    }

    return (int)duty_cycle;
}

