    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set PWM frequency and range
    gpioSetPWMfrequency(VALVE_PIN, PWM_FREQUENCY);
    gpioSetPWMrange(VALVE_PIN, PWM_RANGE);

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Irrigation system started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        // Read sensor values
        int sensor1 = read_mcp3008(0);
        int sensor2 = read_mcp3008(1);
        int sensor3 = read_mcp3008(2);

        // Average sensor readings
        float average_moisture = average_sensor_readings(sensor1, sensor2, sensor3);

        if (average_moisture == -1.0) {
            fprintf(stderr, "Error: Failed to read sensor values\n");
        } else {
            // Map moisture to duty cycle
            int duty_cycle = map_moisture_to_duty_cycle(average_moisture);

            // Set valve position
            gpioPWM(VALVE_PIN, duty_cycle);

            // Log data
            log_data(sensor1, sensor2, sensor3, average_moisture, duty_cycle);
        }

        // Wait 5 seconds
        gpioDelay(5000000); // 5 seconds in microseconds
    }

    // Graceful shutdown
    gpioPWM(VALVE_PIN, 0); // Close the valve
    spiClose(spi_handle);
    fclose(log_file);
    gpioTerminate();

    printf("Irrigation system stopped.\n");

    return 0;
}

