#define SPI_DEVICE 0
#define SPI_SPEED 1000000 // 1 MHz

// Define PWM parameters
#define PWM_PERIOD 1000000 // 1 kHz

// Define frequency range
#define MIN_FREQUENCY 220
#define MAX_FREQUENCY 880

// Define distance range (in cm)
#define MIN_DISTANCE 20
#define MAX_DISTANCE 100

// Define LDR calibration values
#define MIN_LDR_VALUE 0
#define MAX_LDR_VALUE 1023

// Define PWM duty cycle range
#define MIN_DUTY_CYCLE 0
#define MAX_DUTY_CYCLE 1000000

// Define error value for distance reading
#define DISTANCE_ERROR -1

// Define timeout for distance reading (in seconds)
#define TIMEOUT_SEC 0.1

// Global variables
static volatile int running = 1;
static int pwm_fd = -1;
static int spi_fd = -1;
static FILE *config_file = NULL;

// Calibration data
static int trig_delay = 10; // Delay after triggering the sensor
static int echo_timeout = 20000; // Timeout for echo pulse (in microseconds)
static int ldr_calibration_value = 500; // Calibration value for LDR

// Function prototypes
int read_distance();
int read_ldr();
float map_distance_to_frequency(int distance);
int map_ldr_to_duty_cycle(int ldr_value);
void set_pwm_frequency(float frequency);
void set_pwm_duty_cycle(int duty_cycle);
void signal_handler(int sig);
int load_config();
int save_config();

// Function to read distance from HC-SR04 sensor
int read_distance() {
    long start_time, end_time, pulse_duration;
    int distance;

    // Trigger the sensor
    gpioWrite(TRIG_PIN, 1);
    gpioDelay(trig_delay);
    gpioWrite(TRIG_PIN, 0);

    // Measure the echo pulse duration
    start_time = gpioTick();
    while (gpioRead(ECHO_PIN) == 0) {
        if (gpioTick() - start_time > echo_timeout) {
            fprintf(stderr, "Error: Echo pulse timeout\n");
            return DISTANCE_ERROR;
        }
    }
    start_time = gpioTick();

    while (gpioRead(ECHO_PIN) == 1) {
        if (gpioTick() - start_time > echo_timeout) {
            fprintf(stderr, "Error: Echo pulse timeout\n");
            return DISTANCE_ERROR;
        }
    }
    end_time = gpioTick();

    pulse_duration = end_time - start_time;

    // Calculate distance in centimeters
    distance = pulse_duration / 58; // Speed of sound approximation

    return distance;
}

// Function to read LDR value from MCP3008 ADC
int read_ldr() {
    unsigned char spi_tx_buf[3];
    unsigned char spi_rx_buf[3];
    int ldr_value;

    // MCP3008 configuration: single-ended, channel 0
    spi_tx_buf[0] = 0x01; // Start bit
    spi_tx_buf[1] = 0x80; // Single-ended, channel 0 (10000000)
    spi_tx_buf[2] = 0x00; // Don't care

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), (unsigned long)spi_tx_buf) < 0) {
        perror("SPI transaction failed");
        return -1; // Indicate error
    }

    // Extract the ADC value from the response
    ldr_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];

    return ldr_value;
}

// Function to map distance to frequency
float map_distance_to_frequency(int distance) {
    if (distance < MIN_DISTANCE) {
        return MIN_FREQUENCY;
    } else if (distance > MAX_DISTANCE) {
        return MAX_FREQUENCY;
    } else {
        return MIN_FREQUENCY + (float)(distance - MIN_DISTANCE) * (MAX_FREQUENCY - MIN_FREQUENCY) / (MAX_DISTANCE - MIN_DISTANCE);
    }
}

// Function to map LDR value to PWM duty cycle
int map_ldr_to_duty_cycle(int ldr_value) {
    if (ldr_value < MIN_LDR_VALUE) {
        return MIN_DUTY_CYCLE;
    } else if (ldr_value > MAX_LDR_VALUE) {
        return MAX_DUTY_CYCLE;
    } else {
        return MIN_DUTY_CYCLE + (int)(ldr_value - MIN_LDR_VALUE) * (MAX_DUTY_CYCLE - MIN_DUTY_CYCLE) / (MAX_LDR_VALUE - MIN_LDR_VALUE);
    }
}

// Function to set PWM frequency
void set_pwm_frequency(float frequency) {
    int period_ns = (int)(1000000000.0 / frequency);
    char period_str[20];
    snprintf(period_str, sizeof(period_str), "%d", period_ns);

    int fd = open("/sys/class/pwm/pwmchip0/pwm0/period", O_WRONLY);
    if (fd < 0) {
        perror("Failed to open PWM period file");
        return;
    }
    if (write(fd, period_str, strlen(period_str)) < 0) {
        perror("Failed to write PWM period");
        close(fd);
        return;
    }
    close(fd);
}

// Function to set PWM duty cycle
void set_pwm_duty_cycle(int duty_cycle) {
    char duty_cycle_str[20];
