        return -1;
    }

    if (fscanf(config_file, "%d", &trig_delay) != 1) {
        fprintf(stderr, "Error reading trig_delay from config file\n");
        fclose(config_file);
        return -1;
    }
    if (fscanf(config_file, "%d", &echo_timeout) != 1) {
        fprintf(stderr, "Error reading echo_timeout from config file\n");
        fclose(config_file);
        return -1;
    }
    if (fscanf(config_file, "%d", &ldr_calibration_value) != 1) {
        fprintf(stderr, "Error reading ldr_calibration_value from config file\n");
