    fclose(config_file);
    return 0;
}

int main() {
    int distance, ldr_value, duty_cycle;
    float frequency;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
