    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(PWM_PIN, PI_OUTPUT);

    // Initialize PWM
    pwm_fd = open("/sys/class/pwm/pwmchip0/pwm0/enable", O_WRONLY);
    if (pwm_fd < 0) {
        perror("Failed to open PWM enable file");
        gpioTerminate();
        return 1;
    }
    char enable_str[] = "1";
    if (write(pwm_fd, enable_str, strlen(enable_str)) < 0) {
        perror("Failed to enable PWM");
        close(pwm_fd);
        gpioTerminate();
        return 1;
    }
    close(pwm_fd);

    // Initialize SPI
    char spi_device[] = "/dev/spidev0.0";
    spi_fd = open(spi_device, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        gpioTerminate();
        return 1;
    }

    // Configure SPI
    unsigned int mode = SPI_MODE_0;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("Failed to set SPI mode");
        close(spi_fd);
        gpioTerminate();
        return 1;
    }

    unsigned int speed = SPI_SPEED;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("Failed to set SPI speed");
        close(spi_fd);
        gpioTerminate();
        return 1;
    }

    // Load calibration data
    if (load_config() != 0) {
        fprintf(stderr, "Failed to load calibration data, using default values\n");
    }

    // Set up signal handler
    signal(SIGINT, signal_handler);

    // Main loop
    while (running) {
        // Read distance
        distance = read_distance();
        if (distance == DISTANCE_ERROR) {
            fprintf(stderr, "Error reading distance, using previous value\n");
        } else {
            printf("Distance: %d cm\n", distance);
        }

        // Read LDR value
        ldr_value = read_ldr();
        if (ldr_value == -1) {
            fprintf(stderr, "Error reading LDR value, using previous value\n");
        } else {
            printf("LDR value: %d\n", ldr_value);
        }

        // Map distance to frequency
        frequency = map_distance_to_frequency(distance);

        // Map LDR value to duty cycle
        duty_cycle = map_ldr_to_duty_cycle(ldr_value);

        // Set PWM frequency and duty cycle
        set_pwm_frequency(frequency);
        set_pwm_duty_cycle(duty_cycle);

        // Delay
        usleep(50000); // 50 ms
    }

    // Cleanup (should not reach here if signal handler works correctly)
    set_pwm_duty_cycle(0);
    close(spi_fd);
    close(pwm_fd);
    gpioTerminate();

    return 0;
}

