// Constants
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 0
#define FAN_GPIO 18
#define AQI_THRESHOLD 100
#define LOG_FILE "air_quality.log"
#define MAX_RETRIES 3
#define RETRY_DELAY 1 // seconds

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
float adc_to_aqi(int adc_value);
void control_fan(float aqi);
void log_data(float aqi);
void signal_handler(int signal);
int initialize_spi();

// Function to initialize SPI
int initialize_spi() {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "Error opening SPI: %d\n", spi_handle);
        return -1;
    }
    return 0;
}

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    unsigned char tx_buffer[3];
    unsigned char rx_buffer[3];
    int adc_value = -1;
    int retries = 0;

    // Construct SPI message
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | (channel << 4)); // Single-ended, channel select
    tx_buffer[2] = 0x00; // Don't care

    while (retries < MAX_RETRIES) {
        if (spiXfer(spi_handle, tx_buffer, rx_buffer, 3) == 3) {
            // Extract ADC value from response
            adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
            return adc_value;
        } else {
            fprintf(stderr, "SPI read failed (attempt %d/%d). Error code: %d\n", retries + 1, MAX_RETRIES, spi_handle);
            retries++;
            gpioDelay(RETRY_DELAY * 1000); // Delay in milliseconds
        }
    }

    fprintf(stderr, "SPI read failed after %d retries. Re-initializing SPI.\n", MAX_RETRIES);
    spiClose(spi_handle);
    if (initialize_spi() != 0) {
        fprintf(stderr, "Failed to re-initialize SPI. Exiting.\n");
        return -1; // Indicate failure
    }
    return -1; // Indicate failure after retries
}

