        float aqi = adc_to_aqi(adc_value);
        if (aqi < 0) {
            fprintf(stderr, "Failed to convert ADC to AQI. Skipping this iteration.\n");
            gpioDelay(5000); // Wait 5 seconds before next attempt
            continue;
        }

        // Control the fan
        control_fan(aqi);

        // Log the data
        log_data(aqi);

        // Wait 5 seconds
        gpioDelay(5000);
    }

    // Cleanup
    printf("Cleaning up...\n");
    gpioWrite(FAN_GPIO, 0); // Turn fan off
    spiClose(spi_handle);
    fclose(log_file);
    gpioTerminate();

    printf("Exiting.\n");
    return 0;
}

