#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <wiringPiSPI.h>
#include <math.h>

// Motor 1
#define MOTOR1_ENABLE 18
#define MOTOR1_DIR 23

// Motor 2
#define MOTOR2_ENABLE 24
#define MOTOR2_DIR 25

// SPI Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 0

// MCP3008 Channels
#define POT_1_CHANNEL 0
#define POT_2_CHANNEL 1

// GPIO Pins for MCP3008
#define MCP3008_CS 8 // CE0

// Speed Limits
#define MIN_SPEED 50
#define MAX_SPEED 255

// Motion Profile Parameters
#define ACCEL_TIME 2 // seconds
#define HOLD_TIME 2  // seconds
#define DECEL_TIME 2 // seconds
#define PAUSE_TIME 5  // seconds

// Global Variables
volatile sig_atomic_t program_running = 1;

// Function Prototypes
int read_mcp3008(int channel);
float map_pot_to_speed(int pot_value);
void set_motor_speed(int motor_enable_pin, int motor_dir_pin, int speed, int direction);
void move_motors(int motor1_enable_pin, int motor1_dir_pin, int motor2_enable_pin, int motor2_dir_pin, float speed_factor1, float speed_factor2);
void signal_handler(int signal);

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    unsigned char buffer[3];
    int adc_value = 0;

    buffer[0] = 0x01; // Start bit
    buffer[1] = ((channel & 0x07) << 4) | 0x80; // Single-ended mode, channel select
    buffer[2] = 0x00;

    digitalWrite(MCP3008_CS, LOW); // Select the MCP3008
    wiringPiSPIDataRW(SPI_CHANNEL, buffer, 3);
    digitalWrite(MCP3008_CS, HIGH); // Deselect the MCP3008

    adc_value = ((buffer[1] & 0x03) << 8) + buffer[2];

    return adc_value;
}

// Function to map potentiometer value to motor speed (logarithmic)
float map_pot_to_speed(int pot_value) {
    float speed_factor = (float)pot_value / 1023.0;
    speed_factor = log10(speed_factor + 1) / log10(2); // Map 0-1 to 0-1 logarithmically
    return speed_factor;
}

// Function to set motor speed and direction
void set_motor_speed(int motor_enable_pin, int motor_dir_pin, int speed, int direction) {
    if (direction == 1) { // Forward
        gpioWrite(motor_dir_pin, 1);
    } else { // Backward
        gpioWrite(motor_dir_pin, 0);
    }

    if (speed >= MIN_SPEED && speed <= MAX_SPEED) {
        gpioPWM(motor_enable_pin, speed);
    } else {
        fprintf(stderr, "Error: Speed value out of range (%d). Setting to 0.\n", speed);
        gpioPWM(motor_enable_pin, 0);
    }
}

// Function to move motors according to the motion profile
void move_motors(int motor1_enable_pin, int motor1_dir_pin, int motor2_enable_pin, int motor2_dir_pin, float speed_factor1, float speed_factor2) {
    int min_speed = MIN_SPEED;
    int max_speed = MAX_SPEED;
    int accel_time = ACCEL_TIME;
    int hold_time = HOLD_TIME;
    int decel_time = DECEL_TIME;
    int pause_time = PAUSE_TIME;

    // Accelerate
    for (int i = 0; i <= accel_time * 1000; i += 10) { // 10ms steps
        if (!program_running) return;
        int speed = (int)(((float)i / (accel_time * 1000)) * (max_speed - min_speed) + min_speed);
        set_motor_speed(motor1_enable_pin, motor1_dir_pin, speed * speed_factor1, 1); // Forward
        set_motor_speed(motor2_enable_pin, motor2_dir_pin, speed * speed_factor2, 0); // Backward
        gpioDelay(10);
    }

    // Hold
    for (int i = 0; i <= hold_time * 1000; i += 10) { // 10ms steps
        if (!program_running) return;
        set_motor_speed(motor1_enable_pin, motor1_dir_pin, max_speed * speed_factor1, 1); // Forward
        set_motor_speed(motor2_enable_pin, motor2_dir_pin, max_speed * speed_factor2, 0); // Backward
        gpioDelay(10);
    }

    // Decelerate
    for (int i = 0; i <= decel_time * 1000; i += 10) { // 10ms steps
        if (!program_running) return;
        int speed = max_speed - (int)(((float)i / (decel_time * 1000)) * (max_speed - min_speed));
        set_motor_speed(motor1_enable_pin, motor1_dir_pin, speed * speed_factor1, 1); // Forward
        set_motor_speed(motor2_enable_pin, motor2_dir_pin, speed * speed_factor2, 0); // Backward
        gpioDelay(10);
    }

    // Pause
    for (int i = 0; i <= pause_time * 1000; i += 10) { // 10ms steps
        if (!program_running) return;
        set_motor_speed(motor1_enable_pin, motor1_dir_pin, 0, 1); // Stop
        set_motor_speed(motor2_enable_pin, motor2_dir_pin, 0, 0); // Stop
        gpioDelay(10);
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully.\n", signal);
    program_running = 0;

    // Stop motors
    gpioPWM(MOTOR1_ENABLE, 0);
    gpioPWM(MOTOR2_ENABLE, 0);

    // Release GPIO resources
    gpioTerminate();

    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(MOTOR1_ENABLE, PI_OUTPUT);
    gpioSetMode(MOTOR1_DIR, PI_OUTPUT);
    gpioSetMode(MOTOR2_ENABLE, PI_OUTPUT);
    gpioSetMode(MOTOR2_DIR, PI_OUTPUT);
    gpioSetMode(MCP3008_CS, PI_OUTPUT);

    // Initialize SPI
    if (wiringPiSPISetup(SPI_CHANNEL, SPI_SPEED) == -1) {
        fprintf(stderr, "SPI initialisation failed\n");
        gpioTerminate();
        return 1;
    }

    // Set CS pin high initially
    digitalWrite(MCP3008_CS, HIGH);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Motor control program started. Press Ctrl+C to exit.\n");

    while (program_running) {
        // Read potentiometer values
        int pot_value1 = read_mcp3008(POT_1_CHANNEL);
        int pot_value2 = read_mcp3008(POT_2_CHANNEL);

        // Map potentiometer values to speed factors
        float speed_factor1 = map_pot_to_speed(pot_value1);
        float speed_factor2 = map_pot_to_speed(pot_value2);

        // Move motors
        move_motors(MOTOR1_ENABLE, MOTOR1_DIR, MOTOR2_ENABLE, MOTOR2_DIR, speed_factor1, speed_factor2);

        // Small delay to prevent busy-waiting
        gpioDelay(100); // 100ms
    }

    // Cleanup (should not reach here if signal handler works correctly)
    gpioPWM(MOTOR1_ENABLE, 0);
    gpioPWM(MOTOR2_ENABLE, 0);
    gpioTerminate();

    return 0;
}

