#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define LED_PIN 17
#define SPI_CS_PIN 8

// Define SPI parameters
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz

// Define calibration duration
#define CALIBRATION_DURATION 5 // seconds

// Define noise threshold
#define NOISE_THRESHOLD 1.10 // 10% above average

// Define debounce duration
#define DEBOUNCE_DURATION 10 // milliseconds

// Global variables
static volatile int running = 1;
static int spi_handle;
static int ambient_level = 0;
static int led_state = 0; // 0 = off, 1 = on
static unsigned long last_led_toggle = 0;

// Function prototypes
int initialize_gpio();
int initialize_spi();
int read_mcp3008(int channel);
int calibrate_ambient_level();
void control_led(int state);
void signal_handler(int signal);

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(LED_PIN, PI_OUTPUT);
    gpioSetMode(SPI_CS_PIN, PI_OUTPUT);

    return 0;
}

// Function to initialize SPI communication
int initialize_spi() {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI initialisation failed\n");
        return -1;
    }
    return 0;
}

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel\n");
        return -1;
    }

    unsigned char spi_data[3];
    spi_data[0] = 0x01; // Start bit
    spi_data[1] = ((channel & 0x07) << 4) | 0x80; // Single-ended mode, channel select
    spi_data[2] = 0x00;

    gpioWrite(SPI_CS_PIN, 0); // Select the MCP3008
    int result = spiXfer(spi_handle, spi_data, spi_data, 3);
    gpioWrite(SPI_CS_PIN, 1); // Deselect the MCP3008

    if (result != 3) {
        fprintf(stderr, "SPI transfer failed\n");
        return -1;
    }

    int adc_value = ((spi_data[1] & 0x03) << 8) + spi_data[2];
    return adc_value;
}

// Function to calibrate the ambient noise level
int calibrate_ambient_level() {
    long sum = 0;
    int num_samples = 100; // Number of samples for calibration

    printf("Calibrating ambient level for %d seconds...\n", CALIBRATION_DURATION);
    for (int i = 0; i < num_samples; ++i) {
        int adc_value = read_mcp3008(0);
        if (adc_value < 0) {
            fprintf(stderr, "Error reading ADC during calibration\n");
            return -1;
        }
        sum += adc_value;
        gpioDelay(10); // Small delay between samples
    }

    ambient_level = sum / num_samples;
    printf("Ambient level: %d\n", ambient_level);
    return 0;
}

// Function to control the LED
void control_led(int state) {
    unsigned long now = gpioTick();

    if (state != led_state) {
        if (now - last_led_toggle > DEBOUNCE_DURATION * 1000) {
            gpioWrite(LED_PIN, state);
            led_state = state;
            last_led_toggle = now;
        }
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    running = 0;
    control_led(0); // Turn off LED
    spiClose(spi_handle); // Close SPI
    gpioTerminate(); // Terminate pigpio
    exit(0);
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Initialize SPI
    if (initialize_spi() != 0) {
        gpioTerminate();
        return 1;
    }

    // Calibrate ambient level
    if (calibrate_ambient_level() != 0) {
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    printf("Monitoring sound levels...\n");

    // Main loop
    while (running) {
        int adc_value = read_mcp3008(0);
        if (adc_value < 0) {
            fprintf(stderr, "Error reading ADC, retrying...\n");
            gpioDelay(100); // Wait before retrying
            continue;
        }

        double noise_level = (double)adc_value / 1023.0;
        double threshold = ambient_level * NOISE_THRESHOLD;

        if (noise_level > threshold) {
            control_led(1); // Turn on LED
        } else {
            control_led(0); // Turn off LED
        }

        gpioDelay(1); // Small delay to avoid busy-waiting
    }

    return 0;
}

