#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>
#include <time.h>
#include <signal.h>
#include <errno.h>

// Configuration
#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE SPI_MODE_0
#define SPI_BITS_PER_WORD 8
#define SPI_SPEED 1000000 // 1 MHz
#define ADC_CHANNEL 0
#define GPIO_CHIP "gpiochip0"
#define GPIO_LINE 8
#define SAMPLE_RATE 1000 // Hz
#define SAMPLE_PERIOD_NS (1000000000 / SAMPLE_RATE)
#define LOG_FILE "audio_log.txt"

// Global variables
static int spi_fd = -1;
static struct gpiod_chip *gpio_chip = NULL;
static struct gpiod_line *gpio_line_line = NULL;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int spi_open(const char *device);
int spi_configure(int fd, uint8_t mode, uint8_t bits, uint32_t speed);
int spi_transfer(int fd, uint8_t *tx_buf, uint8_t *rx_buf, size_t len);
int gpio_request(struct gpiod_chip *chip, const char *line_name, const char *consumer);
int gpio_set_value(struct gpiod_line *line, int value);
int gpio_line_request(struct gpiod_chip *chip, const char *line_name, int request_type, const char *consumer);
int gpio_line_release(struct gpiod_line *line);
int read_adc(int spi_fd, int channel);
int log_data(FILE *fp, uint64_t timestamp_ns, int adc_value);
void signal_handler(int sig);

// SPI open function
int spi_open(const char *device) {
    int fd = open(device, O_RDWR);
    if (fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }
    return fd;
}

// SPI configure function
int spi_configure(int fd, uint8_t mode, uint8_t bits, uint32_t speed) {
    uint8_t mode_val = 0;
    switch (mode) {
        case SPI_MODE_0:
            mode_val = 0;
            break;
        case SPI_MODE_1:
            mode_val = 1;
            break;
        case SPI_MODE_2:
            mode_val = 2;
            break;
        case SPI_MODE_3:
            mode_val = 3;
            break;
        default:
            fprintf(stderr, "Invalid SPI mode\n");
            return -1;
    }

    if (ioctl(fd, SPI_IOC_WR_MODE, &mode_val) < 0) {
        perror("Error setting SPI mode");
        return -1;
    }

    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        perror("Error setting SPI bits per word");
        return -1;
    }

    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("Error setting SPI max speed");
        return -1;
    }

    return 0;
}

// SPI transfer function
int spi_transfer(int fd, uint8_t *tx_buf, uint8_t *rx_buf, size_t len) {
    struct spi_ioc_transfer transfer = {
        .tx_buf = (unsigned long)tx_buf,
        .rx_buf = (unsigned long)rx_buf,
        .len = len,
        .delay_usecs = 0,
        .speed_hz = SPI_SPEED,
        .bits_per_word = SPI_BITS_PER_WORD,
    };

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &transfer) < 0) {
        perror("Error during SPI transfer");
        return -1;
    }

    return 0;
}

// GPIO request function
int gpio_request(struct gpiod_chip *chip, const char *line_name, const char *consumer) {
    struct gpiod_line *line = gpiod_chip_get_line(chip, line_name);
    if (!line) {
        fprintf(stderr, "Error getting GPIO line %s\n", line_name);
        return -1;
    }

    if (gpiod_line_request(line, consumer, GPIOD_LINE_REQUEST_DIRECTION_OUTPUT)) {
        fprintf(stderr, "Error requesting GPIO line %s\n", line_name);
        return -1;
    }

    return 0;
}

// GPIO set value function
int gpio_set_value(struct gpiod_line *line, int value) {
    if (gpiod_line_set_value(line, value)) {
        fprintf(stderr, "Error setting GPIO value\n");
        return -1;
    }
    return 0;
}

// GPIO line request function
int gpio_line_request(struct gpiod_chip *chip, const char *line_name, int request_type, const char *consumer) {
    struct gpiod_line *line = gpiod_chip_get_line(chip, line_name);
    if (!line) {
        fprintf(stderr, "Error getting GPIO line %s\n", line_name);
        return -1;
    }

    if (gpiod_line_request(line, consumer, request_type)) {
        fprintf(stderr, "Error requesting GPIO line %s\n", line_name);
        return -1;
    }

    return 0;
}

// GPIO line release function
int gpio_line_release(struct gpiod_line *line) {
    if (gpiod_line_release(line)) {
        fprintf(stderr, "Error releasing GPIO line\n");
        return -1;
    }
    return 0;
}

// Read ADC function
int read_adc(int spi_fd, int channel) {
    uint8_t tx_buf[3];
    uint8_t rx_buf[3];

    // MCP3008 command: start bit (0x01), single-ended channel (0x08 | channel) << 4, dummy byte (0x00)
    tx_buf[0] = 0x01;
    tx_buf[1] = (0x08 | channel) << 4;
    tx_buf[2] = 0x00;

    if (spi_transfer(spi_fd, tx_buf, rx_buf, 3) < 0) {
        fprintf(stderr, "Error during SPI transfer\n");
        return -1;
    }

    // Extract the 10-bit ADC value from the response
    int adc_value = ((rx_buf[1] & 0x03) << 8) | rx_buf[2];
    return adc_value;
}

// Log data function
int log_data(FILE *fp, uint64_t timestamp_ns, int adc_value) {
    if (fprintf(fp, "%lu|%d\n", timestamp_ns, adc_value) < 0) {
        perror("Error writing to log file");
        return -1;
    }
    return 0;
}

// Signal handler function
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open SPI device
    spi_fd = spi_open(SPI_DEVICE);
    if (spi_fd < 0) {
        return EXIT_FAILURE;
    }

    // Configure SPI
    if (spi_configure(spi_fd, SPI_MODE, SPI_BITS_PER_WORD, SPI_SPEED) < 0) {
        close(spi_fd);
        return EXIT_FAILURE;
    }

    // Open GPIO chip
    gpio_chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!gpio_chip) {
        perror("Error opening GPIO chip");
        close(spi_fd);
        return EXIT_FAILURE;
    }

    // Request GPIO line
    if (gpio_request(gpio_chip, "gpio8", "audio_logger") < 0) {
        gpiod_chip_close(gpio_chip);
        close(spi_fd);
        return EXIT_FAILURE;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Error opening log file");
        gpio_line_release(gpio_line_line);
        gpiod_chip_close(gpio_chip);
        close(spi_fd);
        return EXIT_FAILURE;
    }

    // Main loop
    struct timespec sleep_time;
    sleep_time.tv_sec = 0;
    sleep_time.tv_nsec = SAMPLE_PERIOD_NS;

    struct timespec start_time, current_time;
    clock_gettime(CLOCK_MONOTONIC_RAW, &start_time);

    while (!terminate) {
        // Read ADC value
        int adc_value = read_adc(spi_fd, ADC_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Error reading ADC value\n");
            break;
        }

        // Get timestamp
        clock_gettime(CLOCK_MONOTONIC_RAW, &current_time);
        uint64_t timestamp_ns = (uint64_t)(current_time.tv_sec - start_time.tv_sec) * 1000000000 + (uint64_t)(current_time.tv_nsec - start_time.tv_nsec);

        // Log data
        if (log_data(log_file, timestamp_ns, adc_value) < 0) {
            fprintf(stderr, "Error logging data\n");
            break;
        }

        // Flush log file
        fflush(log_file);

        // Sleep until next sample
        nanosleep(&sleep_time, NULL);
    }

    // Cleanup
    printf("Cleaning up...\n");
    if (log_file) {
        fclose(log_file);
    }
    if (gpio_line_line) {
        gpio_line_release(gpio_line_line);
    }
    if (gpio_chip) {
        gpiod_chip_close(gpio_chip);
    }
    if (spi_fd >= 0) {
        close(spi_fd);
    }

    return EXIT_SUCCESS;
}

