#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <time.h>

// Define GPIO pins for MCP3008
#define MCP3008_CS 8
#define MCP3008_MOSI 10
#define MCP3008_MISO 9
#define MCP3008_SCLK 11

// Define SPI channel
#define SPI_CHANNEL 0

// Define SPI baud rate
#define SPI_BAUD 1000000 // 1 MHz

// Define ADXL335 sensitivity and zero-g bias
#define ADXL335_SENSITIVITY 0.3 // 300 mV/g
#define ADXL335_ZERO_G_BIAS 1.5 // 1.5V

// Define MCP3008 reference voltage
#define MCP3008_VREF 3.3

// Define Kalman filter parameters
#define PROCESS_NOISE 0.01
#define MEASUREMENT_NOISE 0.1

// Global variables
int spi_handle;
volatile sig_atomic_t terminate = 0;

// Kalman filter state
typedef struct {
    double x;
    double P;
} KalmanState;

KalmanState kalman_x, kalman_y, kalman_z;

// Function prototypes
int initialize_gpio();
int initialize_spi();
int read_mcp3008(int channel);
double adc_to_voltage(int adc_value);
double voltage_to_g(double voltage);
double kalman_filter_update(KalmanState *state, double measurement);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(MCP3008_CS, PI_OUTPUT);
    gpioSetMode(MCP3008_MOSI, PI_OUTPUT);
    gpioSetMode(MCP3008_MISO, PI_INPUT);
    gpioSetMode(MCP3008_SCLK, PI_OUTPUT);

    return 0;
}

// Initialize SPI communication
int initialize_spi() {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI initialisation failed: %d\n", spi_handle);
        return 1;
    }
    return 0;
}

// Read data from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    unsigned char spi_data[3];
    spi_data[0] = 0x01; // Start bit
    spi_data[1] = ((channel & 0x07) << 4) | 0x80; // Single-ended mode, channel select
    spi_data[2] = 0x00;

    gpioWrite(MCP3008_CS, 0); // Select MCP3008
    spiWrite(spi_handle, (char *)spi_data, 3);
    spiRead(spi_handle, (char *)spi_data, 3);
    gpioWrite(MCP3008_CS, 1); // Deselect MCP3008

    int adc_value = ((spi_data[1] & 0x03) << 8) + spi_data[2];
    return adc_value;
}

// Convert ADC value to voltage
double adc_to_voltage(int adc_value) {
    return ((double)adc_value / 1023.0) * MCP3008_VREF;
}

// Convert voltage to acceleration in g
double voltage_to_g(double voltage) {
    return (voltage - ADXL335_ZERO_G_BIAS) / ADXL335_SENSITIVITY;
}

// Kalman filter update function
double kalman_filter_update(KalmanState *state, double measurement) {
    // Prediction step
    state->x = state->x; // No process model, just hold the state
    state->P = state->P + PROCESS_NOISE;

    // Update step
    double K = state->P / (state->P + MEASUREMENT_NOISE);
    state->x = state->x + K * (measurement - state->x);
    state->P = (1 - K) * state->P;

    return state->x;
}

int main() {
    // Initialize signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Initialize SPI
    if (initialize_spi() != 0) {
        gpioTerminate();
        return 1;
    }

    // Initialize Kalman filter states
    kalman_x.x = 0.0;
    kalman_x.P = 1.0;
    kalman_y.x = 0.0;
    kalman_y.P = 1.0;
    kalman_z.x = 0.0;
    kalman_z.P = 1.0;

    // Main loop
    while (!terminate) {
        // Read ADC values
        int adc_x = read_mcp3008(0);
        int adc_y = read_mcp3008(1);
        int adc_z = read_mcp3008(2);

        if (adc_x == -1 || adc_y == -1 || adc_z == -1) {
            fprintf(stderr, "Error reading ADC values\n");
            continue; // Skip to the next iteration
        }

        // Convert ADC values to voltages
        double voltage_x = adc_to_voltage(adc_x);
        double voltage_y = adc_to_voltage(adc_y);
        double voltage_z = adc_to_voltage(adc_z);

        // Convert voltages to acceleration in g
        double acceleration_x = voltage_to_g(voltage_x);
        double acceleration_y = voltage_to_g(voltage_y);
        double acceleration_z = voltage_to_g(voltage_z);

        // Apply Kalman filter
        double filtered_acceleration_x = kalman_filter_update(&kalman_x, acceleration_x);
        double filtered_acceleration_y = kalman_filter_update(&kalman_y, acceleration_y);
        double filtered_acceleration_z = kalman_filter_update(&kalman_z, acceleration_z);

        // Print filtered acceleration values
        printf("X: %.3f g, Y: %.3f g, Z: %.3f g\n", filtered_acceleration_x, filtered_acceleration_y, filtered_acceleration_z);

        // Delay for 10 Hz sampling rate
        gpioDelay(100); // 100 ms
    }

    // Close SPI connection
    spiClose(spi_handle);

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

