#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <time.h>
#include <signal.h>
#include <errno.h>

// Configuration
#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE SPI_MODE_0
#define SPI_BITS_PER_WORD 8
#define SPI_SPEED 1000000 // 1 MHz
#define CSV_FILE "sensor_data.csv"
#define NUM_CHANNELS 3
#define SLEEP_SECONDS 1

// Global variables
int spi_fd = -1;
FILE *csv_file = NULL;
volatile sig_atomic_t terminate = 0;

// Structure to hold SPI configuration
typedef struct {
    int fd;
    unsigned char mode;
    unsigned char bits_per_word;
    unsigned int speed;
} spi_config_t;

// Function prototypes
int spi_init(spi_config_t *config);
int read_mcp3008(int channel);
int log_data(int channel0_value, int channel1_value, int channel2_value);
void signal_handler(int sig);

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating...\n", sig);
}

// Initialize SPI interface
int spi_init(spi_config_t *config) {
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        fprintf(stderr, "Error opening SPI device: %s\n", strerror(errno));
        return -1;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &config->mode) == -1) {
        fprintf(stderr, "Error setting SPI mode: %s\n", strerror(errno));
        close(spi_fd);
        return -1;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &config->bits_per_word) == -1) {
        fprintf(stderr, "Error setting SPI bits per word: %s\n", strerror(errno));
        close(spi_fd);
        return -1;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &config->speed) == -1) {
        fprintf(stderr, "Error setting SPI speed: %s\n", strerror(errno));
        close(spi_fd);
        return -1;
    }

    return 0;
}

// Read ADC value from MCP3008 channel
int read_mcp3008(int channel) {
    unsigned char tx_buf[3];
    unsigned char rx_buf[3];
    struct spi_ioc_transfer transfer[1];

    // Construct SPI message
    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = 0x80 | (channel << 4); // Single-ended mode + channel select
    tx_buf[2] = 0x00; // Dummy byte

    memset(transfer, 0, sizeof(transfer));
    transfer[0].tx_buf = (unsigned long)tx_buf;
    transfer[0].rx_buf = (unsigned long)rx_buf;
    transfer[0].len = 3;
    transfer[0].speed_hz = SPI_SPEED;
    transfer[0].bits_per_word = SPI_BITS_PER_WORD;
    transfer[0].delay_usecs = 0; // No delay
    transfer[0].cs_change = 0; // No chip select change

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), transfer) < 1) {
        fprintf(stderr, "Error sending SPI message: %s\n", strerror(errno));
        return -1;
    }

    // Extract ADC value
    int adc_value = ((rx_buf[1] & 0x03) << 8) | rx_buf[2];
    return adc_value;
}

// Log data to CSV file
int log_data(int channel0_value, int channel1_value, int channel2_value) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(csv_file, "%s,%d,%d,%d\n", timestamp, channel0_value, channel1_value, channel2_value);
    fflush(csv_file); // Ensure data is written to disk immediately

    return 0;
}

int main() {
    spi_config_t spi_config = {
        .fd = -1, // Initialize to -1 to indicate not yet opened
        .mode = SPI_MODE,
        .bits_per_word = SPI_BITS_PER_WORD,
        .speed = SPI_SPEED
    };

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize SPI
    if (spi_init(&spi_config) != 0) {
        fprintf(stderr, "SPI initialization failed. Exiting.\n");
        return 1;
    }

    // Open CSV file for writing
    csv_file = fopen(CSV_FILE, "a");
    if (csv_file == NULL) {
        fprintf(stderr, "Error opening CSV file: %s\n", strerror(errno));
        close(spi_fd);
        return 1;
    }

    // Write header if the file is newly created
    fseek(csv_file, 0, SEEK_END);
    long file_size = ftell(csv_file);
    if (file_size == 0) {
        fprintf(csv_file, "Timestamp,Channel0,Channel1,Channel2\n");
    }

    // Main loop
    while (!terminate) {
        int channel0_value = read_mcp3008(0);
        int channel1_value = read_mcp3008(1);
        int channel2_value = read_mcp3008(2);

        if (channel0_value == -1 || channel1_value == -1 || channel2_value == -1) {
            fprintf(stderr, "Error reading ADC values. Skipping logging.\n");
        } else {
            log_data(channel0_value, channel1_value, channel2_value);
        }

        sleep(SLEEP_SECONDS);
    }

    // Cleanup
    close(spi_fd);
    fclose(csv_file);

    return 0;
}

