#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <time.h>
#include <unistd.h>
#include <mosquitto.h>
#include <pigpio.h>
#include <cjson/cJSON.h>

#define MQTT_BROKER "mqtt.eclipseprojects.io"
#define MQTT_PORT 1883
#define MQTT_TOPIC "home/led_control"
#define MQTT_CLIENT_ID "rpi_led_control"
#define GPIO_PIN 17
#define MAX_RECONNECT_DELAY 60

// Global variables
static struct mosquitto *mosq = NULL;
static volatile int running = 1;

// Function prototypes
void signal_handler(int signum);
int mqtt_connect_with_retry(struct mosquitto **mosq, const char *host, int port, const char *client_id);
int mqtt_subscribe(struct mosquitto *mosq, const char *topic, int qos);
int mqtt_message_callback(struct mosquitto *mosq, void *userdata, const struct mosquitto_message *message);
int parse_json_payload(const char *payload, int *led_state);
void set_led_state(int led_state);
void log_error(const char *message);

// Signal handler for graceful shutdown
void signal_handler(int signum) {
    running = 0;
    printf("Signal received, exiting...\n");
}

// MQTT connect with exponential backoff retry
int mqtt_connect_with_retry(struct mosquitto **mosq, const char *host, int port, const char *client_id) {
    int rc = 0;
    int delay = 1;
    int max_delay = MAX_RECONNECT_DELAY;

    while (running && delay <= max_delay) {
        mosquitto_lib_init();
        *mosq = mosquitto_new(client_id, true, NULL);
        if (*mosq == NULL) {
            log_error("Failed to create mosquitto instance.");
            break;
        }

        rc = mosquitto_connect(*mosq, host, port, 60);
        if (rc == MOSQ_ERR_SUCCESS) {
            printf("Connected to MQTT broker.\n");
            return 0; // Success
        } else {
            log_error("Failed to connect to MQTT broker. Retrying in ");
            fprintf(stderr, "%d seconds\n", delay);
            fflush(stderr);
            sleep(delay);
            delay *= 2;
            if (delay > max_delay) {
                delay = max_delay;
            }
            mosquitto_destroy(*mosq);
            *mosq = NULL;
        }
    }

    log_error("Failed to connect to MQTT broker after multiple retries.");
    return -1; // Failure
}

// MQTT subscribe function
int mqtt_subscribe(struct mosquitto *mosq, const char *topic, int qos) {
    int rc = mosquitto_subscribe(mosq, NULL, topic, qos);
    if (rc != MOSQ_ERR_SUCCESS) {
        log_error("Failed to subscribe to topic.");
        return -1;
    }
    printf("Subscribed to topic %s with QoS %d.\n", topic, qos);
    return 0;
}

// MQTT message callback function
int mqtt_message_callback(struct mosquitto *mosq, void *userdata, const struct mosquitto_message *message) {
    if (message->payloadlen) {
        printf("Received message on topic %s: %s\n", message->topic, (char *)message->payload);
        int led_state;
        if (parse_json_payload((char *)message->payload, &led_state) == 0) {
            set_led_state(led_state);
        } else {
            log_error("Failed to parse JSON payload.");
        }
    } else {
        printf("Received empty message on topic %s\n", message->topic);
    }
    return 0;
}

// JSON parsing function
int parse_json_payload(const char *payload, int *led_state) {
    cJSON *json = cJSON_Parse(payload);
    if (json == NULL) {
        const char *error_ptr = cJSON_GetErrorPtr();
        if (error_ptr != NULL) {
            fprintf(stderr, "Error before: %s\n", error_ptr);
        }
        return -1;
    }

    cJSON *led_state_json = cJSON_GetObjectItemCaseSensitive(json, "led_state");
    if (cJSON_IsBool(led_state_json)) {
        *led_state = cJSON_GetBool(led_state_json);
        cJSON_Delete(json);
        return 0;
    } else {
        log_error("Invalid or missing 'led_state' key in JSON payload.");
        cJSON_Delete(json);
        return -1;
    }
}

// LED control function
void set_led_state(int led_state) {
    gpioWrite(GPIO_PIN, led_state);
    printf("LED set to %s\n", led_state ? "ON" : "OFF");
}

// Error logging function
void log_error(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    fprintf(stderr, "[%d-%02d-%02d %02d:%02d:%02d] ERROR: %s\n",
            t->tm_year + 1900, t->tm_mon + 1, t->tm_mday, t->tm_hour, t->tm_min, t->tm_sec, message);
    fflush(stderr);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        log_error("pigpio initialisation failed");
        return 1;
    }

    // Set GPIO17 as output and turn off LED initially
    gpioSetMode(GPIO_PIN, PI_OUTPUT);
    set_led_state(0);

    // Initialize MQTT
    mosquitto_lib_init();
    mosq = mosquitto_new(MQTT_CLIENT_ID, true, NULL);
    if (!mosq) {
        log_error("Failed to create mosquitto instance.");
        gpioTerminate();
        return 1;
    }

    // Set MQTT callbacks
    mosquitto_message_callback_set(mosq, mqtt_message_callback);
    mosquitto_disconnect_callback_set(mosq, NULL); // Optional
    mosquitto_connect_callback_set(mosq, NULL); // Optional

    // Connect to MQTT broker with retry
    if (mqtt_connect_with_retry(&mosq, MQTT_BROKER, MQTT_PORT, MQTT_CLIENT_ID) != 0) {
        gpioTerminate();
        return 1;
    }

    // Subscribe to MQTT topic
    if (mqtt_subscribe(mosq, MQTT_TOPIC, 0) != 0) {
        mosquitto_destroy(mosq);
        mosquitto_lib_cleanup();
        gpioTerminate();
        return 1;
    }

    // Start MQTT loop
    mosquitto_loop_start(mosq);

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (running) {
        sleep(1);
    }

    // Clean up
    mosquitto_loop_stop(mosq, false);
    mosquitto_disconnect(mosq);
    mosquitto_destroy(mosq);
    mosquitto_lib_cleanup();
    set_led_state(0);
    gpioTerminate();

    printf("Exiting cleanly.\n");
    return 0;
}

