#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// Define GPIO pins
#define SOUND_SENSOR_PIN 17
#define LED_PIN 18

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT and SIGTERM
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to read the sound sensor
int read_sound_sensor() {
    return gpioRead(SOUND_SENSOR_PIN);
}

// Function to control the LED
void control_led(int state) {
    gpioWrite(LED_PIN, state);
}

// Function to blink the LED for 1 second
