#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <gpiod.h>
#include <unistd.h>

#define GPIO_CHIP_PATH "/dev/gpiochip0"
#define GPIO_LINE 17
#define LOG_FILE "/var/log/vibration_shutdown.log"

static volatile sig_atomic_t keep_running = 1;
static struct gpiod_chip *gpio_chip = NULL;
static struct gpiod_line *gpio_line_line = NULL;
static struct gpiod_line_event *event = NULL;

void signal_handler(int sig) {
    keep_running = 0;
    fprintf(stderr, "\nCaught signal %d, exiting gracefully.\n", sig);
}

int main() {
    FILE *log_file = NULL;
    int ret;
    struct timespec ts;
    char timestamp[30];

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open GPIO chip
    gpio_chip = gpiod_chip_open(GPIO_CHIP_PATH);
    if (!gpio_chip) {
        perror("gpiod_chip_open");
        return 1;
    }

    // Get GPIO line
    gpio_line_line = gpiod_chip_get_line(gpio_chip, GPIO_LINE);
    if (!gpio_line_line) {
        perror("gpiod_chip_get_line");
        gpiod_chip_close(gpio_chip);
        return 1;
    }

    // Request GPIO line for falling edge detection
    ret = gpiod_line_request_falling_edge(gpio_line_line, "vibration-monitor");
    if (ret < 0) {
        perror("gpiod_line_request_falling_edge");
        gpiod_chip_close(gpio_chip);
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("fopen");
        gpiod_line_release(gpio_line_line);
        gpiod_chip_close(gpio_chip);
        return 1;
    }

    fprintf(stderr, "Vibration monitoring started. Press Ctrl+C to exit.\n");

    while (keep_running) {
        // Wait for falling edge event
        event = gpiod_line_event_wait(gpio_line_line);
        if (!event) {
            perror("gpiod_line_event_wait");
            break;
        }

        // Read event value
        int value = gpiod_line_event_read(event);
        if (value < 0) {
            perror("gpiod_line_event_read");
            break;
        }

        // Get timestamp
        if (clock_gettime(CLOCK_REALTIME, &ts) == -1) {
            perror("clock_gettime");
            break;
        }

        struct tm tm_info;
        localtime_r(&ts.tv_sec, &tm_info);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info);

        // Log event to file
        fprintf(log_file, "%s Vibration detected!\n", timestamp);
        fflush(log_file);

        // Print to stdout
        printf("%s Vibration detected!\n", timestamp);

        // Shutdown system
        system("sudo shutdown -h now");

        // Clean up event
        gpiod_line_event_put(event);
    }

    // Clean up resources
    if (log_file) {
        fclose(log_file);
    }
    if (gpio_line_line) {
        gpiod_line_release(gpio_line_line);
    }
    if (gpio_chip) {
        gpiod_chip_close(gpio_chip);
    }

    fprintf(stderr, "Exiting.\n");
    return 0;
}

