#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define constants
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define VREF 3.3f
#define LM35_SCALE 0.01f // 10 mV/°C = 0.01 V/°C
#define BUFFER_SIZE 120
#define LOG_INTERVAL 5 // seconds

// Global variables
int spi_handle;
volatile sig_atomic_t terminate = 0;

// Circular buffer
float temperature_buffer[BUFFER_SIZE];
int buffer_index = 0;

// Function prototypes
float read_temperature();
void signal_handler(int signal);
void log_data();

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Function to read temperature from LM35 via MCP3008
float read_temperature() {
    unsigned char tx_buffer[3];
    unsigned char rx_buffer[3];
    int adc_value;
    float voltage, temperature;

    // Construct SPI message
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = 0x80; // Single-ended, channel 0
    tx_buffer[2] = 0x00; // Don't care

    // Perform SPI transaction
    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    if (result != 0) {
        fprintf(stderr, "SPI transfer failed: %d\n", result);
        return -1000.0f; // Indicate error
    }

    // Extract ADC value
    adc_value = ((rx_buffer[1] & 0x03) << 8) | rx_buffer[2];

    // Convert ADC value to voltage
    voltage = (float)adc_value / 1023.0f * VREF;

    // Convert voltage to temperature (°C)
    temperature = voltage / LM35_SCALE;

    return temperature;
}

// Function to log data to file
void log_data() {
    FILE *fp;

    // Open file in binary write mode
    fp = fopen("temp_log.dat", "wb+");
    if (fp == NULL) {
        fprintf(stderr, "Error opening file for writing!\n");
        return;
    }

    // Write temperature buffer to file
    size_t bytes_written = fwrite(temperature_buffer, sizeof(float), BUFFER_SIZE, fp);
    if (bytes_written != BUFFER_SIZE) {
        fprintf(stderr, "Error writing to file! Wrote %zu bytes, expected %d\n", bytes_written, BUFFER_SIZE);
    }

    // Close file
    fclose(fp);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // CE0, 1MHz, Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Temperature monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        float temperature = read_temperature();

        if (temperature > -999.0f) { // Check for read error
            printf("Temperature: %.2f °C\n", temperature);

            // Update circular buffer
            temperature_buffer[buffer_index] = temperature;
            buffer_index = (buffer_index + 1) % BUFFER_SIZE;

            // Log data every LOG_INTERVAL seconds
            if (time(NULL) % LOG_INTERVAL == 0) {
                log_data();
            }
        } else {
            fprintf(stderr, "Failed to read temperature. Skipping.\n");
        }

        sleep(5);
    }

    // Cleanup
    spiClose(spi_handle);
    gpioTerminate();

    printf("Temperature monitoring stopped.\n");

    return 0;
}

