#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <errno.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define BH1750_ADDR 0x23
#define MCP3008_SPI_DEVICE "/dev/spidev0.0"
#define LOG_FILE "environmental_log.txt"
#define SAMPLE_INTERVAL_SEC 1

// Global variables
int i2c_handle = -1;
int spi_fd = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int init_spi();
float read_light_level();
int read_sound_level();
char* format_log_entry(float light_level, int sound_level);
int write_to_log(const char *log_entry);
void signal_handler(int signal);

// Signal handler
void signal_handler(int signal) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating...\n", signal);
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, BH1750_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Initialize SPI
int init_spi() {
    spi_fd = open(MCP3008_SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        fprintf(stderr, "Error opening SPI device: %s\n", strerror(errno));
        return -1;
    }

    // Configure SPI mode
    int mode = SPI_MODE_0;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) == -1) {
        fprintf(stderr, "Error setting SPI mode: %s\n", strerror(errno));
        close(spi_fd);
        return -1;
    }

    // Configure SPI speed
    int speed = 1000000; // 1 MHz
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) == -1) {
        fprintf(stderr, "Error setting SPI speed: %s\n", strerror(errno));
        close(spi_fd);
        return -1;
    }

    return 0;
}

// Read light level from BH1750
float read_light_level() {
    if (i2c_handle < 0) {
        fprintf(stderr, "I2C not initialized\n");
        return -1.0;
    }

    // Send power on and start measurement command (High Resolution Mode)
    if (i2cWriteByteData(i2c_handle, 0x00, 0x10) < 0) {
        fprintf(stderr, "Error writing to I2C device: %d\n", i2c_handle);
        return -1.0;
    }

    // Wait for measurement (at least 180ms)
    gpioDelay(200000); // 200ms

    // Read two bytes of data
    char buf[2];
    if (i2cReadI2CBlockData(i2c_handle, 0x00, buf, 2) != 2) {
        fprintf(stderr, "Error reading from I2C device: %d\n", i2c_handle);
        return -1.0;
    }

    // Convert to lux
    unsigned int raw_value = (buf[0] << 8) | buf[1];
    float lux = (float)raw_value / 1.2;
    return lux;
}

// Read sound level from MCP3008
int read_sound_level() {
    if (spi_fd < 0) {
        fprintf(stderr, "SPI not initialized\n");
        return -1;
    }

    // MCP3008 configuration: Start bit, single-ended mode, channel 0
    unsigned char tx_buf[3];
    unsigned char rx_buf[3];

    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = 0x80; // Single-ended, channel 0 (10000000)
    tx_buf[2] = 0x00; // Don't care

    struct spi_ioc_transfer transfer = {
        .tx_buf = (unsigned long)tx_buf,
        .rx_buf = (unsigned long)rx_buf,
        .len = 3,
        .speed_hz = 1000000, // 1 MHz
        .delay_usecs = 0,
        .bits_per_word = 8,
    };

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &transfer) < 0) {
        fprintf(stderr, "Error during SPI transfer: %s\n", strerror(errno));
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((rx_buf[1] & 0x03) << 8) + rx_buf[2];
    return adc_value;
}

// Format log entry
char* format_log_entry(float light_level, int sound_level) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];
    static char log_entry[100]; // Static to avoid stack allocation issues

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    snprintf(log_entry, sizeof(log_entry), "%s, Light: %.2f, Sound: %d", timestamp, light_level, sound_level);
    return log_entry;
}

// Write to log file
int write_to_log(const char *log_entry) {
    if (log_file == NULL) {
        fprintf(stderr, "Log file not opened\n");
        return -1;
    }

    if (fprintf(log_file, "%s\n", log_entry) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        return -1;
    }

    fflush(log_file); // Ensure data is written immediately
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C and SPI
    if (init_i2c() != 0 || init_spi() != 0) {
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        close(spi_fd);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Read sensor data
        float light_level = read_light_level();
        int sound_level = read_sound_level();

        // Format log entry
        char *log_entry = format_log_entry(light_level, sound_level);

        // Write to log file
        if (write_to_log(log_entry) != 0) {
            fprintf(stderr, "Error writing to log, but continuing...\n");
        }

        // Wait for the next sample
        sleep(SAMPLE_INTERVAL_SEC);
    }

    // Cleanup
    i2cClose(i2c_handle);
    close(spi_fd);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

