#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_SPEED 500000
#define SPI_MODE 0
#define I2C_BUS 1
#define I2C_ADDRESS 0x62
#define VREF 3.3
#define TEMP_MIN 0.0
#define TEMP_MAX 50.0
#define DAC_MIN 0
#define DAC_MAX 4095
#define SAMPLE_INTERVAL 500 // milliseconds

// Global variables
int spi_handle;
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
float convert_to_celsius(int adc_value);
int set_mcp4725(float voltage);
void log_data(int adc_value, float temperature, float voltage);
void signal_handler(int signal);

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    char spi_tx_buf[3];
    char spi_rx_buf[3];

    // Construct SPI message (MCP3008 datasheet)
    spi_tx_buf[0] = 0x01; // Start bit
    spi_tx_buf[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    spi_tx_buf[2] = 0x00; // Don't care

    if (spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3) != 0) {
        fprintf(stderr, "Error: SPI transfer failed\n");
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];

    return adc_value;
}

// Function to convert ADC value to Celsius
float convert_to_celsius(int adc_value) {
    float voltage = (float)adc_value * VREF / 1024.0;
    float temperature = (voltage - 0.5) * 100.0;
    return temperature;
}

// Function to set MCP4725 DAC output voltage
int set_mcp4725(float voltage) {
    if (voltage < 0.0 || voltage > VREF) {
        fprintf(stderr, "Error: Voltage out of range: %.2fV\n", voltage);
        return -1;
    }

    // Calculate DAC value (12-bit resolution)
    int dac_value = (int)((voltage / VREF) * 4095.0);

    // Construct I2C message (MCP4725 datasheet)
    char i2c_tx_buf[2];
    i2c_tx_buf[0] = 0x40; // Write DAC value
    i2c_tx_buf[1] = (dac_value & 0xFF); // Lower byte

    // Write upper byte (shift DAC value right by 8 bits)
    i2c_tx_buf[0] = 0x41; // Write DAC value + MSB
    i2c_tx_buf[1] = ((dac_value >> 8) & 0xFF); // Upper byte

    if (i2cWriteDevice(i2c_handle, i2c_tx_buf, 2) != 0) {
        fprintf(stderr, "Error: I2C write failed\n");
        return -1;
    }

    return 0;
}

// Function to log data to file
void log_data(int adc_value, float temperature, float voltage) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, %d, %.2f, %.2f\n", timestamp, adc_value, temperature, voltage);
    fflush(log_file); // Ensure data is written to disk immediately

    printf("%s, %d, %.2f, %.2f\n", timestamp, adc_value, temperature, voltage);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Open I2C device
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: I2C open failed\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("temperature_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file\n");
        i2cClose(i2c_handle);
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        // Read ADC value
        int adc_value = read_mcp3008(0);
        if (adc_value < 0) {
            fprintf(stderr, "Error: Failed to read ADC value\n");
            continue; // Retry
        }

        // Convert to Celsius
        float temperature = convert_to_celsius(adc_value);

        // Set DAC voltage
        float voltage = temperature * (VREF / (TEMP_MAX - TEMP_MIN));
        if (set_mcp4725(voltage) < 0) {
            fprintf(stderr, "Error: Failed to set DAC voltage\n");
        }

        // Log data
        log_data(adc_value, temperature, voltage);

        // Wait for next sample
        gpioDelay(SAMPLE_INTERVAL * 1000); // Convert milliseconds to microseconds
    }

    // Cleanup
    fclose(log_file);
    i2cClose(i2c_handle);
    spiClose(spi_handle);
    gpioTerminate();

    return 0;
}

