#include <unistd.h>

// Define the GPIO chip and line numbers
#define GPIOCHIP "gpiochip0"
#define RELAY1_LINE 17
#define RELAY2_LINE 22
#define RELAY3_LINE 23
#define RELAY4_LINE 24

// Global variable to store the GPIO chip
struct gpiod_chip *chip;

// Function prototypes
int initialize_gpio(struct gpiod_chip *chip, int line);
int activate_relay(struct gpiod_line *line);
int deactivate_relay(struct gpiod_line *line);
void signal_handler(int sig);

// Signal handler function
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);

    // Deactivate all relays
    deactivate_relay(chip->lines[RELAY1_LINE]);
    deactivate_relay(chip->lines[RELAY2_LINE]);
    deactivate_relay(chip->lines[RELAY3_LINE]);
    deactivate_relay(chip->lines[RELAY4_LINE]);

    // Release GPIO lines
    gpiod_line_release(chip->lines[RELAY1_LINE]);
    gpiod_line_release(chip->lines[RELAY2_LINE]);
    gpiod_line_release(chip->lines[RELAY3_LINE]);
    gpiod_line_release(chip->lines[RELAY4_LINE]);

    // Close the GPIO chip
    gpiod_chip_close(chip);

    exit(0);
}

// Function to initialize a GPIO line
int initialize_gpio(struct gpiod_chip *chip, int line) {
    struct gpiod_line *gpio_line;

    // Request the GPIO line for output
    gpio_line = gpiod_chip_get_line(chip, line);
    if (!gpio_line) {
        fprintf(stderr, "Error: Could not get line %d\n", line);
        return -1;
    }

    // Request the line for output
    if (gpiod_line_request(gpio_line, "relay_control", GPIOD_LINE_REQUEST_DIRECTION_OUTPUT, 0) < 0) {
        fprintf(stderr, "Error: Could not request line %d for output\n", line);
        gpiod_line_release(gpio_line);
        return -1;
    }

    return 0;
}

// Function to activate a relay
int activate_relay(struct gpiod_line *line) {
    if (gpiod_line_set_value(line, 1) < 0) {
        fprintf(stderr, "Error: Could not set line value to 1\n");
        return -1;
    }
    return 0;
}

// Function to deactivate a relay
int deactivate_relay(struct gpiod_line *line) {
    if (gpiod_line_set_value(line, 0) < 0) {
        fprintf(stderr, "Error: Could not set line value to 0\n");
        return -1;
    }
    return 0;
}

int main() {
    // Install signal handlers for SIGINT and SIGTERM
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open the GPIO chip
    chip = gpiod_chip_open_by_name(GPIOCHIP);
    if (!chip) {
        fprintf(stderr, "Error: Could not open GPIO chip %s\n", GPIOCHIP);
        return 1;
    }

    // Initialize the GPIO lines
    if (initialize_gpio(chip, RELAY1_LINE) < 0 ||
        initialize_gpio(chip, RELAY2_LINE) < 0 ||
        initialize_gpio(chip, RELAY3_LINE) < 0 ||
        initialize_gpio(chip, RELAY4_LINE) < 0) {
        signal_handler(SIGTERM); // Clean up and exit
        return 1;
    }

    // Main loop
    while (1) {
        // Activate relay 1
        activate_relay(chip->lines[RELAY1_LINE]);
        sleep(1);
        deactivate_relay(chip->lines[RELAY1_LINE]);
        sleep(1);

        // Activate relay 2
        activate_relay(chip->lines[RELAY2_LINE]);
        sleep(1);
        deactivate_relay(chip->lines[RELAY2_LINE]);
        sleep(1);

        // Activate relay 3
        activate_relay(chip->lines[RELAY3_LINE]);
        sleep(1);
        deactivate_relay(chip->lines[RELAY3_LINE]);
        sleep(1);

        // Activate relay 4
        activate_relay(chip->lines[RELAY4_LINE]);
        sleep(1);
        deactivate_relay(chip->lines[RELAY4_LINE]);
        sleep(1);
    }

    return 0;
}

