#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

// Define GPIO pins
#define MIC_PIN 26
#define LED_PIN 16

// Define constants
#define ADC_RESOLUTION 1024
#define THRESHOLD 700
#define DEBOUNCE_DELAY 50000 // 50 ms in microseconds
#define LED_ON_DURATION 500000 // 500 ms in microseconds

// Global variable for signal handling
volatile sig_atomic_t program_running = 1;

// Function prototypes
int read_adc(int gpio);
int detect_clap(int adc_value, int threshold);
void control_led(int gpio, int state);
void print_timestamped_message(const char *message);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("\nCaught SIGINT, exiting gracefully.\n");
        program_running = 0;
        control_led(LED_PIN, 0); // Turn off LED
        gpioTerminate(); // Terminate pigpio
        exit(0);
    }
}

// Function to read ADC value from a GPIO pin
int read_adc(int gpio) {
    int adc_value = 0;
    int i;

    // Sample the GPIO pin for a short period
    for (i = 0; i < 100; i++) {
        if (gpioRead(gpio) == 1) {
            adc_value++;
        }
        gpioDelay(1); // Small delay for sampling
    }

    return adc_value;
}

// Function to detect a clap based on ADC value and threshold
int detect_clap(int adc_value, int threshold) {
    return (adc_value > threshold) ? 1 : 0;
}

// Function to control the LED
void control_led(int gpio, int state) {
    gpioWrite(gpio, state);
}

// Function to print a timestamped message to the console
void print_timestamped_message(const char *message) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    printf("[%s] %s\n", timestamp, message);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(MIC_PIN, PI_INPUT);
    gpioSetMode(LED_PIN, PI_OUTPUT);

    // Install signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Clap detector running. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        // Read ADC value
        int adc_value = read_adc(MIC_PIN);

        // Detect clap
        int clap_detected = detect_clap(adc_value, THRESHOLD);

        // If clap is detected, turn on LED and print message
        if (clap_detected) {
            control_led(LED_PIN, 1); // Turn on LED
            print_timestamped_message("Clap detected!");
            gpioDelay(LED_ON_DURATION); // Keep LED on for 500ms
            control_led(LED_PIN, 0); // Turn off LED
            gpioDelay(DEBOUNCE_DELAY); // Debounce
        }

        gpioDelay(1000); // Check every 1 ms
    }

    // Clean up and exit
    gpioTerminate();
    return 0;
}

