#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <sys/types.h>

#define GPIO_PIN 17
#define GPIO_PATH "/sys/class/gpio"
#define LOG_FILE "distance_log.txt"
#define VOLTAGE_HIGH 3.3
#define VOLTAGE_LOW 0.0
#define A 26.0
#define B -6.0
#define DISTANCE_THRESHOLD 200.0

volatile sig_atomic_t program_running = 1;

// Function to handle signals (SIGINT, SIGTERM)
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully.\n", signal);
}

// Function to export the GPIO pin
int export_gpio(int pin) {
    char export_path[64];
    int fd;

    snprintf(export_path, sizeof(export_path), "%s/export", GPIO_PATH);
    fd = open(export_path, O_WRONLY);
    if (fd < 0) {
        perror("Failed to open GPIO export file");
        return -1;
    }

    char pin_str[4];
    snprintf(pin_str, sizeof(pin_str), "%d", pin);
    if (write(fd, pin_str, strlen(pin_str)) < 0) {
        perror("Failed to write to GPIO export file");
        close(fd);
        return -1;
    }

    close(fd);
    return 0;
}

// Function to unexport the GPIO pin
int unexport_gpio(int pin) {
    char unexport_path[64];
    int fd;

    snprintf(unexport_path, sizeof(unexport_path), "%s/unexport", GPIO_PATH);
    fd = open(unexport_path, O_WRONLY);
    if (fd < 0) {
        perror("Failed to open GPIO unexport file");
        return -1;
    }

    char pin_str[4];
    snprintf(pin_str, sizeof(pin_str), "%d", pin);
    if (write(fd, pin_str, strlen(pin_str)) < 0) {
        perror("Failed to write to GPIO unexport file");
        close(fd);
        return -1;
    }

    close(fd);
    return 0;
}

// Function to set the GPIO direction (in or out)
int set_gpio_direction(int pin, const char *direction) {
    char direction_path[64];
    int fd;

    snprintf(direction_path, sizeof(direction_path), "%s/gpio%d/direction", GPIO_PATH, pin);
    fd = open(direction_path, O_WRONLY);
    if (fd < 0) {
        perror("Failed to open GPIO direction file");
        return -1;
    }

    if (write(fd, direction, strlen(direction)) < 0) {
        perror("Failed to write to GPIO direction file");
        close(fd);
        return -1;
    }

    close(fd);
    return 0;
}

// Function to read the GPIO value
int read_gpio_value(int pin) {
    char value_path[64];
    int fd;
    char value_str[3];

    snprintf(value_path, sizeof(value_path), "%s/gpio%d/value", GPIO_PATH, pin);
    fd = open(value_path, O_RDONLY);
    if (fd < 0) {
        perror("Failed to open GPIO value file");
        return -1;
    }

    if (read(fd, value_str, 3) < 0) {
        perror("Failed to read GPIO value file");
        close(fd);
        return -1;
    }

    close(fd);
    return atoi(value_str);
}

// Function to convert digital value to voltage
float digital_to_voltage(int digital_value) {
    return (digital_value == 1) ? VOLTAGE_HIGH : VOLTAGE_LOW;
}

// Function to convert voltage to distance
float voltage_to_distance(float voltage) {
    return (A / voltage) + B;
}

// Function to log the distance to a file
int log_distance(float distance) {
    FILE *fp;
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("Failed to open log file");
        return -1;
    }

    fprintf(fp, "%s, Distance: %.2f mm\n", timestamp, distance);
    fclose(fp);
    return 0;
}

// Function to determine feeder activation status
void feeder_status(float distance) {
    if (distance < DISTANCE_THRESHOLD) {
        printf("Feeder Activated\n");
    } else {
        printf("Feeder Idle\n");
    }
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Export GPIO pin
    if (export_gpio(GPIO_PIN) < 0) {
        fprintf(stderr, "Failed to export GPIO %d. Exiting.\n", GPIO_PIN);
        return 1;
    }

    // Set GPIO direction to input
    if (set_gpio_direction(GPIO_PIN, "in") < 0) {
        fprintf(stderr, "Failed to set GPIO %d direction. Exiting.\n", GPIO_PIN);
        unexport_gpio(GPIO_PIN);
        return 1;
    }

    printf("Pet Feeder Program started. Press Ctrl+C to exit.\n");

    while (program_running) {
        int digital_value = read_gpio_value(GPIO_PIN);
        if (digital_value < 0) {
            fprintf(stderr, "Failed to read GPIO %d value. Retrying in 1 second.\n", GPIO_PIN);
            sleep(1);
            continue;
        }

        float voltage = digital_to_voltage(digital_value);
        float distance = voltage_to_distance(voltage);

        if (log_distance(distance) < 0) {
            fprintf(stderr, "Failed to log distance. Continuing.\n");
        }

        feeder_status(distance);

        sleep(1);
    }

    // Unexport GPIO pin before exiting
    if (unexport_gpio(GPIO_PIN) < 0) {
        fprintf(stderr, "Failed to unexport GPIO %d.\n", GPIO_PIN);
    }

    printf("Program finished.\n");
    return 0;
}

