// Define GPIO pins
#define PUMP_GPIO 17
#define SPI_CE0 0

// Define SPI parameters
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz

// Define moisture threshold
#define MOISTURE_THRESHOLD 30.0

// Define log file name
#define LOG_FILE "soil_moisture.log"

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
float calculate_moisture(int adc_value);
void control_pump(float moisture_level);
void log_data(float moisture_level, int pump_status);
void signal_handler(int signal);

// Function to read data from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message (MCP3008 datasheet)
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Don't care

    if (spiXfer(spi_handle, tx_buffer, rx_buffer, 3) != 0) {
        fprintf(stderr, "Error: SPI transfer failed\n");
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];

    return adc_value;
}

// Function to calculate moisture percentage
float calculate_moisture(int adc_value) {
    float moisture = 100.0 - ((float)(adc_value - 300) / (float)(800 - 300)) * 100.0;

    // Clamp moisture value between 0 and 100
    if (moisture < 0.0) {
        moisture = 0.0;
    }
    if (moisture > 100.0) {
        moisture = 100.0;
    }

    return moisture;
}

// Function to control the water pump
void control_pump(float moisture_level) {
    if (moisture_level < MOISTURE_THRESHOLD) {
        gpioWrite(PUMP_GPIO, 1); // Turn pump ON
        printf("Pump ON\n");
    } else {
        gpioWrite(PUMP_GPIO, 0); // Turn pump OFF
        printf("Pump OFF\n");
    }
}

// Function to log data to file
void log_data(float moisture_level, int pump_status) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, Moisture: %.2f%%, Pump: %s\n", timestamp, moisture_level, pump_status ? "ON" : "OFF");
    fflush(log_file); // Ensure data is written to disk immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO17 as output for pump control
    gpioSetMode(PUMP_GPIO, PI_OUTPUT);
    gpioWrite(PUMP_GPIO, 0); // Ensure pump is initially OFF

    // Open SPI channel
    spi_handle = spiOpen(SPI_CE0, SPI_SPEED, 0); // CE0, 1MHz, Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Soil moisture monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        // Read ADC value from channel 0
        int adc_value = read_mcp3008(0);
        if (adc_value < 0) {
            fprintf(stderr, "Error: Failed to read ADC value\n");
            continue; // Skip to the next iteration
        }

        // Calculate moisture percentage
        float moisture_level = calculate_moisture(adc_value);

        // Control the pump
        control_pump(moisture_level);

        // Log the data
        log_data(moisture_level, gpioRead(PUMP_GPIO));

        printf("Moisture: %.2f%%, Pump: %s\n", moisture_level, gpioRead(PUMP_GPIO) ? "ON" : "OFF");

        // Wait for 60 seconds
        sleep(60);
    }

    // Cleanup
    printf("Cleaning up...\n");
    gpioWrite(PUMP_GPIO, 0); // Turn pump OFF
    spiClose(spi_handle);
    fclose(log_file);
    gpioTerminate();

    printf("Exiting.\n");
    return 0;
}

