#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

// Configuration
#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE SPI_MODE_0
#define SPI_BITS_PER_WORD 8
#define SPI_SPEED 1000000 // 1 MHz
#define GPIO_CHIP "gpiochip0"
#define GPIO_LINE 8
#define SAMPLE_INTERVAL_MS 500
#define LOG_FILE "magnetic_log.txt"

// Global variables (minimize usage)
static volatile int keep_running = 1;
static int spi_fd = -1;
static struct gpiod_chip *gpio_chip = NULL;
static struct gpiod_line *gpio_line_line = NULL;
static FILE *log_file = NULL;

// Function prototypes
int spi_transfer(int fd, uint8_t *tx_buf, uint8_t *rx_buf, size_t len);
int read_mcp3008(int spi_fd, int channel);
double calculate_magnetic_field(int adc_value);
int log_data(double magnetic_field);
void signal_handler(int sig);
int setup_gpio(const char *chipname, int line);
void cleanup_gpio(struct gpiod_chip *chip, struct gpiod_line *line);

// SPI transfer function
int spi_transfer(int fd, uint8_t *tx_buf, uint8_t *rx_buf, size_t len) {
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx_buf,
        .rx_buf = (unsigned long)rx_buf,
        .len = len,
        .delay_usecs = 0,
        .speed_hz = SPI_SPEED,
        .bits_per_word = SPI_BITS_PER_WORD,
    };

    int ret = ioctl(fd, SPI_IOC_MESSAGE(1), &tr);
    if (ret < 1) {
        fprintf(stderr, "SPI transfer failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Function to read from MCP3008 ADC
int read_mcp3008(int spi_fd, int channel) {
    uint8_t tx_buf[3];
    uint8_t rx_buf[3];

    // Construct SPI message
    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = (0x08 | (channel << 4)); // Single-ended mode, channel select
    tx_buf[2] = 0x00; // Don't care

    // Perform SPI transfer
    if (spi_transfer(spi_fd, tx_buf, rx_buf, 3) != 0) {
        return -1; // Indicate error
    }

    // Extract ADC value
    int adc_value = ((rx_buf[1] & 0x03) << 8) + rx_buf[2];
    return adc_value;
}

// Function to calculate magnetic field in mT
double calculate_magnetic_field(int adc_value) {
    double vout_mv = (double)adc_value * 3300.0 / 1023.0;
    double b_mt = (vout_mv - 1650.0) / 100.0;
    return b_mt;
}

// Function to log data to file
int log_data(double magnetic_field) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (log_file == NULL) {
        fprintf(stderr, "Log file is not open.\n");
        return -1;
    }

    int ret = fprintf(log_file, "%s,%.2f\n", timestamp, magnetic_field);
    if (ret < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        return -1;
    }

    fflush(log_file); // Ensure data is written to disk
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, exiting...\n");
    keep_running = 0;
}

// Setup GPIO line
int setup_gpio(const char *chipname, int line) {
    gpio_chip = gpiod_chip_open_by_name(chipname);
    if (!gpio_chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", strerror(errno));
        return -1;
    }

    gpio_line_line = gpiod_chip_get_line(gpio_chip, line);
    if (!gpio_line_line) {
        fprintf(stderr, "Error getting GPIO line: %s\n", strerror(errno));
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    struct gpiod_line_request_config config;
    memset(&config, 0, sizeof(config));
    config.consumer = "magnetic_sensor";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;

    if (gpiod_line_request(gpio_line_line, &config, 0) != 0) {
        fprintf(stderr, "Error requesting GPIO line: %s\n", strerror(errno));
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    if (gpiod_line_set_value(gpio_line_line, 0) != 0) { // Set low initially
        fprintf(stderr, "Error setting GPIO line value: %s\n", strerror(errno));
        gpiod_line_release(gpio_line_line);
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    return 0;
}

// Cleanup GPIO line
void cleanup_gpio(struct gpiod_chip *chip, struct gpiod_line *line) {
    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open SPI device
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        fprintf(stderr, "Error opening SPI device: %s\n", strerror(errno));
        return 1;
    }

    // Configure SPI mode
    uint8_t mode = SPI_MODE;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "Error setting SPI mode: %s\n", strerror(errno));
        close(spi_fd);
        return 1;
    }

    // Configure SPI bits per word
    uint8_t bits = SPI_BITS_PER_WORD;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "Error setting SPI bits per word: %s\n", strerror(errno));
        close(spi_fd);
        return 1;
    }

    // Configure SPI speed
    uint32_t speed = SPI_SPEED;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "Error setting SPI speed: %s\n", strerror(errno));
        close(spi_fd);
        return 1;
    }

    // Setup GPIO
    if (setup_gpio(GPIO_CHIP, GPIO_LINE) != 0) {
        close(spi_fd);
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        cleanup_gpio(gpio_chip, gpio_line_line);
        close(spi_fd);
        return 1;
    }

    // Main loop
    while (keep_running) {
        // Read ADC value
        int adc_value = read_mcp3008(spi_fd, 0);
        if (adc_value < 0) {
            fprintf(stderr, "Error reading ADC value, skipping sample.\n");
            usleep(SAMPLE_INTERVAL_MS * 1000); // Sleep for the sample interval
            continue;
        }

        // Calculate magnetic field
        double magnetic_field = calculate_magnetic_field(adc_value);

        // Log data
        if (log_data(magnetic_field) != 0) {
            fprintf(stderr, "Error logging data.\n");
        }

        // Sleep for the sample interval
        usleep(SAMPLE_INTERVAL_MS * 1000);
    }

    // Cleanup
    cleanup_gpio(gpio_chip, gpio_line_line);
    close(spi_fd);
    fclose(log_file);

    return 0;
}

