// Define constants
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define MCP3008_CHANNEL 0
#define LED_GPIO 21
#define THRESHOLD_FIELD 10.0 // mT
#define VCC 3.3 // Sensor supply voltage
#define SENSITIVITY_mV_PER_mT 1.65 // Sensitivity of DRV5055VA at 3.3V

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize();
int read_mcp3008(int channel);
float adc_to_voltage(int adc_value);
float voltage_to_field_strength(float voltage);
void log_data(float field_strength);
void control_led(float field_strength);
void signal_handler(int signal);
void cleanup();

// Structure for configuration (optional)
typedef struct {
    int spi_channel;
    int spi_speed;
    int mcp3008_channel;
    int led_gpio;
    float threshold_field;
    float vcc;
    float sensitivity_mv_per_mt;
} Config;

Config config = {
    SPI_CHANNEL,
    SPI_SPEED,
    MCP3008_CHANNEL,
    LED_GPIO,
    THRESHOLD_FIELD,
    VCC,
    SENSITIVITY_mV_PER_mT
};

int main() {
    if (initialize() != 0) {
        fprintf(stderr, "Initialization failed. Exiting.\n");
        return 1;
    }

    signal(SIGINT, signal_handler);

    while (!terminate) {
        int adc_value = read_mcp3008(config.mcp3008_channel);
        if (adc_value < 0) {
            fprintf(stderr, "Error reading ADC value. Retrying.\n");
            gpioDelay(100); // Wait before retrying
            continue;
        }

        float voltage = adc_to_voltage(adc_value);
        float field_strength = voltage_to_field_strength(voltage);

        log_data(field_strength);
        control_led(field_strength);

        gpioDelay(100); // 100 ms delay
    }

    cleanup();
    return 0;
}

int initialize() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(config.spi_channel, config.spi_speed, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Set LED GPIO as output
    gpioSetMode(config.led_gpio, PI_OUTPUT);
    gpioWrite(config.led_gpio, 0); // Initially turn off the LED

