    log_file = fopen("magnetic_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    return 0;
}

int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    unsigned char spi_tx_buf[3];
    unsigned char spi_rx_buf[3];

    // Construct SPI message (MCP3008 datasheet)
    spi_tx_buf[0] = 0x01; // Start bit
    spi_tx_buf[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    spi_tx_buf[2] = 0x00; // Don't care

    if (spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3) != 0) {
        fprintf(stderr, "SPI transfer failed\n");
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];

    return adc_value;
}

float adc_to_voltage(int adc_value) {
    return (float)adc_value * config.vcc / 1023.0;
}

float voltage_to_field_strength(float voltage) {
    return (voltage - config.vcc / 2.0) * 1000.0 / config.sensitivity_mv_per_mt;
}

void log_data(float field_strength) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, %.4f mT\n", timestamp, field_strength);
    fflush(log_file); // Ensure data is written to file immediately
}

void control_led(float field_strength) {
    if (field_strength > config.threshold_field) {
        gpioWrite(config.led_gpio, 1); // Turn on LED
    } else {
        gpioWrite(config.led_gpio, 0); // Turn off LED
    }
}

void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

void cleanup() {
    printf("Cleaning up...\n");
    gpioWrite(config.led_gpio, 0); // Turn off LED
    spiClose(spi_handle);
    fclose(log_file);
    gpioTerminate();
}

