#include <pigpio.h>
#include <unistd.h>

// Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define ADC_CHANNEL 0
#define VREF 5.0        // Reference voltage for MCP3008
#define SENSITIVITY 0.1 // 100 mV/A = 0.1 V/A
#define LOG_FILE "current_log.txt"

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize();
double read_current();
void log_data(double current);
void signal_handler(int signal);
void cleanup();

// Structure for SPI configuration (optional)
typedef struct {
    int channel;
    int speed;
} spi_config_t;

// Structure for ADC configuration (optional)
typedef struct {
    int channel;
    double vref;
    double sensitivity;
} adc_config_t;


int main() {
    if (initialize() != 0) {
        fprintf(stderr, "Initialization failed. Exiting.\n");
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (!terminate) {
        double current = read_current();
        log_data(current);
        sleep(1);
    }

    cleanup();
    return 0;
}

int initialize() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    return 0;
}

double read_current() {
    unsigned char spi_tx_buf[3];
    unsigned char spi_rx_buf[3];
    int adc_value;
    double voltage, current;

    // MCP3008 command to read channel 0 (single-ended)
    spi_tx_buf[0] = 0x01; // Start bit
    spi_tx_buf[1] = (0x08 | ADC_CHANNEL) << 4; // Single-ended, channel select
    spi_tx_buf[2] = 0x00; // Don't care

    if (spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3) != 0) {
        fprintf(stderr, "SPI transfer failed\n");
        return -1.0; // Indicate error
    }

    // Extract ADC value from the response
    adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];

    // Convert ADC value to voltage
    voltage = ((double)adc_value / 1023.0) * VREF;

    // Convert voltage to current
    current = voltage / SENSITIVITY;

    return current;
}

void log_data(double current) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f\n", timestamp, current);
    fflush(log_file); // Ensure data is written to file immediately

    printf("%s,%.2f\n", timestamp, current); // Also print to console
}

void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

void cleanup() {
    printf("Cleaning up...\n");
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    printf("Cleanup complete. Exiting.\n");
}

