#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// Define SPI parameters
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 0

// Define MCP3008 channel
#define MCP3008_CHANNEL 0

// Define MLX91211 parameters
#define MLX91211_FULL_SCALE_CURRENT 50.0 // Amperes
#define MLX91211_ZERO_CURRENT_VOLTAGE 2.5 // Volts
#define MLX91211_FULL_SCALE_VOLTAGE 5.0 // Volts

// Global variables
int spi_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
float voltage_to_current(float voltage);
void log_current(float current);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    unsigned char tx_buffer[3];
    unsigned char rx_buffer[3];

    // Construct SPI message
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = 0x80 | (channel << 4); // Single-ended mode, channel selection
    tx_buffer[2] = 0x00; // Don't care

    // Perform SPI transfer
    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    if (result != 0) {
        fprintf(stderr, "SPI transfer error: %d\n", result);
        return -1; // Indicate error
    }

    // Extract ADC value (10 bits)
    int adc_value = ((rx_buffer[1] & 0x03) << 8) | rx_buffer[2];

    return adc_value;
}

// Function to convert voltage to current
float voltage_to_current(float voltage) {
    if (voltage < 0.0 || voltage > 5.0) {
        fprintf(stderr, "Warning: Voltage out of range (0-5V): %.2fV\n", voltage);
        return 0.0; // Or some other appropriate value/error
    }

    float current = (voltage - MLX91211_ZERO_CURRENT_VOLTAGE) * (MLX91211_FULL_SCALE_CURRENT / (MLX91211_FULL_SCALE_VOLTAGE - MLX91211_ZERO_CURRENT_VOLTAGE));
    return current;
}

// Function to log current to file
void log_current(float current) {
    FILE *fp = fopen("current_log.txt", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        return;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s %.2f A\n", timestamp, current);
    fflush(fp); // Ensure data is written to disk immediately
    fclose(fp);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Current monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        // Read ADC value
        int adc_value = read_mcp3008(MCP3008_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Error reading ADC value, skipping sample.\n");
            gpioDelay(100000); // 100ms delay
            continue;
        }

        // Convert ADC value to voltage
        float voltage = (float)adc_value / 1023.0 * 5.0;

        // Convert voltage to current
        float current = voltage_to_current(voltage);

        // Log current
        log_current(current);

        // Delay for 100ms
        gpioDelay(100000);
    }

    // Cleanup
    spiClose(spi_handle);
    gpioTerminate();

    printf("Current monitoring stopped.\n");
    return 0;
}

