#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>
#include <time.h>

// Define GPIO pins for the sensors
#define SENSOR1_GPIO 4
#define SENSOR2_GPIO 17

// Debounce parameters
#define NUM_SAMPLES 5
#define SAMPLE_DELAY_MS 2

// Global variables for GPIO chip and lines
struct gpiod_chip *chip;
struct gpiod_line *line1;
struct gpiod_line *line2;

// Function prototypes
int read_sensor(struct gpiod_line *line);
int debounce_read(struct gpiod_line *line);
void log_sensor_data(int sensor1_state, int sensor2_state);
void signal_handler(int sig);

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    if (sig == SIGINT) {
        printf("\nCaught SIGINT, exiting gracefully.\n");

        // Release GPIO resources
        if (line1) {
            gpiod_line_release(line1);
        }
        if (line2) {
            gpiod_line_release(line2);
        }
        if (chip) {
            gpiod_chip_close(chip);
        }

        exit(0);
    }
}

// Function to read the state of a sensor
int read_sensor(struct gpiod_line *line) {
    int value = gpiod_line_get_value(line);
    if (value < 0) {
        fprintf(stderr, "Error reading sensor value: %d\n", value);
        return -1; // Indicate an error
    }
    return value;
}

// Function to debounce the sensor reading
int debounce_read(struct gpiod_line *line) {
    int high_count = 0;
    int low_count = 0;
    int value;

    for (int i = 0; i < NUM_SAMPLES; i++) {
        value = read_sensor(line);
        if (value < 0) {
            return -1; // Propagate error
        }
        if (value == 0) {
            low_count++;
        } else {
            high_count++;
        }
        usleep(SAMPLE_DELAY_MS * 1000); // Convert ms to microseconds
    }

    // Determine the majority value
    return (low_count > high_count) ? 0 : 1;
}

// Function to log sensor data
void log_sensor_data(int sensor1_state, int sensor2_state) {
    printf("Sensor 1: %d, Sensor 2: %d\n", sensor1_state, sensor2_state);

    if (sensor1_state == 0 && sensor2_state == 0) {
        printf("ALERT: Both sensors detect object\n");
    }
}

int main() {
    // Register signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Open the GPIO chip
    chip = gpiod_chip_open_by_number(0);
    if (!chip) {
        perror("Error opening GPIO chip");
        return 1;
    }

    // Get the GPIO lines for the sensors
    line1 = gpiod_chip_get_line(chip, SENSOR1_GPIO);
    if (!line1) {
        perror("Error getting line for sensor 1");
        gpiod_chip_close(chip);
        return 1;
    }

    line2 = gpiod_chip_get_line(chip, SENSOR2_GPIO);
    if (!line2) {
        perror("Error getting line for sensor 2");
        gpiod_line_release(line1);
        gpiod_chip_close(chip);
        return 1;
    }

    // Request the GPIO lines as inputs
    if (gpiod_line_request_input(line1, "sensor1") < 0) {
        perror("Error requesting line 1 as input");
        gpiod_line_release(line2);
        gpiod_chip_close(chip);
        return 1;
    }

    if (gpiod_line_request_input(line2, "sensor2") < 0) {
        perror("Error requesting line 2 as input");
        gpiod_line_release(line1);
        gpiod_chip_close(chip);
        return 1;
    }

    // Main loop
    while (1) {
        int sensor1_state = debounce_read(line1);
        int sensor2_state = debounce_read(line2);

        if (sensor1_state < 0 || sensor2_state < 0) {
            fprintf(stderr, "Error reading sensor data. Exiting.\n");
            break; // Exit loop on error
        }

        log_sensor_data(sensor1_state, sensor2_state);

        sleep(1); // Wait for 1 second
    }

    // Release GPIO resources before exiting
    gpiod_line_release(line1);
    gpiod_line_release(line2);
    gpiod_chip_close(chip);

    return 0;
}

