#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/wait.h>
#include <pigpio.h>
#include <syslog.h>
#include <errno.h>
#include <fcntl.h>
#include <sys/stat.h>

#define PIR_GPIO 17
#define DEBOUNCE_DELAY_MS 200
#define SNAPSHOT_DIR "/home/pi/security_cam/"
#define LOG_FILE "/var/log/motion_detector.log"

volatile sig_atomic_t program_running = 1;

void signal_handler(int signal) {
    program_running = 0;
    syslog(LOG_INFO, "Signal received, stopping program...");
}

int main() {
    int pir_state = 0;
    int last_pir_state = 0;
    time_t rawtime;
    struct tm *timeinfo;
    char filename[256];
    char command[512];
    pid_t pid;
    int status;

    // Initialize syslog
    openlog("motion_detector", LOG_PID | LOG_CONS, LOG_USER);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        closelog();
        return 1;
    }

    // Configure GPIO17 as input with pull-down resistor
    gpioSetMode(PIR_GPIO, PI_INPUT);
    gpioSetPullUpDown(PIR_GPIO, PI_PUD_DOWN);

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    syslog(LOG_INFO, "Motion detector started");

    while (program_running) {
        // Read PIR sensor state
        pir_state = gpioRead(PIR_GPIO);

        // Debounce and detect motion
        if (pir_state != last_pir_state) {
            gpioDelay(DEBOUNCE_DELAY_MS * 1000); // Debounce delay
            pir_state = gpioRead(PIR_GPIO); // Re-read after debounce

            if (pir_state != last_pir_state) {
                last_pir_state = pir_state;

                if (pir_state == 1) {
                    // Motion detected
                    time(&rawtime);
                    timeinfo = localtime(&rawtime);

                    // Generate filename with ISO 8601 timestamp
                    strftime(filename, sizeof(filename), SNAPSHOT_DIR "%Y-%m-%d_%H-%M-%S.jpg", timeinfo);

                    // Construct libcamera-still command
                    snprintf(command, sizeof(command), "libcamera-still -o %s --width 1280 --height 720 --iso 800", filename);

                    // Create snapshot directory if it doesn't exist
                    struct stat st = {0};
                    if (stat(SNAPSHOT_DIR, &st) == -1) {
                        if (mkdir(SNAPSHOT_DIR, 0755) == -1) {
                            syslog(LOG_ERR, "Failed to create snapshot directory: %s", strerror(errno));
                            continue; // Skip to the next iteration
                        }
                    }

                    // Capture image using libcamera-still
                    pid = fork();

                    if (pid == 0) {
                        // Child process
                        execvp("/usr/bin/libcamera-still", NULL); // Execute libcamera-still
                        syslog(LOG_ERR, "execvp failed: %s", strerror(errno));
                        exit(1); // Exit child process if execvp fails
                    } else if (pid > 0) {
                        // Parent process
                        waitpid(pid, &status, 0);

                        if (WIFEXITED(status)) {
                            if (WEXITSTATUS(status) == 0) {
                                syslog(LOG_INFO, "Motion detected, image captured: %s", filename);
                            } else {
                                syslog(LOG_ERR, "Image capture failed with exit status: %d", WEXITSTATUS(status));
                            }
                        } else {
                            syslog(LOG_ERR, "Image capture process terminated abnormally");
                        }
                    } else {
                        syslog(LOG_ERR, "Fork failed: %s", strerror(errno));
                    }
                }
            }
        }

        gpioDelay(50 * 1000); // Poll every 50 ms
    }

    // Cleanup
    gpioTerminate();
    syslog(LOG_INFO, "Motion detector stopped");
    closelog();

    return 0;
}

