#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <errno.h>
#include <signal.h>
#include <time.h>
#include <linux/videodev2.h>
#include <sys/select.h>

#define CLEAR(x) memset(&(x), 0, sizeof(x))

struct buffer {
    void   *start;
    size_t  length;
};

static int                 fd                  = -1;
static struct buffer       *buffers             = NULL;
static unsigned int         n_buffers           = 0;
static unsigned int         frame_number        = 0;
static int                 running             = 1;

static void signal_handler(int sig)
{
    fprintf(stderr, "Caught signal %d, exiting gracefully.\n", sig);
    running = 0;
}

static int xioctl(int fh, int request, void *arg)
{
    int r;

    do {
        r = ioctl(fh, request, arg);
    } while (-1 == r && EINTR == errno);

    return r;
}

static int open_device(const char *device_name)
{
    int fd = open(device_name, O_RDWR | O_NONBLOCK, 0);

    if (-1 == fd) {
        fprintf(stderr, "Cannot open '%s': %s\n", device_name, strerror(errno));
        return -1;
    }

    return fd;
}

static int init_device(int fd)
{
    struct v4l2_capability cap;
    struct v4l2_format fmt;
    struct v4l2_requestbuffers req;

    if (-1 == xioctl(fd, VIDIOC_QUERYCAP, &cap)) {
        fprintf(stderr, "VIDIOC_QUERYCAP error: %s\n", strerror(errno));
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "'%s' is no video capture device\n", "/dev/video0");
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "'%s' does not support streaming i/o\n", "/dev/video0");
        return -1;
    }

    CLEAR(fmt);

    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = 640;
    fmt.fmt.pix.height = 480;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_GREY;
    fmt.fmt.pix.field = V4L2_FIELD_NONE;

    if (-1 == xioctl(fd, VIDIOC_S_FMT, &fmt)) {
        fprintf(stderr, "VIDIOC_S_FMT error: %s\n", strerror(errno));
        return -1;
    }

    CLEAR(req);

    req.count = 1; // Single buffer
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (-1 == xioctl(fd, VIDIOC_REQBUFS, &req)) {
        fprintf(stderr, "VIDIOC_REQBUFS error: %s\n", strerror(errno));
        return -1;
    }

    if (req.count < 1) {
        fprintf(stderr, "Insufficient buffer memory\n");
        return -1;
    }

    buffers = calloc(req.count, sizeof(*buffers));

    if (!buffers) {
        fprintf(stderr, "Out of memory\n");
        return -1;
    }

    for (n_buffers = 0; n_buffers < req.count; ++n_buffers) {
        struct v4l2_buffer buf;

        CLEAR(buf);

        buf.type        = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory      = V4L2_MEMORY_MMAP;
        buf.index       = n_buffers;

        if (-1 == xioctl(fd, VIDIOC_QUERYBUF, &buf)) {
            fprintf(stderr, "VIDIOC_QUERYBUF error: %s\n", strerror(errno));
            return -1;
        }

        buffers[n_buffers].length = buf.length;
        buffers[n_buffers].start = mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf.m.offset);

        if (MAP_FAILED == buffers[n_buffers].start) {
            fprintf(stderr, "mmap error: %s\n", strerror(errno));
            return -1;
        }
    }

    return 0;
}

static int start_capturing(int fd)
{
    unsigned int i;
    enum v4l2_buf_type type;

    for (i = 0; i < n_buffers; ++i) {
        struct v4l2_buffer buf;

        CLEAR(buf);
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = i;

        if (-1 == xioctl(fd, VIDIOC_QBUF, &buf)) {
            fprintf(stderr, "VIDIOC_QBUF error: %s\n", strerror(errno));
            return -1;
        }
    }

    type = V4L2_BUF_TYPE_VIDEO_CAPTURE;

    if (-1 == xioctl(fd, VIDIOC_STREAMON, &type)) {
        fprintf(stderr, "VIDIOC_STREAMON error: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

static int stop_capturing(int fd)
{
    enum v4l2_buf_type type;

    type = V4L2_BUF_TYPE_VIDEO_CAPTURE;

    if (-1 == xioctl(fd, VIDIOC_STREAMOFF, &type)) {
        fprintf(stderr, "VIDIOC_STREAMOFF error: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

static int dequeue_buffer(int fd)
{
    fd_set fds;
    struct timeval tv;
    struct v4l2_buffer buf;
    int r;

    FD_ZERO(&fds);
    FD_SET(fd, &fds);

    tv.tv_sec = 2; // Timeout of 2 seconds
    tv.tv_usec = 0;

    r = select(fd + 1, &fds, NULL, NULL, &tv);

    if (-1 == r) {
        fprintf(stderr, "select error: %s\n", strerror(errno));
        return -1;
    }

    if (0 == r) {
        fprintf(stderr, "select timeout\n");
        return -1;
    }

    CLEAR(buf);
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;

    if (-1 == xioctl(fd, VIDIOC_DQBUF, &buf)) {
        fprintf(stderr, "VIDIOC_DQBUF error: %s\n", strerror(errno));
        return -1;
    }

    return buf.index;
}

static int save_pgm(const char *filename, const void *data, int width, int height)
{
    FILE *fp = fopen(filename, "wb");

    if (!fp) {
        fprintf(stderr, "Cannot open '%s' for writing: %s\n", filename, strerror(errno));
        return -1;
    }

    fprintf(fp, "P5\n%d %d\n255\n", width, height);
    fwrite(data, 1, width * height, fp);
    fclose(fp);

    return 0;
}

static int uninit_device(int fd)
{
    unsigned int i;

    for (i = 0; i < n_buffers; ++i) {
        if (-1 == munmap(buffers[i].start, buffers[i].length)) {
            fprintf(stderr, "munmap error: %s\n", strerror(errno));
            return -1;
        }
    }

    free(buffers);

    return 0;
}

static int close_device(int fd)
{
    if (-1 == close(fd)) {
        fprintf(stderr, "close error: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

int main(int argc, char *argv[])
{
    const char *device_name = "/dev/video0";

    if (argc > 1) {
        device_name = argv[1];
    }

    signal(SIGINT,  signal_handler);
    signal(SIGTERM, signal_handler);

    fd = open_device(device_name);

    if (-1 == fd) {
        return EXIT_FAILURE;
    }

    if (-1 == init_device(fd)) {
        close_device(fd);
        return EXIT_FAILURE;
    }

    if (-1 == start_capturing(fd)) {
        uninit_device(fd);
        close_device(fd);
        return EXIT_FAILURE;
    }

    while (running) {
        int buffer_index = dequeue_buffer(fd);

        if (-1 == buffer_index) {
            break;
        }

        char filename[64];
        snprintf(filename, sizeof(filename), "image_%04d.pgm", ++frame_number);

        if (-1 == save_pgm(filename, buffers[buffer_index].start, 640, 480)) {
            fprintf(stderr, "Failed to save PGM file.\n");
            break;
        }
    }

    if (-1 == stop_capturing(fd)) {
        fprintf(stderr, "Failed to stop capturing.\n");
    }

    if (-1 == uninit_device(fd)) {
        fprintf(stderr, "Failed to uninitialize device.\n");
    }

    if (-1 == close_device(fd)) {
        fprintf(stderr, "Failed to close device.\n");
    }

    return EXIT_SUCCESS;
}

