static int dequeue_buffer(int fd)
{
    fd_set fds;
    struct timeval tv;
    struct v4l2_buffer buf;
    int r;

    FD_ZERO(&fds);
    FD_SET(fd, &fds);

    tv.tv_sec = 2; // Timeout of 2 seconds
    tv.tv_usec = 0;

    r = select(fd + 1, &fds, NULL, NULL, &tv);

    if (-1 == r) {
        fprintf(stderr, "select error: %s\n", strerror(errno));
        return -1;
    }

    if (0 == r) {
        fprintf(stderr, "select timeout\n");
        return -1;
    }

    CLEAR(buf);
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;

    if (-1 == xioctl(fd, VIDIOC_DQBUF, &buf)) {
        fprintf(stderr, "VIDIOC_DQBUF error: %s\n", strerror(errno));
        return -1;
    }

    return buf.index;
}

static int save_pgm(const char *filename, const void *data, int width, int height)
{
    FILE *fp = fopen(filename, "wb");

    if (!fp) {
        fprintf(stderr, "Cannot open '%s' for writing: %s\n", filename, strerror(errno));
        return -1;
    }

    fprintf(fp, "P5\n%d %d\n255\n", width, height);
    fwrite(data, 1, width * height, fp);
    fclose(fp);

    return 0;
}

static int uninit_device(int fd)
{
    unsigned int i;

    for (i = 0; i < n_buffers; ++i) {
        if (-1 == munmap(buffers[i].start, buffers[i].length)) {
            fprintf(stderr, "munmap error: %s\n", strerror(errno));
            return -1;
        }
    }

    free(buffers);

    return 0;
}

static int close_device(int fd)
{
    if (-1 == close(fd)) {
        fprintf(stderr, "close error: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

int main(int argc, char *argv[])
{
    const char *device_name = "/dev/video0";

    if (argc > 1) {
        device_name = argv[1];
    }

    signal(SIGINT,  signal_handler);
    signal(SIGTERM, signal_handler);

    fd = open_device(device_name);

    if (-1 == fd) {
        return EXIT_FAILURE;
    }

    if (-1 == init_device(fd)) {
        close_device(fd);
        return EXIT_FAILURE;
    }

    if (-1 == start_capturing(fd)) {
        uninit_device(fd);
        close_device(fd);
        return EXIT_FAILURE;
    }

    while (running) {
        int buffer_index = dequeue_buffer(fd);

        if (-1 == buffer_index) {
            break;
        }

        char filename[64];
        snprintf(filename, sizeof(filename), "image_%04d.pgm", ++frame_number);

        if (-1 == save_pgm(filename, buffers[buffer_index].start, 640, 480)) {
            fprintf(stderr, "Failed to save PGM file.\n");
            break;
        }
    }

    if (-1 == stop_capturing(fd)) {
        fprintf(stderr, "Failed to stop capturing.\n");
    }

    if (-1 == uninit_device(fd)) {
        fprintf(stderr, "Failed to uninitialize device.\n");
    }

    if (-1 == close_device(fd)) {
        fprintf(stderr, "Failed to close device.\n");
    }

    return EXIT_SUCCESS;
}

