#define HEIGHT 480
#define NUM_BUFFERS 4

// Global variables for signal handling
volatile sig_atomic_t stop_flag = 0;
int fd = -1;

// Structure to hold frame buffer information
struct buffer {
    void   *start;
    size_t  length;
};

struct buffer *buffers = NULL;
size_t n_buffers = 0;

// Signal handler function
void signal_handler(int sig) {
    fprintf(stderr, "Caught signal %d, exiting gracefully.\n", sig);
    stop_flag = 1;
}

// Function to initialize the V4L2 device
int init_v4l2(int *fd) {
    struct v4l2_capability cap;
    struct v4l2_format fmt;
    struct v4l2_requestbuffers req;
    struct v4l2_buffer buf;
    int i;

    // Open the device
    *fd = open(DEVICE_NAME, O_RDWR | O_NONBLOCK, 0);
    if (*fd < 0) {
        fprintf(stderr, "Error opening device %s: %s\n", DEVICE_NAME, strerror(errno));
        return -1;
    }

    // Check capabilities
    if (ioctl(*fd, VIDIOC_QUERYCAP, &cap) < 0) {
        fprintf(stderr, "Error querying capabilities: %s\n", strerror(errno));
        close(*fd);
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "Device does not support video capture\n");
        close(*fd);
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "Device does not support streaming\n");
        close(*fd);
        return -1;
    }

    // Set format
    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = WIDTH;
    fmt.fmt.pix.height = HEIGHT;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_MJPEG;
    fmt.fmt.pix.field = V4L2_FIELD_NONE;

    if (ioctl(*fd, VIDIOC_S_FMT, &fmt) < 0) {
        fprintf(stderr, "Error setting format: %s\n", strerror(errno));
        close(*fd);
        return -1;
    }

    // Request buffers
    memset(&req, 0, sizeof(req));
    req.count = NUM_BUFFERS;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (ioctl(*fd, VIDIOC_REQBUFS, &req) < 0) {
        fprintf(stderr, "Error requesting buffers: %s\n", strerror(errno));
        close(*fd);
        return -1;
    }

    if (req.count < NUM_BUFFERS) {
        fprintf(stderr, "Insufficient buffer memory\n");
        close(*fd);
        return -1;
    }

    buffers = calloc(req.count, sizeof(*buffers));
    if (!buffers) {
        fprintf(stderr, "Out of memory\n");
        close(*fd);
        return -1;
    }

    n_buffers = req.count;

    // Map the buffers
    for (i = 0; i < n_buffers; ++i) {
        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = i;

        if (ioctl(*fd, VIDIOC_QUERYBUF, &buf) < 0) {
            fprintf(stderr, "Error querying buffer %d: %s\n", i, strerror(errno));
            close(*fd);
            free(buffers);
            return -1;
        }

        buffers[i].length = buf.length;
        buffers[i].start = mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, *fd, buf.m.offset);

        if (buffers[i].start == MAP_FAILED) {
            fprintf(stderr, "Error mapping buffer %d: %s\n", i, strerror(errno));
            close(*fd);
            free(buffers);
            return -1;
        }
    }

    // Queue the buffers
    for (i = 0; i < n_buffers; ++i) {
        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = i;

        if (ioctl(*fd, VIDIOC_QBUF, &buf) < 0) {
            fprintf(stderr, "Error queuing buffer %d: %s\n", i, strerror(errno));
            close(*fd);
            free(buffers);
            return -1;
        }
    }

    // Start streaming
    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (ioctl(*fd, VIDIOC_STREAMON, &type) < 0) {
        fprintf(stderr, "Error starting stream: %s\n", strerror(errno));
        close(*fd);
        free(buffers);
        return -1;
    }

    return 0;
}

// Function to capture a frame
int capture_frame(int fd, struct timeval *tv) {
    struct v4l2_buffer buf;
    int i;

    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;

    if (ioctl(fd, VIDIOC_DQBUF, &buf) < 0) {
        fprintf(stderr, "Error dequeuing buffer: %s\n", strerror(errno));
        return -1;
    }

    // Get timestamp
    if (ioctl(fd, VIDIOC_G_FRAME_TIMESTAMP, tv) < 0) {
        fprintf(stderr, "Error getting frame timestamp: %s\n", strerror(errno));
        return -1;
    }

    // Log timestamp
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return -1;
    }

    fprintf(fp, "%ld.%06ld\n", tv->tv_sec, tv->tv_usec);
    fclose(fp);

    // Re-queue the buffer
    if (ioctl(fd, VIDIOC_QBUF, &buf) < 0) {
        fprintf(stderr, "Error queuing buffer: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

// Function to stop the V4L2 device
int stop_v4l2(int fd) {
    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;

    if (ioctl(fd, VIDIOC_STREAMOFF, &type) < 0) {
        fprintf(stderr, "Error stopping stream: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

// Function to unmap the buffers
int unmap_buffers(struct buffer *buffers, size_t n_buffers) {
    size_t i;

    for (i = 0; i < n_buffers; ++i) {
        if (munmap(buffers[i].start, buffers[i].length) < 0) {
            fprintf(stderr, "Error unmapping buffer %zu: %s\n", i, strerror(errno));
            return -1;
        }
    }

    return 0;
}

// Function to release the buffers
int release_buffers(struct buffer *buffers, size_t n_buffers) {
    free(buffers);
    return 0;
}

// Function to close the device
int close_device(int fd) {
    if (close(fd) < 0) {
        fprintf(stderr, "Error closing device: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int main() {
    fd_set rfds;
    struct timeval tv;
    int ret;

    // Install signal handler
    signal(SIGINT, signal_handler);

    // Initialize V4L2
    if (init_v4l2(&fd) < 0) {
        fprintf(stderr, "V4L2 initialization failed\n");
        return 1;
    }

    // Main loop
    while (!stop_flag) {
        // Set up select()
        FD_ZERO(&rfds);
        FD_SET(fd, &rfds);
        tv.tv_sec = 1; // Timeout of 1 second
        tv.tv_usec = 0;

        // Wait for data or timeout
        ret = select(fd + 1, &rfds, NULL, NULL, &tv);

        if (ret < 0) {
            fprintf(stderr, "Error in select(): %s\n", strerror(errno));
            break;
        } else if (ret == 0) {
            // Timeout occurred, but we still want to process any available frames
            continue;
        } else {
            // Data is available
            if (capture_frame(fd, &tv) < 0) {
                fprintf(stderr, "Frame capture failed\n");
                break;
            }
        }
    }

    // Stop V4L2
    if (stop_v4l2(fd) < 0) {
        fprintf(stderr, "V4L2 stop failed\n");
    }

    // Unmap buffers
    if (unmap_buffers(buffers, n_buffers) < 0) {
        fprintf(stderr, "Buffer unmap failed\n");
    }

    // Release buffers
    if (release_buffers(buffers, n_buffers) < 0) {
        fprintf(stderr, "Buffer release failed\n");
    }

    // Close device
    if (close_device(fd) < 0) {
        fprintf(stderr, "Device close failed\n");
    }

    return 0;
}

