// Global variables for signal handling
static int fd = -1;
static struct v4l2_buffer *buffers = NULL;
static size_t num_buffers = 0;
static volatile sig_atomic_t stop_flag = 0;

// Signal handler function
static void signal_handler(int sig)
{
