#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins
#define PAN_PIN 4
#define TILT_PIN 5
#define TILT_UP_PIN 6
#define TILT_DOWN_PIN 7
#define PAN_LEFT_PIN 8
#define PAN_RIGHT_PIN 9

// Define PWM frequency and duty cycle range
#define PWM_FREQUENCY 50
#define DUTY_CYCLE_RANGE 1000

// Define servo position limits
#define MIN_POSITION 25
#define MAX_POSITION 125

// Global variables for servo positions
int pan_position = 75;
int tilt_position = 75;

// Function prototypes
void set_servo_position(int gpio, int position);
void tilt_up();
void tilt_down();
void pan_left();
void pan_right();
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    gpioTerminate();
    exit(0);
}

// Function to set the servo position using software PWM
void set_servo_position(int gpio, int position) {
    // Clamp the position to the valid range
    if (position < MIN_POSITION) {
        position = MIN_POSITION;
    } else if (position > MAX_POSITION) {
        position = MAX_POSITION;
    }

    // Calculate the duty cycle
    int duty_cycle = (int)(((float)(position - MIN_POSITION) / (MAX_POSITION - MIN_POSITION)) * DUTY_CYCLE_RANGE);

    // Set the PWM duty cycle
    gpioPWM(gpio, duty_cycle);
}

// Function to move the tilt up
void tilt_up() {
    tilt_position += 5;
    if (tilt_position > MAX_POSITION) {
        tilt_position = MAX_POSITION;
    }
    set_servo_position(TILT_PIN, tilt_position);
}

// Function to move the tilt down
void tilt_down() {
    tilt_position -= 5;
    if (tilt_position < MIN_POSITION) {
        tilt_position = MIN_POSITION;
    }
    set_servo_position(TILT_PIN, tilt_position);
}

// Function to move the pan left
void pan_left() {
    pan_position -= 5;
    if (pan_position < MIN_POSITION) {
        pan_position = MIN_POSITION;
    }
    set_servo_position(PAN_PIN, pan_position);
}

// Function to move the pan right
void pan_right() {
    pan_position += 5;
    if (pan_position > MAX_POSITION) {
        pan_position = MAX_POSITION;
    }
    set_servo_position(PAN_PIN, pan_position);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(PAN_PIN, PI_OUTPUT);
    gpioSetMode(TILT_PIN, PI_OUTPUT);
    gpioSetMode(TILT_UP_PIN, PI_INPUT);
    gpioSetMode(TILT_DOWN_PIN, PI_INPUT);
    gpioSetMode(PAN_LEFT_PIN, PI_INPUT);
    gpioSetMode(PAN_RIGHT_PIN, PI_INPUT);

    // Enable pull-up resistors on input pins
    gpioSetPullUpDown(TILT_UP_PIN, PI_PUD_UP);
    gpioSetPullUpDown(TILT_DOWN_PIN, PI_PUD_UP);
    gpioSetPullUpDown(PAN_LEFT_PIN, PI_PUD_UP);
    gpioSetPullUpDown(PAN_RIGHT_PIN, PI_PUD_UP);

    // Set PWM frequency
    gpioSetPWMfrequency(PAN_PIN, PWM_FREQUENCY);
    gpioSetPWMfrequency(TILT_PIN, PWM_FREQUENCY);

    // Set initial servo positions
    set_servo_position(PAN_PIN, pan_position);
    set_servo_position(TILT_PIN, tilt_position);

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (1) {
        // Check for button presses
        if (gpioRead(TILT_UP_PIN) == 0) {
            tilt_up();
            gpioDelay(200); // Debounce delay
        }
        if (gpioRead(TILT_DOWN_PIN) == 0) {
            tilt_down();
            gpioDelay(200); // Debounce delay
        }
        if (gpioRead(PAN_LEFT_PIN) == 0) {
            pan_left();
            gpioDelay(200); // Debounce delay
        }
        if (gpioRead(PAN_RIGHT_PIN) == 0) {
            pan_right();
            gpioDelay(200); // Debounce delay
        }

        // Small delay to prevent busy-waiting
        gpioDelay(50);
    }

    return 0;
}

