#include <stdio.h>
#include <stdlib.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/videodev2.h>
#include <string.h>

#define DEVICE_NAME "/dev/video0"

// Function to open the video device
int open_device(const char *device_name) {
    int fd = open(device_name, O_RDWR);
    if (fd == -1) {
        perror("Error opening device");
        return -1;
    }
    return fd;
}

// Function to query device capabilities
int query_capabilities(int fd) {
    struct v4l2_capability cap;
    if (ioctl(fd, VIDIOC_QUERYCAP, &cap) == -1) {
        perror("Error querying capabilities");
        return -1;
    }
    printf("Driver: %s\n", cap.driver);
    printf("Card: %s\n", cap.card);
    printf("Bus Info: %s\n", cap.bus_info);
    printf("Version: %u\n", cap.version);
    printf("Capabilities: 0x%x\n", cap.capabilities);
    return 0;
}

// Function to enumerate frame sizes
int enumerate_frame_sizes(int fd) {
    struct v4l2_fmtdesc fmtdesc;
    struct v4l2_frmsizeenum frmsize;
    int i;

    // Enumerate formats
    fmtdesc.index = 0;
    fmtdesc.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    while (ioctl(fd, VIDIOC_ENUM_FMT, &fmtdesc) == 0) {
        printf("Format: %s\n", fmtdesc.description);

        // Enumerate frame sizes for the format
        frmsize.index = 0;
        frmsize.pixel_format = fmtdesc.pixelformat;
        frmsize.output = 1; // Request supported output sizes
        while (ioctl(fd, VIDIOC_ENUM_FRAMESIZES, &frmsize) == 0) {
            if (frmsize.type == V4L2_FRMSIZE_TYPE_DISCRETE) {
                printf("  Size: %dx%d\n", frmsize.discrete.width, frmsize.discrete.height);
            }
            frmsize.index++;
        }
        fmtdesc.index++;
    }
    return 0;
}

// Function to enumerate frame intervals
int enumerate_frame_intervals(int fd) {
    struct v4l2_frmivalenum frmival;
    int i;

    // Enumerate frame intervals
    frmival.index = 0;
    frmival.pixel_format = V4L2_PIX_FMT_JPEG; // Example format
    frmival.width = 640; // Example width
    frmival.height = 480; // Example height
    frmival.output = 1; // Request supported output intervals
    while (ioctl(fd, VIDIOC_ENUM_FRAMEINTERVALS, &frmival) == 0) {
        printf("  Interval: %d/%d\n", frmival.interval.numerator, frmival.interval.denominator);
        frmival.index++;
    }
    return 0;
}

// Function to query autofocus support
int query_autofocus_support(int fd) {
    struct v4l2_control control;
    struct v4l2_queryctrl query;

    query.id = V4L2_CID_FOCUS_AUTO;
    if (ioctl(fd, VIDIOC_QUERYCTRL, &query) == -1) {
        perror("Error querying autofocus control");
        return -1;
    }

    if (query.flags & V4L2_CTRL_FLAG_DISABLED) {
        printf("Autofocus: Not supported\n");
        return -1;
    }

    control.id = V4L2_CID_FOCUS_AUTO;
    if (ioctl(fd, VIDIOC_QUERYCTRL, &query) == -1) {
        perror("Error querying autofocus control");
        return -1;
    }

    if (query.flags & V4L2_CTRL_FLAG_DISABLED) {
        printf("Autofocus: Not supported\n");
        return -1;
    }

    printf("Autofocus: Supported\n");
    return 0;
}

int main() {
    int fd = open_device(DEVICE_NAME);
    if (fd == -1) {
        return 1;
    }

    if (query_capabilities(fd) == -1) {
        close(fd);
        return 1;
    }

    if (query_autofocus_support(fd) == -1) {
        close(fd);
        return 1;
    }

    if (enumerate_frame_sizes(fd) == -1) {
        close(fd);
        return 1;
    }

    if (enumerate_frame_intervals(fd) == -1) {
        close(fd);
        return 1;
    }

    close(fd);
    return 0;
}

