#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins
#define PAN_PIN 4
#define TILT_PIN 5
#define UP_PIN 6
#define DOWN_PIN 7
#define LEFT_PIN 8
#define RIGHT_PIN 9

// Define PWM frequency
#define PWM_FREQUENCY 50

// Define pulse width limits
#define MIN_PULSE_WIDTH 1000
#define MAX_PULSE_WIDTH 2000

// Define increment/decrement value
#define STEP_SIZE 10

// Global variables for current pulse widths
int pan_pulse_width = 1500;
int tilt_pulse_width = 1500;

// Function prototypes
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    gpioServo(PAN_PIN, 0); // Stop PWM on pan servo
    gpioServo(TILT_PIN, 0); // Stop PWM on tilt servo
    gpioTerminate(); // Terminate pigpio
    exit(0); // Exit program
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Configure GPIO pins
    gpioSetMode(PAN_PIN, PI_OUTPUT);
    gpioSetMode(TILT_PIN, PI_OUTPUT);
    gpioSetMode(UP_PIN, PI_INPUT);
    gpioSetMode(DOWN_PIN, PI_INPUT);
    gpioSetMode(LEFT_PIN, PI_INPUT);
    gpioSetMode(RIGHT_PIN, PI_INPUT);

    // Enable internal pull-up resistors on button pins
    gpioSetPullUpDown(UP_PIN, PI_PUD_UP);
    gpioSetPullUpDown(DOWN_PIN, PI_PUD_UP);
    gpioSetPullUpDown(LEFT_PIN, PI_PUD_UP);
    gpioSetPullUpDown(RIGHT_PIN, PI_PUD_UP);

    // Set PWM frequency for servos
    gpioSetPWMfrequency(PAN_PIN, PWM_FREQUENCY);
    gpioSetPWMfrequency(TILT_PIN, PWM_FREQUENCY);

    // Initialize servos to center position
    gpioServo(PAN_PIN, pan_pulse_width);
    gpioServo(TILT_PIN, tilt_pulse_width);

    printf("Pan Servo: GPIO%d, Tilt Servo: GPIO%d, Center Position: 1500us\n", PAN_PIN, TILT_PIN);

    // Install signal handler for Ctrl+C
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (1) {
        // Check for button presses
        if (gpioRead(UP_PIN) == 0) {
            tilt_pulse_width += STEP_SIZE;
            if (tilt_pulse_width > MAX_PULSE_WIDTH) {
                tilt_pulse_width = MAX_PULSE_WIDTH;
            }
            gpioServo(TILT_PIN, tilt_pulse_width);
        } else if (gpioRead(DOWN_PIN) == 0) {
            tilt_pulse_width -= STEP_SIZE;
            if (tilt_pulse_width < MIN_PULSE_WIDTH) {
                tilt_pulse_width = MIN_PULSE_WIDTH;
            }
            gpioServo(TILT_PIN, tilt_pulse_width);
        } else if (gpioRead(LEFT_PIN) == 0) {
            pan_pulse_width -= STEP_SIZE;
            if (pan_pulse_width < MIN_PULSE_WIDTH) {
                pan_pulse_width = MIN_PULSE_WIDTH;
            }
            gpioServo(PAN_PIN, pan_pulse_width);
        } else if (gpioRead(RIGHT_PIN) == 0) {
            pan_pulse_width += STEP_SIZE;
            if (pan_pulse_width > MAX_PULSE_WIDTH) {
                pan_pulse_width = MAX_PULSE_WIDTH;
            }
            gpioServo(PAN_PIN, pan_pulse_width);
        }

        // Delay for 50ms
        gpioDelay(50000); // 50ms = 50000 microseconds
    }

    return 0;
}

