#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <errno.h>
#include <pigpio.h>
#include <curl/curl.h>

#define PIR_GPIO 17
#define DEBOUNCE_TIME 2000 // milliseconds
#define CAPTURE_DIR "motion_captures"
#define SERVER_IP "127.0.0.1" // Replace with your server IP
#define SERVER_PORT 8080

volatile sig_atomic_t program_running = 1;

void signal_handler(int signal) {
    program_running = 0;
    fprintf(stderr, "\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to capture a timestamped JPEG image using libcamera-still
int capture_image(char *filename) {
    char command[256];
    snprintf(command, sizeof(command), "libcamera-still -o %s --width 640 --height 480 --quality 85", filename);
    int status = system(command);
    if (status == -1) {
        fprintf(stderr, "Error executing libcamera-still command: %s\n", strerror(errno));
        return -1;
    }
    if (WIFEXITED(status) && WEXITSTATUS(status) != 0) {
        fprintf(stderr, "libcamera-still command failed with exit status %d\n", WEXITSTATUS(status));
        return -1;
    }
    return 0;
}

// Function to create the motion_captures directory if it doesn't exist
int create_capture_directory() {
    if (mkdir(CAPTURE_DIR, 0777) == -1) {
        if (errno != EEXIST) {
            fprintf(stderr, "Error creating directory %s: %s\n", CAPTURE_DIR, strerror(errno));
            return -1;
        }
        fprintf(stderr, "Directory %s already exists.\n", CAPTURE_DIR);
    }
    return 0;
}

// Function to generate a filename with a timestamp
int generate_filename(char *filename, size_t filename_size) {
    time_t rawtime;
    struct tm *timeinfo;
    struct timespec ts;

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    clock_gettime(CLOCK_REALTIME, &ts);

    strftime(filename, filename_size, CAPTURE_DIR "/%Y%m%d_%H%M%S", timeinfo);
    snprintf(filename + strlen(filename), filename_size - strlen(filename), "_%06ld.jpg", ts.tv_nsec / 1000);

    return 0;
}

// Function to send a JSON payload to the server using libcurl
int send_json_payload(const char *filename, const char *timestamp, int motion_status, int gpio_pin) {
    CURL *curl;
    CURLcode res;
    char json_payload[256];

    snprintf(json_payload, sizeof(json_payload), "{\"filename\": \"%s\", \"timestamp\": \"%s\", \"motion_status\": %d, \"gpio_pin\": %d}", filename, timestamp, motion_status, gpio_pin);

    curl_global_init(CURL_GLOBAL_DEFAULT);
    curl = curl_easy_init();
    if (curl) {
        char url[256];
        snprintf(url, sizeof(url), "http://%s:%d/upload", SERVER_IP, SERVER_PORT);

        curl_easy_setopt(curl, CURLOPT_URL, url);
        curl_easy_setopt(curl, CURLOPT_POSTFIELDS, json_payload);
        curl_easy_setopt(curl, CURLOPT_POSTFIELDSIZE, (long)strlen(json_payload));

        res = curl_easy_perform(curl);
        if (res != CURLE_OK) {
            fprintf(stderr, "curl_easy_perform() failed: %s\n", curl_easy_strerror(res));
        } else {
            long response_code;
            curl_easy_getinfo(curl, CURLINFO_RESPONSE_CODE, &response_code);
            if (response_code >= 400) {
                fprintf(stderr, "HTTP request failed with status code: %ld\n", response_code);
            }
        }

        curl_easy_cleanup(curl);
    } else {
        fprintf(stderr, "curl_easy_init() failed\n");
        curl_global_cleanup();
        return -1;
    }
    curl_global_cleanup();
    return 0;
}

int main(int argc, char *argv[]) {
    if (argc != 3) {
        fprintf(stderr, "Usage: %s <server_ip> <server_port>\n", argv[0]);
        return 1;
    }

    SERVER_IP = argv[1];
    SERVER_PORT = atoi(argv[2]);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(PIR_GPIO, PI_INPUT);
    gpioSetPullUpDown(PIR_GPIO, PI_PUD_DOWN);

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    if (create_capture_directory() != 0) {
        gpioTerminate();
        return 1;
    }

    int last_motion_time = 0;

    while (program_running) {
        int motion_detected = gpioRead(PIR_GPIO);

        if (motion_detected) {
            time_t rawtime;
            struct tm *timeinfo;
            struct timespec ts;
            char filename[256];
            char timestamp[32];

            time(&rawtime);
            timeinfo = localtime(&rawtime);
            clock_gettime(CLOCK_REALTIME, &ts);

            strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", timeinfo);
            snprintf(timestamp + strlen(timestamp), sizeof(timestamp) - strlen(timestamp), ".%06ldZ", ts.tv_nsec / 1000);

            generate_filename(filename, sizeof(filename));

            if (capture_image(filename) == 0) {
                printf("Captured image: %s\n", filename);
                if (send_json_payload(filename, timestamp, 1, PIR_GPIO) != 0) {
                    fprintf(stderr, "Failed to send JSON payload\n");
                }
            } else {
                fprintf(stderr, "Failed to capture image\n");
            }

            last_motion_time = time(NULL);
        }

        gpioDelay(100); // Poll every 100 ms

        if (time(NULL) - last_motion_time >= DEBOUNCE_TIME / 1000) {
            // Reset debounce timer after the debounce period
        }
    }

    gpioTerminate();
    return 0;
}

