#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>
#include <errno.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_PIN 17
#define DEBOUNCE_DELAY_MS 50
#define IMAGE_DIR "/home/pi/images"
#define LOG_FILE "/home/pi/motion_capture.log"

static volatile int keep_running = 1;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *line = NULL;
static FILE *log_file = NULL;

// Function to handle signals (SIGINT, SIGTERM)
void signal_handler(int sig)
{
    keep_running = 0;
    fprintf(stderr, "\nCaught signal %d, exiting gracefully...\n", sig);
}

// Function to log events to a file
void log_event(const char *message)
{
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (log_file != NULL) {
        fprintf(log_file, "%s: %s\n", timestamp, message);
        fflush(log_file); // Ensure the log is written immediately
    } else {
        fprintf(stderr, "Error: Log file not opened. Message: %s\n", message);
    }
}

// Function to generate a timestamped filename
int generate_filename(char *filename, size_t filename_size)
{
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);

    if (strftime(filename, filename_size, "%Y%m%d_%H%M%S_%03ld.jpg", t) == 0) {
        fprintf(stderr, "Error: strftime failed\n");
        return -1;
    }

    return 0;
}

// Function to capture an image using libcamera-still
int capture_image(const char *filename)
{
    char command[256];
    snprintf(command, sizeof(command), "libcamera-still -o %s --width 640 --height 480 -q 85 --timeout 2000 --nopreview", filename);

    int status = system(command);
    if (status == -1) {
        fprintf(stderr, "Error: system() failed\n");
        return -1;
    }

    if (WIFEXITED(status) && WEXITSTATUS(status) != 0) {
        fprintf(stderr, "Error: libcamera-still exited with status %d\n", WEXITSTATUS(status));
        return -1;
    }

    return 0;
}

int main()
{
    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open the log file
