#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <linux/videodev2.h>
#include <errno.h>
#include <signal.h>
#include <time.h>
#include <sys/select.h>

#define DEVICE_NAME "/dev/video0"
#define WIDTH 640
#define HEIGHT 480
#define CROP_X 100
#define CROP_Y 50
#define CROP_WIDTH 200
#define CROP_HEIGHT 150
#define FRAME_TIMEOUT_SEC 2

// Structure to hold V4L2 buffer information
struct v4l2_buffer {
    unsigned int index;
    unsigned int bytesused;
    enum v4l2_buf_type type;
    unsigned long physical;
    struct v4l2_timestamp timestamp;
    long buffer;
    unsigned int flags;
};

// Global variables
int fd = -1;
struct v4l2_buffer *buffers = NULL;
unsigned int n_buffers = 0;

// Function prototypes
int init_v4l2_device(const char *device_name);
int configure_v4l2_device(int fd);
int capture_frame(int fd, struct v4l2_buffer *buffer);
int crop_frame(const unsigned char *frame, int width, int height, int crop_x, int crop_y, int crop_width, int crop_height, unsigned char *cropped_frame);
int save_cropped_frame(const unsigned char *cropped_frame, int cropped_width, int cropped_height, const char *filename);
void signal_handler(int sig);

// Signal handler function
void signal_handler(int sig) {
    printf("Caught signal %d, cleaning up...\n", sig);
    if (buffers != NULL) {
        munmap(buffers, n_buffers * sizeof(struct v4l2_buffer));
    }
    if (fd != -1) {
        close(fd);
    }
    exit(EXIT_SUCCESS);
}

// Initialize V4L2 device
int init_v4l2_device(const char *device_name) {
    fd = open(device_name, O_RDWR | O_NONBLOCK, 0);
    if (fd == -1) {
        perror("Error opening device");
        return -1;
    }

    struct v4l2_capability cap;
    if (ioctl(fd, VIDIOC_QUERYCAP, &cap) == -1) {
        perror("Error querying capabilities");
        close(fd);
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "%s is not a video capture device\n", device_name);
        close(fd);
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "%s does not support streaming i/o\n", device_name);
        close(fd);
        return -1;
    }

    return 0;
}

// Configure V4L2 device
int configure_v4l2_device(int fd) {
    struct v4l2_format fmt;
    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = WIDTH;
    fmt.fmt.pix.height = HEIGHT;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_YUYV;
    fmt.fmt.pix.field = V4L2_FIELD_NONE;

    if (ioctl(fd, VIDIOC_S_FMT, &fmt) == -1) {
        perror("Error setting format");
        return -1;
    }

    struct v4l2_requestbuffers req;
    memset(&req, 0, sizeof(req));
    req.count = 1; // Single buffer for simplicity
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (ioctl(fd, VIDIOC_REQBUFS, &req) == -1) {
        perror("Error requesting buffers");
        return -1;
    }

    buffers = calloc(req.count, sizeof(struct v4l2_buffer));
    if (!buffers) {
        perror("Out of memory");
        return -1;
    }

    for (unsigned int i = 0; i < req.count; ++i) {
        struct v4l2_buffer buf;
        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = i;

        if (ioctl(fd, VIDIOC_QUERYBUF, &buf) == -1) {
            perror("Error querying buffer");
            return -1;
        }

        buffers[i].length = buf.length;
        buffers[i].start = mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf.m.offset);

        if (buffers[i].start == MAP_FAILED) {
            perror("Error mapping buffer");
            return -1;
        }
    }

    for (unsigned int i = 0; i < n_buffers; ++i) {
        if (ioctl(fd, VIDIOC_QBUF, &buffers[i]) == -1) {
            perror("Error queuing buffer");
            return -1;
        }
    }

    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (ioctl(fd, VIDIOC_STREAMON, &type) == -1) {
        perror("Error starting stream");
        return -1;
    }

    return 0;
}

// Capture a single frame
int capture_frame(int fd, struct v4l2_buffer *buffer) {
    fd_set fds;
    struct timeval tv;
    int r;

    FD_ZERO(&fds);
    FD_SET(fd, &fds);

    tv.tv_sec = FRAME_TIMEOUT_SEC;
    tv.tv_usec = 0;

    r = select(fd + 1, &fds, NULL, NULL, &tv);

    if (r == -1) {
        perror("select()");
        return -1;
    } else if (r == 0) {
        fprintf(stderr, "Timeout waiting for frame\n");
        return -1;
    }

    if (ioctl(fd, VIDIOC_DQBUF, buffer) == -1) {
        perror("Error dequeueing buffer");
        return -1;
    }

    return 0;
}

// Crop the frame
int crop_frame(const unsigned char *frame, int width, int height, int crop_x, int crop_y, int crop_width, int crop_height, unsigned char *cropped_frame) {
    int frame_size = width * height * 2; // YUYV is 2 bytes per pixel
    int cropped_size = crop_width * crop_height * 2;

    // Calculate the starting position in the original frame
    int start_pos = (crop_y * width + crop_x) * 2; // YUYV is 2 bytes per pixel

    // Copy the cropped region
    for (int y = 0; y < crop_height; y++) {
        for (int x = 0; x < crop_width; x++) {
            cropped_frame[(y * crop_width + x) * 2] = frame[start_pos + (y * width + x) * 2]; // Y
            cropped_frame[(y * crop_width + x) * 2 + 1] = frame[start_pos + (y * width + x) * 2 + 1]; // U
            cropped_frame[(y * crop_width + x) * 2 + 2] = frame[start_pos + (y * width + x) * 2 + 2]; // Y
            cropped_frame[(y * crop_width + x) * 2 + 3] = frame[start_pos + (y * width + x) * 2 + 3]; // V
        }
    }

    return 0;
}

// Save the cropped frame to a file
int save_cropped_frame(const unsigned char *cropped_frame, int cropped_width, int cropped_height, const char *filename) {
    FILE *fp = fopen(filename, "wb");
    if (!fp) {
        perror("Error opening file for writing");
        return -1;
    }

    size_t bytes_written = fwrite(cropped_frame, 1, cropped_width * cropped_height * 2, fp);
    if (bytes_written != cropped_width * cropped_height * 2) {
        perror("Error writing to file");
        fclose(fp);
        return -1;
    }

    fclose(fp);
    return 0;
}

int main() {
    // Install signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize V4L2 device
    if (init_v4l2_device(DEVICE_NAME) == -1) {
        return EXIT_FAILURE;
    }

    // Configure V4L2 device
    if (configure_v4l2_device(fd) == -1) {
        close(fd);
        return EXIT_FAILURE;
    }

    struct v4l2_buffer buffer;

    // Capture frame
    if (capture_frame(fd, &buffer) == -1) {
        munmap(buffers, n_buffers * sizeof(struct v4l2_buffer));
        close(fd);
        return EXIT_FAILURE;
    }

    // Crop the frame
    unsigned char *cropped_frame = malloc(CROP_WIDTH * CROP_HEIGHT * 2);
    if (!cropped_frame) {
        perror("Out of memory");
        munmap(buffers, n_buffers * sizeof(struct v4l2_buffer));
        close(fd);
        return EXIT_FAILURE;
    }

    if (crop_frame(buffers[0].start, WIDTH, HEIGHT, CROP_X, CROP_Y, CROP_WIDTH, CROP_HEIGHT, cropped_frame) == -1) {
        free(cropped_frame);
        munmap(buffers, n_buffers * sizeof(struct v4l2_buffer));
        close(fd);
        return EXIT_FAILURE;
    }

    // Save the cropped frame
    if (save_cropped_frame(cropped_frame, CROP_WIDTH, CROP_HEIGHT, "cropped.yuv") == -1) {
        free(cropped_frame);
        munmap(buffers, n_buffers * sizeof(struct v4l2_buffer));
        close(fd);
        return EXIT_FAILURE;
    }

    // Clean up
    free(cropped_frame);
    munmap(buffers, n_buffers * sizeof(struct v4l2_buffer));
    close(fd);

    printf("Cropped frame saved to cropped.yuv\n");

    return EXIT_SUCCESS;
}

