#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// Define GPIO pins for pan and tilt servos
#define PAN_GPIO 17
#define TILT_GPIO 18

// Define PWM frequency
#define PWM_FREQUENCY 50

// Define pulse width limits (microseconds)
#define MIN_PULSE_WIDTH 500
#define MAX_PULSE_WIDTH 2500

// Define angle limits (degrees)
#define MIN_ANGLE 0
#define MAX_ANGLE 180

// Global variables for current pan and tilt angles
int pan_angle = 90;
int tilt_angle = 90;

// Function prototypes
int set_servo_angle(int gpio, int angle);
int get_user_input();
void signal_handler(int signal);

// Function to set the servo angle using pigpio's hardware PWM
int set_servo_angle(int gpio, int angle) {
    // Validate angle input
    if (angle < MIN_ANGLE || angle > MAX_ANGLE) {
        fprintf(stderr, "Error: Angle out of range (0-180).\n");
        return -1; // Indicate failure
    }

    // Calculate pulse width based on angle
    int pulse_width = MIN_PULSE_WIDTH + (int)(((float)(angle - MIN_ANGLE) / (MAX_ANGLE - MIN_ANGLE)) * (MAX_PULSE_WIDTH - MIN_PULSE_WIDTH));

    // Set the servo pulse width
    if (gpioServo(gpio, pulse_width) != 0) {
        fprintf(stderr, "Error: Failed to set servo pulse width for GPIO %d.\n", gpio);
        return -1; // Indicate failure
    }

    return 0; // Indicate success
}

// Function to get user input from stdin
int get_user_input() {
    int input;

    if (scanf("%d", &input) != 1) {
        // Handle invalid input (e.g., non-integer)
        fprintf(stderr, "Error: Invalid input. Please enter a number.\n");
        return -1; // Indicate error
    }

    return input;
}

// Signal handler for Ctrl+C (SIGINT)
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up and exiting...\n", signal);

    // Set both servos to the neutral position (90 degrees)
    if (set_servo_angle(PAN_GPIO, 90) != 0) {
        fprintf(stderr, "Error: Failed to set pan servo to neutral position.\n");
    }
    if (set_servo_angle(TILT_GPIO, 90) != 0) {
        fprintf(stderr, "Error: Failed to set tilt servo to neutral position.\n");
    }

    // Terminate pigpio
    gpioTerminate();

    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return 1; // Exit with error code
    }

    // Set PWM frequency for both servos
    gpioSetPWMfrequency(PAN_GPIO, PWM_FREQUENCY);
    gpioSetPWMfrequency(TILT_GPIO, PWM_FREQUENCY);

    // Set initial servo angles (neutral position)
    if (set_servo_angle(PAN_GPIO, pan_angle) != 0) {
        fprintf(stderr, "Error: Failed to set initial pan angle.\n");
        gpioTerminate();
        return 1;
    }
    if (set_servo_angle(TILT_GPIO, tilt_angle) != 0) {
        fprintf(stderr, "Error: Failed to set initial tilt angle.\n");
        gpioTerminate();
        return 1;
    }

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Pan-Tilt Camera Control\n");
    printf("Use arrow keys (up, down, left, right) to adjust angles.\n");
    printf("Press 'q' to quit.\n");

    // Main loop
    while (1) {
        int input = get_user_input();

        if (input == -1) {
            // Handle invalid input (e.g., non-integer)
            continue; // Skip to the next iteration
        }

        switch (input) {
            case 1073741906: // Left arrow key
                pan_angle -= 5;
                if (pan_angle < MIN_ANGLE) {
                    pan_angle = MIN_ANGLE;
                }
                if (set_servo_angle(PAN_GPIO, pan_angle) != 0) {
                    fprintf(stderr, "Error: Failed to set pan angle.\n");
                }
                break;
            case 1073741904: // Right arrow key
                pan_angle += 5;
                if (pan_angle > MAX_ANGLE) {
                    pan_angle = MAX_ANGLE;
                }
                if (set_servo_angle(PAN_GPIO, pan_angle) != 0) {
                    fprintf(stderr, "Error: Failed to set pan angle.\n");
                }
                break;
            case 1073741908: // Up arrow key
                tilt_angle -= 5;
                if (tilt_angle < MIN_ANGLE) {
                    tilt_angle = MIN_ANGLE;
                }
                if (set_servo_angle(TILT_GPIO, tilt_angle) != 0) {
                    fprintf(stderr, "Error: Failed to set tilt angle.\n");
                }
                break;
            case 1073741907: // Down arrow key
                tilt_angle += 5;
                if (tilt_angle > MAX_ANGLE) {
                    tilt_angle = MAX_ANGLE;
                }
                if (set_servo_angle(TILT_GPIO, tilt_angle) != 0) {
                    fprintf(stderr, "Error: Failed to set tilt angle.\n");
                }
                break;
            case 113: // 'q' key
                signal_handler(SIGINT); // Call signal handler to exit gracefully
                break;
            default:
                printf("Invalid input. Please use arrow keys or 'q' to quit.\n");
                break;
        }

        // Delay to prevent excessive CPU usage
        gpioDelay(100); // 100 milliseconds
    }

    return 0;
}

