// Function to initialize the OLED display
int oled_init() {
    unsigned char init_commands[] = {
        0xAE,       // Display off
        0xD5, 0x80, // Clock divide ratio (0x80 = 100Hz)
        0xA8, 0x3F, // Multiplex ratio (63 = 64 rows)
        0xD3, 0x00, // Display offset (0 = no offset)
        0x40,       // Start line
        0x8D, 0x14, // Charge pump enable
        0x20, 0x00, // Memory addressing mode (0x00 = horizontal)
        0xA1,       // Segment remap (A0 = normal)
        0xC8,       // COM scan direction (C0 = scan from COM[N-1] to COM0, C8 = scan from COM0 to COM[N-1])
        0xDA, 0x12, // COM pins hardware configuration
        0x81, 0xCF, // Contrast control
        0xD9, 0xF1, // Pre-charge period
        0xDB, 0x40, // VCOM deselect level
        0xA4,       // Entire display ON/OFF (A4 = normal, A5 = all ON)
        0xA6,       // Normal/Inverse display (A6 = normal, A7 = inverse)
        0xAF        // Display on
    };

    for (int i = 0; i < sizeof(init_commands); i++) {
        oled_write_command(init_commands[i]);
    }

    return 0;
}

// Function to clear the OLED display buffer
void oled_clear() {
    for (int i = 0; i < OLED_WIDTH * OLED_HEIGHT / 8; i++) {
        oled_write_data(0x00);
    }
}

// Function to write a command to the OLED display
void oled_write_command(unsigned char command) {
    unsigned char buf[2];
    buf[0] = 0x00; // Control byte: command
    buf[1] = command;

    if (write(i2c_fd, buf, 2) != 2) {
        fprintf(stderr, "Error writing command to I2C: %s\n", strerror(errno));
        terminate = 1; // Set termination flag on I2C error
    }
}

// Function to write data to the OLED display
void oled_write_data(unsigned char data) {
    unsigned char buf[2];
    buf[0] = 0x40; // Control byte: data
    buf[1] = data;

    if (write(i2c_fd, buf, 2) != 2) {
        fprintf(stderr, "Error writing data to I2C: %s\n", strerror(errno));
        terminate = 1; // Set termination flag on I2C error
    }
}

// Function to display a string on the OLED display
void oled_display_string(int x, int y, const char *str) {
    int i, j;
    for (i = 0; str[i] != '\0'; i++) {
        int char_index = str[i] - 32; // ASCII 32 is ' '
        if (char_index < 0 || char_index > 94) {
            char_index = 95; // Default to '~' if out of range
        }

        for (j = 0; j < 5; j++) {
            // Set pixel based on font data
            if ((font[char_index][j] & (1 << (4 - j))) > 0) {
                oled_set_pixel(x + i * 6, y + j, 1); // 6 pixels per character
            }
        }
    }
