#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define WIND_SPEED_GPIO 17
#define WIND_DIRECTION_SPI_CHANNEL 0
#define WIND_DIRECTION_SPI_SPEED 1000000 // 1 MHz
#define WIND_DIRECTION_SPI_MODE 0
#define LCD_I2C_ADDR 0x27
#define LCD_I2C_BUS 1
#define LCD_WIDTH 16
#define LCD_HEIGHT 2
#define WIND_SPEED_SCALE 0.5 // m/s per pulse
#define ADC_MAX_VALUE 1023
#define ADC_MIN_VALUE 0
#define DIRECTION_MAX_VALUE 359
#define DIRECTION_MIN_VALUE 0
#define SAMPLE_WINDOW_MS 500

// Global variables
volatile int pulse_count = 0;
int i2c_handle;
int spi_handle;

// Function prototypes
void pulse_callback(int gpio, int level, uint32_t tick, void *user);
float calculate_wind_speed(int pulse_count);
int read_wind_direction(int spi_handle);
void map_adc_to_direction(int adc_value);
void lcd_init(int i2c_handle);
void lcd_clear(int i2c_handle);
void lcd_print(int i2c_handle, int row, int col, const char *text);
void lcd_send_command(int i2c_handle, unsigned char command);
void lcd_send_data(int i2c_handle, unsigned char data);
void lcd_string(int i2c_handle, int row, int col, const char *string);
void signal_handler(int signal);

// LCD commands
#define LCD_CLEARDISPLAY 0x01
#define LCD_RETURNHOME 0x02
#define LCD_ENTRYMODESET 0x04
#define LCD_DISPLAYCONTROL 0x08
#define LCD_CURSORSHIFT 0x10
#define LCD_FUNCTIONSET 0x20

// LCD flags
#define LCD_ENTRYRIGHT 0x00
#define LCD_ENTRYLEFT 0x02
#define LCD_ENTRYSHIFTINCREMENT 0x01
#define LCD_ENTRYSHIFTDECREMENT 0x00

#define LCD_DISPLAYON 0x04
#define LCD_DISPLAYOFF 0x00
#define LCD_CURSORON 0x02
#define LCD_CURSOROFF 0x00
#define LCD_BLINKON 0x01
#define LCD_BLINKOFF 0x00

#define LCD_8BITMODE 0x10
#define LCD_4BITMODE 0x00
#define LCD_2LINE 0x08
#define LCD_1LINE 0x00
#define LCD_5x10DOTS 0x04
#define LCD_5x8DOTS 0x00

// Function to send a command to the LCD
void lcd_send_command(int i2c_handle, unsigned char command) {
    char data_u, data_l;
    data_u = (command & 0xF0);
    data_l = ((command << 4) & 0xF0);

    i2cWriteByte(i2c_handle, data_u | 0x0C); //en=1, rs=0
    gpioDelay(1);
    i2cWriteByte(i2c_handle, data_u | 0x08); //en=0, rs=0
    gpioDelay(1);

    i2cWriteByte(i2c_handle, data_l | 0x0C); //en=1, rs=0
    gpioDelay(1);
    i2cWriteByte(i2c_handle, data_l | 0x08); //en=0, rs=0
    gpioDelay(1);
}

// Function to send data to the LCD
void lcd_send_data(int i2c_handle, unsigned char data) {
    char data_u, data_l;
    data_u = (data & 0xF0);
    data_l = ((data << 4) & 0xF0);

    i2cWriteByte(i2c_handle, data_u | 0x0D); //en=1, rs=1
    gpioDelay(1);
    i2cWriteByte(i2c_handle, data_u | 0x09); //en=0, rs=1
    gpioDelay(1);

    i2cWriteByte(i2c_handle, data_l | 0x0D); //en=1, rs=1
    gpioDelay(1);
    i2cWriteByte(i2c_handle, data_l | 0x09); //en=0, rs=1
    gpioDelay(1);
}

// Function to print a string to the LCD
void lcd_string(int i2c_handle, int row, int col, const char *string) {
    int i;
    char line[LCD_WIDTH + 1];

    // Set cursor position
    lcd_send_command(i2c_handle, 0x80 + (col + row * 2) % LCD_WIDTH);

    // Print the string
    for (i = 0; string[i] != '\0' && i < LCD_WIDTH; i++) {
        lcd_send_data(i2c_handle, string[i]);
    }
}

// Function to initialize the LCD
void lcd_init(int i2c_handle) {
    // Initialise display
    lcd_send_command(i2c_handle, 0x33); // Initialise
    lcd_send_command(i2c_handle, 0x32); // Initialise
    lcd_send_command(i2c_handle, LCD_FUNCTIONSET | LCD_4BITMODE | LCD_2LINE | LCD_5x8DOTS);
    lcd_send_command(i2c_handle, LCD_DISPLAYCONTROL | LCD_DISPLAYON | LCD_CURSOROFF | LCD_BLINKOFF);
    lcd_send_command(i2c_handle, LCD_ENTRYMODESET | LCD_ENTRYLEFT | LCD_ENTRYSHIFTDECREMENT);
    lcd_clear(i2c_handle);
}

// Function to clear the LCD
void lcd_clear(int i2c_handle) {
    lcd_send_command(i2c_handle, LCD_CLEARDISPLAY);
    gpioDelay(2); // This command requires a long delay
}

// Function to print to the LCD
void lcd_print(int i2c_handle, int row, int col, const char *text) {
    lcd_string(i2c_handle, row, col, text);
}

// Interrupt callback function
void pulse_callback(int gpio, int level, uint32_t tick, void *user) {
    if (level == PI_HIGH) {
        pulse_count++;
    }
}

// Function to calculate wind speed
float calculate_wind_speed(int pulse_count) {
    return (float)pulse_count * WIND_SPEED_SCALE;
}

// Function to read wind direction from MCP3008
int read_wind_direction(int spi_handle) {
    unsigned char tx_buf[3];
    unsigned char rx_buf[3];

    // MCP3008 configuration: start bit, single-ended mode, channel 0, MSB first
    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = 0x80; // Single-ended, channel 0 (10000000)
    tx_buf[2] = 0x00; // Don't care

    spiXfer(spi_handle, tx_buf, rx_buf, 3);

    // Extract the 10-bit ADC value from the response
    int adc_value = ((rx_buf[1] & 0x03) << 8) + rx_buf[2];

    return adc_value;
}

// Function to map ADC value to wind direction
int map_adc_to_direction(int adc_value) {
    if (adc_value == ADC_MAX_VALUE || adc_value == ADC_MIN_VALUE) {
        return -1; // Indicate sensor failure
    }

    float direction = ((float)(adc_value - ADC_MIN_VALUE) / (ADC_MAX_VALUE - ADC_MIN_VALUE)) * (DIRECTION_MAX_VALUE - DIRECTION_MIN_VALUE) + DIRECTION_MIN_VALUE;
    return (int)direction;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Caught signal %d, cleaning up...\n", signal);
    gpioTerminate();
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C connection to LCD
    i2c_handle = i2cOpen(LCD_I2C_BUS, LCD_I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize LCD
    lcd_init(i2c_handle);

    // Open SPI connection to MCP3008
    spi_handle = spiOpen(0, WIND_DIRECTION_SPI_SPEED, WIND_DIRECTION_SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "Error opening SPI device: %d\n", spi_handle);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up interrupt on wind speed sensor GPIO
    gpioSetMode(WIND_SPEED_GPIO, PI_INPUT);
    gpioSetAlertFuncEx(WIND_SPEED_GPIO, pulse_callback, NULL);

    // Main loop
    while (1) {
        // Read wind speed
        int current_pulse_count = pulse_count;
        pulse_count = 0; // Reset pulse count for the next sample window

        // Read wind direction
        int adc_value = read_wind_direction(spi_handle);
        int direction = map_adc_to_direction(adc_value);

        // Calculate wind speed
        float wind_speed = calculate_wind_speed(current_pulse_count);

        // Format data for LCD
        char speed_str[20];
        char direction_str[20];
        char lcd_buffer[40];

        snprintf(speed_str, sizeof(speed_str), "Speed: %.2f m/s", wind_speed);
        snprintf(direction_str, sizeof(direction_str), "Dir: %d deg", direction);

        // Print data to LCD
        lcd_clear(i2c_handle);
        lcd_print(i2c_handle, 0, 0, speed_str);
        lcd_print(i2c_handle, 1, 0, direction_str);

        // Check for sensor failures
        if (adc_value == ADC_MAX_VALUE || adc_value == ADC_MIN_VALUE) {
            fprintf(stderr, "Wind direction sensor failure!\n");
        }

        // Wait for 500 ms
        gpioDelay(SAMPLE_WINDOW_MS);
    }

    // Cleanup (this part will not be reached in the infinite loop)
    spiClose(spi_handle);
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

