#define LCD_WIDTH 16
#define LCD_HEIGHT 2
#define PULSE_COUNT_INTERVAL 1 // seconds
#define FLOW_RATE_INTERVAL 5   // seconds
#define MAX_FLOW_RATE 20.0      // L/min
