float calculate_flow_rate(int pulse_count);
void display_flow_rate(float flow_rate);
void signal_handler(int signal);
int lcd_init();
void lcd_clear();
void lcd_print(int row, int col, const char *text);

// LCD functions
int lcd_init() {
