    wiringPiI2CWriteReg8(lcd_fd, 0x00, 0x06); // Cursor move right
    wiringPiI2CWriteReg8(lcd_fd, 0x00, 0x0C); // Turn on display, cursor off, blink off
    wiringPiI2CWriteReg8(lcd_fd, 0x00, 0x28); // Data length, number of lines, font size
    wiringPiI2CWriteReg8(lcd_fd, 0x00, 0x01); // Clear display
    usleep(5000); // Wait for clear display to complete

    return 0;
}

void lcd_clear() {
    wiringPiI2CWriteReg8(lcd_fd, 0x00, 0x01); // Clear display
    usleep(2000); // Wait for clear display to complete
}

