    if (level == PI_HIGH) {
        pulse_count++;
    }
}

// Flow rate calculation function
float calculate_flow_rate(int pulse_count) {
    return (float)pulse_count / CALIBRATION_FACTOR * 60.0;
}

// Display flow rate on LCD
void display_flow_rate(float flow_rate) {
    char buffer[LCD_WIDTH + 1];

    // Format flow rate with two decimal places
    snprintf(buffer, LCD_WIDTH + 1, "%.2f L/min", flow_rate);

    lcd_clear();
    lcd_print(0, 0, "Flow Rate:");
    lcd_print(1, 0, buffer);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Initialize LCD
    if (lcd_init() != 0) {
        gpioTerminate();
        return 1;
    }

    // Set GPIO mode for flow sensor
    gpioSetMode(FLOW_SENSOR_GPIO, PI_INPUT);

    // Set pull-up/down resistor (optional, adjust as needed)
    gpioSetPullUpDown(FLOW_SENSOR_GPIO, PI_PUD_UP);

    // Set alert function for pulse counting
    gpioSetAlertFuncEx(FLOW_SENSOR_GPIO, pulse_counter, NULL);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int last_pulse_count = 0;
    time_t last_flow_rate_time = time(NULL);

    // Main loop
    while (!terminate) {
        sleep(PULSE_COUNT_INTERVAL);

        // Calculate flow rate
        float flow_rate = calculate_flow_rate(pulse_count - last_pulse_count);

        // Validate flow rate
        if (flow_rate < MIN_FLOW_RATE || flow_rate > MAX_FLOW_RATE) {
            fprintf(stderr, "Error: Invalid flow rate: %.2f L/min\n", flow_rate);
            flow_rate = 0.0; // Set to 0 to avoid displaying invalid values
        }

        // Display flow rate
        display_flow_rate(flow_rate);

        // Update last pulse count
        last_pulse_count = pulse_count;

        // Check if it's time to display the flow rate
        time_t current_time = time(NULL);
        if (difftime(current_time, last_flow_rate_time) >= FLOW_RATE_INTERVAL) {
            display_flow_rate(flow_rate);
            last_flow_rate_time = current_time;
        }
    }

    // Cleanup
    lcd_clear();
    gpioTerminate();

    return 0;
}

