#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// Define GPIO pins for rows and columns
const int row_pins[] = {2, 3, 4, 17, 27, 22, 10, 9};
const int col_pins[] = {14, 15, 18, 23, 24, 25, 8, 7};
const int num_rows = 8;
const int num_cols = 8;

// Global variable to indicate program termination
volatile sig_atomic_t terminate = 0;

// Signal handler for SIGINT and SIGTERM
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    // Set row pins as output
    for (int i = 0; i < num_rows; i++) {
        gpioSetMode(row_pins[i], PI_OUTPUT);
        gpioWrite(row_pins[i], 1); // Initialize to HIGH (common anode)
    }

    // Set column pins as output
    for (int i = 0; i < num_cols; i++) {
        gpioSetMode(col_pins[i], PI_OUTPUT);
        gpioWrite(col_pins[i], 1); // Initialize to HIGH (common anode)
    }

    return 0;
}

// Function to clear the LED matrix
void clear_matrix() {
    for (int i = 0; i < num_rows; i++) {
        gpioWrite(row_pins[i], 1); // Set row HIGH
    }
    for (int i = 0; i < num_cols; i++) {
        gpioWrite(col_pins[i], 1); // Set column HIGH
    }
}

// Function to display a single column
void display_column(int col_index) {
    clear_matrix();

    // Set the selected column LOW
    gpioWrite(col_pins[col_index], 0);

    // Set all rows HIGH to light the entire column
    for (int i = 0; i < num_rows; i++) {
        gpioWrite(row_pins[i], 0); // Set row LOW
    }

    gpioDelay(150); // Delay for 150ms

    clear_matrix();
}

int main() {
    // Register signal handlers for SIGINT and SIGTERM
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    printf("Wave animation started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        for (int col = 0; col < num_cols; col++) {
            display_column(col);
        }
    }

    // Cleanup GPIO
    gpioTerminate();

    printf("Program terminated gracefully.\n");
    return 0;
}

