// VL53L3CX I2C address
#define VL53L3CX_ADDR 0x29

// VL53L3CX register addresses (example, adjust based on datasheet)
#define VL53L3CX_REG_IDENTIFICATION_MODEL_ID 0x0000
#define VL53L3CX_REG_IDENTIFICATION_REVISION_ID 0x0001
#define VL53L3CX_REG_SYSRANGE_START 0x0010
#define VL53L3CX_REG_RESULT_RANGE_STATUS 0x0014
#define VL53L3CX_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0 0x0050

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_vl53l3cx();
int read_distance(int *distances, int *num_targets);
void log_data(int *distances, int num_targets);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Initialize the VL53L3CX sensor
int init_vl53l3cx() {
    // Example initialization sequence (replace with actual ULD initialization)
    // This is a stub and needs to be replaced with the correct initialization
    // sequence from the VL53L3CX datasheet.

    // Check sensor ID (example)
    char model_id;
    if (i2cReadI2CBlockData(i2c_handle, VL53L3CX_REG_IDENTIFICATION_MODEL_ID, &model_id, 1) != 1) {
        fprintf(stderr, "Error reading model ID\n");
        return -1;
    }

    if (model_id != 0xEACC) {
        fprintf(stderr, "Incorrect model ID: 0x%02X\n", model_id);
        return -1;
    }

    printf("VL53L3CX sensor initialized successfully.\n");
    return 0;
}

// Read distance measurements from the VL53L3CX sensor
int read_distance(int *distances, int *num_targets) {
    // Start a single measurement
    char start_cmd = 0x01;
    if (i2cWriteI2CBlockData(i2c_handle, VL53L3CX_REG_SYSRANGE_START, &start_cmd, 1) != 1) {
        fprintf(stderr, "Error starting measurement\n");
        return -1;
    }

    // Wait for measurement to complete (adjust timeout as needed)
    gpioDelay(10000); // 10 ms

    // Read range status
    char range_status;
    if (i2cReadI2CBlockData(i2c_handle, VL53L3CX_REG_RESULT_RANGE_STATUS, &range_status, 1) != 1) {
        fprintf(stderr, "Error reading range status\n");
        return -1;
    }

    // Read distance data (example, adjust based on expected data format)
    char distance_data[2];
    if (i2cReadI2CBlockData(i2c_handle, VL53L3CX_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0, distance_data, 2) != 2) {
        fprintf(stderr, "Error reading distance data\n");
        return -1;
    }

    int distance = (distance_data[0] << 8) | distance_data[1];

    // Basic target detection (example, adjust based on expected data format)
    *num_targets = (range_status > 0) ? 1 : 0; // Example: 1 target if range status is valid
    distances[0] = distance;

    return 0;
}

// Log the distance data with a timestamp
void log_data(int *distances, int num_targets) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", timeinfo);

    printf("%s - Targets: %d, Distances: ", timestamp, num_targets);
    for (int i = 0; i < num_targets; i++) {
        printf("%d mm ", distances[i]);
    }
    printf("\n");
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, VL53L3CX_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize the VL53L3CX sensor
    if (init_vl53l3cx() != 0) {
        fprintf(stderr, "VL53L3CX initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for graceful shutdown
    signal(SIGINT, signal_handler);

    // Main loop
    int distances[5]; // Assuming a maximum of 5 targets
    int num_targets;
    while (!terminate) {
        if (read_distance(distances, &num_targets) == 0) {
            log_data(distances, num_targets);
        } else {
            fprintf(stderr, "Error reading distance data\n");
        }
        gpioDelay(100000); // 100 ms
    }

    // Close I2C bus and terminate pigpio
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

