#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define SI1145_ADDR 0x60
#define PART_ID_REG 0x00
#define COMMAND_REG 0x18
#define MEAS_RATE_REG 0x08
#define ALS_RATE_REG 0x09
#define PS_RATE_REG 0x0A
#define IRQ_ENABLE_REG 0x03
#define IRQ_MODE1_REG 0x02
#define IRQ_MODE2_REG 0x04
#define IRQ_DATA_REG 0x05
#define ALS_DATA_REG 0x22
#define PS_DATA_REG 0x24

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int init_si1145();
int read_si1145_data(int *proximity, int *ambient_light);
void log_data(int proximity, int ambient_light);
void signal_handler(int signal);
void cleanup();

// Signal handler
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// I2C initialization function
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SI1145_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Si1145 initialization function
int init_si1145() {
    int part_id;

    // Verify PART ID
    part_id = i2cReadByteData(i2c_handle, PART_ID_REG);
    if (part_id < 0) {
        fprintf(stderr, "Error reading PART ID: %d\n", part_id);
        return -1;
    }
    if (part_id != 0x45) {
        fprintf(stderr, "Incorrect PART ID: 0x%02X\n", part_id);
        return -1;
    }
    printf("Si1145 PART ID: 0x%02X\n", part_id);

    // Initialize sensor
    if (i2cWriteByteData(i2c_handle, COMMAND_REG, 0x01) < 0) {
        fprintf(stderr, "Error writing to COMMAND_REG: %d\n", i2c_handle);
        return -1;
    }
    gpioDelay(10); // Delay after initialization command

    // Set measurement rates
    if (i2cWriteByteData(i2c_handle, MEAS_RATE_REG, 0x7B) < 0) {
        fprintf(stderr, "Error writing to MEAS_RATE_REG: %d\n", i2c_handle);
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, ALS_RATE_REG, 0x7B) < 0) {
        fprintf(stderr, "Error writing to ALS_RATE_REG: %d\n", i2c_handle);
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, PS_RATE_REG, 0x7B) < 0) {
        fprintf(stderr, "Error writing to PS_RATE_REG: %d\n", i2c_handle);
        return -1;
    }

    // Enable interrupt on every sample
    if (i2cWriteByteData(i2c_handle, IRQ_ENABLE_REG, 0x07) < 0) {
        fprintf(stderr, "Error writing to IRQ_ENABLE_REG: %d\n", i2c_handle);
        return -1;
    }

    // Set interrupt mode
    if (i2cWriteByteData(i2c_handle, IRQ_MODE1_REG, 0x00) < 0) {
        fprintf(stderr, "Error writing to IRQ_MODE1_REG: %d\n", i2c_handle);
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, IRQ_MODE2_REG, 0x00) < 0) {
        fprintf(stderr, "Error writing to IRQ_MODE2_REG: %d\n", i2c_handle);
        return -1;
    }

    return 0;
}

// Function to read data from Si1145
int read_si1145_data(int *proximity, int *ambient_light) {
    int als_data, ps_data;

    als_data = i2cReadWordData(i2c_handle, ALS_DATA_REG);
    if (als_data < 0) {
        fprintf(stderr, "Error reading ALS data: %d\n", als_data);
        return -1;
    }

    ps_data = i2cReadWordData(i2c_handle, PS_DATA_REG);
    if (ps_data < 0) {
        fprintf(stderr, "Error reading PS data: %d\n", ps_data);
        return -1;
    }

    *ambient_light = als_data;
    *proximity = ps_data;

    return 0;
}

// Function to log data to file
void log_data(int proximity, int ambient_light) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    fprintf(log_file, "%s, %d, %d\n", timestamp, proximity, ambient_light);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Cleanup function
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    int proximity, ambient_light;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handler
    signal(SIGINT, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Initialize Si1145 sensor
    if (init_si1145() != 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen("biometric_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        cleanup();
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_si1145_data(&proximity, &ambient_light) == 0) {
            // Log data
            log_data(proximity, ambient_light);
        } else {
            fprintf(stderr, "Error reading sensor data. Continuing...\n");
        }

        // Wait 500ms
        gpioDelay(500);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

