#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Si1145 I2C address
#define SI1145_ADDR 0x60

// Si1145 register addresses
#define PART_ID 0x00
#define HW_KEY 0x07
#define CH_LIST 0x4F
#define COMMAND 0x30
#define PS1_DATA_LSB 0x18
#define PS1_DATA_MSB 0x19
#define ALS_VIS_DATA_LSB 0x22
#define ALS_VIS_DATA_MSB 0x23

// Si1145 commands
#define ALS_FORCE 0x06
#define PS_FORCE 0x07

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_sensor();
int read_sensor_data(int *proximity, int *ambient_light);
int log_data(int proximity, int ambient_light);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to initialize the Si1145 sensor
int initialize_sensor() {
    int status;

    // Check PART_ID register
    status = i2cWriteByteData(i2c_handle, PART_ID, 0); // Dummy write to read
    if (status != 0) {
        fprintf(stderr, "Error writing to PART_ID register: %d\n", status);
        return -1;
    }
    int part_id = i2cReadByteData(i2c_handle, PART_ID);
    if (part_id != 0x45) {
        fprintf(stderr, "Error: Invalid PART_ID (0x%02X, expected 0x45)\n", part_id);
        return -1;
    }

    // Write HW_KEY
    status = i2cWriteByteData(i2c_handle, HW_KEY, 0x17);
    if (status != 0) {
        fprintf(stderr, "Error writing to HW_KEY register: %d\n", status);
        return -1;
    }

    // Set CH_LIST to enable PS1 and ALS_VIS channels
    status = i2cWriteByteData(i2c_handle, CH_LIST, 0x77); // Enable PS1 and ALS_VIS
    if (status != 0) {
        fprintf(stderr, "Error writing to CH_LIST register: %d\n", status);
        return -1;
    }

    // Configure measurement rates (example values)
    status = i2cWriteByteData(i2c_handle, 0x02, 0x01); // PS1 rate
    if (status != 0) {
        fprintf(stderr, "Error writing to PS1 rate register: %d\n", status);
        return -1;
    }
    status = i2cWriteByteData(i2c_handle, 0x03, 0x01); // ALS_VIS rate
    if (status != 0) {
        fprintf(stderr, "Error writing to ALS_VIS rate register: %d\n", status);
        return -1;
    }

    return 0;
}

// Function to read proximity and ambient light data from the sensor
int read_sensor_data(int *proximity, int *ambient_light) {
    int status;
    uint8_t data[4];

    // Trigger measurements
    status = i2cWriteByteData(i2c_handle, COMMAND, ALS_FORCE | PS_FORCE);
    if (status != 0) {
        fprintf(stderr, "Error triggering measurements: %d\n", status);
        return -1;
    }

    // Read PS1 data
    status = i2cReadI2CBlockData(i2c_handle, PS1_DATA_LSB, (char *)data, 2);
    if (status != 2) {
        fprintf(stderr, "Error reading PS1 data: %d\n", status);
        return -1;
    }
    *proximity = (data[1] << 8) | data[0];

    // Read ALS_VIS data
    status = i2cReadI2CBlockData(i2c_handle, ALS_VIS_DATA_LSB, (char *)data + 2, 2);
    if (status != 2) {
        fprintf(stderr, "Error reading ALS_VIS data: %d\n", status);
        return -1;
    }
    *ambient_light = (data[3] << 8) | data[2];

    return 0;
}

// Function to log data to a CSV file
int log_data(int proximity, int ambient_light) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    fprintf(log_file, "%s,%d,%d\n", timestamp, proximity, ambient_light);
    fflush(log_file);

    return 0;
}

int main() {
    int proximity, ambient_light;
    int status;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, SI1145_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize the sensor
    if (initialize_sensor() != 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("biometric_data.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Install signal handler
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        // Read sensor data
        status = read_sensor_data(&proximity, &ambient_light);
        if (status == 0) {
            // Log data
            log_data(proximity, ambient_light);
        } else {
            fprintf(stderr, "Error reading sensor data\n");
        }

        // Wait for 1 second
        sleep(1);
    }

    // Cleanup
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

