#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins
#define TRIGGER_PIN 17
#define ECHO_PIN 27

// Define constants
#define SPEED_OF_SOUND 34300 // cm/s
#define TIMEOUT_US 30000      // 30ms timeout
#define MIN_DISTANCE 2       // cm
#define MAX_DISTANCE 400     // cm
#define WATERING_THRESHOLD 15 // cm

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;

// Function prototypes
void trigger_sensor();
long long measure_pulse_width();
float calculate_distance(long long pulse_width);
void log_distance(float distance);
void check_watering_reminder(float distance);
void signal_handler(int signal);

// Function to generate a 10us trigger pulse
void trigger_sensor() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10 microseconds
    gpioWrite(TRIGGER_PIN, 0);
}

// Function to measure the echo pulse width using pigpio edge events
long long measure_pulse_width() {
    long long start_time = 0, end_time = 0;
    int start_sec, start_micros, end_sec, end_micros;
    int timeout_count = 0;

    // Wait for the echo pin to go high (rising edge)
    while (gpioRead(ECHO_PIN) == 0 && timeout_count < TIMEOUT_US) {
        gpioDelay(1); // Check every 1 us
        timeout_count++;
    }

    if (timeout_count >= TIMEOUT_US) {
        return -1; // Timeout: No echo received
    }

    gpioTime(PI_TIME_RELATIVE, &start_sec, &start_micros);
    start_time = (long long)start_sec * 1000000 + start_micros;

    // Wait for the echo pin to go low (falling edge)
    timeout_count = 0;
    while (gpioRead(ECHO_PIN) == 1 && timeout_count < TIMEOUT_US) {
        gpioDelay(1); // Check every 1 us
        timeout_count++;
    }

    if (timeout_count >= TIMEOUT_US) {
        return -2; // Timeout: Echo stuck high
    }

    gpioTime(PI_TIME_RELATIVE, &end_sec, &end_micros);
    end_time = (long long)end_sec * 1000000 + end_micros;

    return end_time - start_time;
}

