void check_watering_reminder(float distance);
void signal_handler(int signal);

// Function to generate a 10us trigger pulse
void trigger_sensor() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10 microseconds
    gpioWrite(TRIGGER_PIN, 0);
}

// Function to measure the echo pulse width using pigpio edge events
long long measure_pulse_width() {
    long long start_time = 0, end_time = 0;
    int start_sec, start_micros, end_sec, end_micros;
    int timeout_count = 0;

    // Wait for the echo pin to go high (rising edge)
    while (gpioRead(ECHO_PIN) == 0 && timeout_count < TIMEOUT_US) {
        gpioDelay(1); // Check every 1 us
        timeout_count++;
    }

    if (timeout_count >= TIMEOUT_US) {
        return -1; // Timeout: No echo received
    }

    gpioTime(PI_TIME_RELATIVE, &start_sec, &start_micros);
    start_time = (long long)start_sec * 1000000 + start_micros;

    // Wait for the echo pin to go low (falling edge)
