#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// APDS-9960 I2C address
#define APDS9960_ADDR 0x39

// APDS-9960 register addresses
#define APDS9960_ENABLE 0x80
#define APDS9960_ATIME 0x81
#define APDS9960_WTIME 0x83
#define APDS9960_PPULSE 0x8E
#define APDS9960_CONTROL 0xF1
#define APDS9960_CONFIG2 0x90
#define APDS9960_ID 0x92
#define APDS9960_RDATA 0x96
#define APDS9960_GDATA 0x98
#define APDS9960_BDATA 0x9A
#define APDS9960_PDATA 0x9C

// Proximity threshold
#define PROXIMITY_THRESHOLD 200

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_sensor();
int read_sensor_data(uint16_t *red, uint16_t *green, uint16_t *blue, uint8_t *proximity);
void log_data(uint16_t red, uint16_t green, uint16_t blue, uint8_t proximity);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Initializes the APDS9960 sensor
int initialize_sensor() {
    int status;

    // Verify sensor ID
    status = i2cWriteByteData(i2c_handle, APDS9960_ID, 0); // Dummy write to trigger read
    if (status < 0) {
        fprintf(stderr, "Error writing to sensor ID register: %d\n", status);
        return -1;
    }
    int sensor_id = i2cReadByteData(i2c_handle, APDS9960_ID);
    if (sensor_id < 0 || sensor_id != 0xAB) {
        fprintf(stderr, "Error reading sensor ID or incorrect ID: 0x%X\n", sensor_id);
        return -1;
    }
    printf("Sensor ID: 0x%X\n", sensor_id);

    // Configure registers
    status = i2cWriteByteData(i2c_handle, APDS9960_ENABLE, 0x03); // Enable power and sensor
    if (status < 0) {
        fprintf(stderr, "Error writing to ENABLE register: %d\n", status);
        return -1;
    }

    status = i2cWriteByteData(i2c_handle, APDS9960_ATIME, 0xDB); // Integration time
    if (status < 0) {
        fprintf(stderr, "Error writing to ATIME register: %d\n", status);
        return -1;
    }

    status = i2cWriteByteData(i2c_handle, APDS9960_WTIME, 0xF6); // Wait time
    if (status < 0) {
        fprintf(stderr, "Error writing to WTIME register: %d\n", status);
        return -1;
    }

    status = i2cWriteByteData(i2c_handle, APDS9960_PPULSE, 0x87); // Pulse length
    if (status < 0) {
        fprintf(stderr, "Error writing to PPULSE register: %d\n", status);
        return -1;
    }

    status = i2cWriteByteData(i2c_handle, APDS9960_CONTROL, 0x03); // Enable proximity
    if (status < 0) {
        fprintf(stderr, "Error writing to CONTROL register: %d\n", status);
        return -1;
    }

    status = i2cWriteByteData(i2c_handle, APDS9960_CONFIG2, 0x01); // Enable ALS
    if (status < 0) {
        fprintf(stderr, "Error writing to CONFIG2 register: %d\n", status);
        return -1;
    }

    return 0;
}

// Reads raw RGB color values and proximity value from the sensor
int read_sensor_data(uint16_t *red, uint16_t *green, uint16_t *blue, uint8_t *proximity) {
    int status;

    // Read RGB data
    status = i2cReadWordData(i2c_handle, APDS9960_RDATA);
    if (status < 0) {
        fprintf(stderr, "Error reading red data: %d\n", status);
        return -1;
    }
    *red = (uint16_t)status;

    status = i2cReadWordData(i2c_handle, APDS9960_GDATA);
    if (status < 0) {
        fprintf(stderr, "Error reading green data: %d\n", status);
        return -1;
    }
    *green = (uint16_t)status;

    status = i2cReadWordData(i2c_handle, APDS9960_BDATA);
    if (status < 0) {
        fprintf(stderr, "Error reading blue data: %d\n", status);
        return -1;
    }
    *blue = (uint16_t)status;

    // Read proximity data
    status = i2cReadByteData(i2c_handle, APDS9960_PDATA);
    if (status < 0) {
        fprintf(stderr, "Error reading proximity data: %d\n", status);
        return -1;
    }
    *proximity = (uint8_t)status;

    return 0;
}

// Logs the sensor data to a CSV file
void log_data(uint16_t red, uint16_t green, uint16_t blue, uint8_t proximity) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%u,%u,%u,%u\n", timestamp, red, green, blue, proximity);
    fflush(log_file); // Ensure data is written to file immediately
}

int main() {
    uint16_t red, green, blue;
    uint8_t proximity;
    int status;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, APDS9960_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize the sensor
    if (initialize_sensor() != 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("color_proximity_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Starting data logging...\n");

    // Main loop
    while (!terminate) {
        // Read sensor data
        status = read_sensor_data(&red, &green, &blue, &proximity);
        if (status == 0) {
            // Log data if proximity exceeds threshold
            if (proximity > PROXIMITY_THRESHOLD) {
                log_data(red, green, blue, proximity);
            }
        } else {
            fprintf(stderr, "Error reading sensor data, attempting to re-initialize...\n");
            // Attempt to re-initialize the sensor
            i2cClose(i2c_handle);
            i2c_handle = i2cOpen(1, APDS9960_ADDR, 0);
            if (i2c_handle < 0) {
                fprintf(stderr, "Error re-opening I2C bus: %d\n", i2c_handle);
                terminate = 1; // Exit loop if re-initialization fails
                continue;
            }
            if (initialize_sensor() != 0) {
                fprintf(stderr, "Sensor re-initialization failed\n");
                terminate = 1; // Exit loop if re-initialization fails
                continue;
            }
        }

        // Wait 100 ms
        gpioDelay(100);
    }

    // Cleanup
    printf("Cleaning up...\n");
    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

