#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// VL53L0X Register Addresses
#define VL53L0X_REG_IDENTIFICATION_MODEL_ID  0x00c0
#define VL53L0X_REG_IDENTIFICATION_REVISION_ID 0x00c2
#define VL53L0X_REG_SYSRANGE_START             0x00
#define VL53L0X_REG_RESULT_INTERRUPT_STATUS    0x13
#define VL53L0X_REG_RESULT_RANGE_STATUS        0x14
#define VL53L0X_REG_SYSTEM_INTERRUPT_CLEAR     0x0B

// I2C Addresses to Check
#define VL53L0X_ADDR_1 0x29
#define VL53L0X_ADDR_2 0x30

// GPIO Pin for Trigger
#define TRIGGER_PIN 17

// I2C Bus
#define I2C_BUS 1

// Timeout for measurement (100ms)
#define TIMEOUT_US 100000

// Global Variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function Prototypes
int initialize_sensor(int i2c_handle);
int trigger_measurement(int i2c_handle);
int read_distance(int i2c_handle, uint16_t *distance);
void log_distance(FILE *log_file, uint16_t distance);
void signal_handler(int signal);

// Signal Handler
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize Sensor
int initialize_sensor(int i2c_handle) {
    int status;
    uint8_t model_id;

    // Check sensor presence by reading the model ID
    status = i2cReadByteData(i2c_handle, VL53L0X_REG_IDENTIFICATION_MODEL_ID);
    if (status < 0) {
        fprintf(stderr, "Error reading model ID: %d\n", status);
        return -1;
    }
    model_id = (uint8_t)status;

    if (model_id != 0xEA) {
        fprintf(stderr, "VL53L0X sensor not found at address 0x%02x (Model ID: 0x%02x)\n", i2c_handle, model_id);
        return -1;
    }

    printf("VL53L0X sensor found at address 0x%02x\n", i2c_handle);

    // Add more initialization steps here if needed (e.g., writing to configuration registers)

    return 0;
}

// Trigger Measurement
int trigger_measurement(int i2c_handle) {
    int status;

    status = i2cWriteByteData(i2c_handle, VL53L0X_REG_SYSRANGE_START, 0x01);
    if (status < 0) {
        fprintf(stderr, "Error writing to SYSRANGE_START: %d\n", status);
        return -1;
    }

    return 0;
}

// Read Distance
int read_distance(int i2c_handle, uint16_t *distance) {
    int status;
    uint8_t data[14];
    uint32_t start_time, current_time;

    // Start timeout timer
    start_time = gpioTick();

    // Poll RESULT_INTERRUPT_STATUS until it indicates a new measurement is ready
    do {
        status = i2cReadByteData(i2c_handle, VL53L0X_REG_RESULT_INTERRUPT_STATUS);
        if (status < 0) {
            fprintf(stderr, "Error reading RESULT_INTERRUPT_STATUS: %d\n", status);
            return -1;
        }
        if ((status & 0x01) != 0) {
            break; // Measurement ready
        }

        gpioDelay(1); // Small delay to avoid busy-waiting
        current_time = gpioTick();
        if (current_time - start_time > TIMEOUT_US) {
            fprintf(stderr, "Timeout waiting for measurement\n");
            return -1;
        }
    } while (1);

    // Read the 14-byte result block
    status = i2cReadI2CBlockData(i2c_handle, VL53L0X_REG_RESULT_RANGE_STATUS, (char *)data, 14);
    if (status < 0) {
        fprintf(stderr, "Error reading result block: %d\n", status);
        return -1;
    }

    // Extract the 16-bit distance from bytes 10-11
    *distance = (uint16_t)((data[10] << 8) | data[11]);

    // Clear the interrupt
    status = i2cWriteByteData(i2c_handle, VL53L0X_REG_SYSTEM_INTERRUPT_CLEAR, 0x01);
    if (status < 0) {
        fprintf(stderr, "Error writing to SYSTEM_INTERRUPT_CLEAR: %d\n", status);
        return -1;
    }

    return 0;
}

// Log Distance
void log_distance(FILE *log_file, uint16_t distance) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%u\n", timestamp, distance);
    fflush(log_file); // Ensure data is written to file immediately
}

int main() {
    int status;
    uint16_t distance;
    int i2c_address;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO 17 as input with pull-up resistor
    gpioSetMode(TRIGGER_PIN, PI_INPUT);
    gpioSetPullUpDown(TRIGGER_PIN, PI_PUD_UP);

    // Open log file
    log_file = fopen("distance_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        gpioTerminate();
        return 1;
    }

    // Register signal handler for graceful shutdown
    signal(SIGINT, signal_handler);

    // Check for VL53L0X sensor at address 0x29
    i2c_address = VL53L0X_ADDR_1;
    i2c_handle = i2cOpen(I2C_BUS, i2c_address, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device at address 0x%02x: %d\n", i2c_address, i2c_handle);
        i2c_handle = i2cOpen(I2C_BUS, VL53L0X_ADDR_2, 0);
        if (i2c_handle < 0) {
            fprintf(stderr, "Error opening I2C device at address 0x%02x: %d\n", i2c_address, i2c_handle);
            fprintf(stderr, "VL53L0X sensor not found at either address. Exiting.\n");
            fclose(log_file);
            gpioTerminate();
            return 1;
        }
    }

    // Initialize the sensor
    if (initialize_sensor(i2c_handle) != 0) {
        fprintf(stderr, "Sensor initialization failed. Exiting.\n");
        i2cClose(i2c_handle);
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    printf("VL53L0X sensor initialized successfully.\n");

    // Main loop
    while (!terminate) {
        // Wait for falling edge on GPIO 17
        if (gpioRead(TRIGGER_PIN) == 0) {
            printf("Falling edge detected on GPIO %d\n", TRIGGER_PIN);

            // Trigger measurement
            if (trigger_measurement(i2c_handle) == 0) {
                // Read distance
                if (read_distance(i2c_handle, &distance) == 0) {
                    // Log distance
                    log_distance(log_file, distance);
                    printf("Distance: %u mm\n", distance);
                } else {
                    fprintf(stderr, "Error reading distance\n");
                }
            } else {
                fprintf(stderr, "Error triggering measurement\n");
            }

            // Debounce: Wait for a short period to avoid multiple triggers from a single edge
            gpioDelay(50); // 50ms debounce
        }

        gpioDelay(1); // Small delay to reduce CPU usage
    }

    // Cleanup
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    printf("Program terminated.\n");
    return 0;
}

