    i2c_address = VL53L0X_ADDR_1;
    i2c_handle = i2cOpen(I2C_BUS, i2c_address, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device at address 0x%02x: %d\n", i2c_address, i2c_handle);
        i2c_handle = i2cOpen(I2C_BUS, VL53L0X_ADDR_2, 0);
        if (i2c_handle < 0) {
            fprintf(stderr, "Error opening I2C device at address 0x%02x: %d\n", i2c_address, i2c_handle);
            fprintf(stderr, "VL53L0X sensor not found at either address. Exiting.\n");
            fclose(log_file);
            gpioTerminate();
            return 1;
        }
    }

    // Initialize the sensor
    if (initialize_sensor(i2c_handle) != 0) {
        fprintf(stderr, "Sensor initialization failed. Exiting.\n");
        i2cClose(i2c_handle);
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    printf("VL53L0X sensor initialized successfully.\n");

    // Main loop
    while (!terminate) {
        // Wait for falling edge on GPIO 17
        if (gpioRead(TRIGGER_PIN) == 0) {
            printf("Falling edge detected on GPIO %d\n", TRIGGER_PIN);

            // Trigger measurement
            if (trigger_measurement(i2c_handle) == 0) {
                // Read distance
                if (read_distance(i2c_handle, &distance) == 0) {
                    // Log distance
                    log_distance(log_file, distance);
                    printf("Distance: %u mm\n", distance);
                } else {
                    fprintf(stderr, "Error reading distance\n");
                }
            } else {
                fprintf(stderr, "Error triggering measurement\n");
            }

            // Debounce: Wait for a short period to avoid multiple triggers from a single edge
            gpioDelay(50); // 50ms debounce
        }

        gpioDelay(1); // Small delay to reduce CPU usage
    }

    // Cleanup
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    printf("Program terminated.\n");
    return 0;
}

