volatile sig_atomic_t program_running = 1;
FILE *log_file = NULL;

void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

/* Reads the sensor value from the specified GPIO pin. */
int read_sensor(int gpio_pin) {
    int value = gpioRead(gpio_pin);
    if (value < 0) {
        fprintf(stderr, "Error reading sensor on GPIO %d: %d\n", gpio_pin, value);
        return -1; // Indicate an error
    }
    return value;
}

/* Logs the sensor readings to the specified file. */
void log_data(FILE *fp, int sensor1_value, int sensor2_value) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(fp, "%s, Sensor 1: %d, Sensor 2: %d\n", timestamp, sensor1_value, sensor2_value);
    fflush(fp); // Ensure data is written to file immediately
}

int main() {
    int sensor1_value, sensor2_value;

    // Register signal handler for graceful shutdown
    signal(SIGINT, signal_handler);

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as inputs
    gpioSetMode(SENSOR_1_GPIO, PI_INPUT);
    gpioSetMode(SENSOR_2_GPIO, PI_INPUT);

    // Open the log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        gpioTerminate();
        return 1;
    }

    printf("Starting obstacle detection. Press Ctrl+C to exit.\n");

    while (program_running) {
        sensor1_value = read_sensor(SENSOR_1_GPIO);
        sensor2_value = read_sensor(SENSOR_2_GPIO);

        if (sensor1_value == -1 || sensor2_value == -1) {
            fprintf(stderr, "Error reading sensors, continuing...\n");
        } else {
            log_data(log_file, sensor1_value, sensor2_value);
        }

        gpioDelay(100); // Wait 100 milliseconds
    }

    // Cleanup and exit
    printf("Cleaning up...\n");
    fclose(log_file);
    gpioTerminate();

    return 0;
}

