// Constants
#define I2C_BUS 1
#define ICU20201_ADDR 0x6A
#define DISTANCE_REG 0x00 // Example register address, adjust as needed
#define LED_GPIO 17
#define DISTANCE_THRESHOLD 20.0 // cm
#define LOG_FILE "distance_log.txt"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_pigpio();
int init_i2c();
int init_gpio();
int init_logging();
int read_distance();
void log_distance(float distance);
void control_led(float distance);
void signal_handler(int signal);
void cleanup();

// Structure for sensor configuration (example)
typedef struct {
    uint8_t config_reg;
    uint8_t mode;
} sensor_config_t;

// Function to initialize pigpio
int init_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Function to initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, ICU20201_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "I2C open failed: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to initialize GPIO
int init_gpio() {
    gpioSetMode(LED_GPIO, PI_OUTPUT);
    gpioWrite(LED_GPIO, 0); // Initially turn off the LED
    return 0;
}

// Function to initialize logging
int init_logging() {
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        return -1;
    }
    return 0;
}

// Function to read distance from the sensor
int read_distance() {
    char buf[2];
    int bytes_read = i2cReadI2CBlockData(i2c_handle, DISTANCE_REG, buf, 2);

    if (bytes_read != 2) {
        fprintf(stderr, "I2C read failed: %d\n", bytes_read);
        return -1;
    }

    // Combine the two bytes into a 16-bit value
    uint16_t raw_distance = (buf[0] << 8) | buf[1];

    // Convert raw distance to centimeters (example conversion, adjust as needed)
    float distance = (float)raw_distance / 10.0; // Example scaling

    return (int)distance;
}

// Function to log distance with ISO-8601 timestamp
void log_distance(float distance) {
    time_t now = time(NULL);
    struct tm *tstruct = localtime(&now);
    char buf[80];
    strftime(buf, sizeof(buf), "%Y-%m-%dT%H:%M:%SZ", tstruct);

    fprintf(log_file, "%s, Distance: %.2f cm\n", buf, distance);
    fflush(log_file); // Ensure data is written to file immediately
}

// Function to control the LED based on distance
void control_led(float distance) {
    if (distance < DISTANCE_THRESHOLD) {
        gpioWrite(LED_GPIO, 1); // Turn on LED
    } else {
        gpioWrite(LED_GPIO, 0); // Turn off LED
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Cleanup function to release resources
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioWrite(LED_GPIO, 0); // Turn off LED
    gpioTerminate();
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize
    if (init_pigpio() != 0) return 1;
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }
    if (init_gpio() != 0) {
        cleanup();
        return 1;
    }
    if (init_logging() != 0) {
        cleanup();
        return 1;
    }

    printf("Ultrasonic sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        int distance_cm = read_distance();
        if (distance_cm >= 0) {
            log_distance((float)distance_cm);
            control_led((float)distance_cm);
        } else {
            fprintf(stderr, "Failed to read distance. Retrying...\n");
        }

        gpioDelay(100); // 100 ms delay
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

