#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Constants
#define I2C_BUS 1
#define SI1182_ADDR 0x60
#define PROXIMITY_REG 0x18
#define AMBIENT_LIGHT_REG 0x16
#define LOG_FILE "biometric_log.txt"
#define RETRY_COUNT 3

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int read_sensor_data(uint16_t *proximity, uint16_t *ambient_light);
int log_data(uint16_t proximity, uint16_t ambient_light);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SI1182_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read sensor data with retries
int read_sensor_data(uint16_t *proximity, uint16_t *ambient_light) {
    char buf[2];
    int result;
    int retries = 0;

    // Read proximity data
    while (retries < RETRY_COUNT) {
        result = i2cReadI2CBlockData(i2c_handle, PROXIMITY_REG, buf, 2);
        if (result == 2) {
            *proximity = (buf[1] << 8) | buf[0];
            break; // Success, exit retry loop
        } else {
            fprintf(stderr, "Error reading proximity data (attempt %d): %d\n", retries + 1, result);
            retries++;
            gpioDelay(10); // Small delay before retrying
        }
    }
    if (retries == RETRY_COUNT) {
        fprintf(stderr, "Failed to read proximity data after %d retries.\n", RETRY_COUNT);
        return -1;
    }

    retries = 0;
    // Read ambient light data
    while (retries < RETRY_COUNT) {
        result = i2cReadI2CBlockData(i2c_handle, AMBIENT_LIGHT_REG, buf, 2);
        if (result == 2) {
            *ambient_light = (buf[1] << 8) | buf[0];
            break; // Success, exit retry loop
        } else {
            fprintf(stderr, "Error reading ambient light data (attempt %d): %d\n", retries + 1, result);
            retries++;
