#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define ICU20201_ADDR 0x6A
#define WHO_AM_I_REG 0x00
#define WHO_AM_I_VALUE 0x50
#define DISTANCE_REG_L 0x01
#define DISTANCE_REG_H 0x02
#define LED_GPIO 17
#define DEFAULT_THRESHOLD 100 // mm
#define LOG_FILE "tof_log.txt"

// Global variables
int i2c_handle;
int distance_threshold = DEFAULT_THRESHOLD;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int init_gpio();
int init_sensor();
int read_distance();
void control_led(int distance);
void log_data(int distance);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, ICU20201_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Initialize GPIO for LED control
int init_gpio() {
    if (gpioSetMode(LED_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting GPIO %d as output\n", LED_GPIO);
        return -1;
    }
    return 0;
}

// Initialize the ICU-20201 sensor
int init_sensor() {
    int who_am_i = i2cReadByteData(i2c_handle, WHO_AM_I_REG);
    if (who_am_i < 0) {
        fprintf(stderr, "Error reading WHO_AM_I register: %d\n", who_am_i);
        return -1;
    }
    if (who_am_i != WHO_AM_I_VALUE) {
        fprintf(stderr, "WHO_AM_I value mismatch: expected 0x%02X, got 0x%02X\n", WHO_AM_I_VALUE, who_am_i);
        return -1;
    }
    printf("Sensor initialized successfully. WHO_AM_I: 0x%02X\n", who_am_i);
    return 0;
}

// Read distance measurement from the sensor
int read_distance() {
    int distance_low, distance_high;

    distance_low = i2cReadByteData(i2c_handle, DISTANCE_REG_L);
    if (distance_low < 0) {
        fprintf(stderr, "Error reading distance low byte: %d\n", distance_low);
        return -1;
    }

    distance_high = i2cReadByteData(i2c_handle, DISTANCE_REG_H);
    if (distance_high < 0) {
        fprintf(stderr, "Error reading distance high byte: %d\n", distance_high);
        return -1;
    }

    return (distance_high << 8) | distance_low;
}

// Control the LED based on the distance
void control_led(int distance) {
    if (distance < distance_threshold) {
        gpioWrite(LED_GPIO, 1); // Turn LED on
    } else {
        gpioWrite(LED_GPIO, 0); // Turn LED off
    }
}

// Log data to file
void log_data(int distance) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, Distance: %d mm\n", timestamp, distance);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Cleanup resources before exiting
void cleanup() {
    printf("Cleaning up resources...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioWrite(LED_GPIO, 0); // Turn off LED
    gpioTerminate();
    if (log_file != NULL) {
        fclose(log_file);
    }
    printf("Cleanup complete. Exiting.\n");
}

int main(int argc, char *argv[]) {
    // Install signal handler
    signal(SIGINT, signal_handler);

    // Parse command-line arguments
    if (argc > 1) {
        distance_threshold = atoi(argv[1]);
        if (distance_threshold <= 0) {
            fprintf(stderr, "Invalid distance threshold. Using default value: %d mm\n", DEFAULT_THRESHOLD);
            distance_threshold = DEFAULT_THRESHOLD;
        }
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Initialize GPIO
    if (init_gpio() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize sensor
    if (init_sensor() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    printf("Starting data acquisition...\n");

    // Main loop
    while (!terminate) {
        int distance = read_distance();
        if (distance >= 0) {
            control_led(distance);
            log_data(distance);
        } else {
            fprintf(stderr, "Error reading distance. Retrying...\n");
        }
        gpioDelay(50); // 50 ms delay
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

