#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>
#include <signal.h>
#include <string.h>

#define I2C_BUS "/dev/i2c-1"
#define SENSOR_ADDRESS 0x50
#define MEASUREMENT_COMMAND_SIZE 4
#define RESPONSE_SIZE 15
#define SAMPLE_COUNT 10
#define THRESHOLD_DISTANCE 1000 // mm
#define LOG_FILE "intrusion_log.txt"

volatile sig_atomic_t program_running = 1;
int i2c_fd = -1;
FILE *log_file = NULL;

void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

int i2c_write_command(int fd, uint8_t *command, int command_size) {
    ssize_t bytes_written = write(fd, command, command_size);
    if (bytes_written != command_size) {
        fprintf(stderr, "Error writing to I2C device: %zd bytes written (expected %d)\n", bytes_written, command_size);
        return -1;
    }
    return 0;
}

int i2c_read_response(int fd, uint8_t *response, int response_size) {
    ssize_t bytes_read = read(fd, response, response_size);
    if (bytes_read != response_size) {
        fprintf(stderr, "Error reading from I2C device: %zd bytes read (expected %d)\n", bytes_read, response_size);
        return -1;
    }
    return 0;
}

int validate_response(uint8_t *response) {
    if (response[0] != 0x50) {
        fprintf(stderr, "Invalid response header: 0x%02X\n", response[0]);
        return -1;
    }
    return 0;
}

int read_distance(int fd) {
    uint8_t command[MEASUREMENT_COMMAND_SIZE] = {0x50, 0x0A, 0x00, 0x01};
    uint8_t response[RESPONSE_SIZE];

    if (i2c_write_command(fd, command, MEASUREMENT_COMMAND_SIZE) != 0) {
        return -1;
    }

    usleep(10000); // Wait 10 ms

    if (i2c_read_response(fd, response, RESPONSE_SIZE) != 0) {
        return -1;
    }

    if (validate_response(response) != 0) {
        return -1;
    }

    // Extract distance (16-bit big-endian)
    int distance = (response[11] << 8) | response[12];
    return distance;
}

double calculate_average_distance(int *distances, int sample_count) {
    double sum = 0.0;
    for (int i = 0; i < sample_count; i++) {
        sum += distances[i];
    }
    return sum / sample_count;
}

int log_intrusion(double average_distance) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (log_file == NULL) {
        fprintf(stderr, "Log file is not open.\n");
        return -1;
    }

    fprintf(log_file, "%s - Intrusion detected: Average distance = %.2f mm\n", timestamp, average_distance);
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

int main() {
    signal(SIGINT, signal_handler);

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Error opening I2C bus");
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, SENSOR_ADDRESS) < 0) {
        perror("Error setting I2C slave address");
        close(i2c_fd);
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        close(i2c_fd);
        return 1;
    }

    int distances[SAMPLE_COUNT];

    while (program_running) {
        double sum = 0.0;
        for (int i = 0; i < SAMPLE_COUNT; i++) {
            int distance = read_distance(i2c_fd);
            if (distance == -1) {
                fprintf(stderr, "Error reading distance, skipping sample.\n");
                distances[i] = -1; // Indicate an error
            } else {
                distances[i] = distance;
                sum += distance;
            }
        }

        double average_distance = calculate_average_distance(distances, SAMPLE_COUNT);

        if (average_distance < THRESHOLD_DISTANCE) {
            if (log_intrusion(average_distance) != 0) {
                fprintf(stderr, "Error logging intrusion.\n");
            }
        }

        usleep(100000); // 100 ms delay
    }

    close(i2c_fd);
    fclose(log_file);

    return 0;
}

