    return sum / sample_count;
}

int log_intrusion(double average_distance) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (log_file == NULL) {
        fprintf(stderr, "Log file is not open.\n");
        return -1;
    }

    fprintf(log_file, "%s - Intrusion detected: Average distance = %.2f mm\n", timestamp, average_distance);
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

int main() {
    signal(SIGINT, signal_handler);

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Error opening I2C bus");
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, SENSOR_ADDRESS) < 0) {
        perror("Error setting I2C slave address");
        close(i2c_fd);
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        close(i2c_fd);
        return 1;
    }

    int distances[SAMPLE_COUNT];

    while (program_running) {
        double sum = 0.0;
        for (int i = 0; i < SAMPLE_COUNT; i++) {
            int distance = read_distance(i2c_fd);
            if (distance == -1) {
                fprintf(stderr, "Error reading distance, skipping sample.\n");
                distances[i] = -1; // Indicate an error
            } else {
                distances[i] = distance;
                sum += distance;
            }
        }

        double average_distance = calculate_average_distance(distances, SAMPLE_COUNT);

        if (average_distance < THRESHOLD_DISTANCE) {
            if (log_intrusion(average_distance) != 0) {
                fprintf(stderr, "Error logging intrusion.\n");
            }
        }

        usleep(100000); // 100 ms delay
    }

    close(i2c_fd);
    fclose(log_file);

    return 0;
}

