#include <signal.h>
#include <pigpio.h>

#define I2C_BUS 1
#define VL53L0X_ADDR 0x29
#define MODEL_ID_REG 0xC0
#define SYSRANGE_START 0x00
#define RESULT_INTERRUPT_STATUS 0x13
#define RESULT_RANGE_STATUS 0x14
#define SYSTEM_INTERRUPT_CLEAR 0x0B

int i2c_handle;

// Function to handle signals (SIGINT, SIGTERM)
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    exit(0);
}

// Function to initialize the VL53L0X sensor
int init_vl53l0x() {
    int status;

    // Check sensor ID
    status = i2cReadByteData(i2c_handle, MODEL_ID_REG);
    if (status < 0) {
        fprintf(stderr, "Error reading model ID: %s\n", strerror(errno));
        return -1;
    }
    if (status != 0xEE) {
        fprintf(stderr, "Incorrect model ID: 0x%02X\n", status);
        return -1;
    }

    printf("VL53L0X sensor initialized successfully.\n");
    return 0;
}

// Function to read distance from the VL53L0X sensor
int read_distance() {
    int status;
    int distance = -1; // Initialize to an invalid value

    // Start a single-shot ranging
    status = i2cWriteByteData(i2c_handle, SYSRANGE_START, 0x01);
    if (status < 0) {
        fprintf(stderr, "Error starting ranging: %s\n", strerror(errno));
        return -1;
    }

    // Wait for the measurement to complete (polling RESULT_INTERRUPT_STATUS)
    int timeout_count = 0;
    while (1) {
        status = i2cReadByteData(i2c_handle, RESULT_INTERRUPT_STATUS);
        if (status < 0) {
            fprintf(stderr, "Error reading interrupt status: %s\n", strerror(errno));
            return -1;
        }

        if (status & 0x01) {
            break; // Measurement complete
        }

        gpioDelay(1000); // Wait 1 ms
        timeout_count++;
        if (timeout_count > 100) {
            fprintf(stderr, "Timeout waiting for measurement.\n");
            return -1;
        }
    }

    // Read the distance
    status = i2cReadWordData(i2c_handle, RESULT_RANGE_STATUS);
    if (status < 0) {
        fprintf(stderr, "Error reading distance: %s\n", strerror(errno));
        return -1;
    }
    distance = status; // Distance is in millimeters

    // Clear the interrupt
    status = i2cWriteByteData(i2c_handle, SYSTEM_INTERRUPT_CLEAR, 0x01);
    if (status < 0) {
        fprintf(stderr, "Error clearing interrupt: %s\n", strerror(errno));
        return -1;
    }

    return distance;
}

int main() {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];
    int distance;

    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed: %s\n", strerror(errno));
        return 1;
    }

    // Open I2C device
    i2c_handle = i2cOpen(I2C_BUS, VL53L0X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Initialize the VL53L0X sensor
    if (init_vl53l0x() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (1) {
        // Read distance
        distance = read_distance();

        if (distance >= 0) {
            // Get current timestamp
            time(&rawtime);
            timeinfo = localtime(&rawtime);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

            // Print the distance with timestamp
            printf("%s Distance: %d mm\n", timestamp, distance);
        } else {
            fprintf(stderr, "Error reading distance.\n");
        }

        gpioDelay(500); // Wait 500 ms
    }

    // The following lines will never be reached due to the infinite loop.
    i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

