// Constants
#define I2C_BUS 1
#define SI1182_ADDR 0x39
#define CONFIG_REG 0x18
#define IRQ_STATUS_REG 0x25
#define PROX_LSB_REG 0x2A
#define PROX_MSB_REG 0x2B
#define PROX_DATA_REG 0x2C
#define PROX_DATA_MSB_REG 0x2D

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_sensor();
int read_proximity_data();
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to initialize the Si1182 sensor
int initialize_sensor() {
    int status;

    // Enable proximity mode by writing to the CONFIG register
    status = i2cWriteByteData(i2c_handle, CONFIG_REG, 0x01);
    if (status < 0) {
        fprintf(stderr, "Error writing to CONFIG register: %d\n", status);
        return -1;
    }

    return 0;
}

// Function to read proximity data from the Si1182 sensor
int read_proximity_data() {
    int status;
    unsigned char data[2];
    int proximity_value;

    // Read the proximity data from registers 0x2C and 0x2D
    status = i2cReadI2CBlockData(i2c_handle, PROX_DATA_REG, (char *)data, 2);
    if (status < 0) {
        fprintf(stderr, "Error reading proximity data: %d\n", status);
        return -1;
    }

    // Combine the two bytes to form the 16-bit proximity value
    proximity_value = (data[1] << 8) | data[0];

    return proximity_value;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, SI1182_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize the sensor
    if (initialize_sensor() != 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        // Read proximity data
        int proximity_value = read_proximity_data();
        if (proximity_value >= 0) {
            // Print the proximity value
            printf("Proximity: %d\n", proximity_value);
        } else {
            fprintf(stderr, "Failed to read proximity data\n");
        }

        // Wait for 500 ms
        gpioDelay(500000); // 500 ms = 500000 microseconds
    }

    // Close I2C bus and terminate pigpio
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

