#include <stdio.h>
#include <stdlib.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>
#include <signal.h>
#include <errno.h>

#define I2C_BUS "/dev/i2c-1"
#define MLX75030_ADDR 0x4C
#define DISTANCE_REG_LOW 0x00
#define DISTANCE_REG_HIGH 0x01
#define DISTANCE_FACTOR 0.125

volatile sig_atomic_t program_running = 1;

void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully.\n", signal);
}

int main() {
    int i2c_fd;
    unsigned char data[2];
    int16_t raw_distance;
    float distance_mm;
    struct timespec sleep_time;

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Error opening I2C bus");
        return 1;
    }

    // Set slave address
    if (ioctl(i2c_fd, I2C_SLAVE, MLX75030_ADDR) < 0) {
        perror("Error setting I2C slave address");
        close(i2c_fd);
        return 1;
    }

    // Verify device is present (read a register)
    unsigned char check_reg = 0x00; // Example register to read
    if (write(i2c_fd, &check_reg, 1) != 1) {
        perror("Error writing to I2C device");
        close(i2c_fd);
        return 1;
    }

    if (read(i2c_fd, data, 1) != 1) {
        perror("Error reading from I2C device");
        close(i2c_fd);
        return 1;
    }

    printf("MLX75030 sensor found at address 0x%02X\n", MLX75030_ADDR);

    // Configure sleep time
    sleep_time.tv_sec = 0;
    sleep_time.tv_nsec = 500000000; // 500 ms

    // Main loop
    while (program_running) {
        // Read distance data
        if (write(i2c_fd, &DISTANCE_REG_LOW, 1) != 1) {
            perror("Error writing to I2C device (register select)");
            nanosleep(&sleep_time, NULL);
            continue; // Retry
        }

        if (read(i2c_fd, data, 2) != 2) {
            perror("Error reading distance data from I2C device");
            nanosleep(&sleep_time, NULL);
            continue; // Retry
        }

        // Convert raw data to distance in mm
        raw_distance = (data[0] << 8) | data[1];
        distance_mm = raw_distance * DISTANCE_FACTOR;

        // Print distance
        printf("Distance: %.2f mm\n", distance_mm);

        // Sleep for 500 ms
        if (nanosleep(&sleep_time, NULL) != 0) {
            if (errno == EINTR) {
                printf("nanosleep interrupted by signal\n");
            } else {
                perror("nanosleep failed");
            }
        }
    }

    // Close I2C bus
    close(i2c_fd);

    return 0;
}

