#include <pigpio.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>

// Define OPT3101 I2C address
#define OPT3101_ADDR 0x44

// Define OPT3101 register addresses (Example - adjust based on datasheet)
#define OPT3101_REG_DISTANCE_0 0x00 // Example register for channel 0 distance
#define OPT3101_REG_AMBIENT_LIGHT 0x02 // Example register for ambient light
#define OPT3101_REG_ERROR_FLAGS 0x04  // Example register for error flags

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    uint16_t distance;
    uint16_t ambient_light;
    uint16_t error_flags;
} sensor_data_t;

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
    terminate = 1;
}

// Function to read a 16-bit register from the OPT3101
uint16_t read_register(int handle, uint8_t reg) {
    char buf[2];
    int result = i2cReadI2CBlockData(handle, reg, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading register 0x%02X: %d\n", reg, result);
        return 0xFFFF; // Return error value
    }
    return (buf[0] << 8) | buf[1];
}

// Function to write a 16-bit register to the OPT3101
int write_register(int handle, uint8_t reg, uint16_t value) {
    char buf[2];
    buf[0] = (value >> 8) & 0xFF;
    buf[1] = value & 0xFF;
    int result = i2cWriteI2CBlockData(handle, reg, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error writing register 0x%02X: %d\n", reg, result);
        return -1; // Return error code
