#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

// Define GPIO pins
#define TRIGGER_PIN 17
#define ECHO_PIN 18

// Define constants
#define SPEED_OF_SOUND 0.0343 // cm/us
#define MAX_PULSE_DURATION 38000 // us (38ms)
#define TIMEOUT_US 200000       // 200ms timeout

// Global variable for program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to trigger the ultrasonic sensor
void triggerSensor() {
    gpioWrite(TRIGGER_PIN, 1); // Set trigger high
    gpioDelay(10);             // Wait 10 us
    gpioWrite(TRIGGER_PIN, 0); // Set trigger low
}

// Function to measure the echo pulse width
long measurePulseWidth() {
    long start_tick, end_tick, pulse_width;

    // Wait for echo to go high (rising edge)
    int count = 0;
    while (gpioRead(ECHO_PIN) == 0 && count < TIMEOUT_US) {
        count++;
        gpioDelay(1); // Small delay to prevent busy-waiting
    }
    if (count >= TIMEOUT_US) {
        fprintf(stderr, "Error: Echo rising edge timeout\n");
        return -1; // Timeout
    }

    start_tick = gpioTick();

    // Wait for echo to go low (falling edge)
    count = 0;
    while (gpioRead(ECHO_PIN) == 1 && count < TIMEOUT_US) {
        count++;
        gpioDelay(1); // Small delay to prevent busy-waiting
    }
    if (count >= TIMEOUT_US) {
        fprintf(stderr, "Error: Echo falling edge timeout\n");
        return -1; // Timeout
    }

    end_tick = gpioTick();

    pulse_width = end_tick - start_tick;

    if (pulse_width <= 0 || pulse_width > MAX_PULSE_DURATION) {
        fprintf(stderr, "Error: Invalid pulse duration: %ld us\n", pulse_width);
        return -1; // Invalid pulse duration
    }

    return pulse_width;
}

// Function to calculate distance in centimeters
float calculateDistance(long pulse_width) {
    return (pulse_width * SPEED_OF_SOUND) / 2.0;
}

// Function to log the distance with a timestamp
void logDistance(float distance) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("[%s] Distance: %.2f cm\n", timestamp, distance);
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);

    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Ultrasonic sensor program started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        // Trigger the sensor
        triggerSensor();

        // Measure the pulse width
        long pulse_width = measurePulseWidth();

        // Calculate the distance
        float distance;
        if (pulse_width > 0) {
            distance = calculateDistance(pulse_width);

            // Log the distance
            logDistance(distance);
        } else {
            fprintf(stderr, "Error: Failed to measure pulse width\n");
        }

        // Wait for 1 second
        gpioDelay(1000000); // 1 second = 1000000 us
    }

    // Terminate pigpio library
    gpioTerminate();

    return 0;
}

