#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <termios.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <sys/time.h>
#include <pigpio.h>
#include <errno.h>

// Constants
#define UART_DEVICE "/dev/serial0"
#define BAUD_RATE B115200
#define GPIO_LED 17
#define DISTANCE_THRESHOLD 1.0
#define RANGE_RESOLUTION 0.0486
#define MAGIC_WORD_LENGTH 8
#define RANGE_PROFILE_LENGTH 64
#define DATA_FRAME_LENGTH (MAGIC_WORD_LENGTH + (RANGE_PROFILE_LENGTH * 2))
#define LED_ON_TIME 2 // seconds

// Global variables
volatile sig_atomic_t program_running = 1;
int uart_fd = -1;
FILE *log_file = NULL;

// Structure for configuration
typedef struct {
    char uart_device[20];
    int baud_rate;
    int gpio_led;
    float distance_threshold;
    float range_resolution;
} Config;

// Function prototypes
int initialize_uart(const char *device, int baud_rate);
int read_radar_data(int fd, unsigned char *buffer, int length);
int validate_magic_word(const unsigned char *buffer);
float calculate_distance(const unsigned short *range_profile);
int detect_intrusion(float distance, float threshold);
void activate_led(int gpio_pin, int duration_seconds);
void log_intrusion(float distance);
void signal_handler(int signal);
void cleanup();

// Signal handler
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully.\n", signal);
}

// UART initialization function
int initialize_uart(const char *device, int baud_rate) {
    int fd = open(device, O_RDWR | O_NOCTTY | O_SYNC);
    if (fd == -1) {
        perror("Error opening UART");
        return -1;
    }

    struct termios tty;
    if (tcgetattr(fd, &tty) != 0) {
        perror("Error getting termios attributes");
        close(fd);
        return -1;
    }

    tty.c_cflag = baud_rate | CS8 | CLOCAL | CREAD;  // 8N1, no parity
    tty.c_iflag = IGNPAR;                           // Ignore parity errors
    tty.c_oflag = 0;
    tty.c_lflag = 0;                               // Non-canonical mode

    tty.c_cc[VMIN] = 0;  // Read at least 0 characters
    tty.c_cc[VTIME] = 5; // Wait for 0.5 seconds (5 * 0.1s)

    if (tcsetattr(fd, TCSANOW, &tty) != 0) {
        perror("Error setting termios attributes");
        close(fd);
        return -1;
    }

    return fd;
}

// Function to read radar data from UART
int read_radar_data(int fd, unsigned char *buffer, int length) {
    ssize_t bytes_read = read(fd, buffer, length);
    if (bytes_read == -1) {
        perror("Error reading from UART");
        return -1;
    } else if (bytes_read != length) {
        fprintf(stderr, "Warning: Read %zd bytes, expected %d. Possible data loss.\n", bytes_read, length);
        return -1; // Indicate incomplete data
    }
    return 0;
}

// Function to validate the magic word
int validate_magic_word(const unsigned char *buffer) {
    const unsigned char magic_word[] = {0x02, 0x01, 0x04, 0x03, 0x06, 0x05, 0x08, 0x07};
    return (memcmp(buffer, magic_word, MAGIC_WORD_LENGTH) == 0);
}

// Function to calculate the distance of the closest object
float calculate_distance(const unsigned short *range_profile) {
    float distance = -1.0; // Initialize to an invalid value
    for (int i = 0; i < RANGE_PROFILE_LENGTH; i++) {
        float current_distance = i * RANGE_RESOLUTION;
        if (range_profile[i] > 0) { // Assuming 0 indicates no object
            if (distance == -1.0 || current_distance < distance) {
                distance = current_distance;
            }
        }
    }
    return distance;
}

// Function to detect intrusion
int detect_intrusion(float distance, float threshold) {
    return (distance >= 0.0 && distance <= threshold);
}

// Function to activate the LED
void activate_led(int gpio_pin, int duration_seconds) {
    gpioWrite(gpio_pin, 1); // Turn LED on
    gpioDelay(duration_seconds * 1000000); // Delay for specified duration (microseconds)
    gpioWrite(gpio_pin, 0); // Turn LED off
}

// Function to log intrusion events
void log_intrusion(float distance) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    fprintf(log_file, "%s,%.4f\n", timestamp, distance);
    fflush(log_file); // Ensure data is written to file immediately
}

// Cleanup function
void cleanup() {
    if (uart_fd != -1) {
        close(uart_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Configuration
    Config config = {
        .uart_device = UART_DEVICE,
        .baud_rate = BAUD_RATE,
        .gpio_led = GPIO_LED,
        .distance_threshold = DISTANCE_THRESHOLD,
        .range_resolution = RANGE_RESOLUTION
    };

    // Signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pin as output
    gpioSetMode(config.gpio_led, PI_OUTPUT);

    // Initialize UART
    uart_fd = initialize_uart(config.uart_device, config.baud_rate);
    if (uart_fd == -1) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen("intrusion_log.csv", "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        cleanup();
        return 1;
    }

    // Main loop
    unsigned char buffer[DATA_FRAME_LENGTH];
    unsigned short range_profile[RANGE_PROFILE_LENGTH];
    float distance;

    printf("Starting intrusion detection...\n");

    while (program_running) {
        // Read data from UART
        if (read_radar_data(uart_fd, buffer, DATA_FRAME_LENGTH) == 0) {
            // Validate magic word
            if (validate_magic_word(buffer)) {
                // Extract range profile data
                memcpy(range_profile, buffer + MAGIC_WORD_LENGTH, RANGE_PROFILE_LENGTH * 2);

                // Calculate distance
                distance = calculate_distance(range_profile);

                // Detect intrusion
                if (detect_intrusion(distance, config.distance_threshold)) {
                    printf("Intrusion detected! Distance: %.4f meters\n", distance);
                    activate_led(config.gpio_led, LED_ON_TIME);
                    log_intrusion(distance);
                }
            } else {
                fprintf(stderr, "Warning: Invalid magic word detected.\n");
            }
        } else {
            // Handle UART read error (e.g., sensor failure)
            fprintf(stderr, "Warning: Potential sensor failure or bus error.\n");
        }

        gpioDelay(100000); // Delay for 0.1 seconds (100ms)
    }

    // Cleanup and exit
    cleanup();
    printf("Exiting.\n");
    return 0;
}

