    while (program_running) {
        // Read data from UART
        if (read_radar_data(uart_fd, buffer, DATA_FRAME_LENGTH) == 0) {
            // Validate magic word
            if (validate_magic_word(buffer)) {
                // Extract range profile data
                memcpy(range_profile, buffer + MAGIC_WORD_LENGTH, RANGE_PROFILE_LENGTH * 2);

                // Calculate distance
                distance = calculate_distance(range_profile);

                // Detect intrusion
                if (detect_intrusion(distance, config.distance_threshold)) {
                    printf("Intrusion detected! Distance: %.4f meters\n", distance);
                    activate_led(config.gpio_led, LED_ON_TIME);
                    log_intrusion(distance);
                }
            } else {
                fprintf(stderr, "Warning: Invalid magic word detected.\n");
            }
        } else {
            // Handle UART read error (e.g., sensor failure)
            fprintf(stderr, "Warning: Potential sensor failure or bus error.\n");
        }

        gpioDelay(100000); // Delay for 0.1 seconds (100ms)
    }

    // Cleanup and exit
    cleanup();
    printf("Exiting.\n");
    return 0;
}

