#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define I2C_ADDRESS 0x69
#define DISTANCE_HIGH_REG 0x31
#define DISTANCE_LOW_REG 0x32
#define GPIO_PIN 17
#define DISTANCE_THRESHOLD 10.0 // cm
#define SAMPLE_INTERVAL_MS 100

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_distance(int i2c_handle);
float convert_to_cm(int raw_distance);
void log_distance(float distance);
void trigger_alert(int gpio_pin);
void signal_handler(int signal);
int initialize();
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Initializes the pigpio library, I2C, and GPIO
int initialize() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "I2C open failed: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    gpioSetMode(GPIO_PIN, PI_OUTPUT);
    gpioWrite(GPIO_PIN, 0); // Ensure GPIO is low initially

    log_file = fopen("distance_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    return 0;
}

// Reads the distance from the sensor
int read_distance(int i2c_handle) {
    char buf[2];
    int result = i2cReadI2CBlockData(i2c_handle, DISTANCE_HIGH_REG, buf, 2);

    if (result != 2) {
        fprintf(stderr, "I2C read failed: %d\n", result);
        return -1; // Indicate error
    }

    return (buf[0] << 8) | buf[1];
}

// Converts the raw distance to centimeters
float convert_to_cm(int raw_distance) {
    // Assuming a linear relationship between raw value and distance in cm
    // This needs to be calibrated based on the sensor's datasheet
    // Example: 1 raw unit = 0.1 cm
    return (float)raw_distance * 0.1; // Example conversion
}

// Logs the distance to a file with a timestamp
void log_distance(float distance) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    fprintf(log_file, "%s, %.2f\n", timestamp, distance);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Triggers an alert by setting a GPIO pin high for 500ms
void trigger_alert(int gpio_pin) {
    gpioWrite(gpio_pin, 1); // Set GPIO high
    gpioDelay(500);         // Wait for 500ms
    gpioWrite(gpio_pin, 0); // Set GPIO low
}

// Cleans up resources before exiting
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    if (initialize()) {
        return 1;
    }

    printf("Distance monitoring started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        // Read distance
        int raw_distance = read_distance(i2c_handle);
        if (raw_distance >= 0) {
            float distance_cm = convert_to_cm(raw_distance);

            // Log distance
            log_distance(distance_cm);

            // Check for alert condition
            if (distance_cm < DISTANCE_THRESHOLD) {
                trigger_alert(GPIO_PIN);
            }
        } else {
            fprintf(stderr, "Failed to read distance. Retrying...\n");
        }

        gpioDelay(SAMPLE_INTERVAL_MS); // Sample every 100ms
    }

    cleanup();
    return 0;
}

