    gpioDelay(1000); // Small delay after write
    char model_id;
    status = i2cReadI2CBlockData(i2c_handle, VL53L1X_REG_IDENTIFICATION_MODEL_ID, &model_id, 1);
    if (status < 0) {
        fprintf(stderr, "Error reading sensor ID: %d\n", status);
        return -1;
    }
    if (model_id != 0xEA) {
        fprintf(stderr, "Incorrect sensor ID: 0x%02X\n", model_id);
        return -1;
    }
    printf("VL53L1X sensor found with ID 0x%02X\n", model_id);

    // Perform software reset
    status = i2cWriteByteData(i2c_handle, VL53L1X_REG_SYSTEM_SOFT_RESET, 0x00);
    if (status < 0) {
        fprintf(stderr, "Error writing reset command: %d\n", status);
        return -1;
    }
    gpioDelay(2000); // Wait 2 ms

    // Start continuous ranging
    status = i2cWriteByteData(i2c_handle, VL53L1X_REG_SYSTEM_MODE_START, 0x01);
    if (status < 0) {
        fprintf(stderr, "Error starting continuous ranging: %d\n", status);
        return -1;
    }

    // Wait for start bit to clear
    int timeout = 100; // 100 ms timeout
    while (timeout > 0) {
        status = i2cReadByteData(i2c_handle, VL53L1X_REG_SYSRANGE_START);
        if (status < 0) {
            fprintf(stderr, "Error reading start bit: %d\n", status);
            return -1;
        }
        if ((status & 0x01) == 0) {
            break;
        }
        gpioDelay(1000); // 1 ms delay
        timeout--;
    }
    if (timeout == 0) {
        fprintf(stderr, "Timeout waiting for start bit to clear\n");
        return -1;
    }

    return 0;
}

// VL53L1X read distance function
int vl53l1x_read_distance(int *distance) {
    int status;
    char data[2];

    // Wait for data ready
    int timeout = 100; // 100 ms timeout
    while (timeout > 0) {
        status = i2cReadByteData(i2c_handle, VL53L1X_REG_RESULT_INTERRUPT_STATUS);
        if (status < 0) {
            fprintf(stderr, "Error reading interrupt status: %d\n", status);
            return -1;
        }
        if ((status & 0x01) != 0) {
            break;
        }
        gpioDelay(1000); // 1 ms delay
        timeout--;
    }
    if (timeout == 0) {
        fprintf(stderr, "Timeout waiting for data ready\n");
        return -1;
    }

    // Read distance
    status = i2cReadI2CBlockData(i2c_handle, VL53L1X_REG_RESULT_RANGE_STATUS, data, 2);
    if (status < 0) {
        fprintf(stderr, "Error reading distance: %d\n", status);
        return -1;
    }

    // Clear interrupt
    status = i2cWriteByteData(i2c_handle, VL53L1X_REG_SYSTEM_INTERRUPT_CLEAR, 0x01);
    if (status < 0) {
        fprintf(stderr, "Error clearing interrupt: %d\n", status);
        return -1;
    }

    // Combine bytes and store distance
    *distance = (data[0] << 8) | data[1];

    return 0;
}

// Logging function
void log_distance(int distance) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%d\n", timestamp, distance);
    fflush(log_file); // Ensure data is written to file immediately
}

// Parking guidance function
void print_guidance(int distance) {
    if (distance < 300) {
        printf("STOP\n");
    } else if (distance < 600) {
        printf("APPROACH\n");
    } else if (distance < 1200) {
        printf("SLOW\n");
    } else {
        printf("CLEAR\n");
    }
}

int main() {
    int distance;
    int status;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize VL53L1X sensor
    if (vl53l1x_init() != 0) {
        fprintf(stderr, "VL53L1X initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("distance_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Write header row if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "timestamp,distance_mm\n");
    }
    fflush(log_file);

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        // Read distance
        status = vl53l1x_read_distance(&distance);
        if (status == 0) {
            // Log distance
            log_distance(distance);

            // Print guidance
            print_guidance(distance);
        } else {
            fprintf(stderr, "Error reading distance, retrying...\n");
        }

        gpioDelay(100000); // 100 ms delay
    }

    // Cleanup
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

