#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define CH201_ADDR 0x45
#define LED_GPIO 18
#define MIN_DISTANCE 50.0  // mm
#define MAX_DISTANCE 500.0 // mm
#define MIN_FREQUENCY 1.0  // Hz
#define MAX_FREQUENCY 10.0 // Hz
#define SAMPLE_INTERVAL_MS 100

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
float read_distance();
float map_distance_to_frequency(float distance);
void blink_led(float frequency);
void log_data(float distance, float frequency);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, CH201_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read distance from the CH201 sensor
float read_distance() {
    char cmd[1] = {0x00}; // Example command to trigger a measurement
    char buf[2];
    int result;

    // Retry I2C write and read operations
    for (int i = 0; i < 3; ++i) {
        result = i2cWriteDevice(i2c_handle, cmd, 1);
        if (result != 0) {
            fprintf(stderr, "I2C write error (attempt %d): %d\n", i + 1, result);
            gpioDelay(10); // Wait 10 ms before retrying
            continue;
        }

        gpioDelay(10); // Wait for measurement (adjust as needed)

        result = i2cReadDevice(i2c_handle, buf, 2);
        if (result != 2) {
            fprintf(stderr, "I2C read error (attempt %d): %d\n", i + 1, result);
            gpioDelay(10); // Wait 10 ms before retrying
            continue;
        }

        // Combine the two bytes into a single distance value
        int distance_raw = (buf[0] << 8) | buf[1];

        // Convert raw value to millimeters (adjust based on sensor datasheet)
        float distance = (float)distance_raw / 10.0; // Example conversion

        return distance;
    }

    fprintf(stderr, "Failed to read distance after 3 attempts.\n");
    return -1.0; // Indicate failure
}

// Map distance to blink frequency
float map_distance_to_frequency(float distance) {
    float frequency;

    if (distance < MIN_DISTANCE) {
        frequency = MAX_FREQUENCY;
    } else if (distance > MAX_DISTANCE) {
        frequency = MIN_FREQUENCY;
    } else {
        // Linear mapping
        frequency = MAX_FREQUENCY - (distance - MIN_DISTANCE) * (MAX_FREQUENCY - MIN_FREQUENCY) / (MAX_DISTANCE - MIN_DISTANCE);
    }

    return frequency;
}

// Blink the LED at the specified frequency
void blink_led(float frequency) {
    static int led_state = 0; // 0 = off, 1 = on
    static unsigned long last_blink_time = 0;
    unsigned long current_time = gpioTick();

    if (frequency > 0) {
        float period_ms = 1000.0 / frequency;
        float half_period_ms = period_ms / 2.0;

        if (current_time - last_blink_time >= half_period_ms * 1000) {
            led_state = !led_state;
            gpioWrite(LED_GPIO, led_state);
            last_blink_time = current_time;
        }
    } else {
        gpioWrite(LED_GPIO, 0); // Turn off LED if frequency is 0
    }
}

// Log timestamped distance and blink frequency
void log_data(float distance, float frequency) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("%s - Distance: %.2f mm, Frequency: %.2f Hz\n", timestamp, distance, frequency);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set LED GPIO as output
    gpioSetMode(LED_GPIO, PI_OUTPUT);

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Starting distance measurement and LED control...\n");

    while (!terminate) {
        // Read distance
        float distance = read_distance();

        if (distance >= 0) {
            // Map distance to frequency
            float frequency = map_distance_to_frequency(distance);

            // Blink LED
            blink_led(frequency);

            // Log data
            log_data(distance, frequency);
        } else {
            fprintf(stderr, "Failed to read distance. Retrying...\n");
        }

        // Wait for the next sample
        gpioDelay(SAMPLE_INTERVAL_MS);
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioWrite(LED_GPIO, 0); // Turn off LED
    gpioTerminate();

    printf("Exiting.\n");
    return 0;
}

