#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// Constants
#define I2C_BUS 1
#define MLX75030_ADDR 0x4C
#define MEASURE_CMD 0x00
#define RETRY_COUNT 3
#define RETRY_DELAY_MS 10
#define SAMPLE_INTERVAL_MS 100

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure for configuration (example)
typedef struct {
    int i2c_bus;
    int i2c_address;
    char *log_file_name;
} config_t;

// Function prototypes
int init_i2c(int bus, int addr);
int read_distance(int handle);
int log_distance(FILE *fp, int distance);
void signal_handler(int signal);
void cleanup();

// Signal handler
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

// Initialize I2C
int init_i2c(int bus, int addr) {
    int handle = i2cOpen(bus, addr, 0);
    if (handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", handle);
        return -1;
    }
    return handle;
}

// Read distance from MLX75030
int read_distance(int handle) {
    int distance = -1;
    int retries = RETRY_COUNT;

    while (retries > 0) {
        if (i2cWriteByteData(handle, MEASURE_CMD, 0) < 0) {
            fprintf(stderr, "Error writing to I2C device: %d\n", i2cWriteByteData(handle, MEASURE_CMD, 0));
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
            retries--;
            continue;
        }

        gpioDelay(1000); // Delay for measurement (adjust as needed)

        int data = i2cReadWordData(handle, 0x00); // Read two bytes
        if (data >= 0) {
            distance = (data & 0xFF); // Assuming distance is in the lower byte
            return distance;
        } else {
            fprintf(stderr, "Error reading from I2C device: %d\n", data);
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
            retries--;
        }
    }

    fprintf(stderr, "Failed to read distance after multiple retries.\n");
    return -1; // Indicate failure
}

// Log distance to file
int log_distance(FILE *fp, int distance) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    if (fprintf(fp, "%s,%d\n", timestamp, distance) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        return -1;
    }
    fflush(fp); // Ensure data is written to disk
    return 0;
}

// Cleanup resources
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    i2c_handle = init_i2c(I2C_BUS, MLX75030_ADDR);
    if (i2c_handle < 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen("distance_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    // Main loop
    while (!terminate) {
        int distance = read_distance(i2c_handle);
        if (distance >= 0) {
            if (log_distance(log_file, distance) != 0) {
                fprintf(stderr, "Error logging distance.\n");
            }
        } else {
            fprintf(stderr, "Failed to read distance.\n");
        }

        gpioDelay(SAMPLE_INTERVAL_MS * 1000); // Delay in microseconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

