#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>
#include <signal.h>
#include <errno.h>

// CH-101 I2C address
#define CH101_ADDR 0x49

// CH-101 register addresses
#define MEAS_TRIGGER 0x04
#define MEAS_STATUS 0x06
#define DIST_HIGH 0x08
#define DIST_LOW 0x09

// Global variables for signal handling
volatile sig_atomic_t program_running = 1;
int i2c_fd = -1;
FILE *log_file = NULL;

// Function to handle signals (SIGINT, SIGTERM)
void signal_handler(int signal) {
    program_running = 0;
    fprintf(stderr, "\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to write a byte to an I2C register
int i2c_write_byte(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2];
    buf[0] = reg;
    buf[1] = value;
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "Error writing to I2C device: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Function to read a byte from an I2C register
int i2c_read_byte(int fd, uint8_t reg, uint8_t *value) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "Error writing register address for read: %s\n", strerror(errno));
        return -1;
    }
    if (read(fd, value, 1) != 1) {
        fprintf(stderr, "Error reading from I2C device: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Function to trigger a single range measurement
int trigger_measurement(int fd) {
    return i2c_write_byte(fd, MEAS_TRIGGER, 0x01);
}

// Function to read the distance from the sensor
int read_distance(int fd, uint16_t *distance) {
    uint8_t dist_high, dist_low;

    // Read DIST_HIGH and DIST_LOW registers
    if (i2c_read_byte(fd, DIST_HIGH, &dist_high) != 0) return -1;
    if (i2c_read_byte(fd, DIST_LOW, &dist_low) != 0) return -1;

    *distance = (dist_high << 8) | dist_low;
    return 0;
}

// Function to log the distance data to a CSV file
int log_data(FILE *fp, uint16_t distance) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    if (fprintf(fp, "%s,%u\n", timestamp, distance) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        return -1;
    }
    fflush(fp); // Ensure data is written to disk immediately
    return 0;
}

int main() {
    int ret;
    uint16_t distance;
    uint8_t status;
    struct timespec sleep_time;
    struct timespec timeout;

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C device
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C device: %s\n", strerror(errno));
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, CH101_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    // Open log file
    log_file = fopen("distance_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    // Write header to log file if it's a new file
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "timestamp,distance_mm\n");
    }
    rewind(log_file);

    // Main loop
    sleep_time.tv_sec = 0;
    sleep_time.tv_nsec = 500000000; // 500 ms

    while (program_running) {
        // Trigger measurement
        if (trigger_measurement(i2c_fd) != 0) {
            fprintf(stderr, "Error triggering measurement, skipping sample.\n");
            nanosleep(&sleep_time, NULL);
            continue;
        }

        // Wait for data to be ready with timeout
        timeout.tv_sec = 0;
        timeout.tv_nsec = 5000000; // 5 ms
        ret = 0;
        while (ret == 0) {
            if (i2c_read_byte(i2c_fd, MEAS_STATUS, &status) != 0) {
                fprintf(stderr, "Error reading MEAS_STATUS, skipping sample.\n");
                nanosleep(&sleep_time, NULL);
                goto next_sample;
            }
            if (status & 0x01) {
                ret = 1; // Data ready
            } else {
                nanosleep(&timeout, NULL);
            }
        }

        // Read distance
        if (read_distance(i2c_fd, &distance) != 0) {
            fprintf(stderr, "Error reading distance, skipping sample.\n");
            nanosleep(&sleep_time, NULL);
            continue;
        }

        // Log data
        if (log_data(log_file, distance) != 0) {
            fprintf(stderr, "Error logging data, skipping sample.\n");
        }

    next_sample:
        nanosleep(&sleep_time, NULL);
    }

    // Clean up
    close(i2c_fd);
    fclose(log_file);

    return 0;
}

