// VL53L5CX I2C address
#define VL53L5CX_ADDR 0x29

// I2C device file
#define I2C_DEVICE "/dev/i2c-1"

// Register addresses (Example - adjust based on datasheet)
#define VL53L5CX_REG_IDENTIFICATION_MODEL_ID 0x00c0
#define VL53L5CX_REG_IDENTIFICATION_REVISION_ID 0x00c2
#define VL53L5CX_REG_SYSRANGE_START 0x0040
#define VL53L5CX_REG_RESULT_RANGE_STATUS 0x0014
#define VL53L5CX_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0 0x0050

// Zone data registers (Example - adjust based on datasheet)
#define VL53L5CX_REG_ZONE_START 0x0070 // Starting register for zone data

// Global variables
int i2c_fd = -1;
volatile sig_atomic_t stop_flag = 0;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    printf("\nCaught signal %d, exiting gracefully...\n", sig);
    stop_flag = 1;
}

// Function to write a byte to an I2C register
int i2c_write_byte(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2];
    buf[0] = reg;
    buf[1] = value;
    if (write(fd, buf, 2) != 2) {
        perror("Failed to write to I2C device");
        return -1;
    }
    return 0;
}

// Function to read a byte from an I2C register
int i2c_read_byte(int fd, uint8_t reg, uint8_t *value) {
    if (write(fd, &reg, 1) != 1) {
        perror("Failed to write register address");
        return -1;
    }
    if (read(fd, value, 1) != 1) {
        perror("Failed to read from I2C device");
        return -1;
    }
    return 0;
}

// Function to read multiple bytes from an I2C register
int i2c_read_bytes(int fd, uint8_t reg, uint8_t *buf, int len) {
    if (write(fd, &reg, 1) != 1) {
        perror("Failed to write register address");
        return -1;
    }
    if (read(fd, buf, len) != len) {
        perror("Failed to read from I2C device");
        return -1;
    }
    return 0;
}

