#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>

// Define the I2C bus and address
#define I2C_BUS 1
#define MLX75030_ADDR 0x4C

// Define the register addresses for distance data (example, adjust based on datasheet)
#define DISTANCE_HIGH_REG 0x00
#define DISTANCE_LOW_REG 0x01

// Global variables for I2C handle and program state
int i2c_handle;
volatile sig_atomic_t program_running = 1;

// Structure to hold sensor data
typedef struct {
    uint16_t distance;
    int status;
} sensor_data_t;

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
    program_running = 0;
}

// Function to initialize the pigpio library and I2C
int initialize() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(I2C_BUS, MLX75030_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Function to read distance data from the sensor with retries
int read_distance(sensor_data_t *data) {
    int retries = 3;
    int status = 0;

    while (retries > 0) {
        char buf[2];
        int bytes_read = i2cReadI2CBlockData(i2c_handle, DISTANCE_HIGH_REG, buf, 2);

        if (bytes_read == 2) {
            data->distance = (buf[0] << 8) | buf[1];
            data->status = 0; // Success
            return 0; // Success
        } else {
            fprintf(stderr, "I2C read failed (bytes read: %d), retries remaining: %d\n", bytes_read, retries);
            status = -1; // Indicate failure
            gpioDelay(10); // Wait 10ms before retrying
            retries--;
        }
    }

    return -1; // Failure after all retries
}

// Function to log the distance data with a timestamp
void log_data(sensor_data_t data) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    long timestamp_ms = (ts.tv_sec * 1000) + (ts.tv_nsec / 1000000);

    printf("Timestamp: %ld ms, Distance: %u mm, Status: %d\n", timestamp_ms, data.distance, data.status);
}

// Function to clean up resources before exiting
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
}

int main() {
    // Register the signal handler for graceful shutdown
    signal(SIGINT, signal_handler);

    // Initialize the pigpio library and I2C
    if (initialize() != 0) {
        return 1;
    }

    sensor_data_t sensor_data;

    // Main loop to read and log data
    while (program_running) {
        if (read_distance(&sensor_data) == 0) {
            log_data(sensor_data);
        } else {
            fprintf(stderr, "Failed to read distance after multiple retries.\n");
        }

        gpioDelay(100); // Wait 100ms
    }

    // Clean up resources before exiting
    cleanup();

    return 0;
}

