#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// VL53L4CX I2C address
#define VL53L4CX_ADDR 0x29

// I2C bus
#define I2C_BUS 1

// I2C handle
int i2c_handle;

// Function prototypes
int vl53l4cx_init();
int vl53l4cx_read_distance(int *distance);
void log_distance(int distance);
void signal_handler(int signal);

// Structure to hold program state
struct ProgramState {
    int running;
};

struct ProgramState state = {1}; // Initialize running to 1

// Signal handler function
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    state.running = 0; // Set running to 0 to exit the main loop
    i2cClose(i2c_handle);
    gpioTerminate();
    exit(0);
}

// VL53L4CX initialization function
int vl53l4cx_init() {
    int status;

    // Soft reset
    status = i2cWriteByteData(i2c_handle, 0x7FFB, 0x00); // Register address is 0x7FFB, value is 0x00
    if (status != 0) {
        fprintf(stderr, "Error: VL53L4CX soft reset failed (status = %d)\n", status);
        return -1;
    }
    gpioDelay(10000); // Wait 10 ms

    // Start ranging
    status = i2cWriteByteData(i2c_handle, 0x0010, 0x01); // Register address is 0x0010, value is 0x01
    if (status != 0) {
        fprintf(stderr, "Error: VL53L4CX start ranging failed (status = %d)\n", status);
        return -1;
    }

    return 0;
}

// VL53L4CX distance reading function
int vl53l4cx_read_distance(int *distance) {
    int status;
    uint8_t high_byte, low_byte;

    // Read interrupt status
    status = i2cReadByteData(i2c_handle, 0x0046);
    if (status < 0) {
        fprintf(stderr, "Error: VL53L4CX read interrupt status failed (status = %d)\n", status);
        return -1;
    }

    if ((status & 0x01) != 0) {
        // Read distance data
        status = i2cReadByteData(i2c_handle, 0x0096); // High byte
        if (status < 0) {
            fprintf(stderr, "Error: VL53L4CX read distance high byte failed (status = %d)\n", status);
            return -1;
        }
        high_byte = (uint8_t)status;

        status = i2cReadByteData(i2c_handle, 0x0097); // Low byte
        if (status < 0) {
            fprintf(stderr, "Error: VL53L4CX read distance low byte failed (status = %d)\n", status);
            return -1;
        }
        low_byte = (uint8_t)status;

        *distance = (high_byte << 8) | low_byte;
        return 0;
    } else {
        return -1; // No new data available
    }
}

// Distance logging function
void log_distance(int distance) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    long microseconds = (long)rawtime % 1000000;

    printf("Timestamp: %s.%06ld, Distance: %d mm\n", timestamp, microseconds, distance);
}

int main() {
    int distance;
    int status;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, VL53L4CX_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: I2C open failed (handle = %d)\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize VL53L4CX sensor
    if (vl53l4cx_init() != 0) {
        fprintf(stderr, "Error: VL53L4CX initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (state.running) {
        status = vl53l4cx_read_distance(&distance);
        if (status == 0) {
            log_distance(distance);
        } else {
            // Optionally log the error here, but we already logged it in vl53l4cx_read_distance
        }
        gpioDelay(500000); // Wait 500 ms
    }

    // Cleanup (should not reach here if signal handler works correctly)
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

