#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

// Define GPIO pins
#define TRIGGER_PIN 23
#define ECHO_PIN 24
#define SERVO_PIN 17

// Define constants
#define SPEED_OF_SOUND 34300.0 // cm/s
#define TIMEOUT_MS 50
#define MIN_DISTANCE 2.0      // cm
#define MAX_DISTANCE 400.0    // cm
#define MIN_ANGLE -90.0       // degrees
#define MAX_ANGLE 90.0        // degrees

// Global variables
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
void signal_handler(int signal);
void trigger_sensor();
long pulse_width();
float calculate_distance(long pulse_width);
float map_distance_to_angle(float distance);
void set_servo_angle(float angle);
void log_data(float distance, float angle);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Function to trigger the ultrasonic sensor
void trigger_sensor() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10 us trigger pulse
    gpioWrite(TRIGGER_PIN, 0);
}

// Function to measure the pulse width of the echo signal
long pulse_width() {
    long start_tick, end_tick, pulse_width;
    int start_sec, start_micros, end_sec, end_micros;

    // Wait for echo to go high (with timeout)
    int timeout_counter = 0;
    while (gpioRead(ECHO_PIN) == 0 && timeout_counter < TIMEOUT_MS * 1000) {
        gpioDelay(1); // Check every 1 us
        timeout_counter++;
    }
    if (timeout_counter >= TIMEOUT_MS * 1000) {
        fprintf(stderr, "Error: Echo signal stuck low.\n");
        return -1; // Timeout error
    }

    gpioTime(PI_TIME_RELATIVE, &start_sec, &start_micros);
    start_tick = start_sec * 1000000 + start_micros;

    // Wait for echo to go low (with timeout)
    timeout_counter = 0;
    while (gpioRead(ECHO_PIN) == 1 && timeout_counter < TIMEOUT_MS * 1000) {
        gpioDelay(1); // Check every 1 us
        timeout_counter++;
    }
    if (timeout_counter >= TIMEOUT_MS * 1000) {
        fprintf(stderr, "Error: Echo signal stuck high.\n");
        return -1; // Timeout error
    }

    gpioTime(PI_TIME_RELATIVE, &end_sec, &end_micros);
    end_tick = end_sec * 1000000 + end_micros;

    pulse_width = end_tick - start_tick;
    return pulse_width;
}

// Function to calculate the distance in centimeters
float calculate_distance(long pulse_width) {
    if (pulse_width < 0) return -1.0; // Error value
    return (pulse_width / 1000000.0) * SPEED_OF_SOUND / 2.0;
}

// Function to map the distance to a servo angle
float map_distance_to_angle(float distance) {
    if (distance < MIN_DISTANCE) return MIN_ANGLE;
    if (distance > MAX_DISTANCE) return MAX_ANGLE;
    return MIN_ANGLE + (distance - MIN_DISTANCE) * (MAX_ANGLE - MIN_ANGLE) / (MAX_DISTANCE - MIN_DISTANCE);
}

// Function to set the servo angle
void set_servo_angle(float angle) {
    // Convert angle to pulse width (SG90 servo typically 1000-2000 us for 0-180 degrees)
    int pulse_width = (int)(1000 + angle * (1000.0 / 180.0)); // Assuming 0-180 degree range
    gpioServo(SERVO_PIN, pulse_width);
}

// Function to log the data to a file
void log_data(float distance, float angle) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, Distance: %.2f cm, Angle: %.2f degrees\n", timestamp, distance, angle);
    fflush(log_file); // Ensure data is written to disk immediately
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(SERVO_PIN, PI_OUTPUT);

    // Open log file
    log_file = fopen("sensor_data.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Parking Assist System running. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        trigger_sensor();
        long pulse_width = pulse_width();
        float distance = calculate_distance(pulse_width);

        if (distance > 0) {
            float angle = map_distance_to_angle(distance);
            set_servo_angle(angle);
            log_data(distance, angle);
        } else {
            fprintf(stderr, "Error: Invalid distance reading.\n");
        }

        gpioDelay(200); // 200 ms delay
    }

    // Cleanup
    gpioServo(SERVO_PIN, 0); // Stop servo
    fclose(log_file);
    gpioTerminate();

    printf("Program terminated.\n");
    return 0;
}

