#include <sys/stat.h>
#include <sys/types.h>
#include <sys/msg.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define VL53L1X_ADDR 0x29
#define MODEL_ID_REG 0x010F
#define SOFTWARE_RESET_REG 0x0000
#define TIMING_BUDGET_REG 0x008E
#define START_RANGING_REG 0x0080
#define DATA_READY_REG 0x0089
#define DISTANCE_REG 0x0096
#define BUZZER_GPIO 23
#define DISTANCE_THRESHOLD 100 // mm
#define MESSAGE_QUEUE_NAME "/distance_queue"
#define MAX_MSG_SIZE 256

// Message queue structure
struct msgbuf {
    long mtype; // Message type (must be > 0)
    char mtext[MAX_MSG_SIZE]; // Message text
};

// Global variables
int i2c_handle;
int message_queue_id;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int init_message_queue();
int init_sensor();
int read_distance();
void control_buzzer(int distance);
void log_distance(int distance);
void signal_handler(int signal);

// Signal handler
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Initialize message queue
int init_message_queue() {
    message_queue_id = msgget(IPC_PRIVATE, 0666 | IPC_CREAT);
    if (message_queue_id < 0) {
        fprintf(stderr, "Error creating message queue: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Initialize VL53L1X sensor
int init_sensor() {
    int model_id;

    // Check model ID
    model_id = i2cReadByteData(i2c_handle, MODEL_ID_REG);
    if (model_id < 0) {
        fprintf(stderr, "Error reading model ID: %s\n", strerror(errno));
        return -1;
    }
    if (model_id != 0xEA) {
        fprintf(stderr, "Error: Incorrect model ID (0x%02X, expected 0xEA)\n", model_id);
        return -1;
    }
    printf("VL53L1X sensor found with model ID 0x%02X\n", model_id);

    // Software reset
    if (i2cWriteByteData(i2c_handle, SOFTWARE_RESET_REG, 0x00) < 0) {
        fprintf(stderr, "Error writing software reset (0x00): %s\n", strerror(errno));
