#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// Define GPIO pins
#define TRIGGER_PIN 17
#define ECHO_PIN 27
#define BUZZER_PIN 22

// Define constants
#define SPEED_OF_SOUND 34300.0 // cm/s
#define TRIGGER_PULSE_DURATION 10 // microseconds
#define BUZZER_THRESHOLD 30.0 // cm
#define BUZZER_ON_TIME 500 // milliseconds
#define BUZZER_OFF_TIME 500 // milliseconds

// Global variables
static volatile int echo_start_tick = 0;
static volatile int echo_end_tick = 0;
static volatile int echo_received = 0;
static volatile int distance_valid = 0;
static volatile float distance = 0.0;
static volatile int buzzer_active = 0;

// Function prototypes
void trigger_pulse();
void echo_callback(int gpio, int level, uint32_t tick);
float calculate_distance(int pulse_width);
void display_distance(float distance);
void control_buzzer(float distance);
void signal_handler(int signal);

// Function to generate a 10us trigger pulse
void trigger_pulse() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(TRIGGER_PULSE_DURATION);
    gpioWrite(TRIGGER_PIN, 0);
}

// Callback function for echo pin interrupts
void echo_callback(int gpio, int level, uint32_t tick) {
    if (level == 1) {
        echo_start_tick = tick;
        echo_received = 0; // Reset flag for new measurement
    } else if (level == 0) {
        echo_end_tick = tick;
        echo_received = 1; // Set flag to indicate echo received
    }
}

// Function to calculate distance from pulse width
float calculate_distance(int pulse_width) {
    if (pulse_width < 0) {
        return -1.0; // Indicate error
    }
    return (float)pulse_width * SPEED_OF_SOUND / 2000000.0; // Divide by 2 for one-way distance
}

// Function to display distance on the console
void display_distance(float distance) {
    printf("Distance: %.2f cm\n", distance);
}

// Function to control the buzzer based on distance
void control_buzzer(float distance) {
    if (distance < BUZZER_THRESHOLD && !buzzer_active) {
        gpioWrite(BUZZER_PIN, 1); // Turn buzzer on
        buzzer_active = 1;
        gpioDelay(BUZZER_ON_TIME);
    } else if (distance >= BUZZER_THRESHOLD && buzzer_active) {
        gpioWrite(BUZZER_PIN, 0); // Turn buzzer off
        buzzer_active = 0;
        gpioDelay(BUZZER_OFF_TIME);
    }
}

// Signal handler for clean shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    gpioWrite(BUZZER_PIN, 0); // Turn off buzzer
    gpioTerminate(); // Terminate pigpio
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(BUZZER_PIN, PI_OUTPUT);

    // Register interrupt callback for echo pin
    if (gpioSetAlertFuncEx(ECHO_PIN, echo_callback, NULL) != 0) {
        fprintf(stderr, "Failed to register alert function\n");
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (1) {
        trigger_pulse(); // Send trigger pulse
        gpioDelay(50); // Wait for echo

        if (echo_received) {
            int pulse_width = echo_end_tick - echo_start_tick;
            distance = calculate_distance(pulse_width);

            if (distance < 2.0 || distance > 400.0) {
                fprintf(stderr, "Invalid distance reading: %.2f cm\n", distance);
                distance_valid = 0;
            } else {
                distance_valid = 1;
            }

            display_distance(distance);
            control_buzzer(distance);
        } else {
            fprintf(stderr, "Sensor absent or timeout\n");
            distance_valid = 0;
        }

        gpioDelay(100); // Wait 100ms
    }

    return 0;
}

