#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <mosquitto.h>
#include <stdbool.h>

// Configuration
#define I2C_BUS 1
#define VL53L1X_ADDR 0x29
#define SERVO_PIN 18
#define OPEN_ANGLE 1000 // Example: 1000 us pulse width for 0 degrees
#define CLOSE_ANGLE 2000 // Example: 2000 us pulse width for 180 degrees
#define DISTANCE_THRESHOLD 200 // mm
#define MQTT_BROKER "localhost" // Replace with your broker address
#define MQTT_PORT 1883
#define MQTT_CLIENT_ID "gate_controller"
#define MQTT_TOPIC "gate/control"
#define MQTT_STATUS_TOPIC "gate/status"

// Global variables
static int i2c_handle;
static struct mosquitto *mosq = NULL;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int vl53l1x_init();
int vl53l1x_read_distance();
void servo_set_angle(int angle);
void log_event(const char *event);
void mqtt_connect_callback(struct mosquitto *mosq, void *userdata, int result);
void mqtt_message_callback(struct mosquitto *mosq, void *userdata, const struct mosquitto_message *message);
void signal_handler(int signal);

// VL53L1X register addresses (Example - adjust based on datasheet)
#define VL53L1X_REG_IDENTIFICATION_MODEL_ID 0x00c0
#define VL53L1X_REG_IDENTIFICATION_REVISION_ID 0x00c2
#define VL53L1X_REG_SYSRANGE_START 0x0040
#define VL53L1X_REG_RESULT_RANGE_STATUS 0x0014
#define VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0 0x0050

// VL53L1X initialization sequence (Example - adjust based on datasheet)
int vl53l1x_init() {
    // Software reset
    if (i2cWriteByteData(i2c_handle, 0x002d, 0x04) < 0) {
        fprintf(stderr, "Error: VL53L1X software reset failed\n");
        return -1;
    }
    gpioDelay(10000); // 10 ms

    // Check sensor ID (Example)
    int sensor_id = i2cReadByteData(i2c_handle, VL53L1X_REG_IDENTIFICATION_MODEL_ID);
    if (sensor_id < 0) {
        fprintf(stderr, "Error: VL53L1X sensor ID read failed\n");
        return -1;
    }
    if (sensor_id != 0xEA) {
        fprintf(stderr, "Error: VL53L1X sensor ID mismatch: 0x%02x\n", sensor_id);
        return -1;
    }

    // Start ranging
    if (i2cWriteByteData(i2c_handle, VL53L1X_REG_SYSRANGE_START, 0x01) < 0) {
        fprintf(stderr, "Error: VL53L1X start ranging failed\n");
        return -1;
    }

    return 0;
}

// VL53L1X read distance
int vl53l1x_read_distance() {
    int distance = -1;
    int retries = 3;

    while (retries > 0) {
        int range_status = i2cReadByteData(i2c_handle, VL53L1X_REG_RESULT_RANGE_STATUS);
        if (range_status < 0) {
            fprintf(stderr, "Error: VL53L1X range status read failed\n");
            gpioDelay(10000); // 10 ms
            retries--;
            continue;
        }

        distance = i2cReadWordData(i2c_handle, VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0);
        if (distance < 0) {
            fprintf(stderr, "Error: VL53L1X distance read failed\n");
            gpioDelay(10000); // 10 ms
            retries--;
            continue;
        }

        if (range_status == 0) {
            fprintf(stderr, "Error: VL53L1X sensor absent\n");
            distance = -1; // Indicate sensor absent
            break;
        }

        return distance;
    }

    fprintf(stderr, "Error: VL53L1X read distance failed after multiple retries\n");
    return -1;
}

// Servo control
void servo_set_angle(int angle) {
    gpioServo(SERVO_PIN, angle);
}

// Logging
void log_event(const char *event) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(log_file, "[%d-%02d-%02d %02d:%02d:%02d] %s\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, event);
    fflush(log_file);
}

// MQTT callbacks
void mqtt_connect_callback(struct mosquitto *mosq, void *userdata, int result) {
    if (result == MOSQ_ERR_SUCCESS) {
        printf("MQTT connected to %s:%d\n", MQTT_BROKER, MQTT_PORT);
        mosquitto_subscribe(mosq, NULL, MQTT_TOPIC, 0);
    } else {
        fprintf(stderr, "MQTT connection error: %s\n", mosquitto_connack_string(result));
    }
}

void mqtt_message_callback(struct mosquitto *mosq, void *userdata, const struct mosquitto_message *message) {
    if (message->payloadlen > 0) {
        printf("Received MQTT message on topic %s: %s\n", message->topic, (char *)message->payload);

        if (strcmp(message->topic, MQTT_TOPIC) == 0) {
            if (strcmp((char *)message->payload, "force_open") == 0) {
                servo_set_angle(OPEN_ANGLE);
                log_event("Gate opened (MQTT force_open)");
            } else if (strcmp((char *)message->payload, "force_close") == 0) {
                servo_set_angle(CLOSE_ANGLE);
