#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>
#include <string.h>

// Define GPIO pins
#define TRIG_PIN 23
#define ECHO_PIN 24

// Define constants
#define SPEED_OF_SOUND 0.0343 // cm/us
#define MIN_PULSE_WIDTH 100   // us
#define MAX_PULSE_WIDTH 30000 // us
#define TIMEOUT_US 60000      // us
#define MEASUREMENT_INTERVAL_MS 200

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;

// Structure to hold timestamp data
typedef struct {
    uint32_t rising_tick;
    uint32_t falling_tick;
} Timestamps;

// Function prototypes
void signal_handler(int signal);
void trigger_pulse();
void echo_callback(int gpio, int level, uint32_t tick, void *user_data);
double calculate_distance(uint32_t pulse_width);
void log_distance(double distance);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to generate a 10us trigger pulse
void trigger_pulse() {
    gpioWrite(TRIG_PIN, 1);
    gpioDelay(10);
    gpioWrite(TRIG_PIN, 0);
}

// Callback function for ECHO pin changes
void echo_callback(int gpio, int level, uint32_t tick, void *user_data) {
    static Timestamps timestamps = {0, 0};
    static uint32_t last_tick = 0;

    if (level == 1) {
        timestamps.rising_tick = tick;
        last_tick = tick;
    } else if (level == 0) {
        timestamps.falling_tick = tick;

        // Handle tick wraparound
        uint32_t pulse_width = (tick < last_tick) ? (tick + (0xFFFFFFFF - last_tick) + 1) : (tick - last_tick);

        if (pulse_width >= MIN_PULSE_WIDTH && pulse_width <= MAX_PULSE_WIDTH) {
            double distance = calculate_distance(pulse_width);
            log_distance(distance);
        } else {
            fprintf(stderr, "Warning: Invalid pulse width: %u us\n", pulse_width);
            if (log_file != NULL) {
                fprintf(log_file, "Warning: Invalid pulse width: %u us\n", pulse_width);
                fflush(log_file);
            }
        }
    }
}

// Function to calculate distance from pulse width
double calculate_distance(uint32_t pulse_width) {
    return (pulse_width * SPEED_OF_SOUND) / 2.0;
}

// Function to log distance to file
void log_distance(double distance) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    printf("%s Distance: %.2f cm\n", timestamp, distance);

    if (log_file != NULL) {
        fprintf(log_file, "%s Distance: %.2f cm\n", timestamp, distance);
        fflush(log_file);
    }
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIG_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);

    // Set pull-down resistor on ECHO pin
    gpioSetPullUpDown(ECHO_PIN, PI_PUD_DOWN);

    // Open log file
    log_file = fopen("distance_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Register callback function for ECHO pin
    gpioSetAlertFuncEx(ECHO_PIN, echo_callback, NULL);

    printf("Distance measurement started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        trigger_pulse();
        gpioDelay(MEASUREMENT_INTERVAL_MS);
    }

    // Cleanup
    gpioSetAlertFuncEx(ECHO_PIN, NULL, NULL); // Disable callback
    fclose(log_file);
    gpioTerminate();

    return 0;
}

