#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <time.h>

// Define constants
#define I2C_BUS 1
#define VL53L1X_ADDR 0x29
#define GPIO_TRIGGER 24
#define GPIO_FORWARD 17
#define GPIO_BACKWARD 18
#define DISTANCE_THRESHOLD_FORWARD 100
#define DISTANCE_THRESHOLD_BACKWARD 300
#define MAX_RETRIES 3
#define MAX_BACKOFF_DELAY 100 // milliseconds

// Global variables
int i2c_handle;
volatile int distance = -1; // Initialize to an invalid value
volatile int motor_state = 0; // 0: stopped, 1: forward, -1: backward
volatile sig_atomic_t program_running = 1;

// Function prototypes
int init_i2c();
int init_vl53l1x();
int trigger_measurement();
int read_distance(int *distance);
void control_motor(int distance);
void isr_trigger();
void signal_handler(int signal);
void log_data(int distance, int motor_state);

// I2C initialization function
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// VL53L1X initialization function
int init_vl53l1x() {
    int retries = 0;
    int status;

    // Soft reset
    while (retries < MAX_RETRIES) {
        status = i2cWriteByteData(i2c_handle, 0x0000, 0x00);
        if (status >= 0) break;
        fprintf(stderr, "Error writing to VL53L1X (soft reset): %d, retrying...\n", status);
        gpioDelay(10 * (1 << retries)); // Exponential backoff
        retries++;
    }
    if (retries == MAX_RETRIES) {
        fprintf(stderr, "Failed to reset VL53L1X after multiple retries.\n");
        return -1;
    }
    gpioDelay(1000); // Wait 1 ms

    retries = 0;
    while (retries < MAX_RETRIES) {
        status = i2cWriteByteData(i2c_handle, 0x0000, 0x01);
        if (status >= 0) break;
        fprintf(stderr, "Error writing to VL53L1X (start measurement): %d, retrying...\n", status);
        gpioDelay(10 * (1 << retries)); // Exponential backoff
        retries++;
    }
    if (retries == MAX_RETRIES) {
        fprintf(stderr, "Failed to start measurement after multiple retries.\n");
        return -1;
    }

    return 0;
}

// Trigger measurement function
int trigger_measurement() {
    int status = gpioWrite(GPIO_TRIGGER, 1);
    if (status != 0) {
        fprintf(stderr, "Error writing to GPIO %d: %d\n", GPIO_TRIGGER, status);
        return -1;
    }
    gpioDelay(1); // 1 us pulse
    status = gpioWrite(GPIO_TRIGGER, 0);
    if (status != 0) {
        fprintf(stderr, "Error writing to GPIO %d: %d\n", GPIO_TRIGGER, status);
        return -1;
    }
    return 0;
