// Read distance function
int read_distance(int *distance) {
    int retries = 0;
    int status;
    unsigned char data[2];

    // Poll for data ready
    while (retries < MAX_RETRIES) {
        status = i2cReadByteData(i2c_handle, 0x0089);
        if (status < 0) {
            fprintf(stderr, "Error reading data ready status: %d, retrying...\n", status);
            gpioDelay(10 * (1 << retries)); // Exponential backoff
            retries++;
            continue;
        }
        if (status & 0x01) break; // Data ready
        gpioDelay(10 * (1 << retries)); // Exponential backoff
        retries++;
    }
    if (retries == MAX_RETRIES) {
        fprintf(stderr, "Timeout waiting for data ready.\n");
        return -1;
    }

    // Read distance data
    retries = 0;
    while (retries < MAX_RETRIES) {
        status = i2cReadI2CBlockData(i2c_handle, 0x0096, (char *)data, 2);
        if (status >= 0) break;
        fprintf(stderr, "Error reading distance data: %d, retrying...\n", status);
        gpioDelay(10 * (1 << retries)); // Exponential backoff
        retries++;
    }
    if (retries == MAX_RETRIES) {
        fprintf(stderr, "Failed to read distance data after multiple retries.\n");
        return -1;
    }

    *distance = (data[0] << 8) | data[1];
    return 0;
}

// Control motor function
void control_motor(int distance) {
    if (distance < DISTANCE_THRESHOLD_FORWARD) {
        if (motor_state != 1) {
            gpioWrite(GPIO_FORWARD, 1);
            gpioWrite(GPIO_BACKWARD, 0);
            motor_state = 1;
            printf("Motor: Forward\n");
        }
    } else if (distance > DISTANCE_THRESHOLD_BACKWARD) {
        if (motor_state != -1) {
            gpioWrite(GPIO_FORWARD, 0);
            gpioWrite(GPIO_BACKWARD, 1);
            motor_state = -1;
            printf("Motor: Backward\n");
        }
    } else {
        if (motor_state != 0) {
            gpioWrite(GPIO_FORWARD, 0);
            gpioWrite(GPIO_BACKWARD, 0);
            motor_state = 0;
            printf("Motor: Stopped\n");
        }
    }
}

