        return -1;
    }

    if (read(fd, value, 1) != 1) {
        perror("I2C Read Error");
        return -1;
    }
    return 0;
}

// MPR121 Soft Reset Function
int mpr121_soft_reset(int fd) {
    if (i2c_write_reg(fd, MPR121_SOFTRESET, 0x63) != 0) {
        fprintf(stderr, "Error: Soft reset failed.\n");
        return -1;
    }
    usleep(100000); // Wait for reset to complete
    return 0;
}

// MPR121 Initialization Function
int mpr121_init(int fd) {
    // Stop Mode
    if (i2c_write_reg(fd, MPR121_ELECONFIG0, 0x00) != 0) return -1;
    if (i2c_write_reg(fd, MPR121_ELECONFIG1, 0x00) != 0) return -1;

    // Baseline Filtering
    if (i2c_write_reg(fd, MPR121_MHDR, 0x01) != 0) return -1;
    if (i2c_write_reg(fd, MPR121_NHDR, 0x01) != 0) return -1;
    if (i2c_write_reg(fd, MPR121_NCLR, 0x0E) != 0) return -1;
    if (i2c_write_reg(fd, MPR121_FDLR, 0x00) != 0) return -1;

    // Auto-Configuration Thresholds
    if (i2c_write_reg(fd, 0x5A, 0x0B) != 0) return -1;
    if (i2c_write_reg(fd, 0x5D, 0xC8) != 0) return -1;
    if (i2c_write_reg(fd, 0x5E, 0x82) != 0) return -1;
    if (i2c_write_reg(fd, 0x5F, 0xB4) != 0) return -1;

    // Enable All 12 Electrodes in Run Mode
    if (i2c_write_reg(fd, MPR121_ELECONFIG0, 0x0C) != 0) return -1;
    if (i2c_write_reg(fd, MPR121_ELECONFIG1, 0x0C) != 0) return -1;

    return 0;
}

// MPR121 Read Touch Status Function
int mpr121_read_touch_status(int fd, unsigned short *touch_status) {
    unsigned char low, high;

    if (i2c_read_reg(fd, MPR121_TOUCHSTATUS_L, &low) != 0) return -1;
    if (i2c_read_reg(fd, MPR121_TOUCHSTATUS_H, &high) != 0) return -1;

    *touch_status = ((unsigned short)high << 8) | low;
    return 0;
}

// Set LED Pattern Function
int set_led_pattern(struct gpiod_line *lines, const unsigned char *pattern) {
    if (!lines || !pattern) return -1;

    for (int i = 0; i < 4; i++) {
        if (lines[i] && pattern[i]) {
            if (gpiod_line_set_value(lines[i], 1) < 0) {
                perror("Error setting GPIO high");
                return -1;
            }
        } else if (lines[i]) {
            if (gpiod_line_set_value(lines[i], 0) < 0) {
                perror("Error setting GPIO low");
                return -1;
            }
        }
    }
    return 0;
}

// Log Event Function
void log_event(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[26];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "[%s] %s\n", timestamp, message);
    fflush(log_file);
    printf("[%s] %s\n", timestamp, message);
}

// Signal Handler Function
void signal_handler(int sig) {
    terminate = 1;
    printf("Signal received, exiting...\n");
}

int main() {
    // Signal Handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C Bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Error opening I2C bus");
        return 1;
    }

    // Specify the address of the slave device
    if (ioctl(i2c_fd, I2C_SLAVE, MPR121_ADDR) < 0) {
        perror("Error setting I2C slave address");
        close(i2c_fd);
        return 1;
    }

    // Open GPIO Chip
    gpio_chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!gpio_chip) {
        perror("Error opening GPIO chip");
        close(i2c_fd);
        return 1;
    }

    // Get GPIO Lines
    gpio_lines[0] = gpiod_chip_get_line(gpio_chip, GPIO_17);
    gpio_lines[1] = gpiod_chip_get_line(gpio_chip, GPIO_18);
    gpio_lines[2] = gpiod_chip_get_line(gpio_chip, GPIO_27);
    gpio_lines[3] = gpiod_chip_get_line(gpio_chip, GPIO_22);

    for (int i = 0; i < 4; i++) {
        if (!gpio_lines[i]) {
            perror("Error getting GPIO line");
            goto cleanup_gpio;
        }

        struct gpiod_line_request_config config;
        memset(&config, 0, sizeof(config));
        config.consumer = "mpr121_art";
        config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;

        if (gpiod_line_request(gpio_lines[i], &config, 0) < 0) {
            perror("Error requesting GPIO line");
            goto cleanup_gpio;
        }
    }

    // Open Log File
    log_file = fopen("proximity_log.txt", "a");
    if (!log_file) {
        perror("Error opening log file");
        goto cleanup_gpio;
    }

    // MPR121 Initialization
    if (mpr121_soft_reset(i2c_fd) != 0) {
        fprintf(stderr, "Error: MPR121 soft reset failed.\n");
        goto cleanup;
    }
    if (mpr121_init(i2c_fd) != 0) {
        fprintf(stderr, "Error: MPR121 initialization failed.\n");
        goto cleanup;
    }

    unsigned short touch_status;
    int electrode_active = -1; // Initialize to an invalid value

    // Main Loop
    while (!terminate) {
        if (mpr121_read_touch_status(i2c_fd, &touch_status) == 0) {
            for (int i = 0; i < 12; i++) {
                if (touch_status & (1 << i)) {
                    if (electrode_active != i) {
                        log_event("Electrode touched");
                        electrode_active = i;
                        set_led_pattern(gpio_lines, led_patterns + i);
                    }
                    break; // Only one electrode active at a time
                }
            }

            if (electrode_active == -1) {
                log_event("No electrode touched");
                set_led_pattern(gpio_lines, led_patterns + 12); // Turn off all LEDs
            }
        } else {
            fprintf(stderr, "Error reading touch status.\n");
        }

        usleep(50000); // 50ms delay
    }

    // Cleanup
cleanup:
    log_event("Exiting program");

    // Close GPIO Lines
    for (int i = 0; i < 4; i++) {
        if (gpio_lines[i]) {
            gpiod_line_release(gpio_lines[i]);
        }
    }

    // Close GPIO Chip
cleanup_gpio:
    if (gpio_chip) {
        gpiod_chip_close(gpio_chip);
    }

    // Close I2C Bus
    if (i2c_fd != -1) {
        close(i2c_fd);
    }

    // Close Log File
    if (log_file) {
        fclose(log_file);
    }

    return 0;
}

