                gpioDelay(LED_ON_DURATION_MS * 1000); // Wait for 1 second
                control_led(0); // Turn LED off
                gpioDelay(DEBOUNCE_MS * 1000); // Debounce
            }
        } else {
            if (last_touch_state == 1) {
                // Optionally, you could add code here to handle the release event
            }
        }

        last_touch_state = current_touch_state;
        gpioDelay(10); // Small delay to avoid busy-waiting
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioWrite(LED_GPIO, 0); // Ensure LED is off
    gpioTerminate();

    return 0;
