#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <syslog.h>
#include <time.h>
#include <sys/time.h>
#include <pigpio.h>
#include <errno.h>

// VL53L1X I2C address
#define VL53L1X_ADDR 0x29

// VL53L1X register addresses
#define VL53L1X_REG_IDENTIFICATION_MODEL_ID 0x0000
#define VL53L1X_REG_IDENTIFICATION_REVISION_ID 0x0001
#define VL53L1X_REG_PRE_RANGE_CONFIG_TIMEOUT_MACROP_HI 0x0015
#define VL53L1X_REG_FINAL_RANGE_CONFIG_TIMEOUT_MACROP_HI 0x0016
#define VL53L1X_REG_SYSTEM_SEQUENCE_CONFIG 0x0021
#define VL53L1X_REG_SYSTEM_START 0x0008
#define VL53L1X_REG_RESULT_RANGE_STATUS 0x0014
#define VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0 0x0050

// GPIO pin for XSHUT
#define XSHUT_PIN 27

// I2C bus
#define I2C_BUS 1

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_pigpio();
int init_i2c();
int init_vl53l1x();
int read_distance(int *distance, int *status);
void log_data(int distance, int status);
void signal_handler(int signal);

// Structure to hold sensor configuration
typedef struct {
    int i2c_address;
    int xshut_pin;
    int i2c_bus;
} sensor_config_t;

// Function to initialize pigpio
int init_pigpio() {
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        return -1;
    }
    return 0;
}

// Function to initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        syslog(LOG_ERR, "Failed to open I2C device: %s", strerror(errno));
        return -1;
    }
    return 0;
}

// Function to initialize the VL53L1X sensor
int init_vl53l1x() {
    // Check sensor ID
    char id;
    if (i2cReadI2CBlockData(i2c_handle, VL53L1X_REG_IDENTIFICATION_MODEL_ID, &id, 1) != 1) {
        syslog(LOG_ERR, "Failed to read sensor ID");
        return -1;
    }
    if (id != 0xEA) {
        syslog(LOG_ERR, "Incorrect sensor ID: 0x%02X", id);
        return -1;
    }

    // Configure sensor for continuous ranging
    char data[2];
    data[0] = 0x00; // Continuous mode
    if (i2cWriteI2CBlockData(i2c_handle, 0x0018, data, 1) != 1) {
        syslog(LOG_ERR, "Failed to write to register 0x0018");
        return -1;
    }

    data[0] = 0x00; // No timeout
    if (i2cWriteI2CBlockData(i2c_handle, 0x0019, data, 1) != 1) {
        syslog(LOG_ERR, "Failed to write to register 0x0019");
        return -1;
    }

    data[0] = 0x01; // Start ranging
    if (i2cWriteI2CBlockData(i2c_handle, 0x0020, data, 1) != 1) {
        syslog(LOG_ERR, "Failed to write to register 0x0020");
        return -1;
    }

    return 0;
}

// Function to read distance from the VL53L1X sensor
int read_distance(int *distance, int *status) {
    char data[2];

    // Read range status
    if (i2cReadI2CBlockData(i2c_handle, VL53L1X_REG_RESULT_RANGE_STATUS, data, 1) != 1) {
        syslog(LOG_ERR, "Failed to read range status");
        return -1;
    }
    *status = data[0];

    // Read distance
    if (i2cReadI2CBlockData(i2c_handle, VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0, data, 2) != 2) {
        syslog(LOG_ERR, "Failed to read distance");
        return -1;
    }

    // Combine the two bytes to form the distance
    *distance = (data[1] << 8) | data[0];

    return 0;
}

// Function to log data to the systemd journal
void log_data(int distance, int status) {
    struct timeval tv;
    gettimeofday(&tv, NULL);
    time_t nowtime = tv.tv_sec;
    struct tm *nowtm = localtime(&nowtime);
    char tmbuf[64], buf[64];
    strftime(tmbuf, sizeof(tmbuf), "%Y-%m-%d %H:%M:%S", nowtm);
    snprintf(buf, sizeof(buf), "%s.%06ld", tmbuf, tv.tv_usec);

    syslog(LOG_INFO, "Timestamp: %s, Distance: %d mm, Status: 0x%02X", buf, distance, status);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    syslog(LOG_INFO, "Signal received, terminating...");
    terminate = 1;
}

int main() {
    // Open syslog
    openlog("vl53l1x_sensor", LOG_PID | LOG_CONS, LOG_USER);

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (init_pigpio() != 0) {
        syslog(LOG_ERR, "Failed to initialize pigpio, exiting");
        closelog();
        return 1;
    }

    // Initialize I2C
