#include <string.h>

// Constants
#define I2C_BUS 1
#define VL53L1X_ADDR 0x29
#define GATE_GPIO 24
#define DISTANCE_THRESHOLD 20 // cm
#define LOG_FILE "gate_log.txt"

// VL53L1X Register Addresses
#define VL53L1X_REG_IDENTIFICATION_MODEL_ID 0x010F
#define VL53L1X_REG_RANGING_MODE 0x0021
#define VL53L1X_REG_START_STOP_MEASURE 0x0015
#define VL53L1X_REG_DISTANCE 0x0089

// Global Variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function Prototypes
int init_vl53l1x();
int read_distance(int *distance);
void control_gate(int distance);
void log_event(const char *message);
void signal_handler(int signal);

// Signal Handler
void signal_handler(int signal) {
    terminate = 1;
    log_event("Received signal, shutting down...");
}

// Initialize VL53L1X Sensor
int init_vl53l1x() {
    int status;

    // Check Model ID
    status = i2cWriteByteData(i2c_handle, VL53L1X_REG_IDENTIFICATION_MODEL_ID, 0x00); // Dummy write to trigger read
    if (status != 0) {
        log_event("Error writing to VL53L1X for model ID read.");
        return -1;
    }
    int model_id = i2cReadByteData(i2c_handle, VL53L1X_REG_IDENTIFICATION_MODEL_ID);
    if (model_id != 0xEA) {
        log_event("VL53L1X model ID check failed.");
        return -1;
    }

    // Set Ranging Mode to Short
    status = i2cWriteByteData(i2c_handle, VL53L1X_REG_RANGING_MODE, 0x00);
    if (status != 0) {
        log_event("Error setting ranging mode.");
        return -1;
    }

    // Start Ranging
    status = i2cWriteByteData(i2c_handle, VL53L1X_REG_START_STOP_MEASURE, 0x01);
    if (status != 0) {
        log_event("Error starting ranging.");
        return -1;
    }

    log_event("VL53L1X sensor initialized successfully.");
    return 0;
}

// Read Distance from VL53L1X Sensor
int read_distance(int *distance) {
    int status;
    uint8_t data[2];

    // Read distance data (2 bytes)
    status = i2cReadI2CBlockData(i2c_handle, VL53L1X_REG_DISTANCE, (char *)data, 2);
    if (status != 2) {
        log_event("Error reading distance data.");
        return -1;
    }

    *distance = (data[0] << 8) | data[1];
    return 0;
}

// Control Gate Actuator
void control_gate(int distance) {
    static int gate_open = 0; // Track gate state

    if (distance < DISTANCE_THRESHOLD && !gate_open) {
        gpioWrite(GATE_GPIO, 1); // Open gate
        gate_open = 1;
        log_event("Gate opened.");
    } else if (distance >= DISTANCE_THRESHOLD && gate_open) {
        gpioWrite(GATE_GPIO, 0); // Close gate
        gate_open = 0;
        log_event("Gate closed.");
    }
}

// Log Event to File
void log_event(const char *message) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(log_file, "[%d-%02d-%02d %02d:%02d:%02d] %s\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, message);
    fflush(log_file);
}

int main() {
    int distance;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize VL53L1X sensor
    if (init_vl53l1x() != 0) {
        fprintf(stderr, "VL53L1X initialization failed\n");
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO mode for gate actuator
    gpioSetMode(GATE_GPIO, PI_OUTPUT);
    gpioWrite(GATE_GPIO, 0); // Ensure gate is closed at startup

    // Set up signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        if (read_distance(&distance) == 0) {
            char log_message[100];
            snprintf(log_message, sizeof(log_message), "Distance: %d mm (%d cm)", distance, distance / 10);
            log_event(log_message);
            control_gate(distance / 10);
        } else {
            log_event("Error reading distance.");
        }

        gpioDelay(100); // 100 ms delay
    }

    // Cleanup
    log_event("Cleaning up...");
    gpioWrite(GATE_GPIO, 0); // Ensure gate is closed on exit
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

