    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        gpioTerminate();
        return 1;
    }

    // Write header row if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Distance (cm),Servo Angle (degrees)\n");
    }

    // Register alert callback
    gpioSetAlertFuncEx(ECHO_PIN, echo_callback, &pulse_data);

    // Main loop
    while (program_running) {
        float distance = measure_distance();
        float filtered_distance = moving_average(distance);
        float angle = map_distance_to_angle(filtered_distance);
        int pulse_width = map_angle_to_pulse_width(angle);

        if (set_servo_pulse_width(pulse_width) != 0) {
            fprintf(stderr, "Error setting servo pulse width\n");
        }

