// Function to write a byte to a VL53L1X register
int vl53l1x_write_byte(int handle, uint16_t reg, uint8_t data) {
    char buf[3];
    buf[0] = (reg >> 8) & 0xFF; // MSB of register address
    buf[1] = reg & 0xFF;      // LSB of register address
    buf[2] = data;
    int result = i2cWriteDevice(handle, buf, 3);
    if (result != 3) {
        fprintf(stderr, "Error writing to VL53L1X register 0x%04X: %d\n", reg, result);
        return -1;
    }
    return 0;
}

// Function to read a byte from a VL53L1X register
int vl53l1x_read_byte(int handle, uint16_t reg, uint8_t *data) {
    int result = i2cWriteDevice(handle, (char *)&reg, 1);
    if (result != 1) {
        fprintf(stderr, "Error writing register address for read: %d\n", result);
        return -1;
    }
    result = i2cReadDevice(handle, (char *)data, 1);
    if (result != 1) {
        fprintf(stderr, "Error reading from VL53L1X register 0x%04X: %d\n", reg, result);
        return -1;
    }
    return 0;
}

// Function to write a word (2 bytes) to a VL53L1X register
int vl53l1x_write_word(int handle, uint16_t reg, uint16_t data) {
    char buf[3];
    buf[0] = (reg >> 8) & 0xFF; // MSB of register address
    buf[1] = reg & 0xFF;      // LSB of register address
    buf[2] = data & 0xFF;
    int result = i2cWriteDevice(handle, buf, 3);
    if (result != 3) {
        fprintf(stderr, "Error writing to VL53L1X register 0x%04X (LSB): %d\n", reg, result);
        return -1;
    }
    buf[0] = (reg + 1) >> 8; // MSB of register address + 1
    buf[1] = (reg + 1) & 0xFF; // LSB of register address + 1
    buf[2] = (data >> 8) & 0xFF;
    result = i2cWriteDevice(handle, buf, 3);
    if (result != 3) {
        fprintf(stderr, "Error writing to VL53L1X register 0x%04X (MSB): %d\n", reg + 1, result);
        return -1;
    }
    return 0;
}

// Function to read a word (2 bytes) from a VL53L1X register
int vl53l1x_read_word(int handle, uint16_t reg, uint16_t *data) {
    char buf[1];
    buf[0] = reg;
    int result = i2cWriteDevice(handle, buf, 1);
    if (result != 1) {
        fprintf(stderr, "Error writing register address for read: %d\n", result);
        return -1;
    }

    char read_buf[2];
    result = i2cReadDevice(handle, read_buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading from VL53L1X register 0x%04X: %d\n", reg, result);
        return -1;
    }

    *data = (read_buf[1] << 8) | read_buf[0];
    return 0;
