    if (vl53l1x_write_byte(i2c_handle, 0x00, 0x01) != 0) return -1; // Example register write
    if (vl53l1x_write_byte(i2c_handle, 0x01, 0x02) != 0) return -1; // Example register write
    if (vl53l1x_write_byte(i2c_handle, 0x02, 0x03) != 0) return -1; // Example register write

    // Enable signal rate check
    if (vl53l1x_write_byte(i2c_handle, 0x03, 0x04) != 0) return -1; // Example register write

    // Configure cross-talk compensation
    if (vl53l1x_write_byte(i2c_handle, 0x04, 0x05) != 0) return -1; // Example register write

    // Start ranging
    if (vl53l1x_write_byte(i2c_handle, 0x05, 0x06) != 0) return -1; // Example register write

