    uint8_t data[2];
    if (vl53l1x_read_byte(i2c_handle, 0x00, &data[0]) != 0) return -1; // Example register read
    if (vl53l1x_read_byte(i2c_handle, 0x01, &data[1]) != 0) return -1; // Example register read

