int initialize_i2c(int bus, int addr) {
    int handle = i2cOpen(bus, addr, 0);
    if (handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", handle);
        return -1;
    }
    return handle;
}

// Function to configure the Si1102 sensor
int configure_si1102(int handle) {
    // Reset the device
    if (i2cWriteByteData(handle, SI1102_REG_RESET, 0x01) < 0) {
        fprintf(stderr, "Error resetting Si1102\n");
        return -1;
    }
    gpioDelay(10); // Wait for reset to complete

    // Configure measurement rate (example: every 100ms)
    if (i2cWriteByteData(handle, SI1102_REG_MEAS_RATE0, 0x0A) < 0) {
        fprintf(stderr, "Error setting measurement rate 0\n");
        return -1;
    }
    if (i2cWriteByteData(handle, SI1102_REG_MEAS_RATE1, 0x00) < 0) {
        fprintf(stderr, "Error setting measurement rate 1\n");
        return -1;
    }

    // Enable interrupt on proximity rising edge
    if (i2cWriteByteData(handle, SI1102_REG_INT_CFG, 0x01) < 0) {
        fprintf(stderr, "Error setting interrupt config\n");
        return -1;
    }

    return 0;
}

// Function to read the proximity value from the Si1102
int read_proximity(int handle) {
    int high_byte, low_byte;

    high_byte = i2cReadByteData(handle, SI1102_REG_PROX_HIGH);
