#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <math.h>

// Define GPIO pins
#define TRIGGER_PIN 23
#define ECHO_PIN 24
#define SPEAKER_PIN 18

// Define constants
#define SPEED_OF_SOUND 34300.0 // Speed of sound in cm/s
#define MIN_DISTANCE 2.0      // Minimum distance in cm
#define MAX_DISTANCE 200.0    // Maximum distance in cm
#define MIN_FREQUENCY 200.0   // Minimum frequency in Hz
#define MAX_FREQUENCY 2000.0  // Maximum frequency in Hz
#define PWM_RANGE 1000000      // PWM range (microseconds)
#define PWM_DUTY_CYCLE 500000  // 50% duty cycle (microseconds)
#define TRIGGER_PULSE_WIDTH 10 // Trigger pulse width in microseconds
#define TIMEOUT_US 200000       // Timeout in microseconds (200 ms)

// Global variables
volatile sig_atomic_t program_running = 1;
double current_frequency = 0.0; // Store the current frequency

// Function prototypes
void signal_handler(int signal);
double measure_distance();
double map_distance_to_frequency(double distance);
void set_frequency(double frequency);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, stopping PWM and terminating pigpio...\n", signal);
    gpioPWM(SPEAKER_PIN, 0); // Stop PWM output
    gpioTerminate();         // Terminate pigpio
    exit(0);
}

// Function to measure distance using HC-SR04
double measure_distance() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(TRIGGER_PULSE_WIDTH);
    gpioWrite(TRIGGER_PIN, 0);

    uint32_t start_tick = 0, end_tick = 0;
    int start_sec, start_micros, end_sec, end_micros;

    // Wait for echo to go high (with timeout)
    int timeout_counter = 0;
    while (gpioRead(ECHO_PIN) == 0 && timeout_counter < TIMEOUT_US) {
        gpioDelay(1); // Small delay to avoid busy-waiting
        timeout_counter++;
    }

    if (timeout_counter >= TIMEOUT_US) {
        fprintf(stderr, "Error: Echo signal timeout\n");
        return -1.0; // Indicate timeout error
    }

    gpioTime(PI_TIME_RELATIVE, &start_sec, &start_micros);
    start_tick = start_sec * 1000000 + start_micros;

    // Wait for echo to go low (with timeout)
    timeout_counter = 0;
    while (gpioRead(ECHO_PIN) == 1 && timeout_counter < TIMEOUT_US) {
        gpioDelay(1); // Small delay to avoid busy-waiting
        timeout_counter++;
    }

    if (timeout_counter >= TIMEOUT_US) {
        fprintf(stderr, "Error: Echo signal timeout (low)\n");
        return -1.0; // Indicate timeout error
    }

    gpioTime(PI_TIME_RELATIVE, &end_sec, &end_micros);
    end_tick = end_sec * 1000000 + end_micros;

    uint32_t pulse_width = end_tick - start_tick;

    // Calculate distance in centimeters
    double distance = (pulse_width / 1000000.0) * SPEED_OF_SOUND / 2.0;

    return distance;
}

// Function to map distance to frequency
double map_distance_to_frequency(double distance) {
    if (distance < MIN_DISTANCE || distance > MAX_DISTANCE) {
        return current_frequency; // Return the previous frequency if out of range
    }

    // Use the logarithmic formula
    double frequency = MIN_FREQUENCY * exp(distance / 50.0);

    // Clamp the frequency to the defined range
    if (frequency < MIN_FREQUENCY) {
        frequency = MIN_FREQUENCY;
    } else if (frequency > MAX_FREQUENCY) {
        frequency = MAX_FREQUENCY;
    }

    return frequency;
}

// Function to set the PWM frequency
void set_frequency(double frequency) {
    if (frequency <= 0.0) {
        fprintf(stderr, "Error: Invalid frequency: %f\n", frequency);
        return;
    }

    // Calculate the period in microseconds
    double period = 1000000.0 / frequency;

    // Calculate the duty cycle in microseconds (50%)
    double duty_cycle = period / 2.0;

    // Set the PWM frequency and duty cycle
    gpioSetPWMfrequency(SPEAKER_PIN, (int)frequency);
    gpioSetPWMrange(SPEAKER_PIN, (int)period);
    gpioPWM(SPEAKER_PIN, (int)duty_cycle);

    current_frequency = frequency; // Update the current frequency
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(SPEAKER_PIN, PI_OUTPUT);

    // Set PWM range and duty cycle
    gpioSetPWMrange(SPEAKER_PIN, PWM_RANGE);
    gpioSetPWMfrequency(SPEAKER_PIN, 0); // Initially set to 0 Hz
    gpioPWM(SPEAKER_PIN, PWM_DUTY_CYCLE); // Set initial duty cycle

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Theremin instrument started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        double distance = measure_distance();

        if (distance > 0) {
            double frequency = map_distance_to_frequency(distance);
            set_frequency(frequency);
            printf("Distance: %.2f cm, Frequency: %.2f Hz\n", distance, frequency);
        } else {
            // Handle error or timeout
            printf("Error: Distance measurement failed. Using previous frequency.\n");
        }

        gpioDelay(50); // Delay for 50 ms
    }

    // Cleanup (should not reach here if signal handler works correctly)
    gpioPWM(SPEAKER_PIN, 0); // Stop PWM output
    gpioTerminate();         // Terminate pigpio

    return 0;
}

