    start_tick = gpioTick();

    // Wait for echo to go low, with timeout
    timeout_counter = 0;
    while (gpioRead(ECHO_PIN) == 1 && timeout_counter < TIMEOUT_US) {
        timeout_counter++;
        gpioDelay(1); // Small delay to prevent busy-waiting
    }

    if (timeout_counter >= TIMEOUT_US) {
        fprintf(stderr, "Timeout waiting for echo low\n");
        return -1.0; // Indicate timeout error
    }

    end_tick = gpioTick();

    // Calculate pulse width in microseconds
    uint32_t pulse_width = end_tick - start_tick;

    // Calculate distance in centimeters
    float distance = (float)pulse_width / 2.0 / SPEED_OF_SOUND;

    return distance;
}

