#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Define constants
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define CS_PIN 8          // GPIO8 (CE0)
#define DISTANCE_REG_LOW 0x0C
#define DISTANCE_REG_HIGH 0x0D
#define INIT_REG_1 0x01
#define INIT_REG_2 0x02
#define INIT_REG_TRIGGER 0x00

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_sensor();
int read_distance(int *distance);
void log_distance(int distance);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating...\n", signal);
}

// Function to initialize the sensor
int initialize_sensor() {
    char tx_buf[2], rx_buf[2];

    // Trigger measurement
    tx_buf[0] = INIT_REG_TRIGGER;
    tx_buf[1] = 0x01;
    if (spiXfer(spi_handle, tx_buf, rx_buf, 2) != 0) {
        fprintf(stderr, "Error: Failed to trigger measurement.\n");
        return -1;
    }

    // Set continuous measurement mode
    tx_buf[0] = INIT_REG_1;
    tx_buf[1] = 0x01;
    if (spiXfer(spi_handle, tx_buf, rx_buf, 2) != 0) {
        fprintf(stderr, "Error: Failed to set continuous measurement mode.\n");
        return -1;
    }

    // Set range to 5m
    tx_buf[0] = INIT_REG_2;
    tx_buf[1] = 0x00;
    if (spiXfer(spi_handle, tx_buf, rx_buf, 2) != 0) {
        fprintf(stderr, "Error: Failed to set range to 5m.\n");
        return -1;
    }

    return 0;
}

// Function to read the distance from the sensor
int read_distance(int *distance) {
    char tx_buf[1], rx_buf[2];

    // Read low byte
    tx_buf[0] = DISTANCE_REG_LOW;
    if (spiXfer(spi_handle, tx_buf, rx_buf, 1) != 0) {
        fprintf(stderr, "Error: Failed to read low byte.\n");
        return -1;
    }

    // Read high byte
    tx_buf[0] = DISTANCE_REG_HIGH;
    if (spiXfer(spi_handle, tx_buf, rx_buf, 1) != 0) {
        fprintf(stderr, "Error: Failed to read high byte.\n");
        return -1;
    }

    // Combine the two bytes to get the distance
    *distance = (rx_buf[1] << 8) | rx_buf[0];

    return 0;
}

// Function to log the distance to a file
void log_distance(int distance) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, %d\n", timestamp, distance);
    fflush(log_file); // Ensure data is written to disk immediately
}

int main() {
    int distance;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed.\n");
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("distance_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file.\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize the sensor
    if (initialize_sensor() != 0) {
        fprintf(stderr, "Error: Sensor initialization failed.\n");
        fclose(log_file);
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        // Read distance
        if (read_distance(&distance) == 0) {
            // Log distance
            log_distance(distance);

            // Check for sensor-absent condition
            if (distance < 200 || distance > 5000) {
                fprintf(stderr, "Warning: Sensor-absent condition detected (distance = %d mm).\n", distance);
            }
        } else {
            fprintf(stderr, "Error: Failed to read distance.\n");
        }

        // Delay
        gpioDelay(100); // 100 ms
    }

    // Cleanup
    fclose(log_file);
    spiClose(spi_handle);
    gpioTerminate();

    return 0;
}

