#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define SI1120_ADDR 0x60
#define RESET_REG 0x30
#define PART_ID_REG 0x00
#define ALS_REG_L 0x22
#define ALS_REG_H 0x23
#define PS1_REG_L 0x18
#define PS1_REG_H 0x19
#define SAMPLE_INTERVAL_MS 500
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 10

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_sensor();
int read_als_data(uint16_t *als_data);
int read_proximity_data(uint16_t *proximity_data);
char *format_timestamp();
int log_data(const char *timestamp, uint16_t als_data, uint16_t proximity_data);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating...\n", signal);
}

// Initializes the Si1120 sensor
int initialize_sensor() {
    int retries = 0;
    int result;

    while (retries < MAX_RETRIES) {
        result = i2cWriteByteData(i2c_handle, RESET_REG, 0x01);
        if (result == 0) {
            gpioDelay(10); // Delay after reset
            break;
        } else {
            fprintf(stderr, "Error resetting sensor (attempt %d): %d\n", retries + 1, result);
            retries++;
            gpioDelay(RETRY_DELAY_MS);
        }
    }

    if (retries == MAX_RETRIES) {
        fprintf(stderr, "Failed to reset sensor after %d retries.\n", MAX_RETRIES);
        return -1;
    }

    retries = 0;
    while (retries < MAX_RETRIES) {
        int part_id = i2cReadByteData(i2c_handle, PART_ID_REG);
        if (part_id >= 0 && part_id == 0x41) {
            break;
        } else {
            fprintf(stderr, "Error reading part ID (attempt %d): %d\n", retries + 1, part_id);
            retries++;
            gpioDelay(RETRY_DELAY_MS);
        }
    }

    if (retries == MAX_RETRIES) {
        fprintf(stderr, "Failed to verify part ID after %d retries.\n", MAX_RETRIES);
        return -1;
    }

    return 0;
}

// Reads ALS data from the sensor
int read_als_data(uint16_t *als_data) {
    int retries = 0;
    int result;
    uint8_t als_l, als_h;

    while (retries < MAX_RETRIES) {
        als_l = i2cReadByteData(i2c_handle, ALS_REG_L);
        if (als_l >= 0) {
            als_h = i2cReadByteData(i2c_handle, ALS_REG_H);
            if (als_h >= 0) {
                *als_data = (uint16_t)((als_h << 8) | als_l);
                return 0;
            } else {
                fprintf(stderr, "Error reading ALS high byte (attempt %d): %d\n", retries + 1, als_h);
            }
        } else {
            fprintf(stderr, "Error reading ALS low byte (attempt %d): %d\n", retries + 1, als_l);
        }
        retries++;
        gpioDelay(RETRY_DELAY_MS);
    }

    fprintf(stderr, "Failed to read ALS data after %d retries.\n", MAX_RETRIES);
    return -1;
}

// Reads proximity data from the sensor
int read_proximity_data(uint16_t *proximity_data) {
    int retries = 0;
    int result;
    uint8_t ps1_l, ps1_h;

    while (retries < MAX_RETRIES) {
        ps1_l = i2cReadByteData(i2c_handle, PS1_REG_L);
        if (ps1_l >= 0) {
            ps1_h = i2cReadByteData(i2c_handle, PS1_REG_H);
            if (ps1_h >= 0) {
                *proximity_data = (uint16_t)((ps1_h << 8) | ps1_l);
                return 0;
            } else {
                fprintf(stderr, "Error reading proximity high byte (attempt %d): %d\n", retries + 1, ps1_h);
            }
        } else {
            fprintf(stderr, "Error reading proximity low byte (attempt %d): %d\n", retries + 1, ps1_l);
        }
        retries++;
        gpioDelay(RETRY_DELAY_MS);
    }

    fprintf(stderr, "Failed to read proximity data after %d retries.\n", MAX_RETRIES);
    return -1;
}

// Formats the current timestamp as YYYY-MM-DD HH:MM:SS
char *format_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    static char buffer[20]; // Static buffer to hold the timestamp

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", timeinfo);
    return buffer;
}

// Logs the data to the file
int log_data(const char *timestamp, uint16_t als_data, uint16_t proximity_data) {
    if (log_file == NULL) {
        fprintf(stderr, "Error: Log file is not open.\n");
        return -1;
    }

    fprintf(log_file, "%s, %u, %u\n", timestamp, als_data, proximity_data);
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, SI1120_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("si1120_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize the sensor
    if (initialize_sensor() != 0) {
        fprintf(stderr, "Sensor initialization failed.\n");
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    uint16_t als_data, proximity_data;
    char *timestamp;

    while (!terminate) {
        // Read sensor data
        if (read_als_data(&als_data) == 0 && read_proximity_data(&proximity_data) == 0) {
            // Format timestamp
            timestamp = format_timestamp();

            // Log data
            if (log_data(timestamp, als_data, proximity_data) != 0) {
                fprintf(stderr, "Error logging data.\n");
            }
        } else {
            fprintf(stderr, "Error reading sensor data.\n");
        }

        // Wait for the next sample
        gpioDelay(SAMPLE_INTERVAL_MS);
    }

    // Cleanup
    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

