FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_sensor();
int read_proximity();
void log_data(int proximity_value);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to initialize the Si1145 sensor
int initialize_sensor() {
    int retries = 3;
    int status;

    while (retries > 0) {
        status = i2cWriteByteData(i2c_handle, REG_HW_KEY, 0x03);
        if (status != 0) {
            fprintf(stderr, "Error writing to HW_KEY register: %d\n", status);
            gpioDelay(100000); // 100ms delay
            retries--;
            continue;
        }

        status = i2cWriteByteData(i2c_handle, REG_MEAS_RATE, 0x02);
        if (status != 0) {
            fprintf(stderr, "Error writing to MEAS_RATE register: %d\n", status);
            gpioDelay(100000); // 100ms delay
            retries--;
            continue;
        }

        status = i2cWriteByteData(i2c_handle, REG_INT_CFG, 0x00);
        if (status != 0) {
            fprintf(stderr, "Error writing to INT_CFG register: %d\n", status);
            gpioDelay(100000); // 100ms delay
            retries--;
            continue;
        }

        status = i2cWriteByteData(i2c_handle, REG_ALS_VIS_IR_ADC_COUNTER, 0x0B);
        if (status != 0) {
            fprintf(stderr, "Error writing to ALS_VIS_IR_ADC_COUNTER register: %d\n", status);
            gpioDelay(100000); // 100ms delay
            retries--;
            continue;
        }

        status = i2cWriteByteData(i2c_handle, REG_ALS_VIS_ADC_GAIN, 0x00);
        if (status != 0) {
            fprintf(stderr, "Error writing to ALS_VIS_ADC_GAIN register: %d\n", status);
            gpioDelay(100000); // 100ms delay
            retries--;
            continue;
        }

        status = i2cWriteByteData(i2c_handle, REG_PS_ADC_COUNTER, 0x49);
        if (status != 0) {
            fprintf(stderr, "Error writing to PS_ADC_COUNTER register: %d\n", status);
            gpioDelay(100000); // 100ms delay
            retries--;
            continue;
        }

        status = i2cWriteByteData(i2c_handle, REG_PS_LED21, 0x03);
        if (status != 0) {
            fprintf(stderr, "Error writing to PS_LED21 register: %d\n", status);
            gpioDelay(100000); // 100ms delay
            retries--;
            continue;
        }

        status = i2cWriteByteData(i2c_handle, REG_PS_LED3, 0x0F);
        if (status != 0) {
            fprintf(stderr, "Error writing to PS_LED3 register: %d\n", status);
            gpioDelay(100000); // 100ms delay
            retries--;
            continue;
        }

        status = i2cWriteByteData(i2c_handle, REG_PS_ADC_MISC, 0x03);
        if (status != 0) {
            fprintf(stderr, "Error writing to PS_ADC_MISC register: %d\n", status);
            gpioDelay(100000); // 100ms delay
            retries--;
            continue;
        }

        status = i2cWriteByteData(i2c_handle, REG_PS_ADC_GAIN, 0x07);
        if (status != 0) {
            fprintf(stderr, "Error writing to PS_ADC_GAIN register: %d\n", status);
            gpioDelay(100000); // 100ms delay
            retries--;
            continue;
        }

        status = i2cWriteByteData(i2c_handle, REG_COMMAND, 0x03);
        if (status != 0) {
            fprintf(stderr, "Error writing to COMMAND register: %d\n", status);
            gpioDelay(100000); // 100ms delay
            retries--;
            continue;
        }

        return 0; // Initialization successful
    }

    fprintf(stderr, "Failed to initialize sensor after multiple retries.\n");
    return -1; // Initialization failed
}

// Function to read proximity data from the Si1145 sensor
int read_proximity() {
    int low_byte, high_byte, proximity_value;
    int retries = 3;
    int status;

    while (retries > 0) {
        low_byte = i2cReadByteData(i2c_handle, REG_PS1_DATA0);
        if (low_byte < 0) {
            fprintf(stderr, "Error reading PS1_DATA0 register: %d\n", low_byte);
            gpioDelay(100000); // 100ms delay
            retries--;
            continue;
        }

        high_byte = i2cReadByteData(i2c_handle, REG_PS1_DATA1);
        if (high_byte < 0) {
            fprintf(stderr, "Error reading PS1_DATA1 register: %d\n", high_byte);
            gpioDelay(100000); // 100ms delay
            retries--;
            continue;
        }

        proximity_value = (high_byte << 8) | low_byte;
        return proximity_value;
    }

    fprintf(stderr, "Failed to read proximity data after multiple retries.\n");
    return -1; // Indicate error
}

// Function to log the proximity data to a file
void log_data(int proximity_value) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, %d\n", timestamp, proximity_value);
    fflush(log_file); // Ensure data is written to disk immediately
}

