#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins
#define TRIGGER_PIN 4
#define ECHO_PIN 17
#define SERVO_PIN 18

// Define constants
#define SPEED_OF_SOUND 34300.0 // Speed of sound in cm/s
#define TIMEOUT_US 50000       // Timeout for echo pulse in microseconds
#define MIN_DISTANCE 20.0      // Minimum distance in cm
#define MAX_DISTANCE 200.0     // Maximum distance in cm
#define MIN_PULSE_WIDTH 500    // Minimum pulse width for servo in microseconds
#define MAX_PULSE_WIDTH 2500   // Maximum pulse width for servo in microseconds

// Global variable for graceful shutdown
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to measure distance using the HC-SR04 sensor
float measure_distance() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10 us trigger pulse
    gpioWrite(TRIGGER_PIN, 0);

    uint32_t start_tick = 0;
    uint32_t end_tick = 0;

    // Wait for echo to go high (with timeout)
    int count = 0;
    while (gpioRead(ECHO_PIN) == 0 && count < TIMEOUT_US) {
        count++;
        gpioDelay(1); // Delay 1 us
    }

    if (count >= TIMEOUT_US) {
        fprintf(stderr, "Error: Echo pulse timeout\n");
        return -1.0; // Indicate error
    }

    start_tick = gpioTick();

    // Wait for echo to go low (with timeout)
    count = 0;
    while (gpioRead(ECHO_PIN) == 1 && count < TIMEOUT_US) {
        count++;
        gpioDelay(1); // Delay 1 us
    }

    if (count >= TIMEOUT_US) {
        fprintf(stderr, "Error: Echo pulse timeout (low)\n");
        return -1.0; // Indicate error
    }

    end_tick = gpioTick();

    // Calculate pulse duration in microseconds
    uint32_t pulse_duration = end_tick - start_tick;

    // Calculate distance in centimeters
    float distance = (pulse_duration * SPEED_OF_SOUND) / 2000000.0; // Divide by 2 for one-way distance

    return distance;
}

// Function to set the servo angle based on distance
void set_servo_angle(float distance) {
    // Map distance to pulse width
    float pulse_width = MIN_PULSE_WIDTH + (distance / (MAX_DISTANCE - MIN_DISTANCE)) * (MAX_PULSE_WIDTH - MIN_PULSE_WIDTH);

    // Set servo pulse width
    gpioServo(SERVO_PIN, (int)pulse_width);
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(SERVO_PIN, PI_OUTPUT);

    // Register signal handler for graceful shutdown
    signal(SIGINT, signal_handler);

    printf("Parking Assist System running. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        // Measure distance
        float distance = measure_distance();

        // Check for errors
        if (distance < 0) {
            fprintf(stderr, "Error: Distance measurement failed\n");
        } else {
            // Set servo angle
            set_servo_angle(distance);

            // Display distance
            printf("Distance: %.2f cm\n", distance);
        }

        // Delay for 100 ms
        gpioDelay(100000); // 100 ms = 100000 us
    }

    // Cleanup before exiting
    gpioServo(SERVO_PIN, 0); // Stop the servo
    gpioTerminate();         // Terminate pigpio

    printf("Exiting.\n");
    return 0;
}

