#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Constants
#define I2C_BUS 1
#define VL53L1X_ADDR 0x29
#define SERVO_GPIO 18
#define OPEN_PWM 2000
#define CLOSED_PWM 1000
#define OPEN_THRESHOLD 200
#define CLOSE_THRESHOLD 250
#define HYSTERESIS 50
#define LOG_FILE "gate_log.txt"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_vl53l1x();
int read_distance();
void control_servo(int pulse_width);
void log_event(const char *event);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize VL53L1X sensor
int init_vl53l1x() {
    int status;

    // Check sensor ID
    status = i2cWriteByteData(i2c_handle, 0x00, 0x00); // Required before reading
    if (status < 0) {
        fprintf(stderr, "Error writing to I2C device: %d\n", status);
        return -1;
    }
    gpioDelay(1000); // Delay 1ms
    uint8_t sensor_id = i2cReadByteData(i2c_handle, 0x010F);
    if (sensor_id != 0xEA) {
        fprintf(stderr, "Error: Invalid sensor ID: 0x%02X\n", sensor_id);
        return -1;
    }

    // Set timing budget (example value)
    status = i2cWriteByteData(i2c_handle, 0x001E, 0x00); // Ranging Mode
    if (status < 0) {
        fprintf(stderr, "Error writing to I2C device: %d\n", status);
        return -1;
    }
    status = i2cWriteByteData(i2c_handle, 0x001F, 0x00); // Timing Budget
    if (status < 0) {
        fprintf(stderr, "Error writing to I2C device: %d\n", status);
        return -1;
    }

    // Start ranging
    status = i2cWriteByteData(i2c_handle, 0x0000, 0x01); // Start ranging
    if (status < 0) {
        fprintf(stderr, "Error writing to I2C device: %d\n", status);
        return -1;
    }

    return 0;
}

// Read distance from VL53L1X sensor
int read_distance() {
    int status;
    uint8_t data[2];

    // Read distance (2 bytes)
    status = i2cReadI2CBlockData(i2c_handle, 0x0014, (char *)data, 2);
    if (status < 0) {
        fprintf(stderr, "Error reading from I2C device: %d\n", status);
        return -1;
    }

    return (data[0] << 8) | data[1];
}

// Control servo motor
void control_servo(int pulse_width) {
    gpioServo(SERVO_GPIO, pulse_width);
}

// Log events to file
void log_event(const char *event) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(log_file, "[%d-%02d-%02d %02d:%02d:%02d] %s\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, event);
    fflush(log_file);
}

int main() {
    int distance;
    int current_pulse_width = CLOSED_PWM;
    int open = 0;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize VL53L1X sensor
    if (init_vl53l1x() != 0) {
        fprintf(stderr, "VL53L1X initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set signal handler for graceful shutdown
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        distance = read_distance();
        if (distance < 0) {
            fprintf(stderr, "Error reading distance, retrying...\n");
            gpioDelay(100); // Small delay before retrying
            continue;
        }

        if (distance < OPEN_THRESHOLD && !open) {
            current_pulse_width = CLOSED_PWM;
            for (int i = CLOSED_PWM; i <= OPEN_PWM; i += 10) {
                control_servo(i);
                gpioDelay(10);
            }
            control_servo(OPEN_PWM);
            log_event("Gate opened");
            open = 1;
        } else if (distance > CLOSE_THRESHOLD && open) {
            current_pulse_width = OPEN_PWM;
            for (int i = OPEN_PWM; i >= CLOSED_PWM; i -= 10) {
                control_servo(i);
                gpioDelay(10);
            }
            control_servo(CLOSED_PWM);
            log_event("Gate closed");
            open = 0;
        }

        gpioDelay(50); // Delay between readings
    }

    // Cleanup
    control_servo(CLOSED_PWM); // Ensure gate is closed on exit
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

