#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define SI7005_ADDR 0x40
#define CONFIG_REG 0x03
#define TEMP_REG 0x01
#define HUMID_REG 0x02
#define SLEEP_TIME 2 // seconds

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_pigpio();
int open_i2c_bus(int bus, int addr);
int write_register(int handle, int reg, int value);
int read_register(int handle, int reg);
float convert_temperature(int raw_temp);
float convert_humidity(int raw_humidity);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize pigpio library
int init_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Open I2C bus
int open_i2c_bus(int bus, int addr) {
    int handle = i2cOpen(bus, addr, 0);
    if (handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d at address 0x%02x: %d\n", bus, addr, handle);
        return -1;
    }
    return handle;
}

// Write to a register
int write_register(int handle, int reg, int value) {
    int result = i2cWriteByteData(handle, reg, value);
    if (result < 0) {
        fprintf(stderr, "Failed to write to register 0x%02x: %d\n", reg, result);
        return -1;
    }
    return 0;
}

// Read from a register
int read_register(int handle, int reg) {
    int result = i2cReadByteData(handle, reg);
    if (result < 0) {
        fprintf(stderr, "Failed to read from register 0x%02x: %d\n", reg, result);
        return -1;
    }
    return result;
}

// Convert raw temperature to Celsius
float convert_temperature(int raw_temp) {
    return (175.72 * raw_temp) / 65536.0 - 46.85;
}

// Convert raw humidity to percentage
float convert_humidity(int raw_humidity) {
    return (125.0 * raw_humidity) / 65536.0 - 6.0;
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize pigpio
    if (init_pigpio() != 0) {
        return 1;
    }

    // Open I2C bus
    i2c_handle = open_i2c_bus(I2C_BUS, SI7005_ADDR);
    if (i2c_handle < 0) {
        gpioTerminate();
        return 1;
    }

    // Configure Si7005 (internal temperature sensor, heater off)
    if (write_register(i2c_handle, CONFIG_REG, 0x00) != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    gpioDelay(10); // Wait 10 ms

    // Main loop
    while (!terminate) {
        // Read temperature
        int raw_temp = read_register(i2c_handle, TEMP_REG);
        if (raw_temp < 0) {
            i2cClose(i2c_handle);
            i2c_handle = open_i2c_bus(I2C_BUS, SI7005_ADDR);
            if (i2c_handle < 0) {
                gpioTerminate();
                return 1;
            }
            if (write_register(i2c_handle, CONFIG_REG, 0x00) != 0) {
                i2cClose(i2c_handle);
                gpioTerminate();
                return 1;
            }
            gpioDelay(10);
            continue; // Skip to the next iteration
        }

        // Read humidity
        int raw_humidity = read_register(i2c_handle, HUMID_REG);
        if (raw_humidity < 0) {
            i2cClose(i2c_handle);
            i2c_handle = open_i2c_bus(I2C_BUS, SI7005_ADDR);
            if (i2c_handle < 0) {
                gpioTerminate();
                return 1;
            }
            if (write_register(i2c_handle, CONFIG_REG, 0x00) != 0) {
                i2cClose(i2c_handle);
                gpioTerminate();
                return 1;
            }
            gpioDelay(10);
            continue; // Skip to the next iteration
        }

        // Convert readings
        float temperature = convert_temperature(raw_temp);
        float humidity = convert_humidity(raw_humidity);

        // Print results
        printf("Temperature: %.2f C, Humidity: %.2f %%\n", temperature, humidity);

        // Sleep for 2 seconds
        sleep(SLEEP_TIME);
    }

    // Close I2C bus and terminate pigpio
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

