volatile sig_atomic_t terminate = 0;
int i2c_handle;

void signal_handler(int sig) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating gracefully...\n", sig);
}

// CRC-8 calculation function
unsigned char crc8(const unsigned char *data, int len) {
    unsigned char crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Function to read temperature and humidity from SHT40
int read_sht40(float *temperature, float *humidity) {
    unsigned char cmd = 0xFD; // High repeatability measurement command
    unsigned char data[6];
    int result;

    result = i2cWriteByte(i2c_handle, cmd);
    if (result != 0) {
        fprintf(stderr, "Error writing to I2C device: %d\n", result);
        return -1;
    }

    gpioDelay(10); // Wait at least 10 ms

    result = i2cReadDevice(i2c_handle, (char *)data, 6);
    if (result != 6) {
        fprintf(stderr, "Error reading from I2C device: %d\n", result);
        return -1;
    }

    // CRC validation
    if (crc8(data, 2) != data[2] || crc8(data + 3, 2) != data[5]) {
        fprintf(stderr, "CRC validation failed\n");
        return -1;
    }

    // Convert raw data to temperature and humidity
    unsigned short raw_temperature = (data[0] << 8) | data[1];
    unsigned short raw_humidity = (data[3] << 8) | data[4];

    *temperature = -45.0 + 175.0 * raw_temperature / 65535.0;
    *humidity = -6.0 + 125.0 * raw_humidity / 65535.0;

    // Clamp humidity to 0-100%
    if (*humidity < 0.0) *humidity = 0.0;
    if (*humidity > 100.0) *humidity = 100.0;

    return 0;
}

