#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Define constants
#define I2C_BUS 1
#define MLX90614_ADDR 0x5A
#define AMBIENT_TEMP_REG 0x06
#define OBJECT_TEMP_REG 0x07
#define LOG_FILE "temperature_log.csv"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold temperature data
typedef struct {
    float ambient_temp;
    float object_temp;
} TemperatureData;

// Function prototypes
int initialize_i2c();
TemperatureData read_temperatures();
void log_temperature(TemperatureData data);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// I2C initialization function
int initialize_i2c() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(I2C_BUS, MLX90614_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Function to read temperatures from the sensor
TemperatureData read_temperatures() {
    TemperatureData data;
    int raw_ambient, raw_object;

    // Read ambient temperature
    raw_ambient = i2cReadWordData(i2c_handle, AMBIENT_TEMP_REG);
    if (raw_ambient < 0) {
        fprintf(stderr, "Error reading ambient temperature: %d\n", raw_ambient);
        data.ambient_temp = -999.0; // Indicate error
    } else {
        data.ambient_temp = (float)raw_ambient * 0.02 - 273.15;
    }

    // Read object temperature
    raw_object = i2cReadWordData(i2c_handle, OBJECT_TEMP_REG);
    if (raw_object < 0) {
        fprintf(stderr, "Error reading object temperature: %d\n", raw_object);
        data.object_temp = -999.0; // Indicate error
    } else {
        data.object_temp = (float)raw_object * 0.02 - 273.15;
    }

    return data;
}

// Function to log temperature data to a file
void log_temperature(TemperatureData data) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp) - 1, "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, data.ambient_temp, data.object_temp);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Cleanup function to release resources
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Register signal handler for graceful shutdown
    signal(SIGINT, signal_handler);

    // Initialize I2C
    if (initialize_i2c() != 0) {
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup();
        return 1;
    }

    // Main loop
    while (!terminate) {
        TemperatureData data = read_temperatures();

        if (data.ambient_temp != -999.0 && data.object_temp != -999.0) {
            log_temperature(data);
        } else {
            fprintf(stderr, "Error reading temperatures, skipping log.\n");
        }

        gpioSleep(PI_TIME_RELATIVE, 5, 0); // Sleep for 5 seconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

