    buf[0] = (MEASURE_CMD >> 8) & 0xFF;
    buf[1] = MEASURE_CMD & 0xFF;
    result = i2cWriteDevice(i2c_handle, buf, 2);
    if (result != 0) {
        log_error("Failed to write measurement command.");
        return -1;
    }

    // Wait for measurement to complete (at least 20ms)
    gpioDelay(20000); // 20ms

    // Read temperature data
    result = i2cReadDevice(i2c_handle, data, 2);
    if (result != 2) {
        log_error("Failed to read temperature data.");
        return -1;
    }

    // Convert raw data to temperature (Celsius)
