    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file.\n");
        gpioTerminate();
        return 1;
    }

    error_file = fopen(ERROR_LOG, "a");
    if (error_file == NULL) {
        fprintf(stderr, "Failed to open error log file.\n");
        fclose(log_file);
        gpioTerminate();
        return 1;
