#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// SHT40 I2C address
#define SHT40_ADDR 0x44

// Measurement command (high repeatability)
#define MEASURE_CMD 0xFD

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float temperature;
    float humidity;
} sensor_data_t;

// CRC-8 calculation function
uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Function to read data from SHT40 sensor
int read_sht40(sensor_data_t *data) {
    uint8_t cmd = MEASURE_CMD;
    uint8_t raw_data[6];
    int result;

    // Send measurement command
    result = i2cWriteDevice(i2c_handle, &cmd, 1);
    if (result != 0) {
        fprintf(log_file, "%s", "Error: Failed to write measurement command.\n");
        fflush(log_file);
        return -1;
    }

    // Wait for measurement (at least 10 ms)
    gpioDelay(10000); // 10 ms

    // Read 6 bytes of data
    result = i2cReadDevice(i2c_handle, (char *)raw_data, 6);
    if (result != 6) {
        fprintf(log_file, "%s", "Error: Failed to read sensor data.\n");
        fflush(log_file);
        return -1;
    }

    // Validate CRC for temperature
    if (crc8(raw_data, 2) != raw_data[2]) {
        fprintf(log_file, "%s", "Error: Temperature CRC check failed.\n");
        fflush(log_file);
        return -1;
    }

    // Validate CRC for humidity
    if (crc8(raw_data + 3, 2) != raw_data[5]) {
        fprintf(log_file, "%s", "Error: Humidity CRC check failed.\n");
        fflush(log_file);
        return -1;
    }

    // Convert raw data to temperature and humidity
    uint16_t raw_temperature = (raw_data[0] << 8) | raw_data[1];
    uint16_t raw_humidity = (raw_data[3] << 8) | raw_data[4];

    data->temperature = -45.0 + 175.0 * raw_temperature / 65535.0;
    data->humidity = 100.0 * raw_humidity / 65535.0;

    return 0;
}

// Function to log data to file
void log_data(sensor_data_t data) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s, Temperature: %.2f C, Humidity: %.2f %%\n", timestamp, data.temperature, data.humidity);
    fflush(log_file);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(log_file, "%s", "Received signal, closing down...\n");
    fflush(log_file);
    terminate = 1;
}

int main() {
    sensor_data_t sensor_data;
    int result;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, SHT40_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("sht40_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        result = read_sht40(&sensor_data);
        if (result == 0) {
            log_data(sensor_data);
        } else {
            fprintf(log_file, "%s", "Error: Failed to read sensor data.\n");
            fflush(log_file);
        }

        gpioDelay(5000000); // 5 seconds
    }

    // Cleanup
    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

