#include <signal.h>
#include <errno.h>
#include <string.h>

// Constants
#define I2C_BUS 1
#define SI7015_ADDR 0x40
#define TEMP_CMD 0xF3
#define HUMID_CMD 0xF5
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 10
#define SAMPLE_INTERVAL_S 5

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_pigpio();
int init_i2c();
int read_sensor_data(int *raw_temp, int *raw_humidity);
float convert_temperature(int raw_temp);
float convert_humidity(int raw_humidity);
void log_data(float temperature, float humidity);
void print_data(float temperature, float humidity);
void signal_handler(int signal);
const char *pigpio_error(int error_code);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize pigpio library
int init_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SI7015_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %s\n", pigpio_error(i2c_handle));
        return -1;
    }
    return 0;
}

// Read raw temperature and humidity data from the sensor
int read_sensor_data(int *raw_temp, int *raw_humidity) {
    char buf[2];
    int retries = 0;

    // Read temperature
    while (retries < MAX_RETRIES) {
        if (i2cWriteByte(i2c_handle, TEMP_CMD) < 0) {
            fprintf(stderr, "Failed to write temperature command: %s\n", pigpio_error(i2c_handle));
            retries++;
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
            continue;
        }

        gpioDelay(20000); // Wait for measurement (20ms)

        if (i2cReadDevice(i2c_handle, buf, 2) == 2) {
            *raw_temp = (buf[0] << 8) | buf[1];
            break; // Success, exit retry loop
        } else {
            fprintf(stderr, "Failed to read temperature data: %s\n", pigpio_error(i2c_handle));
            retries++;
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
        }
    }

    if (retries == MAX_RETRIES) {
        fprintf(stderr, "Failed to read temperature after %d retries\n", MAX_RETRIES);
        return -1;
    }

    retries = 0;
    // Read humidity
    while (retries < MAX_RETRIES) {
        if (i2cWriteByte(i2c_handle, HUMID_CMD) < 0) {
            fprintf(stderr, "Failed to write humidity command: %s\n", pigpio_error(i2c_handle));
            retries++;
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
            continue;
        }

        gpioDelay(20000); // Wait for measurement (20ms)

        if (i2cReadDevice(i2c_handle, buf, 2) == 2) {
            *raw_humidity = (buf[0] << 8) | buf[1];
            break; // Success, exit retry loop
        } else {
            fprintf(stderr, "Failed to read humidity data: %s\n", pigpio_error(i2c_handle));
            retries++;
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
        }
    }

    if (retries == MAX_RETRIES) {
        fprintf(stderr, "Failed to read humidity after %d retries\n", MAX_RETRIES);
        return -1;
    }

    return 0;
}

// Convert raw temperature to Celsius
float convert_temperature(int raw_temp) {
    return (175.72 * raw_temp / 65536.0) - 46.85;
}

// Convert raw humidity to percentage relative humidity
float convert_humidity(int raw_humidity) {
    float humidity = (125.0 * raw_humidity / 65536.0) - 6.0;
    if (humidity < 0.0) humidity = 0.0;
    if (humidity > 100.0) humidity = 100.0;
    return humidity;
}

// Log data to file
void log_data(float temperature, float humidity) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s, Temperature: %.2f C, Humidity: %.2f %%RH\n", timestamp, temperature, humidity);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Print data to console
void print_data(float temperature, float humidity) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    printf("%s, Temperature: %.2f C, Humidity: %.2f %%RH\n", timestamp, temperature, humidity);
