        return -1;
    }

    gpioDelay(10000); // Wait 10 ms

    if (i2cReadDevice(i2c_handle, (char *)data, 6) != 6) {
        fprintf(stderr, "Failed to read data from sensor\n");
        return -1;
    }

    return 0;
}

