    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    uint8_t data[6];
    SensorData sensor_data;

    printf("Starting sensor readings... Press Ctrl+C to exit.\n");

    while (!terminate) {
        // Read sensor data
        if (read_sht40(data) == 0) {
            // Validate CRC for temperature
            if (!validate_crc(data, 2, data[2])) {
                fprintf(stderr, "Temperature CRC check failed\n");
            } else {
                // Validate CRC for humidity
                if (!validate_crc(data + 3, 2, data[5])) {
                    fprintf(stderr, "Humidity CRC check failed\n");
                } else {
                    // Convert data
                    sensor_data = convert_data(data);

                    // Log data
                    if (log_data(sensor_data) != 0) {
                        fprintf(stderr, "Failed to log data\n");
                    }
                }
            }
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }

        gpioSleep(PI_TIME_RELATIVE, SLEEP_DURATION, 0); // Sleep for 5 seconds
    }

    // Cleanup
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

