#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Constants
#define I2C_BUS 1
#define SI7021_ADDR 0x40
#define FAN_GPIO 18
#define TEMP_THRESHOLD_HIGH 28.0
#define TEMP_THRESHOLD_LOW 27.0
#define CIRCULAR_BUFFER_SIZE 60
#define I2C_RETRY_COUNT 3

// Data structure for sensor readings
typedef struct {
    time_t timestamp;
    float temperature;
    float humidity;
} SensorData;

// Circular buffer
SensorData circular_buffer[CIRCULAR_BUFFER_SIZE];
int buffer_index = 0;

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int read_sensor_data(float *temperature, float *humidity);
void control_fan(float temperature);
void log_data(float temperature, float humidity);
void print_buffer();
void signal_handler(int signal);

// Function to initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SI7021_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to read sensor data
int read_sensor_data(float *temperature, float *humidity) {
    char buf[2];
    int raw_temp, raw_humidity;
    int retries = I2C_RETRY_COUNT;

    // Read temperature
    while (retries > 0) {
        if (i2cWriteByte(i2c_handle, 0xE3) != 0) {
            fprintf(stderr, "Error writing temperature command\n");
            gpioDelay(10000); // 10ms
            retries--;
            continue;
        }
        gpioDelay(10000); // Wait 10ms
        if (i2cReadDevice(i2c_handle, buf, 2) == 2) {
            raw_temp = (buf[0] << 8) | buf[1];
            break;
        } else {
            fprintf(stderr, "Error reading temperature data\n");
            gpioDelay(10000); // 10ms
            retries--;
        }
    }
    if (retries == 0) {
        fprintf(stderr, "Failed to read temperature after multiple retries\n");
        return -1;
    }

    retries = I2C_RETRY_COUNT;
    // Read humidity
    while (retries > 0) {
        if (i2cWriteByte(i2c_handle, 0xE5) != 0) {
            fprintf(stderr, "Error writing humidity command\n");
            gpioDelay(10000); // 10ms
            retries--;
            continue;
        }
        gpioDelay(10000); // Wait 10ms
        if (i2cReadDevice(i2c_handle, buf, 2) == 2) {
            raw_humidity = (buf[0] << 8) | buf[1];
            break;
        } else {
            fprintf(stderr, "Error reading humidity data\n");
            gpioDelay(10000); // 10ms
            retries--;
        }
    }
    if (retries == 0) {
        fprintf(stderr, "Failed to read humidity after multiple retries\n");
        return -1;
    }

    *temperature = (175.72 * raw_temp) / 65536.0 - 46.85;
    *humidity = (125.0 * raw_humidity) / 65536.0 - 6.0;

    return 0;
}

// Function to control the fan
void control_fan(float temperature) {
    if (temperature > TEMP_THRESHOLD_HIGH) {
        gpioWrite(FAN_GPIO, 1); // Turn fan ON
    } else if (temperature < TEMP_THRESHOLD_LOW) {
        gpioWrite(FAN_GPIO, 0); // Turn fan OFF
    }
}

// Function to log data to the circular buffer
void log_data(float temperature, float humidity) {
    time(&circular_buffer[buffer_index].timestamp);
    circular_buffer[buffer_index].temperature = temperature;
    circular_buffer[buffer_index].humidity = humidity;
    buffer_index = (buffer_index + 1) % CIRCULAR_BUFFER_SIZE;
}

// Function to print the contents of the circular buffer
void print_buffer() {
    printf("\n--- Sensor Data Log ---\n");
    for (int i = 0; i < CIRCULAR_BUFFER_SIZE; i++) {
        int index = (buffer_index + i) % CIRCULAR_BUFFER_SIZE;
        char timestamp_str[30];
        strftime(timestamp_str, sizeof(timestamp_str), "%Y-%m-%d %H:%M:%S", localtime(&circular_buffer[index].timestamp));
        printf("[%s] Temperature: %.2f °C, Humidity: %.2f %%\n", timestamp_str, circular_buffer[index].temperature, circular_buffer[index].humidity);
    }
    printf("--- End of Log ---\n\n");
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set fan GPIO as output
    gpioSetMode(FAN_GPIO, PI_OUTPUT);
    gpioWrite(FAN_GPIO, 0); // Ensure fan is initially OFF

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    float temperature, humidity;

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_sensor_data(&temperature, &humidity) == 0) {
            // Log the data
            log_data(temperature, humidity);

            // Control the fan
            control_fan(temperature);

            // Print the buffer every 60 seconds
            time_t current_time;
            time(&current_time);
            if (current_time % 60 == 0) {
                print_buffer();
            }

            printf("Temperature: %.2f °C, Humidity: %.2f %%\n", temperature, humidity);
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }

        gpioDelay(2000000); // Wait 2 seconds
    }

    // Cleanup
    gpioWrite(FAN_GPIO, 0); // Turn off fan
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

