#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// SCD40 I2C address
#define SCD40_ADDR 0x62

// SCD40 commands
#define CMD_START_PERIODIC_MEASUREMENT 0x21B1
#define CMD_STOP_PERIODIC_MEASUREMENT 0x3F86

// SCD40 data ready command
#define CMD_GET_DATA_READY 0xE4B8

// SCD40 measurement command
#define CMD_READ_MEASUREMENT 0xEC05

// SCD40 measurement data length
#define MEASUREMENT_DATA_LENGTH 9

// SCD40 CRC polynomial
#define CRC_POLYNOMIAL 0x31

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    uint16_t co2;
    uint16_t temperature;
    uint16_t humidity;
} sensor_data_t;

// Function prototypes
int initialize_pigpio();
int initialize_i2c();
int send_command(uint16_t command);
int read_data_ready();
int read_measurement(sensor_data_t *data);
int verify_crc(uint8_t data[], int len);
float convert_temperature(uint16_t raw_temperature);
float convert_humidity(uint16_t raw_humidity);
int log_data(sensor_data_t data);
void signal_handler(int signal);

// Function to initialize pigpio
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Function to initialize I2C
int initialize_i2c() {
    i2c_handle = i2cOpen(1, SCD40_ADDR, 0); // Bus 1, address 0x62, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to send a command to the SCD40
int send_command(uint16_t command) {
    char buf[2];
    buf[0] = (command >> 8) & 0xFF;
    buf[1] = command & 0xFF;

    int result = i2cWriteDevice(i2c_handle, buf, 2);
    if (result != 0) {
        fprintf(stderr, "Failed to send command 0x%04X: %d\n", command, result);
        return -1;
    }
    return 0;
}

// Function to read the data ready flag
int read_data_ready() {
    char buf[2];
    int result = i2cWriteDevice(i2c_handle, (char[]){CMD_GET_DATA_READY >> 8, CMD_GET_DATA_READY & 0xFF}, 2);
    if (result != 0) {
        fprintf(stderr, "Failed to write data ready command: %d\n", result);
        return -1;
    }

    result = i2cReadDevice(i2c_handle, buf, 2);
    if (result != 0) {
        fprintf(stderr, "Failed to read data ready status: %d\n", result);
        return -1;
    }

    return (buf[1] != 0);
}

// Function to read measurement data from the SCD40
int read_measurement(sensor_data_t *data) {
    char buf[MEASUREMENT_DATA_LENGTH];
    int result = i2cWriteDevice(i2c_handle, (char[]){CMD_READ_MEASUREMENT >> 8, CMD_READ_MEASUREMENT & 0xFF}, 2);
    if (result != 0) {
        fprintf(stderr, "Failed to write measurement command: %d\n", result);
        return -1;
    }

    result = i2cReadDevice(i2c_handle, buf, MEASUREMENT_DATA_LENGTH);
    if (result != MEASUREMENT_DATA_LENGTH) {
        fprintf(stderr, "Failed to read measurement data: %d\n", result);
        return -1;
    }

    // Extract raw data
    data->co2 = (buf[0] << 8) | buf[1];
    data->temperature = (buf[3] << 8) | buf[4];
    data->humidity = (buf[6] << 8) | buf[7];

    return 0;
}

// Function to verify CRC-8 checksum
int verify_crc(uint8_t data[], int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return (crc == 0xFF);
}

// Function to convert raw temperature to Celsius
float convert_temperature(uint16_t raw_temperature) {
    return -45.0 + 175.0 * (float)raw_temperature / (float)(0xFFFF);
}

// Function to convert raw humidity to percentage
float convert_humidity(uint16_t raw_humidity) {
    return 100.0 * (float)raw_humidity / (float)(0xFFFF);
}

// Function to log data to a file
int log_data(sensor_data_t data) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s,%d,%.2f,%.2f\n", timestamp, data.co2, convert_temperature(data.temperature), convert_humidity(data.humidity));
    fflush(log_file);
    return 0;
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    terminate = 1;
    printf("Received signal %d, terminating...\n", signal);
}

int main() {
    // Register signal handler
    signal(SIGINT, signal_handler);

    // Initialize pigpio
    if (initialize_pigpio() != 0) {
        return 1;
    }

    // Initialize I2C
    if (initialize_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("air_quality.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Start periodic measurement
    if (send_command(CMD_START_PERIODIC_MEASUREMENT) != 0) {
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    gpioDelay(1000); // Wait 1 second

    // Main loop
    while (!terminate) {
        // Check if data is ready
        if (read_data_ready()) {
            sensor_data_t data;
            // Read measurement data
            if (read_measurement(&data) == 0) {
                // Verify CRC
                uint8_t co2_data[2] = {data.co2 >> 8, data.co2 & 0xFF};
                uint8_t temperature_data[2] = {data.temperature >> 8, data.temperature & 0xFF};
                uint8_t humidity_data[2] = {data.humidity >> 8, data.humidity & 0xFF};

                if (verify_crc(co2_data, 2) && verify_crc(temperature_data, 2) && verify_crc(humidity_data, 2)) {
                    // Log data
                    log_data(data);
                } else {
                    fprintf(stderr, "CRC verification failed\n");
                }
            } else {
                fprintf(stderr, "Failed to read measurement data\n");
            }
        } else {
            //fprintf(stderr, "Data not ready\n"); // Commented out to reduce verbosity
        }

