#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <signal.h>
#include <unistd.h>
#include <string.h>

// SCD40 I2C address
#define SCD40_ADDR 0x62

// SCD40 commands
#define START_PERIODIC_MEASUREMENT 0x21B1
#define GET_DATA_READY_STATUS 0xE4B8
#define READ_MEASUREMENT 0xEC05
#define STOP_PERIODIC_MEASUREMENT 0x3F86

// GPIO pin for LED
#define LED_PIN 17

// Circular buffer size
#define BUFFER_SIZE 20

// Structure to hold sensor data
typedef struct {
    uint16_t co2;
    float temperature;
    float humidity;
} sensor_data_t;

// Circular buffer structure
typedef struct {
    sensor_data_t data[BUFFER_SIZE];
    int head;
    int tail;
    int count;
} circular_buffer_t;

// Global variables
int i2c_handle;
circular_buffer_t buffer;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_pigpio();
int initialize_i2c();
int initialize_scd40();
int read_scd40_data(sensor_data_t *data);
int validate_crc(uint8_t data[], uint8_t crc);
void add_to_buffer(circular_buffer_t *buffer, sensor_data_t data);
sensor_data_t get_from_buffer(circular_buffer_t *buffer, int index);
void print_buffer(circular_buffer_t *buffer);
void control_led(uint16_t co2);
void signal_handler(int signal);
void cleanup();

// Initialize pigpio library
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Initialize I2C communication
int initialize_i2c() {
    i2c_handle = i2cOpen(1, SCD40_ADDR, 0); // Bus 1, address 0x62, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "I2C open failed: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Initialize SCD40 sensor
int initialize_scd40() {
    uint8_t cmd[2] = {0x21, 0xB1};
    int result = i2cWriteDevice(i2c_handle, cmd, 2);
    if (result != 0) {
        fprintf(stderr, "SCD40 initialization failed: %d\n", result);
        return -1;
    }
    gpioDelay(100); // Wait for initialization
    return 0;
}

// Read data from SCD40 sensor
int read_scd40_data(sensor_data_t *data) {
    uint8_t cmd[2] = {0xEC, 0x05};
    uint8_t buffer[9];
    int result;

    result = i2cWriteDevice(i2c_handle, cmd, 2);
    if (result != 0) {
        fprintf(stderr, "Failed to send read measurement command: %d\n", result);
        return -1;
    }

    gpioDelay(1); // Small delay after writing the command

    result = i2cReadDevice(i2c_handle, buffer, 9);
    if (result != 9) {
        fprintf(stderr, "Failed to read data: %d\n", result);
        return -1;
    }

    // Extract data and validate CRC
    uint16_t co2 = (buffer[0] << 8) | buffer[1];
    uint16_t temp_raw = (buffer[3] << 8) | buffer[4];
    uint16_t humidity_raw = (buffer[6] << 8) | buffer[7];

    if (!validate_crc(buffer, buffer[2]) || !validate_crc(buffer + 3, buffer[5]) || !validate_crc(buffer + 6, buffer[8])) {
        fprintf(stderr, "CRC validation failed\n");
        return -1;
    }

    // Convert data
    data->co2 = co2;
    data->temperature = -45 + 175 * (float)temp_raw / 65535.0;
    data->humidity = 100 * (float)humidity_raw / 65535.0;

    return 0;
}

// Validate CRC-8 checksum
int validate_crc(uint8_t data[], uint8_t crc) {
    uint8_t polynomial = 0x31; // x^8 + x^5 + x^4 + 1
    uint8_t crc_calculated = 0xFF;
    uint8_t bit;

    for (int i = 0; i < 2; i++) {
        crc_calculated ^= data[i];
        for (int j = 0; j < 8; j++) {
            bit = crc_calculated & 0x80;
            crc_calculated <<= 1;
            if (bit) {
                crc_calculated ^= polynomial;
            }
        }
    }

    return (crc_calculated == crc);
}

// Add data to circular buffer
void add_to_buffer(circular_buffer_t *buffer, sensor_data_t data) {
    buffer->data[buffer->head] = data;
    buffer->head = (buffer->head + 1) % BUFFER_SIZE;
    if (buffer->count == BUFFER_SIZE) {
        buffer->tail = (buffer->tail + 1) % BUFFER_SIZE;
    } else {
        buffer->count++;
    }
}

// Get data from circular buffer
sensor_data_t get_from_buffer(circular_buffer_t *buffer, int index) {
    if (index < 0 || index >= buffer->count) {
        fprintf(stderr, "Index out of bounds\n");
        sensor_data_t empty_data = {0, 0.0, 0.0};
        return empty_data;
    }
    int actual_index = (buffer->tail + index) % BUFFER_SIZE;
    return buffer->data[actual_index];
}

// Print circular buffer contents
void print_buffer(circular_buffer_t *buffer) {
    printf("Circular Buffer Contents:\n");
    for (int i = 0; i < buffer->count; i++) {
        sensor_data_t data = get_from_buffer(buffer, i);
        printf("  [%d] CO2: %d ppm, Temperature: %.2f C, Humidity: %.2f %%\n", i, data.co2, data.temperature, data.humidity);
    }
}

// Control LED based on CO2 level
void control_led(uint16_t co2) {
    if (co2 > 1000) {
        gpioWrite(LED_PIN, 1); // Turn LED on
    } else {
        gpioWrite(LED_PIN, 0); // Turn LED off
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup resources before exiting
void cleanup() {
    printf("Cleaning up...\n");
    uint8_t stop_cmd[2] = {0x3F, 0x86};
    i2cWriteDevice(i2c_handle, stop_cmd, 2);
    i2cClose(i2c_handle);
    gpioWrite(LED_PIN, 0); // Turn off LED
    gpioTerminate();
    exit(0);
}

int main() {
    // Initialize
    if (initialize_pigpio() != 0) return 1;
    if (initialize_i2c() != 0) {
        gpioTerminate();
        return 1;
    }
    if (initialize_scd40() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    gpioSetMode(LED_PIN, PI_OUTPUT);
    gpioWrite(LED_PIN, 0); // Initially turn off the LED

    buffer.head = 0;
    buffer.tail = 0;
    buffer.count = 0;

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    sensor_data_t sensor_data;
    uint8_t data_ready_status[2];
    int result;

    printf("SCD40 CO2 Sensor Data Logger\n");

    while (!terminate) {
        // Check data ready status
        uint8_t cmd[2] = {0xE4, 0xB8};
        result = i2cWriteDevice(i2c_handle, cmd, 2);
        if (result != 0) {
            fprintf(stderr, "Failed to send data ready status command: %d\n", result);
            gpioDelay(5000); // Wait 5 seconds before retrying
            continue;
        }

        result = i2cReadDevice(i2c_handle, data_ready_status, 2);
        if (result != 2) {
            fprintf(stderr, "Failed to read data ready status: %d\n", result);
            gpioDelay(5000); // Wait 5 seconds before retrying
            continue;
        }

        if (data_ready_status[0] & 0x01) {
            // Read sensor data
            if (read_scd40_data(&sensor_data) == 0) {
                printf("CO2: %d ppm, Temperature: %.2f C, Humidity: %.2f %%\n", sensor_data.co2, sensor_data.temperature, sensor_data.humidity);
                add_to_buffer(&buffer, sensor_data);
                control_led(sensor_data.co2);
            } else {
                fprintf(stderr, "Failed to read sensor data\n");
            }
        } else {
            printf("Data not ready yet\n");
        }

        gpioDelay(5000); // Wait 5 seconds
    }

    cleanup();
    return 0;
}

