#define SENSOR_OK 0
#define SENSOR_ABSENT 1
#define SENSOR_STUCK 2
#define SENSOR_ERROR 3

volatile sig_atomic_t program_running = 1;
FILE *log_file = NULL;

void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully.\n", signal);
}

int read_temperature(double *temperature) {
    int status = SENSOR_OK;
    unsigned int TH = 0;
    unsigned int TL = 0;
    int last_level = -1; // Initialize to an invalid level
    unsigned int start_tick = 0;
    unsigned int current_tick = 0;
    unsigned int timeout_tick = 0;

    // Wait for the first rising edge
    while (program_running) {
        current_tick = gpioTick();
        if (gpioRead(GPIO_PIN) == 1 && last_level == 0) {
            start_tick = current_tick;
            break;
        }
        if (last_level != -1 && last_level != gpioRead(GPIO_PIN)) {
            status = SENSOR_STUCK;
            break;
        }
        if (current_tick - timeout_tick > 50000) { // 50ms timeout
            status = SENSOR_ABSENT;
            break;
        }
        last_level = gpioRead(GPIO_PIN);
    }

    if (!program_running) return SENSOR_ERROR;

    // Measure high time (TH)
    while (program_running) {
        current_tick = gpioTick();
        if (gpioRead(GPIO_PIN) == 0 && last_level == 1) {
            TH = current_tick - start_tick;
            break;
        }
        if (current_tick - timeout_tick > 50000) { // 50ms timeout
            status = SENSOR_ABSENT;
            break;
        }
        last_level = gpioRead(GPIO_PIN);
    }

    if (!program_running) return SENSOR_ERROR;

    timeout_tick = current_tick;

    // Measure low time (TL)
    while (program_running) {
        current_tick = gpioTick();
        if (gpioRead(GPIO_PIN) == 1 && last_level == 0) {
            TL = current_tick - (start_tick + TH);
            break;
        }
        if (current_tick - timeout_tick > 50000) { // 50ms timeout
            status = SENSOR_ABSENT;
            break;
        }
        last_level = gpioRead(GPIO_PIN);
    }

    if (!program_running) return SENSOR_ERROR;

    if (TL == 0) {
        status = SENSOR_ERROR;
    } else {
        *temperature = 4215.0 - (2143.0 * (double)TH / (double)TL);

        if (*temperature < -40.0 || *temperature > 150.0) {
            status = SENSOR_ERROR;
        }
    }

    return status;
}

