    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    if (log_file == NULL) {
        fprintf(stderr, "Error: Log file is not open.\n");
        return -1;
    }

    if (status == SENSOR_OK) {
        fprintf(log_file, "%s, Temperature: %.2f °C\n", timestamp, temperature);
    } else {
        fprintf(log_file, "%s, SENSOR %d\n", timestamp, status);
    }

    fflush(log_file); // Ensure data is written to disk
    return 0;
}

int main() {
    int pigpio_init_result;
    int log_file_open_result;
    double temperature;
    int sensor_status;
    int consecutive_errors = 0;

    // Initialize pigpio
    pigpio_init_result = gpioInitialise();
    if (pigpio_init_result < 0) {
        fprintf(stderr, "pigpio initialisation failed: %d\n", pigpio_init_result);
        return 1;
    }

    // Set GPIO pin as input
    gpioSetMode(GPIO_PIN, PI_INPUT);

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Temperature monitoring started. Press Ctrl+C to exit.\n");

    while (program_running) {
        sensor_status = read_temperature(&temperature);

        if (sensor_status == SENSOR_OK) {
            if (log_temperature(temperature, sensor_status) != 0) {
                fprintf(stderr, "Error logging temperature.\n");
            }
            consecutive_errors = 0; // Reset error count
        } else {
            if (log_temperature(0.0, sensor_status) != 0) {
                fprintf(stderr, "Error logging sensor status.\n");
            }
            consecutive_errors++;

            if (consecutive_errors >= 3) {
                time_t rawtime;
                struct tm *timeinfo;
                char timestamp[20];

                time(&rawtime);
                timeinfo = localtime(&rawtime);
                strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

                fprintf(log_file, "%s, SENSOR MALFUNCTION\n", timestamp);
                fflush(log_file);
                consecutive_errors = 0; // Reset after logging malfunction
            }
        }

        gpioDelay(5000000); // Sample every 5 seconds
    }

    // Cleanup
    printf("Cleaning up...\n");
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();

    printf("Exiting.\n");
    return 0;
}

