#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <math.h>

// Constants
#define I2C_BUS 1
#define SHT35_ADDR 0x44
#define MEASUREMENT_COMMAND_HIGH 0x24
#define MEASUREMENT_COMMAND_LOW 0x00
#define MEASUREMENT_DELAY_MS 15
#define RETRY_COUNT 3
#define OFFSET_TEMP 2.0
#define OFFSET_HUMIDITY 5.0
#define OFFSET_FREQUENCY (2 * M_PI / 3600.0) // 1 hour period
#define MAX_TEMP 50.0
#define MIN_TEMP -10.0
#define MAX_HUMIDITY 100.0
#define MIN_HUMIDITY 0.0

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float temperature;
    float humidity;
} SensorData;

// Function prototypes
int initialize_pigpio();
int open_i2c_connection();
int read_sensor_data(uint8_t *data);
int validate_crc(uint8_t *data, int data_len);
SensorData convert_raw_to_celsius_rh(uint16_t raw_temperature, uint16_t raw_humidity);
SensorData apply_sinusoidal_offset(SensorData data);
int log_data(SensorData data);
void signal_handler(int signal);
void cleanup();

// Function to initialize pigpio
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Function to open I2C connection
int open_i2c_connection() {
    i2c_handle = i2cOpen(I2C_BUS, SHT35_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to read sensor data
int read_sensor_data(uint8_t *data) {
    char cmd[2] = {MEASUREMENT_COMMAND_HIGH, MEASUREMENT_COMMAND_LOW};
    int result;

    for (int i = 0; i < RETRY_COUNT; ++i) {
        result = i2cWriteDevice(i2c_handle, cmd, 2);
        if (result == 0) {
            gpioDelay(MEASUREMENT_DELAY_MS * 1000); // Delay in microseconds
            result = i2cReadDevice(i2c_handle, (char *)data, 6);
            if (result == 6) {
                return 0; // Success
            } else {
                fprintf(stderr, "I2C read failed (attempt %d): %d\n", i + 1, result);
            }
        } else {
            fprintf(stderr, "I2C write failed (attempt %d): %d\n", i + 1, result);
        }
        gpioDelay(1000000); // 1 second delay
    }

    fprintf(stderr, "Failed to read sensor data after %d retries\n", RETRY_COUNT);
    return -1; // Failure
}

// Function to validate CRC
int validate_crc(uint8_t *data, int data_len) {
    uint8_t crc;
    uint8_t polynomial = 0x31; // x^8 + x^5 + x^4 + 1

    crc = 0xFF;
    for (int i = 0; i < data_len - 1; ++i) {
        crc ^= data[i];
        for (int j = 0; j < 8; ++j) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ polynomial;
            } else {
                crc <<= 1;
            }
        }
    }

    return (crc == data[data_len - 1]);
}

// Function to convert raw data to Celsius and %RH
SensorData convert_raw_to_celsius_rh(uint16_t raw_temperature, uint16_t raw_humidity) {
    SensorData data;
    data.temperature = -45.0 + (175.0 * (float)raw_temperature / 65535.0);
    data.humidity = 100.0 * (float)raw_humidity / 65535.0;
    return data;
}

// Function to apply sinusoidal offset
SensorData apply_sinusoidal_offset(SensorData data) {
    time_t now = time(NULL);
    double time_since_epoch = (double)now;
    double offset_temp = OFFSET_TEMP * sin(OFFSET_FREQUENCY * time_since_epoch);
    double offset_humidity = OFFSET_HUMIDITY * sin(OFFSET_FREQUENCY * time_since_epoch);

    // Clamp values to realistic ranges
    float temp = data.temperature + offset_temp;
    if (temp > MAX_TEMP) temp = MAX_TEMP;
    if (temp < MIN_TEMP) temp = MIN_TEMP;

    float humidity = data.humidity + offset_humidity;
    if (humidity > MAX_HUMIDITY) humidity = MAX_HUMIDITY;
    if (humidity < MIN_HUMIDITY) humidity = MIN_HUMIDITY;

    data.temperature = temp;
    data.humidity = humidity;
    return data;
}

// Function to log data to file
int log_data(SensorData data) {
    time_t now = time(NULL);
    struct tm *tstruct = gmtime(&now);
    char buf[80];
    strftime(buf, sizeof(buf), "%Y-%m-%dT%H:%M:%SZ", tstruct);

    if (log_file == NULL) {
        fprintf(stderr, "Log file is not open\n");
        return -1;
    }

    fprintf(log_file, "%s,%.2f,%.2f\n", buf, data.temperature, data.humidity);
    fflush(log_file); // Ensure data is written to disk
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Cleanup function
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (initialize_pigpio() != 0) {
        return 1;
    }

    // Open I2C connection
    if (open_i2c_connection() != 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen("environmental_data.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup();
        return 1;
    }

    uint8_t sensor_data[6];
    uint16_t raw_temperature, raw_humidity;
    SensorData data, processed_data;

    while (!terminate) {
        // Read sensor data
        if (read_sensor_data(sensor_data) == 0) {
            // Validate CRC
            if (!validate_crc(sensor_data, 6)) {
                fprintf(stderr, "CRC validation failed\n");
                log_data(convert_raw_to_celsius_rh(0, 0)); // Log NaN values
            } else {
                // Convert raw data to Celsius and %RH
                raw_temperature = (sensor_data[0] << 8) | sensor_data[1];
                raw_humidity = (sensor_data[3] << 8) | sensor_data[4];
                data = convert_raw_to_celsius_rh(raw_temperature, raw_humidity);

                // Apply sinusoidal offset
                processed_data = apply_sinusoidal_offset(data);

                // Log data
                if (log_data(processed_data) != 0) {
                    fprintf(stderr, "Failed to log data\n");
                }
            }
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
            log_data(convert_raw_to_celsius_rh(0, 0)); // Log NaN values
        }

        gpioDelay(5000000); // Wait 5 seconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

