#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>

// Constants
#define I2C_BUS 1
#define I2C_ADDRESS 0x25
#define CONTINUOUS_MEASUREMENT_COMMAND 0x362F
#define CONVERSION_TIME_MS 50
#define SAMPLE_INTERVAL_S 1
#define FILENAME "airflow.dat"

// Global variables
int i2c_handle;
FILE *fp;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float pressure;
    float temperature;
} SensorData;

// Function prototypes
int initialize_pigpio();
int open_i2c_connection();
int write_command(int handle, uint16_t command);
int read_sensor_data(int handle, uint8_t *data);
uint8_t calculate_crc(const uint8_t *data, size_t len);
int validate_crc(uint8_t crc, const uint8_t *data, size_t len);
SensorData convert_data(const uint8_t *data);
int log_data(FILE *fp, SensorData data);
void signal_handler(int signal);
void cleanup();

// Signal handler
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

// Initialize pigpio
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Open I2C connection
int open_i2c_connection() {
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %s\n", strerror(errno));
        return -1;
    }
    return i2c_handle;
}

// Write command to the sensor
int write_command(int handle, uint16_t command) {
    char buf[2];
    buf[0] = (command >> 8) & 0xFF;
    buf[1] = command & 0xFF;
    int result = i2cWriteDevice(handle, buf, 2);
    if (result != 0) {
        fprintf(stderr, "Failed to write command: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Read sensor data
int read_sensor_data(int handle, uint8_t *data) {
    int result = i2cReadDevice(handle, (char *)data, 9);
    if (result != 9) {
        fprintf(stderr, "Failed to read sensor data: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Calculate CRC-8 checksum
uint8_t calculate_crc(const uint8_t *data, size_t len) {
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Validate CRC-8 checksum
int validate_crc(uint8_t crc, const uint8_t *data, size_t len) {
    uint8_t calculated_crc = calculate_crc(data, len);
    return (crc == calculated_crc);
}

// Convert raw data to pressure and temperature
SensorData convert_data(const uint8_t *data) {
    SensorData sensor_data;
    int16_t raw_pressure = (data[0] << 8) | data[1];
    int16_t raw_temperature = (data[3] << 8) | data[4];

    if (!validate_crc(data[2], data, 2)) {
        fprintf(stderr, "Pressure CRC check failed\n");
        sensor_data.pressure = -999.0; // Indicate error
    } else if (!validate_crc(data[5], data + 3, 2)) {
        fprintf(stderr, "Temperature CRC check failed\n");
        sensor_data.temperature = -999.0; // Indicate error
    } else {
        sensor_data.pressure = (float)raw_pressure / 240.0 - 1000.0; // Pa
        sensor_data.temperature = (float)raw_temperature / 200.0 - 45.0; // °C
    }

    return sensor_data;
}

// Log data to file
int log_data(FILE *fp, SensorData data) {
    size_t elements_written = fwrite(&data, sizeof(SensorData), 1, fp);
    if (elements_written != 1) {
        fprintf(stderr, "Failed to write data to file: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Cleanup resources
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (fp != NULL) {
        fclose(fp);
    }
    gpioTerminate();
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (initialize_pigpio() != 0) {
        return 1;
    }

    // Open I2C connection
    i2c_handle = open_i2c_connection();
    if (i2c_handle < 0) {
        cleanup();
        return 1;
    }

    // Open data file
    fp = fopen(FILENAME, "wb");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open file: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    // Write continuous measurement command
    if (write_command(i2c_handle, CONTINUOUS_MEASUREMENT_COMMAND) != 0) {
        cleanup();
        return 1;
    }

    // Main loop
    uint8_t data[9];
    SensorData sensor_data;
    while (!terminate) {
        // Read sensor data
        if (read_sensor_data(i2c_handle, data) == 0) {
            // Convert data
            sensor_data = convert_data(data);

            // Log data
            if (log_data(fp, sensor_data) != 0) {
                terminate = 1; // Stop on logging error
            }
        } else {
            fprintf(stderr, "Failed to read sensor data, retrying...\n");
        }

        // Wait for the next sample
        gpioDelay(SAMPLE_INTERVAL_S * 1000000); // Delay in microseconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

