// Reads the raw flow data from the sensor
int read_sensor(int i2c_handle, uint16_t *raw_flow) {
    char buffer[2];
    int result = i2cReadDevice(i2c_handle, buffer, 2);

    if (result != 2) {
        fprintf(stderr, "Error reading from I2C device: %d\n", result);
        return -1; // Indicate failure
    }

    *raw_flow = (buffer[0] << 8) | buffer[1];
    return 0; // Indicate success
}

// Converts the raw flow reading to a flow rate in SLPM
float convert_to_flow_rate(uint16_t raw_flow) {
    // Mask off the status bits and shift right by 2
    raw_flow = (raw_flow >> 2) & 0x3FFF; // Keep only the 14-bit flow data

    // Linear transfer function
    float flow_rate = ((float)raw_flow - 1638) * 10.0 / (14745 - 1638);

    // Ensure flow rate is within the valid range
    if (flow_rate < 0.0) flow_rate = 0.0;
    if (flow_rate > 10.0) flow_rate = 10.0;

    return flow_rate;
}

