void set_fan_speed(float flow_rate) {
    // Scale the flow rate to a duty cycle between 0 and 100
    float duty_cycle = flow_rate / 10.0 * 100.0;

    // Set the PWM duty cycle
    gpioPWM(FAN_GPIO, (int)duty_cycle);
}

