    status = i2cWriteByteData(i2c_handle, CTRL_REG1, 0xB0); // Block data update, 10 Hz, active mode
    if (status < 0) {
        fprintf(stderr, "%s CTRL_REG1 write failed: %d\n", get_timestamp(), status);
        return -1;
    }

    return 0;
}

