#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// SCD30 I2C address
#define SCD30_ADDR 0x61

// I2C bus
#define I2C_BUS 1

// Measurement interval (seconds)
#define MEASUREMENT_INTERVAL 2

// Ventilation thresholds (ppm)
#define CO2_LOW 800
#define CO2_HIGH 1200

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int scd30_init();
int scd30_start_periodic_measurement();
int scd30_read_measurement(float *co2, float *temperature, float *humidity);
int scd30_stop_periodic_measurement();
int scd30_crc8(const uint8_t *data, int len);
void log_data(float co2, float temperature, float humidity);
void control_ventilation(float co2);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

// SCD30 initialization function
int scd30_init() {
    uint8_t cmd[2];
    uint8_t data[2];
    int result;

    // Check if the sensor is responding
    cmd[0] = 0x02; cmd[1] = 0x02;
    result = i2cWriteDevice(i2c_handle, (char *)cmd, 2);
    if (result != 0) {
        fprintf(log_file, "%s: I2C write error during sensor check: %d\n", __TIME__, result);
        fflush(log_file);
        return -1;
    }

    gpioDelay(10000); // 10ms delay

    result = i2cReadDevice(i2c_handle, (char *)data, 2);
    if (result != 2) {
        fprintf(log_file, "%s: I2C read error during sensor check: %d\n", __TIME__, result);
        fflush(log_file);
        return -1;
    }

    if (data[0] != 0x00 || data[1] != 0x00) {
        fprintf(log_file, "%s: Sensor check failed: 0x%02x 0x%02x\n", __TIME__, data[0], data[1]);
        fflush(log_file);
        return -1;
    }

    printf("SCD30 sensor found and initialized.\n");
    return 0;
}

// Start periodic measurement function
int scd30_start_periodic_measurement() {
    uint8_t cmd[2];
    int result;

    cmd[0] = 0x21; cmd[1] = 0xB1;
    result = i2cWriteDevice(i2c_handle, (char *)cmd, 2);
    if (result != 0) {
        fprintf(log_file, "%s: I2C write error starting periodic measurement: %d\n", __TIME__, result);
        fflush(log_file);
        return -1;
    }

    printf("Periodic measurement started.\n");
    return 0;
}

// Stop periodic measurement function
int scd30_stop_periodic_measurement() {
    uint8_t cmd[2];
    int result;

    cmd[0] = 0x3F; cmd[1] = 0x86;
    result = i2cWriteDevice(i2c_handle, (char *)cmd, 2);
    if (result != 0) {
        fprintf(log_file, "%s: I2C write error stopping periodic measurement: %d\n", __TIME__, result);
        fflush(log_file);
        return -1;
    }

    printf("Periodic measurement stopped.\n");
    return 0;
}

// Read measurement function
int scd30_read_measurement(float *co2, float *temperature, float *humidity) {
    uint8_t cmd[2];
    uint8_t data[18];
    int result;

    cmd[0] = 0x03; cmd[1] = 0x00;
    result = i2cWriteDevice(i2c_handle, (char *)cmd, 2);
    if (result != 0) {
        fprintf(log_file, "%s: I2C write error requesting measurement: %d\n", __TIME__, result);
        fflush(log_file);
        return -1;
    }

    gpioDelay(10000); // 10ms delay

    result = i2cReadDevice(i2c_handle, (char *)data, 18);
    if (result != 18) {
        fprintf(log_file, "%s: I2C read error reading measurement: %d\n", __TIME__, result);
        fflush(log_file);
