#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// SDP32 I2C address
#define SDP32_ADDR 0x21

// SDP32 continuous measurement command
#define SDP32_MEASURE_CMD_MSB 0x36
#define SDP32_MEASURE_CMD_LSB 0x2F

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float pressure_pa;
    float temperature_c;
} sensor_data_t;

// Function prototypes
int init_i2c();
int send_command(int handle, uint8_t msb, uint8_t lsb);
int read_sensor_data(int handle, uint8_t *data);
uint8_t calculate_crc(const uint8_t *data, int len);
int verify_crc(const uint8_t *data, int len, uint8_t crc);
int convert_data(const uint8_t *data, sensor_data_t *sensor_data);
void log_data(const sensor_data_t *sensor_data);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(1, SDP32_ADDR, 0); // Bus 1, address 0x21, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Send command to the SDP32 sensor
int send_command(int handle, uint8_t msb, uint8_t lsb) {
    char buf[2];
    buf[0] = msb;
    buf[1] = lsb;
    int result = i2cWriteDevice(handle, buf, 2);
    if (result != 0) {
        fprintf(stderr, "Error writing to I2C: %d\n", result);
        return -1;
    }
    return 0;
}

// Read sensor data from the SDP32 sensor
int read_sensor_data(int handle, uint8_t *data) {
    int result = i2cReadDevice(handle, (char *)data, 9);
    if (result != 9) {
        fprintf(stderr, "Error reading from I2C: %d\n", result);
        return -1;
    }
    return 0;
}

// Calculate CRC-8 checksum
uint8_t calculate_crc(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Verify CRC-8 checksum
int verify_crc(const uint8_t *data, int len, uint8_t crc) {
    uint8_t calculated_crc = calculate_crc(data, len);
    if (calculated_crc != crc) {
        fprintf(stderr, "CRC check failed! Calculated: 0x%02X, Received: 0x%02X\n", calculated_crc, crc);
        return -1;
    }
    return 0;
}

// Convert raw data to pressure and temperature
int convert_data(const uint8_t *data, sensor_data_t *sensor_data) {
    int16_t raw_pressure = (data[0] << 8) | data[1];
    int16_t raw_temperature = (data[3] << 8) | data[4];
    uint16_t raw_scale_factor = (data[6] << 8) | data[7];

    if (verify_crc(data, 2, data[2]) != 0 || verify_crc(data + 3, 2, data[5]) != 0 || verify_crc(data + 6, 2, data[8]) != 0) {
        return -1; // CRC check failed
    }

    sensor_data->pressure_pa = (float)raw_pressure / raw_scale_factor;
    sensor_data->temperature_c = (float)raw_temperature / 200.0; // Temperature in degrees Celsius

    return 0;
}

// Log sensor data to the console
void log_data(const sensor_data_t *sensor_data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("%s - Pressure: %.2f Pa, Temperature: %.2f °C\n", timestamp, sensor_data->pressure_pa, sensor_data->temperature_c);
}

int main(int argc, char *argv[]) {
    int sampling_interval = 1000; // Default sampling interval in milliseconds

    // Parse command-line arguments
    if (argc > 1) {
        sampling_interval = atoi(argv[1]);
        if (sampling_interval <= 0) {
            fprintf(stderr, "Invalid sampling interval. Using default: 1000 ms\n");
            sampling_interval = 1000;
        }
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Send continuous measurement command
    if (send_command(i2c_handle, SDP32_MEASURE_CMD_MSB, SDP32_MEASURE_CMD_LSB) != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    uint8_t sensor_data_raw[9];
    sensor_data_t sensor_data;

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_sensor_data(i2c_handle, sensor_data_raw) == 0) {
            // Convert data
            if (convert_data(sensor_data_raw, &sensor_data) == 0) {
                // Log data
                log_data(&sensor_data);
            } else {
                fprintf(stderr, "Data conversion failed\n");
            }
        } else {
            fprintf(stderr, "Failed to read sensor data. Attempting to re-initialize I2C.\n");
            i2cClose(i2c_handle);
            if (init_i2c() != 0) {
                fprintf(stderr, "Failed to re-initialize I2C. Exiting.\n");
                break; // Exit loop if re-initialization fails
            }
            if (send_command(i2c_handle, SDP32_MEASURE_CMD_MSB, SDP32_MEASURE_CMD_LSB) != 0) {
                fprintf(stderr, "Failed to re-send measurement command. Exiting.\n");
                break;
            }
        }

        // Wait for the next sample
        gpioDelay(sampling_interval * 1000); // pigpioDelay takes microseconds
    }

    // Clean up
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

