#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define the I2C address of the SDP810-125Pa sensor
#define SDP810_I2C_ADDR 0x25

// Define the I2C bus number (typically 1 on Raspberry Pi)
#define I2C_BUS 1

// Define the continuous measurement command
#define MEASURE_CMD 0x3615

// Define the number of bytes to read from the sensor
#define NUM_BYTES 9

// Define the CRC-8 polynomial
#define CRC8_POLY 0x31

// Global variable for the I2C handle
int i2c_handle;

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    exit(0);
}

// Function to calculate the CRC-8 checksum
uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC8_POLY;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Function to read data from the SDP810 sensor
int read_sdp810(int i2c_handle, float *pressure, float *temperature) {
    uint8_t buffer[NUM_BYTES];
    int result;

    // Send the continuous measurement command
    result = i2cWriteWordData(i2c_handle, MEASURE_CMD, 0); //MSB=0, LSB=0
    if (result != 0) {
        fprintf(stderr, "Error writing to I2C device: %d\n", result);
        return -1;
    }

    // Wait for at least 45 ms for the conversion
    gpioDelay(45000); // 45 ms

    // Read 9 bytes from the sensor
    result = i2cReadI2CBlockData(i2c_handle, 0, (char *)buffer, NUM_BYTES);
    if (result != NUM_BYTES) {
        fprintf(stderr, "Error reading from I2C device: %d\n", result);
        return -1;
    }

    // Validate CRC-8 for each 3-byte data word
    for (int i = 0; i < 3; i++) {
        uint8_t crc = crc8(buffer + i * 3, 3);
        if (crc != buffer[i * 3 + 3]) {
            fprintf(stderr, "CRC check failed for data word %d\n", i);
            return -1;
        }
    }

    // Extract raw values and scale factors
    int16_t raw_pressure = (buffer[0] << 8) | buffer[1];
    int16_t raw_temperature = (buffer[3] << 8) | buffer[4];
    uint16_t scale_factor_pressure = (buffer[6] << 8) | buffer[7];

    // Convert raw values to physical units
    *pressure = (float)raw_pressure / scale_factor_pressure;
    *temperature = (float)raw_temperature / 200.0;

    return 0;
}

int main() {
    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open the I2C bus
    i2c_handle = i2cOpen(I2C_BUS, SDP810_I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handling for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    float pressure, temperature;

    // Main loop
    while (1) {
        // Read data from the sensor
        if (read_sdp810(i2c_handle, &pressure, &temperature) == 0) {
            // Log the pressure and temperature values
            printf("Pressure: %.2f Pa, Temperature: %.2f °C\n", pressure, temperature);
        } else {
            fprintf(stderr, "Error reading sensor data\n");
        }

        // Wait for 1 second
        sleep(1);
    }

    return 0;
}

