#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <time.h>
#include <errno.h>

#define I2C_BUS "/dev/i2c-1"
#define HDC1000_ADDR 0x40
#define CONFIG_REG 0x02
#define TEMP_REG 0x00
#define RETRY_COUNT 3

volatile sig_atomic_t program_running = 1;
int i2c_fd = -1;

void signal_handler(int signum) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signum);
}

int hdc1000_init(int fd) {
    uint8_t config_value = 0x00; // Enable temperature and humidity measurement, 14-bit resolution
    int retries = RETRY_COUNT;

    while (retries > 0) {
        if (write(fd, &config_value, 1) != 1) {
            perror("Failed to write to configuration register");
            retries--;
            usleep(10000); // Wait 10ms before retrying
        } else {
            return 0; // Success
        }
    }

    fprintf(stderr, "Failed to initialize HDC1000 after %d retries.\n", RETRY_COUNT);
    return -1; // Failure
}

int hdc1000_read_data(int fd, float *temperature, float *humidity) {
    uint8_t temp_reg = TEMP_REG;
    uint8_t data[4];
    int retries = RETRY_COUNT;

    while (retries > 0) {
        if (write(fd, &temp_reg, 1) != 1) {
            perror("Failed to write to temperature register");
            retries--;
            usleep(10000); // Wait 10ms before retrying
        } else {
            usleep(20000); // Wait for conversion (at least 20ms)

            if (read(fd, data, 4) != 4) {
                perror("Failed to read data from sensor");
                retries--;
                usleep(10000); // Wait 10ms before retrying
            } else {
                // Combine the two bytes for temperature and humidity
                uint16_t raw_temperature = (data[0] << 8) | data[1];
                uint16_t raw_humidity = (data[2] << 8) | data[3];

                // Convert raw values to temperature and humidity
                *temperature = (float)raw_temperature / 65536.0 * 165.0 - 40.0;
                *humidity = (float)raw_humidity / 65536.0 * 100.0;

                return 0; // Success
            }
        }
    }

    fprintf(stderr, "Failed to read data from HDC1000 after %d retries.\n", RETRY_COUNT);
    return -1; // Failure
}

int main() {
    struct timespec sleep_time;
    sleep_time.tv_sec = 5;  // 5 seconds
    sleep_time.tv_nsec = 0; // 0 nanoseconds

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    // Set slave address
    if (ioctl(i2c_fd, I2C_SLAVE, HDC1000_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    // Initialize HDC1000 sensor
    if (hdc1000_init(i2c_fd) != 0) {
        fprintf(stderr, "HDC1000 initialization failed.\n");
        close(i2c_fd);
        return 1;
    }

    float temperature, humidity;

    while (program_running) {
        if (hdc1000_read_data(i2c_fd, &temperature, &humidity) == 0) {
            printf("Temperature: %.2f C, Humidity: %.2f %%\n", temperature, humidity);
        } else {
            fprintf(stderr, "Failed to read temperature and humidity.\n");
        }

        nanosleep(&sleep_time, NULL);
    }

    // Close I2C bus
    close(i2c_fd);

    return 0;
}

