// Define constants
#define I2C_BUS 1
#define SI7051_ADDR 0x40
#define MEASURE_TEMP_CMD 0xE3
#define SLEEP_TIME_US 5000000 // 5 seconds in microseconds

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Signal handler function
void signal_handler(int sig) {
    fprintf(stderr, "\nCaught signal %d, terminating gracefully...\n", sig);
    terminate = 1;
}

// Function to read temperature from Si7051 sensor
float read_temperature() {
    int raw_temperature;
    float temperature_celsius;

    // Send measurement command
    if (i2cWriteByteData(i2c_handle, MEASURE_TEMP_CMD, 0) != 0) {
        fprintf(stderr, "Error writing to I2C device.\n");
        return -1000.0; // Indicate error
    }

    // Wait for measurement to complete (datasheet specifies typical 25ms)
    gpioDelay(50000); // 50ms

    // Read temperature data
    raw_temperature = i2cReadWordData(i2c_handle, 0);
    if (raw_temperature < 0) {
        fprintf(stderr, "Error reading from I2C device.\n");
        return -1000.0; // Indicate error
    }

    // Convert raw temperature to Celsius (datasheet formula)
    temperature_celsius = (175.72 * raw_temperature / 65536.0) - 46.85;

    return temperature_celsius;
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, SI7051_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        float temperature = read_temperature();

        if (temperature > -999.0) {
            printf("Temperature: %.2f °C\n", temperature);
        } else {
            fprintf(stderr, "Failed to read temperature.\n");
        }

        gpioDelay(SLEEP_TIME_US); // Sleep for 5 seconds
    }

    // Close I2C bus and terminate pigpio library
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

