// Define the I2C bus and address
#define I2C_BUS 1
#define MLX90833_ADDR 0x60

// Define the register address for pressure reading (example, check datasheet)
#define PRESSURE_REG 0x00

// Global variable for I2C handle
int i2c_handle;

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    exit(0);
}

// Function to read pressure from the sensor
float read_pressure() {
    char buf[2];
    int result;

    // Write the register address to be read
    result = i2cWriteByteData(i2c_handle, PRESSURE_REG, 0); // Example: writing to register
    if (result != 0) {
        fprintf(stderr, "Error writing to I2C device: %d\n", result);
        return -1.0; // Indicate error
    }

    // Read two bytes from the sensor
    result = i2cReadI2CBlockData(i2c_handle, PRESSURE_REG, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading from I2C device: %d\n", result);
        return -1.0; // Indicate error
    }

    // Combine the two bytes into a 16-bit value
    int16_t raw_pressure = (buf[0] << 8) | buf[1];

    // Convert the raw value to Pascals (example conversion, check datasheet)
    float pressure_Pa = (float)raw_pressure * 0.1; // Example scaling factor

    return pressure_Pa;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, MLX90833_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handling for Ctrl+C
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (1) {
        // Read pressure
        float pressure = read_pressure();

        // Get current time
        time_t now = time(NULL);
        struct tm *t = localtime(&now);
        char timestamp[26];
        strftime(timestamp, sizeof(timestamp)-1, "%Y-%m-%d %H:%M:%S", t);

        // Log the pressure reading
        if (pressure >= 0) {
