#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>

// Constants
#define I2C_BUS 1
#define SDP800_ADDR 0x25
#define CONTINUOUS_MEASUREMENT_CMD 0x362F
#define DATA_LENGTH 9
#define PRESSURE_SCALE 60.0
#define TEMPERATURE_SCALE 200.0
#define LOG_FILE "pressure_log.txt"

// Global variables
int i2c_fd = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float pressure;
    float temperature;
} sensor_data_t;

// Function prototypes
int i2c_setup(int bus, int addr);
int i2c_write(int fd, uint8_t *data, int len);
int i2c_read(int fd, uint8_t *data, int len);
uint8_t crc8(const uint8_t *data, int len);
int read_sensor_data(int fd, sensor_data_t *data);
int validate_crc(uint16_t raw_value, uint8_t crc);
void log_data(sensor_data_t data);
void signal_handler(int sig);

// I2C setup function
int i2c_setup(int bus, int addr) {
    char filename[20];
    snprintf(filename, 19, "/dev/i2c-%d", bus);
    int fd = open(filename, O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C device");
        return -1;
    }
    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        perror("Error setting I2C slave address");
        close(fd);
        return -1;
    }
    return fd;
}

// I2C write function
int i2c_write(int fd, uint8_t *data, int len) {
    ssize_t bytes_written = write(fd, data, len);
    if (bytes_written != len) {
        perror("Error writing to I2C device");
        return -1;
    }
    return 0;
}

// I2C read function
int i2c_read(int fd, uint8_t *data, int len) {
    ssize_t bytes_read = read(fd, data, len);
    if (bytes_read != len) {
        perror("Error reading from I2C device");
        return -1;
    }
    return 0;
}

// CRC-8 calculation function
uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Read sensor data function
int read_sensor_data(int fd, sensor_data_t *data) {
    uint8_t buffer[DATA_LENGTH];
    if (i2c_read(fd, buffer, DATA_LENGTH) != 0) {
        return -1;
    }

    // Extract raw values and CRCs
    uint16_t raw_pressure = (buffer[0] << 8) | buffer[1];
    uint8_t crc_pressure = buffer[2];
    uint16_t raw_temperature = (buffer[3] << 8) | buffer[4];
    uint8_t crc_temperature = buffer[5];

    // Validate CRCs
    if (!validate_crc(raw_pressure, crc_pressure) || !validate_crc(raw_temperature, crc_temperature)) {
        fprintf(stderr, "CRC validation failed\n");
        return -1;
    }

    // Convert raw values to physical units
    data->pressure = (float)raw_pressure / PRESSURE_SCALE;
    data->temperature = (float)raw_temperature / TEMPERATURE_SCALE;

    return 0;
}

// CRC validation function
int validate_crc(uint16_t raw_value, uint8_t crc) {
    uint8_t data[2];
    data[0] = (raw_value >> 8) & 0xFF;
    data[1] = raw_value & 0xFF;
    return (crc8(data, 2) == crc);
}

// Log data function
void log_data(sensor_data_t data) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, data.pressure, data.temperature);
    fflush(log_file); // Ensure data is written to file immediately
}

// Signal handler function
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, exiting...\n");
    terminate = 1;
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    i2c_fd = i2c_setup(I2C_BUS, SDP800_ADDR);
    if (i2c_fd < 0) {
        return 1;
    }

    // Open log file
