    if (access(LOG_FILE, F_OK) == -1) {
        fprintf(fp, "Timestamp,Pressure (Pa)\n");
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s,%.2f\n", timestamp, pressure);
    fclose(fp);
    return 0;
}

