#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// Constants
#define I2C_BUS 1
#define MLX90821_ADDR 0x40
#define PRESSURE_REG 0x00
#define SCALE_FACTOR 0.01
#define SAFE_PRESSURE_MIN 200.0
#define SAFE_PRESSURE_MAX 250.0
#define LOG_FILE "pressure_log.csv"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int read_pressure();
float convert_to_kPa(int raw_pressure);
void log_pressure(float pressure);
void check_pressure_range(float pressure);
void signal_handler(int signal);
void cleanup();

// Structure for configuration (optional)
typedef struct {
    int i2c_bus;
    int i2c_address;
    float pressure_min;
    float pressure_max;
    char *log_filename;
} config_t;

config_t config = {
    I2C_BUS,
    MLX90821_ADDR,
    SAFE_PRESSURE_MIN,
    SAFE_PRESSURE_MAX,
    LOG_FILE
};

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(config.log_filename, "a+");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    // Check if the file is newly created and write the header
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "timestamp,pressure_kPa\n");
    }
    fseek(log_file, 0, SEEK_END); // Reset file pointer to the end

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        // Read pressure
        int raw_pressure = read_pressure();
        if (raw_pressure >= 0) {
            float pressure_kPa = convert_to_kPa(raw_pressure);

            // Log pressure
            log_pressure(pressure_kPa);

            // Check pressure range
            check_pressure_range(pressure_kPa);
        } else {
            fprintf(stderr, "Error reading pressure\n");
        }

        // Wait for 1 second
        gpioDelay(1000); // pigpio's replacement for time_sleep
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(config.i2c_bus, config.i2c_address, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Read pressure from the sensor
int read_pressure() {
    char buf[2];
    int result = i2cReadI2CBlockData(i2c_handle, PRESSURE_REG, buf, 2);

    if (result != 2) {
        fprintf(stderr, "Error reading pressure data: %s\n", strerror(errno));
        // Attempt to re-initialize I2C
        i2cClose(i2c_handle);
        if (init_i2c() != 0) {
            fprintf(stderr, "Failed to re-initialize I2C\n");
            return -1; // Indicate failure
        }
        result = i2cReadI2CBlockData(i2c_handle, PRESSURE_REG, buf, 2);
        if (result != 2) {
            fprintf(stderr, "Second attempt to read pressure data failed: %s\n", strerror(errno));
            return -1; // Indicate failure
        }
    }

    // Combine the two bytes into a 16-bit value
    int16_t raw_pressure = (buf[0] << 8) | buf[1];
    return raw_pressure;
}

// Convert raw pressure to kPa
float convert_to_kPa(int raw_pressure) {
    return (float)raw_pressure * config.scale_factor;
}

// Log pressure to file
void log_pressure(float pressure) {
    time_t now = time(NULL);
    struct tm *t = gmtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    fprintf(log_file, "%s,%.2f\n", timestamp, pressure);
    fflush(log_file); // Ensure data is written to disk
}

// Check pressure range and log warning if necessary
void check_pressure_range(float pressure) {
    if (pressure < config.pressure_min || pressure > config.pressure_max) {
        fprintf(stderr, "WARNING: Pressure out of range (%.2f kPa)\n", pressure);
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Received signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup resources
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fflush(log_file);
        fclose(log_file);
    }
    gpioTerminate();
}

