}

// Read pressure from the sensor
int read_pressure() {
    char buf[2];
    int result = i2cReadI2CBlockData(i2c_handle, PRESSURE_REG, buf, 2);

    if (result != 2) {
        fprintf(stderr, "Error reading pressure data: %s\n", strerror(errno));
        // Attempt to re-initialize I2C
        i2cClose(i2c_handle);
        if (init_i2c() != 0) {
            fprintf(stderr, "Failed to re-initialize I2C\n");
            return -1; // Indicate failure
        }
        result = i2cReadI2CBlockData(i2c_handle, PRESSURE_REG, buf, 2);
        if (result != 2) {
            fprintf(stderr, "Second attempt to read pressure data failed: %s\n", strerror(errno));
            return -1; // Indicate failure
        }
    }

    // Combine the two bytes into a 16-bit value
    int16_t raw_pressure = (buf[0] << 8) | buf[1];
    return raw_pressure;
}

// Convert raw pressure to kPa
float convert_to_kPa(int raw_pressure) {
    return (float)raw_pressure * config.scale_factor;
}

// Log pressure to file
void log_pressure(float pressure) {
    time_t now = time(NULL);
    struct tm *t = gmtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    fprintf(log_file, "%s,%.2f\n", timestamp, pressure);
    fflush(log_file); // Ensure data is written to disk
}

// Check pressure range and log warning if necessary
void check_pressure_range(float pressure) {
    if (pressure < config.pressure_min || pressure > config.pressure_max) {
        fprintf(stderr, "WARNING: Pressure out of range (%.2f kPa)\n", pressure);
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Received signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup resources
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fflush(log_file);
        fclose(log_file);
    }
    gpioTerminate();
}

