#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// Constants
#define I2C_BUS 1
#define HIH6130_ADDR 0x27
#define LOG_FILE "environmental_data.log"
#define LOG_FILE_SIZE_LIMIT 1048576 // 1 MB
#define SAMPLE_INTERVAL_SEC 5

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float temperature;
    float humidity;
} SensorData;

// Function prototypes
int init_i2c();
SensorData read_sensor_data();
void log_data(SensorData data);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, HIH6130_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read temperature and humidity data from the sensor
SensorData read_sensor_data() {
    SensorData data = {0.0, 0.0};
    unsigned char buf[4];
    int result;

    // Trigger measurement
    result = i2cWriteByte(i2c_handle, 0x00);
    if (result != 0) {
        fprintf(stderr, "Error writing to I2C device: %d\n", result);
        data.temperature = -999.0; // Indicate error
        data.humidity = -999.0;
        return data;
    }

    // Wait for measurement (at least 40 ms)
    gpioDelay(40000); // 40 ms

    // Read 4 bytes of data
    result = i2cReadDevice(i2c_handle, (char *)buf, 4);
    if (result != 4) {
        fprintf(stderr, "Error reading from I2C device: %d\n", result);
        data.temperature = -999.0; // Indicate error
        data.humidity = -999.0;
        return data;
    }

    // Check status bits (bits 6 and 7 of byte 0)
    int status = (buf[0] >> 6) & 0x03;
    if (status != 0) {
        fprintf(stderr, "Sensor status error: %d\n", status);
        data.temperature = -999.0; // Indicate error
        data.humidity = -999.0;
        return data;
    }

    // Convert raw data to temperature and humidity
    int raw_humidity = ((buf[0] & 0x3F) << 8) | buf[1];
    int raw_temperature = (buf[2] << 6) | (buf[3] >> 2);

    data.temperature = (raw_temperature * 165.0 / 16383.0) - 40.0;
    data.humidity = (raw_humidity * 100.0 / 16383.0);

    return data;
}

// Log data to file with ISO-8601 timestamp
void log_data(SensorData data) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return;
    }

    // Get current time
    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", tm);

    // Write data to file
    fprintf(fp, "%s,%.2f,%.2f\n", timestamp, data.temperature, data.humidity);

    // Check file size and truncate if necessary
    fseek(fp, 0, SEEK_END);
    long file_size = ftell(fp);
    if (file_size > LOG_FILE_SIZE_LIMIT) {
        fprintf(stderr, "Log file size limit reached. Truncating.\n");
        fclose(fp);
        fp = fopen(LOG_FILE, "w"); // Open in write mode to truncate
        if (fp == NULL) {
            fprintf(stderr, "Error opening log file for truncation: %s\n", strerror(errno));
            return;
        }
    }

    fclose(fp);
}

// Cleanup resources before exiting
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Starting data logging...\n");

    // Main loop
    while (!terminate) {
        SensorData data = read_sensor_data();

        if (data.temperature != -999.0) {
            log_data(data);
            printf("Temperature: %.2f C, Humidity: %.2f %%\n", data.temperature, data.humidity);
        } else {
            fprintf(stderr, "Error reading sensor data. Skipping logging.\n");
        }

        gpioDelay(SAMPLE_INTERVAL_SEC * 1000000); // Wait 5 seconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

