#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define GPIO_PIN 4
#define TICK_TIME 3 // us
#define MIN_PULSE_WIDTH 12 // ticks
#define MAX_PULSE_WIDTH 271 // ticks
#define TIMEOUT_US 100000 // us
#define NUM_NIBBLES 4

// Calibration parameters (example values)
#define SCALE 10.0
#define OFFSET 0.0

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;

// Structure to hold SENT data
typedef struct {
    unsigned int status;
    unsigned int data[3];
    unsigned int checksum;
} SENTData;

// Function prototypes
void signal_handler(int signal);
int init_gpio();
int read_sent_data(SENTData *data);
int validate_sent_data(const SENTData *data);
float convert_to_pressure(const SENTData *data);
int log_pressure(float pressure);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    fprintf(stderr, "\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize GPIO
int init_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(GPIO_PIN, PI_INPUT);
    return 0;
}

// Read SENT data from the sensor
int read_sent_data(SENTData *data) {
    int i, j;
    unsigned int pulse_width;
    unsigned int start_tick, end_tick;

    // Synchronization pulse
    start_tick = gpioTick();
    while (gpioRead(GPIO_PIN) == 0) {
        if (gpioTick() - start_tick > TIMEOUT_US) {
            fprintf(stderr, "Timeout waiting for synchronization pulse\n");
            return -1;
        }
    }
    end_tick = gpioTick();
    pulse_width = end_tick - start_tick;
    if (pulse_width < 56 * TICK_TIME || pulse_width > 56 * TICK_TIME) {
        fprintf(stderr, "Invalid synchronization pulse width: %d ticks\n", pulse_width);
        return -1;
    }

    // Read status nibble
    start_tick = gpioTick();
    while (gpioRead(GPIO_PIN) == 1) {
        if (gpioTick() - start_tick > TIMEOUT_US) {
            fprintf(stderr, "Timeout waiting for status nibble end\n");
            return -1;
        }
    }
    end_tick = gpioTick();
    pulse_width = end_tick - start_tick;
    if (pulse_width < MIN_PULSE_WIDTH || pulse_width > MAX_PULSE_WIDTH) {
        fprintf(stderr, "Invalid status nibble pulse width: %d ticks\n", pulse_width);
        return -1;
    }
    data->status = 0;
    for (i = 0; i < 4; i++) {
        start_tick = gpioTick();
        while (gpioRead(GPIO_PIN) == 0) {
            if (gpioTick() - start_tick > TIMEOUT_US) {
                fprintf(stderr, "Timeout waiting for status nibble start\n");
                return -1;
            }
        }
        end_tick = gpioTick();
        pulse_width = end_tick - start_tick;
        if (pulse_width < MIN_PULSE_WIDTH || pulse_width > MAX_PULSE_WIDTH) {
            fprintf(stderr, "Invalid status nibble pulse width: %d ticks\n", pulse_width);
            return -1;
        }
        data->status = (data->status << 1) | 1;
    }

    // Read data nibbles
    for (j = 0; j < NUM_NIBBLES; j++) {
        start_tick = gpioTick();
        while (gpioRead(GPIO_PIN) == 1) {
            if (gpioTick() - start_tick > TIMEOUT_US) {
                fprintf(stderr, "Timeout waiting for data nibble end\n");
                return -1;
            }
        }
        end_tick = gpioTick();
        pulse_width = end_tick - start_tick;
        if (pulse_width < MIN_PULSE_WIDTH || pulse_width > MAX_PULSE_WIDTH) {
            fprintf(stderr, "Invalid data nibble pulse width: %d ticks\n", pulse_width);
            return -1;
        }
        data->data[j] = 0;
        for (i = 0; i < 4; i++) {
            start_tick = gpioTick();
            while (gpioRead(GPIO_PIN) == 0) {
                if (gpioTick() - start_tick > TIMEOUT_US) {
                    fprintf(stderr, "Timeout waiting for data nibble start\n");
                    return -1;
                }
            }
            end_tick = gpioTick();
            pulse_width = end_tick - start_tick;
            if (pulse_width < MIN_PULSE_WIDTH || pulse_width > MAX_PULSE_WIDTH) {
                fprintf(stderr, "Invalid data nibble pulse width: %d ticks\n", pulse_width);
                return -1;
            }
            data->data[j] = (data->data[j] << 1) | 1;
        }
    }

    // Read checksum nibble
    start_tick = gpioTick();
    while (gpioRead(GPIO_PIN) == 1) {
        if (gpioTick() - start_tick > TIMEOUT_US) {
            fprintf(stderr, "Timeout waiting for checksum nibble end\n");
            return -1;
        }
    }
    end_tick = gpioTick();
    pulse_width = end_tick - start_tick;
    if (pulse_width < MIN_PULSE_WIDTH || pulse_width > MAX_PULSE_WIDTH) {
        fprintf(stderr, "Invalid checksum nibble pulse width: %d ticks\n", pulse_width);
        return -1;
    }
    data->checksum = 0;
    for (i = 0; i < 4; i++) {
        start_tick = gpioTick();
        while (gpioRead(GPIO_PIN) == 0) {
            if (gpioTick() - start_tick > TIMEOUT_US) {
                fprintf(stderr, "Timeout waiting for checksum nibble start\n");
                return -1;
            }
        }
        end_tick = gpioTick();
        pulse_width = end_tick - start_tick;
        if (pulse_width < MIN_PULSE_WIDTH || pulse_width > MAX_PULSE_WIDTH) {
            fprintf(stderr, "Invalid checksum nibble pulse width: %d ticks\n", pulse_width);
            return -1;
        }
        data->checksum = (data->checksum << 1) | 1;
    }

    return 0;
}

// Validate SENT data
int validate_sent_data(const SENTData *data) {
    unsigned int checksum = 0;
    for (int i = 0; i < NUM_NIBBLES; i++) {
        checksum += data->data[i];
    }
    checksum = checksum & 0xF; // Keep only the lower 4 bits

    if (checksum != (data->checksum & 0xF)) {
        fprintf(stderr, "Checksum mismatch: calculated 0x%X, received 0x%X\n", checksum, data->checksum & 0xF);
        return -1;
    }

    return 0;
}

// Convert raw data to pressure
float convert_to_pressure(const SENTData *data) {
    unsigned int raw_value = 0;
    for (int i = 0; i < NUM_NIBBLES; i++) {
        raw_value = (raw_value << 4) | (data->data[i] & 0xF);
    }
    return (float)raw_value * SCALE + OFFSET;
}

// Log pressure reading to file
int log_pressure(float pressure) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s, Pressure: %.2f Pa\n", timestamp, pressure);
        fflush(log_file); // Ensure data is written to disk immediately
        return 0;
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
        return -1;
    }
}

int main() {
    SENTData sent_data;
    float pressure;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (init_gpio() != 0) {
        return 1;
    }

    // Open log file
    log_file = fopen("pressure_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (running) {
        if (read_sent_data(&sent_data) == 0) {
            if (validate_sent_data(&sent_data) == 0) {
                pressure = convert_to_pressure(&sent_data);
                if (log_pressure(pressure) != 0) {
                    fprintf(stderr, "Error logging pressure.\n");
                }
            } else {
                fprintf(stderr, "Invalid SENT data received.\n");
            }
        } else {
            fprintf(stderr, "Error reading SENT data.\n");
        }

        gpioDelay(100); // Delay for 100 ms
    }

    // Clean up
    fclose(log_file);
    gpioTerminate();

    return 0;
}

