#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>

// Constants
#define I2C_BUS 1
#define TMP117_ADDR 0x48
#define TEMP_REG 0x00
#define DEVICE_ID_REG 0x00
#define DEVICE_ID_VALUE 0x117
#define SLEEP_SECONDS 60

// Global variables
int i2c_handle;
FILE *fp;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int verify_sensor();
float read_temperature();
int write_temperature_to_file(float temperature);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, TMP117_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Verify the sensor's device ID
int verify_sensor() {
    int device_id = i2cReadWordData(i2c_handle, DEVICE_ID_REG);
    if (device_id < 0) {
        fprintf(stderr, "Error reading device ID: %d\n", device_id);
        return -1;
    }

    if ((device_id >> 8) != (DEVICE_ID_VALUE >> 8)) {
        fprintf(stderr, "Error: Incorrect device ID (0x%04X, expected 0x%04X)\n", device_id, DEVICE_ID_VALUE);
        return -1;
    }

    printf("Sensor verification successful.\n");
    return 0;
}

// Read the temperature from the sensor
float read_temperature() {
    int16_t raw_temp = i2cReadWordData(i2c_handle, TEMP_REG);
    if (raw_temp < 0) {
        fprintf(stderr, "Error reading temperature: %d\n", raw_temp);
        return -1000.0; // Indicate an error with a very low temperature
    }

    // Convert raw temperature to Celsius
    float temperature = (float)raw_temp * 0.0078125;
    return temperature;
}

// Write the temperature to the file
int write_temperature_to_file(float temperature) {
    float temp_f = temperature * 9.0 / 5.0 + 32.0;
    float temp_c = temperature;
    float temp_k = temperature + 273.15;

    if (fwrite(&temp_f, sizeof(float), 1, fp) != 1) {
        fprintf(stderr, "Error writing Fahrenheit to file: %s\n", strerror(errno));
        return -1;
    }
    if (fwrite(&temp_c, sizeof(float), 1, fp) != 1) {
        fprintf(stderr, "Error writing Celsius to file: %s\n", strerror(errno));
        return -1;
    }
    if (fwrite(&temp_k, sizeof(float), 1, fp) != 1) {
        fprintf(stderr, "Error writing Kelvin to file: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Verify the sensor
    if (verify_sensor() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open the file for writing
    fp = fopen("greenhouse_temps.dat", "wb");
    if (fp == NULL) {
        fprintf(stderr, "Error opening file: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (!terminate) {
        float temperature = read_temperature();
        if (temperature > -999.0) { // Check for read error
            if (write_temperature_to_file(temperature) != 0) {
                fprintf(stderr, "Error writing temperature to file.\n");
            }
        } else {
            fprintf(stderr, "Error reading temperature, skipping write.\n");
        }

        sleep(SLEEP_SECONDS);
    }

    // Clean up
    fclose(fp);
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

