#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Constants
#define I2C_BUS 1
#define SHT40_ADDR 0x44
#define MEASURE_HIGH_PRECISION 0xFD
#define LOG_FILE "environmental_data.txt"

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float temperature;
    float humidity;
} SensorData;

// Function prototypes
int initialize_pigpio();
int open_i2c_bus(int bus, int addr);
int write_i2c_command(int handle, uint8_t command);
int read_i2c_data(int handle, char *data, int count);
int calculate_crc(const char *data, int len);
int validate_crc(uint8_t data, uint8_t crc);
SensorData read_sht40_data(int handle);
void log_data(float temperature, float humidity);
void signal_handler(int signal);

// Function to initialize pigpio
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Function to open the I2C bus
int open_i2c_bus(int bus, int addr) {
    int handle = i2cOpen(bus, addr, 0);
    if (handle < 0) {
        fprintf(stderr, "Failed to open I2C bus: %d\n", handle);
        return -1;
    }
    return handle;
}

// Function to write a command to the I2C bus
int write_i2c_command(int handle, uint8_t command) {
    char buf[1] = {command};
    int result = i2cWriteDevice(handle, buf, 1);
    if (result != 0) {
        fprintf(stderr, "Failed to write to I2C bus: %d\n", result);
        return -1;
    }
    return 0;
}

// Function to read data from the I2C bus
int read_i2c_data(int handle, char *data, int count) {
    int result = i2cReadDevice(handle, data, count);
    if (result != count) {
        fprintf(stderr, "Failed to read from I2C bus: %d\n", result);
        return -1;
    }
    return 0;
}

// Function to calculate CRC-8 checksum
int calculate_crc(const char *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Function to validate CRC-8 checksum
int validate_crc(uint8_t data, uint8_t crc) {
    return calculate_crc((char *)&data, 1) == crc;
}

// Function to read data from the SHT40 sensor
SensorData read_sht40_data(int handle) {
    SensorData data;
    char raw_data[6];

    if (write_i2c_command(handle, MEASURE_HIGH_PRECISION) != 0) {
        data.temperature = -999.0; // Indicate error
        data.humidity = -999.0;
        return data;
    }

    gpioDelay(10000); // Wait 10 ms

    if (read_i2c_data(handle, raw_data, 6) != 0) {
        data.temperature = -999.0; // Indicate error
        data.humidity = -999.0;
        return data;
    }

    // Validate CRC for temperature
    if (!validate_crc(raw_data[0], raw_data[1])) {
        fprintf(stderr, "Temperature CRC check failed\n");
        data.temperature = -999.0; // Indicate error
        data.humidity = -999.0;
        return data;
    }

    // Validate CRC for humidity
    if (!validate_crc(raw_data[3], raw_data[4])) {
        fprintf(stderr, "Humidity CRC check failed\n");
        data.temperature = -999.0; // Indicate error
        data.humidity = -999.0;
        return data;
    }

    // Convert raw data to temperature and humidity
    uint16_t raw_temp = (raw_data[0] << 8) | raw_data[1];
    uint16_t raw_hum = (raw_data[3] << 8) | raw_data[4];

    data.temperature = -45.0 + 175.0 * (raw_temp / 65535.0);
    data.humidity = -6.0 + 125.0 * (raw_hum / 65535.0);

    return data;
}

// Function to log data to a file
void log_data(float temperature, float humidity) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        return;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s, Temperature: %.2f °C, Humidity: %.2f %%\n", timestamp, temperature, humidity);
    fflush(fp);
    fclose(fp);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Received signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Register signal handler
    signal(SIGINT, signal_handler);

    // Initialize pigpio
    if (initialize_pigpio() != 0) {
        return 1;
    }

    // Open I2C bus
    i2c_handle = open_i2c_bus(I2C_BUS, SHT40_ADDR);
    if (i2c_handle < 0) {
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (!terminate) {
        SensorData sensor_data = read_sht40_data(i2c_handle);

        if (sensor_data.temperature != -999.0 && sensor_data.humidity != -999.0) {
            log_data(sensor_data.temperature, sensor_data.humidity);
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }

        gpioDelay(5000000); // Wait 5 seconds
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

