int write_buffer_to_file(const CircularBuffer *cb) {
    FILE *fp = fopen("temperature_log.dat", "wb");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open file for writing\n");
        return -1;
    }

    size_t elements_to_write = (cb->count < BUFFER_SIZE) ? cb->count : BUFFER_SIZE;
    fwrite(cb->buffer, sizeof(float), elements_to_write, fp);

    fclose(fp);
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Cleanup resources before exiting
void cleanup() {
    i2cClose(i2c_handle);
    gpioTerminate();
}

