    // Initialize signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (init_pigpio() != 0) {
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Initialize circular buffer
    CircularBuffer cb = {{0.0}, 0, 0};

    // Main loop
    while (!terminate) {
        float temperature = read_temperature();

        if (temperature > -999.0) { // Check for read error
            printf("Temperature: %.2f °C\n", temperature);
            add_to_buffer(&cb, temperature);
            write_buffer_to_file(&cb);
        } else {
            fprintf(stderr, "Failed to read temperature, skipping sample.\n");
        }

        sleep(SAMPLE_INTERVAL_SEC);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

