#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// Constants
#define I2C_BUS 1
#define SI7202_ADDR 0x40
#define MAG_REG 0x00
#define TEMP_REG 0x01
#define LOG_FILE "mag_temp_log.csv"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float magnetic_field;
    float temperature;
} sensor_data_t;

// Function prototypes
int initialize_i2c();
int read_sensor_data(int handle, int *raw_magnetic, int *raw_temperature);
sensor_data_t convert_sensor_data(int raw_magnetic, int raw_temperature);
int log_data(FILE *fp, float magnetic_field, float temperature);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initializes the I2C bus
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SI7202_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Reads raw magnetic field and temperature data from the sensor
int read_sensor_data(int handle, int *raw_magnetic, int *raw_temperature) {
    char buf[2];
    int result;

    // Read magnetic field
    result = i2cReadI2CBlockData(handle, MAG_REG, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading magnetic field data: %d\n", result);
        return -1;
    }
    *raw_magnetic = (buf[0] << 8) | buf[1];

    // Read temperature
    result = i2cReadI2CBlockData(handle, TEMP_REG, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading temperature data: %d\n", result);
        return -1;
    }
    *raw_temperature = (buf[0] << 8) | buf[1];

    return 0;
}

// Converts raw sensor data to magnetic field (Gauss) and temperature (Celsius)
sensor_data_t convert_sensor_data(int raw_magnetic, int raw_temperature) {
    sensor_data_t data;
    data.magnetic_field = (float)raw_magnetic * 0.1;
    data.temperature = (float)raw_temperature * 0.01 - 25.0;
    return data;
}

// Logs the magnetic field and temperature data to a CSV file
int log_data(FILE *fp, float magnetic_field, float temperature) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    if (fp == NULL) {
        fprintf(stderr, "Error: Log file is not open.\n");
        return -1;
    }

    if (fprintf(fp, "%s,%.2f,%.2f\n", timestamp, magnetic_field, temperature) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        return -1;
    }

    fflush(fp); // Ensure data is written to disk
    return 0;
}

int main() {
    int raw_magnetic, raw_temperature;
    sensor_data_t sensor_data;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handling for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize I2C
    if (initialize_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Open the log file in append mode
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Check if the file is newly created and write the header if needed
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Magnetic Field (Gauss),Temperature (Celsius)\n");
        fflush(log_file);
    }
    fseek(log_file, 0, SEEK_END); // Reset file pointer to the end

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_sensor_data(i2c_handle, &raw_magnetic, &raw_temperature) == 0) {
            // Convert sensor data
            sensor_data = convert_sensor_data(raw_magnetic, raw_temperature);

            // Log data
            if (log_data(log_file, sensor_data.magnetic_field, sensor_data.temperature) != 0) {
                fprintf(stderr, "Error logging data.\n");
            }
        } else {
            // Log NaN values if sensor read fails
            if (log_data(log_file, NAN, NAN) != 0) {
                fprintf(stderr, "Error logging NaN data.\n");
            }
        }

        // Wait for 1 second
        gpioDelay(1000); // pigpio's delay function
    }

    // Cleanup
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

