        return -1000.0f; // Indicate error with a very low temperature
    }

    // Combine the two bytes into a 16-bit signed integer
    int16_t raw_temp = (buf[0] << 8) | buf[1];

    // Convert to float using the scale factor
    float temperature = (float)raw_temp * TEMP_SCALE;

    return temperature;
}

