        if (temperature > -999.0f) { // Check for read error
            log_temperature(temperature);
        } else {
            fprintf(stderr, "Failed to read temperature. Re-initializing I2C...\n");
            i2cClose(i2c_handle);
            if (initialize_i2c() != 0) {
                fprintf(stderr, "Failed to re-initialize I2C. Exiting.\n");
                break; // Exit loop if re-initialization fails
            }
            reinit_count++;
            if (reinit_count > MAX_REINIT) {
                fprintf(stderr, "Max re-initialization attempts reached. Exiting.\n");
                break;
            }
        }

        gpioDelay(1000); // Wait 1 second
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

