// Constants
#define I2C_BUS 1
#define I2C_ADDRESS 0x49
#define LOG_FILE "flow_log.txt"
#define SAMPLE_INTERVAL_SEC 1

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float flow_rate;
    float temperature;
} SensorData;

// Function prototypes
int initialize_i2c();
SensorData read_sensor_data();
float convert_flow_rate(uint16_t raw_flow);
float convert_temperature(uint16_t raw_temp);
void log_data(SensorData data);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Initialize I2C communication
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read sensor data from the I2C device
SensorData read_sensor_data() {
    SensorData data;
    char buffer[4];
    int bytes_read = i2cReadDevice(i2c_handle, buffer, 4);

    if (bytes_read != 4) {
        fprintf(stderr, "Error reading from I2C device: %d\n", bytes_read);
        data.flow_rate = -1.0; // Indicate error
        data.temperature = -100.0; // Indicate error
        return data;
    }

    // Combine bytes to form 14-bit flow and 12-bit temperature values
    uint16_t raw_flow = ((uint16_t)buffer[0] << 8) | buffer[1];
    uint16_t raw_temp = ((uint16_t)buffer[2] << 8) | buffer[3];

    // Convert raw values to SLPM and Celsius
    data.flow_rate = convert_flow_rate(raw_flow);
    data.temperature = convert_temperature(raw_temp);

    return data;
}

// Convert raw flow rate to SLPM
float convert_flow_rate(uint16_t raw_flow) {
    return ((raw_flow / 16384.0) - 0.1) / 0.8 * 25.0;
}

// Convert raw temperature to Celsius
float convert_temperature(uint16_t raw_temp) {
    return ((raw_temp / 4096.0) - 0.1) / 0.8 * 80.0 - 40.0;
}

// Log data to file
void log_data(SensorData data) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s, %.2f SLPM, %.2f °C\n", timestamp, data.flow_rate, data.temperature);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Cleanup resources before exiting
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handling for Ctrl+C and termination signals
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Initialize I2C
    if (initialize_i2c() != 0) {
        fprintf(stderr, "I2C initialization failed. Exiting.\n");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    printf("Starting airflow monitoring...\n");

    // Main loop
    while (!terminate) {
        SensorData data = read_sensor_data();

        if (data.flow_rate != -1.0 && data.temperature != -100.0) {
            log_data(data);
        } else {
            fprintf(stderr, "Error reading sensor data. Attempting to re-initialize I2C.\n");
            fprintf(log_file, "Error reading sensor data. Attempting to re-initialize I2C.\n");
            fclose(log_file);
            i2cClose(i2c_handle);
            if (initialize_i2c() != 0) {
                fprintf(stderr, "I2C re-initialization failed. Exiting.\n");
                terminate = 1; // Exit loop if re-initialization fails
            } else {
                log_file = fopen(LOG_FILE, "a");
                if (log_file == NULL) {
                    fprintf(stderr, "Error opening log file!\n");
                    terminate = 1;
                }
            }
        }

        gpioDelay(SAMPLE_INTERVAL_SEC * 1000); // Delay for 1 second
    }

    // Cleanup and exit
    cleanup();
    printf("Exiting.\n");
    return 0;
}

