#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define DHT11_GPIO 4
#define MAX_RETRIES 3
#define TIMEOUT_US 200

// Structure to hold sensor data
typedef struct {
    int humidity;
    int temperature;
    int status;
} sensor_data_t;

// Global variables
FILE *error_log_file = NULL;
FILE *readings_log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_gpio();
int read_dht11_data(sensor_data_t *data);
int validate_checksum(unsigned char *data);
int log_error(const char *message, int status_code);
int log_reading(int humidity, int temperature);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

// Initialize GPIO using pigpio
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(DHT11_GPIO, PI_OUTPUT);
    gpioWrite(DHT11_GPIO, 1); // Set high initially
    return 0;
}

// Read data from DHT11 sensor
int read_dht11_data(sensor_data_t *data) {
    int retries = 0;
    unsigned char raw_data[5] = {0};

    while (retries < MAX_RETRIES) {
        // Send start signal
        gpioSetMode(DHT11_GPIO, PI_OUTPUT);
        gpioWrite(DHT11_GPIO, 0);
        gpioDelay(18000); // 18 ms
        gpioWrite(DHT11_GPIO, 1);
        gpioDelay(40); // 40 us

        // Switch to input mode and measure response
        gpioSetMode(DHT11_GPIO, PI_INPUT);
        gpioDelay(80); // Wait for response

        if (gpioRead(DHT11_GPIO) == 0) {
            gpioDelay(80); // Wait for end of response

            // Read 40 bits of data
            for (int i = 0; i < 40; i++) {
                gpioDelay(50); // Wait for start of bit
                int pulse_len = 0;
                while (gpioRead(DHT11_GPIO) == 0) {
                    pulse_len++;
                    gpioDelay(1); // Delay 1 us
                    if (pulse_len > TIMEOUT_US) {
                        log_error("Timeout waiting for bit start", -2);
                        goto retry;
                    }
                }

                pulse_len = 0;
                while (gpioRead(DHT11_GPIO) == 1) {
                    pulse_len++;
                    gpioDelay(1); // Delay 1 us
                    if (pulse_len > TIMEOUT_US) {
                        log_error("Timeout waiting for bit end", -3);
                        goto retry;
                    }
                }

                raw_data[i / 8] <<= 1;
                if (pulse_len > 30) {
                    raw_data[i / 8] |= 1;
                }
            }

            // Validate checksum
            if (validate_checksum(raw_data)) {
                data->humidity = raw_data[0];
                data->temperature = raw_data[2];
                data->status = 0; // Success
                return 0;
            } else {
                log_error("Checksum validation failed", -4);
            }

        retry:
            retries++;
            gpioDelay(2000000); // Wait 2 seconds before retrying
        } else {
            log_error("No response from sensor", -1);
            retries++;
            gpioDelay(2000000); // Wait 2 seconds before retrying
        }
    }

    log_error("Failed to read DHT11 after multiple retries", -5);
    return -1;
}

// Validate checksum
int validate_checksum(unsigned char *data) {
    return (data[0] + data[1] + data[2] + data[3]) == data[4];
}

// Log errors to file
int log_error(const char *message, int status_code) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    fprintf(error_log_file, "%s - %s - Status Code: %d\n", timestamp, message, status_code);
    fflush(error_log_file);
    return 0;
}

// Log readings to file
int log_reading(int humidity, int temperature) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    fprintf(readings_log_file, "%s - Humidity: %d%%, Temperature: %d°C\n", timestamp, humidity, temperature);
    fflush(readings_log_file);
    return 0;
}

// Cleanup resources before exiting
void cleanup() {
    printf("Cleaning up...\n");
    if (error_log_file != NULL) {
        fclose(error_log_file);
    }
    if (readings_log_file != NULL) {
        fclose(readings_log_file);
    }
    gpioTerminate();
}

int main() {
    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open log files
    error_log_file = fopen("dht11_errors.log", "a");
    if (error_log_file == NULL) {
        perror("Error opening error log file");
        return 1;
    }

    readings_log_file = fopen("dht11_readings.txt", "a");
    if (readings_log_file == NULL) {
        perror("Error opening readings log file");
