#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define SHT31_ADDR 0x44
#define MEASUREMENT_COMMAND 0x2C06
#define LOG_FILE "sht31d_data.log"

// Structure to hold sensor data
typedef struct {
    float temperature;
    float humidity;
} SensorData;

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// CRC-8 calculation function
uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Function to read sensor data
int read_sensor_data(SensorData *data) {
    uint8_t write_data[2] = {(MEASUREMENT_COMMAND >> 8) & 0xFF, MEASUREMENT_COMMAND & 0xFF};
    uint8_t read_data[6];
    int retries = 3;

    while (retries > 0) {
        if (i2cWriteDevice(i2c_handle, (char *)write_data, 2) == 2) {
            gpioDelay(15000); // Wait 15 ms
            if (i2cReadDevice(i2c_handle, (char *)read_data, 6) == 6) {
                // Validate CRC for temperature
                if (crc8(read_data, 2) != read_data[2]) {
                    fprintf(stderr, "Error: Temperature CRC check failed\n");
                    return -1;
                }

                // Validate CRC for humidity
                if (crc8(read_data + 3, 2) != read_data[5]) {
                    fprintf(stderr, "Error: Humidity CRC check failed\n");
                    return -1;
                }

                // Convert raw data to temperature and humidity
                uint16_t raw_temperature = (read_data[0] << 8) | read_data[1];
                uint16_t raw_humidity = (read_data[3] << 8) | read_data[4];

                data->temperature = -45.0 + 175.0 * raw_temperature / 65535.0;
                data->humidity = 100.0 * raw_humidity / 65535.0;

                return 0; // Success
            } else {
                fprintf(stderr, "Error: I2C read failed (retries remaining: %d)\n", retries);
                gpioDelay(1000000); // Wait 1 second before retrying
            }
        } else {
            fprintf(stderr, "Error: I2C write failed (retries remaining: %d)\n", retries);
            gpioDelay(1000000); // Wait 1 second before retrying
        }
        retries--;
    }

    fprintf(stderr, "Error: Persistent I2C communication failure\n");
    return -1; // Failure after retries
}

// Function to log sensor data
void log_sensor_data(const SensorData *data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, data->temperature, data->humidity);
    fflush(log_file); // Ensure data is written to file immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, SHT31_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: I2C open failed\n");
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    SensorData sensor_data;

    // Main loop
    while (!terminate) {
        if (read_sensor_data(&sensor_data) == 0) {
            log_sensor_data(&sensor_data);
        } else {
            fprintf(stderr, "Error: Failed to read sensor data\n");
        }

        sleep(5);
    }

    // Cleanup
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

