// Function to initialize the sensor
int initialize_sensor(int i2c_handle) {
    int device_id;

    // Read device ID register
    device_id = i2cReadByteData(i2c_handle, DEVICE_ID_REG);
    if (device_id < 0) {
        fprintf(stderr, "Error reading device ID: %s\n", strerror(errno));
        return -1;
    }

    // Verify device ID
    if (device_id != 0x2A) {
        fprintf(stderr, "Error: Invalid device ID 0x%02X (expected 0x2A)\n", device_id);
        return -1;
    }

    return 0;
}

// Function to read sensor data
int read_sensor_data(int i2c_handle, uint16_t *red, uint16_t *green, uint16_t *blue) {
    char buf[6];
    int bytes_read;

    // Read red, green, and blue registers (6 bytes total)
    bytes_read = i2cReadI2CBlockData(i2c_handle, RED_REG, buf, 6);
    if (bytes_read != 6) {
        fprintf(stderr, "Error reading sensor data: %s\n", strerror(errno));
        return -1;
    }

    // Combine bytes to form 16-bit little-endian values
    *red = (uint16_t)((buf[1] << 8) | buf[0]);
    *green = (uint16_t)((buf[3] << 8) | buf[2]);
    *blue = (uint16_t)((buf[5] << 8) | buf[4]);

    return 0;
}

// Function to calculate CCT using McCamy's formula
float calculate_cct(uint16_t red, uint16_t green, uint16_t blue) {
    float x, y, cct;

    // Normalize RGB values (example normalization, adjust as needed)
    float r = (float)red / 65535.0f;
    float g = (float)green / 65535.0f;
    float b = (float)blue / 65535.0f;

    // Calculate x and y coordinates
    x = (r * 0.34172 + g * 0.65828 + b * 0.00000) / (r * 0.25000 + g * 0.64000 + b * 0.11000);
    y = (r * 0.21265 + g * 0.71516 + b * 0.07219) / (r * 0.17850 + g * 0.81200 + b * 0.00950);

    // Calculate CCT using McCamy's formula
    cct = (449.0 * pow(y - 0.33, 3.0)) + (3525.0 * pow(y - 0.33, 2.0)) + (6823.3 * (y - 0.33)) + 5520.33;

    return cct;
}

// Function to calculate the average CCT
float average_cct(float cct1, float cct2) {
    return (cct1 + cct2) / 2.0f;
}

// Function to log CCT data to a CSV file
int log_cct_data(float average_cct) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    // Get current time
    time(&rawtime);
    timeinfo = localtime(&rawtime);

    // Format timestamp
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    // Open log file in append mode
    log_file = fopen("cct_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return -1;
    }

    // Write header if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Average_CCT\n");
    }

    // Write data to log file
    fprintf(log_file, "%s,%.2f\n", timestamp, average_cct);

    // Close log file
    fclose(log_file);

    return 0;
}

int main() {
    uint16_t red1, green1, blue1;
    uint16_t red2, green2, blue2;
    float cct1, cct2, average_cct;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus for sensor 1
    i2c_handle1 = i2cOpen(I2C_BUS, SENSOR1_ADDR, 0);
    if (i2c_handle1 < 0) {
        fprintf(stderr, "Error opening I2C bus for sensor 1: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Open I2C bus for sensor 2
    i2c_handle2 = i2cOpen(I2C_BUS, SENSOR2_ADDR, 0);
    if (i2c_handle2 < 0) {
        fprintf(stderr, "Error opening I2C bus for sensor 2: %s\n", strerror(errno));
        i2cClose(i2c_handle1);
        gpioTerminate();
        return 1;
    }

    // Initialize sensors
    if (initialize_sensor(i2c_handle1) != 0) {
        fprintf(stderr, "Error initializing sensor 1\n");
        i2cClose(i2c_handle1);
        i2cClose(i2c_handle2);
        gpioTerminate();
        return 1;
    }

    if (initialize_sensor(i2c_handle2) != 0) {
        fprintf(stderr, "Error initializing sensor 2\n");
        i2cClose(i2c_handle1);
        i2cClose(i2c_handle2);
        gpioTerminate();
        return 1;
    }

    // Set up signal handling for Ctrl+C
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (1) {
        // Read sensor data
        if (read_sensor_data(i2c_handle1, &red1, &green1, &blue1) == 0 &&
            read_sensor_data(i2c_handle2, &red2, &green2, &blue2) == 0) {

            // Calculate CCT
            cct1 = calculate_cct(red1, green1, blue1);
            cct2 = calculate_cct(red2, green2, blue2);

            // Calculate average CCT
            average_cct = average_cct(cct1, cct2);

            // Log CCT data
            if (log_cct_data(average_cct) != 0) {
                fprintf(stderr, "Error logging CCT data\n");
            }
        } else {
            fprintf(stderr, "Error reading sensor data, skipping log entry\n");
        }

        // Wait for 1 second
        gpioDelay(1000); // pigpio's replacement for time_sleep
    }

    return 0;
}

