#define PRESSURE_REG 0x0A2C
#define TEMPERATURE_REG 0x0A2E
#define P_MIN 0.0
#define P_MAX 800.0
#define T_MIN -40.0
#define T_MAX 125.0
#define RAW_MIN 0
#define RAW_MAX 32768

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure for sensor data
typedef struct {
    float pressure_kPa;
    float temperature_C;
} sensor_data_t;

// Function prototypes
int initialize_i2c();
int read_raw_data(uint16_t *pressure, uint16_t *temperature);
sensor_data_t process_data(uint16_t raw_pressure, uint16_t raw_temperature);
int log_data(sensor_data_t data);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Initializes the I2C bus
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, MLX90824_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Reads raw pressure and temperature data from the sensor
int read_raw_data(uint16_t *pressure, uint16_t *temperature) {
    char buf[4];
    int result;

    // Read pressure and temperature registers (0x0A2C and 0x0A2E)
    result = i2cReadI2CBlockData(i2c_handle, PRESSURE_REG, buf, 4);
    if (result != 4) {
        fprintf(stderr, "Error reading I2C data: %d\n", result);
        return -1;
    }

    // Combine bytes to form 16-bit values (big-endian)
    *pressure = (uint16_t)((buf[0] << 8) | buf[1]);
    *temperature = (uint16_t)((buf[2] << 8) | buf[3]);

    return 0;
}

// Converts raw data to kPa and Celsius
sensor_data_t process_data(uint16_t raw_pressure, uint16_t raw_temperature) {
    sensor_data_t data;

    // Convert pressure to kPa
    data.pressure_kPa = ((float)raw_pressure - RAW_MIN) * (P_MAX - P_MIN) / (RAW_MAX - RAW_MIN);

    // Convert temperature to Celsius
    data.temperature_C = (float)raw_temperature * 0.01 - T_MIN;

    return data;
}

