    timeinfo = gmtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    fprintf(log_file, "%s, Pressure: %.2f kPa, Temperature: %.2f C\n", timestamp, data.pressure_kPa, data.temperature_C);
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handling for Ctrl+C and SIGTERM
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (initialize_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("pressure_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    uint16_t raw_pressure, raw_temperature;
    sensor_data_t sensor_data;

    // Main loop
    while (!terminate) {
        // Read raw data
        if (read_raw_data(&raw_pressure, &raw_temperature) == 0) {
            // Process data
            sensor_data = process_data(raw_pressure, raw_temperature);

            // Log data
            if (log_data(sensor_data) != 0) {
                fprintf(stderr, "Error logging data!\n");
            }
        } else {
            fprintf(stderr, "Error reading sensor data!\n");
        }

        // Wait 2 seconds
        gpioDelay(2000); // pigpio's delay function
    }

    // Clean up
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

