#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define LM75B_ADDR 0x48
#define TEMP_REG 0x00
#define FAN_GPIO 18
#define AVG_TEMP_HIGH 28.0
#define AVG_TEMP_LOW 26.0
#define BUFFER_SIZE 60

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Circular buffer
float temperature_buffer[BUFFER_SIZE];
int buffer_index = 0;

// Function prototypes
float read_temperature();
float calculate_average();
void control_fan(float average_temperature);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating gracefully...\n", signal);
}

// Function to read temperature from LM75B
float read_temperature() {
    char buf[2];
    int result;

    result = i2cReadDevice(i2c_handle, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading temperature: %d\n", result);
        return -1000.0; // Indicate error
    }

    // Combine the two bytes into a 16-bit integer
    int16_t raw_temp = (buf[0] << 8) | buf[1];

    // Extract the 9-bit temperature value (bits D9-D1)
    int16_t temp_value = raw_temp >> 7;

    // Convert to Celsius (0.5 °C resolution)
    float temperature = temp_value * 0.5;

    return temperature;
}

// Function to calculate the running average
float calculate_average() {
    float sum = 0.0;
    for (int i = 0; i < BUFFER_SIZE; i++) {
        sum += temperature_buffer[i];
    }
    return sum / BUFFER_SIZE;
}

// Function to control the cooling fan
void control_fan(float average_temperature) {
    static int fan_on = 0; // Track fan state

    if (average_temperature > AVG_TEMP_HIGH && !fan_on) {
        gpioWrite(FAN_GPIO, 1); // Turn fan on
        fan_on = 1;
        fprintf(stderr, "Turning fan ON (Avg Temp: %.2f)\n", average_temperature);
    } else if (average_temperature < AVG_TEMP_LOW && fan_on) {
        gpioWrite(FAN_GPIO, 0); // Turn fan off
        fan_on = 0;
        fprintf(stderr, "Turning fan OFF (Avg Temp: %.2f)\n", average_temperature);
    }
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, LM75B_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO 18 as output
    gpioSetMode(FAN_GPIO, PI_OUTPUT);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        // Read temperature
        float temperature = read_temperature();
        if (temperature < -900) {
            fprintf(stderr, "Error reading temperature, skipping this iteration.\n");
            sleep(1);
            continue;
        }

        // Store temperature in circular buffer
        temperature_buffer[buffer_index] = temperature;
        buffer_index = (buffer_index + 1) % BUFFER_SIZE;

        // Calculate running average
        float average_temperature = calculate_average();

        // Control fan
        control_fan(average_temperature);

        // Print temperature and average
        printf("Temperature: %.2f °C, Average: %.2f °C\n", temperature, average_temperature);

        // Wait for 1 second
        sleep(1);
    }

    // Cleanup
    gpioWrite(FAN_GPIO, 0); // Turn fan off
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

