// Constants
#define I2C_BUS 1
#define SDP810_ADDR 0x25
#define CONTINUOUS_MEASUREMENT_CMD 0x362F
#define PRESSURE_SCALE_FACTOR 60.0
#define TEMPERATURE_SCALE_FACTOR 200.0
#define PRESSURE_THRESHOLD 5.0
#define LOG_FILE "airflow.log"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float pressure;
    float temperature;
    uint16_t status;
} sensor_data_t;

// Function prototypes
int init_i2c();
int send_command(int handle, uint16_t command);
int read_sensor_data(int handle, int16_t *pressure, int16_t *temperature, uint16_t *status);
uint8_t calculate_crc(const uint8_t *data, size_t len);
int validate_crc(const uint8_t *data, size_t len, uint8_t crc);
int convert_data(int16_t raw_pressure, int16_t raw_temperature, sensor_data_t *data);
int log_data(FILE *fp, sensor_data_t data);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating...\n", signal);
}

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SDP810_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Send a command to the sensor
int send_command(int handle, uint16_t command) {
