#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>
#include <signal.h>
#include <errno.h>
#include <string.h>

// Constants
#define I2C_BUS "/dev/i2c-1"
#define STTS2004_ADDR 0x4A
#define TEMP_REG 0x00
#define LED_CHIP "gpiochip0"
#define LED_LINE 17
#define TEMP_THRESHOLD_HIGH 28.0
#define TEMP_THRESHOLD_LOW 27.0
#define HYSTERESIS_BAND (TEMP_THRESHOLD_HIGH - TEMP_THRESHOLD_LOW)
#define MAX_I2C_RETRIES 3

// Global variables
static int i2c_fd = -1;
static struct gpiod_chip *gpio_chip = NULL;
static struct gpiod_line *gpio_line = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int i2c_read_word(int fd, uint8_t reg, uint16_t *value);
float convert_to_celsius(uint16_t raw_temp);
int set_led_state(struct gpiod_line *line, int state);
void signal_handler(int sig);

// I2C read function with retry mechanism
int i2c_read_word(int fd, uint8_t reg, uint16_t *value) {
    int retries = 0;
    uint8_t buf[2];

    while (retries < MAX_I2C_RETRIES) {
        if (write(fd, &reg, 1) != 1) {
            fprintf(stderr, "Error writing to I2C device: %s\n", strerror(errno));
            retries++;
            usleep(10000); // Wait 10ms before retrying
            continue;
        }

        if (read(fd, buf, 2) != 2) {
            fprintf(stderr, "Error reading from I2C device: %s\n", strerror(errno));
            retries++;
            usleep(10000); // Wait 10ms before retrying
            continue;
        }

        *value = (buf[0] << 8) | buf[1];
        return 0; // Success
    }

    fprintf(stderr, "Failed to read from I2C device after %d retries.\n", MAX_I2C_RETRIES);
    return -1; // Failure
}

// Temperature conversion function
float convert_to_celsius(uint16_t raw_temp) {
    return (float)raw_temp * 0.0625;
}

// LED control function
int set_led_state(struct gpiod_line *line, int state) {
    int ret = gpiod_line_set_value(line, state);
    if (ret < 0) {
        fprintf(stderr, "Error setting LED state: %s\n", strerror(-ret));
        return -1;
    }
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, exiting gracefully...\n");
    terminate = 1;
}

int main() {
    uint16_t raw_temp;
    float temperature;
    int led_state = 0; // 0 = off, 1 = on

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C device
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C device: %s\n", strerror(errno));
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, STTS2004_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    // Open GPIO chip
    gpio_chip = gpiod_chip_open_by_name(LED_CHIP);
    if (!gpio_chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    // Get GPIO line
    gpio_line = gpiod_chip_get_line(gpio_chip, LED_LINE);
    if (!gpio_line) {
        fprintf(stderr, "Error getting GPIO line: %s\n", strerror(errno));
        gpiod_chip_close(gpio_chip);
        close(i2c_fd);
        return 1;
    }

    // Request GPIO line for output
    if (gpiod_line_request_output(gpio_line, "temp_monitor", 0) < 0) {
        fprintf(stderr, "Error requesting GPIO line for output: %s\n", strerror(errno));
        gpiod_chip_close(gpio_chip);
        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Read temperature from sensor
        if (i2c_read_word(i2c_fd, TEMP_REG, &raw_temp) == 0) {
            // Convert temperature to Celsius
            temperature = convert_to_celsius(raw_temp);

            // Log temperature
            printf("Temperature: %.2f °C\n", temperature);

            // Control LED based on temperature and hysteresis
            if (temperature > TEMP_THRESHOLD_HIGH && led_state == 0) {
                if (set_led_state(gpio_line, 1) == 0) {
                    led_state = 1;
                }
            } else if (temperature < TEMP_THRESHOLD_LOW && led_state == 1) {
                if (set_led_state(gpio_line, 0) == 0) {
                    led_state = 0;
                }
            }
        } else {
            fprintf(stderr, "Error reading temperature, skipping LED control.\n");
        }

        sleep(1); // Wait 1 second
    }

    // Cleanup
    printf("Cleaning up...\n");
    if (gpio_line) {
        gpiod_line_release(gpio_line);
    }
    if (gpio_chip) {
        gpiod_chip_close(gpio_chip);
    }
    if (i2c_fd != -1) {
        close(i2c_fd);
    }

    return 0;
}

