#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define SI7021_ADDR 0x40
#define MEASURE_RH 0xF5
#define MEASURE_TEMP 0xF3
#define READ_TEMP_PREV 0xE0

// Global variables for signal handling
static volatile int running = 1;
static int i2c_handle = -1;
static FILE *log_file = NULL;

// Function prototypes
int init_i2c();
int read_sensor_data(float *temperature, float *humidity);
float convert_temperature(uint16_t raw_temp);
float convert_humidity(uint16_t raw_humidity);
int validate_sensor();
void log_data(float temperature, float humidity);
void signal_handler(int signal);
void cleanup();

// Structure to hold sensor data
typedef struct {
    float temperature;
    float humidity;
} sensor_data_t;

int main() {
    sensor_data_t sensor_data;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        fprintf(stderr, "I2C initialisation failed\n");
        gpioTerminate();
        return 1;
    }

    // Validate sensor
    if (validate_sensor() != 0) {
        fprintf(stderr, "Sensor validation failed\n");
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen("environment.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        cleanup();
        return 1;
    }

    // Main loop
    while (running) {
        // Read sensor data
        if (read_sensor_data(&sensor_data.temperature, &sensor_data.humidity) == 0) {
            // Log data
            log_data(sensor_data.temperature, sensor_data.humidity);
        } else {
            fprintf(stderr, "Error reading sensor data\n");
        }

        // Wait 60 seconds
        sleep(60);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SI7021_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        return 1;
    }
    return 0;
}

// Read sensor data
int read_sensor_data(float *temperature, float *humidity) {
    uint8_t buf[2];
    uint16_t raw_temp, raw_humidity;
    int result;

    // Measure Relative Humidity
    result = i2cWriteByte(i2c_handle, MEASURE_RH);
    if (result != 0) {
        fprintf(stderr, "Error writing to I2C device (RH): %d\n", result);
        return 1;
    }
    gpioDelay(20); // Wait 20ms

    // Read Humidity
    result = i2cReadDevice(i2c_handle, (char *)buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading from I2C device (RH): %d\n", result);
        return 1;
    }
    raw_humidity = (buf[0] << 8) | buf[1];
    *humidity = convert_humidity(raw_humidity);

    // Measure Temperature
    result = i2cWriteByte(i2c_handle, MEASURE_TEMP);
    if (result != 0) {
        fprintf(stderr, "Error writing to I2C device (Temp): %d\n", result);
        return 1;
    }
    gpioDelay(20); // Wait 20ms

    // Read Temperature
    result = i2cReadDevice(i2c_handle, (char *)buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading from I2C device (Temp): %d\n", result);
        return 1;
    }
    raw_temp = (buf[0] << 8) | buf[1];
    *temperature = convert_temperature(raw_temp);

    return 0;
}

// Convert raw temperature to Celsius
float convert_temperature(uint16_t raw_temp) {
    return 175.72 * raw_temp / 65536.0 - 46.85;
}

// Convert raw humidity to percentage
float convert_humidity(uint16_t raw_humidity) {
    float humidity = 125.0 * raw_humidity / 65536.0 - 6.0;
    if (humidity < 0.0) humidity = 0.0;
    if (humidity > 100.0) humidity = 100.0;
    return humidity;
}

// Validate sensor
int validate_sensor() {
    uint8_t buf[2];
    int result;
    uint16_t firmware_revision;

    // Read Firmware Revision
    result = i2cWriteByte(i2c_handle, 0xE1);
    if (result != 0) {
        fprintf(stderr, "Error writing to I2C device (Firmware): %d\n", result);
        return 1;
    }
    gpioDelay(20); // Wait 20ms

    result = i2cReadDevice(i2c_handle, (char *)buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading from I2C device (Firmware): %d\n", result);
        return 1;
    }
    firmware_revision = (buf[0] << 8) | buf[1];

    if (firmware_revision != 0x0000) {
        fprintf(stderr, "Sensor validation failed: Firmware revision = 0x%04X\n", firmware_revision);
        return 1;
    }

    return 0;
}

// Log data to file and stdout
void log_data(float temperature, float humidity) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, temperature, humidity);
    fflush(log_file);
    printf("%s,%.2f,%.2f\n", timestamp, temperature, humidity);
}

// Signal handler
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting...\n", signal);
}

// Cleanup function
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

