#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <stdint.h>

#define I2C_ADDR 0x44
#define I2C_DEVICE "/dev/i2c-1"
#define MEASUREMENT_COMMAND_1 0x2C
#define MEASUREMENT_COMMAND_2 0xE0
#define LOG_FILE "temperature_log.txt"

volatile sig_atomic_t program_running = 1;
int i2c_fd = -1;
FILE *log_file = NULL;

void signal_handler(int signal) {
    program_running = 0;
    fprintf(stderr, "\nCaught signal %d, exiting gracefully.\n", signal);
}

int init_i2c() {
    i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C device: %s\n", I2C_DEVICE);
        return -1;
    }
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address: 0x%02X\n", I2C_ADDR);
        close(i2c_fd);
        i2c_fd = -1;
        return -1;
    }
    return 0;
}

int read_temperature(float *temperature) {
    unsigned char command[2] = {MEASUREMENT_COMMAND_1, MEASUREMENT_COMMAND_2};
    unsigned char data[3];
    int16_t raw_ticks;
    uint8_t crc;

    if (write(i2c_fd, command, 2) != 2) {
        fprintf(stderr, "Error writing measurement command to I2C device.\n");
        return -1;
    }

    usleep(10000); // Wait for conversion (10 ms)

    if (read(i2c_fd, data, 3) != 3) {
        fprintf(stderr, "Error reading temperature data from I2C device.\n");
        return -1;
    }

    raw_ticks = (data[0] << 8) | data[1];
    crc = data[2];

    if (crc8(data, 2) != crc) {
        fprintf(stderr, "CRC check failed!\n");
        return -1;
    }

    *temperature = -45.0 + 175.0 * (float)raw_ticks / 65535.0;
    return 0;
}

uint8_t crc8(const unsigned char *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

int log_temperature(float temperature) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        return -1;
    }

    fprintf(log_file, "%s, %.2f\n", timestamp, temperature);
    fclose(log_file);
    return 0;
}

int main() {
    float temperature;

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    if (init_i2c() != 0) {
        return 1;
    }

    while (program_running) {
        if (read_temperature(&temperature) == 0) {
            if (log_temperature(temperature) != 0) {
                fprintf(stderr, "Error logging temperature.\n");
            }
        } else {
            fprintf(stderr, "Error reading temperature.\n");
        }

        sleep(5);
    }

    if (i2c_fd != -1) {
        close(i2c_fd);
    }

    return 0;
}

