#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Constants
#define I2C_BUS 1
#define I2C_ADDRESS 0x25
#define SAMPLE_RATE_HZ 1
#define SAMPLE_PERIOD_US (1000000 / SAMPLE_RATE_HZ)
#define CRC_POLYNOMIAL 0x31
#define CRC_INITIAL_VALUE 0xFF

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float pressure;
    float temperature;
} SensorData;

// Function prototypes
int initialize();
SensorData read_sensor_data();
float calculate_crc(const uint8_t *data, int len);
void log_data(SensorData data);
void log_error(const char *message);
void signal_handler(int signal);

// CRC-8 calculation function
float calculate_crc(const uint8_t *data, int len) {
    uint8_t crc = CRC_INITIAL_VALUE;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Initialization function
int initialize() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("hvac_pressure_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    return 0;
}

// Function to read sensor data
SensorData read_sensor_data() {
    SensorData data = {0.0, 0.0};
    uint8_t buffer[9];
    int result;

    // Send continuous measurement command
    result = i2cWriteWordData(i2c_handle, 0x00, 0x3615);
    if (result < 0) {
        log_error("Failed to write continuous measurement command");
        return data; // Return default values on error
    }

    // Wait for at least 50 ms
    gpioDelay(50000); // 50 ms

    // Read 9 bytes of data
    result = i2cReadI2CBlockData(i2c_handle, 0x00, (char *)buffer, 9);
    if (result < 0) {
        log_error("Failed to read sensor data");
        return data; // Return default values on error
    }

    // Validate CRC for pressure
    uint8_t pressure_data[2] = {buffer[0], buffer[1]};
    uint8_t pressure_crc = buffer[2];
    if ((uint8_t)calculate_crc(pressure_data, 2) != pressure_crc) {
        log_error("Pressure CRC check failed");
        return data; // Return default values on error
    }

    // Validate CRC for temperature
    uint8_t temperature_data[2] = {buffer[3], buffer[4]};
    uint8_t temperature_crc = buffer[5];
    if ((uint8_t)calculate_crc(temperature_data, 2) != temperature_crc) {
        log_error("Temperature CRC check failed");
        return data; // Return default values on error
    }

    // Convert raw data to pressure and temperature
    int16_t raw_pressure = (buffer[0] << 8) | buffer[1];
    int16_t raw_temperature = (buffer[3] << 8) | buffer[4];

    data.pressure = (float)raw_pressure / ((uint16_t)buffer[6] << 8 | (uint16_t)buffer[7]);
    data.temperature = (float)raw_temperature / 200.0;

    return data;
}

// Function to log data to file
void log_data(SensorData data) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, data.pressure, data.temperature);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Function to log errors to file
void log_error(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s,ERROR,%s\n", timestamp, message);
    fflush(log_file);
    fprintf(stderr, "%s,ERROR,%s\n", timestamp, message);
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    terminate = 1;
    printf("Ctrl+C pressed, exiting...\n");
}

int main() {
    if (initialize()) {
        return 1;
    }

    printf("HVAC Pressure Monitoring started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        SensorData data = read_sensor_data();
        log_data(data);
        gpioDelay(SAMPLE_PERIOD_US); // Sample every 1 second
    }

    // Cleanup
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

