    if (result < 0) {
        log_error("Failed to write continuous measurement command");
        return data; // Return default values on error
    }

    // Wait for at least 50 ms
    gpioDelay(50000); // 50 ms

    // Read 9 bytes of data
    result = i2cReadI2CBlockData(i2c_handle, 0x00, (char *)buffer, 9);
    if (result < 0) {
        log_error("Failed to read sensor data");
        return data; // Return default values on error
    }

    // Validate CRC for pressure
    uint8_t pressure_data[2] = {buffer[0], buffer[1]};
    uint8_t pressure_crc = buffer[2];
    if ((uint8_t)calculate_crc(pressure_data, 2) != pressure_crc) {
        log_error("Pressure CRC check failed");
        return data; // Return default values on error
    }

    // Validate CRC for temperature
    uint8_t temperature_data[2] = {buffer[3], buffer[4]};
    uint8_t temperature_crc = buffer[5];
    if ((uint8_t)calculate_crc(temperature_data, 2) != temperature_crc) {
        log_error("Temperature CRC check failed");
        return data; // Return default values on error
    }

    // Convert raw data to pressure and temperature
    int16_t raw_pressure = (buffer[0] << 8) | buffer[1];
    int16_t raw_temperature = (buffer[3] << 8) | buffer[4];

    data.pressure = (float)raw_pressure / ((uint16_t)buffer[6] << 8 | (uint16_t)buffer[7]);
    data.temperature = (float)raw_temperature / 200.0;

    return data;
}

// Function to log data to file
void log_data(SensorData data) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, data.pressure, data.temperature);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Function to log errors to file
void log_error(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s,ERROR,%s\n", timestamp, message);
    fflush(log_file);
    fprintf(stderr, "%s,ERROR,%s\n", timestamp, message);
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    terminate = 1;
    printf("Ctrl+C pressed, exiting...\n");
}

int main() {
    if (initialize()) {
        return 1;
    }

    printf("HVAC Pressure Monitoring started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        SensorData data = read_sensor_data();
        log_data(data);
        gpioDelay(SAMPLE_PERIOD_US); // Sample every 1 second
    }

    // Cleanup
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

