#include <errno.h>

// SCD40 I2C address
#define SCD40_ADDR 0x62

// SCD40 commands
#define CMD_START_PERIODIC_MEASUREMENT 0x21B1
#define CMD_STOP_PERIODIC_MEASUREMENT 0x3F86
#define CMD_READ_MEASUREMENT 0xE000

// SCD40 data structure
typedef struct {
    uint16_t co2;
    uint16_t temperature;
    uint16_t humidity;
} SCD40Data;

// Circular buffer structure
typedef struct {
    time_t timestamp;
    SCD40Data data;
} Reading;

typedef struct {
    Reading buffer[100];
    int head;
    int tail;
    int count;
    pthread_mutex_t mutex;
} CircularBuffer;

// Global variables
int i2c_handle;
volatile sig_atomic_t running = 1;
CircularBuffer data_buffer;

// Function prototypes
int initialize_pigpio();
int initialize_i2c();
int send_command(uint16_t command);
int read_data(SCD40Data *data);
int validate_crc(uint8_t data[], int len);
SCD40Data convert_data(uint8_t data[]);
void add_reading(CircularBuffer *buffer, time_t timestamp, SCD40Data data);
void *logging_thread(void *arg);
void signal_handler(int signal);
void cleanup();

// Helper function to get current timestamp
time_t get_timestamp() {
    return time(NULL);
}

// Initialize pigpio
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Initialize I2C
int initialize_i2c() {
    i2c_handle = i2cOpen(1, SCD40_ADDR, 0); // Bus 1, address 0x62, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Send command to SCD40
int send_command(uint16_t command) {
    char buf[2];
    buf[0] = (command >> 8) & 0xFF;
    buf[1] = command & 0xFF;

    int result = i2cWriteDevice(i2c_handle, buf, 2);
    if (result != 0) {
        fprintf(stderr, "Failed to write to I2C device: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Read data from SCD40
int read_data(SCD40Data *data) {
    char buf[9];
    int result = i2cReadDevice(i2c_handle, buf, 9);
    if (result != 9) {
        fprintf(stderr, "Failed to read from I2C device: %s\n", strerror(errno));
        return -1;
    }

    if (validate_crc(buf, 2) != 0 || validate_crc(buf + 2, 2) != 0 || validate_crc(buf + 4, 2) != 0) {
        fprintf(stderr, "CRC validation failed\n");
        return -1;
    }

    data->co2 = (uint16_t)((buf[0] << 8) | buf[1]);
    data->temperature = (uint16_t)((buf[2] << 8) | buf[3]);
    data->humidity = (uint16_t)((buf[4] << 8) | buf[5]);

    return 0;
}

// Validate CRC-8 checksum
int validate_crc(uint8_t data[], int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return (crc != data[len]);
}

// Convert raw data to CO2, temperature, and humidity
SCD40Data convert_data(uint8_t data[]) {
    SCD40Data converted_data;
    converted_data.co2 = (uint16_t)((data[0] << 8) | data[1]);
    converted_data.temperature = -45 + (175.0 * (uint16_t)((data[2] << 8) | data[3])) / 65535.0;
    converted_data.humidity = (100.0 * (uint16_t)((data[4] << 8) | data[5])) / 65535.0;
    return converted_data;
}

// Add reading to circular buffer
void add_reading(CircularBuffer *buffer, time_t timestamp, SCD40Data data) {
    pthread_mutex_lock(&buffer->mutex);
    buffer->buffer[buffer->head] = (Reading){timestamp, data};
    buffer->head = (buffer->head + 1) % 100;
    if (buffer->count < 100) {
        buffer->count++;
    } else {
        buffer->tail = (buffer->tail + 1) % 100;
    }
    pthread_mutex_unlock(&buffer->mutex);
}

// Logging thread function
void *logging_thread(void *arg) {
    while (running) {
        sleep(60);

        pthread_mutex_lock(&data_buffer.mutex);
        FILE *fp = fopen("/var/log/scd40_data/scd40_data.csv", "w");
        if (fp == NULL) {
            fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
            pthread_mutex_unlock(&data_buffer.mutex);
            continue;
        }

        fprintf(fp, "Timestamp,CO2 (ppm),Temperature (C),Humidity (%%)\n");
        int i = data_buffer.tail;
        for (int j = 0; j < data_buffer.count; j++) {
            fprintf(fp, "%ld,%d,%.2f,%.2f\n", data_buffer.buffer[i].timestamp, data_buffer.buffer[i].data.co2, data_buffer.buffer[i].data.temperature, data_buffer.buffer[i].data.humidity);
            i = (i + 1) % 100;
        }
        fclose(fp);
        pthread_mutex_unlock(&data_buffer.mutex);
    }
    pthread_exit(NULL);
}

// Signal handler
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("Received SIGINT, stopping...\n");
        running = 0;
    }
}

// Cleanup function
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        send_command(CMD_STOP_PERIODIC_MEASUREMENT);
        i2cClose(i2c_handle);
    }
    gpioTerminate();
}

int main() {
    // Initialize signal handler
    signal(SIGINT, signal_handler);

    // Initialize pigpio
    if (initialize_pigpio() != 0) {
        return 1;
    }

    // Initialize I2C
    if (initialize_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Initialize circular buffer
    data_buffer.head = 0;
    data_buffer.tail = 0;
    data_buffer.count = 0;
    pthread_mutex_init(&data_buffer.mutex, NULL);

    // Create logging thread
    pthread_t logging_thread_id;
    if (pthread_create(&logging_thread_id, NULL, logging_thread, NULL) != 0) {
        fprintf(stderr, "Failed to create logging thread: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    // Start periodic measurement
    if (send_command(CMD_START_PERIODIC_MEASUREMENT) != 0) {
        cleanup();
        return 1;
    }
    gpioDelay(1000); // Wait 1 second

    // Main loop
    while (running) {
        SCD40Data data;
        if (read_data(&data) == 0) {
            add_reading(&data_buffer, get_timestamp(), data);
            printf("CO2: %d ppm, Temperature: %.2f C, Humidity: %.2f %%\n", data.co2, data.temperature, data.humidity);
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }
        sleep(5);
    }

    // Cleanup
    pthread_join(logging_thread_id, NULL);
    pthread_mutex_destroy(&data_buffer.mutex);
    cleanup();

    return 0;
}

