#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Constants
#define I2C_BUS 1
#define I2C_ADDRESS 0x25
#define CONTINUOUS_MEASUREMENT_COMMAND 0x362F
#define LOG_FILE "sdp810_log.txt"
#define SLEEP_DURATION_US 1000000 // 1 second

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float pressure_Pa;
    float temperature_C;
} sensor_data_t;

// Function prototypes
int initialize_i2c();
int send_command(int handle, uint16_t command);
int read_sensor_data(int handle, int16_t *pressure, int16_t *temperature, int16_t *scale_factor);
uint8_t calculate_crc(const uint8_t *data, int len);
int validate_crc(const uint8_t *data, int len, uint8_t crc);
float convert_pressure(int16_t raw_pressure, int16_t scale_factor);
float convert_temperature(int16_t raw_temperature);
int log_data(FILE *fp, float pressure_Pa, float temperature_C);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Initializes the I2C bus
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Sends a command to the SDP810 sensor
int send_command(int handle, uint16_t command) {
    char buf[2];
    buf[0] = (command >> 8) & 0xFF;
    buf[1] = command & 0xFF;
    int result = i2cWriteDevice(handle, buf, 2);
    if (result != 0) {
        fprintf(stderr, "Error writing to I2C device: %d\n", result);
        return -1;
    }
    return 0;
}

// Reads sensor data from the SDP810 sensor
int read_sensor_data(int handle, int16_t *pressure, int16_t *temperature, int16_t *scale_factor) {
    char buf[9];
    int result = i2cReadDevice(handle, buf, 9);
    if (result != 9) {
        fprintf(stderr, "Error reading from I2C device: %d\n", result);
        return -1;
    }

    *pressure = (int16_t)((buf[0] << 8) | buf[1]);
    *temperature = (int16_t)((buf[3] << 8) | buf[4]);
    *scale_factor = (int16_t)((buf[6] << 8) | buf[7]);

    return 0;
}

// Calculates the CRC-8 checksum
uint8_t calculate_crc(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Validates the CRC-8 checksum
int validate_crc(const uint8_t *data, int len, uint8_t crc) {
    uint8_t calculated_crc = calculate_crc(data, len);
    return (calculated_crc == crc);
}

// Converts raw pressure data to Pascals
float convert_pressure(int16_t raw_pressure, int16_t scale_factor) {
    return (float)raw_pressure * scale_factor / 1000.0;
}

// Converts raw temperature data to Celsius
float convert_temperature(int16_t raw_temperature) {
    return -45.0 + 175.0 * (float)raw_temperature / 65535.0;
}

// Logs the sensor data to a file
int log_data(FILE *fp, float pressure_Pa, float temperature_C) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "%s,%.2f,%.2f\n", timestamp, pressure_Pa, temperature_C);
    fflush(fp); // Ensure data is written to disk immediately
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (initialize_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handler for graceful shutdown
    signal(SIGINT, signal_handler);

    // Send continuous measurement command
    if (send_command(i2c_handle, CONTINUOUS_MEASUREMENT_COMMAND) != 0) {
        fprintf(stderr, "Failed to send continuous measurement command.\n");
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (!terminate) {
        int16_t raw_pressure, raw_temperature, raw_scale_factor;

        // Read sensor data
        if (read_sensor_data(i2c_handle, &raw_pressure, &raw_temperature, &raw_scale_factor) == 0) {
            // Validate CRC for pressure data
            uint8_t pressure_data[2] = {(raw_pressure >> 8) & 0xFF, raw_pressure & 0xFF};
            if (!validate_crc(pressure_data, 2, buf[2])) {
                fprintf(stderr, "CRC validation failed for pressure data!\n");
            } else {
                // Validate CRC for temperature data
                uint8_t temperature_data[2] = {(raw_temperature >> 8) & 0xFF, raw_temperature & 0xFF};
                if (!validate_crc(temperature_data, 2, buf[5])) {
                    fprintf(stderr, "CRC validation failed for temperature data!\n");
                } else {
                    // Validate CRC for scale factor data
                    uint8_t scale_factor_data[2] = {(raw_scale_factor >> 8) & 0xFF, raw_scale_factor & 0xFF};
