// Function prototypes
int read_raw_temperature(int reg);
float convert_to_celsius(int raw_temp);
void log_temperature(float ambient_temp, float object_temp);
void control_fan(float object_temp);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to read raw temperature data from the sensor
int read_raw_temperature(int reg) {
    int raw_temp = -1;
    int retries = 3;
    int delay_ms = 10;

    while (retries > 0) {
        raw_temp = i2cReadWordData(i2c_handle, reg);
        if (raw_temp >= 0) {
            return raw_temp;
        } else {
            fprintf(stderr, "Error reading register 0x%02X: %d. Retrying...\n", reg, raw_temp);
            gpioDelay(delay_ms * 1000); // Convert ms to microseconds
            delay_ms *= 2; // Exponential backoff
            retries--;
        }
    }

    fprintf(stderr, "Failed to read register 0x%02X after multiple retries.\n", reg);
    return -1; // Indicate failure
}

// Function to convert raw temperature data to Celsius
float convert_to_celsius(int raw_temp) {
    return raw_temp * 0.02 - 273.15;
}

// Function to log temperature data to a file
void log_temperature(float ambient_temp, float object_temp) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        return;
    }

    fprintf(fp, "%s, Ambient: %.2f C, Object: %.2f C\n", timestamp, ambient_temp, object_temp);
    fclose(fp);
}

// Function to control the cooling fan based on temperature
void control_fan(float object_temp) {
    static int fan_on = 0; // Track fan state

    if (object_temp > OBJECT_THRESHOLD && !fan_on) {
        gpioWrite(FAN_GPIO, 1); // Turn fan on
        fan_on = 1;
        printf("Turning fan ON (Object Temp: %.2f C)\n", object_temp);
    } else if (object_temp < AMBIENT_THRESHOLD && fan_on) {
        gpioWrite(FAN_GPIO, 0); // Turn fan off
        fan_on = 0;
        printf("Turning fan OFF (Object Temp: %.2f C)\n", object_temp);
    }
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, MLX90614_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO 18 as output for fan control
    gpioSetMode(FAN_GPIO, PI_OUTPUT);
    gpioWrite(FAN_GPIO, 0); // Ensure fan is initially off

    // Set up signal handling for Ctrl+C
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Temperature monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        // Read raw temperature data
        int raw_ambient_temp = read_raw_temperature(AMBIENT_TEMP_REG);
        int raw_object_temp = read_raw_temperature(OBJECT_TEMP_REG);

        // Convert to Celsius
        float ambient_temp = convert_to_celsius(raw_ambient_temp);
        float object_temp = convert_to_celsius(raw_object_temp);

        // Validate readings
        if (raw_ambient_temp >= 0 && raw_object_temp >= 0) {
            // Log temperature data
            log_temperature(ambient_temp, object_temp);

            // Control the fan
            control_fan(object_temp);

            printf("Ambient: %.2f C, Object: %.2f C\n", ambient_temp, object_temp);
        } else {
            fprintf(stderr, "Invalid temperature readings. Skipping log entry.\n");
        }

        // Wait 2 seconds
        gpioDelay(2000000); // 2 seconds in microseconds
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioWrite(FAN_GPIO, 0); // Turn off fan
    gpioTerminate();

    printf("Exiting.\n");
    return 0;
}

