#include <netinet/in.h>
#include <arpa/inet.h>
#include <pigpio.h>

#define I2C_BUS 1
#define SHT40_ADDR 0x44
#define MEASUREMENT_COMMAND 0xFD
#define PORT 8080
#define BUFFER_SIZE 1024

// Global variables for graceful shutdown
int i2c_handle = -1;
int server_fd = -1;

// Structure to hold sensor data
typedef struct {
    float temperature;
    float humidity;
} SensorData;

// Function prototypes
int read_sht40(int i2c_handle, float *temperature, float *humidity);
int process_sensor_data(float temperature, float humidity);
int create_html_response(float temperature, float humidity, char *html_buffer, size_t buffer_size);
void handle_client(int client_socket);
void signal_handler(int signal);

// Function to read data from SHT40 sensor
int read_sht40(int i2c_handle, float *temperature, float *humidity) {
    unsigned char buffer[6];
    int result;
    unsigned short raw_temperature, raw_humidity;

    // Send measurement command
    result = i2cWriteByte(i2c_handle, MEASUREMENT_COMMAND);
    if (result != 0) {
        fprintf(stderr, "Error writing to I2C device: %d\n", result);
        return -1;
    }

    // Wait for measurement (at least 10 ms)
    gpioDelay(10000); // 10 ms

    // Read 6 bytes of data
    result = i2cReadDevice(i2c_handle, (char *)buffer, 6);
    if (result != 6) {
        fprintf(stderr, "Error reading from I2C device: %d\n", result);
        return -1;
    }

    // Convert raw data to temperature and humidity
    raw_temperature = (buffer[0] << 8) | buffer[1];
    raw_humidity = (buffer[3] << 8) | buffer[4];

    *temperature = -45.0 + 175.0 * (raw_temperature / 65535.0);
    *humidity = -6.0 + 125.0 * (raw_humidity / 65535.0);

    // Clamp humidity to 0-100%
    if (*humidity < 0.0) *humidity = 0.0;
    if (*humidity > 100.0) *humidity = 100.0;

    return 0;
}

// Function to process sensor data (currently just returns the data)
int process_sensor_data(float temperature, float humidity) {
    // In a real application, you might perform additional processing here
    // such as filtering or calibration.
    return 0; // Indicate success
}

// Function to create an HTML response
int create_html_response(float temperature, float humidity, char *html_buffer, size_t buffer_size) {
    int result = snprintf(html_buffer, buffer_size, 
                         "HTTP/1.1 200 OK\r\n" 
                         "Content-Type: text/html\r\n" 
                         "\r\n" 
                         "<!DOCTYPE html><html><head><title>SHT40 Data</title></head><body>" 
                         "<h1>Temperature: %.2f °C</h1>" 
                         "<h1>Humidity: %.2f %%</h1>" 
                         "</body></html>", 
                         temperature, humidity);

    if (result < 0 || result >= buffer_size) {
        fprintf(stderr, "Error creating HTML response\n");
        return -1;
    }

    return 0;
}

// Function to handle a client connection
void handle_client(int client_socket) {
    char buffer[BUFFER_SIZE];
    ssize_t bytes_received;
    float temperature, humidity;
    char html_response[BUFFER_SIZE];

    // Read the request from the client
    bytes_received = recv(client_socket, buffer, BUFFER_SIZE - 1, 0);
    if (bytes_received < 0) {
        perror("Error receiving data from client");
        close(client_socket);
        return;
    }
    buffer[bytes_received] = '\0';

    // Read sensor data
    if (read_sht40(i2c_handle, &temperature, &humidity) == 0) {
        if (process_sensor_data(temperature, humidity) == 0) {
            // Create HTML response
            if (create_html_response(temperature, humidity, html_response, BUFFER_SIZE) == 0) {
                // Send the response to the client
                if (send(client_socket, html_response, strlen(html_response), 0) < 0) {
                    perror("Error sending data to client");
                }
            } else {
                fprintf(stderr, "Error creating HTML response\n");
            }
        } else {
            fprintf(stderr, "Error processing sensor data\n");
        }
    } else {
        fprintf(stderr, "Error reading sensor data\n");
    }

    // Close the client socket
    close(client_socket);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);

    // Close I2C connection
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }

    // Close server socket
    if (server_fd >= 0) {
        close(server_fd);
    }

    // Terminate pigpio
    gpioTerminate();

    exit(0);
}

int main() {
    int client_socket;
    struct sockaddr_in server_address, client_address;
    socklen_t client_address_len = sizeof(client_address);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C connection
    i2c_handle = i2cOpen(I2C_BUS, SHT40_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Create socket
    server_fd = socket(AF_INET, SOCK_STREAM, 0);
    if (server_fd == -1) {
        perror("Error creating socket");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Bind socket to address and port
    server_address.sin_family = AF_INET;
    server_address.sin_addr.s_addr = INADDR_ANY;
    server_address.sin_port = htons(PORT);

    if (bind(server_fd, (struct sockaddr *)&server_address, sizeof(server_address)) < 0) {
        perror("Error binding socket");
        close(server_fd);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Listen for incoming connections
    if (listen(server_fd, 3) < 0) {
        perror("Error listening on socket");
        close(server_fd);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    printf("Server listening on port %d...\n", PORT);

    // Accept incoming connections and handle them
    while (1) {
        client_socket = accept(server_fd, (struct sockaddr *)&client_address, &client_address_len);
        if (client_socket < 0) {
            perror("Error accepting connection");
            continue; // Continue listening for other connections
        }

        handle_client(client_socket);
    }

    // The following lines will never be reached due to the infinite loop
    close(server_fd);
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

