#include <string.h>

// Constants
#define I2C_BUS 1
#define TMP102_ADDR 0x48
#define TEMP_REG 0x00
#define CSV_FILE "temperature_log.csv"

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_temperature(int i2c_handle);
float convert_to_celsius(int raw_temp);
int log_temperature(float temperature);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating gracefully...\n", signal);
}

// Reads the temperature from the TMP102 sensor
int read_temperature(int i2c_handle) {
    char buf[2];
    int result = i2cReadDevice(i2c_handle, buf, 2);

    if (result != 2) {
        fprintf(stderr, "Error reading temperature: %s\n", strerror(errno));
        return -1; // Indicate error
    }

    // Combine the two bytes into a 16-bit integer
    int16_t raw_temp = (buf[0] << 4) | (buf[1] >> 4);

    // Handle two's complement conversion if necessary
    if (raw_temp & 0x800) {
        raw_temp |= 0xF000; // Sign extend
    }

    return raw_temp;
}

// Converts the raw temperature value to degrees Celsius
float convert_to_celsius(int raw_temp) {
    return raw_temp * 0.0625;
}

// Logs the temperature to a CSV file
int log_temperature(float temperature) {
    FILE *fp = fopen(CSV_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening CSV file: %s\n", strerror(errno));
        return -1; // Indicate error
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s,%.2f\n", timestamp, temperature);
    fclose(fp);
    return 0;
}

