#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define constants
#define I2C_BUS 1
#define SDP800_ADDR 0x25
#define CONTINUOUS_MEASUREMENT_CMD 0x362F
#define PRESSURE_TEMP_DATA_SIZE 6
#define SLEEP_DURATION_MS 500

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// CRC-8 calculation function
uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Signal handler for clean shutdown
void signal_handler(int sig) {
    printf("\nCaught signal %d, terminating gracefully...\n", sig);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, SDP800_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        // Send continuous measurement command
        if (i2cWriteWordData(i2c_handle, 0x00, CONTINUOUS_MEASUREMENT_CMD) < 0) {
            fprintf(stderr, "Failed to write continuous measurement command\n");
            break;
        }

        // Wait for measurement to complete (45 ms)
        gpioDelay(45000); // 45 ms

        // Read pressure and temperature data
        char buffer[PRESSURE_TEMP_DATA_SIZE];
        if (i2cReadI2CBlockData(i2c_handle, 0x00, buffer, PRESSURE_TEMP_DATA_SIZE) != PRESSURE_TEMP_DATA_SIZE) {
            fprintf(stderr, "Failed to read pressure and temperature data\n");
            break;
        }

        // Extract raw data
        int16_t raw_pressure = (buffer[0] << 8) | buffer[1];
        int16_t raw_temperature = (buffer[3] << 8) | buffer[4];

        // CRC check for pressure
        uint8_t pressure_crc = crc8(buffer, 2);
        if (pressure_crc != buffer[2]) {
            fprintf(stderr, "Pressure CRC check failed!\n");
            break;
        }

        // CRC check for temperature
        uint8_t temperature_crc = crc8(buffer + 3, 2);
        if (temperature_crc != buffer[5]) {
            fprintf(stderr, "Temperature CRC check failed!\n");
            break;
        }

        // Log raw data to console
        printf("Raw Pressure: %d, Raw Temperature: %d\n", raw_pressure, raw_temperature);

        // Sleep for 500 ms
        gpioDelay(SLEEP_DURATION_MS * 1000); // Convert ms to us
    }

    // Clean up
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

