#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// Configuration
#define SPI_CHANNEL 0 // CE0
#define PWM_GPIO 17
#define PWM_FREQUENCY 1000 // Hz
#define LOG_FILE "reflow_log.csv"
#define ERROR_LOG_FILE "error_log.txt"
#define TARGET_PROFILE_FILE "profile.txt"
#define SAMPLE_RATE_HZ 1
#define SAMPLE_PERIOD_US (1000000 / SAMPLE_RATE_HZ)

// Global variables
int spi_handle;
FILE *log_file;
FILE *error_log_file;
volatile sig_atomic_t terminate = 0;

// PID parameters
double Kp = 1.0;
double Ki = 0.1;
double Kd = 0.01;

// Target temperature profile
double *target_temperatures = NULL;
double *target_times = NULL;
int profile_size = 0;

// Function prototypes
int read_max6675(int spi_handle, double *temperature);
double calculate_pid(double setpoint, double actual_temperature, double *integral, double *previous_error);
void set_pwm_duty_cycle(int gpio_pin, double duty_cycle);
void log_data(double temperature, double target_temperature, double pid_output);
void log_error(const char *message);
void signal_handler(int signal);
int read_target_profile(const char *filename);

// Function to read temperature from MAX6675
int read_max6675(int spi_handle, double *temperature) {
    char tx_buf[3] = {0, 0, 0};
    char rx_buf[3];

    if (spiXfer(spi_handle, tx_buf, rx_buf, 3) != 0) {
        log_error("SPI transfer failed");
        return -1;
    }

    int raw_data = (rx_buf[1] << 8) | rx_buf[2];

    if (raw_data & 0x4) {
        log_error("Thermocouple open circuit");
        return -2;
    }

    if (raw_data & 0x2) {
        log_error("Thermocouple fault");
        return -3;
    }

    int temp_raw = raw_data >> 3;
    *temperature = temp_raw * 0.25;

    return 0;
}

// Function to calculate PID output
double calculate_pid(double setpoint, double actual_temperature, double *integral, double *previous_error) {
    double error = setpoint - actual_temperature;
    *integral += error;
    double derivative = error - *previous_error;
    double output = Kp * error + Ki * (*integral) + Kd * derivative;
    *previous_error = error;
    return output;
}

// Function to set PWM duty cycle
void set_pwm_duty_cycle(int gpio_pin, double duty_cycle) {
    if (duty_cycle < 0.0) duty_cycle = 0.0;
    if (duty_cycle > 1.0) duty_cycle = 1.0;

    int pulse_width = (int)(duty_cycle * 1000000.0); // Assuming 1us resolution
    gpioPWM(gpio_pin, pulse_width);
}

// Function to log data to CSV file
void log_data(double temperature, double target_temperature, double pid_output) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s,%.2f,%.2f,%.2f\n", timestamp, temperature, target_temperature, pid_output);
    fflush(log_file);
}

// Function to log errors to file
void log_error(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(error_log_file, "%s: %s\n", timestamp, message);
    fflush(error_log_file);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("Received signal %d, terminating...\n", signal);
}

// Function to read target temperature profile from file
int read_target_profile(const char *filename) {
    FILE *fp = fopen(filename, "r");
    if (fp == NULL) {
        log_error("Failed to open target profile file");
        return -1;
    }

    char line[256];
    profile_size = 0;
    while (fgets(line, sizeof(line), fp)) {
        profile_size++;
    }
    rewind(fp);

    target_temperatures = (double *)malloc(profile_size * sizeof(double));
    target_times = (double *)malloc(profile_size * sizeof(double));
    if (target_temperatures == NULL || target_times == NULL) {
        log_error("Failed to allocate memory for target profile");
        fclose(fp);
        return -1;
    }

    int i = 0;
    while (fgets(line, sizeof(line), fp)) {
        if (sscanf(line, "%lf,%lf", &target_times[i], &target_temperatures[i]) != 2) {
            log_error("Invalid line in target profile file");
            fclose(fp);
            free(target_temperatures);
            free(target_times);
            return -1;
        }
        i++;
    }

    fclose(fp);
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, 1000000, 0); // Channel, Baud rate, Flags
    if (spi_handle < 0) {
        log_error("SPI open failed");
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        log_error("Failed to open log file");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Open error log file
    error_log_file = fopen(ERROR_LOG_FILE, "a");
    if (error_log_file == NULL) {
        log_error("Failed to open error log file");
        fclose(log_file);
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Set PWM GPIO mode
    gpioSetMode(PWM_GPIO, PI_OUTPUT);
    gpioSetPWMfrequency(PWM_GPIO, PWM_FREQUENCY);
    gpioSetPWMrange(PWM_GPIO, 1000000); // Set range to 1 second

    // Read target temperature profile
    if (read_target_profile(TARGET_PROFILE_FILE) != 0) {
        log_error("Failed to read target profile");
        fclose(log_file);
        fclose(error_log_file);
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize PID variables
    double integral = 0.0;
    double previous_error = 0.0;
    double current_time = 0.0;
    int current_profile_index = 0;

    // Signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        // Read temperature
        double temperature;
        int read_result = read_max6675(spi_handle, &temperature);
        if (read_result != 0) {
            log_error("Failed to read temperature");
            continue; // Skip to the next iteration
        }

        // Determine target temperature based on profile
        current_time = time(NULL);
        if (current_profile_index < profile_size - 1 && current_time >= target_times[current_profile_index + 1]) {
            current_profile_index++;
        }
        double target_temperature = target_temperatures[current_profile_index];

        // Calculate PID output
        double pid_output = calculate_pid(target_temperature, temperature, &integral, &previous_error);

        // Set PWM duty cycle
        set_pwm_duty_cycle(PWM_GPIO, pid_output);

        // Log data
        log_data(temperature, target_temperature, pid_output);

        // Sleep for the remaining time in the sample period
        long remaining_time_us = SAMPLE_PERIOD_US - (long)(gpioTick() % SAMPLE_PERIOD_US);
        if (remaining_time_us > 0) {
            gpioDelay(remaining_time_us);
        }
    }

    // Cleanup
    printf("Cleaning up...\n");
    set_pwm_duty_cycle(PWM_GPIO, 0.0); // Turn off relay
    fclose(log_file);
    fclose(error_log_file);
    spiClose(spi_handle);
    gpioTerminate();
    free(target_temperatures);
    free(target_times);

    return 0;
}

