    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(HEATER_ENABLE_GPIO, PI_OUTPUT);
    gpioSetMode(PWM_GPIO, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(PWM_GPIO, PWM_FREQUENCY);

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Could not open log file.\n");
        gpioTerminate();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Greenhouse control system started. Setpoint: %.2f, Kp: %.2f, Ki: %.2f, Kd: %.2f\n", setpoint, Kp, Ki, Kd);

    // Main loop
    while (running) {
        SensorData sensor_data = read_temperature();

        if (sensor_data.valid) {
            average_temperature = sensor_data.temperature;
        } else {
            fprintf(stderr, "Error: Invalid temperature reading.\n");
        }

        pid_output = calculate_pid(setpoint, average_temperature, &integral, &previous_error);
        control_heater(pid_output);
        duty_cycle = (double)gpioGetPWMdutycycle(PWM_GPIO) / 1000000.0 * 100.0; // Convert to percentage

        log_data(average_temperature, setpoint, pid_output, duty_cycle);

        sleep(SAMPLE_INTERVAL_SEC);
    }

    // Cleanup
    printf("Cleaning up...\n");
    gpioPWM(PWM_GPIO, 0); // Turn off heater
    gpioWrite(HEATER_ENABLE_GPIO, 0); // Disable relay
    fclose(log_file);
    gpioTerminate();

    return 0;
}

