#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define AHT20_ADDR 0x38
#define DEHUMIDIFIER_GPIO 17
#define HUMIDITY_HIGH_THRESHOLD 60.0
#define HUMIDITY_LOW_THRESHOLD 55.0
#define INIT_CMD_1 0xBE
#define INIT_CMD_2 0x08
#define INIT_CMD_3 0x00
#define MEASURE_CMD_1 0xAC
#define MEASURE_CMD_2 0x33
#define MEASURE_CMD_3 0x00
#define RETRY_COUNT 3
#define RETRY_DELAY_MS 10
#define MEASUREMENT_DELAY_MS 80
#define POLLING_INTERVAL_S 5

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_aht20();
int read_humidity(float *humidity);
void control_dehumidifier(float humidity);
void log_data(float humidity);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Initializes the AHT20 sensor
int initialize_aht20() {
    char init_data[3] = {INIT_CMD_1, INIT_CMD_2, INIT_CMD_3};
    int result;

    for (int i = 0; i < RETRY_COUNT; ++i) {
        result = i2cWriteDevice(i2c_handle, init_data, 3);
        if (result == 0) {
            return 0; // Success
        }
        gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
    }

    fprintf(stderr, "Error: Failed to initialize AHT20 after %d retries.\n", RETRY_COUNT);
    return -1; // Failure
}

// Reads humidity data from the AHT20 sensor
int read_humidity(float *humidity) {
    char measure_data[3] = {MEASURE_CMD_1, MEASURE_CMD_2, MEASURE_CMD_3};
    char read_data[6];
    int result;

    for (int i = 0; i < RETRY_COUNT; ++i) {
        result = i2cWriteDevice(i2c_handle, measure_data, 3);
        if (result != 0) {
            fprintf(stderr, "Error writing measurement command: %d\n", result);
            gpioDelay(RETRY_DELAY_MS * 1000);
            continue;
        }

        gpioDelay(MEASUREMENT_DELAY_MS * 1000); // Wait for measurement

        result = i2cReadDevice(i2c_handle, read_data, 6);
        if (result != 0) {
            fprintf(stderr, "Error reading humidity data: %d\n", result);
            gpioDelay(RETRY_DELAY_MS * 1000);
            continue;
        }

        // Check status byte (first byte of read_data)
        uint8_t status = read_data[0];
        if ((status & 0x80) != 0) {
            fprintf(stderr, "Error: Sensor busy (status = 0x%02X)\n", status);
            gpioDelay(RETRY_DELAY_MS * 1000);
            continue;
        }

        // Check calibration status (bit 7 of status byte)
        if ((status & 0x01) != 0) {
            fprintf(stderr, "Error: Sensor not calibrated (status = 0x%02X)\n", status);
            gpioDelay(RETRY_DELAY_MS * 1000);
            continue;
        }

        // Calculate humidity
        uint32_t humidity_raw = ((uint32_t)read_data[1] << 12) | ((uint32_t)read_data[2] << 4) | ((uint32_t)read_data[3] >> 4);
        *humidity = ((float)humidity_raw / 0x100000) * 100;

        return 0; // Success
    }

    fprintf(stderr, "Error: Failed to read humidity after %d retries.\n", RETRY_COUNT);
    return -1; // Failure
}

// Controls the dehumidifier relay based on humidity
void control_dehumidifier(float humidity) {
    if (humidity > HUMIDITY_HIGH_THRESHOLD) {
