#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <signal.h>
#include <syslog.h>
#include <errno.h>
#include <time.h>

#define I2C_BUS "/dev/i2c-1"
#define HTU21D_ADDR 0x40
#define MEASURE_CMD 0xE5
#define HTTP_URL "http://api.example.com/humidity"
#define SLEEP_SECONDS 60

volatile sig_atomic_t keep_running = 1;
int i2c_fd = -1;

void signal_handler(int sig) {
    syslog(LOG_INFO, "Signal received, shutting down...");
    keep_running = 0;
}

int i2c_setup() {
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        syslog(LOG_ERR, "Failed to open I2C bus: %s", strerror(errno));
        return -1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, HTU21D_ADDR) < 0) {
        syslog(LOG_ERR, "Failed to set I2C slave address: %s", strerror(errno));
        close(i2c_fd);
        i2c_fd = -1;
        return -1;
    }

    return 0;
}

int read_htu21d(float *humidity) {
    unsigned char cmd[1] = {MEASURE_CMD};
    unsigned char data[3];

    if (write(i2c_fd, cmd, 1) != 1) {
        syslog(LOG_ERR, "Failed to write to I2C device: %s", strerror(errno));
        return -1;
    }

    usleep(50000); // Wait for measurement (at least 50ms)

    if (read(i2c_fd, data, 3) != 3) {
        syslog(LOG_ERR, "Failed to read from I2C device: %s", strerror(errno));
        return -1;
    }

    // CRC Check
    unsigned char crc = data[2];
    unsigned char data_to_crc = data[0] | data[1] << 8;
    unsigned char calculated_crc = 0;

    for (int i = 0; i < 16; i++) {
        if ((data_to_crc & 0x8000) != 0) {
            calculated_crc ^= 0x131;
        }
        calculated_crc <<= 1;
        data_to_crc <<= 1;
    }

    if (calculated_crc != crc) {
        syslog(LOG_ERR, "CRC check failed!");
        return -1;
    }

    unsigned int raw_humidity = (data[0] << 8) | data[1];
    *humidity = -6.0 + 125.0 * (raw_humidity / 65536.0);

    return 0;
}

int post_humidity(float humidity) {
    int sockfd;
    struct sockaddr_in servaddr;
    char json_data[100];

    sockfd = socket(AF_INET, SOCK_STREAM, 0);
    if (sockfd < 0) {
        syslog(LOG_ERR, "Socket creation failed: %s", strerror(errno));
        return -1;
    }

    memset(&servaddr, 0, sizeof(servaddr));
    servaddr.sin_family = AF_INET;
    servaddr.sin_port = htons(80); // Default HTTP port
    if (inet_pton(AF_INET, "127.0.0.1", &servaddr.sin_addr) <= 0) {
        syslog(LOG_ERR, "Invalid address/ Address not supported: %s", strerror(errno));
        close(sockfd);
        return -1;
    }

    snprintf(json_data, sizeof(json_data), "{\"humidity\": %.2f}", humidity);

    if (connect(sockfd, (struct sockaddr *)&servaddr, sizeof(servaddr)) < 0) {
        syslog(LOG_ERR, "Connection Failed: %s", strerror(errno));
        close(sockfd);
        return -1;
    }

    char request[256];
    snprintf(request, sizeof(request), "POST %s HTTP/1.1\r\nHost: api.example.com\r\nContent-Type: application/json\r\nContent-Length: %zu\r\n\r\n%s", HTTP_URL, strlen(json_data), json_data);

    if (send(sockfd, request, strlen(request), 0) < 0) {
        syslog(LOG_ERR, "Send failed: %s", strerror(errno));
        close(sockfd);
        return -1;
    }

    close(sockfd);
    return 0;
}

int main() {
    openlog("htu21d_monitor", LOG_PID | LOG_CONS, LOG_USER);
    syslog(LOG_INFO, "Starting humidity monitoring...");

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    if (i2c_setup() < 0) {
        syslog(LOG_ERR, "I2C setup failed, exiting...");
        closelog();
        return 1;
    }

    while (keep_running) {
        float humidity;
        if (read_htu21d(&humidity) == 0) {
            syslog(LOG_INFO, "Humidity: %.2f %%", humidity);
            if (post_humidity(humidity) != 0) {
                syslog(LOG_ERR, "Failed to post humidity data.");
            }
        } else {
            syslog(LOG_ERR, "Failed to read humidity.");
        }

        sleep(SLEEP_SECONDS);
    }

    syslog(LOG_INFO, "Exiting humidity monitoring...");
    close(i2c_fd);
    closelog();
    return 0;
}

