#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

// Constants
#define I2C_BUS "/dev/i2c-1"
#define TMP117_ADDR 0x48
#define AHT20_ADDR 0x38
#define PIR_GPIO 17
#define LOG_FILE_PREFIX "sensor_log_"
#define LOG_FILE_SUFFIX ".csv"
#define SAMPLE_INTERVAL_SEC 1
#define MAX_I2C_RETRIES 3
#define BACKOFF_MS 10
#define AHT20_MEASURE_CMD_SIZE 3
#define AHT20_MEASURE_CMD {0xAC, 0x33, 0x00}

// Global variables
static volatile int keep_running = 1;
static int i2c_fd = -1;
static struct gpiod_chip *gpio_chip = NULL;
static struct gpiod_line *pir_line = NULL;
static char log_file_path[256];

// Function prototypes
int init_i2c(const char *bus);
int init_gpio(int gpio);
int init_tmp117(int fd);
int init_aht20(int fd);
float read_temperature(int fd);
float read_humidity(int fd);
int read_motion(int gpio);
int log_data(const char *timestamp, float temperature, float humidity, int motion);
void signal_handler(int sig);
void cleanup();

// I2C initialization function
int init_i2c(const char *bus) {
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C bus");
        return -1;
    }
    return fd;
}

// GPIO initialization function
int init_gpio(int gpio) {
    struct gpiod_line_request_config config;

    gpio_chip = gpiod_chip_open_by_name("gpiochip4");
    if (!gpio_chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    pir_line = gpiod_chip_get_line(gpio_chip, gpio);
    if (!pir_line) {
        perror("Error getting GPIO line");
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    memset(&config, 0, sizeof(config));
    config.consumer = "pir_sensor";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT;

    if (gpiod_line_request(pir_line, &config, 0) < 0) {
        perror("Error requesting GPIO line");
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    return 0;
}

// TMP117 initialization function
int init_tmp117(int fd) {
    // No specific initialization needed for TMP117 in this example
    return 0;
}

// AHT20 initialization function
int init_aht20(int fd) {
    unsigned char init_cmd[3] = {0xBE, 0x08, 0x00};
    if (write(fd, init_cmd, sizeof(init_cmd)) != sizeof(init_cmd)) {
        perror("Error writing to AHT20");
        return -1;
    }
    usleep(10000); // Wait for initialization
    return 0;
}

// Temperature reading function
float read_temperature(int fd) {
    unsigned char buf[2];
    int16_t raw_temp;
    float temperature;
    int retries = 0;

    while (retries < MAX_I2C_RETRIES) {
        if (read(fd, buf, 2) == 2) {
            raw_temp = (buf[0] << 8) | buf[1];
            temperature = raw_temp * 0.0078125;
            return temperature;
        } else {
            perror("Error reading temperature from TMP117");
            retries++;
            usleep(BACKOFF_MS * 1000); // Exponential backoff
        }
    }

    fprintf(stderr, "Failed to read temperature after %d retries\n", MAX_I2C_RETRIES);
    return -999.0; // Indicate error
}

// Humidity reading function
float read_humidity(int fd) {
    unsigned char buf[8];
    int retries = 0;

    while (retries < MAX_I2C_RETRIES) {
        if (write(fd, AHT20_MEASURE_CMD, AHT20_MEASURE_CMD_SIZE) == AHT20_MEASURE_CMD_SIZE) {
            usleep(80000); // Wait for measurement (at least 75ms)
            if (read(fd, buf, 8) == 8) {
                if (!(buf[0] & 0x80)) {
                    int humidity_raw = ((buf[1] << 12) | (buf[2] << 4) | (buf[3] >> 4));
                    float humidity = ((float)humidity_raw / 0x100000) * 100;
                    return humidity;
                } else {
                    fprintf(stderr, "AHT20 busy\n");
                }
            } else {
                perror("Error reading humidity from AHT20");
            }
        } else {
            perror("Error writing to AHT20");
        }
        retries++;
        usleep(BACKOFF_MS * 1000); // Exponential backoff
    }

    fprintf(stderr, "Failed to read humidity after %d retries\n", MAX_I2C_RETRIES);
    return -999.0; // Indicate error
}

// Motion detection function
int read_motion(int gpio) {
    int value = gpiod_line_get_value(pir_line);
    if (value < 0) {
        perror("Error reading PIR sensor value");
        return -1;
    }
    return value;
}

// Data logging function
int log_data(const char *timestamp, float temperature, float humidity, int motion) {
    FILE *fp = fopen(log_file_path, "a");
    if (fp == NULL) {
        perror("Error opening log file");
        return -1;
    }

    fprintf(fp, "%s,%.2f,%.2f,%d\n", timestamp, temperature, humidity, motion);
    fclose(fp);
    return 0;
}

// Signal handler function
void signal_handler(int sig) {
    keep_running = 0;
    printf("Caught signal %d, exiting...\n", sig);
}

// Cleanup function
void cleanup() {
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (gpio_chip) {
        if (pir_line) {
            gpiod_line_release(pir_line);
        }
        gpiod_chip_close(gpio_chip);
    }
}

int main() {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];
    int motion;
    float temperature, humidity;
    int tmp117_fd, aht20_fd;

    // Initialize signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    i2c_fd = init_i2c(I2C_BUS);
    if (i2c_fd < 0) {
        return 1;
    }

    // Initialize GPIO
    if (init_gpio(PIR_GPIO) < 0) {
        cleanup();
        return 1;
    }

    // Initialize TMP117
    tmp117_fd = i2c_fd; // Use the same file descriptor for both sensors
    if (init_tmp117(tmp117_fd) < 0) {
        fprintf(stderr, "Warning: TMP117 initialization failed\n");
    }

    // Initialize AHT20
    aht20_fd = i2c_fd; // Use the same file descriptor for both sensors
    if (init_aht20(aht20_fd) < 0) {
        fprintf(stderr, "Warning: AHT20 initialization failed\n");
    }

    // Determine log file path
