    keep_running = 0;
    printf("Caught signal %d, exiting...\n", sig);
}

// Cleanup function
void cleanup() {
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (gpio_chip) {
        if (pir_line) {
            gpiod_line_release(pir_line);
        }
