#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <errno.h>
#include <signal.h>
#include <time.h>
#include <sys/time.h>
#include <gpiod.h>

// Define GPIO pins
#define RAIN_SENSOR_PIN 17
#define MOTOR_ENA_PIN 22
#define MOTOR_IN1_PIN 23
#define MOTOR_IN2_PIN 24

// Define motor run time (seconds)
#define MOTOR_RUN_TIME 5

// Global variables
static volatile int keep_running = 1;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *rain_line = NULL;
static struct gpiod_line *ena_line = NULL;
static struct gpiod_line *in1_line = NULL;
static struct gpiod_line *in2_line = NULL;

// Function prototypes
int read_rain_sensor(struct gpiod_line *line);
int control_motor(struct gpiod_line *ena_line, struct gpiod_line *in1_line, struct gpiod_line *in2_line, int run_time);
void signal_handler(int sig);
void log_event(const char *message);

// Signal handler function
void signal_handler(int sig) {
    if (sig == SIGINT || sig == SIGTERM) {
        log_event("Received signal, stopping...");
        keep_running = 0;
    }
}

// Function to read the rain sensor
int read_rain_sensor(struct gpiod_line *line) {
    int value = gpiod_line_get_value(line);
    if (value < 0) {
        fprintf(stderr, "Error reading rain sensor: %s\n", strerror(-value));
        return -1;
    }
    return value;
}

// Function to control the motor
int control_motor(struct gpiod_line *ena_line, struct gpiod_line *in1_line, struct gpiod_line *in2_line, int run_time) {
    struct timespec sleep_time;
    sleep_time.tv_sec = run_time;
    sleep_time.tv_nsec = 0;

    // Enable the motor
    if (gpiod_line_set_value(ena_line, 1) < 0) {
        fprintf(stderr, "Error setting ENA high: %s\n", strerror(errno));
        return -1;
    }

    // Set direction for forward movement
    if (gpiod_line_set_value(in1_line, 1) < 0) {
        fprintf(stderr, "Error setting IN1 high: %s\n", strerror(errno));
        return -1;
    }
    if (gpiod_line_set_value(in2_line, 0) < 0) {
        fprintf(stderr, "Error setting IN2 low: %s\n", strerror(errno));
        return -1;
    }

    log_event("Motor started");

    // Wait for the specified run time
    if (nanosleep(&sleep_time, NULL) < 0) {
        if (errno != EINTR) {
            fprintf(stderr, "Error during nanosleep: %s\n", strerror(errno));
            return -1;
        }
    }

    // Stop the motor
    if (gpiod_line_set_value(ena_line, 0) < 0) {
        fprintf(stderr, "Error setting ENA low: %s\n", strerror(errno));
        return -1;
    }

    log_event("Motor stopped");

    return 0;
}

// Function to log events with timestamps
void log_event(const char *message) {
    struct timeval tv;
    struct tm *tm_info;
    char buffer[64];

    gettimeofday(&tv, NULL);
    tm_info = localtime(&tv.tv_sec);

    strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", tm_info);
    printf("[%s.%06ld] %s\n", buffer, tv.tv_usec, message);
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Error opening GPIO chip");
        return 1;
    }

    // Get lines for rain sensor
    rain_line = gpiod_chip_get_line(chip, RAIN_SENSOR_PIN);
    if (!rain_line) {
        perror("Error getting rain sensor line");
        gpiod_chip_close(chip);
        return 1;
    }

    // Get lines for motor control
    ena_line = gpiod_chip_get_line(chip, MOTOR_ENA_PIN);
    in1_line = gpiod_chip_get_line(chip, MOTOR_IN1_PIN);
    in2_line = gpiod_chip_get_line(chip, MOTOR_IN2_PIN);

    if (!ena_line || !in1_line || !in2_line) {
        perror("Error getting motor control lines");
        if(rain_line) gpiod_line_release(rain_line);
        if(ena_line) gpiod_line_release(ena_line);
        if(in1_line) gpiod_line_release(in1_line);
        if(in2_line) gpiod_line_release(in2_line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Request rain sensor line as input
    if (gpiod_line_request_input(rain_line, "rain_sensor") < 0) {
        perror("Error requesting rain sensor line as input");
        if(rain_line) gpiod_line_release(rain_line);
        if(ena_line) gpiod_line_release(ena_line);
        if(in1_line) gpiod_line_release(in1_line);
        if(in2_line) gpiod_line_release(in2_line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Request motor control lines as output
    if (gpiod_line_request_output(ena_line, "motor_ena", 0) < 0) {
        perror("Error requesting ENA line as output");
        if(rain_line) gpiod_line_release(rain_line);
        if(ena_line) gpiod_line_release(ena_line);
        if(in1_line) gpiod_line_release(in1_line);
        if(in2_line) gpiod_line_release(in2_line);
        gpiod_chip_close(chip);
        return 1;
    }
    if (gpiod_line_request_output(in1_line, "motor_in1", 0) < 0) {
        perror("Error requesting IN1 line as output");
        if(rain_line) gpiod_line_release(rain_line);
        if(ena_line) gpiod_line_release(ena_line);
        if(in1_line) gpiod_line_release(in1_line);
        if(in2_line) gpiod_line_release(in2_line);
        gpiod_chip_close(chip);
        return 1;
    }
    if (gpiod_line_request_output(in2_line, "motor_in2", 0) < 0) {
        perror("Error requesting IN2 line as output");
        if(rain_line) gpiod_line_release(rain_line);
        if(ena_line) gpiod_line_release(ena_line);
        if(in1_line) gpiod_line_release(in1_line);
        if(in2_line) gpiod_line_release(in2_line);
        gpiod_chip_close(chip);
        return 1;
    }

    log_event("Program started");

    // Main loop
    while (keep_running) {
        int rain_detected = read_rain_sensor(rain_line);
        if (rain_detected == 0) {
            log_event("Rain detected");
            if (control_motor(ena_line, in1_line, in2_line, MOTOR_RUN_TIME) != 0) {
                fprintf(stderr, "Error controlling motor\n");
            }
        } else if (rain_detected < 0) {
            fprintf(stderr, "Error reading rain sensor, exiting\n");
            break;
        }

        sleep(2);
    }

    // Release GPIO lines and close chip
    log_event("Releasing GPIO lines");
    if(rain_line) gpiod_line_release(rain_line);
    if(ena_line) gpiod_line_release(ena_line);
    if(in1_line) gpiod_line_release(in1_line);
    if(in2_line) gpiod_line_release(in2_line);
    gpiod_chip_close(chip);

    log_event("Program stopped");

    return 0;
}

