// Define GPIO pins for RGB LED (common anode)
#define RED_PIN   17
#define GREEN_PIN 22
#define BLUE_PIN  27

// Global variable to indicate program termination
volatile sig_atomic_t terminate = 0;

// Signal handler function
void signal_handler(int sig)
{
    fprintf(stderr, "\nCaught signal %d, terminating gracefully...\n", sig);
    terminate = 1;
}

// Function to read CPU load from /proc/stat
float read_cpu_load()
{
    FILE *fp;
    unsigned long long user, nice, system, idle, iowait, irq, softirq, steal, guest, guest_nice;
    unsigned long long prev_user, prev_nice, prev_system, prev_idle, prev_iowait, prev_irq, prev_softirq, prev_steal, prev_guest, prev_guest_nice;
    float cpu_load;

    // Read CPU stats from /proc/stat
    fp = fopen("/proc/stat", "r");
    if (fp == NULL) {
        perror("Error opening /proc/stat");
        return -1.0; // Indicate error
    }

    fscanf(fp, "cpu  %llu %llu %llu %llu %llu %llu %llu %llu %llu %llu",
           &prev_user, &prev_nice, &prev_system, &prev_idle, &prev_iowait, &prev_irq, &prev_softirq, &prev_steal, &prev_guest, &prev_guest_nice);
    fclose(fp);

    // Wait for a short period
    gpioDelay(100); // 100 ms

    // Read CPU stats again
    fp = fopen("/proc/stat", "r");
    if (fp == NULL) {
        perror("Error opening /proc/stat");
        return -1.0; // Indicate error
    }

    fscanf(fp, "cpu  %llu %llu %llu %llu %llu %llu %llu %llu %llu %llu",
           &user, &nice, &system, &idle, &iowait, &irq, &softirq, &steal, &guest, &guest_nice);
    fclose(fp);

    // Calculate CPU usage
    unsigned long long prev_total = prev_user + prev_nice + prev_system + prev_idle + prev_iowait + prev_irq + prev_softirq + prev_steal + prev_guest + prev_guest_nice;
    unsigned long long total = user + nice + system + idle + iowait + irq + softirq + steal + guest + guest_nice;
    unsigned long long delta_total = total - prev_total;
    unsigned long long delta_idle = idle - prev_idle;

    cpu_load = (float)(delta_total - delta_idle) / delta_total * 100.0;

    return cpu_load;
}

// Function to map CPU load to RGB color values
void map_cpu_to_rgb(float cpu_load, int *red, int *green, int *blue)
{
    if (cpu_load < 0.0) {
        *red = 0;
        *green = 0;
        *blue = 0;
        return;
    }

    if (cpu_load <= 50.0) {
        // Green to Yellow
        *red = (int)(cpu_load / 50.0 * 255.0);
        *green = 255;
        *blue = 0;
    } else {
        // Yellow to Red
        *red = 255;
        *green = (int)((100.0 - cpu_load) / 50.0 * 255.0);
        *blue = 0;
    }
}

// Function to set the RGB LED color using PWM
void set_rgb_led(int red, int green, int blue)
{
    // Common anode, so invert the PWM values
    gpioPWM(RED_PIN, 255 - red);
    gpioPWM(GREEN_PIN, 255 - green);
    gpioPWM(BLUE_PIN, 255 - blue);
}

int main()
{
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins to output mode
    gpioSetMode(RED_PIN, PI_OUTPUT);
    gpioSetMode(GREEN_PIN, PI_OUTPUT);
    gpioSetMode(BLUE_PIN, PI_OUTPUT);

    // Set PWM range (0-255)
    gpioSetPWMrange(RED_PIN, 255);
    gpioSetPWMrange(GREEN_PIN, 255);
    gpioSetPWMrange(BLUE_PIN, 255);

    // Set PWM frequency (adjust as needed)
    gpioSetPWMfrequency(RED_PIN, 1000); // 1 kHz
    gpioSetPWMfrequency(GREEN_PIN, 1000); // 1 kHz
    gpioSetPWMfrequency(BLUE_PIN, 1000); // 1 kHz

    // Install signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    struct timespec sleep_time;
    sleep_time.tv_sec = 0;
    sleep_time.tv_nsec = 500000000; // 500 ms

    // Main loop
    while (!terminate) {
        // Read CPU load
        float cpu_load = read_cpu_load();
        if (cpu_load < 0.0) {
            fprintf(stderr, "Error reading CPU load, using default values\n");
            cpu_load = 0.0; // Default value
        }

        // Map CPU load to RGB color values
        int red, green, blue;
        map_cpu_to_rgb(cpu_load, &red, &green, &blue);

        // Set RGB LED color
        set_rgb_led(red, green, blue);

        // Sleep for 500 ms
        nanosleep(&sleep_time, NULL);
    }

    // Turn off the LED before exiting
    set_rgb_led(0, 0, 0);

    // Terminate pigpio library
    gpioTerminate();

    return 0;
}

