    }

    // Check chip ID
    int chip_id = i2cReadByteData(i2c_handle, BMP280_REG_CHIPID);
    if (chip_id < 0 || chip_id != 0x58) {
        fprintf(stderr, "Error reading chip ID or invalid ID: 0x%X\n", chip_id);
        i2cClose(i2c_handle);
        return -1;
    }

    // Reset the sensor
    if (i2cWriteByteData(i2c_handle, BMP280_REG_RESET, 0xB6) < 0) {
        fprintf(stderr, "Error resetting sensor\n");
        i2cClose(i2c_handle);
        return -1;
    }
    gpioDelay(10); // Wait for reset to complete

    // Configure sensor (forced mode, oversampling x16, filter off)
    if (i2cWriteByteData(i2c_handle, BMP280_REG_CTRL_MEAS, 0b00110111) < 0) { // Temperature x16, Pressure x16, Forced mode
        fprintf(stderr, "Error writing to CTRL_MEAS register\n");
        i2cClose(i2c_handle);
        return -1;
    }

    if (i2cWriteByteData(i2c_handle, BMP280_REG_CONFIG, 0b00000000) < 0) { // Filter off
        fprintf(stderr, "Error writing to CONFIG register\n");
        i2cClose(i2c_handle);
        return -1;
    }

    return 0;
}

// Initialize UDP socket
int init_udp() {
    udp_socket = socket(AF_INET, SOCK_DGRAM, 0);
    if (udp_socket < 0) {
        perror("Error creating socket");
        return -1;
    }

    struct sockaddr_in server_addr;
    memset(&server_addr, 0, sizeof(server_addr));
    server_addr.sin_family = AF_INET;
    server_addr.sin_port = htons(5000);
    if (inet_pton(AF_INET, "192.168.1.100", &server_addr.sin_addr) <= 0) {
        perror("Invalid address/ Address not supported");
        close(udp_socket);
        return -1;
    }

    return 0;
}

// Read calibration data from sensor
int read_calibration_data(bmp280_calib_data *calib) {
    char data[26];
    if (i2cReadI2CBlockData(i2c_handle, BMP280_REG_CALIB_00, data, 26) < 0) {
        fprintf(stderr, "Error reading calibration data\n");
        return -1;
    }

    calib->dig_T1 = (uint16_t)data[0] | ((uint16_t)data[1] << 8);
    calib->dig_T2 = (int16_t)data[2] | ((int16_t)data[3] << 8);
    calib->dig_T3 = (int16_t)data[4] | ((int16_t)data[5] << 8);
    calib->dig_P1 = (uint16_t)data[6] | ((uint16_t)data[7] << 8);
    calib->dig_P2 = (int16_t)data[8] | ((int16_t)data[9] << 8);
    calib->dig_P3 = (int16_t)data[10] | ((int16_t)data[11] << 8);
    calib->dig_P4 = (int16_t)data[12] | ((int16_t)data[13] << 8);
    calib->dig_P5 = (int16_t)data[14] | ((int16_t)data[15] << 8);
    calib->dig_P6 = (int16_t)data[16] | ((int16_t)data[17] << 8);
    calib->dig_P7 = (int16_t)data[18] | ((int16_t)data[19] << 8);
    calib->dig_P8 = (int16_t)data[20] | ((int16_t)data[21] << 8);
    calib->dig_P9 = (int16_t)data[22] | ((int16_t)data[23] << 8);

    return 0;
}

// Read raw temperature and pressure data
int read_raw_data(int32_t *temperature, int32_t *pressure) {
    // Trigger a measurement by writing to CTRL_MEAS register
    if (i2cWriteByteData(i2c_handle, BMP280_REG_CTRL_MEAS, 0b00110111) < 0) { // Temperature x16, Pressure x16, Forced mode
        fprintf(stderr, "Error triggering measurement\n");
        return -1;
    }

    gpioDelay(10); // Wait for measurement to complete (adjust as needed)

    char data[6];
    if (i2cReadI2CBlockData(i2c_handle, BMP280_REG_PRESS_MSB, data, 6) < 0) {
        fprintf(stderr, "Error reading raw data\n");
        return -1;
    }

    *pressure = ((int32_t)data[0] << 12) | ((int32_t)data[1] << 4) | ((int32_t)data[2] >> 4);
    *temperature = ((int32_t)data[3] << 12) | ((int32_t)data[4] << 4) | ((int32_t)data[5] >> 4);

    return 0;
}

// Compensate temperature using Bosch formula
double compensate_temperature(int32_t raw_temperature) {
    double var1, var2, T;
    double T1 = calib.dig_T1;
    double T2 = calib.dig_T2;
    double T3 = calib.dig_T3;

    var1 = (((double)raw_temperature / 16384.0) - (T1 / 1024.0)) * T2;
    var2 = (((double)raw_temperature / 131072.0) - (T1 / 8192.0)) * (((double)raw_temperature / 131072.0) - (T1 / 8192.0)) * T3;
    double t_fine = var1 + var2;
    T = (t_fine / 5120.0);
    return T;
}

// Compensate pressure using Bosch formula
double compensate_pressure(int32_t raw_pressure, double t_fine) {
    double var1, var2, p;
    double P1 = calib.dig_P1;
    double P2 = calib.dig_P2;
    double P3 = calib.dig_P3;
    double P4 = calib.dig_P4;
    double P5 = calib.dig_P5;
    double P6 = calib.dig_P6;
    double P7 = calib.dig_P7;
    double P8 = calib.dig_P8;
    double P9 = calib.dig_P9;

    var1 = (t_fine / 2.0) - 64000.0;
    var2 = var1 * var1 * (P6 / 32768.0);
    var2 = var2 + (var1 * P5 * 2.0);
    var2 = (var2 / 4.0) + (P4 * 65536.0);
    var1 = (P3 * var1 * var1 / 524288.0 + P2 * var1) / 524288.0;
    var1 = (1.0 + var1 / 32768.0) * P1;

    if (var1 == 0)
    {
        return 0;
    }

    p = 1048576.0 - raw_pressure;
    p = (p - (var2 / 4096.0)) * 6250.0 / var1;
    var1 = P9 * p * p / 2147483648.0;
    var2 = p * P8 / 32768.0;
    p = p + (var1 + var2 + P7) / 16.0;

    return p;
}

// Create JSON string
char* create_json(double temperature, double pressure) {
    char *json_string = malloc(100); // Allocate memory for the JSON string
    if (json_string == NULL) {
        fprintf(stderr, "Error allocating memory for JSON string\n");
        return NULL;
    }
    snprintf(json_string, 100, "{\"temperature\":%.2f, \"pressure\":%.2f}", temperature, pressure);
    return json_string;
}

// Send UDP data
int send_udp_data(const char *json_string) {
    struct sockaddr_in server_addr;
    memset(&server_addr, 0, sizeof(server_addr));
    server_addr.sin_family = AF_INET;
    server_addr.sin_port = htons(5000);
    if (inet_pton(AF_INET, "192.168.1.100", &server_addr.sin_addr) <= 0) {
        perror("Invalid address/ Address not supported");
        return -1;
    }

    if (sendto(udp_socket, json_string, strlen(json_string), 0, (struct sockaddr *)&server_addr, sizeof(server_addr)) < 0) {
        perror("Error sending UDP data");
        return -1;
    }

    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() < 0) {
        gpioTerminate();
        return 1;
    }

    // Read calibration data
    if (read_calibration_data(&calib) < 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize UDP
    if (init_udp() < 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    int32_t raw_temperature, raw_pressure;
    double temperature, pressure;
    char *json_string;

    while (1) {
        // Read raw data
        if (read_raw_data(&raw_temperature, &raw_pressure) < 0) {
            fprintf(stderr, "Error reading raw data, retrying...\n");
            gpioDelay(1000); // Wait 1 second before retrying
            continue;
        }

        // Compensate temperature and pressure
        temperature = compensate_temperature(raw_temperature);
        pressure = compensate_pressure(raw_pressure, temperature);

        // Create JSON string
        json_string = create_json(temperature, pressure);
        if (json_string == NULL) {
            fprintf(stderr, "Error creating JSON string, retrying...\n");
            gpioDelay(1000); // Wait 1 second before retrying
            continue;
        }

        // Send UDP data
        if (send_udp_data(json_string) < 0) {
            fprintf(stderr, "Error sending UDP data, retrying...\n");
        }

        free(json_string); // Free the allocated memory

        // Wait 5 seconds
        gpioDelay(5000);
    }

    return 0;
}

