#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

// Define GPIO pins
#define FAN_PIN 18
#define SPI_CE0 8

// Define SPI parameters
#define SPI_CHANNEL 0
#define SPI_SPEED 500000 // 500 kHz
#define SPI_MODE 0

// Define PWM parameters
#define PWM_FREQUENCY 1000 // 1 kHz
#define PWM_RANGE 255

// Define temperature thresholds
#define TEMP_LOW 25.0
#define TEMP_MED1 40.0
#define TEMP_MED2 60.0

// Define circular buffer size
#define BUFFER_SIZE 20

// Structure to hold temperature data
typedef struct {
    time_t timestamp;
    float temperature;
    int duty_cycle;
} TemperatureData;

// Circular buffer
TemperatureData temperature_buffer[BUFFER_SIZE];
int buffer_index = 0;

// SPI handle
int spi_handle;

// Function prototypes
int read_max31855(int spi_handle, float *thermocouple_temp, int *fault_code);
float calculate_duty_cycle(float temperature);
void update_fan_speed(int duty_cycle);
void add_to_buffer(float temperature, int duty_cycle);
void print_buffer();
void signal_handler(int signal);

// Function to read temperature from MAX31855
int read_max31855(int spi_handle, float *thermocouple_temp, int *fault_code) {
    unsigned char tx_buffer[4] = {0}; // Dummy data for reading
    unsigned char rx_buffer[4];
    int result;

    result = spiXfer(spi_handle, tx_buffer, rx_buffer, 4);
    if (result != 0) {
        fprintf(stderr, "SPI transfer error: %d\n", result);
        return -1; // Indicate error
    }

    // Extract thermocouple temperature (bits 31:17)
    int32_t raw_data = (rx_buffer[0] << 24) | (rx_buffer[1] << 16) | (rx_buffer[2] << 8) | rx_buffer[3];

    // Check for fault bit (bit 16)
    if (raw_data & (1 << 16)) {
        *fault_code = 1; // Fault detected

        // Extract fault type bits (bits 0, 1, 2)
        int fault_type = raw_data & 0x07;

        if (fault_type == 0x01) {
            fprintf(stderr, "MAX31855 Fault: Open Circuit (OC)\n");
        } else if (fault_type == 0x02) {
            fprintf(stderr, "MAX31855 Fault: Short to GND (SCG)\n");
        } else if (fault_type == 0x04) {
            fprintf(stderr, "MAX31855 Fault: Short to VCC (SCV)\n");
        } else {
            fprintf(stderr, "MAX31855 Fault: Unknown Fault Type\n");
        }

        *thermocouple_temp = 0.0; // Set temperature to 0 on fault
    } else {
        *fault_code = 0; // No fault

        // Extract thermocouple temperature (bits 31:17) and sign extend
        raw_data = raw_data >> 18; // Shift right to get the 14-bit temperature
        if (raw_data & (1 << 13)) {
            raw_data |= 0xE000; // Sign extend if negative
        }

        *thermocouple_temp = raw_data * 0.25; // Convert to Celsius
    }

    return 0; // Indicate success
}

// Function to calculate PWM duty cycle based on temperature
float calculate_duty_cycle(float temperature) {
    float duty_cycle;

    if (temperature < TEMP_LOW) {
        duty_cycle = 0.0;
    } else if (temperature < TEMP_MED1) {
        duty_cycle = (temperature - TEMP_LOW) / (TEMP_MED1 - TEMP_LOW) * 50.0;
    } else if (temperature < TEMP_MED2) {
        duty_cycle = 50.0 + (temperature - TEMP_MED1) / (TEMP_MED2 - TEMP_MED1) * (200.0 - 50.0);
    } else {
        duty_cycle = 200.0;
    }

    return duty_cycle;
}

// Function to update fan speed using PWM
void update_fan_speed(int duty_cycle) {
    gpioPWM(FAN_PIN, duty_cycle);
}

// Function to add temperature data to the circular buffer
void add_to_buffer(float temperature, int duty_cycle) {
    temperature_buffer[buffer_index].timestamp = time(NULL);
    temperature_buffer[buffer_index].temperature = temperature;
    temperature_buffer[buffer_index].duty_cycle = duty_cycle;

    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

// Function to print the contents of the circular buffer
void print_buffer() {
    printf("\n--- Temperature Log ---\n");
    for (int i = 0; i < BUFFER_SIZE; i++) {
        int index = (buffer_index + i) % BUFFER_SIZE;
        struct tm *timeinfo = localtime(&temperature_buffer[index].timestamp);
        char timestamp_str[20];
        strftime(timestamp_str, sizeof(timestamp_str), "%Y-%m-%d %H:%M:%S", timeinfo);
        printf("[%s] Temperature: %.2f°C, Duty Cycle: %d\n", timestamp_str, temperature_buffer[index].temperature, temperature_buffer[index].duty_cycle);
    }
    printf("--- End of Log ---\n\n");
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);

    // Stop PWM
    gpioPWM(FAN_PIN, 0);

    // Close SPI
    spiClose(spi_handle);

    // Print the buffer
    print_buffer();

    // Terminate pigpio
    gpioTerminate();

    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO18 as output for PWM
    gpioSetMode(FAN_PIN, PI_OUTPUT);

    // Set PWM frequency and range
    gpioSetPWMfrequency(FAN_PIN, PWM_FREQUENCY);
    gpioSetPWMrange(FAN_PIN, PWM_RANGE);

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    float thermocouple_temp;
    int fault_code;
    float duty_cycle;

    // Main loop
    while (1) {
        // Read temperature from MAX31855
        if (read_max31855(spi_handle, &thermocouple_temp, &fault_code) == 0) {
            // Calculate duty cycle
            duty_cycle = calculate_duty_cycle(thermocouple_temp);

            // Update fan speed
            update_fan_speed((int)duty_cycle);

            // Add data to buffer
            add_to_buffer(thermocouple_temp, (int)duty_cycle);

            printf("Temperature: %.2f°C, Duty Cycle: %.2f\n", thermocouple_temp, duty_cycle);
        } else {
            // Handle SPI error or MAX31855 fault
            fprintf(stderr, "Error reading temperature or MAX31855 fault.\n");
        }

        // Wait for 1 second
        time_sleep(1.0);
    }

    return 0;
}

