#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define CS_GPIO 8
#define RTD_LOG_FILE "rtd_log.csv"
#define TEMP_THRESHOLD 50.0 // Temperature threshold in Celsius
#define LOG_INTERVAL 5 // Logging interval in seconds

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_pigpio();
int init_spi();
int init_cs_gpio();
int read_max31865(unsigned char *data);
int check_fault_status(unsigned char *data);
double calculate_temperature(unsigned char *data);
int log_temperature(double temperature);
void signal_handler(int signal);
void cleanup();

// Structure for configuration (optional)
typedef struct {
    int spi_channel;
    int spi_speed;
    int cs_gpio;
    char *log_file;
    double temp_threshold;
    int log_interval;
} Config;

Config config = {
    SPI_CHANNEL,
    SPI_SPEED,
    CS_GPIO,
    RTD_LOG_FILE,
    TEMP_THRESHOLD,
    LOG_INTERVAL
};

int main() {
    unsigned char data[4];
    double temperature;

    // Initialize pigpio
    if (init_pigpio() != 0) {
        fprintf(stderr, "Failed to initialize pigpio. Exiting.\n");
        return 1;
    }

    // Initialize SPI
    if (init_spi() != 0) {
        fprintf(stderr, "Failed to initialize SPI. Exiting.\n");
        cleanup();
        return 1;
    }

    // Initialize CS GPIO
    if (init_cs_gpio() != 0) {
        fprintf(stderr, "Failed to initialize CS GPIO. Exiting.\n");
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen(config.log_file, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file. Exiting.\n");
        cleanup();
        return 1;
    }

    // Write header if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Temperature (C)\n");
    }
    rewind(log_file);

    // Register signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        // Read temperature from MAX31865
        if (read_max31865(data) == 0) {
            // Check fault status
            if (check_fault_status(data) == 0) {
                // Calculate temperature
                temperature = calculate_temperature(data);

                // Log temperature
                if (log_temperature(temperature) != 0) {
                    fprintf(stderr, "Failed to log temperature.\n");
                }

                // Check temperature threshold
                if (temperature > config.temp_threshold) {
                    printf("Temperature exceeds threshold: %.2f C\n", temperature);
                }
            } else {
                fprintf(stderr, "Fault detected on MAX31865.\n");
            }
        } else {
            fprintf(stderr, "Failed to read temperature from MAX31865.\n");
        }

        // Wait for the next logging interval
        sleep(config.log_interval);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

// Initialize pigpio library
int init_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }
    return 0;
}

// Initialize SPI interface
int init_spi() {
    spi_handle = spiOpen(config.spi_channel, config.spi_speed, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        return 1;
    }
    return 0;
}

// Initialize CS GPIO as output
int init_cs_gpio() {
    gpioSetMode(config.cs_gpio, PI_OUTPUT);
    gpioWrite(config.cs_gpio, 1); // Deactivate chip select initially
    return 0;
}

// Read data from MAX31865
int read_max31865(unsigned char *data) {
    char tx_buf[4] = {0x00, 0x00, 0x00, 0x00}; // Dummy data for reading
    char rx_buf[4];

    gpioWrite(config.cs_gpio, 0); // Activate chip select
    gpioDelay(1); // Small delay after CS activation

    int result = spiXfer(spi_handle, tx_buf, rx_buf, 4);
    if (result != 4) {
        fprintf(stderr, "SPI transfer failed: %d\n", result);
        gpioWrite(config.cs_gpio, 1); // Deactivate chip select
        return 1;
    }

    gpioWrite(config.cs_gpio, 1); // Deactivate chip select
    gpioDelay(1); // Small delay after CS deactivation

    memcpy(data, rx_buf, 4);
    return 0;
}

// Check fault status register
int check_fault_status(unsigned char *data) {
    if (data[3] & 0x01) {
        fprintf(stderr, "Sensor absent fault detected.\n");
        return 1;
    }
    if (data[3] & 0x02) {
        fprintf(stderr, "SPI bus error detected.\n");
        return 1;
    }
    return 0;
}

// Calculate temperature using Callendar-Van Dusen equation
double calculate_temperature(unsigned char *data) {
    unsigned int rtd_raw = ((data[0] << 8) | data[1]) >> 1; // Extract RTD value (13 bits)
    double rtd_resistance = (double)rtd_raw * 430.0 / 16383.0; // Convert to resistance (assuming 430 Ohm reference resistor)

    // Callendar-Van Dusen equation for PT100 (simplified)
    double temperature = (rtd_resistance - 100.0) / 0.385; // Linear approximation

    return temperature;
}

// Log temperature to file
int log_temperature(double temperature) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f\n", timestamp, temperature);
    fflush(log_file); // Ensure data is written to disk
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup resources
void cleanup() {
    printf("Cleaning up...\n");
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioWrite(config.cs_gpio, 1); // Deactivate CS
    gpioTerminate();
    printf("Cleanup complete. Exiting.\n");
}

