// Initialize pigpio library
int init_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }
    return 0;
}

// Initialize SPI interface
int init_spi() {
    spi_handle = spiOpen(config.spi_channel, config.spi_speed, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        return 1;
    }
    return 0;
}

// Initialize CS GPIO as output
int init_cs_gpio() {
    gpioSetMode(config.cs_gpio, PI_OUTPUT);
    gpioWrite(config.cs_gpio, 1); // Deactivate chip select initially
    return 0;
}

// Read data from MAX31865
int read_max31865(unsigned char *data) {
    char tx_buf[4] = {0x00, 0x00, 0x00, 0x00}; // Dummy data for reading
    char rx_buf[4];

    gpioWrite(config.cs_gpio, 0); // Activate chip select
    gpioDelay(1); // Small delay after CS activation

    int result = spiXfer(spi_handle, tx_buf, rx_buf, 4);
    if (result != 4) {
        fprintf(stderr, "SPI transfer failed: %d\n", result);
        gpioWrite(config.cs_gpio, 1); // Deactivate chip select
        return 1;
    }

    gpioWrite(config.cs_gpio, 1); // Deactivate chip select
    gpioDelay(1); // Small delay after CS deactivation

    memcpy(data, rx_buf, 4);
    return 0;
}

// Check fault status register
int check_fault_status(unsigned char *data) {
    if (data[3] & 0x01) {
        fprintf(stderr, "Sensor absent fault detected.\n");
        return 1;
    }
    if (data[3] & 0x02) {
        fprintf(stderr, "SPI bus error detected.\n");
        return 1;
    }
    return 0;
}

// Calculate temperature using Callendar-Van Dusen equation
double calculate_temperature(unsigned char *data) {
    unsigned int rtd_raw = ((data[0] << 8) | data[1]) >> 1; // Extract RTD value (13 bits)
    double rtd_resistance = (double)rtd_raw * 430.0 / 16383.0; // Convert to resistance (assuming 430 Ohm reference resistor)

    // Callendar-Van Dusen equation for PT100 (simplified)
    double temperature = (rtd_resistance - 100.0) / 0.385; // Linear approximation

    return temperature;
}

// Log temperature to file
int log_temperature(double temperature) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f\n", timestamp, temperature);
    fflush(log_file); // Ensure data is written to disk
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup resources
void cleanup() {
    printf("Cleaning up...\n");
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioWrite(config.cs_gpio, 1); // Deactivate CS
    gpioTerminate();
    printf("Cleanup complete. Exiting.\n");
}

