    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(fp, "%s,%.2f,%.2f,%.2f\n", timestamp, temperature, humidity, pressure);
    fflush(fp); // Ensure data is written to disk immediately

    return 0;
}

// Signal handler function
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, exiting...\n");
    terminate = 1;
}

int main() {
    float temperature, humidity, pressure;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C device
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    // Specify the address of the slave device
    if (ioctl(i2c_fd, I2C_SLAVE, BME280_I2C_ADDR) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        close(i2c_fd);
        return 1;
    }

    // Initialize the BME280 sensor
    if (bme280_init(i2c_fd) != 0) {
        fprintf(stderr, "BME280 initialization failed\n");
        close(i2c_fd);
        return 1;
    }

    // Open the log file
    log_file = fopen("bme280_log.csv", "a");
    if (log_file == NULL) {
