        close(i2c_fd);
        return 1;
    }

    // Write the CSV header if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "timestamp,temperature_C,humidity_percent,pressure_hPa\n");
    }

    // Main loop
    while (!terminate) {
        // Read data from the BME280 sensor
        if (bme280_read_data(i2c_fd, &temperature, &humidity, &pressure) == 0) {
            // Log the data to the CSV file
            log_data(log_file, temperature, humidity, pressure);
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }

        sleep(5);
    }

    // Close the log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Close the I2C device
    close(i2c_fd);

    return 0;
}

