#define BMP180_REG_MB 0xBA
#define BMP180_REG_MC 0xBC
#define BMP180_REG_MD 0xBE

// Oversampling setting (OSS)
#define BMP180_OSS 0 // Ultra-low power

// GPIO pin for alert
#define ALERT_GPIO 24

// Circular buffer size (60 seconds * 20 Hz = 1200 samples)
#define BUFFER_SIZE 1200

// Global variables
int i2c_handle;
double pressure_buffer[BUFFER_SIZE];
int buffer_index = 0;
int buffer_count = 0;
