void alert_gpio_on();
void alert_gpio_off();
void signal_handler(int signal);

// Function to initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(1, BMP180_ADDR, 0); // I2C bus 1, address 0x77, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to read calibration data from the BMP180
int read_calibration_data() {
    char data[22];
    if (i2cReadI2CBlockData(i2c_handle, BMP180_REG_AC1, data, 22) != 22) {
        fprintf(stderr, "Error reading calibration data\n");
        return -1;
    }

    ac1 = (data[0] << 8) | data[1];
    ac2 = (data[2] << 8) | data[3];
    ac3 = (data[4] << 8) | data[5];
    ac4 = (data[6] << 8) | data[7];
    ac5 = (data[8] << 8) | data[9];
    ac6 = (data[10] << 8) | data[11];
    b1 = (data[12] << 8) | data[13];
    b2 = (data[14] << 8) | data[15];
    mb = (data[16] << 8) | data[17];
    mc = (data[18] << 8) | data[19];
    md = (data[20] << 8) | data[21];

    return 0;
}

// Function to read raw temperature data from the BMP180
int read_raw_temperature() {
    char data[2];
    if (i2cWriteByteData(i2c_handle, BMP180_REG_CONTROL, 0x2E) != 0) {
        fprintf(stderr, "Error writing temperature conversion command\n");
        return -1;
    }
    gpioDelay(5); // Wait 4.5ms
    if (i2cReadI2CBlockData(i2c_handle, BMP180_REG_MSB, data, 2) != 2) {
        fprintf(stderr, "Error reading raw temperature data\n");
        return -1;
    }
    return (data[0] << 8) | data[1];
}

// Function to read raw pressure data from the BMP180
int read_raw_pressure() {
    char data[3];
    if (i2cWriteByteData(i2c_handle, BMP180_REG_CONTROL, 0x34 + (BMP180_OSS << 6)) != 0) {
        fprintf(stderr, "Error writing pressure conversion command\n");
        return -1;
    }
    gpioDelay(5); // Wait 4.5ms (OSS=0)
    if (i2cReadI2CBlockData(i2c_handle, BMP180_REG_MSB, data, 3) != 3) {
        fprintf(stderr, "Error reading raw pressure data\n");
        return -1;
    }
    return ((data[0] << 16) | (data[1] << 8) | data[2]) >> (8 - BMP180_OSS);
}

// Function to calculate pressure in hPa
double calculate_pressure(int raw_temperature, int raw_pressure) {
    long x1, x2, x3, b3, b5, b6, p;
    unsigned long b4, b7;

    b5 = (((long)raw_temperature - (long)ac6) * (long)ac5) >> 15;
