// Function to update the circular buffer
void update_circular_buffer(double pressure) {
    pressure_buffer[buffer_index] = pressure;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
    if (buffer_count < BUFFER_SIZE) {
        buffer_count++;
    }
}

// Function to calculate the rolling average
double calculate_rolling_average() {
    if (buffer_count == 0) {
        return 0.0;
    }

    double sum = 0.0;
    for (int i = 0; i < buffer_count; i++) {
        sum += pressure_buffer[i];
    }
    return sum / buffer_count;
}

// Function to check for pressure deviation
void check_pressure_deviation(double current_pressure) {
    double rolling_average_new = calculate_rolling_average();

    if (fabs(current_pressure - rolling_average_new) > 5.0) {
        if (!alert_active) {
            alert_gpio_on();
            alert_active = 1;
            fprintf(stderr, "ALERT: Pressure deviation detected! Current: %.2f hPa, Rolling Average: %.2f hPa\n", current_pressure, rolling_average_new);
        }
    } else {
        if (alert_active) {
            alert_gpio_off();
            alert_active = 0;
        }
    }

    rolling_average = rolling_average_new;
}

// Function to turn the alert GPIO on
void alert_gpio_on() {
    gpioWrite(ALERT_GPIO, 1); // Set GPIO HIGH
}

// Function to turn the alert GPIO off
void alert_gpio_off() {
    gpioWrite(ALERT_GPIO, 0); // Set GPIO LOW
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    fprintf(stderr, "Caught signal %d, cleaning up...\n", signal);
    i2cClose(i2c_handle);
    gpioWrite(ALERT_GPIO, 0); // Ensure GPIO is LOW on exit
    gpioTerminate();
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO24 as output
    gpioSetMode(ALERT_GPIO, PI_OUTPUT);

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Read calibration data
    if (read_calibration_data() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (1) {
        int raw_temperature = read_raw_temperature();
        int raw_pressure = read_raw_pressure();

        if (raw_temperature != -1 && raw_pressure != -1) {
            double pressure = calculate_pressure(raw_temperature, raw_pressure);
            printf("Pressure: %.2f hPa\n", pressure);
            update_circular_buffer(pressure);
            check_pressure_deviation(pressure);
        } else {
            fprintf(stderr, "Error reading sensor data\n");
        }

        gpioDelay(50); // Sample every 50 ms
    }

    return 0;
}

