#include <unistd.h>
#include <pigpio.h>

// BMP180 I2C address
#define BMP180_ADDR 0x77

// BMP180 registers
#define BMP180_REG_CONTROL 0xF4
#define BMP180_REG_MSB 0xF6
#define BMP180_REG_LSB 0xF7
#define BMP180_REG_XLSB 0xF8

// Calibration data registers
#define BMP180_REG_CAL_AC1 0xAA
#define BMP180_REG_CAL_AC2 0xAC
#define BMP180_REG_CAL_AC3 0xAE
#define BMP180_REG_CAL_AC4 0xB0
#define BMP180_REG_CAL_AC5 0xB2
#define BMP180_REG_CAL_AC6 0xB4
#define BMP180_REG_CAL_B1 0xB6
#define BMP180_REG_CAL_B2 0xB8
#define BMP180_REG_CAL_MB 0xBA
#define BMP180_REG_CAL_MC 0xBC
#define BMP180_REG_CAL_MD 0xBE

// Oversampling setting (0 = ultra low power)
#define BMP180_OSS 0

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Calibration data
int16_t ac1, ac2, ac3, b1, b2, mb, mc, md;
uint16_t ac4, ac5, ac6;

// Function prototypes
int init_i2c();
int read_calibration_data();
int read_raw_temperature(int *raw_temp);
int read_raw_pressure(int *raw_pressure);
double calculate_temperature(int raw_temp);
double calculate_pressure(int raw_pressure, double temperature);
void log_data(double temperature, double pressure);
void signal_handler(int signal);

// Function to initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(1, BMP180_ADDR, 0); // Bus 1, address 0x77, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to read calibration data from the BMP180
int read_calibration_data() {
    char buf[22];
    if (i2cReadI2CBlockData(i2c_handle, BMP180_REG_CAL_AC1, buf, 22) != 22) {
        fprintf(stderr, "Error reading calibration data\n");
        return -1;
    }

    ac1 = (buf[0] << 8) | buf[1];
    ac2 = (buf[2] << 8) | buf[3];
    ac3 = (buf[4] << 8) | buf[5];
    ac4 = (buf[6] << 8) | buf[7];
    ac5 = (buf[8] << 8) | buf[9];
    ac6 = (buf[10] << 8) | buf[11];
    b1 = (buf[12] << 8) | buf[13];
    b2 = (buf[14] << 8) | buf[15];
    mb = (buf[16] << 8) | buf[17];
    mc = (buf[18] << 8) | buf[19];
    md = (buf[20] << 8) | buf[21];

    return 0;
}

// Function to read raw temperature data from the BMP180
int read_raw_temperature(int *raw_temp) {
    char buf[2];
    char control_buf[2];

    control_buf[0] = BMP180_REG_CONTROL;
    control_buf[1] = 0x2E; // Temperature measurement command

    if (i2cWriteI2CBlockData(i2c_handle, BMP180_REG_CONTROL, control_buf + 1, 1) != 1) {
        fprintf(stderr, "Error writing temperature command\n");
        return -1;
    }

    gpioDelay(5000); // Wait 5ms

    control_buf[0] = BMP180_REG_MSB;
    if (i2cWriteI2CBlockData(i2c_handle, BMP180_REG_MSB, control_buf, 1) != 1) {
        fprintf(stderr, "Error writing register address for temperature read\n");
        return -1;
    }

    if (i2cReadI2CBlockData(i2c_handle, BMP180_REG_MSB, buf, 2) != 2) {
        fprintf(stderr, "Error reading raw temperature data\n");
        return -1;
    }

    *raw_temp = (buf[0] << 8) | buf[1];
    return 0;
}

// Function to read raw pressure data from the BMP180
int read_raw_pressure(int *raw_pressure) {
    char buf[3];
    char control_buf[2];

    control_buf[0] = BMP180_REG_CONTROL;
    control_buf[1] = 0x34 + (BMP180_OSS << 6); // Pressure measurement command

    if (i2cWriteI2CBlockData(i2c_handle, BMP180_REG_CONTROL, control_buf + 1, 1) != 1) {
        fprintf(stderr, "Error writing pressure command\n");
        return -1;
    }

    gpioDelay(2 + (3 << BMP180_OSS)) ; // Wait 2.5ms (OSS = 0)

    control_buf[0] = BMP180_REG_MSB;
    if (i2cWriteI2CBlockData(i2c_handle, BMP180_REG_MSB, control_buf, 1) != 1) {
        fprintf(stderr, "Error writing register address for pressure read\n");
        return -1;
    }

    if (i2cReadI2CBlockData(i2c_handle, BMP180_REG_MSB, buf, 3) != 3) {
        fprintf(stderr, "Error reading raw pressure data\n");
        return -1;
    }

    *raw_pressure = ((unsigned long)buf[0] << 16 | (unsigned long)buf[1] << 8 | (unsigned long)buf[2]) >> (8 - BMP180_OSS);
    return 0;
}

// Function to calculate temperature in degrees Celsius
double calculate_temperature(int raw_temp) {
    long x1 = ((long)raw_temp - (long)ac6) * ((long)ac5) / pow(2, 15);
    long x2 = ((long)mc * pow(2, 11)) / (x1 + md);
    long b5 = x1 + x2;
    double temperature = (b5 + 8) / pow(2, 4) / 10.0;
    return temperature;
}

// Function to calculate pressure in Pascals
double calculate_pressure(int raw_pressure, double temperature) {
    long b6 = (long)temperature * 10 - 4000;
    long x1 = ((long)b1 * (b6 * b6 / pow(2, 12))) / pow(2, 11);
    long x2 = ((long)ac2 * b6) / pow(2, 11);
    long x3 = x1 + x2;
    long b3 = (((((long)ac1) * 4 + x3) << BMP180_OSS) + 2) / 4;
    unsigned long b4 = ((unsigned long)ac4 * (unsigned long)(x3 + 32768)) / pow(2, 15);
    unsigned long b7 = ((unsigned long)raw_pressure - b3) * (50000 >> BMP180_OSS);
    long p;
    if (b7 < 0x80000000) {
        p = (b7 * 2) / b4;
    } else {
        p = (b7 / b4) * 2;
    }
    x1 = (p / pow(2, 8)) * (p / pow(2, 8));
    x1 = (x1 * 3038) / pow(2, 16);
    x2 = (-7357 * p) / pow(2, 16);
    double pressure = p + (x1 + x2 + 3791) / pow(2, 4);
    return pressure;
}

// Function to log data to a file
void log_data(double temperature, double pressure) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, %.2f, %.2f\n", timestamp, temperature, pressure);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Read calibration data
    if (read_calibration_data() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("bmp180_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int raw_temp, raw_pressure;
    double temperature, pressure;

    // Main loop
    while (!terminate) {
        // Read raw temperature and pressure
        if (read_raw_temperature(&raw_temp) == 0 && read_raw_pressure(&raw_pressure) == 0) {
            // Calculate temperature and pressure
            temperature = calculate_temperature(raw_temp);
            pressure = calculate_pressure(raw_pressure, temperature);

            // Log data
            log_data(temperature, pressure);

            printf("Temperature: %.2f C, Pressure: %.2f Pa\n", temperature, pressure);
        } else {
            fprintf(stderr, "Error reading sensor data\n");
        }

        gpioDelay(500000); // Wait 500ms
    }

    // Clean up
    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

