#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define FAN_GPIO 18
#define PWM_FREQUENCY 25000
#define TEMP_FILE "/sys/class/thermal/thermal_zone0/temp"
#define LOG_FILE "fan_log.txt"

volatile sig_atomic_t program_running = 1;
FILE *log_fp = NULL;

void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully.\n", signal);
}

float read_cpu_temperature() {
    FILE *fp;
    char temp_str[10];
    float temperature = -1.0;

    fp = fopen(TEMP_FILE, "r");
    if (fp == NULL) {
        perror("Failed to open temperature file");
        return -1.0;
    }

    if (fgets(temp_str, sizeof(temp_str), fp) != NULL) {
        temperature = atoi(temp_str) / 1000.0;
    } else {
        perror("Failed to read temperature from file");
    }

    fclose(fp);
    return temperature;
}

int calculate_duty_cycle(float temperature) {
    int duty_cycle;

    if (temperature < 40.0) {
        duty_cycle = 0;
    } else if (temperature > 70.0) {
        duty_cycle = 255;
    } else {
        duty_cycle = (int)(((temperature - 40.0) / (70.0 - 40.0)) * 255.0);
    }

    return duty_cycle;
}

int set_fan_speed(int duty_cycle) {
    if (gpioPWM(FAN_GPIO, duty_cycle) != 0) {
        fprintf(stderr, "Failed to set fan speed to %d\n", duty_cycle);
        return -1;
    }
    return 0;
}

int log_data(float temperature, int duty_cycle) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_fp != NULL) {
        fprintf(log_fp, "%s, Temperature: %.2f°C, Duty Cycle: %d\n", timestamp, temperature, duty_cycle);
        fflush(log_fp); // Ensure data is written to disk immediately
        return 0;
    } else {
        fprintf(stderr, "Log file not opened.\n");
        return -1;
    }
}

int main() {
    float temperature;
    int duty_cycle;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO mode and PWM frequency
    gpioSetMode(FAN_GPIO, PI_OUTPUT);
    gpioSetPWMfrequency(FAN_GPIO, PWM_FREQUENCY);
    gpioSetPWMrange(FAN_GPIO, 255);

    // Open log file
    log_fp = fopen(LOG_FILE, "a");
    if (log_fp == NULL) {
        perror("Failed to open log file");
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Fan control program started. Press Ctrl+C to exit.\n");

    while (program_running) {
        temperature = read_cpu_temperature();
        if (temperature < 0) {
            fprintf(stderr, "Failed to read temperature, using previous value.\n");
        } else {
            duty_cycle = calculate_duty_cycle(temperature);
            if (set_fan_speed(duty_cycle) != 0) {
                fprintf(stderr, "Failed to set fan speed.\n");
            }
            if (log_data(temperature, duty_cycle) != 0) {
                fprintf(stderr, "Failed to log data.\n");
            }
        }

        sleep(5);
    }

    // Cleanup
    printf("Stopping fan and cleaning up...\n");
    set_fan_speed(0); // Stop the fan
    if (log_fp != NULL) {
        fclose(log_fp);
    }
    gpioTerminate();

    printf("Exiting.\n");
    return 0;
}

