#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <sys/time.h>
#include <pigpio.h>
#include <jansson.h>
#include <math.h>

// Constants
#define GPIO_HEATER 18
#define SPI_CHANNEL 0
#define SPI_SPEED 500000
#define PWM_FREQUENCY 1000
#define PWM_RANGE 1000
#define TARGET_TEMP_DEFAULT 25.0
#define Kp_DEFAULT 1.0
#define Ki_DEFAULT 0.1
#define Kd_DEFAULT 0.01
#define MAX_TEMP 80.0
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 10

// Global variables
static volatile int running = 1;
static int spi_handle;
static double target_temperature = TARGET_TEMP_DEFAULT;
static double Kp = Kp_DEFAULT;
static double Ki = Ki_DEFAULT;
static double Kd = Kd_DEFAULT;
static double last_error = 0.0;
static double integral = 0.0;
static double last_time = 0.0;

// Function prototypes
void signal_handler(int signal);
int read_config(const char *filename, double *target_temperature, double *Kp, double *Ki, double *Kd);
int spi_read_register(int handle, unsigned char address, unsigned char *data, int len);
int spi_write_register(int handle, unsigned char address, unsigned char data);
double read_temperature();
double pid_control(double current_temperature);
void set_pwm_duty_cycle(double duty_cycle);
void log_error(const char *message);

// Signal handler
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

// Read configuration from JSON file
int read_config(const char *filename, double *target_temperature, double *Kp, double *Ki, double *Kd) {
    json_t *root;
    json_error_t error;

    root = json_load_file(filename, 0, &error);
    if (!root) {
        fprintf(stderr, "Error: Could not load config file: %s\n", error.text);
        return -1;
    }

    json_t *target_temp_json = json_object_get(root, "target_temperature");
    json_t *kp_json = json_object_get(root, "Kp");
    json_t *ki_json = json_object_get(root, "Ki");
    json_t *kd_json = json_object_get(root, "Kd");

    if (!json_is_real(target_temp_json) || !json_is_real(kp_json) || !json_is_real(ki_json) || !json_is_real(kd_json)) {
        fprintf(stderr, "Error: Invalid values in config file\n");
        json_decref(root);
        return -1;
    }

    *target_temperature = json_real_value(target_temp_json);
    *Kp = json_real_value(kp_json);
    *Ki = json_real_value(ki_json);
    *Kd = json_real_value(kd_json);

    json_decref(root);
    return 0;
}

// Read data from MAX31865 register
int spi_read_register(int handle, unsigned char address, unsigned char *data, int len) {
    char tx[len + 1];
    char rx[len + 1];

    tx[0] = address | 0x80; // Read bit set
    for (int i = 1; i <= len; i++) {
        tx[i] = 0x00; // Dummy data for reading
    }

    if (spiXfer(handle, tx, rx, len + 1) != 0) {
        log_error("SPI read failed");
        return -1;
    }

    for (int i = 0; i < len; i++) {
        data[i] = rx[i + 1];
    }

    return 0;
}

// Write data to MAX31865 register
int spi_write_register(int handle, unsigned char address, unsigned char data) {
    char tx[2];
    char rx[2];

    tx[0] = address & 0x7F; // Write bit clear
    tx[1] = data;

    if (spiXfer(handle, tx, rx, 2) != 0) {
        log_error("SPI write failed");
        return -1;
    }

    return 0;
}

// Read temperature from MAX31865
double read_temperature() {
    unsigned char msb, lsb;
    int rtd_code;
    double resistance, temperature;
    int retries = 0;

    while (retries < MAX_RETRIES) {
        if (spi_read_register(spi_handle, 0x01, &msb, 1) != 0) {
            log_error("Failed to read MSB");
            retries++;
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
            continue;
        }

        if (spi_read_register(spi_handle, 0x02, &lsb, 1) != 0) {
            log_error("Failed to read LSB");
            retries++;
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
            continue;
        }

        rtd_code = ((msb << 8) | lsb) >> 1; // Shift right by 1 bit

        // Check for fault bit (D0 of MSB)
        if (msb & 0x01) {
            unsigned char fault_status;
            if (spi_read_register(spi_handle, 0x07, &fault_status, 1) != 0) {
                log_error("Failed to read fault status");
                retries++;
                gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
                continue;
            }

            if (fault_status & 0x01) {
                log_error("RTD Open");
                return -1000.0; // Indicate RTD open fault
            } else if (fault_status & 0x02) {
                log_error("RTD Short to GND");
                return -1000.0; // Indicate RTD short to GND fault
            } else if (fault_status & 0x04) {
                log_error("RTD Short to VCC");
                return -1000.0; // Indicate RTD short to VCC fault
            } else if (fault_status & 0x08) {
                log_error("VBIAS Overvoltage");
                return -1000.0; // Indicate VBIAS overvoltage fault
            } else if (fault_status & 0x10) {
                log_error("VBIAS Undervoltage");
                return -1000.0; // Indicate VBIAS undervoltage fault
            }
        }

        resistance = ((double)rtd_code / 32768.0) * 430.0; // R_rtd = (code / 32768) * R_ref

        // Callendar-Van Dusen equation (for t >= 0)
        double A = 3.9083e-3;
        double B = -5.775e-7;
        temperature = (sqrt(pow(A, 2) - 4 * B * (1 - resistance / 100.0)) - A) / (2 * B);

        return temperature;
    }

    log_error("Max retries reached for temperature reading");
    return -1000.0; // Indicate failure
}

// PID control loop
double pid_control(double current_temperature) {
    double error = target_temperature - current_temperature;
    double derivative = (error - last_error) / (time_time() - last_time);
    last_time = time_time();
    last_error = error;

    integral += error * (time_time() - last_time);

    // Limit integral term to prevent windup
    double integral_limit = 100.0; // Adjust as needed
    if (integral > integral_limit) integral = integral_limit;
    if (integral < -integral_limit) integral = -integral_limit;

    double output = Kp * error + Ki * integral + Kd * derivative;

    // Clamp output to 0-100%
    if (output < 0.0) output = 0.0;
    if (output > 100.0) output = 100.0;

    return output;
}

// Set PWM duty cycle
void set_pwm_duty_cycle(double duty_cycle) {
    int duty = (int)(duty_cycle * PWM_RANGE / 100.0);
    gpioPWM(GPIO_HEATER, duty);
}

// Log errors to stderr
void log_error(const char *message) {
    struct timeval tv;
    gettimeofday(&tv, NULL);
    time_t nowtime = tv.tv_sec;
    struct tm *nowtm = localtime(&nowtime);
    char tmbuf[64], buf[256];
    strftime(tmbuf, sizeof(tmbuf), "%Y-%m-%d %H:%M:%S", nowtm);
    snprintf(buf, sizeof(buf), "%s.%06ld: %s\n", tmbuf, tv.tv_usec, message);
    fprintf(stderr, "%s", buf);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO18 as output
    gpioSetMode(GPIO_HEATER, PI_OUTPUT);

    // Set PWM frequency and range
    gpioSetPWMfrequency(GPIO_HEATER, PWM_FREQUENCY);
    gpioSetPWMrange(GPIO_HEATER, PWM_RANGE);

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // SPI mode 0
    if (spi_handle < 0) {
        log_error("Failed to open SPI channel");
        gpioTerminate();
        return 1;
    }

    // Initialize MAX31865 (write to config register)
    if (spi_write_register(spi_handle, 0x80, 0xC1) != 0) {
        log_error("Failed to initialize MAX31865");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Read configuration from file
    if (read_config("config.json", &target_temperature, &Kp, &Ki, &Kd) != 0) {
        fprintf(stderr, "Warning: Could not read config.json, using default values\n");
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    struct timeval last_temp_read_time;
    gettimeofday(&last_temp_read_time, NULL);

    // Main loop
    while (running) {
        double current_temperature = read_temperature();

        if (current_temperature < -999.0) {
            log_error("Failed to read temperature, shutting down");
            set_pwm_duty_cycle(0.0);
            spiClose(spi_handle);
            gpioTerminate();
            return 1;
        }

        double pid_output = pid_control(current_temperature);
        set_pwm_duty_cycle(pid_output);

        struct timeval current_time;
        gettimeofday(&current_time, NULL);
        double time_elapsed = (current_time.tv_sec - last_temp_read_time.tv_sec) + (current_time.tv_usec - last_temp_read_time.tv_usec) / 1000000.0;

        if (time_elapsed >= 0.1) {
            last_temp_read_time = current_time;
        }

        gpioDelay(100000); // 100ms delay
    }

    // Cleanup
    set_pwm_duty_cycle(0.0);
    spiClose(spi_handle);
    gpioTerminate();

    return 0;
}

