        double B = -5.775e-7;
        temperature = (sqrt(pow(A, 2) - 4 * B * (1 - resistance / 100.0)) - A) / (2 * B);

        return temperature;
    }

    log_error("Max retries reached for temperature reading");
    return -1000.0; // Indicate failure
}

// PID control loop
double pid_control(double current_temperature) {
    double error = target_temperature - current_temperature;
    double derivative = (error - last_error) / (time_time() - last_time);
    last_time = time_time();
    last_error = error;

    integral += error * (time_time() - last_time);

    // Limit integral term to prevent windup
    double integral_limit = 100.0; // Adjust as needed
    if (integral > integral_limit) integral = integral_limit;
    if (integral < -integral_limit) integral = -integral_limit;

    double output = Kp * error + Ki * integral + Kd * derivative;

    // Clamp output to 0-100%
    if (output < 0.0) output = 0.0;
    if (output > 100.0) output = 100.0;

    return output;
}

// Set PWM duty cycle
void set_pwm_duty_cycle(double duty_cycle) {
    int duty = (int)(duty_cycle * PWM_RANGE / 100.0);
    gpioPWM(GPIO_HEATER, duty);
}

// Log errors to stderr
void log_error(const char *message) {
    struct timeval tv;
    gettimeofday(&tv, NULL);
    time_t nowtime = tv.tv_sec;
    struct tm *nowtm = localtime(&nowtime);
    char tmbuf[64], buf[256];
    strftime(tmbuf, sizeof(tmbuf), "%Y-%m-%d %H:%M:%S", nowtm);
    snprintf(buf, sizeof(buf), "%s.%06ld: %s\n", tmbuf, tv.tv_usec, message);
    fprintf(stderr, "%s", buf);
}

int main() {
