    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO18 as output
    gpioSetMode(GPIO_HEATER, PI_OUTPUT);

    // Set PWM frequency and range
    gpioSetPWMfrequency(GPIO_HEATER, PWM_FREQUENCY);
    gpioSetPWMrange(GPIO_HEATER, PWM_RANGE);

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // SPI mode 0
    if (spi_handle < 0) {
        log_error("Failed to open SPI channel");
        gpioTerminate();
        return 1;
    }

    // Initialize MAX31865 (write to config register)
    if (spi_write_register(spi_handle, 0x80, 0xC1) != 0) {
        log_error("Failed to initialize MAX31865");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Read configuration from file
    if (read_config("config.json", &target_temperature, &Kp, &Ki, &Kd) != 0) {
        fprintf(stderr, "Warning: Could not read config.json, using default values\n");
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    struct timeval last_temp_read_time;
    gettimeofday(&last_temp_read_time, NULL);

    // Main loop
    while (running) {
        double current_temperature = read_temperature();

        if (current_temperature < -999.0) {
            log_error("Failed to read temperature, shutting down");
            set_pwm_duty_cycle(0.0);
            spiClose(spi_handle);
            gpioTerminate();
            return 1;
        }

        double pid_output = pid_control(current_temperature);
        set_pwm_duty_cycle(pid_output);

        struct timeval current_time;
        gettimeofday(&current_time, NULL);
        double time_elapsed = (current_time.tv_sec - last_temp_read_time.tv_sec) + (current_time.tv_usec - last_temp_read_time.tv_usec) / 1000000.0;

        if (time_elapsed >= 0.1) {
            last_temp_read_time = current_time;
        }

        gpioDelay(100000); // 100ms delay
    }

    // Cleanup
    set_pwm_duty_cycle(0.0);
    spiClose(spi_handle);
    gpioTerminate();

    return 0;
}

