// BMP180 I2C address
#define BMP180_ADDR 0x77

// BMP180 registers
#define BMP180_REG_CONTROL 0xF4
#define BMP180_REG_MSB 0xF6
#define BMP180_REG_LSB 0xF7
#define BMP180_REG_XLSB 0xF8

// Calibration data registers
#define BMP180_REG_CAL_AC1 0xAA
#define BMP180_REG_CAL_AC2 0xAC
#define BMP180_REG_CAL_AC3 0xAE
#define BMP180_REG_CAL_AC4 0xB0
#define BMP180_REG_CAL_AC5 0xB2
#define BMP180_REG_CAL_AC6 0xB4
#define BMP180_REG_CAL_B1 0xB6
#define BMP180_REG_CAL_B2 0xB8
#define BMP180_REG_CAL_MB 0xBA
#define BMP180_REG_CAL_MC 0xBC
#define BMP180_REG_CAL_MD 0xBE

// Oversampling setting (0, 1, 2, or 3)
#define BMP180_OSS 0

// Temperature and pressure thresholds
#define TEMP_THRESHOLD 30.0f
#define PRESSURE_THRESHOLD 950.0f

// I2C bus file descriptor
int i2c_fd = -1;

// Calibration data
int16_t ac1, ac2, ac3, b1, b2, mb, mc, md;
uint16_t ac4, ac5, ac6;

// Function prototypes
int i2c_read_bytes(int fd, uint8_t reg, uint8_t *buf, int len);
int i2c_write_byte(int fd, uint8_t reg, uint8_t value);
int read_calibration_data(int fd);
int read_raw_temperature(int fd);
int read_raw_pressure(int fd);
float calculate_temperature(int raw_temp);
float calculate_pressure(int raw_pressure, int raw_temp);
void log_breach(float temperature, float pressure);
void signal_handler(int sig);

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    if (sig == SIGINT || sig == SIGTERM) {
        fprintf(stderr, "\nCaught signal %d, exiting gracefully.\n", sig);
        if (i2c_fd != -1) {
            close(i2c_fd);
        }
        exit(0);
    }
}

// Function to read multiple bytes from I2C
int i2c_read_bytes(int fd, uint8_t reg, uint8_t *buf, int len) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "Error writing register address: %s\n", strerror(errno));
        return -1;
    }
    if (read(fd, buf, len) != len) {
        fprintf(stderr, "Error reading bytes: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Function to write a single byte to I2C
int i2c_write_byte(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2];
    buf[0] = reg;
    buf[1] = value;
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "Error writing byte: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Function to read calibration data from the BMP180
int read_calibration_data(int fd) {
    uint8_t buf[22];
    if (i2c_read_bytes(fd, BMP180_REG_CAL_AC1, buf, 22) != 0) {
        fprintf(stderr, "Error reading calibration data\n");
        return -1;
    }

    ac1 = (buf[0] << 8) | buf[1];
    ac2 = (buf[2] << 8) | buf[3];
    ac3 = (buf[4] << 8) | buf[5];
    ac4 = (buf[6] << 8) | buf[7];
    ac5 = (buf[8] << 8) | buf[9];
    ac6 = (buf[10] << 8) | buf[11];
    b1 = (buf[12] << 8) | buf[13];
    b2 = (buf[14] << 8) | buf[15];
    mb = (buf[16] << 8) | buf[17];
    mc = (buf[18] << 8) | buf[19];
    md = (buf[20] << 8) | buf[21];

    return 0;
}

// Function to read raw temperature data from the BMP180
int read_raw_temperature(int fd) {
    uint8_t buf[2];
    buf[0] = 0x2E; // Temperature measurement command

    if (i2c_write_byte(fd, BMP180_REG_CONTROL, buf[0]) != 0) {
        fprintf(stderr, "Error writing temperature measurement command\n");
        return -1;
    }

    usleep(5000); // Wait 4.5ms (minimum)

    if (i2c_read_bytes(fd, BMP180_REG_MSB, buf, 2) != 0) {
        fprintf(stderr, "Error reading raw temperature data\n");
        return -1;
    }

    return (buf[0] << 8) | buf[1];
}

// Function to read raw pressure data from the BMP180
int read_raw_pressure(int fd) {
    uint8_t buf[2];
    buf[0] = 0x34 + (BMP180_OSS << 6); // Pressure measurement command

    if (i2c_write_byte(fd, BMP180_REG_CONTROL, buf[0]) != 0) {
        fprintf(stderr, "Error writing pressure measurement command\n");
        return -1;
    }

    usleep(26000); // Wait 25.5ms (maximum for OSS = 3)

    uint8_t data[3];
    if (i2c_read_bytes(fd, BMP180_REG_MSB, data, 3) != 0) {
        fprintf(stderr, "Error reading raw pressure data\n");
        return -1;
    }

    return ((data[0] << 16) | (data[1] << 8) | data[2]) >> (8 - BMP180_OSS);
}

// Function to calculate temperature in degrees Celsius
float calculate_temperature(int raw_temp) {
    long x1 = ((long)raw_temp - (long)ac6) * ((long)ac5) / pow(2, 15);
    long x2 = ((long)mc * pow(2, 11)) / (x1 + md);
    long b5 = x1 + x2;
    float temperature = (b5 + 8) / pow(2, 4) / 10.0f;
    return temperature;
}

// Function to calculate pressure in hPa
float calculate_pressure(int raw_pressure, int raw_temp) {
    long x1 = ((long)raw_temp - (long)ac6) * ((long)ac5) / pow(2, 15);
    long x2 = ((long)mc * pow(2, 11)) / (x1 + md);
    long b5 = x1 + x2;

    long b6 = b5 - 4000;
    long x3 = ((long)b2 * (b6 * b6) / pow(2, 12)) / pow(2, 11);
    long x4 = ((long)ac2 * b6) / pow(2, 11);
    long b3 = (((((long)ac1) * 4 + x3) << BMP180_OSS) + 2) / 4;

    unsigned long x1_u = ((unsigned long)ac3 * b6) / pow(2, 13);
    unsigned long x2_u = ((unsigned long)b1 * ((b6 * b6) / pow(2, 12))) / pow(2, 16);
    unsigned long x3_u = ((x1_u + x2_u) + 2) / pow(2, 2);
    unsigned long b4 = ((unsigned long)ac4 * (x3_u + 32768)) / pow(2, 15);

    unsigned long b7 = ((unsigned long)raw_pressure - b3) * (50000 >> BMP180_OSS);
    long p;
    if (b7 < 0x80000000) {
        p = (b7 * 2) / b4;
    } else {
        p = (b7 / b4) * 2;
    }

    x1 = (p / pow(2, 8)) * (p / pow(2, 8));
    x1 = (x1 * 3038) / pow(2, 16);
    x2 = (-7357 * p) / pow(2, 16);
    float pressure = p + (x1 + x2 + 3791) / pow(2, 4);
    return pressure / 100.0f; // Convert to hPa
}

// Function to log temperature and pressure breaches to a file
void log_breach(float temperature, float pressure) {
    FILE *fp = fopen("breach_log.txt", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening breach_log.txt: %s\n", strerror(errno));
        return;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char s[64];
    strftime(s, sizeof(s), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s - Temperature: %.2f°C, Pressure: %.2f hPa\n", s, temperature, pressure);
    fclose(fp);
}

int main() {
    // Register signal handler for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C bus
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C bus: %s\n", strerror(errno));
        return 1;
    }

    // Specify the address of the slave device
    if (ioctl(i2c_fd, I2C_SLAVE, BMP180_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    // Read calibration data
    if (read_calibration_data(i2c_fd) != 0) {
        fprintf(stderr, "Failed to read calibration data. Exiting.\n");
        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (1) {
        int raw_temp, raw_pressure;
        float temperature, pressure;

        // Read raw temperature and pressure
        raw_temp = read_raw_temperature(i2c_fd);
        if (raw_temp < 0) {
            fprintf(stderr, "Failed to read raw temperature. Retrying...\n");
            usleep(100000); // Wait 100ms before retrying
            continue;
        }

        raw_pressure = read_raw_pressure(i2c_fd);
        if (raw_pressure < 0) {
            fprintf(stderr, "Failed to read raw pressure. Retrying...\n");
            usleep(100000); // Wait 100ms before retrying
            continue;
        }

        // Calculate temperature and pressure
        temperature = calculate_temperature(raw_temp);
        pressure = calculate_pressure(raw_pressure, raw_temp);

        // Log breaches
        if (temperature > TEMP_THRESHOLD || pressure < PRESSURE_THRESHOLD) {
            log_breach(temperature, pressure);
        }

        printf("Temperature: %.2f°C, Pressure: %.2f hPa\n", temperature, pressure);

        sleep(1); // Sample every 1 second
    }

    // Close I2C bus (this will never be reached in the infinite loop)
    close(i2c_fd);
    return 0;
}

