#define BMP180_REG_AC3 0xAE
#define BMP180_REG_AC4 0xB0
#define BMP180_REG_AC5 0xB2
#define BMP180_REG_AC6 0xB4
#define BMP180_REG_B1 0xB6
#define BMP180_REG_B2 0xB8
#define BMP180_REG_MB 0xBA
#define BMP180_REG_MC 0xBC
#define BMP180_REG_MD 0xBE

// Fan GPIO pin
#define FAN_PIN 18

// Temperature threshold for fan control (in Celsius)
#define TEMPERATURE_THRESHOLD 30.0

// Circular buffer size
#define BUFFER_SIZE 60

// Structure to hold BMP180 calibration data
typedef struct {
    int16_t ac1;
    int16_t ac2;
    int16_t ac3;
    uint16_t ac4;
    uint16_t ac5;
    uint16_t ac6;
    int16_t b1;
    int16_t b2;
    int16_t mb;
    int16_t mc;
    int16_t md;
} bmp180_calibration_data_t;

// Structure to hold temperature and pressure readings
typedef struct {
    time_t timestamp;
    float temperature;
    float pressure;
} reading_t;

// Circular buffer structure
typedef struct {
    reading_t buffer[BUFFER_SIZE];
    int head;
    int count;
} circular_buffer_t;

// Global variables
int i2c_handle;
bmp180_calibration_data_t calibration_data;
circular_buffer_t reading_buffer;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_calibration_data(int i2c_handle, bmp180_calibration_data_t *calibration_data);
int read_raw_temperature(int i2c_handle);
int read_raw_pressure(int i2c_handle);
float calculate_true_temperature(int raw_temperature, bmp180_calibration_data_t calibration_data);
float calculate_true_pressure(int raw_pressure, int raw_temperature, bmp180_calibration_data_t calibration_data);
void add_reading(circular_buffer_t *buffer, reading_t reading);
reading_t get_latest_reading(circular_buffer_t *buffer);
void control_fan(float temperature);
void timer_callback(int timer_id, void *user_data);
void signal_handler(int signal);
void init_circular_buffer(circular_buffer_t *buffer);

// Function to read calibration data from the BMP180
int read_calibration_data(int i2c_handle, bmp180_calibration_data_t *calibration_data) {
    uint8_t buffer[22];
    if (i2cReadI2CBlockData(i2c_handle, BMP180_REG_AC1, (char *)buffer, 22) != 22) {
        fprintf(stderr, "Error reading calibration data\n");
        return -1;
    }

    calibration_data->ac1 = (buffer[0] << 8) | buffer[1];
    calibration_data->ac2 = (buffer[2] << 8) | buffer[3];
    calibration_data->ac3 = (buffer[4] << 8) | buffer[5];
    calibration_data->ac4 = (buffer[6] << 8) | buffer[7];
    calibration_data->ac5 = (buffer[8] << 8) | buffer[9];
    calibration_data->ac6 = (buffer[10] << 8) | buffer[11];
    calibration_data->b1 = (buffer[12] << 8) | buffer[13];
    calibration_data->b2 = (buffer[14] << 8) | buffer[15];
    calibration_data->mb = (buffer[16] << 8) | buffer[17];
    calibration_data->mc = (buffer[18] << 8) | buffer[19];
    calibration_data->md = (buffer[20] << 8) | buffer[21];

    return 0;
}

// Function to read raw temperature data from the BMP180
int read_raw_temperature(int i2c_handle) {
    char buf[2];
    buf[0] = BMP180_REG_CONTROL;
    buf[1] = 0x2E; // Temperature measurement command

    if (i2cWriteDevice(i2c_handle, buf, 2) != 0) {
        fprintf(stderr, "Error writing temperature command\n");
        return -1;
    }

    gpioDelay(5000); // Wait 5ms

    buf[0] = BMP180_REG_MSB;
    if (i2cWriteDevice(i2c_handle, buf, 1) != 0) {
        fprintf(stderr, "Error writing temperature read command\n");
        return -1;
    }

    if (i2cReadDevice(i2c_handle, buf, 2) != 2) {
        fprintf(stderr, "Error reading raw temperature data\n");
        return -1;
    }

    return (buf[0] << 8) | buf[1];
}

// Function to read raw pressure data from the BMP180
int read_raw_pressure(int i2c_handle) {
    char buf[2];
    buf[0] = BMP180_REG_CONTROL;
    buf[1] = 0x34; // Pressure measurement command (OSS = 0)

    if (i2cWriteDevice(i2c_handle, buf, 2) != 0) {
        fprintf(stderr, "Error writing pressure command\n");
        return -1;
    }

    gpioDelay(5000); // Wait 5ms

    buf[0] = BMP180_REG_MSB;
    if (i2cWriteDevice(i2c_handle, buf, 1) != 0) {
        fprintf(stderr, "Error writing pressure read command\n");
        return -1;
    }

    char data[3];
    if (i2cReadDevice(i2c_handle, data, 3) != 3) {
        fprintf(stderr, "Error reading raw pressure data\n");
        return -1;
    }

    return ((data[0] << 16) | (data[1] << 8) | data[2]) >> 8;
}

// Function to calculate true temperature in Celsius
float calculate_true_temperature(int raw_temperature, bmp180_calibration_data_t calibration_data) {
    long x1 = ((long)raw_temperature - (long)calibration_data.ac6) * ((long)calibration_data.ac5) / pow(2, 15);
    long x2 = ((long)calibration_data.mc * pow(2, 11)) / (x1 + calibration_data.md);
    long b5 = x1 + x2;
    float temperature = (b5 + 8) / pow(2, 4) / 10.0;
    return temperature;
}

// Function to calculate true pressure in Pascals
float calculate_true_pressure(int raw_pressure, int raw_temperature, bmp180_calibration_data_t calibration_data) {
    long x1 = ((long)raw_temperature - (long)calibration_data.ac6) * ((long)calibration_data.ac5) / pow(2, 15);
    long x2 = ((long)calibration_data.mc * pow(2, 11)) / (x1 + calibration_data.md);
    long b5 = x1 + x2;

    long b6 = b5 - 4000;
    long x3 = ((long)calibration_data.b2 * (b6 * b6) / pow(2, 12)) / pow(2, 11);
    long x4 = ((long)calibration_data.ac2 * b6) / pow(2, 11);
    long b3 = (((long)calibration_data.ac1 * 4 + x3 + x4 + 2) / 4);

    unsigned long x1_pressure = ((unsigned long)calibration_data.ac3 * b6) / pow(2, 13);
    unsigned long x2_pressure = ((unsigned long)calibration_data.b1 * ((b6 * b6) / pow(2, 12))) / pow(2, 16);
    unsigned long x3_pressure = ((x1_pressure + x2_pressure + 2) / 4);
    unsigned long b4 = ((unsigned long)calibration_data.ac4 * (x3_pressure + 32768)) / pow(2, 15);

    unsigned long b7 = ((unsigned long)raw_pressure - b3) * (50000);
    long p;
    if (b7 < 0x80000000) {
        p = (b7 * 2) / b4;
    } else {
        p = (b7 / b4) * 2;
    }

    x1 = (p / pow(2, 8)) * (p / pow(2, 8));
    x1 = (x1 * 3038) / pow(2, 16);
    x2 = (-7357 * p) / pow(2, 16);
    float pressure = p + (x1 + x2 + 3791) / pow(2, 4);
    return pressure;
}

// Function to add a reading to the circular buffer
void add_reading(circular_buffer_t *buffer, reading_t reading) {
    buffer->buffer[buffer->head] = reading;
    buffer->head = (buffer->head + 1) % BUFFER_SIZE;
    if (buffer->count < BUFFER_SIZE) {
        buffer->count++;
    }
}

// Function to get the latest reading from the circular buffer
reading_t get_latest_reading(circular_buffer_t *buffer) {
    int index = (buffer->head - 1 + BUFFER_SIZE) % BUFFER_SIZE;
    return buffer->buffer[index];
}

// Function to control the cooling fan
void control_fan(float temperature) {
    if (temperature > TEMPERATURE_THRESHOLD) {
        gpioWrite(FAN_PIN, 1); // Turn fan on
    } else {
        gpioWrite(FAN_PIN, 0); // Turn fan off
    }
}

// Timer callback function
void timer_callback(int timer_id, void *user_data) {
    int raw_temperature, raw_pressure;
    float temperature, pressure;
    reading_t reading;

    raw_temperature = read_raw_temperature(i2c_handle);
    if (raw_temperature == -1) {
        fprintf(stderr, "Error reading raw temperature, skipping sample\n");
        return;
    }

    raw_pressure = read_raw_pressure(i2c_handle);
    if (raw_pressure == -1) {
        fprintf(stderr, "Error reading raw pressure, skipping sample\n");
        return;
    }

    temperature = calculate_true_temperature(raw_temperature, calibration_data);
    pressure = calculate_true_pressure(raw_pressure, raw_temperature, calibration_data);

    reading.timestamp = time(NULL);
    reading.temperature = temperature;
    reading.pressure = pressure;

    add_reading(&reading_buffer, reading);

    printf("%ld,%.2f,%.2f\n", reading.timestamp, reading.temperature, reading.pressure);

    control_fan(temperature);
}

// Signal handler function
void signal_handler(int signal) {
    fprintf(stderr, "Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Function to initialize the circular buffer
void init_circular_buffer(circular_buffer_t *buffer) {
    buffer->head = 0;
    buffer->count = 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, BMP180_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus\n");
        gpioTerminate();
        return 1;
    }

    // Read calibration data
    if (read_calibration_data(i2c_handle, &calibration_data) != 0) {
        fprintf(stderr, "Error reading calibration data, exiting\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize circular buffer
    init_circular_buffer(&reading_buffer);

    // Set fan pin as output
    gpioSetMode(FAN_PIN, PI_OUTPUT);

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Set up hardware timer callback
    gpioSetTimerFuncEx(0, 500, timer_callback, NULL);

    // Main loop
    while (!terminate) {
        gpioDelay(100); // Sleep for 100ms to reduce CPU usage
    }

    // Cleanup
    gpioWrite(FAN_PIN, 0); // Turn fan off
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

