        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    pigpio_initialized = 1;
    return 0;
}

// Function to initialize the I2C connection
int init_i2c() {
    i2c_handle = i2cOpen(1, BMP180_ADDR, 0); // Bus 1, address 0x77, no flags
