#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define HEATER_PIN 17
#define SPI_CE0 8
#define SPI_MISO 9
#define SPI_MOSI 10
#define SPI_SCLK 11

// Define SPI parameters
#define SPI_CHANNEL 0
#define SPI_SPEED 2000000 // 2 MHz

// Define PI controller parameters
#define KP 1.0
#define KI 0.1
#define INTEGRAL_LIMIT 100.0

// Define PWM parameters
#define PWM_FREQUENCY 1000 // 1 kHz
#define MAX_DUTY_CYCLE 80.0 // 80%

// Define target temperature
#define TARGET_TEMPERATURE 25.0

// Define log file name
#define LOG_FILE "heater_log.csv"

// Define error codes
#define SPI_ERROR -1
#define THERMOCOUPLE_ERROR -2

// Global variables
static volatile int running = 1;
static int spi_handle;
static FILE *log_file;

// Function prototypes
double read_temperature();
double calculate_duty_cycle(double current_temperature);
void set_heater_duty_cycle(double duty_cycle);
void log_data(double temperature, double duty_cycle);
void signal_handler(int signal);
int initialize();
void cleanup();

// Structure to hold PI controller state
typedef struct {
    double integral;
} PIControllerState;

PIControllerState pi_state = {0.0};

// Function to read temperature from MAX31855
double read_temperature() {
    unsigned char data[4];
    int result;

    result = spiRead(spi_handle, (char *)data, 4);
    if (result != 4) {
        fprintf(stderr, "SPI read error: %d\n", result);
        log_data(0.0, 0.0); // Log error
        return SPI_ERROR;
    }

    // Check for thermocouple fault
    if (data[3] & 0x07) {
        fprintf(stderr, "Thermocouple fault detected!\n");
        if (data[3] & 0x01) fprintf(stderr, "  Open circuit\n");
        if (data[3] & 0x02) fprintf(stderr, "  Short to GND\n");
        if (data[3] & 0x04) fprintf(stderr, "  Short to VCC\n");
        log_data(0.0, 0.0); // Log error
        return THERMOCOUPLE_ERROR;
    }

    // Extract temperature data (bits 31:18)
    int16_t raw_temp = ((data[0] << 8) | data[1]) >> 2;

    // Convert to Celsius
    double temperature = raw_temp * 0.25;

    return temperature;
}

// Function to calculate PWM duty cycle using PI controller
double calculate_duty_cycle(double current_temperature) {
    double error = TARGET_TEMPERATURE - current_temperature;

    pi_state.integral += error;

    // Anti-windup
    if (pi_state.integral > INTEGRAL_LIMIT) {
        pi_state.integral = INTEGRAL_LIMIT;
    } else if (pi_state.integral < -INTEGRAL_LIMIT) {
        pi_state.integral = -INTEGRAL_LIMIT;
    }

    double output = KP * error + KI * pi_state.integral;

    // Limit duty cycle to 0-100%
    if (output < 0.0) {
        output = 0.0;
    } else if (output > 100.0) {
        output = 100.0;
    }

    return output;
}

// Function to set heater duty cycle
void set_heater_duty_cycle(double duty_cycle) {
    if (duty_cycle > MAX_DUTY_CYCLE) {
        duty_cycle = MAX_DUTY_CYCLE;
    }
    gpioPWM(HEATER_PIN, (int)(duty_cycle * 255.0 / 100.0)); // pigpio uses 0-255 range
}

// Function to log data to file
void log_data(double temperature, double duty_cycle) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, temperature, duty_cycle);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    running = 0;
}

// Initialization function
int initialize() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(HEATER_PIN, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(HEATER_PIN, PWM_FREQUENCY);

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // CE0, 2 MHz, mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Write header to log file if it's a new file
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Temperature(C),DutyCycle(%%)\n");
    }

    return 0;
}

// Cleanup function
void cleanup() {
    // Turn off heater
    set_heater_duty_cycle(0.0);

    // Close SPI
    spiClose(spi_handle);

    // Close log file
    fclose(log_file);

    // Terminate pigpio
    gpioTerminate();
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize
    if (initialize()) {
        return 1;
    }

    printf("Temperature control started. Press Ctrl+C to exit.\n");

    while (running) {
        double temperature = read_temperature();

        if (temperature == SPI_ERROR || temperature == THERMOCOUPLE_ERROR) {
            // Handle SPI or thermocouple error
            set_heater_duty_cycle(0.0);
            sleep(1); // Wait before retrying
            continue;
        }

        double duty_cycle = calculate_duty_cycle(temperature);
        set_heater_duty_cycle(duty_cycle);
        log_data(temperature, duty_cycle);

        printf("Temperature: %.2f C, Duty Cycle: %.2f %%\n", temperature, duty_cycle);

        sleep(1); // Control loop frequency
    }

    // Cleanup and exit
    cleanup();
    printf("Temperature control stopped.\n");
    return 0;
}

