// Define GPIO pins for RGB LED (common anode)
#define RED_PIN   17
#define GREEN_PIN 18
#define BLUE_PIN  27

// Temperature file path
#define TEMP_FILE "/sys/class/thermal/thermal_zone0/temp"

// Global flag for signal handling
volatile sig_atomic_t terminate = 0;

// Signal handler function
void signal_handler(int sig)
{
    terminate = 1;
}

// Function to read CPU temperature from file
int read_cpu_temp()
{
    int fd;
    char temp_str[10];
    int temp_mC;

    fd = open(TEMP_FILE, O_RDONLY);
    if (fd < 0) {
        perror("Error opening temperature file");
        return -1;
    }

    if (read(fd, temp_str, sizeof(temp_str) - 1) < 0) {
        perror("Error reading temperature file");
        close(fd);
        return -1;
    }

    close(fd);
    temp_str[sizeof(temp_str) - 1] = '\0'; // Ensure null termination
    temp_mC = atoi(temp_str);

    return temp_mC;
}

// Function to set RGB LED color using PWM
void set_rgb_color(int red, int green, int blue)
{
    gpioPWM(RED_PIN, 255 - red);
    gpioPWM(GREEN_PIN, 255 - green);
    gpioPWM(BLUE_PIN, 255 - blue);
}

// Function to determine RGB color based on temperature
void determine_color(int temp_mC, int *red, int *green, int *blue)
{
    if (temp_mC < 40000) {
        *red = 0;
        *green = 0;
        *blue = 255;
    } else if (temp_mC < 60000) {
        *red = 0;
        *green = 255;
        *blue = 0;
    } else {
        *red = 255;
        *green = 0;
        *blue = 0;
    }
}

int main()
{
    int temp_mC;
    int red, green, blue;

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins to output mode
    gpioSetMode(RED_PIN, PI_OUTPUT);
    gpioSetMode(GREEN_PIN, PI_OUTPUT);
    gpioSetMode(BLUE_PIN, PI_OUTPUT);

    // Set PWM range (0-255)
    gpioSetPWMrange(RED_PIN, 255);
    gpioSetPWMrange(GREEN_PIN, 255);
    gpioSetPWMrange(BLUE_PIN, 255);

    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        // Read CPU temperature
        temp_mC = read_cpu_temp();

        if (temp_mC == -1) {
            fprintf(stderr, "Error reading temperature, skipping update\n");
            sleep(0.5);
            continue;
        }

        // Determine RGB color based on temperature
        determine_color(temp_mC, &red, &green, &blue);

        // Set RGB LED color
        set_rgb_color(red, green, blue);

        // Print temperature and RGB values
        printf("Temperature: %d m°C, R: %d, G: %d, B: %d\n", temp_mC, red, green, blue);

        // Wait for 0.5 seconds
        sleep(0.5);
    }

    // Cleanup and exit
    printf("Cleaning up and exiting...\n");
    set_rgb_color(255, 255, 255); // Turn off all LEDs
    gpioTerminate();
    return 0;
}

