#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <sys/time.h>
#include <pigpio.h>
#include <curl/curl.h>

#define DHT22_GPIO 4
#define SERVER_URL "http://yourserver.com/api/humidity"
#define MAX_RETRIES 3
#define RETRY_DELAY_SEC 5

// Structure to hold sensor data
typedef struct {
    float temperature;
    float humidity;
} SensorData;

// Global flag to signal program termination
volatile sig_atomic_t terminate = 0;

// Signal handler function
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, terminating program...\n");
    terminate = 1;
}

// Function to read DHT22 sensor data using bit-banging
int read_dht22(int gpio, float *temperature, float *humidity) {
    int data[5] = {0, 0, 0, 0, 0};
    int bit_count = 0;
    int i, j;

    // Send start signal
    gpioSetMode(gpio, PI_OUTPUT);
    gpioWrite(gpio, 0);
    gpioDelay(1000); // 1 ms
    gpioWrite(gpio, 1);
    gpioDelay(30); // 30 us

    // Switch to input mode and read data
    gpioSetMode(gpio, PI_INPUT);
    gpioSetPullUpDown(gpio, PI_PUD_UP);

    // Wait for response (low for ~80us, then high for ~80us)
    int timeout = 0;
    while (gpioRead(gpio) == 1) {
        gpioDelay(1); // Wait 1 us
        timeout++;
        if (timeout > 100) return -1; // Timeout
    }

    timeout = 0;
    while (gpioRead(gpio) == 0) {
        gpioDelay(1); // Wait 1 us
        timeout++;
        if (timeout > 100) return -1; // Timeout
    }

    timeout = 0;
    while (gpioRead(gpio) == 1) {
        gpioDelay(1); // Wait 1 us
        timeout++;
        if (timeout > 100) return -1; // Timeout
    }

    // Read 40 bits of data
    for (i = 0; i < 5; i++) {
        for (j = 0; j < 8; j++) {
            timeout = 0;
            while (gpioRead(gpio) == 0) {
                gpioDelay(1); // Wait 1 us
                timeout++;
                if (timeout > 100) return -1; // Timeout
            }

            long start = gpioTick();
            timeout = 0;
            while (gpioRead(gpio) == 1) {
                gpioDelay(1); // Wait 1 us
                timeout++;
                if (timeout > 100) return -1; // Timeout
            }
            long end = gpioTick();

            if ((end - start) > 40) {
                data[i] |= (1 << (7 - j));
            }
        }
    }

    // Validate checksum
    if ((data[0] + data[1] + data[2] + data[3]) & 0xFF != data[4]) {
        fprintf(stderr, "Checksum error\n");
        return -2;
    }

    // Convert data to temperature and humidity
    *humidity = (float)((data[0] << 8) + data[1]) / 10.0;
    *temperature = (float)(((data[2] & 0x7F) << 8) + data[3]) / 10.0;
    if (data[2] & 0x80) {
        *temperature = -*temperature;
    }

    return 0;
}

// Function to format sensor data as a JSON string
int format_json(float temperature, float humidity, char *json_string, size_t buffer_size) {
    int ret = snprintf(json_string, buffer_size, "{\"temperature\": %.1f, \"humidity\": %.1f}", temperature, humidity);
    if (ret < 0 || ret >= buffer_size) {
        fprintf(stderr, "Error formatting JSON\n");
        return -1;
    }
    return 0;
}

// Function to send data to the server using libcurl
int send_data(const char *url, const char *json_data) {
    CURL *curl;
    CURLcode res;
    struct curl_slist *headers = NULL;

    curl_global_init(CURL_GLOBAL_ALL);
    curl = curl_easy_init();
    if (curl) {
        curl_easy_setopt(curl, CURLOPT_URL, url);
        curl_easy_setopt(curl, CURLOPT_POST, 1L);
        curl_easy_setopt(curl, CURLOPT_POSTFIELDS, json_data);

        // Set content type to application/json
        headers = curl_slist_append(headers, "Content-Type: application/json");
        curl_easy_setopt(curl, CURLOPT_HTTPHEADER, headers);

        res = curl_easy_perform(curl);
        if (res != CURLE_OK) {
            fprintf(stderr, "curl_easy_perform() failed: %s\n", curl_easy_strerror(res));
        } else {
            long response_code;
            curl_easy_getinfo(curl, CURLINFO_RESPONSE_CODE, &response_code);
            if (response_code >= 400) {
                fprintf(stderr, "HTTP request failed with code: %ld\n", response_code);
            }
        }

        curl_easy_cleanup(curl);
        curl_slist_free_all(headers);
    } else {
        fprintf(stderr, "Error initializing libcurl\n");
        curl_global_cleanup();
        return -1;
    }
    curl_global_cleanup();
    return (res == CURLE_OK) ? 0 : -1;
}

int main() {
    float temperature, humidity;
    char json_string[128];
    int retries = 0;
    int result;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        // Read sensor data
        result = read_dht22(DHT22_GPIO, &temperature, &humidity);
        if (result == 0) {
            // Format data as JSON
            if (format_json(temperature, humidity, json_string, sizeof(json_string)) == 0) {
                // Send data to server
                if (send_data(SERVER_URL, json_string) != 0) {
                    fprintf(stderr, "Failed to send data to server\n");
                }
            } else {
                fprintf(stderr, "Failed to format JSON data\n");
            }
        } else {
            fprintf(stderr, "Failed to read sensor data (error code: %d)\n", result);
        }

        // Wait for 5 seconds
        sleep(5);
    }

    // Clean up pigpio
    gpioTerminate();

    return 0;
}

