#define BMP180_REG_CAL_AC6 0xB4
#define BMP180_REG_CAL_B1 0xB6
#define BMP180_REG_CAL_B2 0xB8
#define BMP180_REG_CAL_MB 0xBA
#define BMP180_REG_CAL_MC 0xBC
#define BMP180_REG_CAL_MD 0xBE

// Oversampling setting
#define BMP180_OSS 3

// GPIO pin for button interrupt
#define BUTTON_GPIO 4

// Global variables
static int i2c_handle;
static volatile int logging_enabled = 0;
static volatile uint32_t last_interrupt_time = 0;
static volatile uint32_t current_interrupt_time = 0;

// Calibration coefficients
static int16_t ac1, ac2, ac3, b1, b2, mb, mc, md;
static uint16_t ac4, ac5, ac6;

// Function prototypes
int init_pigpio();
int init_i2c();
int read_calibration_data();
int validate_calibration_data();
int read_raw_temperature();
int read_raw_pressure();
double calculate_temperature(int ut);
double calculate_pressure(int up, int ut);
void log_data(double pressure);
void button_interrupt_handler(int gpio, int level, uint32_t tick, void *user_data);
void signal_handler(int signal);

// Function to initialize pigpio
int init_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Function to initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(1, BMP180_ADDR, 0); // Bus 1, address 0x77, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to read calibration data from BMP180
int read_calibration_data() {
    char buf[22];
    if (i2cReadI2CBlockData(i2c_handle, BMP180_REG_CAL_AC1, buf, 22) != 22) {
        fprintf(stderr, "Failed to read calibration data\n");
        return -1;
    }

    ac1 = (buf[0] << 8) | buf[1];
    ac2 = (buf[2] << 8) | buf[3];
    ac3 = (buf[4] << 8) | buf[5];
    ac4 = (buf[6] << 8) | buf[7];
    ac5 = (buf[8] << 8) | buf[9];
    ac6 = (buf[10] << 8) | buf[11];
    b1 = (buf[12] << 8) | buf[13];
    b2 = (buf[14] << 8) | buf[15];
    mb = (buf[16] << 8) | buf[17];
    mc = (buf[18] << 8) | buf[19];
    md = (buf[20] << 8) | buf[21];

    return 0;
}

// Function to validate calibration data
int validate_calibration_data() {
    // Basic validation: check if the values are within a reasonable range
    if (ac1 == 0 || ac2 == 0 || ac3 == 0 || ac4 == 0 || ac5 == 0 || ac6 == 0 ||
        b1 == 0 || b2 == 0 || mb == 0 || mc == 0 || md == 0) {
        fprintf(stderr, "Invalid calibration data\n");
        return -1;
    }
    return 0;
}

// Function to read raw temperature value
int read_raw_temperature() {
    char buf[2];
    char control_value = 0x2E; // Temperature measurement command

    if (i2cWriteByteData(i2c_handle, BMP180_REG_CONTROL, control_value) != 0) {
        fprintf(stderr, "Failed to write temperature measurement command\n");
        return -1;
    }

    gpioDelay(5000); // Wait 5ms

    if (i2cReadI2CBlockData(i2c_handle, BMP180_REG_MSB, buf, 2) != 2) {
        fprintf(stderr, "Failed to read raw temperature data\n");
        return -1;
    }

    return (buf[0] << 8) | buf[1];
}

// Function to read raw pressure value
int read_raw_pressure() {
    char buf[3];
    char control_value = 0x34 + (BMP180_OSS << 6); // Pressure measurement command

    if (i2cWriteByteData(i2c_handle, BMP180_REG_CONTROL, control_value) != 0) {
        fprintf(stderr, "Failed to write pressure measurement command\n");
        return -1;
    }

    gpioDelay(26000); // Wait 26ms (OSS=3)

    if (i2cReadI2CBlockData(i2c_handle, BMP180_REG_MSB, buf, 3) != 3) {
        fprintf(stderr, "Failed to read raw pressure data\n");
        return -1;
    }

    return ((buf[0] << 16) | (buf[1] << 8) | buf[2]) >> (8 - BMP180_OSS);
}

// Function to calculate temperature in degrees Celsius
double calculate_temperature(int ut) {
    long x1 = ((long)ut - (long)ac6) * ((long)ac5) / pow(2, 15);
    long x2 = ((long)mc * pow(2, 11)) / (x1 + md);
    long b5 = x1 + x2;
    double temperature = (b5 + 8) / pow(2, 4) / 10.0;
    return temperature;
}

// Function to calculate pressure in hPa
double calculate_pressure(int up, int ut) {
    long x1 = ((long)ut - (long)ac6) * ((long)ac5) / pow(2, 15);
    long x2 = ((long)mc * pow(2, 11)) / (x1 + md);
    long b5 = x1 + x2;

    long b6 = b5 - 4000;
    long x3 = ((long)b2 * (b6 * b6) / pow(2, 12)) / pow(2, 11);
    long x4 = ((long)ac2 * b6) / pow(2, 11);
    long b3 = (((((long)ac1) * 4 + x3) << BMP180_OSS) + 2) / 4;

    unsigned long x1_pressure = ((unsigned long)ac3 * b6) / pow(2, 13);
    unsigned long x2_pressure = ((unsigned long)b1 * ((b6 * b6) / pow(2, 12))) / pow(2, 16);
    unsigned long x3_pressure = ((x1_pressure + x2_pressure + 2) / 4);
    unsigned long b4 = ((unsigned long)ac4 * (x3_pressure + 32768)) / pow(2, 15);

    unsigned long b7 = ((unsigned long)up - b3) * (50000 >> BMP180_OSS);
    long pressure;
    if (b7 < 0x80000000)
    {
        pressure = (b7 * 2) / b4;
    }
    else
    {
        pressure = (b7 / b4) * 2;
    }

    x1 = (pressure / pow(2, 8)) * (pressure / pow(2, 8));
    x1 = (x1 * 3038) / pow(2, 16);
    x2 = (-7357 * pressure) / pow(2, 16);
    double pressure_hpa = pressure + (x1 + x2 + 3791) / pow(2, 4);
    return pressure_hpa;
}

// Function to log data to file
void log_data(double pressure) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    FILE *fp = fopen("pressure_log.txt", "a");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        return;
    }

    fprintf(fp, "%s, %.2f hPa\n", timestamp, pressure);
    fclose(fp);
}

// Function to handle button interrupt
void button_interrupt_handler(int gpio, int level, uint32_t tick, void *user_data) {
    current_interrupt_time = tick;
    if (current_interrupt_time - last_interrupt_time > 200000) {
        logging_enabled = !logging_enabled;
        printf("Logging %s\n", logging_enabled ? "enabled" : "disabled");
        last_interrupt_time = current_interrupt_time;
    }
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    i2cClose(i2c_handle);
    gpioTerminate();
    exit(0);
}

int main() {
    // Initialize pigpio
    if (init_pigpio() != 0) {
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Read calibration data
    if (read_calibration_data() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Validate calibration data
    if (validate_calibration_data() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO4 as input with pull-up resistor
    gpioSetMode(BUTTON_GPIO, PI_INPUT);
    gpioSetPullUpDown(BUTTON_GPIO, PI_PUD_UP);

    // Set interrupt handler for falling edge
    gpioSetISRFuncEx(BUTTON_GPIO, FALLING_EDGE, 0, button_interrupt_handler, NULL);

    // Set signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Press the button on GPIO4 to toggle logging.\n");

    // Main loop
    while (1) {
        if (logging_enabled) {
            int ut = read_raw_temperature();
            int up = read_raw_pressure();

            if (ut != -1 && up != -1) {
                double temperature = calculate_temperature(ut);
                double pressure = calculate_pressure(up, ut);
                log_data(pressure);
                printf("Temperature: %.2f C, Pressure: %.2f hPa\n", temperature, pressure);
            } else {
                fprintf(stderr, "Failed to read sensor data\n");
            }
        } else {
            printf("Logging is currently disabled.\n");
        }

        gpioDelay(2000000); // Wait 2 seconds
    }

    return 0;
}

