#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <syslog.h>
#include <time.h>
#include <sys/time.h>
#include <pigpio.h>
#include <curl/curl.h>
#include <getopt.h>

#define DHT22_GPIO 4
#define DEFAULT_SERVER_URL "http://your-server.com/api/humidity"
#define MAX_RETRIES 3
#define BACKOFF_DELAY 2 // seconds

// Structure to hold DHT22 data
typedef struct {
    float humidity;
    float temperature;
    int valid;
} DHT22Data;

// Global variables
static volatile int running = 1;
static char *server_url = DEFAULT_SERVER_URL;

// Function prototypes
DHT22Data read_dht22_data();
int validate_checksum(unsigned char *data);
int post_humidity_data(float humidity);
void signal_handler(int sig);
void log_message(int priority, const char *message);

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    running = 0;
    log_message(LOG_INFO, "Signal received, shutting down...");
}

// Logging function using syslog
void log_message(int priority, const char *message) {
    syslog(priority, message);
    fprintf(stderr, "%s\n", message);
}

// Function to read data from DHT22 sensor
DHT22Data read_dht22_data() {
    DHT22Data data = {0.0, 0.0, 0};
    int i, j;
    unsigned int tick;
    unsigned char raw_data[5] = {0};

    // Send start signal
    gpioSetMode(DHT22_GPIO, PI_OUTPUT);
    gpioWrite(DHT22_GPIO, 0);
    gpioDelay(1); // > 1ms
    gpioWrite(DHT22_GPIO, 1);
    gpioDelay(30); // 20-40us

    gpioSetMode(DHT22_GPIO, PI_INPUT);

    // Read 40 bits of data
    for (i = 0; i < 5; i++) {
        for (j = 0; j < 8; j++) {
            // Wait for low
            while (gpioRead(DHT22_GPIO) == 0) {
                if (gpioTick() - tick > 100000) { // Timeout after 100ms
                    log_message(LOG_ERR, "DHT22 timeout waiting for low");
                    return data; // Return invalid data
                }
            }

            // Wait for high
            tick = gpioTick();
            while (gpioRead(DHT22_GPIO) == 1) {
                if (gpioTick() - tick > 100000) { // Timeout after 100ms
                    log_message(LOG_ERR, "DHT22 timeout waiting for high");
                    return data; // Return invalid data
                }
            }

            // Determine bit value based on high pulse length
            if (gpioTick() - tick > 40) {
                raw_data[i] |= (1 << (7 - j));
            }
        }
    }

    // Validate checksum
    if (validate_checksum(raw_data)) {
        // Convert data to humidity and temperature
        data.humidity = ((raw_data[0] << 8) | raw_data[1]) / 10.0;
        data.temperature = (((raw_data[2] & 0x7F) << 8) | raw_data[3]) / 10.0;
        if (raw_data[2] & 0x80) {
            data.temperature *= -1;
        }
        data.valid = 1;
    } else {
        log_message(LOG_ERR, "DHT22 checksum failure");
    }

    return data;
}

// Function to validate the checksum of the DHT22 data
int validate_checksum(unsigned char *data) {
    return (data[4] == ((data[0] + data[1] + data[2] + data[3]) & 0xFF));
}

// Function to post humidity data to the server
int post_humidity_data(float humidity) {
    CURL *curl;
    CURLcode res;
    char json_data[50];
    int retries = 0;

    snprintf(json_data, sizeof(json_data), "{\"humidity\": %.1f}", humidity);

    while (retries < MAX_RETRIES) {
        curl_global_init(CURL_GLOBAL_DEFAULT);
        curl = curl_easy_init();

        if (curl) {
            curl_easy_setopt(curl, CURLOPT_URL, server_url);
            curl_easy_setopt(curl, CURLOPT_POST, 1L);
            curl_easy_setopt(curl, CURLOPT_POSTFIELDS, json_data);
            curl_easy_setopt(curl, CURLOPT_POSTFIELDSIZE, (long)strlen(json_data));
            curl_easy_setopt(curl, CURLOPT_HTTPHEADER, "Content-Type: application/json");

            res = curl_easy_perform(curl);

            if (res == CURLE_OK) {
                long response_code;
                curl_easy_getinfo(curl, CURLINFO_RESPONSE_CODE, &response_code);

                if (response_code >= 200 && response_code < 300) {
                    log_message(LOG_INFO, "Humidity data posted successfully");
                    curl_easy_cleanup(curl);
                    curl_global_cleanup();
                    return 0; // Success
                } else {
                    char error_message[100];
                    snprintf(error_message, sizeof(error_message), "HTTP request failed with code: %ld", response_code);
                    log_message(LOG_ERR, error_message);
                }
            } else {
                log_message(LOG_ERR, curl_easy_strerror(res));
            }

            curl_easy_cleanup(curl);
        } else {
            log_message(LOG_ERR, "curl_easy_init() failed");
        }

        curl_global_cleanup();
        retries++;
        sleep(BACKOFF_DELAY * (1 << retries)); // Exponential backoff
    }

    log_message(LOG_ERR, "Failed to post humidity data after multiple retries");
    return -1; // Failure
}

int main(int argc, char *argv[]) {
    int opt;

    // Parse command-line arguments
    while ((opt = getopt(argc, argv, "s:")) != -1) {
        switch (opt) {
            case 's':
                server_url = optarg;
                break;
            default:
                fprintf(stderr, "Usage: %s [-s server_url]\n", argv[0]);
                exit(EXIT_FAILURE);
        }
    }

    // Initialize syslog
    openlog("dht22_monitor", LOG_PID | LOG_CONS, LOG_USER);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        log_message(LOG_ERR, "pigpio initialisation failed");
        closelog();
        return 1;
    }

    // Set signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    log_message(LOG_INFO, "DHT22 monitor started");

    // Main loop
    while (running) {
        DHT22Data dht22_data = read_dht22_data();

        if (dht22_data.valid) {
            if (post_humidity_data(dht22_data.humidity) != 0) {
