// Define paths for temperature and fan control
#define TEMP_PATH "/sys/class/thermal/thermal_zone0/temp"
#define MAX_STATE_PATH "/sys/class/thermal/cooling_device0/max_state"
#define CUR_STATE_PATH "/sys/class/thermal/cooling_device0/cur_state"
#define LOG_PATH "/var/log/fan_control.log"

// Define temperature thresholds and fan states
#define TEMP_THRESHOLD_1 45000
#define TEMP_THRESHOLD_2 55000
#define TEMP_THRESHOLD_3 65000

// Global variable for current fan state
static int current_fan_state = 0;

// Function prototypes
int read_temperature();
int read_max_state();
int write_fan_state(int state);
int log_fan_change(int state);
void signal_handler(int signum);

// Signal handler for graceful shutdown
void signal_handler(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        printf("Received signal %d, shutting down gracefully...\n", signum);
        log_fan_change(-1); // Log shutdown
        write_fan_state(0); // Turn off the fan
        exit(0);
    }
}

// Function to read CPU temperature from sysfs
int read_temperature() {
    FILE *fp;
    char buffer[10];
    int temperature = -1; // Initialize to an invalid value

    fp = fopen(TEMP_PATH, "r");
    if (fp == NULL) {
        perror("Failed to open temperature file");
        return -1;
    }

    if (fgets(buffer, sizeof(buffer), fp) == NULL) {
        perror("Failed to read temperature");
        fclose(fp);
        return -1;
    }

    fclose(fp);

    temperature = atoi(buffer);
    return temperature;
}

// Function to read the maximum fan state from sysfs
int read_max_state() {
    FILE *fp;
    char buffer[10];
    int max_state = -1; // Initialize to an invalid value

    fp = fopen(MAX_STATE_PATH, "r");
    if (fp == NULL) {
        perror("Failed to open max_state file");
        return -1;
    }

    if (fgets(buffer, sizeof(buffer), fp) == NULL) {
        perror("Failed to read max_state");
        fclose(fp);
        return -1;
    }

    fclose(fp);

    max_state = atoi(buffer);
    return max_state;
}

// Function to write the fan state to sysfs
int write_fan_state(int state) {
    FILE *fp;
    char buffer[10];
    int max_state = read_max_state();

    if (max_state == -1) {
        fprintf(stderr, "Error reading max_state, using default value 3\n");
        max_state = 3; // Default max state
    }

    if (state > max_state) {
        fprintf(stderr, "Requested fan state %d exceeds max_state %d, capping at %d\n", state, max_state, max_state);
        state = max_state;
    }

    fp = fopen(CUR_STATE_PATH, "w");
    if (fp == NULL) {
        perror("Failed to open cur_state file");
        return -1;
    }

    snprintf(buffer, sizeof(buffer), "%d", state);
    if (fputs(buffer, fp) == EOF) {
        perror("Failed to write fan state");
        fclose(fp);
        return -1;
    }

    fclose(fp);
    return 0;
}

// Function to log fan state changes to a file
int log_fan_change(int state) {
    FILE *fp;
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fp = fopen(LOG_PATH, "a");
    if (fp == NULL) {
        perror("Failed to open log file");
        return -1;
    }

    if (state == -1) {
        fprintf(fp, "%s - Shutting down fan control\n", timestamp);
    } else {
        fprintf(fp, "%s - Fan state: %d\n", timestamp, state);
    }

    fclose(fp);
    return 0;
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (1) {
        int temperature = read_temperature();
        if (temperature == -1) {
            fprintf(stderr, "Failed to read temperature, retrying in 5 seconds...\n");
            sleep(5);
            continue;
        }

        int fan_state;
        if (temperature < TEMP_THRESHOLD_1) {
            fan_state = 0;
        } else if (temperature < TEMP_THRESHOLD_2) {
            fan_state = 1;
        } else if (temperature < TEMP_THRESHOLD_3) {
            fan_state = 2;
        } else {
            fan_state = 3;
        }

        if (fan_state != current_fan_state) {
            if (write_fan_state(fan_state) == 0) {
                current_fan_state = fan_state;
                log_fan_change(fan_state);
            } else {
                fprintf(stderr, "Failed to set fan state, retrying in 5 seconds...\n");
            }
        }

        sleep(5);
    }

    return 0;
}

