    double output = Kp * error + Ki * integral + Kd * derivative;
    previous_error = error;
    return output;
}

// Function to set heater PWM duty cycle
void set_heater_pwm(double duty_cycle) {
    if (duty_cycle < 0.0) duty_cycle = 0.0;
    if (duty_cycle > 100.0) duty_cycle = 100.0;
    gpioPWM(HEATER_PIN, (int)(duty_cycle * 255.0 / 100.0)); // pigpio PWM range is 0-255
}

// Function to log data to file
void log_data(double temperature, double duty_cycle, double pid_output) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[26];
    strftime(timestamp, sizeof(timestamp)-1, "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s, Temperature: %.2f C, Duty Cycle: %.2f %%, PID Output: %.2f\n",
            timestamp, temperature, duty_cycle, pid_output);
    fflush(log_file); // Ensure data is written to file immediately
}

// Function to handle errors
void handle_error(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[26];
    strftime(timestamp, sizeof(timestamp)-1, "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s, ERROR: %s\n", timestamp, message);
    fflush(log_file);
    fprintf(stderr, "%s, ERROR: %s\n", timestamp, message);
    set_heater_pwm(0.0); // Disable heater
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    running = 0;
    set_heater_pwm(0.0); // Disable heater
    spiClose(spi_handle);
    gpioTerminate();
    fclose(log_file);
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open log file
    log_file = fopen("heater_log.txt", "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        gpioTerminate();
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(HEATER_PIN, PI_OUTPUT);
    gpioSetPWMfrequency(HEATER_PIN, PWM_FREQUENCY);
    gpioSetPWMrange(HEATER_PIN, 255);

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        handle_error("SPI open failed");
        gpioTerminate();
        fclose(log_file);
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (running) {
        double temperature = read_temperature();

        if (temperature > MAX_TEMPERATURE || temperature < MIN_TEMPERATURE) {
            handle_error("Temperature out of range");
            set_heater_pwm(0.0);
        } else {
            double pid_output = calculate_pid(TARGET_TEMPERATURE, temperature);
            double duty_cycle = pid_output; // Assuming PID output is directly proportional to duty cycle
            set_heater_pwm(duty_cycle);
            log_data(temperature, duty_cycle, pid_output);
        }

        gpioDelay(1000); // Wait 1 second
    }

    // Cleanup (should not reach here if signal handler works correctly)
    set_heater_pwm(0.0);
    spiClose(spi_handle);
    gpioTerminate();
    fclose(log_file);

    return 0;
}

