#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define GPIO_PIN 18
#define PWM_FREQUENCY 25000
#define TEMP_FILE "/sys/class/thermal/thermal_zone0/temp"
#define LOG_FILE "cooling_log.csv"

volatile sig_atomic_t program_running = 1;

void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to read CPU temperature from file
int read_cpu_temp() {
    FILE *fp;
    int temp_milli_celsius;

    fp = fopen(TEMP_FILE, "r");
    if (fp == NULL) {
        perror("Error opening temperature file");
        return -1; // Indicate error
    }

    if (fscanf(fp, "%d", &temp_milli_celsius) != 1) {
        fprintf(stderr, "Error reading temperature from file\n");
        fclose(fp);
        return -1; // Indicate error
    }

    fclose(fp);
    return temp_milli_celsius / 1000; // Convert to degrees Celsius
}

// Function to calculate PWM duty cycle based on temperature
int calculate_duty_cycle(int temperature) {
    int duty_cycle;

    if (temperature <= 40) {
        duty_cycle = 0;
    } else if (temperature >= 70) {
        duty_cycle = 100;
    } else {
        duty_cycle = (int)(((float)(temperature - 40) / (70 - 40)) * 100);
    }

    return duty_cycle;
}

// Function to set PWM duty cycle
int set_pwm_duty_cycle(int duty_cycle) {
    if (gpioPWM(GPIO_PIN, duty_cycle * 255 / 100) != 0) {
        fprintf(stderr, "Error setting PWM duty cycle\n");
        return -1; // Indicate error
    }
    return 0;
}

// Function to log data to CSV file
int log_data(int temperature, int duty_cycle) {
    FILE *fp;
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("Error opening log file");
        return -1; // Indicate error
    }

    fprintf(fp, "%s,%.2f,%d\n", timestamp, (float)temperature, duty_cycle);
    fclose(fp);
    return 0;
}

int main() {
    int temperature, duty_cycle;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pin to output mode
    gpioSetMode(GPIO_PIN, PI_OUTPUT);

    // Set PWM frequency
    if (gpioSetPWMfrequency(GPIO_PIN, PWM_FREQUENCY) != 0) {
        fprintf(stderr, "Error setting PWM frequency\n");
        gpioTerminate();
        return 1;
    }

    // Set PWM range (0-255)
    gpioSetPWMrange(GPIO_PIN, 255);

    // Install signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (program_running) {
        // Read CPU temperature
        temperature = read_cpu_temp();
        if (temperature == -1) {
            fprintf(stderr, "Error reading temperature, using previous value or exiting\n");
            // Consider adding a default temperature or exiting if temperature is critical
            continue; // Skip to the next iteration
        }

        // Calculate PWM duty cycle
        duty_cycle = calculate_duty_cycle(temperature);

        // Set PWM duty cycle
        if (set_pwm_duty_cycle(duty_cycle) != 0) {
            fprintf(stderr, "Error setting PWM duty cycle, continuing...\n");
        }

        // Log data
        if (log_data(temperature, duty_cycle) != 0) {
            fprintf(stderr, "Error logging data, continuing...\n");
        }

        // Wait 5 seconds
        gpioDelay(5000000); // 5 seconds in microseconds
    }

    // Shutdown sequence
    printf("Shutting down fan...\n");
    set_pwm_duty_cycle(0); // Turn off fan
    gpioTerminate();       // Terminate pigpio

    printf("Exiting.\n");
    return 0;
}

