#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define SENSOR1_ADDR 0x08
#define SENSOR2_ADDR 0x09
#define MEASUREMENT_COMMAND 0x3608
#define FLOW_CONVERSION_FACTOR 0.01
#define LOG_FILE "flow_log.txt"
#define MAX_RETRIES 3

// Global variables
int i2c_handle1 = -1;
int i2c_handle2 = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_pigpio();
int open_i2c_device(int bus, int addr);
int read_sensor_data(int handle, uint8_t *data);
float convert_to_flow_rate(uint16_t raw_value);
int validate_crc(uint8_t data[], int len);
int log_data(float flow1, float flow2);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Initialize pigpio library
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Open I2C device
int open_i2c_device(int bus, int addr) {
    int handle = i2cOpen(bus, addr, 0);
    if (handle < 0) {
        fprintf(stderr, "Failed to open I2C device at address 0x%02x: %d\n", addr, handle);
        return -1;
    }
    return handle;
}

// Read sensor data
int read_sensor_data(int handle, uint8_t *data) {
    int bytes_read = i2cReadDevice(handle, (char *)data, 3);
    if (bytes_read != 3) {
        fprintf(stderr, "Failed to read sensor data: %d\n", bytes_read);
        return -1;
    }
    return 0;
}

// Convert raw data to flow rate
float convert_to_flow_rate(uint16_t raw_value) {
    return (float)raw_value * FLOW_CONVERSION_FACTOR;
}

// Validate CRC checksum
int validate_crc(uint8_t data[], int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len - 1; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return (crc == data[len - 1]);
}

// Log data to file
int log_data(float flow1, float flow2) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    if (log_file == NULL) {
        fprintf(stderr, "Log file is not open\n");
        return -1;
    }

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, flow1, flow2);
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

// Cleanup resources
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle1 >= 0) {
        i2cClose(i2c_handle1);
    }
    if (i2c_handle2 >= 0) {
        i2cClose(i2c_handle2);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (initialize_pigpio() != 0) {
        return 1;
    }

    // Open I2C devices
    i2c_handle1 = open_i2c_device(I2C_BUS, SENSOR1_ADDR);
    if (i2c_handle1 < 0) {
        cleanup();
        return 1;
    }

    i2c_handle2 = open_i2c_device(I2C_BUS, SENSOR2_ADDR);
    if (i2c_handle2 < 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup();
        return 1;
    }

    printf("Starting data acquisition...\n");

    // Main loop
    while (!terminate) {
        uint8_t sensor1_data[3];
        uint8_t sensor2_data[3];
        float flow1, flow2;
        int retries;

        // Sensor 1
        retries = 0;
        while (retries < MAX_RETRIES) {
            if (i2cWriteDevice(i2c_handle1, (char *)&MEASUREMENT_COMMAND, 2) != 2) {
                fprintf(stderr, "Failed to write measurement command to sensor 1 (attempt %d)\n", retries + 1);
                retries++;
                gpioDelay(1000); // Wait before retrying
                continue;
            }

            gpioDelay(10); // Wait for measurement

            if (read_sensor_data(i2c_handle1, sensor1_data) == 0) {
                if (validate_crc(sensor1_data, 3)) {
                    uint16_t raw_value = (sensor1_data[0] << 8) | sensor1_data[1];
                    flow1 = convert_to_flow_rate(raw_value);
                    break; // Success, exit retry loop
                } else {
                    fprintf(stderr, "CRC validation failed for sensor 1 (attempt %d)\n", retries + 1);
                }
            } else {
                fprintf(stderr, "Failed to read sensor 1 data (attempt %d)\n", retries + 1);
            }
            retries++;
        }

        if (retries == MAX_RETRIES) {
            fprintf(stderr, "Failed to read sensor 1 after %d retries\n", MAX_RETRIES);
            flow1 = -1.0; // Indicate error
        }

        // Sensor 2
        retries = 0;
        while (retries < MAX_RETRIES) {
            if (i2cWriteDevice(i2c_handle2, (char *)&MEASUREMENT_COMMAND, 2) != 2) {
                fprintf(stderr, "Failed to write measurement command to sensor 2 (attempt %d)\n", retries + 1);
                retries++;
                gpioDelay(1000); // Wait before retrying
                continue;
            }

            gpioDelay(10); // Wait for measurement

            if (read_sensor_data(i2c_handle2, sensor2_data) == 0) {
                if (validate_crc(sensor2_data, 3)) {
                    uint16_t raw_value = (sensor2_data[0] << 8) | sensor2_data[1];
                    flow2 = convert_to_flow_rate(raw_value);
                    break; // Success, exit retry loop
                } else {
                    fprintf(stderr, "CRC validation failed for sensor 2 (attempt %d)\n", retries + 1);
                }
            } else {
                fprintf(stderr, "Failed to read sensor 2 data (attempt %d)\n", retries + 1);
            }
            retries++;
        }

        if (retries == MAX_RETRIES) {
            fprintf(stderr, "Failed to read sensor 2 after %d retries\n", MAX_RETRIES);
            flow2 = -1.0; // Indicate error
        }

        // Log data
        if (flow1 >= 0 && flow2 >= 0) {
            if (log_data(flow1, flow2) != 0) {
                fprintf(stderr, "Failed to log data\n");
            }
        }

        gpioDelay(1000); // Wait 1 second
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

