            if (i2cWriteDevice(i2c_handle2, (char *)&MEASUREMENT_COMMAND, 2) != 2) {
                fprintf(stderr, "Failed to write measurement command to sensor 2 (attempt %d)\n", retries + 1);
                retries++;
                gpioDelay(1000); // Wait before retrying
                continue;
            }

            gpioDelay(10); // Wait for measurement

            if (read_sensor_data(i2c_handle2, sensor2_data) == 0) {
                if (validate_crc(sensor2_data, 3)) {
                    uint16_t raw_value = (sensor2_data[0] << 8) | sensor2_data[1];
                    flow2 = convert_to_flow_rate(raw_value);
                    break; // Success, exit retry loop
                } else {
                    fprintf(stderr, "CRC validation failed for sensor 2 (attempt %d)\n", retries + 1);
                }
            } else {
                fprintf(stderr, "Failed to read sensor 2 data (attempt %d)\n", retries + 1);
            }
            retries++;
        }

        if (retries == MAX_RETRIES) {
            fprintf(stderr, "Failed to read sensor 2 after %d retries\n", MAX_RETRIES);
            flow2 = -1.0; // Indicate error
        }

        // Log data
        if (flow1 >= 0 && flow2 >= 0) {
            if (log_data(flow1, flow2) != 0) {
                fprintf(stderr, "Failed to log data\n");
            }
        }

        gpioDelay(1000); // Wait 1 second
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

