// Define GPIO pins for the rotary encoder
#define ENCODER_A_PIN 17
#define ENCODER_B_PIN 18

// Define the log file name
#define LOG_FILE "encoder_log.txt"

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;

// Structure to hold the quadrature state
typedef struct {
    int a_state;
    int b_state;
} QuadratureState;

// Function prototypes
void signal_handler(int signal);
int initialize_gpio();
int initialize_logging();
void cleanup();
void log_data(int a_state, int b_state, float angle);
float calculate_angle(int a_state, int b_state, int *previous_a_state, int *previous_b_state);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to initialize the pigpio library and configure GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(ENCODER_A_PIN, PI_INPUT);
    gpioSetPullUpDown(ENCODER_A_PIN, PI_PUD_UP);

    gpioSetMode(ENCODER_B_PIN, PI_INPUT);
    gpioSetPullUpDown(ENCODER_B_PIN, PI_PUD_UP);

    return 0;
}

// Function to initialize the log file
int initialize_logging() {
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        return 1;
    }
    return 0;
}

// Function to perform cleanup before exiting
void cleanup() {
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

// Function to log data to the file
void log_data(int a_state, int b_state, float angle) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, A: %d, B: %d, Angle: %.2f\n", timestamp, a_state, b_state, angle);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Function to calculate the angular position based on the quadrature state
float calculate_angle(int a_state, int b_state, int *previous_a_state, int *previous_b_state) {
    static int current_angle = 0;
    int a_diff = a_state - *previous_a_state;
    int b_diff = b_state - *previous_b_state;

    if (a_diff == 1 && b_diff == 0) {
        current_angle += 90;
    } else if (a_diff == 0 && b_diff == 1) {
        current_angle -= 90;
    } else if (a_diff == -1 && b_diff == 0) {
        current_angle -= 90;
    } else if (a_diff == 0 && b_diff == -1) {
        current_angle += 90;
    }

    // Normalize the angle to be within 0-360 degrees
    if (current_angle >= 360) {
        current_angle -= 360;
    } else if (current_angle < 0) {
        current_angle += 360;
    }

    *previous_a_state = a_state;
    *previous_b_state = b_state;

    return (float)current_angle;
}

int main() {
    // Install signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Initialize logging
    if (initialize_logging() != 0) {
        cleanup();
        return 1;
    }

    int previous_a_state = gpioRead(ENCODER_A_PIN);
    int previous_b_state = gpioRead(ENCODER_B_PIN);

    printf("Monitoring rotary encoder... Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        int a_state = gpioRead(ENCODER_A_PIN);
        int b_state = gpioRead(ENCODER_B_PIN);

        float angle = calculate_angle(a_state, b_state, &previous_a_state, &previous_b_state);
        log_data(a_state, b_state, angle);

        gpioDelay(1); // Small delay to prevent busy-waiting
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

