#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <linux/i2c-dev.h>
#include <sys/ioctl.h>
#include <fcntl.h>
#include <errno.h>

// Constants
#define I2C_BUS 1
#define ADPD144RI_ADDR 0x39
#define LED_GPIO 17
#define IR_THRESHOLD 2000
#define SAMPLE_INTERVAL_MS 100

// ADPD144RI Register Addresses (Example - Refer to datasheet for correct values)
#define ADPD144RI_FIFO_DATA_REG 0x60
#define ADPD144RI_FIFO_CONTROL_REG 0x5E
#define ADPD144RI_SYSTEM_CONFIG_REG 0x00

// Global variables
int i2c_fd;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int adpd144ri_init(int i2c_fd);
int adpd144ri_read_data(int i2c_fd, unsigned short *red, unsigned short *ir);
int adpd144ri_check_sensor_present(int i2c_fd);
void led_control(int gpio_pin, int state);
void log_data(FILE *fp, unsigned short red, unsigned short ir);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Initialize the ADPD144RI sensor
int adpd144ri_init(int i2c_fd) {
    // Example initialization sequence (Refer to datasheet)
    unsigned char init_data[] = {0x01, 0x02, 0x03}; // Example initialization data
    int result;

    // Write initialization data to the sensor
    for (int i = 0; i < sizeof(init_data); i++) {
        result = i2c_smbus_write_byte_data(i2c_fd, i, init_data[i]);
        if (result < 0) {
            fprintf(stderr, "Error writing to I2C device: %s\n", strerror(errno));
            return -1;
        }
        usleep(10000); // Small delay after each write
    }

    return 0;
}

// Read red and IR channel data from the FIFO
int adpd144ri_read_data(int i2c_fd, unsigned short *red, unsigned short *ir) {
    unsigned char buffer[4];
    int result;

    // Read 4 bytes from the FIFO data register
    result = i2c_smbus_read_i2c_block_data(i2c_fd, ADPD144RI_FIFO_DATA_REG, (char *)buffer, 4);
    if (result < 0) {
        fprintf(stderr, "Error reading from I2C device: %s\n", strerror(errno));
        return -1;
    }

    // Combine bytes to form 16-bit values
    *red = (buffer[0] << 8) | buffer[1];
    *ir = (buffer[2] << 8) | buffer[3];

    return 0;
}

// Check if the sensor is present
int adpd144ri_check_sensor_present(int i2c_fd) {
    // Example: Read a register and check if it's not zero
    int data = i2c_smbus_read_byte_data(i2c_fd, ADPD144RI_SYSTEM_CONFIG_REG);
    if (data < 0) {
        fprintf(stderr, "Error reading sensor presence: %s\n", strerror(errno));
        return 0; // Assume sensor absent on error
    }
    return (data != 0);
}

// Control the LED
void led_control(int gpio_pin, int state) {
    gpioWrite(gpio_pin, state);
}

// Log data to file
void log_data(FILE *fp, unsigned short red, unsigned short ir) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d,%u,%u\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, red, ir);
    fflush(fp); // Ensure data is written to disk immediately
}

int main() {
    unsigned short red, ir;
    int result;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set LED GPIO as output
    gpioSetMode(LED_GPIO, PI_OUTPUT);

    // Open I2C device
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C device: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, ADPD144RI_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address: %s\n", strerror(errno));
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Initialize the sensor
    if (adpd144ri_init(i2c_fd) != 0) {
        fprintf(stderr, "ADPD144RI initialization failed\n");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Check if the sensor is present
    if (!adpd144ri_check_sensor_present(i2c_fd)) {
        fprintf(stderr, "ADPD144RI sensor not found\n");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("adpd144ri_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Register signal handler for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        // Read sensor data
        result = adpd144ri_read_data(i2c_fd, &red, &ir);
        if (result == 0) {
            // Control LED based on IR threshold
            if (ir > IR_THRESHOLD) {
                led_control(LED_GPIO, 1); // Turn LED on
            } else {
                led_control(LED_GPIO, 0); // Turn LED off
            }

            // Log data
            log_data(log_file, red, ir);
        } else {
            fprintf(stderr, "Error reading sensor data\n");
        }

        // Wait for the next sample
        usleep(SAMPLE_INTERVAL_MS * 1000); // Convert ms to microseconds
    }

    // Cleanup
    fclose(log_file);
    close(i2c_fd);
    gpioTerminate();

    return 0;
}

