#include <linux/i2c-dev.h>
#include <gpiod.h>

// Constants
#define I2C_BUS "/dev/i2c-1"
#define ADPD144RI_ADDR 0x39
#define PART_ID_REG 0x00
#define FIFO_DATA_REG 0x08
#define FIFO_DATA_REG_MSB 0x09
#define FIFO_DATA_REG_LSB 0x0A
#define FIFO_DATA_REG_LSB_LSB 0x0B
#define LED_GPIO 17
#define IR_THRESHOLD 2000
#define SAMPLE_PERIOD_MS 100

// Global variables
static int i2c_fd = -1;
static struct gpiod_chip *gpio_chip = NULL;
static struct gpiod_line *led_line = NULL;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int i2c_read_reg8(int fd, uint8_t reg);
int i2c_write_reg8(int fd, uint8_t reg, uint8_t value);
int adpd144ri_init(int fd);
int adpd144ri_read_fifo(int fd, uint16_t *red, uint16_t *ir);
int gpio_init(int gpio_pin);
void gpio_set_value(int gpio_pin, int value);
void log_data(FILE *fp, uint16_t red, uint16_t ir);
void signal_handler(int sig);
void cleanup();

// I2C read function
int i2c_read_reg8(int fd, uint8_t reg) {
    int result = i2c_smbus_read_byte_data(fd, reg);
    if (result < 0) {
        fprintf(stderr, "I2C read error: %s\n", strerror(errno));
        return -1;
    }
    return result;
}

// I2C write function
int i2c_write_reg8(int fd, uint8_t reg, uint8_t value) {
    int result = i2c_smbus_write_byte_data(fd, reg, value);
    if (result < 0) {
        fprintf(stderr, "I2C write error: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// ADPD144RI initialization function
int adpd144ri_init(int fd) {
    uint8_t part_id;

    // Check PART_ID register
    part_id = i2c_read_reg8(fd, PART_ID_REG);
    if (part_id != 0x41) {
        fprintf(stderr, "Error: Invalid PART_ID (0x%02X)\n", part_id);
        return -1;
    }

    // Add more initialization steps here based on the datasheet
    // For example, configuring gain, integration time, etc.

    return 0;
}

// ADPD144RI FIFO read function
int adpd144ri_read_fifo(int fd, uint16_t *red, uint16_t *ir) {
    uint8_t msb, lsb, lsb_lsb;

    msb = i2c_read_reg8(fd, FIFO_DATA_REG_MSB);
    lsb = i2c_read_reg8(fd, FIFO_DATA_REG_LSB);
    lsb_lsb = i2c_read_reg8(fd, FIFO_DATA_REG_LSB_LSB);

    if (msb < 0 || lsb < 0 || lsb_lsb < 0) {
        return -1;
    }

    *red = (uint16_t)((msb << 8) | lsb);
    *ir = (uint16_t)((lsb << 8) | lsb_lsb);

    return 0;
}

// GPIO initialization function
int gpio_init(int gpio_pin) {
    struct gpiod_line_request_config config;

    gpio_chip = gpiod_chip_open_by_name("gpiochip0");
    if (!gpio_chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    led_line = gpiod_chip_get_line(gpio_chip, gpio_pin);
    if (!led_line) {
        perror("Error getting GPIO line");
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    memset(&config, 0, sizeof(config));
    config.consumer = "adpd144ri_led";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;

    if (gpiod_line_request(led_line, &config, 0) < 0) {
        perror("Error requesting GPIO line");
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    return 0;
}

// GPIO set value function
void gpio_set_value(int gpio_pin, int value) {
    if (gpiod_line_set_value(led_line, value) < 0) {
        perror("Error setting GPIO value");
    }
}

// Log data function
void log_data(FILE *fp, uint16_t red, uint16_t ir) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(fp, "%s,%u,%u\n", timestamp, red, ir);
    fflush(fp);
}

// Signal handler function
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Cleanup function
void cleanup() {
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (gpio_chip) {
        gpiod_line_release(led_line);
        gpiod_chip_close(gpio_chip);
    }
    if (log_file) {
        fclose(log_file);
    }
    exit(0);
}

int main() {
    uint16_t red, ir;
    struct timespec sleep_time;
    sleep_time.tv_sec = 0;
    sleep_time.tv_nsec = SAMPLE_PERIOD_MS * 1000000; // 100ms

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Error opening I2C bus");
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, ADPD144RI_ADDR) < 0) {
        perror("Error setting I2C slave address");
        close(i2c_fd);
        return 1;
    }

    // Initialize ADPD144RI sensor
    if (adpd144ri_init(i2c_fd) < 0) {
        fprintf(stderr, "ADPD144RI initialization failed\n");
        close(i2c_fd);
        return 1;
    }

    // Initialize GPIO
    if (gpio_init(LED_GPIO) < 0) {
        fprintf(stderr, "GPIO initialization failed\n");
        close(i2c_fd);
        return 1;
    }

    // Open log file
    log_file = fopen("adpd144ri_log.txt", "a");
    if (!log_file) {
        perror("Error opening log file");
        cleanup();
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Read FIFO data
        if (adpd144ri_read_fifo(i2c_fd, &red, &ir) == 0) {
            // Log data
            log_data(log_file, red, ir);

            // Control LED based on IR threshold
            if (ir > IR_THRESHOLD) {
                gpio_set_value(LED_GPIO, 1); // Turn LED on
            } else {
                gpio_set_value(LED_GPIO, 0); // Turn LED off
            }
        } else {
            fprintf(stderr, "Error reading FIFO data\n");
        }

        // Sleep for 100ms
        nanosleep(&sleep_time, NULL);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

