static volatile int keepRunning = 1;

// Function to handle signals (SIGINT, SIGTERM)
void signalHandler(int signum) {
    keepRunning = 0;
    printf("\nExiting gracefully...\n");
}

// Function to initialize GPIO pins
int initializeGPIO() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(GPIO_INPUT, PI_INPUT);
    gpioSetMode(GPIO_OUTPUT, PI_OUTPUT);
    gpioWrite(GPIO_OUTPUT, GAIN_PIN_VALUE);

    return 0;
}

// Function to detect rising edge
int detectRisingEdge(int gpioPin) {
    int currentLevel = gpioRead(gpioPin);
    int previousLevel = currentLevel;
    gpioDelay(POLLING_INTERVAL_MS * 1000); // Delay for polling interval
    currentLevel = gpioRead(gpioPin);

    if (currentLevel == 1 && previousLevel == 0) {
        return 1; // Rising edge detected
    }
    return 0; // No rising edge
}

// Function to log peak event to file
