        gpioTerminate();
        return 1;
    }

    printf("Audio peak detection started. Press Ctrl+C to exit.\n");

    // Main loop
    while (keepRunning) {
        if (detectRisingEdge(GPIO_INPUT)) {
            logPeakEvent(logFile);
        }
    }

    // Cleanup
    fclose(logFile);
    gpioTerminate();

    return 0;
}

