#define I2C_BUS 1
#define SLF3S_ADDR 0x36
#define MEASURE_CMD 0x3608
#define FLOW_LOG_FILE "flow_log.csv"
#define SLEEP_MS 1000

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_sensor();
int read_flow_rate(int *raw_flow);
float convert_to_flow_rate(int raw_flow);
uint8_t crc8(const uint8_t *data, size_t len);
void log_flow_rate(float flow_rate);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initializes the SLF3S-4000B sensor
int initialize_sensor() {
    char cmd[2] = {(MEASURE_CMD >> 8) & 0xFF, MEASURE_CMD & 0xFF};
    int result = i2cWriteDevice(i2c_handle, cmd, 2);
    if (result != 0) {
        fprintf(stderr, "Error initializing sensor: %d\n", result);
        return -1;
    }
    return 0;
}

// Reads the raw flow rate from the sensor
int read_flow_rate(int *raw_flow) {
    char buffer[3];
    int result = i2cReadDevice(i2c_handle, buffer, 3);
    if (result != 3) {
        fprintf(stderr, "Error reading flow rate: %d\n", result);
        return -1;
    }

    *raw_flow = (buffer[0] << 8) | buffer[1];
    return 0;
}

// Converts the raw flow rate to uL/min
float convert_to_flow_rate(int raw_flow) {
    return (float)raw_flow / 1000.0;
}

// Calculates the CRC-8 checksum
uint8_t crc8(const uint8_t *data, size_t len) {
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Logs the flow rate to a CSV file
void log_flow_rate(float flow_rate) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(log_file, "%s,%.3f\n", timestamp, flow_rate);
    fflush(log_file);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, SLF3S_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize the sensor
    if (initialize_sensor() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open the log file
    log_file = fopen(FLOW_LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    int raw_flow;
    float flow_rate;

    // Main loop
    while (!terminate) {
        if (read_flow_rate(&raw_flow) == 0) {
            uint8_t crc = crc8((uint8_t[]){(raw_flow >> 8) & 0xFF, raw_flow & 0xFF}, 2);
            if (crc == (uint8_t)raw_flow) {
                flow_rate = convert_to_flow_rate(raw_flow);
                log_flow_rate(flow_rate);
                printf("Flow rate: %.3f uL/min\n", flow_rate);
            } else {
                fprintf(stderr, "CRC check failed!\n");
            }
        } else {
            fprintf(stderr, "Failed to read flow rate. Retrying...\n");
        }

        gpioDelay(SLEEP_MS);
    }

    // Cleanup
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

