#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <gpiod.h>

#define GPIO_CHIP_NAME "gpiochip0"
#define GPIO_LINE 17
#define DEBOUNCE_DELAY_MS 50
#define INTRUSION_THRESHOLD_S 5

static volatile sig_atomic_t keep_running = 1;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *line = NULL;
static struct timespec last_touch_time;

void signal_handler(int sig) {
    keep_running = 0;
    fprintf(stderr, "\nCaught signal %d, exiting gracefully...\n", sig);
}

int main() {
    struct gpiod_line_request_config config;
    int ret;
    struct timespec ts;
    int touched;

    /* Register signal handlers */
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    /* Open GPIO chip */
    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip '%s': %s\n", GPIO_CHIP_NAME, strerror(errno));
        return EXIT_FAILURE;
    }

    /* Get GPIO line */
    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        fprintf(stderr, "Error getting GPIO line %d: %s\n", GPIO_LINE, strerror(errno));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* Request GPIO line as input */
    memset(&config, 0, sizeof(config));
    config.consumer = "ttp223_tamper";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT;

    ret = gpiod_line_request(line, &config, 0);
    if (ret < 0) {
        fprintf(stderr, "Error requesting GPIO line %d: %s\n", GPIO_LINE, strerror(errno));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* Initialize last touch time */
    clock_gettime(CLOCK_MONOTONIC, &last_touch_time);

    /* Main loop */
    while (keep_running) {
        /* Read sensor value */
        touched = gpiod_line_get_value(line);
        if (touched < 0) {
            fprintf(stderr, "Error reading GPIO line %d: %s\n", GPIO_LINE, strerror(errno));
            break; /* Exit loop on error */
        }

        /* Check for touch */
        if (touched == 1) {
            /* Debounce delay */
            struct timespec delay;
            delay.tv_sec = 0;
            delay.tv_nsec = DEBOUNCE_DELAY_MS * 1000000; /* Convert ms to ns */
            nanosleep(&delay, NULL);

            /* Read sensor again after debounce */
            if (gpiod_line_get_value(line) == 1) {
                /* Update last touch time */
                clock_gettime(CLOCK_MONOTONIC, &last_touch_time);
            }
        } else {
            /* Reset intrusion timer if released */
            clock_gettime(CLOCK_MONOTONIC, &last_touch_time);
        }

        /* Check for intrusion */
        clock_gettime(CLOCK_MONOTONIC, &ts);
        double elapsed_time = (ts.tv_sec - last_touch_time.tv_sec) + (ts.tv_nsec - last_touch_time.tv_nsec) / 1e9;
        if (touched == 1 && elapsed_time > INTRUSION_THRESHOLD_S) {
            printf("Intrusion Alert!\n");
            clock_gettime(CLOCK_MONOTONIC, &last_touch_time); /* Reset timer after alert */
        }

        /* Delay */
        struct timespec delay;
        delay.tv_sec = 0;
        delay.tv_nsec = 100 * 1000000; /* 100 ms */
        nanosleep(&delay, NULL);
    }

    /* Cleanup */
    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }

    return EXIT_SUCCESS;
}

