            clock_gettime(CLOCK_MONOTONIC, &last_touch_time); /* Reset timer after alert */
        }

        /* Delay */
        struct timespec delay;
        delay.tv_sec = 0;
        delay.tv_nsec = 100 * 1000000; /* 100 ms */
        nanosleep(&delay, NULL);
    }

    /* Cleanup */
    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }

    return EXIT_SUCCESS;
}

