#include <unistd.h>
#include <pigpio.h>
#include <alsa/asoundlib.h>

// Configuration
#define SAMPLE_RATE 44100
#define NUM_CHANNELS 1
#define FORMAT SND_PCM_FORMAT_S24_LE
#define PERIOD_SIZE 1024
#define GPIO_PIN 17
#define AUDIO_FILE "audio_capture.pcm"

// Global variables
snd_pcm_t *pcm_handle;
FILE *audio_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_alsa(snd_pcm_t **pcm_handle);
int initialize_gpio(int gpio_pin);
int acquire_audio_data(snd_pcm_t *pcm_handle, FILE *audio_file);
void signal_handler(int signal);

// Signal handler
void signal_handler(int signal) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating...\n", signal);
}

// Initialize ALSA
int initialize_alsa(snd_pcm_t **pcm_handle) {
    snd_pcm_hw_params_t *hw_params;
    int err;

    if ((err = snd_pcm_open(pcm_handle, "default", SND_PCM_STREAM_CAPTURE, 0)) < 0) {
        fprintf(stderr, "Error opening PCM device: %s\n", snd_strerror(err));
        return -1;
    }

    snd_pcm_hw_params_alloca(&hw_params);

    if ((err = snd_pcm_hw_params_any(*pcm_handle, hw_params)) < 0) {
        fprintf(stderr, "Error setting HW params: %s\n", snd_strerror(err));
        snd_pcm_close(*pcm_handle);
        return -1;
    }

    if ((err = snd_pcm_hw_params_set_access(*pcm_handle, hw_params, SND_PCM_ACCESS_RW_INTERLEAVED)) < 0) {
        fprintf(stderr, "Error setting access: %s\n", snd_strerror(err));
        snd_pcm_close(*pcm_handle);
        return -1;
    }

    if ((err = snd_pcm_hw_params_set_format(*pcm_handle, hw_params, FORMAT)) < 0) {
        fprintf(stderr, "Error setting format: %s\n", snd_strerror(err));
        snd_pcm_close(*pcm_handle);
        return -1;
    }

    if ((err = snd_pcm_hw_params_set_channels(*pcm_handle, hw_params, NUM_CHANNELS)) < 0) {
        fprintf(stderr, "Error setting channels: %s\n", snd_strerror(err));
        snd_pcm_close(*pcm_handle);
        return -1;
    }

    unsigned int rate = SAMPLE_RATE;
    if ((err = snd_pcm_hw_params_set_rate_near(*pcm_handle, hw_params, &rate, 0)) < 0) {
        fprintf(stderr, "Error setting rate: %s\n", snd_strerror(err));
        snd_pcm_close(*pcm_handle);
        return -1;
    }

    if ((err = snd_pcm_hw_params(*pcm_handle, hw_params)) < 0) {
        fprintf(stderr, "Error setting HW params: %s\n", snd_strerror(err));
        snd_pcm_close(*pcm_handle);
        return -1;
    }

    return 0;
}

// Initialize GPIO
int initialize_gpio(int gpio_pin) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(gpio_pin, PI_OUTPUT);
    gpioWrite(gpio_pin, 0); // Select left channel

    return 0;
}

// Acquire audio data
int acquire_audio_data(snd_pcm_t *pcm_handle, FILE *audio_file) {
    char *buffer = (char *)malloc(PERIOD_SIZE * 3); // 3 bytes per sample (24-bit)
    if (!buffer) {
        fprintf(stderr, "Error allocating buffer\n");
        return -1;
    }

    while (!terminate) {
        int err = snd_pcm_readi(pcm_handle, buffer, PERIOD_SIZE);
        if (err < 0) {
            fprintf(stderr, "Error reading PCM data: %s\n", snd_strerror(err));
            break;
        }

        // Convert 24-bit to 16-bit
        for (int i = 0; i < PERIOD_SIZE; i++) {
            int16_t sample = (int16_t)((((int32_t)buffer[i * 3 + 2] << 8) | ((int32_t)buffer[i * 3 + 1] << 16)) >> 8);
            fwrite(&sample, sizeof(int16_t), 1, audio_file);
        }
    }

    free(buffer);
    return 0;
}

int main() {
    // Install signal handler
    signal(SIGINT, signal_handler);

    // Initialize ALSA
    if (initialize_alsa(&pcm_handle) < 0) {
        return 1;
    }

    // Initialize GPIO
    if (initialize_gpio(GPIO_PIN) < 0) {
        snd_pcm_close(pcm_handle);
        return 1;
    }

    // Open audio file
    audio_file = fopen(AUDIO_FILE, "wb");
    if (!audio_file) {
        fprintf(stderr, "Error opening audio file\n");
        gpioTerminate();
        snd_pcm_close(pcm_handle);
        return 1;
    }

    // Acquire audio data
    if (acquire_audio_data(pcm_handle, audio_file) < 0) {
        fprintf(stderr, "Error acquiring audio data\n");
    }

    // Clean up
    fclose(audio_file);
    gpioTerminate();
    snd_pcm_close(pcm_handle);

    return 0;
}

