#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>
#include <math.h>

// Define GPIO pins
#define FLAME_SENSOR_PIN 4
#define FAN_PIN 18

// Define PWM frequency
#define PWM_FREQUENCY 100

// Define log file name
#define LOG_FILE "flame_log.txt"

// Global variables
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_gpio();
int read_flame_sensor();
double calculate_duty_cycle(double flame_duration);
int set_fan_speed(double duty_cycle);
int log_event(const char *event_description);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(FLAME_SENSOR_PIN, PI_INPUT);
    gpioSetMode(FAN_PIN, PI_OUTPUT);

    gpioSetPWMfrequency(FAN_PIN, PWM_FREQUENCY);
    gpioSetPWMrange(FAN_PIN, 100); // Set PWM range to 0-100 for percentage

    return 0;
}

// Read flame sensor value
int read_flame_sensor() {
    int value = gpioRead(FLAME_SENSOR_PIN);
    if (value < 0) {
        fprintf(stderr, "Error reading flame sensor\n");
        return -1; // Indicate error
    }
    return value;
}

// Calculate duty cycle based on flame duration
double calculate_duty_cycle(double flame_duration) {
    // Exponential curve: 0% at 0 seconds, 80% at 10 seconds
    double max_duration = 10.0; // Maximum duration for 80% duty cycle
    double duty_cycle = 80.0 * exp(-flame_duration / max_duration);

    // Clamp duty cycle between 0 and 80
    if (duty_cycle < 0.0) duty_cycle = 0.0;
    if (duty_cycle > 80.0) duty_cycle = 80.0;

    return duty_cycle;
}

// Set fan speed using PWM
int set_fan_speed(double duty_cycle) {
    int pwm_value = (int)(duty_cycle * 100 / 100.0); // Convert percentage to PWM value (0-100)
    gpioPWM(FAN_PIN, pwm_value);
    return 0;
}

// Log events to file
int log_event(const char *event_description) {
    time_t now = time(NULL);
    struct tm *tstruct = localtime(&now);
    char buf[80];
    strftime(buf, sizeof(buf), "%Y-%m-%dT%H:%M:%SZ", tstruct);

    if (log_file != NULL) {
        fprintf(log_file, "%s: %s\n", buf, event_description);
        fflush(log_file); // Ensure immediate write to file
        return 0;
    } else {
        fprintf(stderr, "Error: Log file not opened.\n");
        return 1;
    }
}

// Cleanup function
void cleanup() {
    printf("Cleaning up...\n");

    // Stop PWM
    gpioPWM(FAN_PIN, 0);

    // Release GPIO pins
    gpioSetMode(FLAME_SENSOR_PIN, PI_INPUT); // Set back to input
    gpioSetMode(FAN_PIN, PI_INPUT); // Set back to input

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate pigpio
    gpioTerminate();

    printf("Cleanup complete. Exiting.\n");
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        cleanup();
        return 1;
    }

    // Log system start
    log_event("System started");

    time_t flame_start_time = 0;
    int flame_detected = 0;

    // Main loop
    while (!terminate) {
        int sensor_value = read_flame_sensor();
        if (sensor_value < 0) {
            fprintf(stderr, "Error reading sensor, exiting.\n");
            break;
        }

        if (sensor_value == 0) { // Flame detected (LOW signal)
            if (!flame_detected) {
                flame_detected = 1;
                flame_start_time = time(NULL);
                log_event("Flame detected");
            }
        } else { // No flame (HIGH signal)
            if (flame_detected) {
                flame_detected = 0;
                time_t flame_end_time = time(NULL);
                double flame_duration = difftime(flame_end_time, flame_start_time);
                double duty_cycle = calculate_duty_cycle(flame_duration);
                set_fan_speed(duty_cycle);
                char log_message[100];
                snprintf(log_message, sizeof(log_message), "Flame ended, duty cycle: %.2f%%", duty_cycle);
                log_event(log_message);
            }
        }

        gpioDelay(50); // 50 ms delay
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

