#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define constants
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 0
#define TRIGGER_GPIO 23
#define DATA_READY_GPIO 24
#define MAGIC_NUMBER 0x52444144
#define FRAME_SIZE 32768
#define CONFIG_SIZE 24

// Configuration struct
typedef struct {
    uint32_t start_frequency;
    uint32_t end_frequency;
    uint16_t num_chirps;
    uint16_t num_samples;
    uint16_t frame_period_ms;
} config_t;

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_gpio();
int initialize_spi();
int write_log_header(FILE *fp);
int read_heatmap_data(FILE *fp);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioSetMode(TRIGGER_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting GPIO %d as output\n", TRIGGER_GPIO);
        return -1;
    }
    if (gpioSetMode(DATA_READY_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Error setting GPIO %d as input\n", DATA_READY_GPIO);
        return -1;
    }
    return 0;
}

// Initialize SPI interface
int initialize_spi() {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "Error opening SPI channel %d: %d\n", SPI_CHANNEL, spi_handle);
        return -1;
    }
    return 0;
}

// Write log file header
int write_log_header(FILE *fp) {
    time_t rawtime;
    struct tm *timeinfo;
    time(&rawtime);
    timeinfo = localtime(&rawtime);

    char timestamp[8];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    uint32_t magic = MAGIC_NUMBER;
    uint32_t start_frequency = 77000000000; // 77 GHz
    uint32_t end_frequency = 79000000000;   // 79 GHz
    uint16_t num_chirps = 64;
    uint16_t num_samples = 256;
    uint16_t frame_period_ms = 100;

    config_t config = {
        .start_frequency = start_frequency,
        .end_frequency = end_frequency,
        .num_chirps = num_chirps,
        .num_samples = num_samples,
        .frame_period_ms = frame_period_ms
    };

    if (fwrite(&magic, sizeof(uint32_t), 1, fp) != 1) {
        fprintf(stderr, "Error writing magic number to log file\n");
        return -1;
    }
    if (fwrite(timestamp, sizeof(char), 8, fp) != 8) {
        fprintf(stderr, "Error writing timestamp to log file\n");
        return -1;
    }
    if (fwrite(&config, sizeof(config_t), 1, fp) != 1) {
        fprintf(stderr, "Error writing config to log file\n");
        return -1;
    }

    return 0;
}

// Read heatmap data from SPI
int read_heatmap_data(FILE *fp) {
    char buffer[FRAME_SIZE];
    int bytes_read = spiRead(spi_handle, buffer, FRAME_SIZE);

    if (bytes_read != FRAME_SIZE) {
        fprintf(stderr, "Error reading from SPI: %d bytes read (expected %d)\n", bytes_read, FRAME_SIZE);
        return -1;
    }

    time_t rawtime;
    struct tm *timeinfo;
    time(&rawtime);
    timeinfo = localtime(&rawtime);

    char timestamp[8];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    uint32_t frame_number = 1; // Assuming frame number starts at 1

    if (fprintf(fp, "%s,%u,%d", timestamp, frame_number, bytes_read) < 0) {
        fprintf(stderr, "Error writing to log file\n");
        return -1;
    }
    if (fwrite(buffer, sizeof(char), bytes_read, fp) != bytes_read) {
        fprintf(stderr, "Error writing data to log file\n");
        return -1;
    }

    return 0;
