    }
    if (gpioSetMode(DATA_READY_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Error setting GPIO %d as input\n", DATA_READY_GPIO);
        return -1;
    }
    return 0;
}

// Initialize SPI interface
int initialize_spi() {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "Error opening SPI channel %d: %d\n", SPI_CHANNEL, spi_handle);
        return -1;
    }
    return 0;
}

// Write log file header
int write_log_header(FILE *fp) {
    time_t rawtime;
    struct tm *timeinfo;
    time(&rawtime);
    timeinfo = localtime(&rawtime);

    char timestamp[8];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

