#include <unistd.h>
#include <gpiod.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_PIN 20
#define LOG_FILE "flame_log.txt"

static volatile int keep_running = 1;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *line = NULL;
static FILE *log_file = NULL;

// Function to handle signals (SIGINT, SIGTERM)
void signal_handler(int sig) {
    keep_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", sig);
}

// Function to get the current timestamp in ISO 8601 UTC format
char* get_iso8601_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    char *timestamp = (char*)malloc(25 * sizeof(char)); // Allocate memory for the timestamp

    if (timestamp == NULL) {
        perror("Failed to allocate memory for timestamp");
        return NULL;
    }

    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    strftime(timestamp, 25, "%Y-%m-%dT%H:%M:%SZ", timeinfo);
    return timestamp;
}

// Function to log events to a file
int log_event(const char *event) {
    char *timestamp = get_iso8601_timestamp();
    if (timestamp == NULL) {
        fprintf(stderr, "Failed to get timestamp, skipping log entry.\n");
        return -1;
    }

    if (log_file != NULL) {
        fprintf(log_file, "%s: %s\n", timestamp, event);
        fflush(log_file); // Ensure the log is written immediately
    } else {
        fprintf(stderr, "Log file is not open, cannot log event: %s\n", event);
    }
    free(timestamp);
    return 0;
}

// Function to read the flame sensor value
int read_flame_sensor() {
    int value = gpiod_line_get_value(line);
    if (value < 0) {
        fprintf(stderr, "Error reading GPIO value: %d\n", value);
        return -1; // Indicate an error
    }
    return value;
}

// Function to initialize the GPIO line
int init_gpio() {
    struct gpiod_line_request_config config;

    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        perror("Error getting GPIO line");
        gpiod_chip_close(chip);
        return -1;
    }

    memset(&config, 0, sizeof(config));
    config.consumer = "flame_sensor";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT;

    if (gpiod_line_request(line, &config, 0) < 0) {
        perror("Error requesting GPIO line");
        gpiod_chip_close(chip);
        return -1;
    }

    return 0;
}

// Function to cleanup resources
void cleanup() {
    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (log_file) {
        fclose(log_file);
    }
}

int main() {
    int prev_value = -1; // Initialize to an invalid value
    int current_value;

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (init_gpio() < 0) {
        fprintf(stderr, "GPIO initialization failed, exiting.\n");
        return 1;
    }

    // Open the log file
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Error opening log file");
        cleanup();
        return 1;
    }

    printf("Flame sensor monitoring started. Press Ctrl+C to exit.\n");

    while (keep_running) {
        current_value = read_flame_sensor();

        if (current_value < 0) {
            fprintf(stderr, "Error reading sensor, retrying...\n");
            usleep(100000); // Wait 100ms before retrying
            continue;
        }

        if (current_value != prev_value) {
            if (current_value == 0) {
                log_event("Flame Detected");
                printf("Flame Detected\n");
            } else {
                log_event("Flame Cleared");
                printf("Flame Cleared\n");
            }
            prev_value = current_value;
        }

        usleep(100000); // Wait 100 milliseconds
    }

    cleanup();
    printf("Exiting.\n");
    return 0;
}

