#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define OPT3001_ADDR 0x44
#define RESULT_REG 0x00
#define CONFIG_REG 0x01
#define CONTINUOUS_MODE 0xCC00 // Continuous conversion mode, auto range
#define RETRY_COUNT 3
#define RETRY_DELAY_MS 10

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int configure_sensor();
int read_sensor_data(uint16_t *data);
float calculate_lux(uint16_t data);
char* get_iso8601_timestamp();
int log_data(float lux);
void signal_handler(int signal);
void cleanup();

// Structure for sensor configuration (optional)
typedef struct {
    int bus;
    int address;
    int mode;
} sensor_config_t;


int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        fprintf(stderr, "I2C initialisation failed\n");
        cleanup();
        return 1;
    }

    // Configure the sensor
    if (configure_sensor() != 0) {
        fprintf(stderr, "Sensor configuration failed\n");
        cleanup();
        return 1;
    }

    // Open the log file
    log_file = fopen("light_data.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup();
        return 1;
    }

    // Main loop
    uint16_t sensor_data;
    float lux;
    while (!terminate) {
        // Read sensor data
        if (read_sensor_data(&sensor_data) == 0) {
            // Calculate lux
            lux = calculate_lux(sensor_data);

            // Log the data
            if (log_data(lux) != 0) {
                fprintf(stderr, "Failed to log data\n");
            }
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }

        // Wait for 1 second
        gpioDelay(1000); // pigpio's delay function
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, OPT3001_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        return 1;
    }
    return 0;
}

// Configure the sensor
int configure_sensor() {
    char buf[2];
    buf[0] = CONFIG_REG;
    buf[1] = (CONTINUOUS_MODE >> 8) & 0xFF; // MSB
    if (i2cWriteDevice(i2c_handle, buf, 2) != 0) {
        fprintf(stderr, "Failed to write config register MSB\n");
        return 1;
    }

    buf[0] = (CONFIG_REG + 1) & 0xFF; //LSB
    buf[1] = CONTINUOUS_MODE & 0xFF; //LSB
    if (i2cWriteDevice(i2c_handle, buf, 2) != 0) {
        fprintf(stderr, "Failed to write config register LSB\n");
        return 1;
    }
    return 0;
}

// Read sensor data
int read_sensor_data(uint16_t *data) {
    char buf[1];
    char result[2];
    int retries = RETRY_COUNT;

    buf[0] = RESULT_REG;

    while (retries > 0) {
        if (i2cWriteDevice(i2c_handle, buf, 1) == 0) {
            if (i2cReadDevice(i2c_handle, result, 2) == 2) {
                *data = ((uint16_t)result[0] << 8) | (uint16_t)result[1];
                return 0; // Success
            } else {
                fprintf(stderr, "Failed to read result register\n");
            }
        } else {
            fprintf(stderr, "Failed to write result register address\n");
        }
        retries--;
        gpioDelay(RETRY_DELAY_MS);
    }
    return 1; // Failure
}

// Calculate lux
float calculate_lux(uint16_t data) {
    int exponent = (data >> 12) & 0x0F;
    int mantissa = data & 0x0FFF;
    return 0.01 * (float)mantissa * (float)(1 << exponent);
}

// Get ISO 8601 timestamp
char* get_iso8601_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    char *timestamp = (char*)malloc(25 * sizeof(char)); // Allocate memory for the timestamp

    time(&rawtime);
    timeinfo = gmtime(&rawtime); // Use gmtime for UTC time

    strftime(timestamp, 25, "%Y-%m-%dT%H:%M:%SZ", timeinfo);
    return timestamp;
}

// Log data to file
int log_data(float lux) {
    char *timestamp = get_iso8601_timestamp();
    if (timestamp == NULL) {
        fprintf(stderr, "Failed to get timestamp\n");
        return 1;
    }

    fprintf(log_file, "%s, %.2f\n", timestamp, lux);
    fflush(log_file); // Ensure data is written to disk
    free(timestamp);
    return 0;
}

// Signal handler
void signal_handler(int signal) {
    fprintf(stderr, "Received signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup function
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

