    i2c_handle = i2cOpen(I2C_BUS, OPT3001_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        return 1;
    }
    return 0;
}

// Configure the sensor
int configure_sensor() {
    char buf[2];
    buf[0] = CONFIG_REG;
    buf[1] = (CONTINUOUS_MODE >> 8) & 0xFF; // MSB
    if (i2cWriteDevice(i2c_handle, buf, 2) != 0) {
        fprintf(stderr, "Failed to write config register MSB\n");
        return 1;
    }

    buf[0] = (CONFIG_REG + 1) & 0xFF; //LSB
    buf[1] = CONTINUOUS_MODE & 0xFF; //LSB
    if (i2cWriteDevice(i2c_handle, buf, 2) != 0) {
        fprintf(stderr, "Failed to write config register LSB\n");
        return 1;
    }
    return 0;
}

// Read sensor data
int read_sensor_data(uint16_t *data) {
    char buf[1];
    char result[2];
    int retries = RETRY_COUNT;

    buf[0] = RESULT_REG;

    while (retries > 0) {
        if (i2cWriteDevice(i2c_handle, buf, 1) == 0) {
            if (i2cReadDevice(i2c_handle, result, 2) == 2) {
                *data = ((uint16_t)result[0] << 8) | (uint16_t)result[1];
                return 0; // Success
            } else {
                fprintf(stderr, "Failed to read result register\n");
            }
        } else {
            fprintf(stderr, "Failed to write result register address\n");
        }
        retries--;
        gpioDelay(RETRY_DELAY_MS);
    }
    return 1; // Failure
}

// Calculate lux
float calculate_lux(uint16_t data) {
    int exponent = (data >> 12) & 0x0F;
    int mantissa = data & 0x0FFF;
    return 0.01 * (float)mantissa * (float)(1 << exponent);
}

// Get ISO 8601 timestamp
char* get_iso8601_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    char *timestamp = (char*)malloc(25 * sizeof(char)); // Allocate memory for the timestamp

    time(&rawtime);
    timeinfo = gmtime(&rawtime); // Use gmtime for UTC time

    strftime(timestamp, 25, "%Y-%m-%dT%H:%M:%SZ", timeinfo);
    return timestamp;
}

// Log data to file
int log_data(float lux) {
    char *timestamp = get_iso8601_timestamp();
    if (timestamp == NULL) {
        fprintf(stderr, "Failed to get timestamp\n");
        return 1;
    }

    fprintf(log_file, "%s, %.2f\n", timestamp, lux);
    fflush(log_file); // Ensure data is written to disk
    free(timestamp);
    return 0;
}

// Signal handler
void signal_handler(int signal) {
    fprintf(stderr, "Received signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup function
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

