#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Define the GPIO chip and line names
#define GPIO_CHIP_NAME "gpiochip0"
#define GPIO_LINE_NUMBER 17

// Global variables for signal handling
volatile sig_atomic_t program_running = 1;
struct gpiod_chip *gpio_chip = NULL;
struct gpiod_line *gpio_line = NULL;

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT) {
        program_running = 0;
        fprintf(stderr, "\nCaught SIGINT, exiting gracefully...\n");
    }
}

// Function to get the current timestamp
void get_timestamp(char *timestamp) {
    time_t rawtime;
    struct tm *timeinfo;

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, 20, "%Y-%m-%d %H:%M:%S", timeinfo);
}

// Function to read the flame detection status
int read_flame_status() {
    int value = gpiod_line_request_get_value(gpio_line);
    if (value < 0) {
        fprintf(stderr, "Error reading GPIO line value: %d\n", value);
        return -1; // Indicate an error
    }
    return value;
}

// Function to log the flame detection status
void log_flame_status(int status) {
    char timestamp[20];
    get_timestamp(timestamp);

    if (status == 0) {
        printf("%s Flame Detected: YES\n", timestamp);
    } else {
        printf("%s Flame Detected: NO\n", timestamp);
    }
}

int main() {
    // Install signal handler for SIGINT
    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        perror("signal");
        return 1;
    }

    // Open the GPIO chip
    gpio_chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!gpio_chip) {
        fprintf(stderr, "Error opening GPIO chip '%s'\n", GPIO_CHIP_NAME);
        return 1;
    }

    // Request the GPIO line
    gpio_line = gpiod_chip_request_line(gpio_chip, GPIO_LINE_NUMBER, "flame_detect");
    if (!gpio_line) {
        fprintf(stderr, "Error requesting GPIO line %d\n", GPIO_LINE_NUMBER);
        gpiod_chip_close(gpio_chip);
        return 1;
    }

    // Configure the GPIO line as input with pull-up resistor
    struct gpiod_line_config config;
    memset(&config, 0, sizeof(config));
    config.consumer = "flame_detect";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT;
    config.flags = GPIOD_LINE_CONFIG_PULL_UP;

    if (gpiod_line_config(gpio_line, &config) < 0) {
        fprintf(stderr, "Error configuring GPIO line %d\n", GPIO_LINE_NUMBER);
        gpiod_chip_release_line(gpio_chip, GPIO_LINE_NUMBER);
        gpiod_chip_close(gpio_chip);
        return 1;
    }

    // Main loop
    while (program_running) {
        int flame_status = read_flame_status();
        if (flame_status != -1) {
            log_flame_status(flame_status);
        }

        struct timespec sleep_time;
        sleep_time.tv_sec = 1;  // 1 second
        sleep_time.tv_nsec = 0; // 0 nanoseconds
        nanosleep(&sleep_time, NULL);
    }

    // Cleanup resources
    if (gpio_line) {
        gpiod_chip_release_line(gpio_chip, GPIO_LINE_NUMBER);
    }
    if (gpio_chip) {
        gpiod_chip_close(gpio_chip);
    }

    return 0;
}

