// Define the GPIO pins connected to the TTP226 channels
const int TTP226_PINS[] = {2, 3, 4, 5, 6, 7, 8, 9};
const int NUM_CHANNELS = sizeof(TTP226_PINS) / sizeof(TTP226_PINS[0]);

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signal) {
    if (signal == SIGINT) {
        program_running = 0;
        fprintf(stderr, "\nCaught SIGINT, exiting gracefully...\n");
    }
}

int main() {
    // Register the signal handler for SIGINT
    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        perror("signal");
        return 1;
    }

    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Configure the GPIO pins as inputs
    for (int i = 0; i < NUM_CHANNELS; i++) {
        if (gpioSetMode(TTP226_PINS[i], PI_INPUT) != 0) {
            fprintf(stderr, "Failed to set GPIO %d as input\n", TTP226_PINS[i]);
            gpioTerminate();
            return 1;
        }
    }

    // Main loop to read and log the sensor data
    while (program_running) {
        // Read the state of each channel
        for (int i = 0; i < NUM_CHANNELS; i++) {
            int value = gpioRead(TTP226_PINS[i]);
            if (value < 0) {
                fprintf(stderr, "Error reading GPIO %d\n", TTP226_PINS[i]);
            } else {
                printf("Channel %d: %d\n", i + 1, value);
            }
        }

        // Wait for 100 milliseconds
        gpioDelay(100);
    }

    // Terminate the pigpio library before exiting
    gpioTerminate();
    printf("Program terminated.\n");
    return 0;
}

