#include <signal.h>
#include <pigpio.h>
#include <time.h>

// Define the GPIO pins connected to the TTP226 channels
const int channels[] = {2, 3, 4, 5, 6, 7, 8, 9};
const int num_channels = sizeof(channels) / sizeof(channels[0]);

// Global variable to indicate program termination
volatile sig_atomic_t terminate = 0;

// Signal handler function
void signal_handler(int sig) {
    fprintf(stderr, "\nCaught signal %d, terminating gracefully...\n", sig);
    terminate = 1;
}

int main() {
    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Register signal handlers for SIGINT and SIGTERM
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Configure each GPIO pin as an input with a pull-down resistor
    for (int i = 0; i < num_channels; i++) {
        if (gpioSetMode(channels[i], PI_INPUT) != 0) {
            fprintf(stderr, "Failed to set GPIO %d as input\n", channels[i]);
            gpioTerminate();
            return 1;
        }
        if (gpioSetPullUpDown(channels[i], PI_PUD_DOWN) != 0) {
            fprintf(stderr, "Failed to set pull-down resistor on GPIO %d\n", channels[i]);
            gpioTerminate();
            return 1;
        }
    }

    // Main loop to read and log the sensor data
    while (!terminate) {
        // Get the current timestamp in milliseconds
        struct timespec ts;
        clock_gettime(CLOCK_MONOTONIC, &ts);
        long timestamp_ms = (ts.tv_sec * 1000) + (ts.tv_nsec / 1000000);

        // Read the state of each channel and print the data
        printf("[%ld ms] ", timestamp_ms);
        for (int i = 0; i < num_channels; i++) {
            int value = gpioRead(channels[i]);
            printf("CH%d=%d ", i + 1, value);
        }
        printf("\n");

        // Delay for 100 milliseconds
        gpioDelay(100000);
    }

    // Terminate the pigpio library before exiting
    gpioTerminate();
    fprintf(stderr, "pigpio terminated.\n");
    return 0;
}

