#include <unistd.h>

// Define GPIO pins for the sensors
#define SENSOR_1_GPIO 4
#define SENSOR_2_GPIO 5

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

int main() {
    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Configure GPIO pins as inputs with pull-up resistors
    if (gpioSetMode(SENSOR_1_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", SENSOR_1_GPIO);
        gpioTerminate();
        return 1;
    }
    gpioSetPullUpDown(SENSOR_1_GPIO, PI_PUD_UP);

    if (gpioSetMode(SENSOR_2_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", SENSOR_2_GPIO);
        gpioTerminate();
        return 1;
    }
    gpioSetPullUpDown(SENSOR_2_GPIO, PI_PUD_UP);

    // Set up signal handling for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop to read sensor states
    while (program_running) {
        // Read the state of sensor 1
        int sensor_1_state = gpioRead(SENSOR_1_GPIO);

        // Read the state of sensor 2
        int sensor_2_state = gpioRead(SENSOR_2_GPIO);

        // Log the sensor states to the console
        printf("Sensor 1: %s, Sensor 2: %s\n",
               (sensor_1_state == 0) ? "LOW" : "HIGH",
               (sensor_2_state == 0) ? "LOW" : "HIGH");

        // Wait for 500 milliseconds
        gpioDelay(500000); // pigpio uses microseconds
    }

    // Terminate the pigpio library before exiting
    gpioTerminate();

    return 0;
}

