#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>
#include <string.h>

// Define GPIO chip and line numbers
#define GPIO_CHIP "gpiochip0"
#define GPIO_LINES {2, 3, 4, 17, 27, 22, 10, 9}
#define NUM_CHANNELS 8

// Global variables for signal handling and GPIO resources
volatile sig_atomic_t program_running = 1;
struct gpiod_chip *gpio_chip = NULL;
struct gpiod_line *gpio_lines[NUM_CHANNELS];

// Function prototypes
int initialize_gpio(void);
int read_sensor_data(void);
int log_data(int sensor_data);
void cleanup_gpio(void);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("\nCaught SIGINT, exiting gracefully...\n");
        program_running = 0;
    }
}

// Function to initialize GPIO lines
int initialize_gpio(void) {
    int i;
    struct gpiod_line_request_config config;

    // Open GPIO chip
    gpio_chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!gpio_chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    // Request GPIO lines
    for (i = 0; i < NUM_CHANNELS; i++) {
        int pin = GPIO_LINES[i];
        gpio_lines[i] = gpiod_chip_get_line(gpio_chip, pin);
        if (!gpio_lines[i]) {
            perror("Error getting GPIO line");
            cleanup_gpio();
            return -1;
        }

        memset(&config, 0, sizeof(config));
        config.consumer = "touch_sensor";
        config.request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT;

        if (gpiod_line_request(gpio_lines[i], &config, 0) < 0) {
            perror("Error requesting GPIO line");
            cleanup_gpio();
            return -1;
        }
    }

    return 0;
}

// Function to read sensor data
int read_sensor_data(void) {
    int i;
    int sensor_data = 0;

    for (i = 0; i < NUM_CHANNELS; i++) {
        int value = gpiod_line_get_value(gpio_lines[i]);
        if (value < 0) {
            perror("Error reading GPIO line value");
            cleanup_gpio();
            exit(EXIT_FAILURE);
        }
        sensor_data |= (value << i);
    }

    return sensor_data;
}

// Function to log data to console
int log_data(int sensor_data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    printf("%s,%d\n", timestamp, sensor_data);
    return 0;
}

// Function to cleanup GPIO resources
void cleanup_gpio(void) {
    int i;

    if (gpio_chip) {
        for (i = 0; i < NUM_CHANNELS; i++) {
            if (gpio_lines[i]) {
                gpiod_line_release(gpio_lines[i]);
            }
        }
        gpiod_chip_close(gpio_chip);
    }
}

int main(void) {
    // Install signal handler
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() < 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return EXIT_FAILURE;
    }

    // Main loop
    while (program_running) {
        int sensor_data = read_sensor_data();
        log_data(sensor_data);
        usleep(50000); // 50 ms delay
    }

    // Cleanup GPIO resources before exiting
    cleanup_gpio();

    return EXIT_SUCCESS;
}

