#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define TILT_SENSOR_GPIO 4

volatile sig_atomic_t program_running = 1;

void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

int main() {
    int current_state, previous_state = -1; // Initialize to an invalid state
    time_t current_time;
    struct tm *time_info;
    char timestamp[20];

    // Register signal handler for SIGINT (Ctrl+C)
    signal(SIGINT, signal_handler);

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Configure GPIO 4 as an input with pull-up resistor
    gpioSetMode(TILT_SENSOR_GPIO, PI_INPUT);
    gpioSetPullUpDown(TILT_SENSOR_GPIO, PI_PUD_UP);

    printf("Tilt sensor monitoring started. Press Ctrl+C to exit.\n");

    while (program_running) {
        current_state = gpioRead(TILT_SENSOR_GPIO);

        if (current_state != 0 && current_state != 1) {
            fprintf(stderr, "Error: Invalid GPIO read value: %d\n", current_state);
        } else {
            if (current_state != previous_state) {
                time(&current_time);
                time_info = localtime(&current_time);
                strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", time_info);

                if (current_state == 0) {
                    printf("%s Tilted\n", timestamp);
                } else {
                    printf("%s Not Tilted\n", timestamp);
                }

                fflush(stdout); // Ensure output is immediately visible
                previous_state = current_state;
            }
        }

        gpioDelay(100); // Poll every 100 ms
    }

    // Terminate pigpio library before exiting
    gpioTerminate();
    printf("pigpio terminated.\n");

    return 0;
}

