#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Si1145 I2C address
#define SI1145_ADDR 0x60

// Si1145 register addresses
#define SI1145_REG_PARTID 0x00
#define SI1145_REG_HW_KEY 0x17
#define SI1145_REG_CHLIST 0x01
#define SI1145_REG_COMMAND 0x07
#define SI1145_REG_ALS_VIS_DATA0 0x22
#define SI1145_REG_UV_INDEX0 0x2C

// Commands
#define SI1145_COMMAND_ALS_FORCE 0x06

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_sensor();
int read_sensor_data(float *uv_index, int *als_visible);
void log_data(float uv_index, int als_visible);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Initialize the Si1145 sensor
int initialize_sensor() {
    int status;

    // Check PART ID
    status = i2cWriteByteData(i2c_handle, SI1145_REG_PARTID, 0x00); // Dummy write to read register
    if (status < 0) {
        fprintf(stderr, "Error writing to PARTID register: %d\n", status);
        return -1;
    }
    int part_id = i2cReadByteData(i2c_handle, SI1145_REG_PARTID);
    if (part_id < 0) {
        fprintf(stderr, "Error reading PARTID register: %d\n", part_id);
        return -1;
    }
    if (part_id != 0x45) {
        fprintf(stderr, "Incorrect PART ID: 0x%02X\n", part_id);
        return -1;
    }
    printf("Si1145 PART ID: 0x%02X\n", part_id);

    // Write HW_KEY
    status = i2cWriteByteData(i2c_handle, SI1145_REG_HW_KEY, 0x17);
    if (status < 0) {
        fprintf(stderr, "Error writing to HW_KEY register: %d\n", status);
        return -1;
    }

    // Configure CHLIST
    status = i2cWriteByteData(i2c_handle, SI1145_REG_CHLIST, 0x01); // Enable UV and ALS_VIS
    if (status < 0) {
        fprintf(stderr, "Error writing to CHLIST register: %d\n", status);
        return -1;
    }

    return 0;
}

// Read UV index and ALS visible data from the sensor
int read_sensor_data(float *uv_index, int *als_visible) {
    int status;

    // Trigger measurement
    status = i2cWriteByteData(i2c_handle, SI1145_REG_COMMAND, SI1145_COMMAND_ALS_FORCE);
    if (status < 0) {
        fprintf(stderr, "Error writing to COMMAND register: %d\n", status);
        return -1;
    }

    // Wait for measurement to complete (adjust as needed)
    gpioDelay(10); // 10ms delay

    // Read ALS_VIS data
    status = i2cReadByteData(i2c_handle, SI1145_REG_ALS_VIS_DATA0);
    if (status < 0) {
        fprintf(stderr, "Error reading ALS_VIS data: %d\n", status);
        return -1;
    }
    int als_visible_low = status;

    status = i2cReadByteData(i2c_handle, SI1145_REG_ALS_VIS_DATA0 + 1);
    if (status < 0) {
        fprintf(stderr, "Error reading ALS_VIS data (high byte): %d\n", status);
        return -1;
    }
    int als_visible_high = status;

    *als_visible = (als_visible_high << 8) | als_visible_low;

    // Read UV_INDEX data
    status = i2cReadByteData(i2c_handle, SI1145_REG_UV_INDEX0);
    if (status < 0) {
        fprintf(stderr, "Error reading UV_INDEX data: %d\n", status);
        return -1;
    }
    *uv_index = (float)status;

    return 0;
}

// Log data to CSV file
void log_data(float uv_index, int als_visible) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f,%d\n", timestamp, uv_index, als_visible);
    fflush(log_file); // Ensure data is written to file immediately
}

int main() {
    float uv_index;
    int als_visible;
    int status;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, SI1145_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize the sensor
    if (initialize_sensor() != 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("uv_als_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Write CSV header if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "timestamp,uv_index,als_visible\n");
    }

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        // Read sensor data
        status = read_sensor_data(&uv_index, &als_visible);
        if (status == 0) {
            // Print data to console
            printf("UV Index: %.2f, ALS Visible: %d\n", uv_index, als_visible);

            // Log data to file
            log_data(uv_index, als_visible);
        } else {
            fprintf(stderr, "Error reading sensor data\n");
        }

        // Wait for 1 second
        gpioDelay(1000); // 1000ms = 1 second
    }

    // Clean up
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

