#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>
#include <time.h>
#include <signal.h>
#include <errno.h>

// Constants
#define I2C_BUS "/dev/i2c-1"
#define SENSOR1_ADDR 0x36
#define SENSOR2_ADDR 0x37
#define GPIO_CHIP "gpiochip0"
#define GPIO_PIN 17
#define SCALE_FACTOR 0.036
#define ALARM_THRESHOLD 0.5
#define LOG_FILE "flow_log.txt"
#define MEASUREMENT_DELAY_MS 100
#define READ_INTERVAL_S 1

// Global variables
static volatile int keep_running = 1;
static int i2c_fd1 = -1;
static int i2c_fd2 = -1;
static struct gpiod_line *gpio_line = NULL;
static struct gpiod_chip *gpio_chip = NULL;
static FILE *log_file = NULL;

// Function prototypes
int init_i2c(int addr);
int init_gpio(int pin);
int start_measurement(int fd);
int read_sensor_data(int fd, int *flow, int *temp);
float convert_flow(int raw_flow);
float calculate_average_flow(float flow1, float flow2);
void control_alarm(float average_flow);
void log_data(float flow1, float flow2, float average_flow);
void signal_handler(int sig);
void cleanup();

// CRC calculation function
unsigned char crc8(const unsigned char *data, int len) {
    unsigned char crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Initialize I2C
int init_i2c(int addr) {
    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C bus");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        perror("Error setting I2C slave address");
        close(fd);
        return -1;
    }

    return fd;
}

// Initialize GPIO
int init_gpio(int pin) {
    struct gpiod_line_request_config config;
    memset(&config, 0, sizeof(config));
    config.consumer = "flow_monitor";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;

    gpio_chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!gpio_chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    gpio_line = gpiod_chip_get_line(gpio_chip, pin);
    if (!gpio_line) {
        perror("Error getting GPIO line");
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    if (gpiod_line_request(gpio_line, &config, 0) < 0) {
        perror("Error requesting GPIO line");
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    return 0;
}

// Start measurement on the sensor
int start_measurement(int fd) {
    unsigned char command[2] = {0x36, 0x08};
    if (write(fd, command, 2) != 2) {
        perror("Error writing to I2C device");
        return -1;
    }
    usleep(MEASUREMENT_DELAY_MS * 1000); // Delay for measurement
    return 0;
}

// Read sensor data
int read_sensor_data(int fd, int *flow, int *temp) {
    unsigned char buffer[9];
    if (read(fd, buffer, 9) != 9) {
        perror("Error reading from I2C device");
        return -1;
    }

    // Validate flow data
    unsigned char flow_data[3] = {buffer[0], buffer[1], buffer[2]};
    unsigned char flow_crc = buffer[3];
    if (crc8(flow_data, 3) != flow_crc) {
        fprintf(stderr, "CRC check failed for flow data\n");
        return -1;
    }

    *flow = (buffer[0] << 8) | buffer[1];

    // Validate temperature data
    unsigned char temp_data[3] = {buffer[6], buffer[7], buffer[8]};
    unsigned char temp_crc = buffer[9];
    if (crc8(temp_data, 3) != temp_crc) {
        fprintf(stderr, "CRC check failed for temperature data\n");
        return -1;
    }

    *temp = (buffer[6] << 8) | buffer[7];

    return 0;
}

// Convert raw flow value to ml/min
float convert_flow(int raw_flow) {
    return (float)raw_flow * SCALE_FACTOR;
}

// Calculate average flow rate
float calculate_average_flow(float flow1, float flow2) {
    return (flow1 + flow2) / 2.0;
}

// Control the alarm based on average flow rate
void control_alarm(float average_flow) {
    if (average_flow < ALARM_THRESHOLD) {
        gpiod_line_set_value(gpio_line, 1); // Set GPIO high
    } else {
        gpiod_line_set_value(gpio_line, 0); // Set GPIO low
    }
}

// Log data to file
void log_data(float flow1, float flow2, float average_flow) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s, Flow1: %.2f ml/min, Flow2: %.2f ml/min, Average: %.2f ml/min\n",
            timestamp, flow1, flow2, average_flow);
    fflush(log_file);
}

// Signal handler for clean shutdown
void signal_handler(int sig) {
    keep_running = 0;
    printf("Caught signal %d, exiting...\n", sig);
}

// Cleanup resources
void cleanup() {
    if (i2c_fd1 != -1) {
        close(i2c_fd1);
    }
    if (i2c_fd2 != -1) {
        close(i2c_fd2);
    }
    if (gpio_line) {
        gpiod_line_release(gpio_line);
    }
    if (gpio_chip) {
        gpiod_chip_close(gpio_chip);
    }
    if (log_file) {
        fclose(log_file);
    }
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    i2c_fd1 = init_i2c(SENSOR1_ADDR);
    if (i2c_fd1 < 0) {
        fprintf(stderr, "Failed to initialize I2C for sensor 1\n");
        return 1;
    }

    i2c_fd2 = init_i2c(SENSOR2_ADDR);
    if (i2c_fd2 < 0) {
        fprintf(stderr, "Failed to initialize I2C for sensor 2\n");
        cleanup();
        return 1;
    }

    // Initialize GPIO
    if (init_gpio(GPIO_PIN) < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Error opening log file");
        cleanup();
        return 1;
    }

    // Main loop
    while (keep_running) {
        int flow1, temp1, flow2, temp2;
        float flow_rate1, flow_rate2, average_flow;

        // Read sensor 1 data
        if (start_measurement(i2c_fd1) == 0 && read_sensor_data(i2c_fd1, &flow1, &temp1) == 0) {
            flow_rate1 = convert_flow(flow1);
        } else {
            flow_rate1 = -1.0; // Indicate error
        }

        // Read sensor 2 data
        if (start_measurement(i2c_fd2) == 0 && read_sensor_data(i2c_fd2, &flow2, &temp2) == 0) {
            flow_rate2 = convert_flow(flow2);
        } else {
            flow_rate2 = -1.0; // Indicate error
        }

        // Calculate average flow rate
        if (flow_rate1 >= 0 && flow_rate2 >= 0) {
            average_flow = calculate_average_flow(flow_rate1, flow_rate2);
        } else {
            average_flow = -1.0; // Indicate error
        }

        // Control alarm
        control_alarm(average_flow);

        // Log data
        log_data(flow_rate1, flow_rate2, average_flow);

        sleep(READ_INTERVAL_S);
    }

    // Cleanup resources before exiting
    cleanup();

    return 0;
}

