#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins
#define SENSOR_1_PIN 23
#define SENSOR_2_PIN 24
#define LED_PIN 25

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT and SIGTERM
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to read sensor value
int read_sensor(int gpio_pin) {
    int value = gpioRead(gpio_pin);
    if (value < 0) {
        fprintf(stderr, "Error reading sensor on GPIO %d\n", gpio_pin);
        return -1; // Indicate error
    }
    return value;
}

// Function to control the LED
void control_led(int gpio_pin, int state) {
    int result = gpioWrite(gpio_pin, state);
    if (result != 0) {
        fprintf(stderr, "Error writing to LED on GPIO %d\n", gpio_pin);
    }
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    if (gpioSetMode(SENSOR_1_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d to input\n", SENSOR_1_PIN);
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(SENSOR_2_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d to input\n", SENSOR_2_PIN);
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(LED_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d to output\n", LED_PIN);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Obstacle avoidance system started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        // Read sensor values
        int sensor1_value = read_sensor(SENSOR_1_PIN);
        int sensor2_value = read_sensor(SENSOR_2_PIN);

        // Check for errors during sensor reading
        if (sensor1_value == -1 || sensor2_value == -1) {
            fprintf(stderr, "Error reading sensors, exiting...\n");
            break; // Exit loop on error
        }

        // Determine LED state based on sensor values
        int led_state = (sensor1_value == 0 || sensor2_value == 0) ? 1 : 0;

        // Control the LED
        control_led(LED_PIN, led_state);

        // Delay for 100 ms
        gpioDelay(100);
    }

    // Clean up and exit
    control_led(LED_PIN, 0); // Turn off LED before exiting
    gpioTerminate();
    printf("Program terminated.\n");
    return 0;
}

