// Constants
#define I2C_BUS 1
#define I2C_ADDRESS 0x0E
#define DATA_REG_START 0x01
#define DATA_REG_END 0x0C
#define DEVICE_ID_REG 0x00
#define DEVICE_ID_VALUE 0x8D
#define LOG_FILE "magnetic_log.csv"
#define SAMPLE_INTERVAL_MS 100

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    int16_t x;
    int16_t y;
    int16_t z;
} sensor_data_t;

// Function prototypes
int initialize_sensor();
int read_sensor_data(sensor_data_t *data);
void convert_to_mt(sensor_data_t *data);
void log_data(sensor_data_t *data);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating...\n", signal);
}

// Function to initialize the sensor
int initialize_sensor() {
    // Check device ID
    char device_id;
    int result = i2cReadI2CBlockData(i2c_handle, DEVICE_ID_REG, &device_id, 1);
    if (result != 1) {
        fprintf(stderr, "Error reading device ID: %d\n", result);
        return -1;
    }

    if (device_id != DEVICE_ID_VALUE) {
        fprintf(stderr, "Incorrect device ID: 0x%02X (expected 0x%02X)\n", device_id, DEVICE_ID_VALUE);
        return -1;
    }

    // Configure for continuous conversion mode and 50mT range (example configuration)
    // Refer to TMAG5170-Q1 datasheet for correct register settings
    // This is a placeholder; actual configuration depends on the sensor's datasheet
    char config_data[2];
    config_data[0] = 0x01; // Example register address
    config_data[1] = 0x00; // Example configuration value

    result = i2cWriteI2CBlockData(i2c_handle, config_data[0], config_data + 1, 1); // Write to the configuration register
    if (result != 1) {
        fprintf(stderr, "Error writing configuration: %d\n", result);
        return -1;
    }

    return 0;
}

// Function to read sensor data
int read_sensor_data(sensor_data_t *data) {
    char buffer[6];
    int result = i2cReadI2CBlockData(i2c_handle, DATA_REG_START, buffer, 6);
    if (result != 6) {
        fprintf(stderr, "Error reading sensor data: %d\n", result);
        return -1;
    }

    // Combine bytes to form 16-bit values (MSB first)
    data->x = (int16_t)((buffer[0] << 8) | buffer[1]);
    data->y = (int16_t)((buffer[2] << 8) | buffer[3]);
    data->z = (int16_t)((buffer[4] << 8) | buffer[5]);

    return 0;
}

// Function to convert raw data to milliteslas
void convert_to_mt(sensor_data_t *data) {
    // LSB scale factor for 50mT range (example value, check datasheet)
    float lsb_scale = 0.001; // Example: 1 LSB = 0.001 mT

    data->x *= lsb_scale;
    data->y *= lsb_scale;
    data->z *= lsb_scale;
}

