#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>
#include <string.h>

#define GPIO_PIN 23
#define LOG_FILE "flood_log.txt"

volatile sig_atomic_t program_running = 1;

// Function to handle signals (SIGINT, SIGTERM)
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to read the water level sensor
int read_water_level() {
    int level = gpioRead(GPIO_PIN);
    if (level < 0) {
        fprintf(stderr, "Error reading GPIO %d: %d\n", GPIO_PIN, level);
        return -1; // Indicate an error
    }
    return level;
}

// Function to log an alert to the file
void log_alert() {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file %s\n", LOG_FILE);
        return;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "%s ALERT: Water detected\n", timestamp);
    fclose(fp);
    printf("%s ALERT: Water detected\n", timestamp);
}

// Function to log an error to the file
void log_error(const char *message) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file %s\n", LOG_FILE);
        return;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "%s ERROR: %s\n", timestamp, message);
    fclose(fp);
    fprintf(stderr, "%s ERROR: %s\n", timestamp, message);
}

int main() {
    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        log_error("pigpio initialisation failed");
        return 1;
    }

    // Set GPIO pin as input with pull-down resistor
    gpioSetMode(GPIO_PIN, PI_INPUT);
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_DOWN);

    printf("Water level monitoring started. Press Ctrl+C to exit.\n");

    while (program_running) {
        int water_level = read_water_level();
        if (water_level == 1) {
            log_alert();
        } else if (water_level < 0) {
            // Error reading sensor, attempt to re-initialize pigpio
            log_error("Failed to read water level, attempting to re-initialize pigpio...");
            gpioTerminate();
            gpioInitialise();
            gpioSetMode(GPIO_PIN, PI_INPUT);
            gpioSetPullUpDown(GPIO_PIN, PI_PUD_DOWN);
        }

        gpioDelay(2000); // Wait 2 seconds
    }

    // Clean up and exit
    gpioTerminate();
    printf("Water level monitoring stopped.\n");
    return 0;
}

