#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define GPIO_PIN 4
#define LOG_FILE "rpm_log.txt"

// Global variables
static volatile int pulse_count = 0;
static volatile int running = 1;
static FILE *log_file = NULL;

// Function prototypes
void pulse_callback(int gpio, int level, uint32_t tick, void *user);
int read_rpm();
void log_rpm(int rpm);
void signal_handler(int signal);

// Callback function for rising edge detection
void pulse_callback(int gpio, int level, uint32_t tick, void *user)
{
    if (level == PI_HIGH) // Rising edge
    {
        gpioAtomicInc(GPIO_PIN, 1); // Increment pulse count atomically
    }
}

// Function to read RPM
int read_rpm()
{
    int rpm;
    int local_pulse_count;

    // Disable interrupts temporarily
    gpioSetAlertFuncEx(GPIO_PIN, NULL, NULL);

    // Read the current pulse count
    local_pulse_count = pulse_count;

    // Reset the pulse count
    pulse_count = 0;

    // Re-enable interrupts
    gpioSetAlertFuncEx(GPIO_PIN, pulse_callback, NULL);

    // Calculate RPM
    rpm = local_pulse_count * 60;

    return rpm;
}

// Function to log RPM to file
void log_rpm(int rpm)
{
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file != NULL)
    {
        fprintf(log_file, "%s %d\n", timestamp, rpm);
        fflush(log_file); // Ensure data is written to disk immediately
    }
    else
    {
        fprintf(stderr, "Error: Log file not opened.\n");
    }

    printf("%s %d\n", timestamp, rpm);
}

// Signal handler for Ctrl+C
void signal_handler(int signal)
{
    printf("Caught signal %d, exiting gracefully.\n", signal);
    running = 0;

    // Disable interrupts
    gpioSetAlertFuncEx(GPIO_PIN, NULL, NULL);

    // Close log file
    if (log_file != NULL)
    {
        fclose(log_file);
    }

    // Terminate pigpio
    gpioTerminate();

    exit(0);
}

int main()
{
    int pigpio_init_result;

    // Initialize pigpio
    pigpio_init_result = gpioInitialise();
    if (pigpio_init_result < 0)
    {
        fprintf(stderr, "pigpio initialisation failed: %d\n", pigpio_init_result);
        return 1;
    }

    // Set GPIO pin as input with pull-up resistor
    gpioSetMode(GPIO_PIN, PI_INPUT);
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_UP);

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL)
    {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Set up interrupt callback
    gpioSetAlertFuncEx(GPIO_PIN, pulse_callback, NULL);

    // Main loop
    while (running)
    {
        int rpm = read_rpm();
        log_rpm(rpm);
        gpioDelay(1000); // Sample every 1 second
    }

    return 0;
}

