#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <syslog.h>
#include <pigpio.h>

// Define GPIO pins
#define TOUCH_SENSOR_PIN 23
#define LED_PIN 18

// Global variables
static volatile int running = 1;
static int gpio_initialized = 0;

// Function prototypes
int initialize_gpio();
int read_touch_sensor();
void control_led(int state);
void log_event(const char *message);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    running = 0;
    log_event("Signal received, shutting down...");
    cleanup();
    exit(0);
}

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        log_event("pigpio initialisation failed");
        return -1;
    }
    gpio_initialized = 1;

    gpioSetMode(TOUCH_SENSOR_PIN, PI_INPUT);
    gpioSetMode(LED_PIN, PI_OUTPUT);
    gpioSetPullUpDown(TOUCH_SENSOR_PIN, PI_PUD_DOWN); // Optional: Use pull-down resistor

    log_event("GPIO initialisation successful");
    return 0;
}

// Read the touch sensor state
int read_touch_sensor() {
    return gpioRead(TOUCH_SENSOR_PIN);
}

// Control the LED state
void control_led(int state) {
    gpioWrite(LED_PIN, state);
}

// Log events to syslog
void log_event(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[26];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    syslog(LOG_INFO, "%s: %s", timestamp, message);
}

// Cleanup function to release resources
void cleanup() {
    if (gpio_initialized) {
        control_led(0); // Turn off LED
        gpioTerminate();
        log_event("pigpio terminated");
    }
    closelog();
}

int main() {
    // Open syslog
    openlog("touch_sensor", LOG_PID | LOG_CONS, LOG_USER);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        log_event("GPIO initialisation failed, exiting");
        closelog();
        return 1;
    }

    log_event("Application started");

    // Main loop
    while (running) {
        int touch_detected = read_touch_sensor();

        if (touch_detected) {
            control_led(1); // Turn on LED
            log_event("Touch detected");
        } else {
            control_led(0); // Turn off LED
        }

        gpioDelay(50); // Wait 50ms
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

