void signal_handler(int signal) {
    program_running = 0;
    fprintf(stderr, "\nCaught signal %d, shutting down...\n", signal);
}

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if (gpioSetMode(SENSOR_1_PIN, PI_INPUT) != 0) {
