#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <pigpio.h>

// Define GPIO pins for the Hall-Effect sensors
#define SENSOR1_GPIO 17
#define SENSOR2_GPIO 18

// Debounce time in milliseconds
#define DEBOUNCE_TIME 5

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;

// Structure to hold sensor states
typedef struct {
    int sensor1_state;
    int sensor2_state;
} SensorStates;

// Function prototypes
void signal_handler(int signal);
int initialize_gpio();
int initialize_logging();
void cleanup();
void log_sensor_data(SensorStates states);
double calculate_rpm(double time_diff_sec);
void sensor1_callback(int gpio, int level, uint32_t tick);
void sensor2_callback(int gpio, int level, uint32_t tick);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(SENSOR1_GPIO, PI_INPUT);
    gpioSetMode(SENSOR2_GPIO, PI_INPUT);

    // Set pull-up/down resistors if needed (adjust as necessary)
    gpioSetPullUpDown(SENSOR1_GPIO, PI_PUD_DOWN);
    gpioSetPullUpDown(SENSOR2_GPIO, PI_PUD_DOWN);

    return 0;
}

// Initialize logging to a CSV file
int initialize_logging() {
    log_file = fopen("shaft_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return 1;
    }

    // Write header if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "timestamp,sensor1_state,sensor2_state\n");
    }

    return 0;
}

// Cleanup resources before exiting
void cleanup() {
    printf("Cleaning up...\n");
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

// Log sensor data to the CSV file
void log_sensor_data(SensorStates states) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%d,%d\n", timestamp, states.sensor1_state, states.sensor2_state);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Calculate RPM based on the time difference between pulses
double calculate_rpm(double time_diff_sec) {
    if (time_diff_sec > 0) {
        return (60.0 / time_diff_sec) / 2.0; // 60 seconds in a minute, 2 pulses per revolution
    } else {
        return 0.0;
    }
}

// Callback function for sensor 1
void sensor1_callback(int gpio, int level, uint32_t tick) {
    static uint32_t last_tick = 0;
    uint32_t current_tick = gpioTick();

    if (current_tick - last_tick > DEBOUNCE_TIME * 1000) {
        last_tick = current_tick;

        SensorStates states;
        states.sensor1_state = level;
        states.sensor2_state = gpioRead(SENSOR2_GPIO);

        log_sensor_data(states);

        double time_diff_sec = (double)(current_tick - last_tick) / 1000000.0; // Convert microseconds to seconds
        double rpm = calculate_rpm(time_diff_sec);
        printf("Sensor 1: Level %d, RPM: %.2f\n", level, rpm);
    }
}

// Callback function for sensor 2
void sensor2_callback(int gpio, int level, uint32_t tick) {
    static uint32_t last_tick = 0;
    uint32_t current_tick = gpioTick();

    if (current_tick - last_tick > DEBOUNCE_TIME * 1000) {
        last_tick = current_tick;

        SensorStates states;
        states.sensor1_state = gpioRead(SENSOR1_GPIO);
        states.sensor2_state = level;

        log_sensor_data(states);

        double time_diff_sec = (double)(current_tick - last_tick) / 1000000.0; // Convert microseconds to seconds
        double rpm = calculate_rpm(time_diff_sec);
        printf("Sensor 2: Level %d, RPM: %.2f\n", level, rpm);
    }
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Initialize logging
    if (initialize_logging() != 0) {
        cleanup();
        return 1;
    }

    // Set up callbacks for both sensors
    gpioSetAlertFuncEx(SENSOR1_GPIO, sensor1_callback, NULL);
    gpioSetAlertFuncEx(SENSOR2_GPIO, sensor2_callback, NULL);

    printf("RPM monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        gpioDelay(100); // Sleep for 100ms to reduce CPU usage
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

