        double rpm = calculate_rpm(time_diff_sec);
        printf("Sensor 1: Level %d, RPM: %.2f\n", level, rpm);
    }
}

// Callback function for sensor 2
void sensor2_callback(int gpio, int level, uint32_t tick) {
    static uint32_t last_tick = 0;
    uint32_t current_tick = gpioTick();

    if (current_tick - last_tick > DEBOUNCE_TIME * 1000) {
        last_tick = current_tick;

        SensorStates states;
        states.sensor1_state = gpioRead(SENSOR1_GPIO);
        states.sensor2_state = level;

        log_sensor_data(states);

        double time_diff_sec = (double)(current_tick - last_tick) / 1000000.0; // Convert microseconds to seconds
        double rpm = calculate_rpm(time_diff_sec);
        printf("Sensor 2: Level %d, RPM: %.2f\n", level, rpm);
    }
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Initialize logging
    if (initialize_logging() != 0) {
        cleanup();
        return 1;
    }

    // Set up callbacks for both sensors
    gpioSetAlertFuncEx(SENSOR1_GPIO, sensor1_callback, NULL);
    gpioSetAlertFuncEx(SENSOR2_GPIO, sensor2_callback, NULL);

    printf("RPM monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        gpioDelay(100); // Sleep for 100ms to reduce CPU usage
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

