#define SENSOR_2_PIN 18
#define ALARM_PIN 27

// Define alarm duration (in seconds)
#define ALARM_DURATION 2

// Global variables
FILE *log_file = NULL;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize_gpio();
int read_sensor(int gpio_pin);
void activate_alarm();
void deactivate_alarm();
void log_event(const char *event_type, int sensor_id, int state);
void signal_handler(int signal);
char* get_iso8601_timestamp();

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(SENSOR_1_PIN, PI_INPUT);
    gpioSetPullUpDown(SENSOR_1_PIN, PI_PUD_DOWN);

    gpioSetMode(SENSOR_2_PIN, PI_INPUT);
    gpioSetPullUpDown(SENSOR_2_PIN, PI_PUD_DOWN);

    gpioSetMode(ALARM_PIN, PI_OUTPUT);
    gpioWrite(ALARM_PIN, PI_LOW);

    return 0;
}

// Function to read sensor value
int read_sensor(int gpio_pin) {
    return gpioRead(gpio_pin);
}

// Function to activate the alarm
void activate_alarm() {
    gpioWrite(ALARM_PIN, PI_HIGH);
    gpioDelay(ALARM_DURATION * 1000000); // Delay for alarm duration (in microseconds)
    gpioWrite(ALARM_PIN, PI_LOW);
}

// Function to deactivate the alarm
void deactivate_alarm() {
    gpioWrite(ALARM_PIN, PI_LOW);
}

// Function to log events to file
void log_event(const char *event_type, int sensor_id, int state) {
    char *timestamp = get_iso8601_timestamp();
    if (timestamp == NULL) {
        fprintf(stderr, "Failed to get timestamp\n");
        return;
    }

    fprintf(log_file, "%s - Sensor %d - %s - State: %d\n", timestamp, sensor_id, event_type, state);
    fflush(log_file); // Ensure data is written to disk immediately
    free(timestamp);
}

// Function to get ISO-8601 timestamp
char* get_iso8601_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    char *timestamp = (char*)malloc(25 * sizeof(char)); // Allocate memory for timestamp

    if (timestamp == NULL) {
        perror("Failed to allocate memory for timestamp");
        return NULL;
    }

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, 25, "%Y-%m-%dT%H:%M:%S", timeinfo);
    return timestamp;
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open log file
    log_file = fopen("bridge_integrity.log", "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        gpioTerminate();
        return 1;
    }

    int sensor1_state = 0;
    int sensor2_state = 0;
    int alarm_active = 0;
    unsigned long alarm_start_time = 0;

    printf("Bridge integrity monitoring started. Press Ctrl+C to exit.\n");

    while (program_running) {
        // Read sensor values
        int current_sensor1_state = read_sensor(SENSOR_1_PIN);
        int current_sensor2_state = read_sensor(SENSOR_2_PIN);

        // Log sensor state changes
        if (current_sensor1_state != sensor1_state) {
            log_event("Tilt Start", 1, current_sensor1_state);
            sensor1_state = current_sensor1_state;
        }
        if (current_sensor2_state != sensor2_state) {
            log_event("Tilt Start", 2, current_sensor2_state);
            sensor2_state = current_sensor2_state;
        }

        // Check for alarm condition
        if (sensor1_state == 1 || sensor2_state == 1) {
            if (!alarm_active) {
                log_event("Threshold Exceeded", (sensor1_state == 1) ? 1 : 2, 1);
                activate_alarm();
                alarm_active = 1;
                alarm_start_time = gpioTick();
            }
        } else {
            if (alarm_active) {
                log_event("Tilt End", (sensor1_state == 1) ? 1 : 2, 0);
                deactivate_alarm();
                alarm_active = 0;
            }
        }

        gpioDelay(100000); // 100 ms delay
    }

    // Cleanup
    printf("Cleaning up...\n");
    deactivate_alarm();
    fclose(log_file);
    gpioTerminate();

    printf("Exiting.\n");
    return 0;
}

