#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <math.h>
#include <string.h>

// Constants
#define I2C_BUS 1
#define D7S_ADDR 0x1D
#define CTRL1_REG 0x1F
#define ACCEL_X_REG 0x28
#define LED_GPIO 17
#define THRESHOLD 500
#define SAMPLE_INTERVAL_MS 100
#define RETRY_COUNT 3

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure for sensor data
typedef struct {
    int16_t x;
    int16_t y;
    int16_t z;
} sensor_data_t;

// Function prototypes
int initialize_sensor();
sensor_data_t read_sensor_data();
double calculate_vibration_magnitude(sensor_data_t data);
void control_led(int on);
void log_event(double magnitude);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initializes the Omron D7S-A0011 sensor
int initialize_sensor() {
    int retries = 0;
    while (retries < RETRY_COUNT) {
        // Check if the sensor is present by reading a register
        char buf[1];
        buf[0] = CTRL1_REG; // Read CTRL1 register
        if (i2cWriteDevice(i2c_handle, buf, 1) != 0) {
            fprintf(stderr, "Error writing to I2C device: %d\n", i2c_handle);
            retries++;
            gpioDelay(1000); // Wait before retrying
            continue;
        }

        if (i2cReadDevice(i2c_handle, buf, 1) != 1) {
            fprintf(stderr, "Error reading from I2C device: %d\n", i2c_handle);
            retries++;
            gpioDelay(1000); // Wait before retrying
            continue;
        }

        // Clear power-down bit in CTRL1 register (0x1F)
        char ctrl1_data[2];
        ctrl1_data[0] = CTRL1_REG;
        ctrl1_data[1] = 0x00; // Clear power-down bit

        if (i2cWriteDevice(i2c_handle, ctrl1_data, 2) != 0) {
            fprintf(stderr, "Error writing to CTRL1 register: %d\n", i2c_handle);
            retries++;
            gpioDelay(1000); // Wait before retrying
            continue;
        }

        printf("Sensor initialized successfully.\n");
        return 0; // Success
    }

    fprintf(stderr, "Failed to initialize sensor after %d retries.\n", RETRY_COUNT);
    return -1; // Failure
}

// Reads acceleration data from the sensor
sensor_data_t read_sensor_data() {
    sensor_data_t data;
    char buffer[6];
    int retries = 0;

    while (retries < RETRY_COUNT) {
        if (i2cWriteDevice(i2c_handle, (char[]){ACCEL_X_REG}, 1) != 0) {
            fprintf(stderr, "Error writing to I2C device for read: %d\n", i2c_handle);
            retries++;
            gpioDelay(1000); // Wait before retrying
            continue;
        }

        if (i2cReadDevice(i2c_handle, buffer, 6) != 6) {
            fprintf(stderr, "Error reading from I2C device: %d\n", i2c_handle);
            retries++;
            gpioDelay(1000); // Wait before retrying
            continue;
        }

        // Combine bytes to form 16-bit values (little-endian)
        data.x = (int16_t)((buffer[1] << 8) | buffer[0]);
        data.y = (int16_t)((buffer[3] << 8) | buffer[2]);
        data.z = (int16_t)((buffer[5] << 8) | buffer[4]);
        return data;
    }

