#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <syslog.h>
#include <gpiod.h>
#include <unistd.h>

// Define GPIO pins for the flame sensors
#define SENSOR1_GPIO 2
#define SENSOR2_GPIO 3
#define SENSOR3_GPIO 4
#define SENSOR4_GPIO 17
#define SENSOR5_GPIO 27

// Debounce delay in milliseconds
#define DEBOUNCE_DELAY_MS 50

// Global flag to signal program termination
volatile sig_atomic_t terminate = 0;

// Structure to hold GPIO line information
typedef struct {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    int gpio_pin;
} gpio_line_t;

// Array to store GPIO line information
gpio_line_t gpio_lines[5];

// Function prototypes
int init_gpio(gpio_line_t *line, int gpio_pin);
int read_sensor(gpio_line_t *line);
int log_event(int sensor_id, int gpio_pin);
void signal_handler(int sig);
void cleanup();

// Signal handler function
void signal_handler(int sig) {
    syslog(LOG_USER, "Signal received, terminating...");
    terminate = 1;
}

// Function to initialize a GPIO line
int init_gpio(gpio_line_t *line, int gpio_pin) {
    line->gpio_pin = gpio_pin;
    line->chip = gpiod_chip_open_by_name("gpiochip0");
    if (!line->chip) {
        syslog(LOG_ERR, "Failed to open GPIO chip: %m");
        return -1;
    }

    line->line = gpiod_chip_get_line(line->chip, gpio_pin);
    if (!line->line) {
        syslog(LOG_ERR, "Failed to get GPIO line %d: %m", gpio_pin);
        gpiod_chip_close(line->chip);
        return -1;
    }

    struct gpiod_line_request_config config;
    memset(&config, 0, sizeof(config));
    config.consumer = "flame_monitor";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT;

    if (gpiod_line_request(line->line, &config, 0) < 0) {
        syslog(LOG_ERR, "Failed to request GPIO line %d: %m", gpio_pin);
        gpiod_chip_close(line->chip);
        return -1;
    }

    return 0;
}

// Function to read the sensor value
int read_sensor(gpio_line_t *line) {
    int value = gpiod_line_get_value(line->line);
    if (value < 0) {
        syslog(LOG_ERR, "Failed to read GPIO line %d: %m", line->gpio_pin);
        return -1;
    }
    return value;
}

// Function to log an event to syslog
int log_event(int sensor_id, int gpio_pin) {
    time_t now = time(NULL);
    struct tm *tstruct = gmtime(&now);
    char buf[80];
    strftime(buf, sizeof(buf), "%Y-%m-%dT%H:%M:%SZ", tstruct);

    syslog(LOG_USER, "%s - Sensor ID: %d (GPIO %d) - Flame Detected", buf, sensor_id, gpio_pin);
    return 0;
}

// Function to cleanup GPIO resources
void cleanup() {
    syslog(LOG_USER, "Cleaning up GPIO resources...");
    for (int i = 0; i < 5; i++) {
        if (gpio_lines[i].line) {
            gpiod_line_release(gpio_lines[i].line);
        }
        if (gpio_lines[i].chip) {
            gpiod_chip_close(gpio_lines[i].chip);
        }
    }
    closelog();
}

int main() {
    // Initialize syslog
    openlog("flame_monitor", LOG_PID | LOG_CONS, LOG_USER);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO lines
    gpio_lines[0].gpio_pin = SENSOR1_GPIO;
    gpio_lines[1].gpio_pin = SENSOR2_GPIO;
    gpio_lines[2].gpio_pin = SENSOR3_GPIO;
    gpio_lines[3].gpio_pin = SENSOR4_GPIO;
    gpio_lines[4].gpio_pin = SENSOR5_GPIO;

    for (int i = 0; i < 5; i++) {
        if (init_gpio(&gpio_lines[i], gpio_lines[i].gpio_pin) < 0) {
            syslog(LOG_ERR, "Failed to initialize GPIO %d, exiting...", gpio_lines[i].gpio_pin);
            cleanup();
            return 1;
        }
    }

    // Main loop
    while (!terminate) {
        for (int i = 0; i < 5; i++) {
            int sensor_value = read_sensor(&gpio_lines[i]);
            if (sensor_value < 0) {
                syslog(LOG_ERR, "Failed to read sensor on GPIO %d, continuing...", gpio_lines[i].gpio_pin);
                continue; // Continue to the next sensor
            }

            // Flame detected (LOW signal)
            if (sensor_value == 0) {
                // Debounce
                usleep(DEBOUNCE_DELAY_MS * 1000); // Convert ms to microseconds
                int debounced_value = read_sensor(&gpio_lines[i]);
                if (debounced_value < 0) {
                    syslog(LOG_ERR, "Failed to read sensor on GPIO %d during debounce, continuing...", gpio_lines[i].gpio_pin);
                    continue; // Continue to the next sensor
                }

                if (debounced_value == 0) {
                    log_event(i + 1, gpio_lines[i].gpio_pin);
                }
            }
        }

        sleep(1); // Poll every 1 second
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

