#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define VEML7700_ADDR 0x10
#define CONFIG_REG 0x00
#define ALS_REG 0x04
#define GPIO_LED 18
#define PWM_FREQ 1000
#define PWM_RANGE 100
#define LUX_SCALE 0.0576

// Thresholds for adaptive brightness
#define LUX_THRESHOLD_1 100
#define LUX_THRESHOLD_2 500
#define LUX_THRESHOLD_3 1000

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_pigpio();
int init_i2c();
int config_veml7700();
int read_als_raw();
float convert_to_lux(int raw_value);
int set_led_brightness(float lux);
int log_data(float lux, int brightness, int error_code);
void signal_handler(int signal);

// Structure for VEML7700 configuration
typedef struct {
    uint8_t gain;
    uint8_t integration_time;
} veml7700_config_t;

// Function to initialize pigpio
int init_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Function to initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, VEML7700_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to configure the VEML7700 sensor
int config_veml7700() {
    veml7700_config_t config = {0x00, 0x00}; // Gain 1/8, Integration Time 100ms
    uint8_t data[2];
    data[0] = config.gain;
    data[1] = config.integration_time;

    int result = i2cWriteI2CBlockData(i2c_handle, CONFIG_REG, (char *)data, 2);
    if (result < 0) {
        fprintf(stderr, "Failed to write config register: %d\n", result);
        return -1;
    }
    return 0;
}

// Function to read raw ALS value from the sensor
int read_als_raw() {
    char buffer[2];
    int result = i2cReadI2CBlockData(i2c_handle, ALS_REG, buffer, 2);
    if (result < 0) {
        fprintf(stderr, "Failed to read ALS register: %d\n", result);
        return -1;
    }

    // Combine the two bytes into a 16-bit value (little-endian)
    int raw_value = (buffer[1] << 8) | buffer[0];
    return raw_value;
}

// Function to convert raw ALS value to lux
float convert_to_lux(int raw_value) {
    return (float)raw_value * LUX_SCALE;
}

// Function to set LED brightness based on lux value
int set_led_brightness(float lux) {
    int brightness = 0;

    if (lux < LUX_THRESHOLD_1) {
        brightness = PWM_RANGE;
    } else if (lux < LUX_THRESHOLD_2) {
        brightness = (int)(PWM_RANGE * 0.75);
    } else if (lux < LUX_THRESHOLD_3) {
        brightness = (int)(PWM_RANGE * 0.5);
    } else {
        brightness = (int)(PWM_RANGE * 0.25);
    }

    gpioPWM(GPIO_LED, brightness);
    return brightness;
}

// Function to log data to file
int log_data(float lux, int brightness, int error_code) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp) - 1, "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s, Lux: %.2f, Brightness: %d, Error Code: %d\n", timestamp, lux, brightness, error_code);
    fflush(log_file);
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Received signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (init_pigpio() != 0) {
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Configure VEML7700 sensor
    if (config_veml7700() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO 18 as output
    gpioSetMode(GPIO_LED, PI_OUTPUT);

    // Set PWM frequency and range
    gpioSetPWMfrequency(GPIO_LED, PWM_FREQ);
    gpioSetPWMrange(GPIO_LED, PWM_RANGE);

    // Open log file
    log_file = fopen("grow_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (!terminate) {
        int raw_value = read_als_raw();
        if (raw_value < 0) {
            log_data(0.0, 0, -1); // Log error
        } else {
            float lux = convert_to_lux(raw_value);
            int brightness = set_led_brightness(lux);
            log_data(lux, brightness, 0); // Log data
        }

        sleep(1);
    }

    // Cleanup
    gpioPWM(GPIO_LED, 0); // Turn off LED
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

