#define LED_PIN 17

// Debounce time in milliseconds
#define DEBOUNCE_TIME 50

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;

// Function prototypes
int initialize_gpio();
int read_touch_sensors();
void log_touch_event(int channel);
void control_led(int state);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
    control_led(0); // Turn off LED
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate(); // Release pigpio resources
    exit(0);
}

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set touch sensor pins as inputs with pull-down resistors
    gpioSetMode(TOUCH_PIN_1, PI_INPUT);
    gpioSetPullUpDown(TOUCH_PIN_1, PI_PUD_DOWN);
    gpioSetMode(TOUCH_PIN_2, PI_INPUT);
    gpioSetPullUpDown(TOUCH_PIN_2, PI_PUD_DOWN);
    gpioSetMode(TOUCH_PIN_3, PI_INPUT);
    gpioSetPullUpDown(TOUCH_PIN_3, PI_PUD_DOWN);
    gpioSetMode(TOUCH_PIN_4, PI_INPUT);
    gpioSetPullUpDown(TOUCH_PIN_4, PI_PUD_DOWN);
    gpioSetMode(TOUCH_PIN_5, PI_INPUT);
    gpioSetPullUpDown(TOUCH_PIN_5, PI_PUD_DOWN);
    gpioSetMode(TOUCH_PIN_6, PI_INPUT);
    gpioSetPullUpDown(TOUCH_PIN_6, PI_PUD_DOWN);
    gpioSetMode(TOUCH_PIN_7, PI_INPUT);
    gpioSetPullUpDown(TOUCH_PIN_7, PI_PUD_DOWN);
    gpioSetMode(TOUCH_PIN_8, PI_INPUT);
    gpioSetPullUpDown(TOUCH_PIN_8, PI_PUD_DOWN);

    // Set LED pin as output
    gpioSetMode(LED_PIN, PI_OUTPUT);

    return 0;
}

// Read touch sensor values
int read_touch_sensors() {
    int sensor_values = 0;
    sensor_values |= (gpioRead(TOUCH_PIN_1) << 0);
    sensor_values |= (gpioRead(TOUCH_PIN_2) << 1);
    sensor_values |= (gpioRead(TOUCH_PIN_3) << 2);
    sensor_values |= (gpioRead(TOUCH_PIN_4) << 3);
    sensor_values |= (gpioRead(TOUCH_PIN_5) << 4);
    sensor_values |= (gpioRead(TOUCH_PIN_6) << 5);
    sensor_values |= (gpioRead(TOUCH_PIN_7) << 6);
    sensor_values |= (gpioRead(TOUCH_PIN_8) << 7);
    return sensor_values;
}

// Log touch event to file
void log_touch_event(int channel) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s - Channel %d Touched\n", timestamp, channel);
        fflush(log_file); // Ensure data is written to file immediately
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

// Control LED state
void control_led(int state) {
    gpioWrite(LED_PIN, state);
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open log file
    log_file = fopen("touch_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate(); // Release pigpio resources
        return 1;
    }

    int last_sensor_values = 0;
    int current_sensor_values = 0;
    int debounce_counter = 0;

    printf("Security Keypad Simulation started. Press Ctrl+C to exit.\n");

    while (running) {
        current_sensor_values = read_touch_sensors();

        for (int i = 0; i < 8; i++) {
            if ((current_sensor_values & (1 << i)) && !(last_sensor_values & (1 << i))) {
                // Channel i just touched
                debounce_counter++;
                if (debounce_counter >= DEBOUNCE_TIME) {
                    log_touch_event(i + 1);
                    debounce_counter = 0; // Reset debounce counter
                }
            } else if (!(current_sensor_values & (1 << i)) && (last_sensor_values & (1 << i))) {
                // Channel i just released
                debounce_counter++;
                if (debounce_counter >= DEBOUNCE_TIME) {
                    debounce_counter = 0; // Reset debounce counter
                }
            } else {
                debounce_counter = 0; // Reset debounce counter if state is stable
            }
        }

        last_sensor_values = current_sensor_values;

        // Control LED based on touch sensor state
        int any_touched = (current_sensor_values > 0);
        control_led(any_touched);

        gpioDelay(50); // Poll every 50 ms
    }

    // Cleanup (should not reach here if signal handler works correctly)
    control_led(0); // Turn off LED
    fclose(log_file);
    gpioTerminate(); // Release pigpio resources

    return 0;
}

