#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define OPT3001_ADDR 0x44
#define CONFIG_REG 0x01
#define RESULT_REG 0x00
#define CONFIG_WORD 0xC810 // Continuous mode, auto range, 100ms conversion time
#define SLEEP_TIME_US 1000000 // 1 second

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_pigpio();
int init_i2c();
int write_config();
int read_result();
double calculate_lux(uint16_t raw_result);
int log_data(double lux_value);
void signal_handler(int signal);
void cleanup();

// Structure for configuration (optional)
typedef struct {
    int i2c_bus;
    int opt3001_address;
    int config_register;
    int result_register;
    uint16_t config_word;
    char *log_file_name;
} opt3001_config_t;


int main() {
    // Initialize pigpio
    if (init_pigpio() != 0) {
        fprintf(stderr, "Failed to initialize pigpio. Exiting.\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        fprintf(stderr, "Failed to initialize I2C. Exiting.\n");
        gpioTerminate();
        return 1;
    }

    // Write configuration to OPT3001
    if (write_config() != 0) {
        fprintf(stderr, "Failed to write configuration to OPT3001. Exiting.\n");
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen("light_data.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file. Exiting.\n");
        cleanup();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        // Read result from OPT3001
        int raw_result = read_result();
        if (raw_result >= 0) {
            // Calculate lux value
            double lux_value = calculate_lux((uint16_t)raw_result);

            // Log data to file
            if (log_data(lux_value) != 0) {
                fprintf(stderr, "Failed to log data. Continuing.\n");
            }

            // Print lux value to stdout
            printf("Lux: %.2f\n", lux_value);
        } else {
            fprintf(stderr, "Failed to read result from OPT3001. Continuing.\n");
        }

        // Sleep for 1 second
        gpioDelay(SLEEP_TIME_US);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

// Initialize pigpio library
int init_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }
    return 0;
}

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, OPT3001_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        return 1;
    }
    return 0;
}

// Write configuration to OPT3001
int write_config() {
    uint16_t config_word_be = ((CONFIG_WORD >> 8) & 0xFF) | ((CONFIG_WORD << 8) & 0xFF00);
    int result = i2cWriteWordData(i2c_handle, CONFIG_REG, config_word_be);
    if (result < 0) {
        fprintf(stderr, "Failed to write configuration: %d\n", result);
        return 1;
    }
    gpioDelay(100000); // Wait 100ms for conversion
    return 0;
}

// Read result from OPT3001
int read_result() {
    int raw_result = i2cReadWordData(i2c_handle, RESULT_REG);
    if (raw_result < 0) {
        fprintf(stderr, "Failed to read result: %d\n", raw_result);
        return -1;
    }
    return raw_result;
}

// Calculate lux value from raw result
double calculate_lux(uint16_t raw_result) {
    int exponent = (raw_result >> 12) & 0x0F;
    int mantissa = raw_result & 0x0FFF;
    return mantissa * 0.01 * (1 << exponent);
}

// Log data to file
int log_data(double lux_value) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(log_file, "%s, %.2f\n", timestamp, lux_value);
    fflush(log_file); // Ensure data is written to disk
    return 0;
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("Ctrl+C pressed. Exiting.\n");
    terminate = 1;
}

// Cleanup resources
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

