#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define GPIO_PIN 4
#define DEBOUNCE_DELAY_MS 50
#define LOG_FILE "touch_log.txt"

static volatile int running = 1;
static int last_state = 0; // Initialize to 0 (pulled down)

// Function to handle signals (SIGINT, SIGTERM)
void signal_handler(int signal) {
    running = 0;
    fprintf(stderr, "\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to get the current timestamp in the desired format
char* get_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    char *timestamp = (char*)malloc(20 * sizeof(char)); // Allocate memory for the timestamp string

    if (timestamp == NULL) {
        fprintf(stderr, "Error: Failed to allocate memory for timestamp.\n");
        return NULL;
    }

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, 20, "%Y-%m-%d %H:%M:%S", timeinfo);
    return timestamp;
}

// Function to log the event to the file
int log_event(const char* event_type) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not open log file %s for writing.\n", LOG_FILE);
        return -1;
    }

    char* timestamp = get_timestamp();
    if (timestamp == NULL) {
        fclose(fp);
        return -1;
    }

    fprintf(fp, "%s: %s\n", timestamp, event_type);
    fflush(fp);
    fclose(fp);
    free(timestamp);
    return 0;
}

int main() {
    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return 1;
    }

    // Set GPIO4 as an input with pull-down resistor
    gpioSetMode(GPIO_PIN, PI_INPUT);
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_DOWN);

    fprintf(stderr, "Touch sensor monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        int current_state = gpioRead(GPIO_PIN);

        if (current_state != last_state) {
            if (current_state == 1) {
                if (log_event("Touch Detected") != 0) {
                    fprintf(stderr, "Error: Failed to log touch event.\n");
                }
            } else {
                if (log_event("Touch Released") != 0) {
                    fprintf(stderr, "Error: Failed to log release event.\n");
                }
            }
            last_state = current_state;
            gpioDelay(DEBOUNCE_DELAY_MS * 1000); // Debounce delay
        }
        gpioDelay(1000); // Check every 1ms
    }

    // Cleanup before exiting
    gpioSetMode(GPIO_PIN, PI_INPUT); // Set back to input
    gpioTerminate();

    fprintf(stderr, "Touch sensor monitoring stopped.\n");
    return 0;
}

