#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define I2C_ADDRESS 0x08
#define FLOW_COMMAND_HIGH 0x36
#define FLOW_COMMAND_LOW 0x08
#define FLOW_DATA_LENGTH 3
#define FLOW_RATE_SCALE 90.0
#define FLOW_RATE_MIN 0.0
#define FLOW_RATE_MAX 100.0
#define LOG_FILE "cooling_log.csv"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_i2c();
int read_flow_data(int16_t *raw_flow);
uint8_t calculate_crc(const uint8_t *data, size_t length);
int validate_crc(const uint8_t *data, size_t length, uint8_t crc);
float convert_to_ml_min(int16_t raw_flow);
char *get_status(float flow_rate);
int log_data(float flow_rate, const char *status);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Initializes the I2C connection
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Reads flow data from the sensor
int read_flow_data(int16_t *raw_flow) {
    char write_buffer[2] = {FLOW_COMMAND_HIGH, FLOW_COMMAND_LOW};
    char read_buffer[FLOW_DATA_LENGTH];

    if (i2cWriteDevice(i2c_handle, write_buffer, 2) != 2) {
        fprintf(stderr, "Error writing to I2C device\n");
        return -1;
    }

    gpioDelay(2); // Wait 2 ms

    if (i2cReadDevice(i2c_handle, read_buffer, FLOW_DATA_LENGTH) != FLOW_DATA_LENGTH) {
        fprintf(stderr, "Error reading from I2C device\n");
        return -1;
    }

    *raw_flow = (int16_t)((read_buffer[0] << 8) | read_buffer[1]);
    return 0;
}

// Calculates the CRC-8 checksum
uint8_t calculate_crc(const uint8_t *data, size_t length) {
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < length; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Validates the CRC-8 checksum
int validate_crc(const uint8_t *data, size_t length, uint8_t crc) {
    uint8_t calculated_crc = calculate_crc(data, length);
    return (calculated_crc == crc);
}

// Converts the raw flow value to ml/min
float convert_to_ml_min(int16_t raw_flow) {
    return (float)raw_flow / FLOW_RATE_SCALE;
}

// Determines the status based on the flow rate
char *get_status(float flow_rate) {
    if (flow_rate < FLOW_RATE_MIN || flow_rate > FLOW_RATE_MAX) {
        return "INVALID";
    }
    return "OK";
}

// Logs the data to a CSV file
int log_data(float flow_rate, const char *status) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (log_file == NULL) {
        fprintf(stderr, "Error: Log file is not open.\n");
        return -1;
    }

    fprintf(log_file, "%s,%.2f,%s\n", timestamp, flow_rate, status);
    fflush(log_file); // Ensure data is written to disk
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handling
    signal(SIGINT, signal_handler);

    // Initialize I2C
    if (initialize_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Open the log file
    log_file = fopen(LOG_FILE, "a+");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Write the header row if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Flow Rate (ml/min),Status\n");
    }
    rewind(log_file);

    int16_t raw_flow;
    float flow_rate;
    char *status;

    while (!terminate) {
        // Read flow data
        if (read_flow_data(&raw_flow) == 0) {
            uint8_t crc = (uint8_t)read_buffer[2];

            // Validate CRC
            if (validate_crc((uint8_t *)read_buffer, FLOW_DATA_LENGTH - 1, crc)) {
                // Convert to ml/min
                flow_rate = convert_to_ml_min(raw_flow);

                // Get status
                status = get_status(flow_rate);

                // Log data
                if (log_data(flow_rate, status) != 0) {
                    fprintf(stderr, "Error logging data\n");
                }
            } else {
                fprintf(stderr, "CRC validation failed\n");
                log_data(-1.0, "ERROR"); // Log error
            }
        } else {
            fprintf(stderr, "Failed to read flow data\n");
            log_data(-1.0, "ERROR"); // Log error
        }

        gpioDelay(1000); // Sample every 1 second
    }

    // Cleanup
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

