#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <gpiod.h>
#include <stdbool.h>

// Define GPIO pins for the sensors
#define LEFT_SENSOR_PIN 17
#define MIDDLE_SENSOR_PIN 27
#define RIGHT_SENSOR_PIN 22

// Define the GPIO chip name
#define GPIO_CHIP_NAME "gpiochip0"

// Define the log file name
#define LOG_FILE_NAME "path_log.csv"

// Global variables for signal handling
static volatile sig_atomic_t keep_running = 1;
static struct gpiod_chip *gpio_chip = NULL;
static struct gpiod_line *left_line = NULL;
static struct gpiod_line *middle_line = NULL;
static struct gpiod_line *right_line = NULL;
static FILE *log_file = NULL;

// Function prototypes
int read_sensor(struct gpiod_line *line);
int log_data(FILE *fp, int left, int middle, int right);
void signal_handler(int sig);
int setup_gpio(void);
int cleanup_gpio(void);

// Signal handler function
void signal_handler(int sig) {
    if (sig == SIGINT) {
        fprintf(stderr, "\nCaught SIGINT, exiting gracefully.\n");
        keep_running = 0;
    }
}

// Function to read the sensor value from a GPIO line
int read_sensor(struct gpiod_line *line) {
    int value = gpiod_line_get_value(line);
    if (value < 0) {
        fprintf(stderr, "Error reading sensor value: %s\n", strerror(-value));
        return -1; // Indicate an error
    }
    return value;
}

// Function to log the sensor data to a CSV file
int log_data(FILE *fp, int left, int middle, int right) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[21]; // YYYY-MM-DDTHH:MM:SSZ\0

    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    if (fprintf(fp, "%s,%d,%d,%d\n", timestamp, left, middle, right) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        return -1; // Indicate an error
    }
    return 0;
}

// Function to set up the GPIO lines
int setup_gpio(void) {
    int ret;

    // Open the GPIO chip
    gpio_chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!gpio_chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", strerror(errno));
        return -1;
    }

    // Request the left sensor line as input
    left_line = gpiod_chip_get_line(gpio_chip, LEFT_SENSOR_PIN);
    if (!left_line) {
        fprintf(stderr, "Error getting left sensor line: %s\n", strerror(errno));
        goto cleanup_gpio_error;
    }

    ret = gpiod_line_request_input(left_line, "left_sensor");
    if (ret < 0) {
        fprintf(stderr, "Error requesting left sensor line as input: %s\n", strerror(-ret));
        goto cleanup_gpio_error;
    }

    // Request the middle sensor line as input
    middle_line = gpiod_chip_get_line(gpio_chip, MIDDLE_SENSOR_PIN);
    if (!middle_line) {
        fprintf(stderr, "Error getting middle sensor line: %s\n", strerror(errno));
        goto cleanup_gpio_error;
    }

    ret = gpiod_line_request_input(middle_line, "middle_sensor");
    if (ret < 0) {
        fprintf(stderr, "Error requesting middle sensor line as input: %s\n", strerror(-ret));
        goto cleanup_gpio_error;
    }

    // Request the right sensor line as input
    right_line = gpiod_chip_get_line(gpio_chip, RIGHT_SENSOR_PIN);
    if (!right_line) {
        fprintf(stderr, "Error getting right sensor line: %s\n", strerror(errno));
        goto cleanup_gpio_error;
    }

    ret = gpiod_line_request_input(right_line, "right_sensor");
    if (ret < 0) {
        fprintf(stderr, "Error requesting right sensor line as input: %s\n", strerror(-ret));
        goto cleanup_gpio_error;
    }

    return 0;

cleanup_gpio_error:
    if (left_line) gpiod_line_release(left_line);
    if (middle_line) gpiod_line_release(middle_line);
    if (right_line) gpiod_line_release(right_line);
    if (gpio_chip) gpiod_chip_close(gpio_chip);
    return -1;
}

// Function to clean up the GPIO lines
int cleanup_gpio(void) {
    if (left_line) gpiod_line_release(left_line);
    if (middle_line) gpiod_line_release(middle_line);
    if (right_line) gpiod_line_release(right_line);
    if (gpio_chip) gpiod_chip_close(gpio_chip);
    return 0;
}

int main(void) {
    int left_value, middle_value, right_value;
    int ret;

    // Set up signal handling for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize the GPIO lines
    if (setup_gpio() < 0) {
        fprintf(stderr, "GPIO setup failed. Exiting.\n");
        return 1;
    }

    // Open the log file in append mode
    log_file = fopen(LOG_FILE_NAME, "a");
    if (!log_file) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        cleanup_gpio();
        return 1;
    }

    // Write the CSV header if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "timestamp,left,middle,right\n");
    }
    rewind(log_file);

    // Main loop to read and log sensor data
    while (keep_running) {
        // Read sensor values
        left_value = read_sensor(left_line);
        middle_value = read_sensor(middle_line);
        right_value = read_sensor(right_line);

        // Log the data if all sensor readings were successful
        if (left_value >= 0 && middle_value >= 0 && right_value >= 0) {
            if (log_data(log_file, left_value, middle_value, right_value) < 0) {
                fprintf(stderr, "Error logging data. Continuing.\n");
            }
        } else {
            fprintf(stderr, "Error reading sensor data. Skipping logging.\n");
        }

        // Wait for 50 milliseconds
        struct timespec delay;
        delay.tv_sec = 0;
        delay.tv_nsec = 50 * 1000 * 1000; // 50 milliseconds
        nanosleep(&delay, NULL);
    }

    // Clean up and exit
    fclose(log_file);
    cleanup_gpio();
    return 0;
}

