    if (right_line) gpiod_line_release(right_line);
    if (gpio_chip) gpiod_chip_close(gpio_chip);
    return 0;
}

int main(void) {
    int left_value, middle_value, right_value;
    int ret;

    // Set up signal handling for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize the GPIO lines
    if (setup_gpio() < 0) {
        fprintf(stderr, "GPIO setup failed. Exiting.\n");
        return 1;
    }

    // Open the log file in append mode
    log_file = fopen(LOG_FILE_NAME, "a");
    if (!log_file) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        cleanup_gpio();
        return 1;
    }

    // Write the CSV header if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "timestamp,left,middle,right\n");
    }
    rewind(log_file);

    // Main loop to read and log sensor data
    while (keep_running) {
        // Read sensor values
        left_value = read_sensor(left_line);
        middle_value = read_sensor(middle_line);
        right_value = read_sensor(right_line);

        // Log the data if all sensor readings were successful
        if (left_value >= 0 && middle_value >= 0 && right_value >= 0) {
            if (log_data(log_file, left_value, middle_value, right_value) < 0) {
                fprintf(stderr, "Error logging data. Continuing.\n");
            }
        } else {
            fprintf(stderr, "Error reading sensor data. Skipping logging.\n");
        }

        // Wait for 50 milliseconds
        struct timespec delay;
        delay.tv_sec = 0;
        delay.tv_nsec = 50 * 1000 * 1000; // 50 milliseconds
        nanosleep(&delay, NULL);
    }

    // Clean up and exit
    fclose(log_file);
    cleanup_gpio();
    return 0;
}

