#include <gpiod.h>
#include <unistd.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_LINE 4
#define LOG_FILE "flame_events.txt"

static volatile int keep_running = 1;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *line = NULL;
static FILE *log_file = NULL;

// Function to handle signals (SIGINT, SIGTERM)
void signal_handler(int sig) {
    keep_running = 0;
    fprintf(stderr, "\nCaught signal %d, exiting gracefully...\n", sig);
}

// Function to get the current timestamp as a string
char* get_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    static char timestamp[20]; // YYYY-MM-DD HH:MM:SS\0

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    return timestamp;
}

// Function to log an event to the log file
int log_event(const char *timestamp) {
    if (log_file == NULL) {
        fprintf(stderr, "Error: Log file is not open.\n");
        return -1;
    }

    if (fprintf(log_file, "%s\n", timestamp) < 0) {
        fprintf(stderr, "Error writing to log file.\n");
        return -1;
    }
    fflush(log_file); // Ensure data is written to disk
    return 0;
}

// Function to handle the flame detection event
void flame_detected_callback(int gpio, struct gpiod_line *line, struct gpiod_line_event *event) {
    char *timestamp = get_timestamp();
    printf("Flame detected at %s\n", timestamp);
    if (log_event(timestamp) != 0) {
        fprintf(stderr, "Error logging event.\n");
    }
}

int main() {
    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open the GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Error opening GPIO chip");
        return 1;
    }

    // Get the GPIO line
    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        perror("Error getting GPIO line");
        gpiod_chip_close(chip);
        return 1;
    }

    // Request the GPIO line for input
    if (gpiod_line_request_input(line, "flame_sensor") < 0) {
        perror("Error requesting GPIO line for input");
        gpiod_chip_close(chip);
        return 1;
    }

    // Open the log file
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Error opening log file");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Set up edge detection on the falling edge
    if (gpiod_line_request_events(line, GPIOD_LINE_EVENT_FALLING_EDGE) < 0) {
        perror("Error requesting events");
        fclose(log_file);
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Register the callback function for flame detection
    if (gpiod_line_set_callback(line, flame_detected_callback) < 0) {
        perror("Error setting callback");
        fclose(log_file);
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return 1;
    }

    fprintf(stderr, "Flame sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop to keep the program running until a signal is received
    while (keep_running) {
        sleep(1); // Reduce CPU usage
    }

    // Clean up resources before exiting
    gpiod_line_set_callback(line, NULL); // Disable callback
    gpiod_line_release(line);
    fclose(log_file);
    gpiod_chip_close(chip);

    fprintf(stderr, "Exiting.\n");
    return 0;
}

