#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins
#define TOUCH_SENSOR_PIN 23
#define LED_PIN 24

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;

// Function prototypes
void signal_handler(int signal);
int initialize_gpio();
void cleanup_gpio();
void log_event(const char *event_type, int led_state);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(TOUCH_SENSOR_PIN, PI_INPUT);
    gpioSetMode(LED_PIN, PI_OUTPUT);

    return 0;
}

// Cleanup GPIO resources
void cleanup_gpio() {
    gpioWrite(LED_PIN, 0); // Turn off LED
    gpioTerminate();
}

// Log events to file
void log_event(const char *event_type, int led_state) {
    time_t now = time(NULL);
    struct tm *tstruct = localtime(&now);
    char buf[80];
    strftime(buf, sizeof(buf), "%Y-%m-%dT%H:%M:%SZ", tstruct);

    if (log_file != NULL) {
        fprintf(log_file, "%s - %s - LED State: %d\n", buf, event_type, led_state);
        fflush(log_file); // Ensure data is written to disk immediately
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

int main() {
    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open log file
    log_file = fopen("touch_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        cleanup_gpio();
        return 1;
    }

    int led_state = 0; // Initial LED state

    printf("Touch sensor monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        // Read touch sensor state
        int touch_detected = gpioRead(TOUCH_SENSOR_PIN);

        if (touch_detected == 1) {
            // Toggle LED state
            led_state = !led_state;
            gpioWrite(LED_PIN, led_state);

            // Log the event
            log_event("Touch Detected", led_state);

            // Debounce delay (not strictly needed, but good practice)
            gpioDelay(100); // 100ms
        }

        gpioDelay(10); // Small delay to reduce CPU usage
    }

    // Cleanup and exit
    printf("Cleaning up and exiting...\n");
    fclose(log_file);
    cleanup_gpio();

    return 0;
}

