#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <gpiod.h>

// Define GPIO pins
#define FLAME_SENSOR_PIN 17
#define BUZZER_PIN 18

// Define debounce delay (in milliseconds)
#define DEBOUNCE_DELAY_MS 50

// Global variables
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *flame_line = NULL;
static struct gpiod_line *buzzer_line = NULL;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_gpio(void);
int init_log(void);
void log_event(const char *message);
void activate_buzzer(void);
void deactivate_buzzer(void);
void signal_handler(int sig);
void cleanup(void);

// Signal handler function
void signal_handler(int sig) {
    terminate = 1;
    log_event("Received signal, shutting down...");
}

// Initialize GPIO lines
int init_gpio(void) {
    int ret;

    // Open GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", strerror(errno));
        return -1;
    }

    // Get flame sensor line
    flame_line = gpiod_chip_get_line(chip, FLAME_SENSOR_PIN);
    if (!flame_line) {
        fprintf(stderr, "Error getting flame sensor line: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        return -1;
    }

    // Request flame sensor line as input
    ret = gpiod_line_request_input(flame_line, "flame_sensor");
    if (ret < 0) {
        fprintf(stderr, "Error requesting flame sensor line as input: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        return -1;
    }

    // Get buzzer line
    buzzer_line = gpiod_chip_get_line(chip, BUZZER_PIN);
    if (!buzzer_line) {
        fprintf(stderr, "Error getting buzzer line: %s\n", strerror(errno));
        gpiod_line_release(flame_line);
        gpiod_chip_close(chip);
        return -1;
    }

    // Request buzzer line as output
    ret = gpiod_line_request_output(buzzer_line, "buzzer", 0); // Initialize to LOW
    if (ret < 0) {
        fprintf(stderr, "Error requesting buzzer line as output: %s\n", strerror(errno));
        gpiod_line_release(flame_line);
        gpiod_chip_close(chip);
        return -1;
    }

    return 0;
}

// Initialize log file
int init_log(void) {
    log_file = fopen("alert_log.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return -1;
    }

    // Log system start
    log_event("System started");

    return 0;
}

// Log an event with timestamp
void log_event(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s: %s\n", timestamp, message);
    fflush(log_file); // Ensure immediate write to file
    printf("%s: %s\n", timestamp, message); // Also print to console
}

// Activate the buzzer
void activate_buzzer(void) {
    int ret = gpiod_line_set_value(buzzer_line, 1);
    if (ret < 0) {
        fprintf(stderr, "Error setting buzzer value: %s\n", strerror(errno));
    }
}

// Deactivate the buzzer
void deactivate_buzzer(void) {
    int ret = gpiod_line_set_value(buzzer_line, 0);
    if (ret < 0) {
        fprintf(stderr, "Error setting buzzer value: %s\n", strerror(errno));
    }
}

// Cleanup resources
void cleanup(void) {
    log_event("System stopped");

    // Release GPIO lines
    if (flame_line) {
        gpiod_line_release(flame_line);
    }
    if (buzzer_line) {
        gpiod_line_release(buzzer_line);
    }

    // Close GPIO chip
    if (chip) {
        gpiod_chip_close(chip);
    }

    // Close log file
    if (log_file) {
        fclose(log_file);
    }
}

int main(void) {
    int ret;
    int last_value = 1; // Assume no flame initially (HIGH)
    struct timespec delay;
    delay.tv_sec = 0;
    delay.tv_nsec = 100 * 1000 * 1000; // 100 milliseconds

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (init_gpio() < 0) {
        return 1;
    }

    // Initialize log file
    if (init_log() < 0) {
        cleanup();
        return 1;
    }

    log_event("System started");

    // Main loop
    while (!terminate) {
        int current_value = gpiod_line_get_value(flame_line);

        if (current_value < 0) {
            fprintf(stderr, "Error reading flame sensor value: %s\n", strerror(errno));
            break; // Exit loop on error
        }

        if (current_value == 0 && last_value == 1) {
            // Flame detected (LOW to HIGH transition)
            log_event("Flame detected!");
            activate_buzzer();
            nanosleep(&delay, NULL); // 100ms delay
            deactivate_buzzer();
            nanosleep(&delay, NULL); // 100ms delay
            nanosleep(&delay, NULL); // 100ms delay
            nanosleep(&delay, NULL); // 100ms delay
            nanosleep(&delay, NULL); // 100ms delay
            nanosleep(&delay, NULL); // 100ms delay
            nanosleep(&delay, NULL); // 100ms delay
            nanosleep(&delay, NULL); // 100ms delay
            nanosleep(&delay, NULL); // 100ms delay
            nanosleep(&delay, NULL); // 100ms delay
        }

        last_value = current_value;
        nanosleep(&delay, NULL); // Poll every 100ms
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

