    return 0;
}

// Log an event with timestamp
void log_event(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s: %s\n", timestamp, message);
    fflush(log_file); // Ensure immediate write to file
    printf("%s: %s\n", timestamp, message); // Also print to console
}

// Activate the buzzer
void activate_buzzer(void) {
    int ret = gpiod_line_set_value(buzzer_line, 1);
    if (ret < 0) {
        fprintf(stderr, "Error setting buzzer value: %s\n", strerror(errno));
    }
}

// Deactivate the buzzer
void deactivate_buzzer(void) {
    int ret = gpiod_line_set_value(buzzer_line, 0);
    if (ret < 0) {
        fprintf(stderr, "Error setting buzzer value: %s\n", strerror(errno));
    }
}

// Cleanup resources
void cleanup(void) {
    log_event("System stopped");

    // Release GPIO lines
    if (flame_line) {
        gpiod_line_release(flame_line);
    }
    if (buzzer_line) {
        gpiod_line_release(buzzer_line);
    }

    // Close GPIO chip
    if (chip) {
        gpiod_chip_close(chip);
    }

    // Close log file
    if (log_file) {
        fclose(log_file);
    }
}

int main(void) {
    int ret;
    int last_value = 1; // Assume no flame initially (HIGH)
    struct timespec delay;
    delay.tv_sec = 0;
    delay.tv_nsec = 100 * 1000 * 1000; // 100 milliseconds

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (init_gpio() < 0) {
        return 1;
    }

    // Initialize log file
    if (init_log() < 0) {
        cleanup();
        return 1;
    }

    log_event("System started");

    // Main loop
    while (!terminate) {
        int current_value = gpiod_line_get_value(flame_line);

        if (current_value < 0) {
            fprintf(stderr, "Error reading flame sensor value: %s\n", strerror(errno));
            break; // Exit loop on error
        }

        if (current_value == 0 && last_value == 1) {
            // Flame detected (LOW to HIGH transition)
            log_event("Flame detected!");
            activate_buzzer();
            nanosleep(&delay, NULL); // 100ms delay
            deactivate_buzzer();
            nanosleep(&delay, NULL); // 100ms delay
            nanosleep(&delay, NULL); // 100ms delay
            nanosleep(&delay, NULL); // 100ms delay
            nanosleep(&delay, NULL); // 100ms delay
            nanosleep(&delay, NULL); // 100ms delay
            nanosleep(&delay, NULL); // 100ms delay
            nanosleep(&delay, NULL); // 100ms delay
            nanosleep(&delay, NULL); // 100ms delay
            nanosleep(&delay, NULL); // 100ms delay
        }

        last_value = current_value;
        nanosleep(&delay, NULL); // Poll every 100ms
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

