#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>
#include <string.h>

#define TOUCH_PIN 4
#define LED_PIN 17

volatile sig_atomic_t program_running = 1;

void signal_handler(int signal) {
    program_running = 0;
    fprintf(stderr, "\nCaught signal %d, exiting gracefully.\n", signal);
}

int main() {
    int pigpio_init_result;
    int gpio_mode_result;
    int gpio_set_mode_result;
    int gpio_write_result;
    FILE *log_file;
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];
    int last_touch_state = 0; // 0 = released, 1 = touched
    int led_state = 0; // 0 = off, 1 = on
    int debounce_counter = 0;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    pigpio_init_result = gpioInitialise();
    if (pigpio_init_result < 0) {
        fprintf(stderr, "pigpio initialisation failed: %d\n", pigpio_init_result);
        return 1;
    }

    // Set GPIO4 as input
    gpio_mode_result = gpioSetMode(TOUCH_PIN, PI_INPUT);
    if (gpio_mode_result != 0) {
        fprintf(stderr, "Failed to set GPIO%d as input: %d\n", TOUCH_PIN, gpio_mode_result);
        gpioTerminate();
        return 1;
    }

    // Set GPIO17 as output
    gpio_set_mode_result = gpioSetMode(LED_PIN, PI_OUTPUT);
    if (gpio_set_mode_result != 0) {
        fprintf(stderr, "Failed to set GPIO%d as output: %d\n", LED_PIN, gpio_set_mode_result);
        gpioTerminate();
        return 1;
    }

    // Open the log file
    log_file = fopen("touch_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    fprintf(stdout, "Touch sensor monitoring started. Press Ctrl+C to exit.\n");

    while (program_running) {
        int current_touch_state = gpioRead(TOUCH_PIN);

        if (current_touch_state != last_touch_state) {
            debounce_counter++;
            if (debounce_counter >= 20) { // 20 * 10ms = 200ms
                if (current_touch_state == 1) { // Rising edge (LOW-to-HIGH)
                    // Toggle LED
                    led_state = !led_state;
                    gpio_write_result = gpioWrite(LED_PIN, led_state);
                    if (gpio_write_result != 0) {
                        fprintf(stderr, "Error writing to GPIO%d: %d\n", LED_PIN, gpio_write_result);
                    }

                    // Log the event
                    time(&rawtime);
                    timeinfo = gmtime(&rawtime);
                    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

                    if (fprintf(log_file, "%s - Touch detected\n", timestamp) < 0) {
                        fprintf(stderr, "Error writing to log file!\n");
                    }
                    fflush(log_file); // Ensure data is written to disk

                    last_touch_state = current_touch_state;
                    debounce_counter = 0; // Reset debounce counter
                }
            }
        } else {
            debounce_counter = 0; // Reset debounce counter if state is stable
        }

        gpioDelay(10); // Poll every 10 ms
    }

    // Cleanup
    gpioWrite(LED_PIN, 0); // Turn off LED
    fclose(log_file);
    gpioTerminate();

    fprintf(stdout, "Program terminated.\n");
    return 0;
}

