int read_sensor(int gpio);
int log_state_change(int sensor_id, int state);
void signal_handler(int signal);

// Structure to hold sensor states
typedef struct {
    int sensor1_state;
    int sensor2_state;
    int sensor3_state;
} SensorStates;

SensorStates current_states = {1, 1, 1}; // Initialize all sensors to magnet-removed (HIGH)
SensorStates previous_states = {1, 1, 1};

// Function to initialize the pigpio library and configure GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Configure GPIO pins as inputs with pull-up resistors
    if (gpioSetMode(SENSOR1_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set mode for SENSOR1_GPIO\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetPullUpDown(SENSOR1_GPIO, PI_PUD_UP) != 0) {
        fprintf(stderr, "Failed to set pull-up for SENSOR1_GPIO\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(SENSOR2_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set mode for SENSOR2_GPIO\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetPullUpDown(SENSOR2_GPIO, PI_PUD_UP) != 0) {
        fprintf(stderr, "Failed to set pull-up for SENSOR2_GPIO\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(SENSOR3_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set mode for SENSOR3_GPIO\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetPullUpDown(SENSOR3_GPIO, PI_PUD_UP) != 0) {
        fprintf(stderr, "Failed to set pull-up for SENSOR3_GPIO\n");
        gpioTerminate();
        return 1;
    }

    return 0;
}

// Function to read the state of a sensor
int read_sensor(int gpio) {
    int state = gpioRead(gpio);
    if (state < 0) {
        fprintf(stderr, "Error reading sensor on GPIO %d\n", gpio);
        return -1; // Indicate an error
    }
    return state;
}

