        // Read sensor states
        int sensor1_state = read_sensor(SENSOR1_GPIO);
        int sensor2_state = read_sensor(SENSOR2_GPIO);
        int sensor3_state = read_sensor(SENSOR3_GPIO);

        if (sensor1_state == -1 || sensor2_state == -1 || sensor3_state == -1) {
            // Handle sensor read error (already logged in read_sensor)
            gpioDelay(100); // Wait before retrying
            continue;
        }

        // Check for state changes and log them
        if (sensor1_state != previous_states.sensor1_state) {
            log_state_change(1, sensor1_state);
            previous_states.sensor1_state = sensor1_state;
        }
        if (sensor2_state != previous_states.sensor2_state) {
            log_state_change(2, sensor2_state);
