        if (sensor3_state != previous_states.sensor3_state) {
            log_state_change(3, sensor3_state);
            previous_states.sensor3_state = sensor3_state;
        }

        // Delay for 100 ms
        gpioDelay(100);
    }

    // Clean up and exit
    fclose(log_file);
    gpioTerminate();
    return 0;
}

