#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Constants
#define I2C_BUS 1
#define SI1182_ADDR 0x4A
#define LED_CURRENT_REG 0x3F
#define AVG_REG 0x04
#define ENABLE_REG 0x01
#define HR_REG 0x2A
#define PART_ID_REG 0x00
#define HW_REV_REG 0x01
#define MOVING_AVG_SIZE 5

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure for sensor configuration
typedef struct {
    uint8_t led_current;
    uint8_t averaging;
    uint8_t enable;
} sensor_config_t;

// Function prototypes
int initialize_sensor();
int read_heart_rate(int *raw_hr);
float convert_to_bpm(int raw_hr);
float apply_moving_average(float new_bpm, float *bpm_history, int history_size);
int validate_bpm(float bpm);
int log_data(float bpm);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initializes the Si1182-A-GM sensor
int initialize_sensor() {
    int status;

    // Check PART_ID
    status = i2cReadByteData(i2c_handle, PART_ID_REG);
    if (status < 0) {
        fprintf(stderr, "Error reading PART_ID: %d\n", status);
        return -1;
    }
    if ((uint8_t)status != 0x02) {
        fprintf(stderr, "Incorrect PART_ID: 0x%02X\n", status);
        return -1;
    }

    // Check HW_REV
    status = i2cReadByteData(i2c_handle, HW_REV_REG);
    if (status < 0) {
        fprintf(stderr, "Error reading HW_REV: %d\n", status);
        return -1;
    }
    if ((uint8_t)status != 0x01) {
        fprintf(stderr, "Incorrect HW_REV: 0x%02X\n", status);
        return -1;
    }

    // Configure sensor
    if (i2cWriteByteData(i2c_handle, LED_CURRENT_REG, 0x3F) < 0) {
        fprintf(stderr, "Error writing LED current\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, AVG_REG, 0x04) < 0) {
        fprintf(stderr, "Error writing averaging\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, ENABLE_REG, 0x01) < 0) {
        fprintf(stderr, "Error writing enable\n");
        return -1;
    }

    return 0;
}

// Reads the heart-rate data from the sensor
int read_heart_rate(int *raw_hr) {
    int status;
    int retries = 3;

    while (retries > 0) {
        status = i2cReadWordData(i2c_handle, HR_REG);
        if (status >= 0) {
            *raw_hr = status;
            return 0; // Success
        } else {
            fprintf(stderr, "Error reading heart rate: %d, retries remaining: %d\n", status, retries);
            retries--;
            gpioDelay(10000); // Wait 10ms before retrying
        }
    }

    fprintf(stderr, "Failed to read heart rate after multiple retries.\n");
    return -1; // Failure
}

// Converts the raw heart-rate value to BPM
float convert_to_bpm(int raw_hr) {
    return (float)raw_hr * 0.5;
}

// Applies a 5-sample moving average filter
float apply_moving_average(float new_bpm, float *bpm_history, int history_size) {
    static int index = 0;
    static float history[MOVING_AVG_SIZE] = {0.0};
    float sum = 0.0;

    history[index] = new_bpm;
    index = (index + 1) % history_size;

    for (int i = 0; i < history_size; i++) {
        sum += history[i];
    }

    return sum / history_size;
}

// Validates the BPM value
int validate_bpm(float bpm) {
    return (bpm >= 30.0 && bpm <= 220.0);
}

// Logs the BPM data to a CSV file
int log_data(float bpm) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(log_file, "%s,%.2f\n", timestamp, bpm);
