#include <pigpio.h>

#define GPIO_PIN 17
#define LOG_FILE "flame_log.txt"

static volatile int running = 1;
static int gpio_initialized = 0;

// Function to handle signals (SIGINT, SIGTERM)
void signal_handler(int signal) {
    running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to get the current timestamp as a string
char* get_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    char *timestamp = (char*)malloc(20 * sizeof(char)); // Allocate memory for the timestamp string

    if (timestamp == NULL) {
        perror("Failed to allocate memory for timestamp");
        return NULL;
    }

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, 20, "%Y-%m-%d %H:%M:%S", timeinfo);
    return timestamp;
}

// Function to log the event to a file
int log_event(const char* timestamp) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("Error opening log file");
        return -1;
    }

    fprintf(fp, "%s FLAME DETECTED\n", timestamp);
    fflush(fp); // Ensure the data is written to the file immediately
    fclose(fp);
    return 0;
}

// Callback function for falling edge detection
void flame_detected_callback(int gpio, int level, uint32_t tick) {
    if (level == 0) { // Falling edge detected (HIGH to LOW)
        char* timestamp = get_timestamp();
        if (timestamp != NULL) {
            printf("FLAME DETECTED at %s\n", timestamp);
            if (log_event(timestamp) != 0) {
                fprintf(stderr, "Error logging event.\n");
            }
            free(timestamp); // Free the allocated memory
        } else {
            fprintf(stderr, "Failed to get timestamp.\n");
        }
    }
}

int main() {
    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }
    gpio_initialized = 1;

    // Set GPIO17 as input with pull-up resistor
    gpioSetMode(GPIO_PIN, PI_INPUT);
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_UP);

    // Set alert function for falling edge detection
    gpioSetAlertFunc(GPIO_PIN, flame_detected_callback);

    printf("Flame sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        gpioDelay(100); // Poll every 100 ms
    }

    // Cleanup
    gpioSetAlertFunc(GPIO_PIN, NULL); // Disable the callback
    if (gpio_initialized) {
        gpioTerminate();
    }

    printf("Exiting.\n");
    return 0;
}

