int update_counter(int sensor_pins[], int num_sensors);
int write_counter_to_gpio(int counter_value);
int log_touch_event(int channel, int counter_value);
void signal_handler(int sig);

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    printf("\nCaught signal %d, exiting gracefully...\n", sig);
    running = 0;

    // Reset all output pins to 0
    for (int i = 0; i < 8; i++) {
        if (counter_lines[i] != NULL) {
            gpiod_line_set_value(counter_lines[i], 0);
        }
    }

    // Release sensor lines
    for (int i = 0; i < 8; i++) {
        if (sensor_lines[i] != NULL) {
            gpiod_line_release(sensor_lines[i]);
        }
    }

    // Release counter lines
    for (int i = 0; i < 8; i++) {
        if (counter_lines[i] != NULL) {
            gpiod_line_release(counter_lines[i]);
        }
    }

    // Close the chip
    if (chip != NULL) {
        gpiod_chip_close(chip);
    }

    exit(0);
}

// Initialize GPIO pins
int initialize_gpio() {
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", strerror(errno));
        return -1;
    }

    // Request sensor lines as inputs
    sensor_lines[0] = gpiod_chip_get_line(chip, SENSOR_1_PIN);
    sensor_lines[1] = gpiod_chip_get_line(chip, SENSOR_2_PIN);
    sensor_lines[2] = gpiod_chip_get_line(chip, SENSOR_3_PIN);
    sensor_lines[3] = gpiod_chip_get_line(chip, SENSOR_4_PIN);
    sensor_lines[4] = gpiod_chip_get_line(chip, SENSOR_5_PIN);
    sensor_lines[5] = gpiod_chip_get_line(chip, SENSOR_6_PIN);
    sensor_lines[6] = gpiod_chip_get_line(chip, SENSOR_7_PIN);
    sensor_lines[7] = gpiod_chip_get_line(chip, SENSOR_8_PIN);

    for (int i = 0; i < 8; i++) {
        if (!sensor_lines[i]) {
            fprintf(stderr, "Error getting sensor line %d: %s\n", i + 1, strerror(errno));
            // Release previously acquired lines
            for (int j = 0; j < i; j++) {
                if (sensor_lines[j] != NULL) {
                    gpiod_line_release(sensor_lines[j]);
                }
            }
            for (int j = 0; j < 8; j++) {
                if (counter_lines[j] != NULL) {
                    gpiod_line_release(counter_lines[j]);
                }
            }
            gpiod_chip_close(chip);
            return -1;
        }
        if (gpiod_line_request_input(sensor_lines[i], "touch_sensor") < 0) {
            fprintf(stderr, "Error requesting sensor line %d as input: %s\n", i + 1, strerror(errno));
            // Release previously acquired lines
            for (int j = 0; j <= i; j++) {
                if (sensor_lines[j] != NULL) {
                    gpiod_line_release(sensor_lines[j]);
                }
            }
            for (int j = 0; j < 8; j++) {
                if (counter_lines[j] != NULL) {
                    gpiod_line_release(counter_lines[j]);
                }
            }
            gpiod_chip_close(chip);
            return -1;
        }
    }

    // Request counter lines as outputs
    counter_lines[0] = gpiod_chip_get_line(chip, COUNTER_0_PIN);
    counter_lines[1] = gpiod_chip_get_line(chip, COUNTER_1_PIN);
    counter_lines[2] = gpiod_chip_get_line(chip, COUNTER_2_PIN);
    counter_lines[3] = gpiod_chip_get_line(chip, COUNTER_3_PIN);
    counter_lines[4] = gpiod_chip_get_line(chip, COUNTER_4_PIN);
    counter_lines[5] = gpiod_chip_get_line(chip, COUNTER_5_PIN);
    counter_lines[6] = gpiod_chip_get_line(chip, COUNTER_6_PIN);
    counter_lines[7] = gpiod_chip_get_line(chip, COUNTER_7_PIN);

    for (int i = 0; i < 8; i++) {
        if (!counter_lines[i]) {
            fprintf(stderr, "Error getting counter line %d: %s\n", i + 1, strerror(errno));
            // Release previously acquired lines
            for (int j = 0; j < 8; j++) {
                if (sensor_lines[j] != NULL) {
                    gpiod_line_release(sensor_lines[j]);
                }
            }
            for (int j = 0; j < 8; j++) {
                if (counter_lines[j] != NULL) {
                    gpiod_line_release(counter_lines[j]);
                }
            }
            gpiod_chip_close(chip);
            return -1;
        }
        if (gpiod_line_request_output(counter_lines[i], "counter_output", 0) < 0) {
            fprintf(stderr, "Error requesting counter line %d as output: %s\n", i + 1, strerror(errno));
            // Release previously acquired lines
            for (int j = 0; j < 8; j++) {
                if (sensor_lines[j] != NULL) {
                    gpiod_line_release(sensor_lines[j]);
                }
            }
            for (int j = 0; j <= i; j++) {
                if (counter_lines[j] != NULL) {
                    gpiod_line_release(counter_lines[j]);
                }
            }
            gpiod_chip_close(chip);
            return -1;
        }
    }

    // Stabilization delay
    struct timespec delay = {0, 200000000}; // 200ms
    nanosleep(&delay, NULL);

    return 0;
}

// Read sensor value
int read_sensor(int sensor_pin) {
    int value = gpiod_line_get_value(sensor_lines[sensor_pin - SENSOR_1_PIN]);
    if (value < 0) {
        fprintf(stderr, "Error reading sensor pin %d: %s\n", sensor_pin, strerror(errno));
        return -1; // Indicate error
    }
    return value;
}

// Update counter based on sensor inputs
int update_counter(int sensor_pins[], int num_sensors) {
    for (int i = 0; i < num_sensors; i++) {
        int sensor_value = read_sensor(sensor_pins[i]);
        if (sensor_value == 1) {
            counter++;
            if (counter > 255) {
                counter = 0;
            }
            return counter; // Return the updated counter
        }
    }
    return counter; // Return the current counter if no sensor triggered
}

// Write counter value to GPIO outputs
int write_counter_to_gpio(int counter_value) {
    for (int i = 0; i < 8; i++) {
        int bit = (counter_value >> i) & 1;
        if (gpiod_line_set_value(counter_lines[i], bit) < 0) {
            fprintf(stderr, "Error writing to counter line %d: %s\n", i + 1, strerror(errno));
            return -1; // Indicate error
        }
    }
    return 0;
}

// Log touch event to file
int log_touch_event(int channel, int counter_value) {
    FILE *fp = fopen("touch_log.txt", "a");
    if (!fp) {
        fprintf(stderr, "Warning: Could not open touch_log.txt for writing. Logging to stdout instead.\n");
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%d-%02d-%02dT%02d:%02d:%02dZ, Channel: %d, Counter: %d\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, channel, counter_value);
    fclose(fp);
    return 0;
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() < 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return 1;
    }

    int sensor_pins[] = {SENSOR_1_PIN, SENSOR_2_PIN, SENSOR_3_PIN, SENSOR_4_PIN, SENSOR_5_PIN, SENSOR_6_PIN, SENSOR_7_PIN, SENSOR_8_PIN};
    int prev_counter = 0;

    // Main loop
    while (running) {
        int current_counter = update_counter(sensor_pins, 8);

        if (current_counter != prev_counter) {
            write_counter_to_gpio(current_counter);

            for (int i = 0; i < 8; i++) {
                int sensor_value = read_sensor(sensor_pins[i]);
                if (sensor_value == 1) {
                    log_touch_event(i + 1, current_counter);
                    printf("Touch on channel %d | Counter: %d\n", i + 1, current_counter);
                }
            }
            prev_counter = current_counter;
        }

        struct timespec delay = {0, 10000000}; // 10ms
        nanosleep(&delay, NULL);
    }

    return 0;
}

