#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <gpiod.h>

// Define GPIO lines and chip name
#define GPIO_CHIP "gpiochip0"
#define GPIO_17 17
#define GPIO_18 18

// Define debounce time in milliseconds
#define DEBOUNCE_TIME_MS 50

// Global variables for GPIO lines and chip
struct gpiod_chip *chip = NULL;
struct gpiod_line *line17 = NULL;
struct gpiod_line *line18 = NULL;

// Function prototypes
int init_gpio(void);
int read_sensor(int gpio_line);
int log_event(int sensor_number);
void cleanup(int signal);

// Signal handler for graceful shutdown
void cleanup(int signal) {
    fprintf(stderr, "\nCaught signal %d, cleaning up...\n", signal);

    if (line17) {
        gpiod_line_release(line17);
    }
    if (line18) {
        gpiod_line_release(line18);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }

    fprintf(stderr, "Cleanup complete. Exiting.\n");
    exit(0);
}

// Initialize GPIO lines
int init_gpio(void) {
    int ret;

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", GPIO_CHIP);
        return -1;
    }

    // Request GPIO 17 as input with pull-up
    line17 = gpiod_chip_get_line(chip, GPIO_17);
    if (!line17) {
        fprintf(stderr, "Error getting GPIO %d line\n", GPIO_17);
        gpiod_chip_close(chip);
        return -1;
    }

    ret = gpiod_line_request_input(line17, "tilt_sensor_17", 0);
    if (ret < 0) {
        fprintf(stderr, "Error requesting GPIO %d as input: %s\n", GPIO_17, strerror(-ret));
        gpiod_chip_close(chip);
        return -1;
    }

    // Request GPIO 18 as input with pull-up
    line18 = gpiod_chip_get_line(chip, GPIO_18);
    if (!line18) {
        fprintf(stderr, "Error getting GPIO %d line\n", GPIO_18);
        gpiod_line_release(line17);
        gpiod_chip_close(chip);
        return -1;
    }

    ret = gpiod_line_request_input(line18, "tilt_sensor_18", 0);
    if (ret < 0) {
        fprintf(stderr, "Error requesting GPIO %d as input: %s\n", GPIO_18, strerror(-ret));
        gpiod_line_release(line17);
        gpiod_chip_close(chip);
        return -1;
    }

    return 0;
}

// Read sensor value
int read_sensor(int gpio_line) {
    int value;
    int ret;

    if (gpio_line == GPIO_17) {
        value = gpiod_line_get_value(line17);
        ret = gpiod_line_request_both_edges(line17, 0); // Enable both rising and falling edge detection
        if (ret < 0) {
            fprintf(stderr, "Error requesting both edges for GPIO %d: %s\n", GPIO_17, strerror(-ret));
            return -1;
        }
    } else if (gpio_line == GPIO_18) {
        value = gpiod_line_get_value(line18);
        ret = gpiod_line_request_both_edges(line18, 0); // Enable both rising and falling edge detection
        if (ret < 0) {
            fprintf(stderr, "Error requesting both edges for GPIO %d: %s\n", GPIO_18, strerror(-ret));
            return -1;
        }
    } else {
        fprintf(stderr, "Invalid GPIO line number: %d\n", gpio_line);
        return -1;
    }

    return value;
}

// Log event to file
int log_event(int sensor_number) {
    FILE *fp;
    time_t t;
    struct tm *tm_info;
    char timestamp[20];

    // Get current time
    time(&t);
    tm_info = localtime(&t);

    // Format timestamp
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

    // Open log file in append mode
    fp = fopen("/var/log/tilt_events.log", "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return -1;
    }

    // Write event to log file
    fprintf(fp, "%s, Sensor %d tilted\n", timestamp, sensor_number);

    // Close log file
    fclose(fp);

    return 0;
}

int main(void) {
    int prev_value17 = 1; // Initialize to pulled-up state
    int prev_value18 = 1; // Initialize to pulled-up state
    int current_value17, current_value18;
    struct timespec ts;
    long debounce_start_ns;

    // Install signal handlers
    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    // Initialize GPIO
    if (init_gpio() < 0) {
        return 1;
    }

    fprintf(stderr, "Tilt sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (1) {
