// Define GPIO pins
#define SENSOR1_PIN 17
#define SENSOR2_PIN 27
#define LED_PIN 22

// Global variables
FILE *log_file = NULL;
int running = 1;

// Function prototypes
int read_sensor(int gpio_pin);
void control_led(int gpio_pin, int state);
void log_data(FILE *fp, int sensor1_value, int sensor2_value, int led_state);
void signal_handler(int signal);

// Function to read sensor value
int read_sensor(int gpio_pin) {
    return gpioRead(gpio_pin);
}

// Function to control LED state
void control_led(int gpio_pin, int state) {
    gpioWrite(gpio_pin, state);
}

// Function to log data to file
void log_data(FILE *fp, int sensor1_value, int sensor2_value, int led_state) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(fp, "%s,%d,%d,%d\n", timestamp, sensor1_value, sensor2_value, led_state);
    fflush(fp); // Ensure data is written to file immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
    running = 0;
    control_led(LED_PIN, 0); // Turn off LED
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate(); // Terminate pigpio
    exit(0);
}

