    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(SENSOR1_PIN, PI_INPUT);
    gpioSetMode(SENSOR2_PIN, PI_INPUT);
    gpioSetMode(LED_PIN, PI_OUTPUT);

    // Open log file
    log_file = fopen("obstacle_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (running) {
        // Read sensor values
        int sensor1_value = read_sensor(SENSOR1_PIN);
        int sensor2_value = read_sensor(SENSOR2_PIN);

        // Control LED based on sensor values
        int led_state = (sensor1_value == 0 && sensor2_value == 0) ? 1 : 0;
        control_led(LED_PIN, led_state);

        // Log data
        log_data(log_file, sensor1_value, sensor2_value, led_state);

        // Wait 100 ms
        gpioDelay(100);
    }

    // Cleanup (should not reach here if signal handler works correctly)
    control_led(LED_PIN, 0);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

