#include <signal.h>
#include <time.h>
#include <pigpio.h>

// Define GPIO pins
#define MIC_INPUT_PIN 4
#define LED_OUTPUT_PIN 17

// Sampling rate (approximately 8 kHz)
#define SAMPLE_PERIOD_US 125

// LED on time (100 ms)
#define LED_ON_TIME_MS 100

// Global flag for signal handling
volatile sig_atomic_t program_running = 1;

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT) {
        fprintf(stderr, "\nCaught SIGINT, exiting gracefully...\n");
        program_running = 0;
    }
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Configure GPIO4 as input
    if (gpioSetMode(MIC_INPUT_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as input\n", MIC_INPUT_PIN);
        gpioTerminate();
        return 1;
    }

    // Configure GPIO17 as output
    if (gpioSetMode(LED_OUTPUT_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", LED_OUTPUT_PIN);
        gpioTerminate();
        return 1;
    }

    // Register signal handler for SIGINT
    signal(SIGINT, signal_handler);

    fprintf(stderr, "Program started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        // Read the microphone input
        int mic_value = gpioRead(MIC_INPUT_PIN);

        // Check for errors during GPIO read
        if (mic_value < 0) {
            fprintf(stderr, "Error reading GPIO%d\n", MIC_INPUT_PIN);
            program_running = 0; // Exit loop on error
            continue;
        }

        // If a peak is detected (HIGH signal)
        if (mic_value == 1) {
            // Get current timestamp
            struct timespec ts;
            clock_gettime(CLOCK_REALTIME, &ts);
            long timestamp_ms = (ts.tv_sec * 1000) + (ts.tv_nsec / 1000000);

            // Print timestamp to stdout
            printf("%ld\n", timestamp_ms);

            // Turn on the LED
            if (gpioWrite(LED_OUTPUT_PIN, 1) != 0) {
                fprintf(stderr, "Error writing to GPIO%d\n", LED_OUTPUT_PIN);
                program_running = 0; // Exit loop on error
                continue;
            }

            // Wait for 100 ms
            gpioDelay(LED_ON_TIME_MS * 1000); // Convert ms to us

            // Turn off the LED
            if (gpioWrite(LED_OUTPUT_PIN, 0) != 0) {
                fprintf(stderr, "Error writing to GPIO%d\n", LED_OUTPUT_PIN);
                program_running = 0; // Exit loop on error
                continue;
            }
        }

        // Delay for the sampling period
        gpioDelay(SAMPLE_PERIOD_US);
    }

    // Clean up and exit
    fprintf(stderr, "Cleaning up...\n");

    // Ensure LED is off
    gpioWrite(LED_OUTPUT_PIN, 0);

    // Terminate pigpio library
    gpioTerminate();

    fprintf(stderr, "Program finished.\n");
    return 0;
}

