        gpioTerminate();
        return 1;
    }

    // Main loop to read sensor values and log them to the console
    while (program_running) {
        // Read sensor values
        int left_value = gpioRead(LEFT_SENSOR_PIN);
        int center_value = gpioRead(CENTER_SENSOR_PIN);
        int right_value = gpioRead(RIGHT_SENSOR_PIN);

