#include <stdio.h>
#include <stdlib.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <time.h>
#include <string.h>

// Constants
#define I2C_BUS 1
#define SI1175_ADDR 0x49
#define ALS_LSB_REG 0x24
#define ALS_MSB_REG 0x25
#define READ_INTERVAL_MS 100

// Global variables
int i2c_fd = -1; // I2C file descriptor
volatile sig_atomic_t terminate = 0; // Termination flag

// Function prototypes
int i2c_setup(int bus, int addr);
int i2c_read_reg(int fd, unsigned char reg);
int i2c_write_reg(int fd, unsigned char reg, unsigned char value);
int read_als_data(int fd, unsigned short *als_data);
void log_data(unsigned short als_data);
void signal_handler(int sig);

// Signal handler function
void signal_handler(int sig) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", sig);
}

// I2C setup function
int i2c_setup(int bus, int addr) {
    char filename[20];
    snprintf(filename, 19, "/dev/i2c-%d", bus);
    int fd = open(filename, O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C device");
        return -1;
    }
    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        perror("Error setting I2C slave address");
        close(fd);
        return -1;
    }
    return fd;
}

// I2C read register function
int i2c_read_reg(int fd, unsigned char reg) {
    int result = i2c_smbus_read_byte_data(fd, reg);
    if (result < 0) {
        fprintf(stderr, "Error reading register 0x%02X: %d\n", reg, result);
        return -1;
    }
    return result;
}

// I2C write register function
int i2c_write_reg(int fd, unsigned char reg, unsigned char value) {
    int result = i2c_smbus_write_byte_data(fd, reg, value);
    if (result < 0) {
        fprintf(stderr, "Error writing to register 0x%02X: %d\n", reg, result);
        return -1;
    }
    return 0;
}

// Function to read ALS data
int read_als_data(int fd, unsigned short *als_data) {
    int lsb, msb;

    lsb = i2c_read_reg(fd, ALS_LSB_REG);
    if (lsb < 0) {
        return -1;
    }

    msb = i2c_read_reg(fd, ALS_MSB_REG);
    if (msb < 0) {
        return -1;
    }

    *als_data = (msb << 8) | lsb;
    return 0;
}

// Function to log data with timestamp
void log_data(unsigned short als_data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    printf("[%s] ALS Data: 0x%04X\n", timestamp, als_data);
}

int main() {
    unsigned short als_data;

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize I2C
    i2c_fd = i2c_setup(I2C_BUS, SI1175_ADDR);
    if (i2c_fd < 0) {
        fprintf(stderr, "I2C setup failed. Exiting.\n");
        return 1;
    }

    printf("Si1175 ALS Reader started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        if (read_als_data(i2c_fd, &als_data) == 0) {
            log_data(als_data);
        } else {
            fprintf(stderr, "Failed to read ALS data.\n");
        }
        usleep(READ_INTERVAL_MS * 1000); // Sleep for 100ms
    }

    // Cleanup
    if (i2c_fd != -1) {
        close(i2c_fd);
    }

    printf("Exiting.\n");
    return 0;
}

