#define MIDDLE_GPIO 3
#define RIGHT_GPIO 4

// Global variables for GPIO lines and chip
struct gpiod_line *left_line = NULL;
struct gpiod_line *middle_line = NULL;
struct gpiod_line *right_line = NULL;
struct gpiod_chip *gpio_chip = NULL;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);

    // Release GPIO lines if they are open
    if (left_line) {
        gpiod_line_release(left_line);
    }
    if (middle_line) {
        gpiod_line_release(middle_line);
    }
    if (right_line) {
        gpiod_line_release(right_line);
    }

    // Close GPIO chip if it is open
    if (gpio_chip) {
        gpiod_chip_close(gpio_chip);
    }

    exit(0);
}

int main() {
    // Register signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Open GPIO chip
    gpio_chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!gpio_chip) {
        perror("Error opening GPIO chip");
        return 1;
    }

    // Get GPIO lines
    left_line = gpiod_chip_get_line(gpio_chip, LEFT_GPIO);
    if (!left_line) {
