        gpiod_chip_close(gpio_chip);
        return 1;
    }

    middle_line = gpiod_chip_get_line(gpio_chip, MIDDLE_GPIO);
    if (!middle_line) {
        perror("Error getting middle GPIO line");
        gpiod_line_release(left_line);
        gpiod_chip_close(gpio_chip);
        return 1;
    }

    right_line = gpiod_chip_get_line(gpio_chip, RIGHT_GPIO);
