#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>
#include <string.h>

// Define GPIO pins for the TTP226 channels
const int gpio_pins[] = {5, 6, 13, 19, 26, 12, 16, 20};
const int num_channels = sizeof(gpio_pins) / sizeof(gpio_pins[0]);

// Global variables for signal handling
static volatile sig_atomic_t keep_running = 1;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line **lines = NULL;

// Signal handler function
void signal_handler(int sig)
{
    fprintf(stderr, "\nCaught signal %d, exiting gracefully.\n", sig);
    keep_running = 0;
}

// Function to initialize the GPIO chip
int initialize_gpio()
{
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Error: Could not open GPIO chip 'gpiochip0'.\n");
        return -1;
    }

    lines = calloc(num_channels, sizeof(struct gpiod_line *));
    if (!lines) {
        fprintf(stderr, "Error: Could not allocate memory for lines.\n");
        gpiod_chip_close(chip);
        return -1;
    }

    for (int i = 0; i < num_channels; i++) {
        lines[i] = gpiod_chip_get_line(chip, gpio_pins[i]);
        if (!lines[i]) {
            fprintf(stderr, "Error: Could not get line %d (GPIO %d).\n", i + 1, gpio_pins[i]);
            // Release previously allocated lines
            for (int j = 0; j < i; j++) {
                gpiod_line_release(lines[j]);
            }
            free(lines);
            gpiod_chip_close(chip);
            return -1;
        }

        if (gpiod_line_request_input(lines[i], "touch_sensor") < 0) {
            fprintf(stderr, "Error: Could not request line %d (GPIO %d) as input.\n", i + 1, gpio_pins[i]);
            // Release previously allocated lines
            for (int j = 0; j <= i; j++) {
                gpiod_line_release(lines[j]);
            }
            free(lines);
            gpiod_chip_close(chip);
            return -1;
        }
    }

    return 0;
}

// Function to read the sensor data
int read_sensor_data(int *data)
{
    for (int i = 0; i < num_channels; i++) {
        int value = gpiod_line_get_value(lines[i]);
        if (value < 0) {
            fprintf(stderr, "Error: Could not read value from line %d (GPIO %d).\n", i + 1, gpio_pins[i]);
            return -1;
        }
        data[i] = value;
    }
    return 0;
}

// Function to log the sensor data
void log_sensor_data(const int *data)
{
    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);
    double timestamp = (double)ts.tv_sec + (double)ts.tv_nsec / 1000000000.0;

    printf("[%lf] ", timestamp);
    for (int i = 0; i < num_channels; i++) {
        printf("CH%d=%d ", i + 1, data[i]);
    }
    printf("\n");
}

// Function to cleanup GPIO resources
void cleanup_gpio()
{
    if (lines) {
        for (int i = 0; i < num_channels; i++) {
            if (lines[i]) {
                gpiod_line_release(lines[i]);
            }
        }
        free(lines);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
}

int main()
{
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return 1;
    }

    // Main loop
    int sensor_data[num_channels];
    while (keep_running) {
        if (read_sensor_data(sensor_data) == 0) {
            log_sensor_data(sensor_data);
        } else {
            fprintf(stderr, "Error reading sensor data. Continuing.\n");
        }
        struct timespec delay;
        delay.tv_sec = 0;
        delay.tv_nsec = 200 * 1000 * 1000; // 200ms
        nanosleep(&delay, NULL);
    }

    // Cleanup GPIO resources before exiting
    cleanup_gpio();

    return 0;
}

