#include <pigpio.h>
#include <unistd.h>

// Define GPIO pins for RGB LED (Common Anode)
#define RED_PIN   17
#define GREEN_PIN 18
#define BLUE_PIN  27

// PWM frequency
#define PWM_FREQUENCY 1000

// Number of hues in the palette
#define NUM_HUES 10

// Hue palette (0-360 degrees)
const float hue_palette[] = {0, 60, 120, 180, 240, 300, 360, 30, 90, 210};

// Global variables
volatile sig_atomic_t program_running = 1;

// Function prototypes
void signal_handler(int signal);
int initialize_gpio();
void set_led_color(int red, int green, int blue);
void fade_to_hue(float hue);
float hsv_to_rgb(float h, float s, float v, float *r, float *g, float *b);
void cleanup_gpio();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    syslog(LOG_INFO, "Signal received, shutting down...");
}

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        return -1;
    }

    if (gpioSetMode(RED_PIN, PI_OUTPUT) != 0) {
        syslog(LOG_ERR, "Failed to set RED_PIN as output");
        gpioTerminate();
        return -1;
    }
    if (gpioSetMode(GREEN_PIN, PI_OUTPUT) != 0) {
        syslog(LOG_ERR, "Failed to set GREEN_PIN as output");
        gpioTerminate();
        return -1;
    }
    if (gpioSetMode(BLUE_PIN, PI_OUTPUT) != 0) {
        syslog(LOG_ERR, "Failed to set BLUE_PIN as output");
        gpioTerminate();
        return -1;
    }

    if (gpioSetPWMfrequency(RED_PIN, PWM_FREQUENCY) != 0) {
        syslog(LOG_ERR, "Failed to set PWM frequency for RED_PIN");
        gpioTerminate();
        return -1;
    }
    if (gpioSetPWMfrequency(GREEN_PIN, PWM_FREQUENCY) != 0) {
        syslog(LOG_ERR, "Failed to set PWM frequency for GREEN_PIN");
        gpioTerminate();
        return -1;
    }
    if (gpioSetPWMfrequency(BLUE_PIN, PWM_FREQUENCY) != 0) {
        syslog(LOG_ERR, "Failed to set PWM frequency for BLUE_PIN");
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Set the color of the RGB LED using PWM
void set_led_color(int red, int green, int blue) {
    // Invert the PWM duty cycle for common anode LED
    int red_inverted = 255 - red;
    int green_inverted = 255 - green;
    int blue_inverted = 255 - blue;

    gpioPWM(RED_PIN, red_inverted);
    gpioPWM(GREEN_PIN, green_inverted);
    gpioPWM(BLUE_PIN, blue_inverted);
}

// Fade to a new hue over a period of time
void fade_to_hue(float hue) {
    float r, g, b;
    hsv_to_rgb(hue, 1.0, 1.0, &r, &g, &b);

    int red_start = (int)(r * 255);
    int green_start = (int)(g * 255);
    int blue_start = (int)(b * 255);

    float r_step = (r * 255 - red_start) / 50.0;
    float g_step = (g * 255 - green_start) / 50.0;
    float b_step = (b * 255 - blue_start) / 50.0;

    for (int i = 0; i <= 50; i++) {
        int red = red_start + (int)(r_step * i);
        int green = green_start + (int)(g_step * i);
        int blue = blue_start + (int)(b_step * i);

        // Clamp values to [0, 255]
        if (red < 0) red = 0;
        if (red > 255) red = 255;
        if (green < 0) green = 0;
        if (green > 255) green = 255;
        if (blue < 0) blue = 0;
        if (blue > 255) blue = 255;

        set_led_color(red, green, blue);
        gpioDelay(100000); // 100ms delay
    }
}

// Convert HSV to RGB
void hsv_to_rgb(float h, float s, float v, float *r, float *g, float *b) {
    if (s == 0.0) {
        *r = *g = *b = v;
        return;
    }

    h = fmod(h, 360.0);
    if (h < 0) h += 360;

    float h_i = (int)(h / 60.0);
    float f = h / 60.0 - h_i;
    float p = v * (1.0 - s);
    float q = v * (1.0 - s * f);
    float t = v * (1.0 - s * (1.0 - f));

    switch ((int)h_i) {
        case 0:
            *r = v;
            *g = t;
            *b = p;
            break;
        case 1:
            *r = q;
            *g = v;
            *b = p;
            break;
        case 2:
            *r = p;
            *g = v;
            *b = t;
            break;
        case 3:
            *r = p;
            *g = q;
            *b = v;
            break;
        case 4:
            *r = t;
            *g = p;
            *b = v;
            break;
        default: // case 5:
            *r = v;
            *g = p;
            *b = q;
            break;
    }
}

// Cleanup GPIO resources
void cleanup_gpio() {
    gpioPWM(RED_PIN, 0);
    gpioPWM(GREEN_PIN, 0);
    gpioPWM(BLUE_PIN, 0);
    gpioTerminate();
    syslog(LOG_INFO, "GPIO resources released");
}

int main() {
    // Initialize syslog
    openlog("mood_lamp", LOG_PID | LOG_CONS, LOG_USER);

    // Seed the random number generator
    srand(time(NULL));

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        syslog(LOG_ERR, "GPIO initialization failed, exiting");
        closelog();
        return 1;
    }

    syslog(LOG_INFO, "Mood lamp started");

    // Main loop
    while (program_running) {
        // Select a random hue from the palette
        int random_hue_index = rand() % NUM_HUES;
        float hue = hue_palette[random_hue_index];

        // Fade to the selected hue
        fade_to_hue(hue);

        // Wait before selecting a new hue
        gpioDelay(5000000); // 5 seconds
    }

    // Cleanup and exit
    cleanup_gpio();
    closelog();
    return 0;
}

