#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>
#include <signal.h>
#include <time.h>
#include <string.h>

// TCS34725 Registers
#define TCS34725_ADDRESS 0x29
#define TCS34725_COMMAND_BIT 0x80
#define TCS34725_ENABLE 0x00
#define TCS34725_ATIME 0x01
#define TCS34725_CONTROL 0x0F
#define TCS34725_ID 0x12
#define TCS34725_CDATA 0x14
#define TCS34725_RDATA 0x16
#define TCS34725_GDATA 0x18
#define TCS34725_BDATA 0x1A

// GPIO Pin for LED
#define LED_GPIO 17

// Red Threshold
#define RED_THRESHOLD 200

// Global Variables
static int i2c_fd = -1;
static struct gpiod_chip *gpio_chip = NULL;
static struct gpiod_line *gpio_line = NULL;
static volatile sig_atomic_t terminate = 0;

// Calibration Data
static int clear_offset = 0;
static int red_offset = 0;
static int green_offset = 0;
static int blue_offset = 0;
static int clear_gain = 1;
static int red_gain = 1;
static int green_gain = 1;
static int blue_gain = 1;

// Function Prototypes
int tcs34725_init(int fd);
int tcs34725_read_raw_data(int fd, uint16_t *clear, uint16_t *red, uint16_t *green, uint16_t *blue);
void calibrate_data(uint16_t clear, uint16_t red, uint16_t green, uint16_t blue, int *calibrated_clear, int *calibrated_red, int *calibrated_green, int *calibrated_blue);
void set_gpio_output(int pin, int value);
void signal_handler(int sig);

// Signal Handler
void signal_handler(int sig) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating...\n", sig);
}

// Initialize TCS34725 Sensor
int tcs34725_init(int fd) {
    uint8_t buf[2];

    // Enable Power and RGBC
    buf[0] = TCS34725_COMMAND_BIT | TCS34725_ENABLE;
    buf[1] = 0x03; // PON | AEN
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "Error writing to I2C device.\n");
        return -1;
    }

    // Set Integration Time (ATIME)
    buf[0] = TCS34725_COMMAND_BIT | TCS34725_ATIME;
    buf[1] = 0x00; // 154ms
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "Error writing to I2C device.\n");
        return -1;
    }

    // Set Gain (CONTROL)
    buf[0] = TCS34725_COMMAND_BIT | TCS34725_CONTROL;
    buf[1] = 0x00; // 1x gain
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "Error writing to I2C device.\n");
        return -1;
    }

    // Verify Sensor ID
    buf[0] = TCS34725_COMMAND_BIT | TCS34725_ID;
    if (write(fd, buf, 1) != 1) {
        fprintf(stderr, "Error writing to I2C device.\n");
        return -1;
    }

    if (read(fd, buf, 1) != 1) {
        fprintf(stderr, "Error reading from I2C device.\n");
        return -1;
    }

    if (buf[0] != 0x44) {
        fprintf(stderr, "Error: Invalid sensor ID: 0x%02X\n", buf[0]);
        return -1;
    }

    return 0;
}

// Read Raw Data from TCS34725 Sensor
int tcs34725_read_raw_data(int fd, uint16_t *clear, uint16_t *red, uint16_t *green, uint16_t *blue) {
    uint8_t buf[8];
    uint8_t reg = TCS34725_COMMAND_BIT | TCS34725_CDATA;

    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "Error writing to I2C device.\n");
        return -1;
    }

    if (read(fd, buf, 8) != 8) {
        fprintf(stderr, "Error reading from I2C device.\n");
        return -1;
    }

    *clear = (buf[1] << 8) | buf[0];
    *red   = (buf[3] << 8) | buf[2];
    *green = (buf[5] << 8) | buf[4];
    *blue  = (buf[7] << 8) | buf[6];

    return 0;
}

// Calibrate Raw Data
void calibrate_data(uint16_t clear, uint16_t red, uint16_t green, uint16_t blue, int *calibrated_clear, int *calibrated_red, int *calibrated_green, int *calibrated_blue) {
    *calibrated_clear = (clear - clear_offset) * clear_gain;
    *calibrated_red   = (red - red_offset) * red_gain;
    *calibrated_green = (green - green_offset) * green_gain;
    *calibrated_blue  = (blue - blue_offset) * blue_gain;
}

// Set GPIO Output
void set_gpio_output(int pin, int value) {
    int ret;
    struct gpiod_line_request_config config;

    memset(&config, 0, sizeof(config));
    config.consumer = "TCS34725_LED";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;

    ret = gpiod_line_request(gpio_line, &config, value);
    if (ret < 0) {
        fprintf(stderr, "Error requesting GPIO line: %d\n", ret);
    }
}

int main() {
    uint16_t clear, red, green, blue;
    int calibrated_clear, calibrated_red, calibrated_green, calibrated_blue;
    struct timespec sleep_time = {0, 200000000}; // 200ms
    struct timespec remaining_time;

    // Register Signal Handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C Device
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C device: /dev/i2c-1\n");
        return 1;
    }

    // Specify the address of the slave device
    if (ioctl(i2c_fd, I2C_SLAVE, TCS34725_ADDRESS) < 0) {
        fprintf(stderr, "Error setting I2C slave address.\n");
        close(i2c_fd);
        return 1;
    }

    // Initialize TCS34725 Sensor
    if (tcs34725_init(i2c_fd) != 0) {
        fprintf(stderr, "Error initializing TCS34725 sensor.\n");
        close(i2c_fd);
        return 1;
    }

    // Open GPIO Chip
    gpio_chip = gpiod_chip_open_by_name("gpiochip0");
    if (!gpio_chip) {
        fprintf(stderr, "Error opening GPIO chip.\n");
        close(i2c_fd);
        return 1;
    }

    // Get GPIO Line
    gpio_line = gpiod_chip_get_line(gpio_chip, LED_GPIO);
    if (!gpio_line) {
        fprintf(stderr, "Error getting GPIO line.\n");
        gpiod_chip_close(gpio_chip);
        close(i2c_fd);
        return 1;
    }

    // Request GPIO Line for Output
    if (gpiod_line_request_output(gpio_line, "TCS34725_LED", 0) < 0) {
        fprintf(stderr, "Error requesting GPIO line for output.\n");
        gpiod_chip_close(gpio_chip);
        close(i2c_fd);
        return 1;
    }

    // Main Loop
    while (!terminate) {
        // Read Raw Data
        if (tcs34725_read_raw_data(i2c_fd, &clear, &red, &green, &blue) == 0) {
            // Calibrate Data
            calibrate_data(clear, red, green, blue, &calibrated_clear, &calibrated_red, &calibrated_green, &calibrated_blue);

            // Display Calibrated Values
            printf("C: %d, R: %d, G: %d, B: %d\n", calibrated_clear, calibrated_red, calibrated_green, calibrated_blue);

            // Control LED
            if (calibrated_red > RED_THRESHOLD) {
                set_gpio_output(LED_GPIO, 1);
            } else {
                set_gpio_output(LED_GPIO, 0);
            }
        } else {
            fprintf(stderr, "Error reading sensor data. Attempting re-initialization.\n");
            // Attempt to re-initialize the sensor
            if (tcs34725_init(i2c_fd) != 0) {
                fprintf(stderr, "Error re-initializing TCS34725 sensor.\n");
                terminate = 1; // Exit if re-initialization fails
            }
        }

        // Sleep for 200ms
        nanosleep(&sleep_time, &remaining_time);
    }

    // Cleanup
    set_gpio_output(LED_GPIO, 0); // Turn off LED
    gpiod_line_release(gpio_line);
    gpiod_chip_close(gpio_chip);
    close(i2c_fd);

    return 0;
}

