#include <math.h>

// Define constants
#define BH1750_ADDR 0x23
#define BH1750_CONTINUOUS_HIGH_RES_MODE 0x10
#define NUM_LEDS 10
#define PWM_FREQUENCY 800000 // 800 kHz
#define PWM_RANGE 255

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
void signal_handler(int signal);
int init_bh1750();
float read_bh1750();
uint8_t map_lux_to_brightness(float lux);
void set_led_brightness(uint8_t brightness);
void generate_ws2812b_data(uint8_t brightness, uint32_t *data);
void send_ws2812b_data(uint32_t *data, int num_leds);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Initialize the BH1750 sensor
int init_bh1750() {
    int result = i2cWriteByteData(i2c_handle, 0x00, BH1750_CONTINUOUS_HIGH_RES_MODE);
    if (result != 0) {
        fprintf(stderr, "Error writing to BH1750: %d\n", result);
        return -1;
    }
    return 0;
}

// Read the lux value from the BH1750 sensor
float read_bh1750() {
    char buf[2];
    int result = i2cReadI2CBlockData(i2c_handle, 0x00, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading from BH1750: %d\n", result);
        return -1.0;
    }

    uint16_t raw_value = (buf[0] << 8) | buf[1];
    float lux = (float)raw_value / 1.2;
    return lux;
}

// Map lux value to LED brightness (logarithmic mapping)
uint8_t map_lux_to_brightness(float lux) {
    if (lux <= 0) {
        return 0;
    }

    // Logarithmic mapping
    float log_lux = log10(lux);
    float normalized_lux = log_lux / log10(1000.0); // Normalize to 0-1 range

    // Non-linear mapping (e.g., square root)
    float brightness_float = sqrt(normalized_lux);

    uint8_t brightness = (uint8_t)(brightness_float * 255.0);
    return brightness;
}

// Set the brightness of all LEDs in the strip
void set_led_brightness(uint8_t brightness) {
    // Generate WS2812B data for all LEDs
    uint32_t data[NUM_LEDS];
    for (int i = 0; i < NUM_LEDS; i++) {
        generate_ws2812b_data(brightness, &data[i]);
    }

    // Send the data to the LED strip
    send_ws2812b_data(data, NUM_LEDS);
}

// Generate WS2812B data for a single LED
void generate_ws2812b_data(uint8_t brightness, uint32_t *data) {
    // WS2812B requires a specific timing pattern for each bit.
    // This is a simplified example.  A real implementation would
    // generate the precise timing waveform.
    // For simplicity, we'll just set the brightness for each color.
    *data = 0x000000; // Black
}

// Send WS2812B data to the LED strip using pigpio's wave functionality
void send_ws2812b_data(uint32_t *data, int num_leds) {
    // This is a placeholder.  A real implementation would use pigpio's
    // wave functionality to generate the precise timing waveform required
    // by the WS2812B.
    // For now, we'll just print the data.
    for (int i = 0; i < num_leds; i++) {
        printf("LED %d: 0x%08X\n", i, data[i]);
    }
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C connection
    i2c_handle = i2cOpen(1, BH1750_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize BH1750 sensor
    if (init_bh1750() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        // Read lux value from BH1750
        float lux = read_bh1750();
        if (lux < 0) {
            fprintf(stderr, "Error reading lux value, retrying...\n");
            gpioDelay(100); // Wait before retrying
            continue;
        }

        // Map lux value to brightness
        uint8_t brightness = map_lux_to_brightness(lux);

        // Set LED brightness
        set_led_brightness(brightness);

        // Print lux value and brightness
        printf("Lux: %.2f, Brightness: %d\n", lux, brightness);

        // Wait for a short period
        gpioDelay(100); // 100 ms
    }

    // Clean up
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

