#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/spi/spidev.h>
#include <pigpio.h>
#include <signal.h>
#include <errno.h>
#include <string.h>

// Constants
#define I2C_BUS "/dev/i2c-1"
#define SPI_DEVICE "/dev/spidev0.0"
#define NUM_LEDS 10
#define LUX_MIN 10.0
#define LUX_MAX 300.0
#define BRIGHTNESS_MIN 0
#define BRIGHTNESS_MAX 31
#define SPI_SPEED 1000000 // 1 MHz

// Global variables
int i2c_fd = -1;
int spi_fd = -1;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c(const char *bus);
int init_spi(const char *device, int speed);
int init_bh1750(int fd);
float read_lux(int fd);
int map_lux_to_brightness(float lux);
int init_apa102(int fd);
int send_apa102_frame(int fd, int brightness);
void signal_handler(int sig);
void cleanup();

// Signal handler
void signal_handler(int sig) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", sig);
}

// I2C initialization
int init_i2c(const char *bus) {
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C bus");
        return -1;
    }
    return fd;
}

// SPI initialization
int init_spi(const char *device, int speed) {
    int fd = open(device, O_RDWR);
    if (fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }

    // Configure SPI mode
    uint8_t mode = 0; // SPI mode 0
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) == -1) {
        perror("Error setting SPI mode");
        close(fd);
        return -1;
    }

    // Configure SPI speed
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) == -1) {
        perror("Error setting SPI speed");
        close(fd);
        return -1;
    }

    return fd;
}

// BH1750 initialization
int init_bh1750(int fd) {
    uint8_t mode = 0x20; // One-Time High-Resolution Mode
    if (write(fd, &mode, 1) != 1) {
        perror("Error writing to BH1750");
        return -1;
    }
    return 0;
}

// Read lux value from BH1750
float read_lux(int fd) {
    uint8_t buffer[2];
    if (read(fd, buffer, 2) != 2) {
        perror("Error reading from BH1750");
        return -1.0;
    }

    uint16_t raw = (buffer[0] << 8) | buffer[1];
    return (float)raw / 1.2;
}

// Map lux value to APA102 brightness
int map_lux_to_brightness(float lux) {
    if (lux < LUX_MIN) {
        return BRIGHTNESS_MIN;
    } else if (lux > LUX_MAX) {
        return BRIGHTNESS_MAX;
    } else {
        return (int)(((lux - LUX_MIN) / (LUX_MAX - LUX_MIN)) * (BRIGHTNESS_MAX - BRIGHTNESS_MIN));
    }
}

// APA102 initialization
int init_apa102(int fd) {
    // Send start frame (all zeros)
    uint8_t start_frame[4] = {0x00, 0x00, 0x00, 0x00};
    if (write(fd, start_frame, 4) != 4) {
        perror("Error sending start frame");
        return -1;
    }
    return 0;
}

// Send APA102 frame
int send_apa102_frame(int fd, int brightness) {
    uint8_t led_frame[4];
    led_frame[0] = 0xE0 | brightness; // Global brightness
    led_frame[1] = 0x00; // Blue
    led_frame[2] = 0x00; // Green
    led_frame[3] = 0x00; // Red

    if (write(fd, led_frame, 4) != 4) {
        perror("Error sending LED frame");
        return -1;
    }
    return 0;
}

// Cleanup function
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (spi_fd != -1) {
        close(spi_fd);
    }
    gpioTerminate();
}

int main() {
    // Register signal handler
    signal(SIGINT, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    i2c_fd = init_i2c(I2C_BUS);
    if (i2c_fd < 0) {
        cleanup();
        return 1;
    }

    // Initialize SPI
    spi_fd = init_spi(SPI_DEVICE, SPI_SPEED);
    if (spi_fd < 0) {
        cleanup();
        return 1;
    }

    // Initialize BH1750
    if (init_bh1750(i2c_fd) < 0) {
        cleanup();
        return 1;
    }

    // Initialize APA102
    if (init_apa102(spi_fd) < 0) {
        cleanup();
        return 1;
    }

    printf("Starting main loop...\n");

    while (!terminate) {
        // Read lux value
        float lux = read_lux(i2c_fd);
        if (lux < 0) {
            fprintf(stderr, "Error reading lux value, retrying...\n");
            sleep(1); // Wait before retrying
            continue;
        }

        // Map lux to brightness
        int brightness = map_lux_to_brightness(lux);

        // Send APA102 frame
        if (send_apa102_frame(spi_fd, brightness) < 0) {
            fprintf(stderr, "Error sending APA102 frame, retrying...\n");
            sleep(1); // Wait before retrying
            continue;
        }

        // Send end frame (all ones)
        uint8_t end_frame[4] = {0xFF, 0xFF, 0xFF, 0xFF};
        if (write(spi_fd, end_frame, 4) != 4) {
            perror("Error sending end frame");
            terminate = 1; // Exit on end frame error
            break;
        }

        printf("Lux: %.2f, Brightness: %d\n", lux, brightness);

        sleep(1); // Update every 1 second
    }

    // Turn off LEDs
    uint8_t off_frame[4] = {0x00, 0x00, 0x00, 0x00};
    for (int i = 0; i < NUM_LEDS; i++) {
        if (write(spi_fd, off_frame, 4) != 4) {
            perror("Error sending off frame");
        }
    }
    uint8_t end_frame[4] = {0xFF, 0xFF, 0xFF, 0xFF};
    if (write(spi_fd, end_frame, 4) != 4) {
        perror("Error sending end frame");
    }

    cleanup();
    return 0;
}

