#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define constants
#define I2C_BUS 1
#define BH1750_ADDR_LOW 0x23
#define BH1750_ADDR_HIGH 0x5C
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define NUM_SENSORS 3
#define NUM_LEDS 10
#define FADE_TIME_MS 500
#define MAIN_LOOP_DELAY_MS 100

// APA102 start frame
#define APA102_START_FRAME_SIZE 4
#define APA102_START_FRAME_DATA 0x00000000

// Global variables
int i2c_handles[NUM_SENSORS];
int spi_handle;
int running = 1;

// Function prototypes
int init_i2c_sensor(int i2c_bus, int i2c_address);
int read_bh1750(int i2c_handle);
float average_lux(int lux_values[], int num_sensors);
int map_lux_to_brightness(float average_lux);
void set_apa102_brightness(int spi_handle, int brightness);
void fade_apa102_brightness(int spi_handle, int current_brightness, int target_brightness, int fade_time_ms);
void signal_handler(int signal);

// Structure to hold sensor data
typedef struct {
    int address;
    int handle;
    int present;
} sensor_t;

// Initialize I2C sensor
int init_i2c_sensor(int i2c_bus, int i2c_address) {
    int handle = i2cOpen(i2c_bus, i2c_address, 0);
    if (handle < 0) {
        fprintf(stderr, "Error opening I2C device at address 0x%02X: %d\n", i2c_address, handle);
        return -1;
    }
    return handle;
}

// Read lux value from BH1750 sensor
int read_bh1750(int i2c_handle) {
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Invalid I2C handle.\n");
        return -1;
    }

    if (i2cWriteByteData(i2c_handle, 0x00, 0x21) < 0) {
        fprintf(stderr, "Error writing to I2C device: %d\n", i2c_handle);
        return -1;
    }

    gpioDelay(180); // Wait for conversion (at least 180ms)

    char buf[2];
    if (i2cReadDevice(i2c_handle, buf, 2) != 2) {
        fprintf(stderr, "Error reading from I2C device: %d\n", i2c_handle);
        return -1;
    }

    int lux = (buf[0] << 8) | buf[1];
    return lux;
}

// Calculate average lux value
float average_lux(int lux_values[], int num_sensors) {
    float sum = 0.0;
    int count = 0;
    for (int i = 0; i < num_sensors; i++) {
        if (lux_values[i] >= 0) {
            sum += lux_values[i];
            count++;
        }
    }
    if (count > 0) {
        return sum / count;
    } else {
        return 0.0; // Return 0 if no valid readings
    }
}

// Map lux value to brightness level (0-31)
int map_lux_to_brightness(float average_lux) {
    // Define lux ranges and corresponding brightness levels
    int brightness = 0;
    if (average_lux < 100) {
        brightness = 31;
    } else if (average_lux < 200) {
        brightness = 28;
    } else if (average_lux < 300) {
        brightness = 25;
    } else if (average_lux < 400) {
        brightness = 22;
    } else if (average_lux < 500) {
        brightness = 19;
    } else if (average_lux < 600) {
        brightness = 16;
    } else if (average_lux < 700) {
        brightness = 13;
    } else if (average_lux < 800) {
        brightness = 10;
    } else if (average_lux < 900) {
        brightness = 7;
    } else if (average_lux < 1000) {
        brightness = 4;
    } else {
        brightness = 1;
    }
    return brightness;
}

// Set APA102 brightness
void set_apa102_brightness(int spi_handle, int brightness) {
    // Create APA102 start frame
    uint32_t start_frame = APA102_START_FRAME_DATA;

    // Create LED data (all LEDs at the same brightness)
    uint8_t led_data[NUM_LEDS * 4]; // 4 bytes per LED (RGB + Global Brightness)
    for (int i = 0; i < NUM_LEDS; i++) {
        led_data[i * 4] = 0x00; // Blue
        led_data[i * 4 + 1] = 0x00; // Green
        led_data[i * 4 + 2] = 0x00; // Red
        led_data[i * 4 + 3] = brightness; // Global Brightness (0-31)
    }

    // Combine start frame and LED data
    uint8_t spi_data[APA102_START_FRAME_SIZE + NUM_LEDS * 4];
    memcpy(spi_data, &start_frame, APA102_START_FRAME_SIZE);
    memcpy(spi_data + APA102_START_FRAME_SIZE, led_data, NUM_LEDS * 4);

    // Send data via SPI
    spiWrite(spi_handle, (char *)spi_data, APA102_START_FRAME_SIZE + NUM_LEDS * 4);
}

// Fade APA102 brightness
void fade_apa102_brightness(int spi_handle, int current_brightness, int target_brightness, int fade_time_ms) {
    int steps = 50; // Number of steps in the fade
    int brightness_diff = target_brightness - current_brightness;
    int brightness_step = brightness_diff / steps;

    for (int i = 0; i < steps; i++) {
        int new_brightness = current_brightness + (i * brightness_step);
        if (new_brightness < 0) new_brightness = 0;
        if (new_brightness > 31) new_brightness = 31;
        set_apa102_brightness(spi_handle, new_brightness);
        gpioDelay(fade_time_ms / steps);
    }
    set_apa102_brightness(spi_handle, target_brightness);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    running = 0;

    // Turn off the LED strip
    set_apa102_brightness(spi_handle, 0);

    // Close I2C handles
    for (int i = 0; i < NUM_SENSORS; i++) {
        if (i2c_handles[i] >= 0) {
            i2cClose(i2c_handles[i]);
        }
    }

    // Close SPI handle
    spiClose(spi_handle);

    // Terminate pigpio
    gpioTerminate();

    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Initialize I2C sensors
    sensor_t sensors[NUM_SENSORS];
    sensors[0].address = BH1750_ADDR_LOW;
    sensors[1].address = BH1750_ADDR_HIGH;
    sensors[2].address = BH1750_ADDR_LOW; // Example of reusing address, check for duplicates

    for (int i = 0; i < NUM_SENSORS; i++) {
        sensors[i].handle = init_i2c_sensor(I2C_BUS, sensors[i].address);
        sensors[i].present = (sensors[i].handle >= 0);
        i2c_handles[i] = sensors[i].handle;
    }

    // Initialize SPI
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error opening SPI device: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Main loop
    int current_brightness = 0;
    while (running) {
        // Read lux values from sensors
        int lux_values[NUM_SENSORS];
        for (int i = 0; i < NUM_SENSORS; i++) {
            if (sensors[i].present) {
                lux_values[i] = read_bh1750(sensors[i].handle);
                if (lux_values[i] < 0) {
                    lux_values[i] = -1; // Indicate error
                }
            } else {
                lux_values[i] = -1; // Sensor not present
            }
        }

        // Calculate average lux value
        float average_lux = average_lux(lux_values, NUM_SENSORS);

        // Map lux value to brightness level
        int target_brightness = map_lux_to_brightness(average_lux);

        // Fade to the new brightness
        fade_apa102_brightness(spi_handle, current_brightness, target_brightness, FADE_TIME_MS);

        current_brightness = target_brightness;

        // Delay
        gpioDelay(MAIN_LOOP_DELAY_MS);
    }

    // Cleanup (should not reach here if signal handler works correctly)
    set_apa102_brightness(spi_handle, 0);
    for (int i = 0; i < NUM_SENSORS; i++) {
        i2cClose(i2c_handles[i]);
    }
    spiClose(spi_handle);
    gpioTerminate();

    return 0;
}

