#include <signal.h>
#include <math.h>
#include <time.h>

// Constants
#define I2C_ADDR 0x10
#define ALS_REG 0x04
#define CONFIG_REG 0x00
#define GPIO_PIN 18
#define MAX_LUX 120000.0
#define GAMMA 2.2
#define RETRY_COUNT 3
#define RETRY_DELAY_MS 100

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_veml7700();
int read_als_data(uint16_t *als_data);
double convert_to_lux(uint16_t raw_value);
int map_lux_to_brightness(double lux);
void set_led_brightness(int brightness);
void signal_handler(int signal);

// Signal handler
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Initialize VEML7700 sensor
int init_veml7700() {
    char buf[3];
    buf[0] = CONFIG_REG;
    buf[1] = 0x00; // Integration time 100ms, gain 1/8
    buf[2] = 0x00;

    int result = i2cWriteDevice(i2c_handle, buf, 3);
    if (result != 0) {
        fprintf(stderr, "Error writing to VEML7700: %d\n", result);
        return -1;
    }
    return 0;
}

// Read ALS data from VEML7700
int read_als_data(uint16_t *als_data) {
    char reg = ALS_REG;
    char buf[2];
    int result;
    int retries = 0;

    while (retries < RETRY_COUNT) {
