#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>
#include <string.h>

// Define GPIO pins
#define FLAME_SENSOR_PIN 4
#define BUZZER_PIN 17
#define LED_PIN 18

// Define GPIO chip name
#define GPIO_CHIP "gpiochip0"

// Global variables for GPIO lines and chip
struct gpiod_line *flame_sensor_line = NULL;
struct gpiod_line *buzzer_line = NULL;
struct gpiod_line *led_line = NULL;
struct gpiod_chip *gpio_chip = NULL;

// Function prototypes
int self_test();
int read_flame_sensor();
void activate_buzzer();
void deactivate_buzzer();
void activate_led();
void deactivate_led();
void log_event(const char *event);
void signal_handler(int sig);

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    if (sig == SIGINT) {
        printf("\nCaught SIGINT, exiting gracefully.\n");

        // Deactivate buzzer and LED
        deactivate_buzzer();
        deactivate_led();

        // Release GPIO lines
        if (flame_sensor_line) {
            gpiod_line_release(flame_sensor_line);
        }
        if (buzzer_line) {
            gpiod_line_release(buzzer_line);
        }
        if (led_line) {
            gpiod_line_release(led_line);
        }

        // Close GPIO chip
        if (gpio_chip) {
            gpiod_chip_close(gpio_chip);
        }

        exit(0);
    }
}

// Self-test function
int self_test() {
    int i;
    int flame_detected = 0;

    // Blink LED twice
    for (i = 0; i < 2; i++) {
        activate_led();
        struct timespec sleep_time = {0, 500000000}; // 500 ms
        nanosleep(&sleep_time, NULL);
        deactivate_led();
        sleep_time.tv_nsec = 500000000;
        nanosleep(&sleep_time, NULL);
    }

    // Read flame sensor 5 times
    for (i = 0; i < 5; i++) {
        int sensor_value = read_flame_sensor();
        if (sensor_value == 0) {
            flame_detected++;
        }
        struct timespec sleep_time = {0, 100000000}; // 100 ms
        nanosleep(&sleep_time, NULL);
    }

    // Check if flame was consistently detected
    if (flame_detected == 5) {
        log_event("Self-test failed: Flame sensor consistently LOW.");
        return 1; // Self-test failed
    }

    log_event("Self-test passed.");
    return 0; // Self-test passed
}

// Function to read the flame sensor
int read_flame_sensor() {
    int value = gpiod_line_get_value(flame_sensor_line);
    if (value < 0) {
        perror("Error reading flame sensor");
        return -1; // Indicate error
    }
    return value;
}

// Function to activate the buzzer
void activate_buzzer() {
    int ret = gpiod_line_set_value(buzzer_line, 1);
    if (ret < 0) {
        perror("Error activating buzzer");
    }
}

// Function to deactivate the buzzer
void deactivate_buzzer() {
    int ret = gpiod_line_set_value(buzzer_line, 0);
    if (ret < 0) {
        perror("Error deactivating buzzer");
    }
}

// Function to activate the LED
void activate_led() {
    int ret = gpiod_line_set_value(led_line, 1);
    if (ret < 0) {
        perror("Error activating LED");
    }
}

// Function to deactivate the LED
void deactivate_led() {
    int ret = gpiod_line_set_value(led_line, 0);
    if (ret < 0) {
        perror("Error deactivating LED");
    }
}

// Function to log events with timestamps
void log_event(const char *event) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    printf("[%s] %s\n", timestamp, event);
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open GPIO chip
    gpio_chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!gpio_chip) {
        perror("Error opening GPIO chip");
        return 1;
    }

    // Get GPIO lines
    flame_sensor_line = gpiod_chip_get_line(gpio_chip, FLAME_SENSOR_PIN);
    buzzer_line = gpiod_chip_get_line(gpio_chip, BUZZER_PIN);
    led_line = gpiod_chip_get_line(gpio_chip, LED_PIN);

    if (!flame_sensor_line || !buzzer_line || !led_line) {
        perror("Error getting GPIO line");
        gpiod_chip_close(gpio_chip);
        return 1;
    }

    // Request GPIO lines for input/output
    struct gpiod_line_request_config config;
    memset(&config, 0, sizeof(config));

    config.consumer = "flame_sensor";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT;
    config.flags = 0;

    if (gpiod_line_request(flame_sensor_line, &config, 0) < 0) {
        perror("Error requesting flame sensor line");
        gpiod_chip_close(gpio_chip);
        gpiod_line_release(flame_sensor_line);
        gpiod_line_release(buzzer_line);
        gpiod_line_release(led_line);
        return 1;
    }

    config.consumer = "buzzer";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;

    if (gpiod_line_request(buzzer_line, &config, 0) < 0) {
        perror("Error requesting buzzer line");
        gpiod_chip_close(gpio_chip);
        gpiod_line_release(flame_sensor_line);
        gpiod_line_release(buzzer_line);
        gpiod_line_release(led_line);
        return 1;
    }

    config.consumer = "led";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;

    if (gpiod_line_request(led_line, &config, 0) < 0) {
        perror("Error requesting LED line");
        gpiod_chip_close(gpio_chip);
        gpiod_line_release(flame_sensor_line);
        gpiod_line_release(buzzer_line);
        gpiod_line_release(led_line);
        return 1;
    }

    // Perform self-test
    if (self_test()) {
        // Signal self-test failure
        log_event("Self-test failed.");
        for (int i = 0; i < 5; i++) {
            activate_led();
            struct timespec sleep_time = {0, 100000000}; // 100 ms
            nanosleep(&sleep_time, NULL);
            deactivate_led();
            sleep_time.tv_nsec = 100000000;
            nanosleep(&sleep_time, NULL);
        }

        // Buzzer pattern
        for (int i = 0; i < 3; i++) {
            activate_buzzer();
            struct timespec sleep_time = {0, 200000000}; // 200 ms
            nanosleep(&sleep_time, NULL);
            deactivate_buzzer();
            sleep_time.tv_nsec = 200000000;
            nanosleep(&sleep_time, NULL);
            activate_buzzer();
            sleep_time.tv_nsec = 600000000; // 600 ms
            nanosleep(&sleep_time, NULL);
            deactivate_buzzer();
            sleep_time.tv_nsec = 200000000;
            nanosleep(&sleep_time, NULL);
        }

        gpiod_chip_close(gpio_chip);
        gpiod_line_release(flame_sensor_line);
        gpiod_line_release(buzzer_line);
        gpiod_line_release(led_line);
        return 1;
    }

    // Main loop
    while (1) {
        int sensor_value = read_flame_sensor();
        if (sensor_value < 0) {
            log_event("Error reading sensor, exiting.");
            break;
        }

        if (sensor_value == 0) {
            log_event("Flame detected!");
            activate_buzzer();
            activate_led();

            // Wait for flame to go away
            while (1) {
                sensor_value = read_flame_sensor();
                if (sensor_value < 0) {
                    log_event("Error reading sensor, exiting.");
                    break;
                }
                if (sensor_value == 1) {
                    log_event("Flame gone!");
                    deactivate_buzzer();
                    deactivate_led();
                    break;
                }
                struct timespec sleep_time = {0, 50000000}; // 50 ms
                nanosleep(&sleep_time, NULL);
            }
        }
        struct timespec sleep_time = {0, 50000}; // 50 ms
        nanosleep(&sleep_time, NULL);
    }

    // Cleanup (should not reach here under normal circumstances due to signal handler)
    deactivate_buzzer();
    deactivate_led();
    gpiod_line_release(flame_sensor_line);
    gpiod_line_release(buzzer_line);
    gpiod_line_release(led_line);
    gpiod_chip_close(gpio_chip);

    return 0;
}

