#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <time.h>
#include <string.h>
#include <errno.h>

// Constants
#define I2C_BUS "/dev/i2c-1"
#define BH1750_ADDR 0x23
#define CONTINUOUS_HIGH_RES_MODE 0x10
#define LUX_SCALE_FACTOR 1.2
#define GPIO_PIN 17
#define BUFFER_SIZE 60
#define MIN_BLINK_RATE 0.5
#define MAX_BLINK_RATE 5.0
#define LUX_THRESHOLD_HIGH 1000.0
#define LUX_THRESHOLD_LOW 500.0

// Global variables
volatile sig_atomic_t program_running = 1;
int i2c_fd = -1;

// Circular buffer structure
typedef struct {
    float buffer[BUFFER_SIZE];
    int head;
    int count;
} CircularBuffer;

// Function prototypes
int init_i2c(const char *bus);
int init_bh1750(int fd);
int read_bh1750(int fd, uint16_t *raw_value);
float convert_to_lux(uint16_t raw_value);
void add_to_buffer(CircularBuffer *cb, float value);
float calculate_average(CircularBuffer *cb);
void control_led(float average_lux);
void signal_handler(int signal);
void cleanup();

// Initialize I2C bus
int init_i2c(const char *bus) {
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C bus");
        return -1;
    }
    if (ioctl(fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        perror("Error setting I2C slave address");
        close(fd);
        return -1;
    }
    return fd;
}

// Initialize BH1750 sensor
int init_bh1750(int fd) {
    uint8_t mode = CONTINUOUS_HIGH_RES_MODE;
    if (write(fd, &mode, 1) != 1) {
        perror("Error writing to I2C device");
        return -1;
    }
    return 0;
}

// Read raw data from BH1750 sensor
int read_bh1750(int fd, uint16_t *raw_value) {
    uint8_t buffer[2];
    if (read(fd, buffer, 2) != 2) {
        perror("Error reading from I2C device");
        return -1;
    }
    *raw_value = (buffer[0] << 8) | buffer[1];
    return 0;
}

// Convert raw data to lux
float convert_to_lux(uint16_t raw_value) {
    return (float)raw_value / LUX_SCALE_FACTOR;
}

// Add value to circular buffer
void add_to_buffer(CircularBuffer *cb, float value) {
    cb->buffer[cb->head] = value;
    cb->head = (cb->head + 1) % BUFFER_SIZE;
    if (cb->count < BUFFER_SIZE) {
        cb->count++;
    }
}

// Calculate average of values in circular buffer
float calculate_average(CircularBuffer *cb) {
    if (cb->count == 0) {
        return 0.0;
    }
    float sum = 0.0;
    for (int i = 0; i < cb->count; i++) {
        sum += cb->buffer[i];
    }
    return sum / cb->count;
}

// Control LED blinking rate based on average lux
void control_led(float average_lux) {
    float blink_rate = MIN_BLINK_RATE + (average_lux / LUX_THRESHOLD_HIGH) * (MAX_BLINK_RATE - MIN_BLINK_RATE);
    if (average_lux < LUX_THRESHOLD_LOW) {
        blink_rate = MIN_BLINK_RATE;
    }
    if (blink_rate > MAX_BLINK_RATE) {
        blink_rate = MAX_BLINK_RATE;
    }

    float period = 1.0 / blink_rate;
    float on_time = period / 2.0;

    char gpio_path[64];
    snprintf(gpio_path, sizeof(gpio_path), "/sys/class/gpio/gpio%d/value", GPIO_PIN);

    int gpio_fd = open(gpio_path, O_WRONLY);
    if (gpio_fd < 0) {
        perror("Error opening GPIO value file");
        return;
    }

    struct timespec on_time_spec = {0};
    on_time_spec.tv_sec = (int)on_time;
    on_time_spec.tv_nsec = (long)((on_time - (int)on_time) * 1000000000);
    nanosleep(&on_time_spec, NULL);

    if (write(gpio_fd, "1", 1) != 1) {
        perror("Error writing to GPIO value file (on)");
    }

    struct timespec off_time_spec = {0};
    off_time_spec.tv_sec = (int)(period - on_time);
    off_time_spec.tv_nsec = (long)((period - on_time - (int)(period - on_time)) * 1000000000);
    nanosleep(&off_time_spec, NULL);

    if (write(gpio_fd, "0", 1) != 1) {
        perror("Error writing to GPIO value file (off)");
    }

    close(gpio_fd);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting...\n", signal);
}

// Cleanup resources before exiting
void cleanup() {
    if (i2c_fd != -1) {
        close(i2c_fd);
    }

    // Unexport GPIO (if it was exported)
    char gpio_path[64];
    snprintf(gpio_path, sizeof(gpio_path), "/sys/class/gpio/unexport");
    int gpio_fd = open(gpio_path, O_WRONLY);
    if (gpio_fd >= 0) {
        char gpio_str[4];
        snprintf(gpio_str, sizeof(gpio_str), "%d", GPIO_PIN);
        write(gpio_fd, gpio_str, strlen(gpio_str));
        close(gpio_fd);
    }
}

int main() {
    // Install signal handler
    signal(SIGINT, signal_handler);

    // Initialize I2C
    i2c_fd = init_i2c(I2C_BUS);
    if (i2c_fd < 0) {
        return 1;
    }

    // Initialize BH1750 sensor
    if (init_bh1750(i2c_fd) < 0) {
        cleanup();
        return 1;
    }

    // Initialize circular buffer
    CircularBuffer lux_buffer = {{0.0}, 0, 0};

    // Export GPIO pin
    char gpio_path[64];
    snprintf(gpio_path, sizeof(gpio_path), "/sys/class/gpio/export");
    int gpio_fd = open(gpio_path, O_WRONLY);
    if (gpio_fd < 0) {
        perror("Error opening GPIO export file");
        cleanup();
        return 1;
    }
    char gpio_str[4];
    snprintf(gpio_str, sizeof(gpio_str), "%d", GPIO_PIN);
    write(gpio_fd, gpio_str, strlen(gpio_str));
    close(gpio_fd);

    // Set GPIO direction to output
    snprintf(gpio_path, sizeof(gpio_path), "/sys/class/gpio/gpio%d/direction", GPIO_PIN);
    gpio_fd = open(gpio_path, O_WRONLY);
    if (gpio_fd < 0) {
        perror("Error opening GPIO direction file");
        cleanup();
        return 1;
    }
    write(gpio_fd, "out", 3);
    close(gpio_fd);

    // Main loop
    while (program_running) {
        uint16_t raw_value;
        if (read_bh1750(i2c_fd, &raw_value) == 0) {
            float lux = convert_to_lux(raw_value);
            add_to_buffer(&lux_buffer, lux);
            float average_lux = calculate_average(&lux_buffer);
            printf("Raw: %u, Lux: %.2f, Average Lux: %.2f\n", raw_value, lux, average_lux);
            control_led(average_lux);
        } else {
            fprintf(stderr, "Error reading sensor data. Retrying...\n");
        }
        sleep(1);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

