#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <unistd.h>
#include <errno.h>
#include <string.h>

// Define GPIO pins
#define DATA_PIN 17
#define CLOCK_PIN 18
#define LATCH_PIN 27

// Define segment patterns for digits 0-9 (common cathode)
const unsigned char digit_patterns[] = {
    0b00111111, // 0
    0b00000110, // 1
    0b01011011, // 2
    0b01001111, // 3
    0b01100110, // 4
    0b01101101, // 5
    0b01111101, // 6
    0b00000111, // 7
    0b01111111, // 8
    0b01101111  // 9
};

// Function to shift out data to the 74HC595
void shift_out(struct gpiod_line *data_line, struct gpiod_line *clock_line, unsigned char data) {
    for (int i = 0; i < 8; i++) {
        // Set data pin based on the current bit
        if (data & (1 << i)) {
            gpiod_line_set_value(data_line, 1);
        } else {
            gpiod_line_set_value(data_line, 0);
        }

        // Clock the data in
        gpiod_line_set_value(clock_line, 1);
        usleep(1); // Small delay for clock stability
        gpiod_line_set_value(clock_line, 0);
        usleep(1); // Small delay for clock stability
    }
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *data_line, *clock_line, *latch_line;
    int ret;

    // Open the GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Error opening GPIO chip");
        return 1;
    }

    // Get the data line
    data_line = gpiod_chip_get_line(chip, DATA_PIN);
    if (!data_line) {
        perror("Error getting data line");
        gpiod_chip_close(chip);
        return 1;
    }

    // Get the clock line
    clock_line = gpiod_chip_get_line(chip, CLOCK_PIN);
    if (!clock_line) {
        perror("Error getting clock line");
        gpiod_line_release(data_line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Get the latch line
    latch_line = gpiod_chip_get_line(chip, LATCH_PIN);
    if (!latch_line) {
        perror("Error getting latch line");
        gpiod_line_release(data_line);
        gpiod_line_release(clock_line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Request the lines for output
    ret = gpiod_line_request_output(data_line, "seven_segment_data", 0);
    if (ret < 0) {
        perror("Error requesting data line for output");
        gpiod_line_release(data_line);
        gpiod_line_release(clock_line);
        gpiod_line_release(latch_line);
        gpiod_chip_close(chip);
        return 1;
    }

    ret = gpiod_line_request_output(clock_line, "seven_segment_clock", 0);
    if (ret < 0) {
        perror("Error requesting clock line for output");
        gpiod_line_release(data_line);
        gpiod_line_release(clock_line);
        gpiod_line_release(latch_line);
        gpiod_chip_close(chip);
        return 1;
    }

    ret = gpiod_line_request_output(latch_line, "seven_segment_latch", 0);
    if (ret < 0) {
        perror("Error requesting latch line for output");
        gpiod_line_release(data_line);
        gpiod_line_release(clock_line);
        gpiod_line_release(latch_line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Main loop to blink the digit '5'
    while (1) {
        // Display the digit '5'
        shift_out(data_line, clock_line, digit_patterns[5]);
        gpiod_line_set_value(latch_line, 1);
        usleep(1); // Small delay
        gpiod_line_set_value(latch_line, 0);
        usleep(500000); // 500 ms

        // Turn off all segments
        shift_out(data_line, clock_line, 0x00);
        gpiod_line_set_value(latch_line, 1);
        usleep(1); // Small delay
        gpiod_line_set_value(latch_line, 0);
        usleep(500000); // 500 ms
    }

    // Cleanup (this part will not be reached in the infinite loop)
    gpiod_line_release(data_line);
    gpiod_line_release(clock_line);
    gpiod_line_release(latch_line);
    gpiod_chip_close(chip);

    return 0;
}

