#include <stdlib.h>
#include <gpiod.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>

// Define GPIO pins
#define LED_PIN 17
#define BUTTON_PIN 18

// Global variables for GPIO chip and lines
struct gpiod_chip *chip;
struct gpiod_line *led_line;
struct gpiod_line *button_line;

// Function prototypes
int init_gpio(void);
void blink_led(void);
void button_interrupt(int gpio, struct gpiod_line *line, struct gpiod_event *event);
void signal_handler(int sig);

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    if (sig == SIGINT) {
        printf("\nCaught SIGINT, exiting gracefully.\n");
        // Turn off the LED
        if (led_line) {
            int ret = gpiod_line_set_value(led_line, 0);
            if (ret < 0) {
                perror("Error setting LED value to 0");
            }
        }

        // Release GPIO lines
        if (led_line) {
            gpiod_line_release(led_line);
        }
        if (button_line) {
            gpiod_line_release(button_line);
        }

        // Close GPIO chip
        if (chip) {
            gpiod_chip_close(chip);
        }

        exit(0);
    }
}

// Initialize GPIO pins
int init_gpio(void) {
    // Open GPIO chip 0
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    // Request LED pin as output
    led_line = gpiod_chip_get_line(chip, LED_PIN);
    if (!led_line) {
        perror("Error getting LED line");
        gpiod_chip_close(chip);
        return -1;
    }

    int ret = gpiod_line_request(led_line, "blink_button", GPIOD_LINE_REQUEST_DIRECTION_OUTPUT);
    if (ret < 0) {
        perror("Error requesting LED line as output");
        gpiod_chip_close(chip);
        return -1;
    }

    // Request button pin as input with pull-up and falling edge detection
    button_line = gpiod_chip_get_line(chip, BUTTON_PIN);
    if (!button_line) {
        perror("Error getting button line");
        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
        return -1;
    }

    ret = gpiod_line_request(button_line, "blink_button", GPIOD_LINE_REQUEST_DIRECTION_INPUT | GPIOD_LINE_REQUEST_FLAG_PULL_UP | GPIOD_LINE_REQUEST_FLAG_EVENT_BOTH_EDGES);
    if (ret < 0) {
        perror("Error requesting button line as input");
        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
        return -1;
    }

    return 0;
}

// Blink the LED
void blink_led(void) {
    int ret;

    // Turn on the LED
    ret = gpiod_line_set_value(led_line, 1);
    if (ret < 0) {
        perror("Error setting LED value to 1");
        return;
    }

    // Wait for 1 second
    struct timespec sleep_time;
    sleep_time.tv_sec = 1;
    sleep_time.tv_nsec = 0;
    nanosleep(&sleep_time, NULL);

    // Turn off the LED
    ret = gpiod_line_set_value(led_line, 0);
    if (ret < 0) {
        perror("Error setting LED value to 0");
        return;
    }

    // Wait for 1 second
    sleep_time.tv_sec = 1;
    sleep_time.tv_nsec = 0;
    nanosleep(&sleep_time, NULL);
}

// Button interrupt handler
void button_interrupt(int gpio, struct gpiod_line *line, struct gpiod_event *event) {
    printf("Button pressed!\n");

    // Turn off the LED
    int ret = gpiod_line_set_value(led_line, 0);
    if (ret < 0) {
        perror("Error setting LED value to 0 in interrupt");
    }

    // Release GPIO lines and close chip (already done in signal handler, but included for completeness)
    gpiod_line_release(led_line);
    gpiod_line_release(button_line);
    gpiod_chip_close(chip);

    exit(0);
}

int main(void) {
    // Install signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (init_gpio() < 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return 1;
    }

    // Main loop
    while (1) {
        // Blink the LED
        blink_led();

        // Wait for button press with a timeout
        struct gpiod_event event;
        int ret = gpiod_line_event_wait(button_line, 1000000); // Timeout of 1 second (1000000 microseconds)

        if (ret < 0) {
            perror("Error waiting for button event");
            break; // Exit loop on error
        } else if (ret == 0) {
            // Timeout occurred, continue blinking
            continue;
        } else {
            // Button event occurred
            gpiod_event_init(&event);
            gpiod_line_event_read(button_line, &event);
            button_interrupt(event.gpio, button_line, &event);
        }
    }

    // Cleanup (should not reach here under normal operation due to signal handler)
    gpiod_line_release(led_line);
    gpiod_line_release(button_line);
    gpiod_chip_close(chip);

    return 0;
}

