#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>
#include <signal.h>
#include <time.h>
#include <errno.h>

// Define GPIO pins
#define LED_PIN 24
#define BUTTON_PIN 22

// Define I2C parameters
#define I2C_BUS "/dev/i2c-1"
#define SENSOR_ADDRESS 0x48
#define SENSOR_REG 0x00

// Define LED blink interval (in milliseconds)
#define BLINK_INTERVAL_MS 500

// Global variables
static volatile int keep_running = 1;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *led_line = NULL;
static struct gpiod_line *button_line = NULL;
static int i2c_fd = -1;

// Function prototypes
int init_gpio(void);
int init_i2c(void);
int read_sensor_data(void);
void control_led(int sensor_value);
void button_callback(int line, struct gpiod_line *line, int value, void *user_data);
void signal_handler(int sig);
void cleanup(void);

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, exiting gracefully...\n");
    keep_running = 0;
}

// Initialize GPIO lines
int init_gpio(void) {
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", strerror(errno));
        return -1;
    }

    led_line = gpiod_chip_get_line(chip, LED_PIN);
    if (!led_line) {
        fprintf(stderr, "Error getting LED line: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        return -1;
    }

    button_line = gpiod_chip_get_line(chip, BUTTON_PIN);
    if (!button_line) {
        fprintf(stderr, "Error getting button line: %s\n", strerror(errno));
        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
        return -1;
    }

    // Set LED pin as output and initially low
    if (gpiod_line_request_output(led_line, "led_control", 0) < 0) {
        fprintf(stderr, "Error requesting LED line as output: %s\n", strerror(errno));
        gpiod_line_release(button_line);
        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
        return -1;
    }

    // Set button pin as input with pull-down resistor
    if (gpiod_line_request_input(button_line, "button_control") < 0) {
        fprintf(stderr, "Error requesting button line as input: %s\n", strerror(errno));
        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
        return -1;
    }

    return 0;
}

// Initialize I2C communication
int init_i2c(void) {
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C bus: %s\n", strerror(errno));
        return -1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, SENSOR_ADDRESS) < 0) {
        fprintf(stderr, "Error setting I2C slave address: %s\n", strerror(errno));
        close(i2c_fd);
        return -1;
    }

    return 0;
}

// Read sensor data from I2C
int read_sensor_data(void) {
    unsigned char buffer[2];
    int result;

    result = read(i2c_fd, buffer, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading from I2C: %s\n", strerror(errno));
        return -1;
    }

    // Combine the two bytes into a single 16-bit value
    return (buffer[0] << 8) | buffer[1];
}

// Control the LED based on sensor data
void control_led(int sensor_value) {
    static int led_state = 0; // 0 = off, 1 = on
    static struct timespec last_blink_time;
    struct timespec current_time;
    long elapsed_ms;

    clock_gettime(CLOCK_MONOTONIC, &current_time);
    elapsed_ms = (current_time.tv_sec - last_blink_time.tv_sec) * 1000 + (current_time.tv_nsec - last_blink_time.tv_nsec) / 1000000;

    if (sensor_value > 1000) { // Example threshold
        if (led_state == 0 && elapsed_ms >= BLINK_INTERVAL_MS) {
            gpiod_line_set_value(led_line, 1);
            led_state = 1;
            clock_gettime(CLOCK_MONOTONIC, &last_blink_time);
        } else if (led_state == 1 && elapsed_ms >= BLINK_INTERVAL_MS) {
            gpiod_line_set_value(led_line, 0);
            led_state = 0;
            clock_gettime(CLOCK_MONOTONIC, &last_blink_time);
        }
    } else {
        gpiod_line_set_value(led_line, 0);
        led_state = 0;
    }
}

// Callback function for button press/release
void button_callback(int line, struct gpiod_line *line, int value, void *user_data) {
    (void)user_data; // Suppress unused parameter warning
    if (value == 0) { // Button pressed (active low)
        printf("Button pressed!\n");
    } else { // Button released
        printf("Button released!\n");
    }
}

// Cleanup resources before exiting
void cleanup(void) {
    printf("Cleaning up resources...\n");

    if (led_line) {
        gpiod_line_release(led_line);
    }
    if (button_line) {
        gpiod_line_release(button_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (i2c_fd != -1) {
        close(i2c_fd);
    }

    printf("Cleanup complete.\n");
}

int main(void) {
    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (init_gpio() < 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() < 0) {
        fprintf(stderr, "I2C initialization failed. Exiting.\n");
        cleanup();
        return 1;
    }

    // Set up interrupt on button press/release
    if (gpiod_line_request_callback(button_line, "button_callback", button_callback, NULL) < 0) {
        fprintf(stderr, "Error requesting callback on button line: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    printf("Program started. Press Ctrl+C to exit.\n");

    // Main loop
    while (keep_running) {
        int sensor_value = read_sensor_data();
        if (sensor_value >= 0) {
            control_led(sensor_value);
        } else {
            fprintf(stderr, "Failed to read sensor data. Retrying...\n");
        }
        usleep(10000); // Sleep for 10ms
    }

    // Cleanup resources before exiting
    cleanup();

    return 0;
}

