        return 1;
    }

    // Initialize I2C
    if (init_i2c() < 0) {
        fprintf(stderr, "I2C initialization failed. Exiting.\n");
        cleanup();
        return 1;
    }

    // Set up interrupt on button press/release
    if (gpiod_line_request_callback(button_line, "button_callback", button_callback, NULL) < 0) {
        fprintf(stderr, "Error requesting callback on button line: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    printf("Program started. Press Ctrl+C to exit.\n");

    // Main loop
    while (keep_running) {
        int sensor_value = read_sensor_data();
        if (sensor_value >= 0) {
            control_led(sensor_value);
        } else {
            fprintf(stderr, "Failed to read sensor data. Retrying...\n");
        }
        usleep(10000); // Sleep for 10ms
    }

    // Cleanup resources before exiting
    cleanup();

    return 0;
}

