#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <math.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define LSM303_ADDR 0x19
#define OUT_X_L_A 0x28
#define CTRL_REG1_A 0x20
#define CTRL_REG4_A 0x23
#define GPIO_PIN 17
#define SAMPLE_RATE_HZ 10
#define SAMPLE_PERIOD_US (1000000 / SAMPLE_RATE_HZ)
#define IMPACT_THRESHOLD 2.0 // Default threshold
#define IMPACT_PULSE_MS 50
#define LOG_FILE "impact_log.txt"

// Global variables
static volatile int running = 1;
static int i2c_handle;
static FILE *log_file;

// Structure to hold accelerometer data
typedef struct {
    int16_t x;
    int16_t y;
    int16_t z;
} accelerometer_data_t;

// Function prototypes
int initialize_i2c();
int configure_accelerometer();
accelerometer_data_t read_accelerometer_data();
double calculate_g_force(accelerometer_data_t data);
void impact_detected(accelerometer_data_t data);
void log_impact_data(accelerometer_data_t data);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize I2C communication
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, LSM303_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Configure the LSM303DLHC accelerometer
int configure_accelerometer() {
    // Enable all axes and set data rate to 100 Hz
    if (i2cWriteByteData(i2c_handle, CTRL_REG1_A, 0x27) < 0) {
        fprintf(stderr, "Error writing to CTRL_REG1_A\n");
        return -1;
    }

    // Set full-scale range to +/- 2G
    if (i2cWriteByteData(i2c_handle, CTRL_REG4_A, 0x00) < 0) {
        fprintf(stderr, "Error writing to CTRL_REG4_A\n");
        return -1;
    }

    return 0;
}

// Read accelerometer data from the LSM303DLHC
accelerometer_data_t read_accelerometer_data() {
    accelerometer_data_t data;
    char buffer[6];

    if (i2cReadI2CBlockData(i2c_handle, OUT_X_L_A | 0x80, buffer, 6) < 0) {
        fprintf(stderr, "Error reading accelerometer data\n");
        data.x = 0; data.y = 0; data.z = 0; // Return zeroed data on error
        return data;
    }

    data.x = (int16_t)((buffer[1] << 8) | buffer[0]);
    data.y = (int16_t)((buffer[3] << 8) | buffer[2]);
    data.z = (int16_t)((buffer[5] << 8) | buffer[4]);

    return data;
}

// Calculate the magnitude of the G-force vector
double calculate_g_force(accelerometer_data_t data) {
    double x = (double)data.x / 16384.0;
    double y = (double)data.y / 16384.0;
    double z = (double)data.z / 16384.0;
    return sqrt(x * x + y * y + z * z);
}

// Impact detection and GPIO control
void impact_detected(accelerometer_data_t data) {
    double g_force = calculate_g_force(data);

    if (g_force > IMPACT_THRESHOLD) {
        printf("Impact detected! G-force: %.2f\n", g_force);
        gpioWrite(GPIO_PIN, 1); // Set GPIO HIGH
        gpioDelay(IMPACT_PULSE_MS * 1000); // Delay for 50ms
        gpioWrite(GPIO_PIN, 0); // Set GPIO LOW
        log_impact_data(data);
    }
}

// Log impact data to file
void log_impact_data(accelerometer_data_t data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, X: %d, Y: %d, Z: %d\n", timestamp, data.x, data.y, data.z);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Cleanup resources before exiting
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main(int argc, char *argv[]) {
    double impact_threshold = IMPACT_THRESHOLD;

    // Parse command-line arguments
    if (argc > 1) {
        impact_threshold = atof(argv[1]);
        printf("Using impact threshold: %.2f G\n", impact_threshold);
    } else {
        printf("Using default impact threshold: %.2f G\n", impact_threshold);
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pin as output
    gpioSetMode(GPIO_PIN, PI_OUTPUT);

    // Initialize I2C
    if (initialize_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Configure accelerometer
    if (configure_accelerometer() != 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        cleanup();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Impact detection started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        accelerometer_data_t data = read_accelerometer_data();
        impact_detected(data);
        gpioDelay(SAMPLE_PERIOD_US); // Delay for 100ms
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

