#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// Constants
#define I2C_BUS 1
#define I2C_ADDRESS 0x39
#define ALS_REG_LSB 0x64
#define ALS_REG_MSB 0x65
#define RED_REG_LSB 0x66
#define RED_REG_MSB 0x68
#define GREEN_REG_LSB 0x68
#define GREEN_REG_MSB 0x6A
#define BLUE_REG_LSB 0x6A
#define BLUE_REG_MSB 0x6C
#define MODE_REG 0x0D
#define PWM_GPIO 18
#define PWM_FREQUENCY 1000 // Hz
#define SAMPLE_INTERVAL_MS 500

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_sensor();
int read_als_data(uint16_t *als);
int read_rgb_data(uint16_t *red, uint16_t *green, uint16_t *blue);
void log_data(uint16_t als, uint16_t red, uint16_t green, uint16_t blue);
void set_led_brightness(uint16_t als);
void signal_handler(int signal);

// Signal handler
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Initialize the sensor
int initialize_sensor() {
    int result = i2cWriteByteData(i2c_handle, MODE_REG, 0x01);
    if (result != 0) {
        fprintf(stderr, "Error initializing sensor: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Read ALS data from the sensor
int read_als_data(uint16_t *als) {
    char buf[2];
    int result = i2cReadI2CBlockData(i2c_handle, ALS_REG_LSB, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading ALS data: %s\n", strerror(errno));
        return -1;
    }
    *als = (buf[1] << 8) | buf[0];
    return 0;
}

// Read RGB data from the sensor
int read_rgb_data(uint16_t *red, uint16_t *green, uint16_t *blue) {
    char buf[6];
    int result = i2cReadI2CBlockData(i2c_handle, RED_REG_LSB, buf, 6);
    if (result != 6) {
        fprintf(stderr, "Error reading RGB data: %s\n", strerror(errno));
        return -1;
    }

    *red = (buf[1] << 8) | buf[0];
    *green = (buf[3] << 8) | buf[2];
    *blue = (buf[5] << 8) | buf[4];

    return 0;
