#include <signal.h>
#include <string.h>

// FXOS8700CQ I2C address
#define FXOS8700CQ_ADDR 0x1F

// FXOS8700CQ register addresses
#define FXOS8700CQ_WHO_AM_I 0x0D
#define FXOS8700CQ_CTRL_REG1 0x2A
#define FXOS8700CQ_XYZ_DATA_CFG 0x0E
#define FXOS8700CQ_OUT_X_MSB 0x01

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_sensor();
int read_acceleration(float *x, float *y, float *z);
float calculate_magnitude(float x, float y, float z);
void log_impact(float x, float y, float z, float magnitude);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize the FXOS8700CQ sensor
int init_sensor() {
    // Verify WHO_AM_I register
    int who_am_i = i2cReadByteData(i2c_handle, FXOS8700CQ_WHO_AM_I);
    if (who_am_i < 0) {
        fprintf(stderr, "Error reading WHO_AM_I register: %d\n", who_am_i);
        return -1;
    }
    if (who_am_i != 0xC7) {
        fprintf(stderr, "Error: WHO_AM_I register returned 0x%02X, expected 0xC7\n", who_am_i);
        return -1;
    }
    printf("FXOS8700CQ sensor found!\n");

    // Configure sensor for active mode and 200 Hz ODR
    if (i2cWriteByteData(i2c_handle, FXOS8700CQ_CTRL_REG1, 0x01) < 0) {
        fprintf(stderr, "Error writing to CTRL_REG1 register\n");
        return -1;
    }

    // Configure sensor for ±2g range
    if (i2cWriteByteData(i2c_handle, FXOS8700CQ_XYZ_DATA_CFG, 0x00) < 0) {
        fprintf(stderr, "Error writing to XYZ_DATA_CFG register\n");
        return -1;
    }

    return 0;
}

// Read acceleration data from the sensor
int read_acceleration(float *x, float *y, float *z) {
    char buffer[6];
    int result = i2cReadI2CBlockData(i2c_handle, FXOS8700CQ_OUT_X_MSB, buffer, 6);
    if (result < 0) {
        fprintf(stderr, "Error reading acceleration data: %d\n", result);
        return -1;
    }

    // Combine high and low bytes, shift right by 2 bits, and convert to g
    int16_t raw_x = (int16_t)((buffer[0] << 8) | buffer[1]) >> 2;
    int16_t raw_y = (int16_t)((buffer[2] << 8) | buffer[3]) >> 2;
    int16_t raw_z = (int16_t)((buffer[4] << 8) | buffer[5]) >> 2;

    *x = (float)raw_x / 4096.0f * 9.81f;
    *y = (float)raw_y / 4096.0f * 9.81f;
    *z = (float)raw_z / 4096.0f * 9.81f;

    return 0;
}

// Calculate the magnitude of the acceleration vector
float calculate_magnitude(float x, float y, float z) {
    return sqrt(x * x + y * y + z * z);
}

// Log impact data to a file
void log_impact(float x, float y, float z, float magnitude) {
    FILE *fp = fopen("impact_log.txt", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening impact_log.txt for writing\n");
        return;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s,%.3f,%.3f,%.3f,%.3f\n", timestamp, x, y, z, magnitude);
    fclose(fp);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, FXOS8700CQ_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize the sensor
    if (init_sensor() < 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    float x, y, z, magnitude;

    // Main loop
    while (!terminate) {
        // Read acceleration data
        if (read_acceleration(&x, &y, &z) == 0) {
            // Calculate magnitude
            magnitude = calculate_magnitude(x, y, z);

            // Check for impact
            if (magnitude > 19.62f) {
                log_impact(x, y, z, magnitude);
                printf("Impact detected! Magnitude: %.3f m/s^2\n", magnitude);
            }
        } else {
            fprintf(stderr, "Failed to read acceleration data. Continuing...\n");
        }

        // Delay for 50 ms
        gpioDelay(50000); // 50 ms = 50000 microseconds
    }

    // Close I2C bus and terminate pigpio
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

