#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <math.h>

// Constants
#define I2C_BUS 1
#define GYRO_ADDR 0x69
#define WHO_AM_I_REG 0x0F
#define WHO_AM_I_VALUE 0xD3
#define CTRL_REG1 0x20
#define CTRL_REG4 0x23
#define OUT_X_L 0x28
#define OUT_X_H 0x29
#define OUT_Y_L 0x2A
#define OUT_Y_H 0x2B
#define OUT_Z_L 0x2C
#define OUT_Z_H 0x2D
#define SENSITIVITY 0.00875f // dps/LSB
#define CALIBRATION_SAMPLES 100
#define ALERT_THRESHOLD 50.0f // dps
#define LOG_FILE "gyro_log.txt"

// Global variables
volatile sig_atomic_t program_running = 1;
int i2c_fd = -1;
FILE *log_file = NULL;

// Calibration offsets
float x_offset = 0.0f;
float y_offset = 0.0f;
float z_offset = 0.0f;

// Function prototypes
int init_i2c(int bus, int addr);
int read_register(int fd, uint8_t reg);
int write_register(int fd, uint8_t reg, uint8_t value);
int read_block(int fd, uint8_t reg, uint8_t *data, int len);
int16_t read_raw_data(int fd, uint8_t reg_l, uint8_t reg_h);
float convert_to_dps(int16_t raw_data);
void calibrate_gyro(int fd);
void log_data(float x, float y, float z);
void check_alerts(float x, float y, float z);
void signal_handler(int signum);

// Signal handler
void signal_handler(int signum) {
    program_running = 0;
    fprintf(stderr, "\nCaught signal %d, exiting gracefully...\n", signum);
}

// Initialize I2C bus
int init_i2c(int bus, int addr) {
    char filename[20];
    snprintf(filename, 19, "/dev/i2c-%d", bus);
    int fd = open(filename, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening I2C bus %d: %s\n", bus, strerror(errno));
        return -1;
    }
    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        fprintf(stderr, "Error setting I2C slave address 0x%02X: %s\n", addr, strerror(errno));
        close(fd);
        return -1;
    }
    return fd;
}

// Read a single register
int read_register(int fd, uint8_t reg) {
    int value = i2c_smbus_read_byte_data(fd, reg);
    if (value < 0) {
        fprintf(stderr, "Error reading register 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    return value;
}

// Write a single register
int write_register(int fd, uint8_t reg, uint8_t value) {
    int result = i2c_smbus_write_byte_data(fd, reg, value);
    if (result < 0) {
        fprintf(stderr, "Error writing register 0x%02X with value 0x%02X: %s\n", reg, value, strerror(errno));
        return -1;
    }
    return 0;
}

// Read a block of data
int read_block(int fd, uint8_t reg, uint8_t *data, int len) {
    int result = i2c_smbus_read_i2c_block_data(fd, reg, (char *)data, len);
    if (result < 0) {
        fprintf(stderr, "Error reading block from register 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

// Read raw 16-bit data from two registers
int16_t read_raw_data(int fd, uint8_t reg_l, uint8_t reg_h) {
    uint8_t data[2];
    if (read_block(fd, reg_l, data, 2) < 0) {
        return 0; // Return 0 on error
    }
    return (int16_t)((data[1] << 8) | data[0]);
}

// Convert raw data to degrees per second
float convert_to_dps(int16_t raw_data) {
    return (float)raw_data * SENSITIVITY;
}

// Calibrate the gyroscope
void calibrate_gyro(int fd) {
    float x_sum = 0.0f;
    float y_sum = 0.0f;
    float z_sum = 0.0f;

    for (int i = 0; i < CALIBRATION_SAMPLES; i++) {
        int16_t raw_x = read_raw_data(fd, OUT_X_L, OUT_X_H);
        int16_t raw_y = read_raw_data(fd, OUT_Y_L, OUT_Y_H);
        int16_t raw_z = read_raw_data(fd, OUT_Z_L, OUT_Z_H);

        x_sum += convert_to_dps(raw_x);
        y_sum += convert_to_dps(raw_y);
        z_sum += convert_to_dps(raw_z);
        usleep(10000); // 10 ms delay
    }

    x_offset = x_sum / CALIBRATION_SAMPLES;
    y_offset = y_sum / CALIBRATION_SAMPLES;
    z_offset = z_sum / CALIBRATION_SAMPLES;

    printf("Calibration complete. Offsets: X=%.3f, Y=%.3f, Z=%.3f\n", x_offset, y_offset, z_offset);
}

// Log data to file
void log_data(float x, float y, float z) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", t);

