        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", t);
        fprintf(log_file, "%s,ALERT,%.3f,%.3f,%.3f\n", timestamp, x, y, z);
        fflush(log_file);
    }
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
