    float accel_x, accel_y, accel_z;
    float mag_x, mag_y, mag_z;
    float heading;
} sensor_data_t;

int main() {
    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        fprintf(stderr, "I2C initialisation failed\n");
        gpioTerminate();
        return 1;
    }

    // Initialize accelerometer and magnetometer
    if (init_accelerometer() != 0 || init_magnetometer() != 0) {
        fprintf(stderr, "Sensor initialisation failed\n");
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("compass_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        gpioTerminate();
        return 1;
    }

    // Main loop
    sensor_data_t sensor_data;
    while (1) {
        // Read sensor data
        if (read_accelerometer(&sensor_data.accel_x, &sensor_data.accel_y, &sensor_data.accel_z) != 0) {
            fprintf(stderr, "Failed to read accelerometer data\n");
        }
        if (read_magnetometer(&sensor_data.mag_x, &sensor_data.mag_y, &sensor_data.mag_z) != 0) {
            fprintf(stderr, "Failed to read magnetometer data\n");
        }

        // Calculate heading
        sensor_data.heading = calculate_heading(sensor_data.accel_x, sensor_data.accel_y, sensor_data.accel_z, sensor_data.mag_x, sensor_data.mag_y, sensor_data.mag_z);

        // Log data
        if (log_data(sensor_data.heading, sensor_data.accel_x, sensor_data.accel_y, sensor_data.accel_z, sensor_data.mag_x, sensor_data.mag_y, sensor_data.mag_z) != 0) {
            fprintf(stderr, "Failed to log data\n");
        }

        // Delay for 100ms
        gpioDelay(100);
    }

    return 0;
}

// Initialize I2C
int init_i2c() {
    accel_handle = i2cOpen(1, ACCEL_ADDR, 0); // Bus 1, accelerometer address
    if (accel_handle < 0) {
        fprintf(stderr, "Failed to open I2C device for accelerometer: %d\n", accel_handle);
        return -1;
    }

    mag_handle = i2cOpen(1, MAG_ADDR, 0); // Bus 1, magnetometer address
    if (mag_handle < 0) {
        fprintf(stderr, "Failed to open I2C device for magnetometer: %d\n", mag_handle);
        i2cClose(accel_handle);
        return -1;
    }

    return 0;
}

// Initialize accelerometer
int init_accelerometer() {
    int result = i2cWriteByteData(accel_handle, CTRL_REG1_A, 0x27); // Enable all axes, 50 Hz
    if (result < 0) {
        fprintf(stderr, "Failed to write to accelerometer CTRL_REG1_A: %d\n", result);
        return -1;
    }
    return 0;
}

// Initialize magnetometer
int init_magnetometer() {
    int result = i2cWriteByteData(mag_handle, MR_REG_M, 0x00); // Continuous conversion mode
    if (result < 0) {
        fprintf(stderr, "Failed to write to magnetometer MR_REG_M: %d\n", result);
        return -1;
    }
    return 0;
}

// Read accelerometer data
int read_accelerometer(float *x, float *y, float *z) {
    char buffer[6];
    int result = i2cReadI2CBlockData(accel_handle, OUT_X_L_A | 0x80, buffer, 6); // Auto-increment
    if (result < 0) {
        fprintf(stderr, "Failed to read accelerometer data: %d\n", result);
        return -1;
    }

    // Combine high and low bytes, convert to g (assuming +/- 2g sensitivity)
    *x = (float)((int16_t)((buffer[1] << 8) | buffer[0])) / 16384.0f;
    *y = (float)((int16_t)((buffer[3] << 8) | buffer[2])) / 16384.0f;
    *z = (float)((int16_t)((buffer[5] << 8) | buffer[4])) / 16384.0f;

    return 0;
}

// Read magnetometer data
int read_magnetometer(float *x, float *y, float *z) {
    char buffer[6];
    int result = i2cReadI2CBlockData(mag_handle, OUT_X_H_M, buffer, 6);
    if (result < 0) {
        fprintf(stderr, "Failed to read magnetometer data: %d\n", result);
        return -1;
    }

    // Combine high and low bytes, convert to gauss (assuming +/- 1.3 gauss sensitivity)
    *x = (float)((int16_t)((buffer[0] << 8) | buffer[1])) / 1090.0f;
    *z = (float)((int16_t)((buffer[2] << 8) | buffer[3])) / 1090.0f;
    *y = (float)((int16_t)((buffer[4] << 8) | buffer[5])) / 1090.0f;

    return 0;
}

// Calculate tilt-compensated heading
float calculate_heading(float accel_x, float accel_y, float accel_z, float mag_x, float mag_y, float mag_z) {
    float roll = atan2(accel_x, accel_z);
    float pitch = atan2(-accel_y, sqrt(accel_x * accel_x + accel_z * accel_z));

    float mag_x_comp = mag_x * cos(pitch) + mag_z * sin(pitch);
    float mag_y_comp = mag_x * sin(roll) * sin(pitch) + mag_y * cos(roll) - mag_z * sin(roll) * cos(pitch);

    float heading = atan2(mag_y_comp, mag_x_comp) * 180 / M_PI;
    if (heading < 0) {
        heading += 360;
    }

    return heading;
}

// Log data to file
int log_data(float heading, float accel_x, float accel_y, float accel_z, float mag_x, float mag_y, float mag_z) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file == NULL) {
        fprintf(stderr, "Log file is not open\n");
        return -1;
    }

    // Check if the file is new and write the header
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Heading,Accel_X,Accel_Y,Accel_Z,Mag_X,Mag_Y,Mag_Z\n");
    }

    fprintf(log_file, "%s,%.2f,%.4f,%.4f,%.4f,%.4f,%.4f,%.4f\n",
            timestamp, heading, accel_x, accel_y, accel_z, mag_x, mag_y, mag_z);
    fflush(log_file); // Ensure data is written to disk

    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);

    // Close I2C handles
    if (accel_handle >= 0) {
        i2cClose(accel_handle);
    }
    if (mag_handle >= 0) {
        i2cClose(mag_handle);
    }

    // Terminate pigpio
    gpioTerminate();

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    exit(0);
}

