#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// VL6180X I2C address
#define VL6180X_ADDR 0x29

// VL6180X register addresses
#define VL6180X_REG_IDENTIFICATION_MODEL_ID 0x000
#define VL6180X_REG_SYSTEM_FRESH_OUT_OF_RESET 0x016
#define VL6180X_REG_SYSTEM_MODE_GPIO1 0x010
#define VL6180X_REG_SYSRANGE_START 0x018
#define VL6180X_REG_RESULT_RANGE_VAL 0x062
#define VL6180X_REG_RESULT_RANGE_STATUS 0x04D

// I2C bus
#define I2C_BUS 1

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int vl6180x_init();
int read_distance();
void log_data(int distance);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// VL6180X initialization function
int vl6180x_init() {
    int status;

    // Check device ID
    status = i2cWriteByteData(i2c_handle, VL6180X_REG_SYSTEM_FRESH_OUT_OF_RESET, 0x00);
    if (status < 0) {
        fprintf(stderr, "Error writing to I2C device: %d\n", status);
        return -1;
    }
    gpioDelay(1000); // 1 ms delay

    status = i2cWriteByteData(i2c_handle, VL6180X_REG_SYSTEM_MODE_GPIO1, 0x10);
    if (status < 0) {
        fprintf(stderr, "Error writing to I2C device: %d\n", status);
        return -1;
    }
    gpioDelay(1000); // 1 ms delay

    status = i2cWriteByteData(i2c_handle, VL6180X_REG_SYSRANGE_START, 0x01);
    if (status < 0) {
        fprintf(stderr, "Error writing to I2C device: %d\n", status);
        return -1;
    }
    gpioDelay(1000); // 1 ms delay

    return 0;
}

// Function to read distance from VL6180X
int read_distance() {
    int distance;
    int status;

    status = i2cWriteByteData(i2c_handle, VL6180X_REG_SYSRANGE_START, 0x01);
    if (status < 0) {
        fprintf(stderr, "Error writing to I2C device: %d\n", status);
        return -1;
    }
    gpioDelay(1000); // 1 ms delay

    distance = i2cReadByteData(i2c_handle, VL6180X_REG_RESULT_RANGE_VAL);
    if (distance < 0) {
        fprintf(stderr, "Error reading from I2C device: %d\n", distance);
        return -1;
    }

    return distance;
}

// Function to log data to file
void log_data(int distance) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (distance < 100) {
        fprintf(log_file, "%s DOOR_OPEN\n", timestamp);
        printf("%s DOOR_OPEN\n", timestamp);
    } else {
        fprintf(log_file, "%s DOOR_CLOSED\n", timestamp);
        printf("%s DOOR_CLOSED\n", timestamp);
    }
    fflush(log_file);
}

int main() {
    int distance;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, VL6180X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("distance_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize VL6180X sensor
    if (vl6180x_init() != 0) {
        fprintf(stderr, "VL6180X initialization failed!\n");
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        distance = read_distance();
        if (distance >= 0) {
            log_data(distance);
        } else {
            fprintf(stderr, "Error reading distance, attempting re-initialization...\n");
            fclose(log_file);
            i2cClose(i2c_handle);
            gpioTerminate();

            i2c_handle = i2cOpen(I2C_BUS, VL6180X_ADDR, 0);
            if (i2c_handle < 0) {
                fprintf(stderr, "Error re-opening I2C device: %d\n", i2c_handle);
                terminate = 1; // Exit loop if re-initialization fails
            } else {
                if (vl6180x_init() != 0) {
                    fprintf(stderr, "VL6180X re-initialization failed!\n");
                    terminate = 1; // Exit loop if re-initialization fails
                }
            }
        }

        gpioDelay(100); // 100 ms delay
    }

    // Clean up
    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

