int initialize_i2c(int address) {
    int handle = i2cOpen(1, address, 0); // Bus 1, address, flags
    if (handle < 0) {
        fprintf(stderr, "Failed to open I2C device at address 0x%02x: %s\n", address, strerror(errno));
        return -1;
    }
    return handle;
}

// Enable the sensor by writing to the control register
int enable_sensor(int i2c_handle) {
    int result = i2cWriteByteData(i2c_handle, CONTROL_REG, 0x80);
    if (result < 0) {
        fprintf(stderr, "Failed to enable sensor: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

