    if (enable_sensor(i2c_handle1) != 0) {
        i2cClose(i2c_handle1);
        i2cClose(i2c_handle2);
        gpioTerminate();
        return 1;
    }

    if (enable_sensor(i2c_handle2) != 0) {
        i2cClose(i2c_handle1);
        i2cClose(i2c_handle2);
        gpioTerminate();
        return 1;
    }

    // Open the log file
    log_file = fopen("audio_log.dat", "w");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        i2cClose(i2c_handle1);
        i2cClose(i2c_handle2);
        gpioTerminate();
        return 1;
    }

    // Write the CSV header
    fprintf(log_file, "sec,nsec,sensor1,sensor2,tdoa\n");

    // Main loop
    while (!terminate) {
        int16_t sensor1_data, sensor2_data;
        struct timespec ts;
        int16_t tdoa;

        // Read data from sensor 1
        if (read_sensor_data(i2c_handle1, &sensor1_data) == 0) {
            // Read data from sensor 2
            if (read_sensor_data(i2c_handle2, &sensor2_data) == 0) {
                // Calculate TDOA
                tdoa = calculate_tdoa(sensor1_data, sensor2_data);

                // Get timestamp
                if (clock_gettime(CLOCK_REALTIME, &ts) == 0) {
                    // Log the data
                    if (log_data(log_file, ts.tv_sec, ts.tv_nsec, sensor1_data, sensor2_data, tdoa) != 0) {
                        fprintf(stderr, "Error logging data, but continuing...\n");
                    }
                } else {
                    fprintf(stderr, "Failed to get timestamp: %s\n", strerror(errno));
                }
            } else {
                fprintf(stderr, "Error reading sensor 2 data, but continuing...\n");
            }
        } else {
            fprintf(stderr, "Error reading sensor 1 data, but continuing...\n");
        }

        // Delay for the sampling interval
        gpioDelay(SAMPLE_INTERVAL_US);
