#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

// Define constants
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 3
#define SPI_FLAGS 0b11000000000 // CPOL=1, CPHA=1, AUX off
#define SAMPLE_INTERVAL_MS 100
#define SLEEP_INTERVAL_MS 10

// ADIS16488A Register Addresses
#define X_GYRO_REG 0x04
#define Y_GYRO_REG 0x06
#define Z_GYRO_REG 0x08
#define X_ACCEL_REG 0x0A
#define Y_ACCEL_REG 0x0C
#define Z_ACCEL_REG 0x0E

// Sensitivity values
#define GYRO_SENSITIVITY 0.005f // deg/sec/LSB
#define ACCEL_SENSITIVITY 0.00025f // g/LSB

// Global variables
static int spi_handle;
static FILE *fp;
static volatile int running = 1;

// Function prototypes
int spi_xfer_word(int handle, uint16_t data);
int read_register(int handle, uint8_t reg_addr);
void read_imu_data(int handle, float *gyro_x, float *gyro_y, float *gyro_z, float *accel_x, float *accel_y, float *accel_z);
void log_data(FILE *fp, long long timestamp, float gyro_x, float gyro_y, float gyro_z, float accel_x, float accel_y, float accel_z);
void cleanup(int signal);

// Function to perform a single SPI transfer
int spi_xfer_word(int handle, uint16_t data) {
    char tx_buf[2];
    char rx_buf[2];

    tx_buf[0] = (data >> 8) & 0xFF; // MSB
    tx_buf[1] = data & 0xFF;      // LSB

    int result = spiXfer(handle, tx_buf, rx_buf, 2);
    if (result != 2) {
        fprintf(stderr, "SPI transfer error: %d\n", result);
        return -1;
    }

    return ((rx_buf[0] << 8) | rx_buf[1]);
}

// Function to read a register from the ADIS16488A
int read_register(int handle, uint8_t reg_addr) {
    uint16_t request = 0x0000 | (reg_addr << 1); // MSB is 0, address in bits 1-7
    spi_xfer_word(handle, request);
    gpioDelay(40); // Stall for 40 microseconds
    return spi_xfer_word(handle, 0x0000); // Dummy read
}

// Function to read IMU data
void read_imu_data(int handle, float *gyro_x, float *gyro_y, float *gyro_z, float *accel_x, float *accel_y, float *accel_z) {
    int16_t raw_gyro_x = read_register(handle, X_GYRO_REG);
    int16_t raw_gyro_y = read_register(handle, Y_GYRO_REG);
    int16_t raw_gyro_z = read_register(handle, Z_GYRO_REG);
    int16_t raw_accel_x = read_register(handle, X_ACCEL_REG);
    int16_t raw_accel_y = read_register(handle, Y_ACCEL_REG);
    int16_t raw_accel_z = read_register(handle, Z_ACCEL_REG);

    *gyro_x = (float)raw_gyro_x * GYRO_SENSITIVITY;
    *gyro_y = (float)raw_gyro_y * GYRO_SENSITIVITY;
    *gyro_z = (float)raw_gyro_z * GYRO_SENSITIVITY;
    *accel_x = (float)raw_accel_x * ACCEL_SENSITIVITY;
    *accel_y = (float)raw_accel_y * ACCEL_SENSITIVITY;
    *accel_z = (float)raw_accel_z * ACCEL_SENSITIVITY;
}

// Function to log data to a CSV file
void log_data(FILE *fp, long long timestamp, float gyro_x, float gyro_y, float gyro_z, float accel_x, float accel_y, float accel_z) {
    fprintf(fp, "%lld,%.6f,%.6f,%.6f,%.6f,%.6f,%.6f\n", timestamp, gyro_x, gyro_y, gyro_z, accel_x, accel_y, accel_z);
    fflush(fp); // Ensure data is written to disk immediately
}

// Cleanup function to be called on program termination
void cleanup(int signal) {
    printf("Cleaning up and exiting...\n");
    running = 0; // Stop the main loop
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    if (fp != NULL) {
        fclose(fp);
    }
    gpioTerminate();
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Open CSV file for logging
    fp = fopen("imu_data.csv", "w");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open imu_data.csv for writing\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Write CSV header
    fprintf(fp, "timestamp,gyro_x,gyro_y,gyro_z,accel_x,accel_y,accel_z\n");

    // Register cleanup function for signal handling
    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);
    atexit(cleanup);

    float gyro_x, gyro_y, gyro_z, accel_x, accel_y, accel_z;
    struct timespec ts;
    long long timestamp;

    // Main loop
    while (running) {
        // Read IMU data
        read_imu_data(spi_handle, &gyro_x, &gyro_y, &gyro_z, &accel_x, &accel_y, &accel_z);

        // Get timestamp
        if (clock_gettime(CLOCK_REALTIME, &ts) == 0) {
            timestamp = (long long)(ts.tv_sec) * 1000 + (long long)(ts.tv_nsec) / 1000000;
        } else {
            fprintf(stderr, "Error getting timestamp\n");
            timestamp = 0; // Or some error value
        }

        // Log data
        log_data(fp, timestamp, gyro_x, gyro_y, gyro_z, accel_x, accel_y, accel_z);

        // Sleep for a short interval to check for signals
        gpioDelay(SLEEP_INTERVAL_MS);
    }

    return 0;
}

