    *accel_y = (float)raw_accel_y * ACCEL_SENSITIVITY;
    *accel_z = (float)raw_accel_z * ACCEL_SENSITIVITY;
}

// Function to log data to a CSV file
void log_data(FILE *fp, long long timestamp, float gyro_x, float gyro_y, float gyro_z, float accel_x, float accel_y, float accel_z) {
    fprintf(fp, "%lld,%.6f,%.6f,%.6f,%.6f,%.6f,%.6f\n", timestamp, gyro_x, gyro_y, gyro_z, accel_x, accel_y, accel_z);
    fflush(fp); // Ensure data is written to disk immediately
}

// Cleanup function to be called on program termination
void cleanup(int signal) {
    printf("Cleaning up and exiting...\n");
    running = 0; // Stop the main loop
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    if (fp != NULL) {
        fclose(fp);
    }
    gpioTerminate();
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Open CSV file for logging
    fp = fopen("imu_data.csv", "w");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open imu_data.csv for writing\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Write CSV header
    fprintf(fp, "timestamp,gyro_x,gyro_y,gyro_z,accel_x,accel_y,accel_z\n");

    // Register cleanup function for signal handling
    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);
    atexit(cleanup);

    float gyro_x, gyro_y, gyro_z, accel_x, accel_y, accel_z;
    struct timespec ts;
    long long timestamp;

    // Main loop
    while (running) {
        // Read IMU data
        read_imu_data(spi_handle, &gyro_x, &gyro_y, &gyro_z, &accel_x, &accel_y, &accel_z);

        // Get timestamp
        if (clock_gettime(CLOCK_REALTIME, &ts) == 0) {
            timestamp = (long long)(ts.tv_sec) * 1000 + (long long)(ts.tv_nsec) / 1000000;
        } else {
            fprintf(stderr, "Error getting timestamp\n");
            timestamp = 0; // Or some error value
        }

        // Log data
        log_data(fp, timestamp, gyro_x, gyro_y, gyro_z, accel_x, accel_y, accel_z);

        // Sleep for a short interval to check for signals
        gpioDelay(SLEEP_INTERVAL_MS);
    }

    return 0;
}

