// SPI transfer function
int spi_transfer(int spi_handle, uint8_t reg_addr, uint16_t *data) {
    char tx_buf[3];
    char rx_buf[3];

    // Construct the transmit buffer: register address (MSB=1) + dummy byte + dummy byte
    tx_buf[0] = 0x80 | reg_addr; // Set MSB to 1 for read
    tx_buf[1] = 0x00;
    tx_buf[2] = 0x00;

