    while (running) {
        // Read IMU data
        if (read_gyro_data(spi_handle, &gyro_x, &gyro_y, &gyro_z) != 0) {
            fprintf(stderr, "Error reading gyro data\n");
        }
        if (read_accel_data(spi_handle, &accel_x, &accel_y, &accel_z) != 0) {
            fprintf(stderr, "Error reading accel data\n");
        }

        // Print the data
