#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>
#include <linux/i2c-dev.h>
#include <sys/ioctl.h>
#include <fcntl.h>

// Constants
#define I2C_BUS 1
#define MMA8451Q_ADDR 0x1D
#define WHO_AM_I_REG 0x0D
#define WHO_AM_I_VALUE 0x1A
#define CTRL_REG1 0x2A
#define CTRL_REG2 0x2B
#define OUT_X_MSB 0x01
#define OUT_X_LSB 0x02
#define OUT_Y_MSB 0x03
#define OUT_Y_LSB 0x04
#define OUT_Z_MSB 0x05
#define OUT_Z_LSB 0x06
#define LED_GPIO 17
#define ACCEL_THRESHOLD 2.0f
#define LED_ON_TIME_MS 500
#define SAMPLE_RATE_MS 100

// Global variables
int i2c_fd;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int init_gpio();
int init_mma8451q();
int read_mma8451q(float *x, float *y, float *z);
float calculate_magnitude(float x, float y, float z);
void log_impact(float x, float y, float z);
void signal_handler(int signal);
void cleanup();

// Signal handler
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

// Initialize I2C
int init_i2c() {
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Error opening I2C bus");
        return -1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, MMA8451Q_ADDR) < 0) {
        perror("Error setting I2C slave address");
        close(i2c_fd);
        return -1;
    }

    return 0;
}

// Initialize GPIO
int init_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(LED_GPIO, PI_OUTPUT);
    gpioWrite(LED_GPIO, 0); // Initially off
    return 0;
}

// Initialize MMA8451Q
int init_mma8451q() {
    uint8_t who_am_i;

    // Set to active mode and 800 Hz ODR
    if (i2cWriteByteData(i2c_fd, CTRL_REG1, 0x01) < 0) {
        perror("Error writing to CTRL_REG1");
        return -1;
    }

    // Set to +-2g range
    if (i2cWriteByteData(i2c_fd, CTRL_REG2, 0x00) < 0) {
        perror("Error writing to CTRL_REG2");
        return -1;
    }

    // Verify WHO_AM_I register
    who_am_i = i2cReadByteData(i2c_fd, WHO_AM_I_REG);
    if (who_am_i < 0) {
        perror("Error reading WHO_AM_I register");
        return -1;
    }

    if (who_am_i != WHO_AM_I_VALUE) {
        fprintf(stderr, "Error: WHO_AM_I register returned 0x%02X, expected 0x%02X\n", who_am_i, WHO_AM_I_VALUE);
        return -1;
    }

    printf("MMA8451Q initialized successfully\n");
    return 0;
}

// Read acceleration data from MMA8451Q
int read_mma8451q(float *x, float *y, float *z) {
    int16_t raw_x, raw_y, raw_z;
    uint8_t x_msb, x_lsb, y_msb, y_lsb, z_msb, z_lsb;

    x_msb = i2cReadByteData(i2c_fd, OUT_X_MSB);
    x_lsb = i2cReadByteData(i2c_fd, OUT_X_LSB);
    y_msb = i2cReadByteData(i2c_fd, OUT_Y_MSB);
    y_lsb = i2cReadByteData(i2c_fd, OUT_Y_LSB);
    z_msb = i2cReadByteData(i2c_fd, OUT_Z_MSB);
    z_lsb = i2cReadByteData(i2c_fd, OUT_Z_LSB);

    if (x_msb < 0 || x_lsb < 0 || y_msb < 0 || y_lsb < 0 || z_msb < 0 || z_lsb < 0) {
        perror("Error reading acceleration data");
        return -1;
    }

    raw_x = (int16_t)((x_msb << 8) | x_lsb);
    raw_y = (int16_t)((y_msb << 8) | y_lsb);
    raw_z = (int16_t)((z_msb << 8) | z_lsb);

    *x = (float)raw_x / 1024.0f;
    *y = (float)raw_y / 1024.0f;
    *z = (float)raw_z / 1024.0f;

    return 0;
}

// Calculate acceleration magnitude
float calculate_magnitude(float x, float y, float z) {
    return sqrtf(x * x + y * y + z * z);
}

// Log impact event
void log_impact(float x, float y, float z) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s - Impact detected: X=%.2f g, Y=%.2f g, Z=%.2f g\n", timestamp, x, y, z);
    fflush(log_file); // Ensure data is written to file immediately
}

// Cleanup resources
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_fd > 0) {
        close(i2c_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioWrite(LED_GPIO, 0); // Turn off LED
    gpioTerminate();
}

int main() {
    float x, y, z, magnitude;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() < 0) {
        return 1;
    }

    // Initialize GPIO
    if (init_gpio() < 0) {
        cleanup();
        return 1;
    }

    // Initialize MMA8451Q
    if (init_mma8451q() < 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen("impact_log.txt", "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        cleanup();
        return 1;
    }

    printf("Monitoring acceleration... Press Ctrl+C to exit.\n");

    while (!terminate) {
        // Read acceleration data
        if (read_mma8451q(&x, &y, &z) == 0) {
            // Calculate magnitude
            magnitude = calculate_magnitude(x, y, z);

            // Check for impact
            if (magnitude > ACCEL_THRESHOLD) {
                printf("Impact detected! Magnitude: %.2f g\n", magnitude);
                log_impact(x, y, z);
                gpioWrite(LED_GPIO, 1); // Turn on LED
                gpioDelay(LED_ON_TIME_MS * 1000); // Delay for 500ms
                gpioWrite(LED_GPIO, 0); // Turn off LED
            }
        } else {
            fprintf(stderr, "Error reading sensor data. Retrying...\n");
        }

        gpioDelay(SAMPLE_RATE_MS * 1000); // Delay for 100ms
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

