#include <linux/i2c-dev.h>

// Constants
#define I2C_BUS "/dev/i2c-1" // I2C bus on Raspberry Pi 3 Model B+
#define TMAG5273_ADDR 0x35
#define X_REG 0x10
#define Y_REG 0x11
#define Z_REG 0x12
#define SAMPLE_RATE_SEC 1

// Global variables
static int i2c_fd = -1; // I2C file descriptor
static FILE *log_file = NULL; // Log file pointer
static volatile sig_atomic_t terminate = 0; // Termination flag

// Structure to hold sensor data
typedef struct {
    int16_t x;
    int16_t y;
    int16_t z;
} sensor_data_t;

// Function prototypes
int i2c_setup(const char *bus, int addr);
int read_sensor_data(int fd, sensor_data_t *data);
int log_data(FILE *fp, sensor_data_t data);
void signal_handler(int sig);

// Signal handler function
void signal_handler(int sig) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating...\n", sig);
}

// I2C setup function
int i2c_setup(const char *bus, int addr) {
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening I2C bus %s: %s\n", bus, strerror(errno));
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        fprintf(stderr, "Error setting I2C slave address 0x%02x: %s\n", addr, strerror(errno));
        close(fd);
        return -1;
    }

    return fd;
}

// Function to read sensor data
int read_sensor_data(int fd, sensor_data_t *data) {
    uint8_t buf[6];
    ssize_t bytes_read;

    // Read X, Y, and Z registers (6 bytes total)
    bytes_read = read(fd, buf, 6);
    if (bytes_read != 6) {
        fprintf(stderr, "Error reading sensor data: %s (read %zd bytes)\n", strerror(errno), bytes_read);
        return -1;
    }

    // Combine bytes to form 16-bit little-endian values
    data->x = (int16_t)((buf[1] << 8) | buf[0]);
    data->y = (int16_t)((buf[3] << 8) | buf[2]);
    data->z = (int16_t)((buf[5] << 8) | buf[4]);

    return 0;
}

// Function to log data to CSV file
int log_data(FILE *fp, sensor_data_t data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (fprintf(fp, "%s,%d,%d,%d\n", timestamp, data.x, data.y, data.z) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        return -1;
    }

    fflush(fp); // Ensure data is written to disk immediately
    return 0;
}

int main() {
    sensor_data_t sensor_data;

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    i2c_fd = i2c_setup(I2C_BUS, TMAG5273_ADDR);
    if (i2c_fd < 0) {
        return EXIT_FAILURE;
    }

    // Open log file
    log_file = fopen("magnetic_field_log.csv", "a+");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Check if the file is empty and write the header if needed
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,X,Y,Z\n");
    }
    fseek(log_file, 0, SEEK_END); // Reset file pointer to the end

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_sensor_data(i2c_fd, &sensor_data) == 0) {
            // Log data
            if (log_data(log_file, sensor_data) != 0) {
                fprintf(stderr, "Error logging data.\n");
            }
        } else {
            fprintf(stderr, "Error reading sensor data.\n");
        }

        // Wait for the next sample
        sleep(SAMPLE_RATE_SEC);
    }

    // Cleanup
    close(i2c_fd);
    fclose(log_file);

    return EXIT_SUCCESS;
}

