#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>
#include <math.h>

// ADXL345 I2C address
#define ADXL345_ADDRESS 0x53

// ADXL345 registers
#define ADXL345_REG_DEVID 0x00
#define ADXL345_REG_THRESH_FF 0x0A
#define ADXL345_REG_TIME_FF 0x20
#define ADXL345_REG_INT_ENABLE 0x2E
#define ADXL345_REG_INT_MAP 0x2F
#define ADXL345_REG_POWER_CTL 0x2D
#define ADXL345_REG_INT_SOURCE 0x30
#define ADXL345_REG_DATAX0 0x32

// GPIO pin for interrupt
#define GPIO_PIN 17

// Global variables
static int i2c_fd = -1;
static struct gpiod_chip *gpio_chip = NULL;
static struct gpiod_line *gpio_line = NULL;
static int event_fd = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int i2c_write_byte(int fd, uint8_t reg, uint8_t value);
int i2c_read_byte(int fd, uint8_t reg, uint8_t *value);
int i2c_read_bytes(int fd, uint8_t reg, uint8_t *values, int len);
int adxl345_init(int fd);
int adxl345_read_acceleration(int fd, int16_t *x, int16_t *y, int16_t *z);
int gpio_init(int pin);
int gpio_enable_interrupt(int pin);
int gpio_disable_interrupt(int pin);
void interrupt_handler(int fd, struct gpiod_line *line, struct gpiod_line_event *event);
void log_data(FILE *fp, int16_t x, int16_t y, int16_t z);
void signal_handler(int sig);

// I2C write byte function
int i2c_write_byte(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2];
    buf[0] = reg;
    buf[1] = value;
    if (write(fd, buf, 2) != 2) {
        perror("I2C write failed");
        return -1;
    }
    return 0;
}

// I2C read byte function
int i2c_read_byte(int fd, uint8_t reg, uint8_t *value) {
    if (write(fd, &reg, 1) != 1) {
        perror("I2C write (address) failed");
        return -1;
    }
    if (read(fd, value, 1) != 1) {
        perror("I2C read failed");
        return -1;
    }
    return 0;
}

// I2C read bytes function
int i2c_read_bytes(int fd, uint8_t reg, uint8_t *values, int len) {
    if (write(fd, &reg, 1) != 1) {
        perror("I2C write (address) failed");
        return -1;
    }
    if (read(fd, values, len) != len) {
        perror("I2C read failed");
        return -1;
    }
    return 0;
}

// ADXL345 initialization function
int adxl345_init(int fd) {
    uint8_t devid;
    int16_t x, y, z;

    // Verify device ID
    if (i2c_read_byte(fd, ADXL345_REG_DEVID, &devid) != 0) {
        fprintf(stderr, "Error reading device ID\n");
        return -1;
    }
    if (devid != 0xE5) {
        fprintf(stderr, "Incorrect device ID: 0x%02X\n", devid);
        return -1;
    }

    // Set freefall threshold
    if (i2c_write_byte(fd, ADXL345_REG_THRESH_FF, 0x27) != 0) { // ~300 mg
        fprintf(stderr, "Error setting freefall threshold\n");
        return -1;
    }

    // Set freefall time
    if (i2c_write_byte(fd, ADXL345_REG_TIME_FF, 0x90) != 0) { // ~100 ms
        fprintf(stderr, "Error setting freefall time\n");
        return -1;
    }

    // Enable freefall interrupt
    if (i2c_write_byte(fd, ADXL345_REG_INT_ENABLE, 0x08) != 0) { // Enable freefall interrupt
        fprintf(stderr, "Error enabling freefall interrupt\n");
        return -1;
    }

    // Map freefall interrupt to INT1
    if (i2c_write_byte(fd, ADXL345_REG_INT_MAP, 0x00) != 0) { // Map to INT1
        fprintf(stderr, "Error mapping freefall interrupt\n");
        return -1;
    }

    // Enter measurement mode
    if (i2c_write_byte(fd, ADXL345_REG_POWER_CTL, 0x08) != 0) { // Measurement mode
        fprintf(stderr, "Error entering measurement mode\n");
        return -1;
    }

    // Read initial acceleration values
    if (adxl345_read_acceleration(fd, &x, &y, &z) != 0) {
        fprintf(stderr, "Error reading initial acceleration\n");
        return -1;
    }

    printf("ADXL345 initialized successfully\n");
    return 0;
}

// ADXL345 read acceleration function
int adxl345_read_acceleration(int fd, int16_t *x, int16_t *y, int16_t *z) {
    uint8_t data[6];

    if (i2c_read_bytes(fd, ADXL345_REG_DATAX0, data, 6) != 0) {
        fprintf(stderr, "Error reading acceleration data\n");
        return -1;
    }

    *x = (int16_t)((data[1] << 8) | data[0]);
    *y = (int16_t)((data[3] << 8) | data[2]);
    *z = (int16_t)((data[5] << 8) | data[4]);

    return 0;
}

// GPIO initialization function
int gpio_init(int pin) {
    struct gpiod_line_request_config config;

    gpio_chip = gpiod_chip_open_by_name("gpiochip0");
    if (!gpio_chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    gpio_line = gpiod_chip_get_line(gpio_chip, pin);
    if (!gpio_line) {
        perror("Error getting GPIO line");
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    memset(&config, 0, sizeof(config));
    config.consumer = "adxl345_interrupt";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT;

    if (gpiod_line_request(gpio_line, &config, 0) != 0) {
        perror("Error requesting GPIO line");
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    return 0;
}

// GPIO enable interrupt function
int gpio_enable_interrupt(int pin) {
    struct gpiod_line_event_config config;

    memset(&config, 0, sizeof(config));
    config.event_type = GPIOD_LINE_EVENT_FALLING_EDGE;

    event_fd = gpiod_line_get_event_fd(gpio_line);
    if (event_fd < 0) {
        perror("Error getting event file descriptor");
        return -1;
    }

    if (gpiod_line_request_event(gpio_line, &config) != 0) {
        perror("Error requesting event");
        close(event_fd);
        return -1;
    }

    return 0;
}

// GPIO disable interrupt function
int gpio_disable_interrupt(int pin) {
    if (gpiod_line_release_event(gpio_line) != 0) {
        perror("Error releasing event");
        return -1;
    }
    close(event_fd);
    return 0;
}

// Interrupt handler function
void interrupt_handler(int fd, struct gpiod_line *line, struct gpiod_line_event *event) {
    uint8_t int_source;
    int16_t x, y, z;
    struct timespec ts;
    char timestamp[30];

    // Read interrupt source register
    if (i2c_read_byte(i2c_fd, ADXL345_REG_INT_SOURCE, &int_source) != 0) {
        fprintf(stderr, "Error reading interrupt source\n");
        return;
    }

    // Check if freefall interrupt is set
    if (int_source & 0x08) {
        // Read acceleration data
        if (adxl345_read_acceleration(i2c_fd, &x, &y, &z) == 0) {
            // Get timestamp
            clock_gettime(CLOCK_REALTIME, &ts);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&ts.tv_sec));
            snprintf(timestamp + strlen(timestamp), sizeof(timestamp) - strlen(timestamp), ".%03ld", ts.tv_nsec / 1000000);

            // Log data
            log_data(log_file, x, y, z);
        } else {
            fprintf(stderr, "Error reading acceleration data in interrupt handler\n");
        }
    }
}

// Log data function
void log_data(FILE *fp, int16_t x, int16_t y, int16_t z) {
    if (fp == NULL) {
        fprintf(stderr, "Log file is not open\n");
        return;
    }

    fprintf(fp, "%d,%d,%d\n", x, y, z);
    fflush(fp);
}

// Signal handler function
void signal_handler(int sig) {
    printf("Signal received, cleaning up...\n");
    terminate = 1;

    // Disable interrupts
    if (i2c_write_byte(i2c_fd, ADXL345_REG_INT_ENABLE, 0x00) != 0) {
        fprintf(stderr, "Error disabling interrupts\n");
    }

    // Close I2C file descriptor
    if (i2c_fd != -1) {
        close(i2c_fd);
    }

    // Release GPIO line
    if (gpio_line) {
        gpiod_line_release(gpio_line);
        gpiod_chip_close(gpio_chip);
    }

    // Close log file
    if (log_file) {
        fclose(log_file);
    }

    exit(0);
}

int main() {
    struct pollfd pfd;
    int ret;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C device
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Error opening I2C device");
        return 1;
    }

    // Specify slave address
    if (ioctl(i2c_fd, I2C_SLAVE, ADXL345_ADDRESS) < 0) {
        perror("Error setting I2C slave address");
        close(i2c_fd);
        return 1;
    }

    // Initialize ADXL345
    if (adxl345_init(i2c_fd) != 0) {
        fprintf(stderr, "ADXL345 initialization failed\n");
        close(i2c_fd);
        return 1;
    }

    // Initialize GPIO
    if (gpio_init(GPIO_PIN) != 0) {
        fprintf(stderr, "GPIO initialization failed\n");
        close(i2c_fd);
        return 1;
    }

    // Enable interrupt
    if (gpio_enable_interrupt(GPIO_PIN) != 0) {
        fprintf(stderr, "GPIO interrupt enable failed\n");
        close(i2c_fd);
        gpiod_chip_close(gpio_chip);
        return 1;
    }

    // Open log file
    log_file = fopen("freefall_log.csv", "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        close(i2c_fd);
        gpiod_chip_close(gpio_chip);
        return 1;
    }

    // Write header row if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,X,Y,Z\n");
    }
    fflush(log_file);

    // Set up pollfd for interrupt handling
    pfd.fd = event_fd;
    pfd.events = POLLPRI | POLLERR;

    // Main loop
    while (!terminate) {
        ret = poll(&pfd, 1, -1); // Wait indefinitely for an interrupt

        if (ret < 0) {
            perror("Poll failed");
            break;
        }

        if (ret > 0) {
            if (pfd.revents & POLLPRI) {
                // Handle interrupt
                interrupt_handler(i2c_fd, gpio_line, NULL); // event is not used in this implementation
                lseek(event_fd, 0, SEEK_SET); // Reset file pointer to read the next interrupt
            } else if (pfd.revents & POLLERR) {
                fprintf(stderr, "Error on GPIO line\n");
                break;
            }
        }
    }

    // Cleanup (should not reach here if signal handler is working)
    gpio_disable_interrupt(GPIO_PIN);
    close(i2c_fd);
    gpiod_chip_close(gpio_chip);
    fclose(log_file);

    return 0;
}

