#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <math.h>
#include <string.h>

// LSM6DSR I2C address
#define LSM6DSR_ADDR 0x6A

// LSM6DSR register addresses
#define LSM6DSR_WHO_AM_I 0x0F
#define LSM6DSR_CTRL1_XL 0x10
#define LSM6DSR_CTRL2_G 0x11
#define LSM6DSR_OUTX_L_G 0x22
#define LSM6DSR_OUTX_L_XL 0x28

// Accelerometer and Gyroscope ranges
#define ACCEL_RANGE 2.0f  // +-2g
#define GYRO_RANGE 250.0f // +-250 dps

// ODR (Output Data Rate)
#define ODR 104 // Hz

// Fall detection thresholds
#define FREEFALL_THRESHOLD 0.2f // g
#define IMPACT_THRESHOLD 2.5f  // g
#define FREEFALL_WINDOW 0.5f   // seconds
#define IMPACT_WINDOW 0.5f    // seconds

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float accel_x, accel_y, accel_z;
    float gyro_x, gyro_y, gyro_z;
} sensor_data_t;

// Function prototypes
int init_i2c();
int config_lsm6dsr();
int read_sensor_data(sensor_data_t *data);
float calculate_acceleration_magnitude(sensor_data_t data);
void log_data(sensor_data_t data);
void fall_detection(sensor_data_t data);
void signal_handler(int signal);
int check_who_am_i();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(1, LSM6DSR_ADDR, 0); // I2C bus 1, address 0x6A, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Configure the LSM6DSR
int config_lsm6dsr() {
    // Configure accelerometer: +-2g, 104 Hz ODR
    if (i2cWriteByteData(i2c_handle, LSM6DSR_CTRL1_XL, 0x84) < 0) { // 0x84 = 0b10000100 (FS_XL = 01, ODR_XL = 100)
        fprintf(stderr, "Error writing to CTRL1_XL\n");
        return -1;
    }

    // Configure gyroscope: +-250 dps, 104 Hz ODR
    if (i2cWriteByteData(i2c_handle, LSM6DSR_CTRL2_G, 0x84) < 0) { // 0x84 = 0b10000100 (FS_G = 01, ODR_G = 100)
        fprintf(stderr, "Error writing to CTRL2_G\n");
        return -1;
    }

    return 0;
}

// Read sensor data from the LSM6DSR
int read_sensor_data(sensor_data_t *data) {
    char buffer[12];

    // Read accelerometer data (6 bytes)
    if (i2cReadI2CBlockData(i2c_handle, LSM6DSR_OUTX_L_XL, buffer, 6) < 0) {
        fprintf(stderr, "Error reading accelerometer data\n");
        return -1;
    }

    // Read gyroscope data (6 bytes)
    if (i2cReadI2CBlockData(i2c_handle, LSM6DSR_OUTX_L_G, buffer + 6, 6) < 0) {
        fprintf(stderr, "Error reading gyroscope data\n");
        return -1;
    }

    // Convert raw data to g and dps
    int16_t raw_accel_x = (int16_t)((buffer[1] << 8) | buffer[0]);
    int16_t raw_accel_y = (int16_t)((buffer[3] << 8) | buffer[2]);
    int16_t raw_accel_z = (int16_t)((buffer[5] << 8) | buffer[4]);
    int16_t raw_gyro_x = (int16_t)((buffer[7] << 8) | buffer[6]);
    int16_t raw_gyro_y = (int16_t)((buffer[9] << 8) | buffer[8]);
    int16_t raw_gyro_z = (int16_t)((buffer[11] << 8) | buffer[10]);

    data->accel_x = (float)raw_accel_x / 16384.0f * ACCEL_RANGE; // 16384 LSB/g for +-2g
    data->accel_y = (float)raw_accel_y / 16384.0f * ACCEL_RANGE;
    data->accel_z = (float)raw_accel_z / 16384.0f * ACCEL_RANGE;
    data->gyro_x = (float)raw_gyro_x / 131.0f * GYRO_RANGE;    // 131 LSB/dps for +-250 dps
    data->gyro_y = (float)raw_gyro_y / 131.0f * GYRO_RANGE;
    data->gyro_z = (float)raw_gyro_z / 131.0f * GYRO_RANGE;

    return 0;
}

// Calculate the magnitude of the acceleration vector
float calculate_acceleration_magnitude(sensor_data_t data) {
    return sqrt(data.accel_x * data.accel_x + data.accel_y * data.accel_y + data.accel_z * data.accel_z);
}

// Log sensor data to a CSV file
void log_data(sensor_data_t data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.3f,%.3f,%.3f,%.3f,%.3f,%.3f\n",
            timestamp, data.accel_x, data.accel_y, data.accel_z, data.gyro_x, data.gyro_y, data.gyro_z);
    fflush(log_file); // Ensure data is written to file immediately
}

// Fall detection state machine
void fall_detection(sensor_data_t data) {
    static int freefall_state = 0;
    static int impact_state = 0;
    static time_t freefall_start_time = 0;
    static time_t impact_start_time = 0;

    float magnitude = calculate_acceleration_magnitude(data);

    if (magnitude < FREEFALL_THRESHOLD) {
        if (freefall_state == 0) {
            freefall_state = 1;
            freefall_start_time = time(NULL);
            printf("Freefall detected!\n");
        } else {
            // Check if freefall window has elapsed
            if (difftime(time(NULL), freefall_start_time) >= FREEFALL_WINDOW) {
                freefall_state = 2; // Freefall confirmed
                printf("Freefall confirmed!\n");
            }
        }
    } else {
        freefall_state = 0; // Reset freefall state
    }

    if (freefall_state == 2 && magnitude > IMPACT_THRESHOLD) {
        if (impact_state == 0) {
            impact_state = 1;
            impact_start_time = time(NULL);
            printf("Impact detected!\n");
        } else {
            // Check if impact window has elapsed
            if (difftime(time(NULL), impact_start_time) >= IMPACT_WINDOW) {
                impact_state = 2; // Impact confirmed
                printf("Impact confirmed!\n");
            }
        }
    } else {
        impact_state = 0; // Reset impact state
    }
}

// Check WHO_AM_I register
int check_who_am_i() {
    int who_am_i = i2cReadByteData(i2c_handle, LSM6DSR_WHO_AM_I);
    if (who_am_i < 0) {
        fprintf(stderr, "Error reading WHO_AM_I register\n");
        return -1;
    }
    if (who_am_i != 0x69) {
        fprintf(stderr, "WHO_AM_I check failed! Expected 0x69, got 0x%x\n", who_am_i);
        return -1;
    }
    printf("WHO_AM_I check passed!\n");
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Check WHO_AM_I register
    if (check_who_am_i() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Configure LSM6DSR
    if (config_lsm6dsr() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("motion_log.txt", "w");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    fprintf(log_file, "Timestamp,Accel_X,Accel_Y,Accel_Z,Gyro_X,Gyro_Y,Gyro_Z\n"); // CSV header

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    sensor_data_t sensor_data;

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_sensor_data(&sensor_data) == 0) {
            // Log data
            log_data(sensor_data);

            // Fall detection
            fall_detection(sensor_data);
        } else {
            fprintf(stderr, "Error reading sensor data, retrying...\n");
        }

        // Delay for approximately 104 Hz (1000000 / 104 = 9615.384615384615)
        gpioDelay(9615); // Delay in microseconds
    }

    // Clean up
    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

