    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// SPI Read Register Function
int spi_read_register(int handle, uint8_t address, uint16_t *data) {
    char tx_buf[2];
    char rx_buf[2];

    tx_buf[0] = address | 0x80; // Set read bit (MSB)
    tx_buf[1] = 0x00; // Dummy byte

    if (spiXfer(handle, tx_buf, rx_buf, 2) != 2) {
        fprintf(stderr, "SPI read error\n");
        return -1;
    }

    *data = (rx_buf[0] << 8) | rx_buf[1];
    return 0;
}

// SPI Write Register Function
int spi_write_register(int handle, uint8_t address, uint16_t data) {
    char tx_buf[2];
    char rx_buf[2];

    tx_buf[0] = address & 0x7F; // Clear read bit (MSB)
    tx_buf[1] = data & 0xFF; // LSB

    if (spiXfer(handle, tx_buf, rx_buf, 2) != 2) {
        fprintf(stderr, "SPI write error\n");
        return -1;
    }

    return 0;
}

