#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Constants
#define I2C_BUS 1
#define GYRO_ADDR 0x69
#define WHO_AM_I_REG 0x0F
#define WHO_AM_I_VALUE 0xD3
#define CTRL_REG1 0x20
#define CTRL_REG4 0x23
#define OUT_X_L 0x28
#define OUT_X_H 0x29
#define OUT_Y_L 0x2A
#define OUT_Y_H 0x2B
#define OUT_Z_L 0x2C
#define OUT_Z_H 0x2D
#define SENSITIVITY 8.75 // mdps/LSB
#define SAMPLE_RATE_MS 10
#define RETRY_COUNT 3

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold gyroscope data
typedef struct {
    int16_t x;
    int16_t y;
    int16_t z;
} gyro_data_t;

// Function prototypes
int init_gyro();
gyro_data_t read_gyro_data();
void convert_to_dps(gyro_data_t raw_data, float *x_dps, float *y_dps, float *z_dps);
void log_data(float x_dps, float y_dps, float z_dps);
void signal_handler(int signal);

// Signal handler for graceful termination
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Initialize the gyroscope
int init_gyro() {
    int retries = 0;
    while (retries < RETRY_COUNT) {
        // Open I2C bus
        i2c_handle = i2cOpen(I2C_BUS, GYRO_ADDR, 0);
        if (i2c_handle < 0) {
            fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
            retries++;
            gpioDelay(1000000); // Wait 1 second before retrying
            continue;
        }

        // Verify WHO_AM_I register
        int who_am_i = i2cReadByteData(i2c_handle, WHO_AM_I_REG);
        if (who_am_i < 0) {
            fprintf(stderr, "Error reading WHO_AM_I register: %d\n", who_am_i);
            i2cClose(i2c_handle);
            retries++;
            gpioDelay(1000000); // Wait 1 second before retrying
            continue;
        }

        if (who_am_i != WHO_AM_I_VALUE) {
            fprintf(stderr, "WHO_AM_I value incorrect: 0x%02X (expected 0x%02X)\n", who_am_i, WHO_AM_I_VALUE);
            i2cClose(i2c_handle);
            retries++;
            gpioDelay(1000000); // Wait 1 second before retrying
            continue;
        }

        // Configure CTRL_REG1
        int status = i2cWriteByteData(i2c_handle, CTRL_REG1, 0x0F); // Normal mode, all axes enabled
        if (status < 0) {
            fprintf(stderr, "Error writing to CTRL_REG1: %d\n", status);
            i2cClose(i2c_handle);
            retries++;
            gpioDelay(1000000); // Wait 1 second before retrying
            continue;
        }

        // Configure CTRL_REG4
        status = i2cWriteByteData(i2c_handle, CTRL_REG4, 0x00); // +-250 dps full-scale range
        if (status < 0) {
            fprintf(stderr, "Error writing to CTRL_REG4: %d\n", status);
            i2cClose(i2c_handle);
            retries++;
            gpioDelay(1000000); // Wait 1 second before retrying
            continue;
        }

        printf("Gyroscope initialized successfully.\n");
        return 0; // Success
    }

    fprintf(stderr, "Failed to initialize gyroscope after %d retries.\n", RETRY_COUNT);
    return -1; // Failure
}

// Read raw gyroscope data
gyro_data_t read_gyro_data() {
    char buffer[6];
    gyro_data_t data;
    int status = i2cReadI2CBlockData(i2c_handle, OUT_X_L | 0x80, buffer, 6); // Enable auto-increment

    if (status < 0) {
        fprintf(stderr, "Error reading gyroscope data: %d\n", status);
        data.x = 0; // Return 0 to avoid further issues
        data.y = 0;
        data.z = 0;
        return data;
    }

    // Combine high and low bytes for each axis
    data.x = (int16_t)((buffer[1] << 8) | buffer[0]);
    data.y = (int16_t)((buffer[3] << 8) | buffer[2]);
    data.z = (int16_t)((buffer[5] << 8) | buffer[4]);

    return data;
}

// Convert raw data to degrees per second
void convert_to_dps(gyro_data_t raw_data, float *x_dps, float *y_dps, float *z_dps) {
    *x_dps = (float)raw_data.x / SENSITIVITY;
    *y_dps = (float)raw_data.y / SENSITIVITY;
    *z_dps = (float)raw_data.z / SENSITIVITY;
}

// Log data to file
void log_data(float x_dps, float y_dps, float z_dps) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    long long timestamp_ns = (long long)ts.tv_sec * 1000000000LL + ts.tv_nsec;

    fprintf(log_file, "%lld,%.3f,%.3f,%.3f\n", timestamp_ns, x_dps, y_dps, z_dps);
    fflush(log_file); // Ensure data is written to disk immediately
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handling for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize the gyroscope
    if (init_gyro() != 0) {
        fprintf(stderr, "Gyroscope initialization failed. Exiting.\n");
        gpioTerminate();
        return 1;
    }

    // Open the log file
    log_file = fopen("gyro_log.csv", "w");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Write the header row
    fprintf(log_file, "Timestamp,X,Y,Z\n");

    // Main loop
    while (!terminate) {
        // Read gyroscope data
        gyro_data_t raw_data = read_gyro_data();

        // Convert to degrees per second
        float x_dps, y_dps, z_dps;
        convert_to_dps(raw_data, &x_dps, &y_dps, &z_dps);

        // Log the data
        log_data(x_dps, y_dps, z_dps);

        // Delay for 10 ms
        gpioDelay(SAMPLE_RATE_MS * 1000); // pigpioDelay takes microseconds
    }

    // Clean up
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    printf("Program terminated.\n");
    return 0;
}

