        return 1;
    }

    // Set GPIO17 as input with pull-up resistor
    gpioSetMode(FLAME_SENSOR_GPIO, PI_INPUT);
    gpioSetPullUpDown(FLAME_SENSOR_GPIO, PI_PUD_UP);

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Flame sensor monitoring started. Press Ctrl+C to exit.\n");

    while (program_running) {
        // Read sensor value
        sensor_value = gpioRead(FLAME_SENSOR_GPIO);

        if (sensor_value == PI_BAD_GPIO) {
            fprintf(stderr, "Error reading GPIO %d\n", FLAME_SENSOR_GPIO);
            fprintf(log_file, "Error reading GPIO %d\n", FLAME_SENSOR_GPIO);
            fflush(log_file);
        } else {
            // Get current timestamp
            time(&rawtime);
            timeinfo = localtime(&rawtime);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

            // Log event to file
            fprintf(log_file, "%s - Flame detected: %s\n", timestamp, (sensor_value == 0) ? "YES" : "NO");
            fflush(log_file);

            // Check for flame detection and print alarm
            if (sensor_value == 0) {
                printf("FLAME DETECTED!\n");
            }
        }

        gpioDelay(500); // Poll every 500 ms
    }

    // Clean up
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();

    printf("Program terminated.\n");
    return 0;
}

