// Structure to hold acceleration data
typedef struct {
    int16_t x;
    int16_t y;
    int16_t z;
} AccelerationData;

// Global variables
int i2c_fd = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int i2c_setup(const char *bus, int addr);
AccelerationData read_acceleration_data(int fd);
AccelerationData process_acceleration_data(AccelerationData raw_data);
char *get_iso8601_timestamp(char *timestamp_str, size_t timestamp_str_size);
int log_data(FILE *fp, const char *timestamp, int16_t x, int16_t y, int16_t z);
void signal_handler(int sig);

// I2C setup function
int i2c_setup(const char *bus, int addr) {
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening I2C bus %s: %s\n", bus, strerror(errno));
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        fprintf(stderr, "Error setting I2C slave address 0x%02X: %s\n", addr, strerror(errno));
        close(fd);
        return -1;
    }

    return fd;
}

// Function to read acceleration data from the sensor
AccelerationData read_acceleration_data(int fd) {
    AccelerationData data;
    uint8_t buffer[6];

    if (read(fd, buffer, 6) != 6) {
        fprintf(stderr, "Error reading from I2C device: %s\n", strerror(errno));
        data.x = 0; // Indicate error
        data.y = 0;
        data.z = 0;
        return data;
    }

    data.x = (int16_t)((buffer[1] << 8) | buffer[0]);
    data.y = (int16_t)((buffer[3] << 8) | buffer[2]);
    data.z = (int16_t)((buffer[5] << 8) | buffer[4]);

    return data;
}

// Function to process acceleration data (convert to g's, apply calibration)
AccelerationData process_acceleration_data(AccelerationData raw_data) {
    // Placeholder for calibration and unit conversion
    // Replace with actual calibration values and conversion factors
    AccelerationData processed_data;
    processed_data.x = raw_data.x; // Assuming raw data is already in g's
    processed_data.y = raw_data.y;
    processed_data.z = raw_data.z;
    return processed_data;
}

// Function to get the current timestamp in ISO-8601 format
char *get_iso8601_timestamp(char *timestamp_str, size_t timestamp_str_size) {
    time_t rawtime;
    struct tm *timeinfo;

    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    strftime(timestamp_str, timestamp_str_size, "%Y-%m-%dT%H:%M:%SZ", timeinfo);
    return timestamp_str;
}

// Function to log data to a CSV file
int log_data(FILE *fp, const char *timestamp, int16_t x, int16_t y, int16_t z) {
    if (fprintf(fp, "%s,%d,%d,%d\n", timestamp, x, y, z) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    fprintf(stderr, "Caught signal %d, terminating...\n", sig);
    terminate = 1;
}

int main() {
    char timestamp[32];
    AccelerationData raw_data, processed_data;

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Initialize I2C
    i2c_fd = i2c_setup(I2C_BUS, D7S_ADDR);
    if (i2c_fd < 0) {
        return 1;
    }

    // Open log file
    log_file = fopen("vibration_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    // Write header if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,X,Y,Z\n");
    }
    rewind(log_file);

    // Main loop
    while (!terminate) {
        // Read acceleration data
        raw_data = read_acceleration_data(i2c_fd);

        // Check for read errors
        if (raw_data.x == 0 && raw_data.y == 0 && raw_data.z == 0) {
            fprintf(stderr, "Error reading acceleration data, skipping sample.\n");
            usleep(SAMPLE_INTERVAL_MS * 1000); // Sleep for the sample interval
            continue;
        }

        // Process acceleration data
        processed_data = process_acceleration_data(raw_data);

        // Get timestamp
        get_iso8601_timestamp(timestamp, sizeof(timestamp));

        // Log data
        if (log_data(log_file, timestamp, processed_data.x, processed_data.y, processed_data.z) != 0) {
            fprintf(stderr, "Error logging data.\n");
        }

        // Sleep for the sample interval
        usleep(SAMPLE_INTERVAL_MS * 1000);
    }

    // Cleanup
    close(i2c_fd);
    fclose(log_file);

    return 0;
}

