#include <signal.h>
#include <pigpio.h>

#define SENSOR_1_GPIO 17
#define SENSOR_2_GPIO 27
#define LOG_FILE "conveyor_log.txt"

static volatile int running = 1;
static FILE *log_file = NULL;

// Function to handle signals (SIGINT, SIGTERM)
void signal_handler(int signal) {
    running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to read sensor data
int read_sensor(int gpio) {
    int value = gpioRead(gpio);
    if (value < 0) {
        fprintf(stderr, "Error reading GPIO %d: %d\n", gpio, value);
        return -1; // Indicate error
    }
    return value;
}

// Function to log data to file
void log_data(FILE *fp, int sensor1_state, int sensor2_state) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    char timestamp[100];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&ts.tv_sec));
    snprintf(timestamp + strlen(timestamp), sizeof(timestamp) - strlen(timestamp), ".%03ld", ts.tv_nsec / 1000000);

    fprintf(fp, "%s, Sensor1: %d, Sensor2: %d\n", timestamp, sensor1_state, sensor2_state);
    fflush(fp); // Ensure data is written to disk immediately
}

int main() {
    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes and pull-ups
    gpioSetMode(SENSOR_1_GPIO, PI_INPUT);
    gpioSetPullUpDown(SENSOR_1_GPIO, PI_PUD_UP);
    gpioSetMode(SENSOR_2_GPIO, PI_INPUT);
    gpioSetPullUpDown(SENSOR_2_GPIO, PI_PUD_UP);

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        gpioTerminate();
        return 1;
    }

    printf("Conveyor belt safety system started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        // Read sensor values
        int sensor1_state = read_sensor(SENSOR_1_GPIO);
        int sensor2_state = read_sensor(SENSOR_2_GPIO);

        if (sensor1_state == -1 || sensor2_state == -1) {
            // Error reading sensors, continue to next iteration
            gpioDelay(50); // Wait 50ms before retrying
            continue;
        }

        // Log data
        log_data(log_file, sensor1_state, sensor2_state);

        // Check if both sensors are triggered
        if (sensor1_state == 1 && sensor2_state == 1) {
            printf("Both sensors triggered! Halting conveyor.\n");
        }

        gpioDelay(50); // Wait 50ms
    }

    // Cleanup and exit
    printf("Cleaning up...\n");
    fclose(log_file);
    gpioTerminate();
    printf("Exiting.\n");
    return 0;
}

