#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <math.h>
#include <signal.h>
#include <time.h>
#include <string.h>

// LIS3MDL I2C address
#define LIS3MDL_ADDR 0x1E

// LIS3MDL register addresses
#define WHO_AM_I 0x0F
#define CTRL_REG1 0x20
#define CTRL_REG4 0x23
#define CTRL_REG3 0x22
#define OUT_X_L 0x28
#define OUT_X_H 0x29
#define OUT_Y_L 0x2A
#define OUT_Y_H 0x2B
#define OUT_Z_L 0x2C
#define OUT_Z_H 0x2D

// Calibration parameters
#define X_OFFSET 0.0
#define Y_OFFSET 0.0
#define Z_OFFSET 0.0
#define X_SCALE 1.0
#define Y_SCALE 1.0
#define Z_SCALE 1.0

// Metal detection threshold (mG)
#define METAL_THRESHOLD 800.0

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold magnetometer data
typedef struct {
    float x;
    float y;
    float z;
} magnetometer_data_t;

// Function prototypes
int initialize_magnetometer();
int read_magnetometer_data(int16_t *x, int16_t *y, int16_t *z);
magnetometer_data_t process_magnetometer_data(int16_t raw_x, int16_t raw_y, int16_t raw_z);
void log_magnetometer_data(magnetometer_data_t data);
void check_metal_detection(magnetometer_data_t data);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating...\n", signal);
}

// Initializes the LIS3MDL magnetometer
int initialize_magnetometer() {
    int retries = 3;
    while (retries > 0) {
        // Check WHO_AM_I register
        int who_am_i = i2cReadByteData(i2c_handle, WHO_AM_I);
        if (who_am_i < 0) {
            fprintf(stderr, "Error reading WHO_AM_I register: %d\n", who_am_i);
            gpioDelay(100000); // 100ms delay
            retries--;
            continue;
        }

        if (who_am_i != 0x3D) {
            fprintf(stderr, "WHO_AM_I returned 0x%02X, expected 0x3D\n", who_am_i);
            gpioDelay(100000); // 100ms delay
            retries--;
            continue;
        }

        // Configure CTRL_REG1 (80 Hz ODR, continuous conversion)
        int status = i2cWriteByteData(i2c_handle, CTRL_REG1, 0x70);
        if (status < 0) {
            fprintf(stderr, "Error writing to CTRL_REG1: %d\n", status);
            gpioDelay(100000); // 100ms delay
            retries--;
            continue;
        }

        // Configure CTRL_REG4 (High-performance mode on all axes)
        status = i2cWriteByteData(i2c_handle, CTRL_REG4, 0x0C);
        if (status < 0) {
            fprintf(stderr, "Error writing to CTRL_REG4: %d\n", status);
            gpioDelay(100000); // 100ms delay
            retries--;
            continue;
        }

        // Configure CTRL_REG3 (Continuous-conversion mode)
        status = i2cWriteByteData(i2c_handle, CTRL_REG3, 0x00);
        if (status < 0) {
            fprintf(stderr, "Error writing to CTRL_REG3: %d\n", status);
            gpioDelay(100000); // 100ms delay
            retries--;
            continue;
        }

        fprintf(stderr, "Magnetometer initialized successfully.\n");
        return 0; // Success
    }

    fprintf(stderr, "Failed to initialize magnetometer after multiple retries.\n");
    return -1; // Failure
}

// Reads raw magnetometer data from the LIS3MDL
int read_magnetometer_data(int16_t *x, int16_t *y, int16_t *z) {
    char buffer[6];
    int status = i2cReadI2CBlockData(i2c_handle, OUT_X_L | 0x80, buffer, 6); // Enable auto-increment
    if (status < 0) {
        fprintf(stderr, "Error reading magnetometer data: %d\n", status);
        return -1;
    }

    // Combine low and high bytes (little-endian)
    *x = (int16_t)((buffer[1] << 8) | buffer[0]);
    *y = (int16_t)((buffer[3] << 8) | buffer[2]);
    *z = (int16_t)((buffer[5] << 8) | buffer[4]);

    return 0;
}

// Processes raw magnetometer data and converts to milliGauss
magnetometer_data_t process_magnetometer_data(int16_t raw_x, int16_t raw_y, int16_t raw_z) {
    magnetometer_data_t data;

    // Apply calibration
    data.x = (float)raw_x * X_SCALE + X_OFFSET;
    data.y = (float)raw_y * Y_SCALE + Y_OFFSET;
    data.z = (float)raw_z * Z_SCALE + Z_OFFSET;

    // Convert to milliGauss (0.146 mG/LSB)
    data.x *= 0.146;
    data.y *= 0.146;
    data.z *= 0.146;

    return data;
}

// Logs magnetometer data to a file
void log_magnetometer_data(magnetometer_data_t data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.3f,%.3f,%.3f\n", timestamp, data.x, data.y, data.z);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Checks for metal detection based on the total magnetic field magnitude
void check_metal_detection(magnetometer_data_t data) {
    float magnitude = sqrt(data.x * data.x + data.y * data.y + data.z * data.z);
    if (magnitude > METAL_THRESHOLD) {
        fprintf(stderr, "Metal detected! Magnitude: %.3f mG\n", magnitude);
    }
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C device
    i2c_handle = i2cOpen(1, LIS3MDL_ADDR, 0); // Bus 1, address 0x1E, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize magnetometer
    if (initialize_magnetometer() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("magnetic_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handler for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int16_t raw_x, raw_y, raw_z;
    magnetometer_data_t magnetometer_data;

    // Main loop
    while (!terminate) {
        // Read magnetometer data
        if (read_magnetometer_data(&raw_x, &raw_y, &raw_z) == 0) {
            // Process magnetometer data
            magnetometer_data = process_magnetometer_data(raw_x, raw_y, raw_z);

            // Log magnetometer data
            log_magnetometer_data(magnetometer_data);

            // Check for metal detection
            check_metal_detection(magnetometer_data);
        } else {
            fprintf(stderr, "Error reading magnetometer data. Retrying initialization.\n");
            i2cClose(i2c_handle);
            gpioDelay(1000000); // 1 second delay
            i2c_handle = i2cOpen(1, LIS3MDL_ADDR, 0);
            if (i2c_handle < 0) {
                fprintf(stderr, "Error re-opening I2C device: %d\n", i2c_handle);
                terminate = 1; // Exit loop if re-initialization fails
            } else {
                if (initialize_magnetometer() != 0) {
                    fprintf(stderr, "Magnetometer re-initialization failed.\n");
                    terminate = 1;
                }
            }
        }

        gpioDelay(100000); // 100ms delay (10 Hz sampling rate)
    }

    // Cleanup
    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();

    fprintf(stderr, "Program terminated.\n");
    return 0;
}

