    data.y = (float)raw_y * Y_SCALE + Y_OFFSET;
    data.z = (float)raw_z * Z_SCALE + Z_OFFSET;

    // Convert to milliGauss (0.146 mG/LSB)
    data.x *= 0.146;
    data.y *= 0.146;
    data.z *= 0.146;

    return data;
}

// Logs magnetometer data to a file
void log_magnetometer_data(magnetometer_data_t data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.3f,%.3f,%.3f\n", timestamp, data.x, data.y, data.z);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Checks for metal detection based on the total magnetic field magnitude
void check_metal_detection(magnetometer_data_t data) {
    float magnitude = sqrt(data.x * data.x + data.y * data.y + data.z * data.z);
    if (magnitude > METAL_THRESHOLD) {
        fprintf(stderr, "Metal detected! Magnitude: %.3f mG\n", magnitude);
    }
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C device
    i2c_handle = i2cOpen(1, LIS3MDL_ADDR, 0); // Bus 1, address 0x1E, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize magnetometer
    if (initialize_magnetometer() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("magnetic_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handler for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int16_t raw_x, raw_y, raw_z;
    magnetometer_data_t magnetometer_data;

    // Main loop
    while (!terminate) {
        // Read magnetometer data
        if (read_magnetometer_data(&raw_x, &raw_y, &raw_z) == 0) {
            // Process magnetometer data
            magnetometer_data = process_magnetometer_data(raw_x, raw_y, raw_z);

            // Log magnetometer data
            log_magnetometer_data(magnetometer_data);

            // Check for metal detection
            check_metal_detection(magnetometer_data);
        } else {
            fprintf(stderr, "Error reading magnetometer data. Retrying initialization.\n");
            i2cClose(i2c_handle);
            gpioDelay(1000000); // 1 second delay
            i2c_handle = i2cOpen(1, LIS3MDL_ADDR, 0);
            if (i2c_handle < 0) {
                fprintf(stderr, "Error re-opening I2C device: %d\n", i2c_handle);
                terminate = 1; // Exit loop if re-initialization fails
            } else {
                if (initialize_magnetometer() != 0) {
                    fprintf(stderr, "Magnetometer re-initialization failed.\n");
                    terminate = 1;
                }
            }
        }

        gpioDelay(100000); // 100ms delay (10 Hz sampling rate)
    }

    // Cleanup
    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();

    fprintf(stderr, "Program terminated.\n");
    return 0;
}

