#define ADXL354B_YDATA_H  0x0C
#define ADXL354B_YDATA_XL 0x0D
#define ADXL354B_ZDATA_L  0x0E
#define ADXL354B_ZDATA_H  0x0F
#define ADXL354B_ZDATA_XL 0x10

// SPI Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED   1000000 // 1 MHz
#define SPI_MODE    0

// Global Variables
static int spi_handle;
static FILE *log_file;
static volatile sig_atomic_t terminate = 0;

// Function Prototypes
int spi_read_register(uint8_t reg, uint8_t *data, int len);
int spi_write_register(uint8_t reg, uint8_t data);
int adxl354b_reset();
int adxl354b_check_partid();
int adxl354b_read_acceleration(float *x, float *y, float *z);
void log_data(float x, float y, float z);
void signal_handler(int signal);

// SPI Read Function with Retry
int spi_read_register(uint8_t reg, uint8_t *data, int len) {
    char tx_buf[len + 1];
    char rx_buf[len + 1];
    int retries = 3;

    tx_buf[0] = reg | 0x80 | 0x40; // Read + Multi-byte
    memset(tx_buf + 1, 0, len); // Pad with zeros for reading

    while (retries > 0) {
        if (spiXfer(spi_handle, tx_buf, rx_buf, len + 1) == 0) {
            memcpy(data, rx_buf + 1, len);
            return 0; // Success
        } else {
            fprintf(stderr, "SPI read error, retrying...\n");
            retries--;
            gpioDelay(1000); // Wait 1 ms before retrying
        }
    }

    fprintf(stderr, "SPI read failed after multiple retries.\n");
    return -1; // Failure
}

// SPI Write Function with Retry
int spi_write_register(uint8_t reg, uint8_t data) {
    char tx_buf[2];
    int retries = 3;

    tx_buf[0] = reg & 0x7F; // Write only
    tx_buf[1] = data;

    while (retries > 0) {
        if (spiWrite(spi_handle, tx_buf, 2) == 0) {
            return 0; // Success
        } else {
            fprintf(stderr, "SPI write error, retrying...\n");
            retries--;
            gpioDelay(1000); // Wait 1 ms before retrying
        }
    }

    fprintf(stderr, "SPI write failed after multiple retries.\n");
    return -1; // Failure
}

// ADXL354B Reset Function
int adxl354b_reset() {
    if (spi_write_register(ADXL354B_RESET, 0x52) != 0) {
        fprintf(stderr, "Failed to reset ADXL354B.\n");
        return -1;
    }
    gpioDelay(1000); // Wait 1 ms
    return 0;
}

// ADXL354B Check Part ID Function
int adxl354b_check_partid() {
    uint8_t partid;
    if (spi_read_register(ADXL354B_PARTID, &partid, 1) != 0) {
        fprintf(stderr, "Failed to read PARTID.\n");
        return -1;
    }

    if (partid != 0x1D) {
        fprintf(stderr, "Incorrect PARTID: 0x%02X\n", partid);
        return -1;
    }

    printf("ADXL354B Part ID: 0x%02X (OK)\n", partid);
    return 0;
}

// ADXL354B Read Acceleration Function
int adxl354b_read_acceleration(float *x, float *y, float *z) {
    uint8_t x_data[3], y_data[3], z_data[3];
    int32_t x_raw, y_raw, z_raw;

    if (spi_read_register(ADXL354B_XDATA_L, x_data, 3) != 0) return -1;
    if (spi_read_register(ADXL354B_YDATA_L, y_data, 3) != 0) return -1;
    if (spi_read_register(ADXL354B_ZDATA_L, z_data, 3) != 0) return -1;

    x_raw = (int32_t)((((uint32_t)z_data[2] << 16) | ((uint32_t)y_data[2] << 8) | x_data[2]));
    x_raw = x_raw >> 4; // Align to 20 bits
    if (x_raw & 0x800000) {
        x_raw |= 0xFFF00000; // Sign extend
    }

    y_raw = (int32_t)((((uint32_t)z_data[2] << 16) | ((uint32_t)y_data[2] << 8) | y_data[2]));
    y_raw = y_raw >> 4; // Align to 20 bits
    if (y_raw & 0x800000) {
        y_raw |= 0xFFF00000; // Sign extend
    }

    z_raw = (int32_t)((((uint32_t)z_data[2] << 16) | ((uint32_t)z_data[2] << 8) | z_data[2]));
    z_raw = z_raw >> 4; // Align to 20 bits
    if (z_raw & 0x800000) {
        z_raw |= 0xFFF00000; // Sign extend
    }

    *x = (float)x_raw * 0.0000039; // Convert to g
    *y = (float)y_raw * 0.0000039; // Convert to g
    *z = (float)z_raw * 0.0000039; // Convert to g

    return 0;
}

