    // Reset ADXL354B
    if (adxl354b_reset() != 0) {
        fprintf(stderr, "ADXL354B reset failed\n");
        fclose(log_file);
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Check Part ID
    if (adxl354b_check_partid() != 0) {
        fprintf(stderr, "ADXL354B check failed\n");
        fclose(log_file);
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Set measurement mode
    if (spi_write_register(ADXL354B_POWER_CTL, 0x02) != 0) {
