#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>
#include <string.h>

// ADIS16362 Register Addresses
#define X_GYRO 0x04
#define Y_GYRO 0x06
#define Z_GYRO 0x08
#define X_ACCL 0x0A
#define Y_ACCL 0x0C
#define Z_ACCL 0x0E

// Scaling factors
#define GYRO_SCALE 0.05f  // deg/sec/LSB
#define ACCL_SCALE 0.0025f // g/LSB

// SPI Configuration
#define SPI_CHANNEL 0
#define SPI_BAUD 1000000
#define SPI_MODE 3

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold IMU data
typedef struct {
    float x_gyro;
    float y_gyro;
    float z_gyro;
    float x_accel;
    float y_accel;
    float z_accel;
} imu_data_t;

// Function prototypes
int spi_read_register(int handle, uint8_t address, uint16_t *data);
imu_data_t read_imu_data(int handle);
void log_data(imu_data_t data);
void signal_handler(int signal);

// Function to read a 16-bit register from the ADIS16362
int spi_read_register(int handle, uint8_t address, uint16_t *data) {
    char tx_buffer[2];
    char rx_buffer[2];
    int result;

    // Set MSB for read operation
    tx_buffer[0] = (address | 0x80); // Set MSB to 1 for read
    tx_buffer[1] = 0x00; // Dummy byte

    result = spiXfer(handle, tx_buffer, rx_buffer, 2);
    if (result != 2) {
        fprintf(stderr, "Error: spiXfer failed (read register 0x%02X): %d\n", address, result);
        return -1; // Indicate failure
    }

    *data = (rx_buffer[0] << 8) | rx_buffer[1];
    return 0; // Indicate success
}

// Function to read IMU data from the ADIS16362
imu_data_t read_imu_data(int handle) {
    imu_data_t data;
    uint16_t raw_gyro_x, raw_gyro_y, raw_gyro_z, raw_accel_x, raw_accel_y, raw_accel_z;

    // Read gyroscope data
    if (spi_read_register(handle, X_GYRO, &raw_gyro_x) != 0) {
        data.x_gyro = 0.0f; // Set to 0 on error
    } else {
        data.x_gyro = (float)raw_gyro_x * GYRO_SCALE;
    }

    if (spi_read_register(handle, Y_GYRO, &raw_gyro_y) != 0) {
        data.y_gyro = 0.0f;
    } else {
        data.y_gyro = (float)raw_gyro_y * GYRO_SCALE;
    }

    if (spi_read_register(handle, Z_GYRO, &raw_gyro_z) != 0) {
        data.z_gyro = 0.0f;
    } else {
        data.z_gyro = (float)raw_gyro_z * GYRO_SCALE;
    }

    // Read accelerometer data
    if (spi_read_register(handle, X_ACCL, &raw_accel_x) != 0) {
        data.x_accel = 0.0f;
    } else {
        data.x_accel = (float)raw_accel_x * ACCL_SCALE;
    }

    if (spi_read_register(handle, Y_ACCL, &raw_accel_y) != 0) {
        data.y_accel = 0.0f;
    } else {
        data.y_accel = (float)raw_accel_y * ACCL_SCALE;
    }

    if (spi_read_register(handle, Z_ACCL, &raw_accel_z) != 0) {
        data.z_accel = 0.0f;
    } else {
        data.z_accel = (float)raw_accel_z * ACCL_SCALE;
    }

    return data;
}

// Function to log IMU data to a file
void log_data(imu_data_t data) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    double timestamp = (double)ts.tv_sec + (double)ts.tv_nsec / 1000000000.0;

    fprintf(log_file, "%.9f,%.6f,%.6f,%.6f,%.6f,%.6f,%.6f\n",
            timestamp, data.x_gyro, data.y_gyro, data.z_gyro, data.x_accel, data.y_accel, data.z_accel);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "\nCaught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("imu_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Write header to log file if it's a new file
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,X_Gyro,Y_Gyro,Z_Gyro,X_Accel,Y_Accel,Z_Accel\n");
    }
    fflush(log_file);

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        imu_data_t imu_data = read_imu_data(spi_handle);
        log_data(imu_data);
        gpioDelay(10); // 10 ms delay for approximately 100 Hz sampling
    }

    // Cleanup
    spiClose(spi_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

