#define GPIO_CHIP_NAME "gpiochip4"
#define GPIO_LINE_NUMBER 17

static struct gpiod_chip *chip = NULL;
static struct gpiod_line *line = NULL;
static volatile sig_atomic_t terminate = 0;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int sig) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating...\n", sig);
}

// Function to initialize the GPIO line
int init_gpio(struct gpiod_chip **chip, struct gpiod_line **line) {
    int ret;

    // Open the GPIO chip
    ret = gpiod_chip_open_by_name(GPIO_CHIP_NAME, &chip);
    if (ret < 0) {
        fprintf(stderr, "Error opening GPIO chip: %d\n", ret);
        return -1;
    }

    // Get the GPIO line
    ret = gpiod_chip_get_line(*chip, GPIO_LINE_NUMBER, &line);
    if (ret < 0) {
        fprintf(stderr, "Error getting GPIO line: %d\n", ret);
        gpiod_chip_close(*chip);
        return -1;
    }

    // Request the line for input
    ret = gpiod_line_request_input(line, "obstacle_sensor");
    if (ret < 0) {
        fprintf(stderr, "Error requesting GPIO line for input: %d\n", ret);
        gpiod_chip_close(*chip);
        gpiod_line_release(line);
        return -1;
    }

    return 0;
}

// Function to read the sensor value
int read_sensor(struct gpiod_line *line) {
    int value = gpiod_line_get_value(line);
    if (value < 0) {
        fprintf(stderr, "Error reading sensor value\n");
        return -1;
    }
    return value;
}

// Function to log the self-parking sequence
void log_self_parking() {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("%s - Self-parking sequence started\n", timestamp);
    sleep(5);
    printf("%s - Self-parking sequence completed\n", timestamp);
}

// Function to cleanup GPIO resources
void cleanup_gpio(struct gpiod_chip *chip, struct gpiod_line *line) {
    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
}

int main() {
    int sensor_value;

    // Register signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (init_gpio(&chip, &line) < 0) {
        fprintf(stderr, "GPIO initialization failed\n");
        return 1;
    }

    printf("Obstacle sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        sensor_value = read_sensor(line);
        if (sensor_value < 0) {
            fprintf(stderr, "Error reading sensor, exiting\n");
            break;
        }

        if (sensor_value == 0) {
            log_self_parking();
        }

        sleep(1);
    }

    // Cleanup GPIO resources before exiting
    cleanup_gpio(chip, line);

    printf("Obstacle sensor monitoring stopped.\n");

    return 0;
}

