// Define GPIO pins for the sensors
#define SENSOR1_PIN 17
#define SENSOR2_PIN 27

// Global variables for GPIO chip and lines
struct gpiod_chip *chip;
struct gpiod_line *line1;
struct gpiod_line *line2;

// Function prototypes
int read_sensor(struct gpiod_line *line);
void log_data(int sensor1_value, int sensor2_value);
void signal_handler(int sig);

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    if (sig == SIGINT) {
        printf("\nCaught SIGINT, exiting gracefully.\n");
        if (line1) {
            gpiod_line_release(line1);
        }
        if (line2) {
            gpiod_line_release(line2);
        }
        if (chip) {
            gpiod_chip_close(chip);
        }
        exit(0);
    }
}

// Function to read the value of a sensor
int read_sensor(struct gpiod_line *line) {
    int value = gpiod_line_get_value(line);
    if (value < 0) {
        fprintf(stderr, "Error reading sensor value: %d\n", value);
        return -1; // Indicate an error
    }
    return value;
}

// Function to log the sensor data with a timestamp
void log_data(int sensor1_value, int sensor2_value) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("[%s] Sensor 1: %d, Sensor 2: %d\n", timestamp, sensor1_value, sensor2_value);
}

int main() {
    // Register the signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Open the GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Error opening GPIO chip");
        return 1;
    }

    // Get the GPIO lines for the sensors
    line1 = gpiod_chip_get_line(chip, SENSOR1_PIN);
    if (!line1) {
        perror("Error getting line for sensor 1");
        gpiod_chip_close(chip);
        return 1;
    }

    line2 = gpiod_chip_get_line(chip, SENSOR2_PIN);
    if (!line2) {
        perror("Error getting line for sensor 2");
        gpiod_line_release(line1);
        gpiod_chip_close(chip);
        return 1;
    }

    // Request the GPIO lines for input
    struct gpiod_line_request_config config;
    memset(&config, 0, sizeof(config));
    config.consumer = "obstacle_avoidance";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT;

    if (gpiod_line_request(line1, &config, 0) < 0) {
        perror("Error requesting line 1 for input");
        gpiod_line_release(line1);
        gpiod_line_release(line2);
        gpiod_chip_close(chip);
        return 1;
    }

    if (gpiod_line_request(line2, &config, 0) < 0) {
        perror("Error requesting line 2 for input");
        gpiod_line_release(line1);
        gpiod_line_release(line2);
        gpiod_chip_close(chip);
        return 1;
    }

    // Main loop to read and log sensor data
    while (1) {
        int sensor1_value = read_sensor(line1);
        int sensor2_value = read_sensor(line2);

        if (sensor1_value == -1 || sensor2_value == -1) {
            fprintf(stderr, "Error reading sensor data, retrying...\n");
        } else {
            log_data(sensor1_value, sensor2_value);
        }

        usleep(100000); // 100 ms delay
    }

    // The following lines will never be reached due to the infinite loop.
    gpiod_line_release(line1);
    gpiod_line_release(line2);
    gpiod_chip_close(chip);

    return 0;
}

