#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>
#include <time.h>
#include <signal.h>
#include <errno.h>

// ADIS16266 Register Addresses
#define ADIS16266_XGYRO_OUT 0x04
#define ADIS16266_YGYRO_OUT 0x06
#define ADIS16266_ZGYRO_OUT 0x08
#define ADIS16266_MSC_CTRL  0x24

// SPI Configuration
#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE SPI_MODE_3
#define SPI_SPEED 1000000 // 1 MHz
#define CS_GPIO 8

// Global Variables
static int spi_fd = -1;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *cs_line = NULL;
static volatile sig_atomic_t terminate = 0;

// Function Prototypes
int spi_init(void);
int gpio_init(void);
int adis16266_init(void);
int read_gyro_data(int16_t *x, int16_t *y, int16_t *z);
void convert_to_angular_rates(int16_t x, int16_t y, int16_t z, float *x_rate, float *y_rate, float *z_rate);
void log_data(float x_rate, float y_rate, float z_rate);
void signal_handler(int sig);
void cleanup(void);

// Signal Handler
void signal_handler(int sig) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", sig);
}

// SPI Initialization
int spi_init(void) {
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }

    // Configure SPI mode
    uint8_t mode = SPI_MODE;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("Error setting SPI mode");
        close(spi_fd);
        return -1;
    }

    // Configure SPI speed
    uint32_t speed = SPI_SPEED;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("Error setting SPI speed");
        close(spi_fd);
        return -1;
    }

    return 0;
}

// GPIO Initialization
int gpio_init(void) {
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    cs_line = gpiod_chip_get_line(chip, CS_GPIO);
    if (!cs_line) {
        perror("Error getting GPIO line");
        gpiod_chip_close(chip);
        return -1;
    }

    if (gpiod_line_request_output(cs_line, "adis16266", 0) < 0) {
        perror("Error requesting GPIO line as output");
        gpiod_chip_close(chip);
        return -1;
    }

    return 0;
}

// ADIS16266 Initialization
int adis16266_init(void) {
    uint8_t tx_buf[2];
    uint8_t rx_buf[2];
    int ret;

    // Enable data ready mode (MSC_CTRL register)
    tx_buf[0] = (ADIS16266_MSC_CTRL | 0x80); // Set MSB for write
    tx_buf[1] = 0x00; // Value to write (example: enable data ready)

    ret = spi_transfer(spi_fd, tx_buf, rx_buf, 2);
    if (ret < 0) {
        perror("Error writing to ADIS16266");
        return -1;
    }

    return 0;
}

// Read Gyroscope Data
