#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// LSM6DSR I2C address
#define LSM6DSR_ADDR 0x6B

// LSM6DSR register addresses
#define WHO_AM_I 0x0F
#define CTRL1_XL 0x10
#define CTRL2_G 0x11
#define OUTX_L_G 0x22
#define OUTX_L_XL 0x28

// Sensitivity values
#define GYRO_SENSITIVITY 0.00875f // mdps/LSB
#define ACCEL_SENSITIVITY 0.000061f // g/LSB

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Signal handler for Ctrl+C
void sigint_handler(int signal)
{
    terminate = 1;
}

// Function to initialize the LSM6DSR
int init_lsm6dsr()
{
    int status;

    // Check WHO_AM_I register
    status = i2cWriteByteData(i2c_handle, WHO_AM_I, 0x00); // Dummy write to prepare for read
    if (status != 0) {
        fprintf(stderr, "Error writing to WHO_AM_I register: %d\n", status);
        return -1;
    }
    int who_am_i = i2cReadByteData(i2c_handle, WHO_AM_I);
    if (who_am_i < 0) {
        fprintf(stderr, "Error reading WHO_AM_I register: %d\n", who_am_i);
        return -1;
    }
    if (who_am_i != 0x6B) {
        fprintf(stderr, "WHO_AM_I mismatch: Expected 0x6B, got 0x%X\n", who_am_i);
        return -1;
    }

    // Configure accelerometer
    status = i2cWriteByteData(i2c_handle, CTRL1_XL, 0x42); // +-2g, 104 Hz
    if (status != 0) {
        fprintf(stderr, "Error writing to CTRL1_XL register: %d\n", status);
        return -1;
    }

    // Configure gyroscope
    status = i2cWriteByteData(i2c_handle, CTRL2_G, 0x42); // +-250 dps, 104 Hz
    if (status != 0) {
        fprintf(stderr, "Error writing to CTRL2_G register: %d\n", status);
        return -1;
    }

    return 0;
}

// Function to read accelerometer and gyroscope data
int read_data(float *gyro_x, float *gyro_y, float *gyro_z, float *accel_x, float *accel_y, float *accel_z)
{
    char buffer[12];
    int status;
    int16_t raw_gyro_x, raw_gyro_y, raw_gyro_z, raw_accel_x, raw_accel_y, raw_accel_z;

    // Burst read 12 bytes starting from OUTX_L_G
    status = i2cWriteByte(i2c_handle, OUTX_L_G);
    if (status != 0) {
        fprintf(stderr, "Error writing to I2C device: %d\n", status);
        return -1;
    }

    status = i2cReadI2CBlockData(i2c_handle, OUTX_L_G, buffer, 12);
    if (status != 12) {
        fprintf(stderr, "Error reading from I2C device: %d\n", status);
        return -1;
    }

    // Extract raw data
    raw_gyro_x = (int16_t)((buffer[1] << 8) | buffer[0]);
    raw_gyro_y = (int16_t)((buffer[3] << 8) | buffer[2]);
    raw_gyro_z = (int16_t)((buffer[5] << 8) | buffer[4]);
    raw_accel_x = (int16_t)((buffer[7] << 8) | buffer[6]);
    raw_accel_y = (int16_t)((buffer[9] << 8) | buffer[8]);
    raw_accel_z = (int16_t)((buffer[11] << 8) | buffer[10]);

    // Convert to physical units
    *gyro_x = (float)raw_gyro_x * GYRO_SENSITIVITY;
    *gyro_y = (float)raw_gyro_y * GYRO_SENSITIVITY;
    *gyro_z = (float)raw_gyro_z * GYRO_SENSITIVITY;
    *accel_x = (float)raw_accel_x * ACCEL_SENSITIVITY;
    *accel_y = (float)raw_accel_y * ACCEL_SENSITIVITY;
    *accel_z = (float)raw_accel_z * ACCEL_SENSITIVITY;

    return 0;
}

int main()
{
    float gyro_x, gyro_y, gyro_z, accel_x, accel_y, accel_z;
    int status;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, LSM6DSR_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize LSM6DSR
    if (init_lsm6dsr() != 0) {
        fprintf(stderr, "LSM6DSR initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, sigint_handler);

    // Main loop
    while (!terminate) {
        // Read data
        status = read_data(&gyro_x, &gyro_y, &gyro_z, &accel_x, &accel_y, &accel_z);
        if (status == 0) {
            // Print data
            printf("%.3f,%.3f,%.3f,%.3f,%.3f,%.3f\n", gyro_x, gyro_y, gyro_z, accel_x, accel_y, accel_z);
        } else {
            fprintf(stderr, "Error reading data\n");
        }

        // Delay for 100 ms
        gpioDelay(100000); // 100 ms = 100000 us
    }

    // Clean up
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

