#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// FXOS8700 I2C address
#define FXOS8700_ADDR 0x1D

// FXOS8700 Registers
#define FXOS8700_WHO_AM_I 0x0D
#define FXOS8700_CTRL_REG1 0x2A
#define FXOS8700_CTRL_REG2 0x2B
#define FXOS8700_M_CTRL_REG1 0x5B
#define FXOS8700_M_CTRL_REG2 0x5C
#define FXOS8700_OUT_X_MSB 0x01

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    printf("\nCaught signal %d, terminating gracefully...\n", sig);
    terminate = 1;
}

// Function to initialize the FXOS8700 sensor
int init_fxos8700() {
    int retries = 3;
    while (retries > 0) {
        // Check WHO_AM_I register
        char who_am_i;
        if (i2cReadI2CBlockData(i2c_handle, FXOS8700_WHO_AM_I, &who_am_i, 1) != 1) {
            fprintf(stderr, "Error reading WHO_AM_I register. Retrying...\n");
            gpioDelay(100000); // 100ms delay
            retries--;
            continue;
        }

