#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>
#include <string.h>

#define GPIO_PIN 17
#define SAMPLE_PERIOD_MS 1
#define ALERT_WINDOW_S 5
#define ALERT_PAUSE_S 1

volatile sig_atomic_t program_running = 1;

void signal_handler(int signal) {
    program_running = 0;
    fprintf(stderr, "\nCaught signal %d, exiting gracefully...\n", signal);
}

int main(int argc, char *argv[]) {
    int threshold;
    int high_count;
    time_t start_time, current_time;
    struct tm *time_info;
    char timestamp[20];

    // Signal handling setup
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Parse command-line argument
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <threshold>\n", argv[0]);
        return 1;
    }

    char *endptr;
    threshold = strtol(argv[1], &endptr, 10);

    if (*endptr != '\0' || threshold <= 0) {
        fprintf(stderr, "Error: Invalid threshold value. Must be a positive integer.\n");
        return 1;
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(GPIO_PIN, PI_INPUT);

    time(&start_time);

    while (program_running) {
        high_count = 0;
        time(&start_time);

        while (program_running) {
            time(&current_time);
            if (difftime(current_time, start_time) >= ALERT_WINDOW_S) {
                break;
            }

            if (gpioRead(GPIO_PIN) == 1) {
                high_count++;
            }
            gpioDelay(SAMPLE_PERIOD_MS);
        }

        time(&current_time);
        time_info = localtime(&current_time);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", time_info);

        if (high_count > threshold) {
            printf("%s ALERT: High readings: %d\n", timestamp, high_count);
        } else {
            printf("%s Normal: High readings: %d\n", timestamp, high_count);
        }

        gpioDelay(ALERT_PAUSE_S * 1000); // Pause for 1 second
    }

    gpioTerminate();
    return 0;
}

