// Function to generate a random 6-digit code
int generate_random_code(int *code) {
    if (code == NULL) {
        fprintf(stderr, "Error: Null pointer passed to generate_random_code.\n");
        return -1;
    }

    // Generate a random number between 100000 and 999999
    *code = (rand() % 900000) + 100000;
    return 0;
}

