        return -1;
    }

    int entered_code = atoi(user_input);
    return (entered_code == code);
}

// Function to unlock a door
int unlock_door(struct gpiod_line *line) {
    if (line == NULL) {
        fprintf(stderr, "Error: Null pointer passed to unlock_door.\n");
        return -1;
    }

    int ret = gpiod_line_set_value(line, 1); // Set GPIO HIGH to unlock
    if (ret < 0) {
        fprintf(stderr, "Error setting GPIO %d HIGH: %s\n", line->number, strerror(-ret));
        return -1;
