    return 0;
}

// Function to lock a door
int lock_door(struct gpiod_line *line) {
    if (line == NULL) {
        fprintf(stderr, "Error: Null pointer passed to lock_door.\n");
        return -1;
    }

    int ret = gpiod_line_set_value(line, 0); // Set GPIO LOW to lock
    if (ret < 0) {
        fprintf(stderr, "Error setting GPIO %d LOW: %s\n", line->number, strerror(-ret));
        return -1;
    }

