#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS "/dev/i2c-1"
#define BH1750_ADDR 0x23
#define HIGH_RES_MODE_2 0x21
#define LUX_SCALE_FACTOR 1.2
#define LOG_FILE "light_log.txt"

volatile sig_atomic_t program_running = 1;

void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully.\n", signal);
}

int i2c_setup(const char *bus_name, int device_address) {
    int file_descriptor = open(bus_name, O_RDWR);
    if (file_descriptor < 0) {
        perror("Error opening I2C bus");
        return -1;
    }

    if (ioctl(file_descriptor, I2C_SLAVE, device_address) < 0) {
        perror("Error setting I2C slave address");
        close(file_descriptor);
        return -1;
    }

    return file_descriptor;
}

int bh1750_write_command(int file_descriptor, uint8_t command) {
    uint8_t buffer[1];
    buffer[0] = command;

    if (write(file_descriptor, buffer, 1) != 1) {
        perror("Error writing to I2C device");
        return -1;
    }

    return 0;
}

int bh1750_read_data(int file_descriptor, uint16_t *raw_value) {
    uint8_t buffer[2];

    if (read(file_descriptor, buffer, 2) != 2) {
        perror("Error reading from I2C device");
        return -1;
    }

    *raw_value = (buffer[0] << 8) | buffer[1];
    return 0;
}

float calculate_lux(uint16_t raw_value) {
    return (raw_value * 5.0) / 6.0;
}

int log_data(const char *timestamp, float lux_value) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("Error opening log file");
        return -1;
    }

    fprintf(fp, "Timestamp: %s, Lux: %.2f\n", timestamp, lux_value);
    fclose(fp);
    return 0;
}

int main() {
    int i2c_fd;
    uint16_t raw_value;
    float lux_value;
    time_t current_time;
    struct tm *time_info;
    char timestamp[20];

    signal(SIGINT, signal_handler);

    i2c_fd = i2c_setup(I2C_BUS, BH1750_ADDR);
    if (i2c_fd < 0) {
        return 1;
    }

    while (program_running) {
        if (bh1750_write_command(i2c_fd, HIGH_RES_MODE_2) < 0) {
            fprintf(stderr, "Error writing to BH1750, retrying in 5 seconds.\n");
            sleep(5);
            continue;
        }

        usleep(180000); // Wait for 180ms

        if (bh1750_read_data(i2c_fd, &raw_value) < 0) {
            fprintf(stderr, "Error reading from BH1750, retrying in 5 seconds.\n");
            sleep(5);
            continue;
        }

        lux_value = calculate_lux(raw_value);

        time(&current_time);
        time_info = localtime(&current_time);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", time_info);

        if (log_data(timestamp, lux_value) < 0) {
            fprintf(stderr, "Error logging data, retrying in 5 seconds.\n");
        }

        printf("Timestamp: %s, Lux: %.2f\n", timestamp, lux_value);
        sleep(5);
    }

    close(i2c_fd);
    return 0;
}

