void play_tone(float frequency);
void log_frequency(float frequency);
void handle_client(int client_socket);
void signal_handler(int signal);

// Function to initialize the MPR121
int init_mpr121() {
    // Soft reset
    if (i2cWriteByteData(i2c_handle, 0x80, 0x63) < 0) {
        perror("Error: MPR121 soft reset failed");
        return -1;
    }
    gpioDelay(100); // Wait for reset to complete

    // Configure electrode sensitivity and release thresholds
    for (int i = 0; i < 12; i++) {
        if (i2cWriteByteData(i2c_handle, 0x41 + 2 * i, 0x30) < 0) { // Touch threshold
            perror("Error: MPR121 touch threshold config failed");
            return -1;
        }
        if (i2cWriteByteData(i2c_handle, 0x42 + 2 * i, 0x10) < 0) { // Release threshold
            perror("Error: MPR121 release threshold config failed");
            return -1;
        }
    }

    // Enable all electrodes
    if (i2cWriteByteData(i2c_handle, 0x5E, 0x8F) < 0) {
        perror("Error: MPR121 electrode enable failed");
        return -1;
    }

    // Configure filter settings (example values)
    if (i2cWriteByteData(i2c_handle, 0x5B, 0x01) < 0) { // Filter configuration
        perror("Error: MPR121 filter config failed");
        return -1;
    }

    return 0;
}

// Function to read touch data from the MPR121
int read_touch_data(unsigned short *touch_data) {
    char buf[2];
    if (i2cReadI2CBlockData(i2c_handle, 0x00, buf, 2) != 2) {
        perror("Error: MPR121 read failed");
        return -1;
    }
    *touch_data = (buf[1] << 8) | buf[0];
    return 0;
}

// Function to map touch data to a frequency using a logarithmic scale
float map_touch_to_frequency(unsigned short touch_data) {
    float max_touch = 0.0;
    for (int i = 0; i < 12; i++) {
        if (touch_data & (1 << i)) {
            max_touch = 1.0; // At least one electrode is touched
            break;
        }
    }

    // Logarithmic mapping
    float frequency = 220.0 * powf(880.0 / 220.0, max_touch);
    return frequency;
}

// Function to play a tone using hardware PWM
void play_tone(float frequency) {
    gpioSetPWMfrequency(PWM_GPIO, (int)frequency);
    gpioPWM(PWM_GPIO, 128); // 50% duty cycle
}

// Function to log the frequency to a file
void log_frequency(float frequency) {
    if (log_file != NULL) {
        fprintf(log_file, "%.2f\n", frequency);
        fflush(log_file); // Ensure data is written to disk immediately
    } else {
        perror("Error: Log file not opened");
    }
}

// Function to handle a client connection
void handle_client(int client_socket) {
    char buffer[1024] = {0};
    ssize_t bytes_received = recv(client_socket, buffer, sizeof(buffer) - 1, 0);
    if (bytes_received > 0) {
        printf("Received: %s\n", buffer);

        // Check for motion detection message
        if (strstr(buffer, "MOTION_DETECTED:") != NULL) {
            // Verify the secret key
            char *secret_key_start = strstr(buffer, SECRET_KEY);
            if (secret_key_start != NULL) {
                if (strstr(secret_key_start, SECRET_KEY) == secret_key_start) {
                    printf("Secret key verified!\n");

                    // Play tones for 5 seconds
                    for (int i = 0; i < PLAYBACK_DURATION_S * 1000 / SAMPLE_PERIOD_MS; i++) {
                        unsigned short touch_data;
                        if (read_touch_data(&touch_data) == 0) {
                            float frequency = map_touch_to_frequency(touch_data);
                            play_tone(frequency);
                            log_frequency(frequency);
                        } else {
                            fprintf(stderr, "Error reading touch data in handle_client\n");
                        }
                        gpioDelay(SAMPLE_PERIOD_MS);
                    }

                    // Stop PWM after playback
                    gpioPWM(PWM_GPIO, 0);
                } else {
                    fprintf(stderr, "Error: Secret key mismatch\n");
                }
            } else {
