#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>
#include <signal.h>
#include <time.h>
#include <errno.h>

// Constants
#define I2C_BUS "/dev/i2c-1"
#define LSM303_ADDR 0x1E
#define CTRL_REG1_M 0x20
#define OUT_X_L_M 0x08
#define LED_GPIO 17
#define PWM_CHIP "gpiochip0"
#define PWM_LINE 0
#define PWM_PERIOD 1000000 // 1 kHz
#define SAMPLE_INTERVAL_MS 100

// Global variables (to be cleaned up on exit)
static int i2c_fd = -1;
static struct gpiod_chip *gpio_chip = NULL;
static struct gpiod_line *led_line = NULL;
static struct gpiod_line *pwm_line = NULL;
static struct gpiod_pwm_channel *pwm_channel = NULL;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c(const char *bus);
int init_gpio(int gpio_pin);
int init_pwm(int gpio_pin, int period_ns);
int init_lsm303(int fd);
int read_magnetometer_data(int fd, int16_t *x, int16_t *y, int16_t *z);
double calculate_magnitude(int16_t x, int16_t y, int16_t z);
int set_led_brightness(int duty_cycle);
void log_data(int16_t x, int16_t y, int16_t z, double magnitude);
void signal_handler(int sig);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    terminate = 1;
    printf("Signal received, cleaning up...\n");
}

// Initialize I2C bus
int init_i2c(const char *bus) {
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C bus");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, LSM303_ADDR) < 0) {
        perror("Error setting I2C slave address");
        close(fd);
        return -1;
    }

    return fd;
}

// Initialize GPIO line for LED
int init_gpio(int gpio_pin) {
    gpio_chip = gpiod_chip_open_by_name(PWM_CHIP);
    if (!gpio_chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    led_line = gpiod_chip_get_line(gpio_chip, gpio_pin);
    if (!led_line) {
        perror("Error getting GPIO line");
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    if (gpiod_line_request_output(led_line, "magnetometer", 0) < 0) {
        perror("Error requesting GPIO line for output");
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    return 0;
}

// Initialize PWM channel
int init_pwm(int gpio_pin, int period_ns) {
    pwm_line = gpiod_chip_get_line(gpio_chip, gpio_pin);
    if (!pwm_line) {
        perror("Error getting GPIO line for PWM");
        return -1;
    }

    pwm_channel = gpiod_chip_get_pwm_line(gpio_chip, gpio_pin);
    if (!pwm_channel) {
        perror("Error getting PWM line");
        return -1;
    }

    if (gpiod_pwm_channel_request(pwm_channel, "magnetometer", period_ns, 0) < 0) {
        perror("Error requesting PWM channel");
        return -1;
    }

    return 0;
}

// Initialize LSM303 magnetometer
int init_lsm303(int fd) {
    uint8_t init_data[2] = {CTRL_REG1_M, 0x18}; // 10 Hz continuous conversion
    if (write(fd, init_data, sizeof(init_data)) != sizeof(init_data)) {
        perror("Error writing to magnetometer");
        return -1;
    }
    return 0;
}

// Read magnetometer data
int read_magnetometer_data(int fd, int16_t *x, int16_t *y, int16_t *z) {
    uint8_t buffer[6];
    if (read(fd, buffer, sizeof(buffer)) != sizeof(buffer)) {
        perror("Error reading from magnetometer");
        return -1;
    }

    *x = (int16_t)((buffer[1] << 8) | buffer[0]);
    *y = (int16_t)((buffer[3] << 8) | buffer[2]);
    *z = (int16_t)((buffer[5] << 8) | buffer[4]);

    return 0;
}

// Calculate magnitude of Z-axis field
double calculate_magnitude(int16_t x, int16_t y, int16_t z) {
    return sqrt(x * x + y * y + z * z);
}

// Set LED brightness using PWM
int set_led_brightness(int duty_cycle) {
    if (duty_cycle < 0 || duty_cycle > 100) {
        fprintf(stderr, "Invalid duty cycle: %d\n", duty_cycle);
        return -1;
    }

    int pwm_value = (int)((duty_cycle / 100.0) * PWM_PERIOD);
    if (gpiod_pwm_channel_set_duty_ns(pwm_channel, pwm_value) < 0) {
        perror("Error setting PWM duty cycle");
        return -1;
    }
    return 0;
}

// Log data to file
void log_data(int16_t x, int16_t y, int16_t z, double magnitude) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s, X: %d, Y: %d, Z: %d, Magnitude: %.2f\n", timestamp, x, y, z, magnitude);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Cleanup resources
void cleanup() {
    printf("Cleaning up resources...\n");

    if (pwm_channel) {
        gpiod_pwm_channel_release(pwm_channel);
    }
    if (led_line) {
        gpiod_line_release(led_line);
    }
    if (gpio_chip) {
        gpiod_chip_close(gpio_chip);
    }
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (log_file) {
        fclose(log_file);
    }

    printf("Cleanup complete.\n");
}

int main() {
    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    i2c_fd = init_i2c(I2C_BUS);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to initialize I2C. Exiting.\n");
        return 1;
    }

    // Initialize GPIO and PWM
    if (init_gpio(LED_GPIO) < 0 || init_pwm(PWM_LINE, PWM_PERIOD) < 0) {
        fprintf(stderr, "Failed to initialize GPIO/PWM. Exiting.\n");
        cleanup();
        return 1;
    }

    // Initialize LSM303
    if (init_lsm303(i2c_fd) < 0) {
        fprintf(stderr, "Failed to initialize LSM303. Exiting.\n");
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen("magnetometer_log.txt", "a");
    if (!log_file) {
        perror("Error opening log file");
        cleanup();
        return 1;
    }

    int16_t x, y, z;
    double magnitude;
    int duty_cycle;

    // Main loop
    while (!terminate) {
        // Read magnetometer data
        if (read_magnetometer_data(i2c_fd, &x, &y, &z) == 0) {
            // Calculate magnitude
            magnitude = calculate_magnitude(x, y, z);

            // Scale magnitude to duty cycle (0-100)
            duty_cycle = (int)((magnitude / 1000.0) * 100.0); // Assuming max magnitude is 1000
            if (duty_cycle < 0) duty_cycle = 0;
            if (duty_cycle > 100) duty_cycle = 100;

            // Set LED brightness
            if (set_led_brightness(duty_cycle) != 0) {
                fprintf(stderr, "Failed to set LED brightness.\n");
            }

            // Log data
            log_data(x, y, z, magnitude);
        } else {
            fprintf(stderr, "Failed to read magnetometer data.\n");
        }

        // Wait for the next sample
        usleep(SAMPLE_INTERVAL_MS * 1000); // Convert ms to us
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

