#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>

// HMC5883L I2C address
#define HMC5883L_ADDR 0x1E

// HMC5883L register addresses
#define HMC5883L_CONFIG_A 0x00
#define HMC5883L_CONFIG_B 0x01
#define HMC5883L_MODE 0x02
#define HMC5883L_DATA_X_MSB 0x03
#define HMC5883L_DATA_X_LSB 0x04
#define HMC5883L_DATA_Z_MSB 0x05
#define HMC5883L_DATA_Z_LSB 0x06
#define HMC5883L_DATA_Y_MSB 0x07
#define HMC5883L_DATA_Y_LSB 0x08

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Hard-iron offset buffers
int16_t x_offset_buffer[100];
int16_t y_offset_buffer[100];
int16_t z_offset_buffer[100];
int buffer_index = 0;

// Function prototypes
int initialize_magnetometer();
int read_magnetometer_data(int16_t *x, int16_t *y, int16_t *z);
void update_hard_iron_offsets(int16_t x, int16_t y, int16_t z);
void apply_hard_iron_offsets(int16_t x, int16_t y, int16_t z, int16_t x_offset, int16_t y_offset, int16_t z_offset, float *x_corrected, float *y_corrected, float *z_corrected);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating gracefully...\n", signal);
}

// Initializes the HMC5883L magnetometer
int initialize_magnetometer() {
    // Configuration Register A: 8-sample averaging, 15 Hz output rate
    if (i2cWriteByteData(i2c_handle, HMC5883L_CONFIG_A, 0x70) < 0) {
        fprintf(stderr, "Error writing to Configuration Register A\n");
        return -1;
    }

    // Configuration Register B: Gain = 1.3 Gauss
    if (i2cWriteByteData(i2c_handle, HMC5883L_CONFIG_B, 0x20) < 0) {
        fprintf(stderr, "Error writing to Configuration Register B\n");
        return -1;
    }

    // Mode Register: Continuous measurement mode
    if (i2cWriteByteData(i2c_handle, HMC5883L_MODE, 0x00) < 0) {
        fprintf(stderr, "Error writing to Mode Register\n");
        return -1;
    }

    return 0;
}

// Reads raw magnetometer data
int read_magnetometer_data(int16_t *x, int16_t *y, int16_t *z) {
    char buffer[6];

    if (i2cReadI2CBlockData(i2c_handle, HMC5883L_DATA_X_MSB, buffer, 6) != 6) {
        fprintf(stderr, "Error reading magnetometer data\n");
        return -1;
    }

    *x = (int16_t)((buffer[0] << 8) | buffer[1]);
    *z = (int16_t)((buffer[2] << 8) | buffer[3]);
    *y = (int16_t)((buffer[4] << 8) | buffer[5]);

    return 0;
}

// Updates the hard-iron offset buffers with new readings
void update_hard_iron_offsets(int16_t x, int16_t y, int16_t z) {
    x_offset_buffer[buffer_index] = x;
    y_offset_buffer[buffer_index] = y;
    z_offset_buffer[buffer_index] = z;

    buffer_index = (buffer_index + 1) % 100;
}

// Calculates the running average of the hard-iron offsets
void apply_hard_iron_offsets(int16_t x, int16_t y, int16_t z, int16_t x_offset, int16_t y_offset, int16_t z_offset, float *x_corrected, float *y_corrected, float *z_corrected) {
    int16_t x_sum = 0, y_sum = 0, z_sum = 0;

    for (int i = 0; i < 100; i++) {
        x_sum += x_offset_buffer[i];
        y_sum += y_offset_buffer[i];
        z_sum += z_offset_buffer[i];
    }

    *x_corrected = (float)x - (float)x_sum / 100.0;
    *y_corrected = (float)y - (float)y_sum / 100.0;
    *z_corrected = (float)z - (float)z_sum / 100.0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, HMC5883L_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize the magnetometer
    if (initialize_magnetometer() < 0) {
        fprintf(stderr, "Magnetometer initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handling for Ctrl+C
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int16_t x, y, z;
    float x_corrected, y_corrected, z_corrected;

    // Main loop
    while (!terminate) {
        // Read magnetometer data
        if (read_magnetometer_data(&x, &y, &z) == 0) {
            // Update hard-iron offsets
            update_hard_iron_offsets(x, y, z);

            // Calculate running average of offsets
            apply_hard_iron_offsets(x, y, z, x, y, z, &x_corrected, &y_corrected, &z_corrected);

            // Print offset-corrected values
            printf("X: %.2f, Y: %.2f, Z: %.2f\n", x_corrected, y_corrected, z_corrected);
        } else {
            fprintf(stderr, "Failed to read magnetometer data. Retrying...\n");
        }

        // Wait 500 ms
        gpioDelay(500000); // 500 ms = 500000 microseconds
    }

    // Close I2C bus and terminate pigpio
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

