#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>
#include <time.h>
#include <signal.h>
#include <math.h>

// LSM303D I2C address
#define LSM303D_ADDR 0x1D

// LSM303D register addresses
#define WHO_AM_I 0x0F
#define CTRL_REG1 0x20
#define CTRL_REG4 0x23
#define INT1_CFG 0x30
#define INT1_THS 0x32
#define INT1_DURATION 0x33
#define OUT_X_L_A 0x28

// GPIO pin for INT1 interrupt
#define INT1_GPIO 23

// Circular buffer size
#define BUFFER_SIZE 64

// Structure to hold acceleration data
typedef struct {
    int16_t x;
    int16_t y;
    int16_t z;
} acceleration_data_t;

// Global variables
int i2c_fd;
struct gpiod_chip *gpio_chip;
struct gpiod_line *gpio_line;
struct gpiod_line_request_config config;
int buffer_index = 0;
acceleration_data_t circular_buffer[BUFFER_SIZE];
volatile sig_atomic_t program_running = 1;

// Function prototypes
int i2c_read_byte(int reg);
int i2c_write_byte(int reg, int value);
int i2c_read_block(int reg, uint8_t *data, int len);
int i2c_write_block(int reg, uint8_t *data, int len);
int lsm303d_init();
void interrupt_handler(int line, struct gpiod_line *gpio_line, struct gpiod_line_event *event);
void print_buffer();
void signal_handler(int sig);

// I2C read byte function
int i2c_read_byte(int reg) {
    int result = i2c_smbus_read_byte_data(i2c_fd, reg);
    if (result < 0) {
        fprintf(stderr, "Error reading register 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    return result;
}

// I2C write byte function
int i2c_write_byte(int reg, int value) {
    int result = i2c_smbus_write_byte_data(i2c_fd, reg, value);
    if (result < 0) {
        fprintf(stderr, "Error writing 0x%02X to register 0x%02X: %s\n", value, reg, strerror(errno));
        return -1;
    }
    return 0;
}

// I2C read block function
int i2c_read_block(int reg, uint8_t *data, int len) {
    int result = i2c_smbus_read_i2c_block_data(i2c_fd, reg, (char *)data, len);
    if (result < 0) {
        fprintf(stderr, "Error reading block from register 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

// I2C write block function
int i2c_write_block(int reg, uint8_t *data, int len) {
    int result = i2c_smbus_write_i2c_block_data(i2c_fd, reg, (char *)data, len);
    if (result < 0) {
        fprintf(stderr, "Error writing block to register 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

// LSM303D initialization function
int lsm303d_init() {
    // Verify WHO_AM_I register
    int who_am_i = i2c_read_byte(WHO_AM_I);
    if (who_am_i != 0x49) {
        fprintf(stderr, "Error: WHO_AM_I register returned 0x%02X, expected 0x49\n", who_am_i);
        return -1;
    }

    // Configure accelerometer
    if (i2c_write_byte(CTRL_REG1, 0x57) < 0) return -1; // 50 Hz ODR, all axes enabled
    if (i2c_write_byte(CTRL_REG4, 0x00) < 0) return -1; // +-2g full-scale

    // Configure interrupt
    if (i2c_write_byte(INT1_CFG, 0x2A) < 0) return -1; // Any-axis-high interrupt
    uint8_t threshold_value = 125; // 2000 mg threshold / 16
    if (i2c_write_byte(INT1_THS, threshold_value) < 0) return -1;
    if (i2c_write_byte(INT1_DURATION, 0x00) < 0) return -1; // Immediate interrupt

    return 0;
}

// Interrupt handler function
void interrupt_handler(int line, struct gpiod_line *gpio_line, struct gpiod_line_event *event) {
    if (event->event == GPIOD_LINE_EVENT_RISING_EDGE) {
        printf("Interrupt triggered!\n");
        print_buffer();
    }
}

// Print circular buffer function
void print_buffer() {
    printf("--- Interrupt Triggered ---\n");
    for (int i = 0; i < 10; i++) {
        int index = (buffer_index - 1 - i + BUFFER_SIZE) % BUFFER_SIZE;
        printf("Sample %d: X=%d, Y=%d, Z=%d\n", i + 1, circular_buffer[index].x, circular_buffer[index].y, circular_buffer[index].z);
    }
    printf("-------------------------\n");
}

// Signal handler function
void signal_handler(int sig) {
    printf("Caught signal %d, exiting gracefully...\n", sig);
    program_running = 0;
}

int main() {
    // Open I2C device
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C device: %s\n", strerror(errno));
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, LSM303D_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

