#define INT1_DURATION 0x33
#define OUT_X_L_A 0x28

// GPIO pin for INT1 interrupt
#define INT1_GPIO 23

// Circular buffer size
#define BUFFER_SIZE 64

// Structure to hold acceleration data
typedef struct {
    int16_t x;
    int16_t y;
    int16_t z;
} acceleration_data_t;

// Global variables
int i2c_fd;
struct gpiod_chip *gpio_chip;
struct gpiod_line *gpio_line;
struct gpiod_line_request_config config;
int buffer_index = 0;
acceleration_data_t circular_buffer[BUFFER_SIZE];
volatile sig_atomic_t program_running = 1;

// Function prototypes
int i2c_read_byte(int reg);
int i2c_write_byte(int reg, int value);
int i2c_read_block(int reg, uint8_t *data, int len);
int i2c_write_block(int reg, uint8_t *data, int len);
int lsm303d_init();
void interrupt_handler(int line, struct gpiod_line *gpio_line, struct gpiod_line_event *event);
void print_buffer();
void signal_handler(int sig);

// I2C read byte function
int i2c_read_byte(int reg) {
    int result = i2c_smbus_read_byte_data(i2c_fd, reg);
    if (result < 0) {
        fprintf(stderr, "Error reading register 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    return result;
}

// I2C write byte function
int i2c_write_byte(int reg, int value) {
    int result = i2c_smbus_write_byte_data(i2c_fd, reg, value);
    if (result < 0) {
        fprintf(stderr, "Error writing 0x%02X to register 0x%02X: %s\n", value, reg, strerror(errno));
        return -1;
    }
    return 0;
}

// I2C read block function
int i2c_read_block(int reg, uint8_t *data, int len) {
    int result = i2c_smbus_read_i2c_block_data(i2c_fd, reg, (char *)data, len);
    if (result < 0) {
        fprintf(stderr, "Error reading block from register 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

// I2C write block function
int i2c_write_block(int reg, uint8_t *data, int len) {
    int result = i2c_smbus_write_i2c_block_data(i2c_fd, reg, (char *)data, len);
    if (result < 0) {
        fprintf(stderr, "Error writing block to register 0x%02X: %s\n", reg, strerror(errno));
