#include <errno.h>

// Define GPIO pins for solenoids
#define SOLENOID_1_GPIO 17
#define SOLENOID_2_GPIO 27

// Define chip name
#define GPIO_CHIP "gpiochip0"

// Global variables for GPIO lines and chip
struct gpiod_line *solenoid_1_line = NULL;
struct gpiod_line *solenoid_2_line = NULL;
struct gpiod_chip *gpio_chip = NULL;

// Function prototypes
int initialize_gpio(void);
int control_solenoid(int gpio_pin, int state);
void cleanup_gpio(void);
void signal_handler(int sig);

// Structure to hold GPIO configuration
typedef struct {
    int solenoid_1_gpio;
    int solenoid_2_gpio;
    const char *gpio_chip_name;
} gpio_config_t;

// Signal handler function
void signal_handler(int sig) {
    fprintf(stderr, "\nCaught signal %d, cleaning up...\n", sig);
    cleanup_gpio();
    exit(0);
}

// Function to initialize GPIO lines
int initialize_gpio(void) {
    int ret;

    // Open GPIO chip
    gpio_chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!gpio_chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", GPIO_CHIP);
        return -1;
    }

    // Get line for solenoid 1
    solenoid_1_line = gpiod_chip_get_line(gpio_chip, SOLENOID_1_GPIO);
    if (!solenoid_1_line) {
        fprintf(stderr, "Error getting line for solenoid 1 (GPIO %d)\n", SOLENOID_1_GPIO);
        goto cleanup_chip;
    }

    // Get line for solenoid 2
    solenoid_2_line = gpiod_chip_get_line(gpio_chip, SOLENOID_2_GPIO);
    if (!solenoid_2_line) {
        fprintf(stderr, "Error getting line for solenoid 2 (GPIO %d)\n", SOLENOID_2_GPIO);
        goto cleanup_line_1;
    }

    // Request lines for output
    ret = gpiod_line_request_output(solenoid_1_line, "solenoid_1", 0);
    if (ret < 0) {
        fprintf(stderr, "Error requesting solenoid 1 line for output: %s\n", strerror(-ret));
        goto cleanup_line_2;
    }

    ret = gpiod_line_request_output(solenoid_2_line, "solenoid_2", 0);
    if (ret < 0) {
        fprintf(stderr, "Error requesting solenoid 2 line for output: %s\n", strerror(-ret));
        goto cleanup_solenoid_1;
    }

    // Set initial state to LOW (de-energized)
    if (control_solenoid(SOLENOID_1_GPIO, 0) != 0) {
        fprintf(stderr, "Error setting solenoid 1 LOW\n");
        goto cleanup_solenoid_2;
    }
    if (control_solenoid(SOLENOID_2_GPIO, 0) != 0) {
        fprintf(stderr, "Error setting solenoid 2 LOW\n");
        goto cleanup_solenoid_2;
    }

    return 0;

cleanup_solenoid_2:
    gpiod_line_release(solenoid_2_line);
cleanup_solenoid_1:
    gpiod_line_release(solenoid_1_line);
cleanup_line_2:
    gpiod_chip_close(gpio_chip);
cleanup_chip:
    if (gpio_chip) {
        gpiod_chip_close(gpio_chip);
    }
    return -1;
}

// Function to control solenoid state
int control_solenoid(int gpio_pin, int state) {
    int ret;
    struct gpiod_line *line;

    if (gpio_pin == SOLENOID_1_GPIO) {
        line = solenoid_1_line;
    } else if (gpio_pin == SOLENOID_2_GPIO) {
        line = solenoid_2_line;
    } else {
        fprintf(stderr, "Invalid GPIO pin: %d\n", gpio_pin);
        return -1;
    }

    ret = gpiod_line_set_value(line, state);
    if (ret < 0) {
        fprintf(stderr, "Error setting GPIO %d to %d: %s\n", gpio_pin, state, strerror(-ret));
        return -1;
    }

    return 0;
}

// Function to cleanup GPIO lines and chip
void cleanup_gpio(void) {
    if (solenoid_1_line) {
        gpiod_line_release(solenoid_1_line);
    }
    if (solenoid_2_line) {
        gpiod_line_release(solenoid_2_line);
    }
    if (gpio_chip) {
        gpiod_chip_close(gpio_chip);
    }
}

int main(void) {
    struct timespec sleep_time;

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return 1;
    }

    // Main loop
    sleep_time.tv_sec = 0;
    sleep_time.tv_nsec = 500000000; // 500 ms

    while (1) {
        // Energize solenoid 1
        if (control_solenoid(SOLENOID_1_GPIO, 1) != 0) {
            fprintf(stderr, "Error energizing solenoid 1\n");
            cleanup_gpio();
            return 1;
        }
        nanosleep(&sleep_time, NULL);

        // De-energize solenoid 1, energize solenoid 2
        if (control_solenoid(SOLENOID_1_GPIO, 0) != 0) {
            fprintf(stderr, "Error de-energizing solenoid 1\n");
            cleanup_gpio();
            return 1;
        }
        if (control_solenoid(SOLENOID_2_GPIO, 1) != 0) {
            fprintf(stderr, "Error energizing solenoid 2\n");
            cleanup_gpio();
            return 1;
        }
        nanosleep(&sleep_time, NULL);

        // De-energize solenoid 2
        if (control_solenoid(SOLENOID_2_GPIO, 0) != 0) {
            fprintf(stderr, "Error de-energizing solenoid 2\n");
            cleanup_gpio();
            return 1;
        }
        nanosleep(&sleep_time, NULL);
    }

    return 0;
}

