#include <pigpio.h>
#include <time.h>

// Define GPIO pins for door locks
#define LOCK1_GPIO 17
#define LOCK2_GPIO 27

// Define UART ports
#define UART1_PORT "/dev/serial0"
#define UART2_PORT "/dev/serial1"

// Define expected code
#define EXPECTED_CODE "123456"

// Define timeout duration (seconds)
#define TIMEOUT_DURATION 5

// Global variables for serial port file descriptors and program state
int uart1_fd = -1;
int uart2_fd = -1;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize_gpio();
int open_serial_port(const char *port);
int read_serial_data(int fd, char *buffer, size_t buffer_size);
int validate_code(const char *code);
int unlock_doors();
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(LOCK1_GPIO, PI_OUTPUT);
    gpioSetMode(LOCK2_GPIO, PI_OUTPUT);
    gpioWrite(LOCK1_GPIO, 0); // Initially locked
    gpioWrite(LOCK2_GPIO, 0); // Initially locked

    return 0;
}

// Open a serial port
int open_serial_port(const char *port) {
    int fd = open(port, O_RDWR | O_NOCTTY | O_NONBLOCK);
    if (fd == -1) {
        perror("Error opening serial port");
        return -1;
    }

    struct termios tty;
    if (tcgetattr(fd, &tty) != 0) {
        perror("Error getting termios attributes");
        close(fd);
        return -1;
    }

    tty.c_cflag = B9600 | CS8 | CLOCAL | CREAD;  // 9600 baud, 8 data bits, no parity, 1 stop bit
    tty.c_iflag = IGNPAR; // Ignore parity errors
