    }

    // Convert data to temperature and humidity
    int humidity_raw = (data[0] << 8) | data[1];
    int temperature_raw = (data[2] << 8) | data[3];

    *humidity = (float)humidity_raw / 10.0;
    *temperature = (float)temperature_raw / 10.0;

    return 0;
}

// PIR sensor interrupt handler
void motion_detected(void) {
    static unsigned long last_interrupt_time = 0;
    struct timespec now;
    clock_gettime(CLOCK_MONOTONIC, &now);
    unsigned long current_time = now.tv_sec * 1000 + now.tv_nsec / 1000000;

    // Debounce the interrupt
    if (current_time - last_interrupt_time < MOTION_DETECT_DELAY_MS) {
        syslog(LOG_DEBUG, "Motion interrupt debounced");
        return;
    }
    last_interrupt_time = current_time;

    syslog(LOG_INFO, "Motion detected!");
    relay_on();
}

// Relay control functions
void relay_on(void) {
    int ret = gpiod_line_set_value(relay_line, 1);
    if (ret < 0) {
        syslog(LOG_ERR, "Failed to set relay HIGH: %s", strerror(-ret));
    } else {
        syslog(LOG_INFO, "Relay ON");
    }
}

void relay_off(void) {
    int ret = gpiod_line_set_value(relay_line, 0);
    if (ret < 0) {
        syslog(LOG_ERR, "Failed to set relay LOW: %s", strerror(-ret));
    } else {
        syslog(LOG_INFO, "Relay OFF");
    }
}

// Failsafe mechanism
void failsafe(void) {
    syslog(LOG_WARNING, "Failsafe triggered: PIR sensor HIGH for too long");
    relay_off();
}

// Signal handler for clean shutdown
void signal_handler(int sig) {
    syslog(LOG_INFO, "Signal received, shutting down...");
    running = 0;
}

// Cleanup function
void cleanup(void) {
    syslog(LOG_INFO, "Cleaning up...");

    if (relay_line) {
        gpiod_line_set_value(relay_line, 0); // Ensure relay is off
        gpiod_line_release(relay_line);
    }
    if (pir_line) {
        gpiod_line_release(pir_line);
    }
    if (gpio_chip) {
        gpiod_chip_close(gpio_chip);
    }
    if (i2c_fd != -1) {
        close(i2c_fd);
    }

    closelog();
    exit(0);
}

// Initialize GPIO
int init_gpio(void) {
    gpio_chip = gpiod_chip_open_by_name("gpiochip0");
    if (!gpio_chip) {
        syslog(LOG_ERR, "Failed to open GPIO chip: %s", strerror(errno));
        return -1;
    }

    pir_line = gpiod_chip_get_line(gpio_chip, PIR_GPIO);
    if (!pir_line) {
        syslog(LOG_ERR, "Failed to get PIR GPIO line: %s", strerror(errno));
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    relay_line = gpiod_chip_get_line(gpio_chip, RELAY_GPIO);
    if (!relay_line) {
        syslog(LOG_ERR, "Failed to get relay GPIO line: %s", strerror(errno));
        gpiod_chip_close(gpio_chip);
        gpiod_line_release(pir_line);
        return -1;
    }

    struct gpiod_line_request_config pir_config;
    memset(&pir_config, 0, sizeof(pir_config));
    pir_config.consumer = "motion_sensor";
    pir_config.request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT;

    struct gpiod_line_request_config relay_config;
    memset(&relay_config, 0, sizeof(relay_config));
    relay_config.consumer = "relay_control";
    relay_config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;

    int ret = gpiod_line_request(pir_line, &pir_config, 0);
    if (ret < 0) {
        syslog(LOG_ERR, "Failed to request PIR line: %s", strerror(-ret));
        gpiod_chip_close(gpio_chip);
        gpiod_line_release(pir_line);
        gpiod_line_release(relay_line);
        return -1;
    }

    ret = gpiod_line_request(relay_line, &relay_config, 0);
    if (ret < 0) {
        syslog(LOG_ERR, "Failed to request relay line: %s", strerror(-ret));
        gpiod_chip_close(gpio_chip);
        gpiod_line_release(pir_line);
        gpiod_line_release(relay_line);
        return -1;
    }

    return 0;
}

// Initialize I2C
int init_i2c(int address) {
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        syslog(LOG_ERR, "Failed to open I2C bus: %s", strerror(errno));
        return -1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, address) < 0) {
        syslog(LOG_ERR, "Failed to set I2C slave address: %s", strerror(errno));
        close(i2c_fd);
        return -1;
    }

    return 0;
}

int main(int argc, char *argv[]) {
    openlog("motion_relay", LOG_PID | LOG_CONS, LOG_USER);

    if (argc > 1) {
        i2c_address = strtol(argv[1], NULL, 0);
        syslog(LOG_INFO, "Using I2C address: 0x%02x", i2c_address);
    }

    if (init_gpio() != 0) {
        syslog(LOG_ERR, "GPIO initialization failed");
        closelog();
        return 1;
    }

    if (init_i2c(i2c_address) != 0) {
        syslog(LOG_ERR, "I2C initialization failed");
        cleanup();
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    syslog(LOG_INFO, "System started");

    float temperature, humidity;
    struct timespec ts;
    ts.tv_sec = 0;
    ts.tv_nsec = 100000000; // 100ms

    while (running) {
        int pir_value = gpiod_line_get_value(pir_line);
        if (pir_value < 0) {
            syslog(LOG_ERR, "Failed to read PIR value: %s", strerror(-pir_value));
            break;
        }

        if (pir_value == 1) {
            motion_detected();
        } else {
            relay_off();
        }

        if (read_dht22(&temperature, &humidity) == 0) {
            syslog(LOG_INFO, "Temperature: %.1f°C, Humidity: %.1f%%", temperature, humidity);
        } else {
            syslog(LOG_ERR, "Failed to read DHT22 sensor");
        }

        nanosleep(&ts, NULL);
    }

    cleanup();
    return 0;
}

