#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <syslog.h>
#include <time.h>
#include <pigpio.h>
#include <pthread.h>
#include <unistd.h>

// Define GPIO pins for the relays
#define RELAY1_PIN 4
#define RELAY2_PIN 17
#define RELAY3_PIN 27
#define RELAY4_PIN 22

// Define the timer interval (in seconds)
#define TIMER_INTERVAL 60

// Define the relay activation duration (in seconds)
#define RELAY_DURATION 300

// Define the pause duration (in seconds)
#define PAUSE_DURATION 60

// Define the number of relays
#define NUM_RELAYS 4

// Structure to hold relay state and timer information
typedef struct {
    int relay_pins[NUM_RELAYS];
    int current_relay;
    int timer_id;
    volatile sig_atomic_t running;
    pthread_mutex_t mutex;
} IrrigationSystem;

// Global instance of the IrrigationSystem struct
IrrigationSystem irrigation_system;

// Function prototypes
void signal_handler(int signal);
void timer_callback(int timer, void *user_data);
void activate_relay(int relay_pin);
void deactivate_relay(int relay_pin);
void log_event(const char *message);

// Signal handler function
void signal_handler(int signal) {
    log_event("Signal received, shutting down...");
    irrigation_system.running = 0; // Stop the main loop

    // Deactivate all relays
    for (int i = 0; i < NUM_RELAYS; i++) {
        deactivate_relay(irrigation_system.relay_pins[i]);
    }

    // Cancel the timer
    gpioSetTimerFuncEx(0, 0, NULL, NULL);

    // Release GPIO resources
    gpioTerminate();

    // Close syslog
    closelog();

    // Exit the program
    exit(0);
}

// Timer callback function
void timer_callback(int timer, void *user_data) {
    IrrigationSystem *system = (IrrigationSystem *)user_data;
    pthread_mutex_lock(&system->mutex);

    if (system->current_relay < NUM_RELAYS) {
        // Activate the current relay
        activate_relay(system->relay_pins[system->current_relay]);
        char message[100];
        snprintf(message, sizeof(message), "Relay %d activated", system->current_relay + 1);
        log_event(message);

        // Increment the current relay index
        system->current_relay++;

        // Wait for the relay activation duration
        gpioDelay(RELAY_DURATION * 1000000); // Convert seconds to microseconds

        // Deactivate the current relay
        deactivate_relay(system->relay_pins[system->current_relay - 1]);
        snprintf(message, sizeof(message), "Relay %d deactivated", system->current_relay);
        log_event(message);

        // Decrement the current relay index to point to the previously activated relay
        system->current_relay--;

        // Wait for the pause duration
        gpioDelay(PAUSE_DURATION * 1000000); // Convert seconds to microseconds
    } else {
        // Reset the current relay index to 0 to start the sequence again
        system->current_relay = 0;
    }

    pthread_mutex_unlock(&system->mutex);
}

// Function to activate a relay
void activate_relay(int relay_pin) {
    gpioWrite(relay_pin, 0); // Active-LOW
}

// Function to deactivate a relay
void deactivate_relay(int relay_pin) {
    gpioWrite(relay_pin, 1); // Active-LOW
}

// Function to log events to syslog
void log_event(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    syslog(LOG_INFO, "%s: %s", timestamp, message);
}

int main() {
    // Initialize syslog
    openlog("irrigation_system", LOG_PID | LOG_CONS, LOG_USER);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        log_event("pigpio initialisation failed");
        closelog();
        return 1;
    }

    // Set GPIO pins as outputs
    for (int i = 0; i < NUM_RELAYS; i++) {
        gpioSetMode(irrigation_system.relay_pins[i], PI_OUTPUT);
        deactivate_relay(irrigation_system.relay_pins[i]); // Initialize all relays to OFF
    }

    // Initialize the IrrigationSystem struct
    irrigation_system.relay_pins[0] = RELAY1_PIN;
    irrigation_system.relay_pins[1] = RELAY2_PIN;
    irrigation_system.relay_pins[2] = RELAY3_PIN;
    irrigation_system.relay_pins[3] = RELAY4_PIN;
    irrigation_system.current_relay = 0;
    irrigation_system.running = 1;
    pthread_mutex_init(&irrigation_system.mutex, NULL);

    // Set up signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Set up the timer
    irrigation_system.timer_id = 0; // Timer ID is always 0 for gpioSetTimerFuncEx
    if (gpioSetTimerFuncEx(irrigation_system.timer_id, TIMER_INTERVAL * 1000000, timer_callback, &irrigation_system) != 0) {
        log_event("Failed to set timer function");
        gpioTerminate();
        closelog();
        return 1;
    }

    // Main loop
    while (irrigation_system.running) {
        sleep(1); // Keep the program alive and responsive to signals
    }

    // Cleanup (should not reach here if signal handler works correctly)
    gpioSetTimerFuncEx(irrigation_system.timer_id, 0, NULL, NULL); // Cancel the timer
    pthread_mutex_destroy(&irrigation_system.mutex);
    gpioTerminate();
    closelog();

    return 0;
}

