#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <time.h>
#include <sys/time.h>
#include <pthread.h>
#include <errno.h>

// MPU6050 I2C address
#define MPU6050_ADDR 0x68

// MPU6050 registers
#define PWR_MGMT_1 0x6B
#define ACCEL_CONFIG 0x1C
#define ACCEL_XOUT_H 0x3B

// Scaling factor for accelerometer data
#define ACCEL_SCALE 16384.0f

// Circular buffer size
#define BUFFER_SIZE 100

// Structure to hold acceleration data
typedef struct {
    float x;
    float y;
    float z;
} AccelData;

// Global variables
int i2c_fd;
AccelData accel_buffer[BUFFER_SIZE];
int buffer_index = 0;
int buffer_count = 0;
pthread_mutex_t buffer_mutex = PTHREAD_MUTEX_INITIALIZER;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int init_i2c(int bus, int addr);
int init_mpu6050(int fd);
int read_accel_data(int fd, AccelData *data);
void add_to_buffer(AccelData data);
AccelData get_latest_data();
void signal_handler(int sig);
void *timer_thread(void *arg);

// Function to initialize I2C
int init_i2c(int bus, int addr) {
    char filename[20];
    snprintf(filename, 19, "/dev/i2c-%d", bus);
    int fd = open(filename, O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C device");
        return -1;
    }
    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        perror("Error setting I2C slave address");
        close(fd);
        return -1;
    }
    return fd;
}

// Function to initialize MPU6050
int init_mpu6050(int fd) {
    uint8_t init_data[] = {
        PWR_MGMT_1, 0x00, // Wake up the MPU6050
        ACCEL_CONFIG, 0x00  // Set accelerometer range to +-2g
    };
    if (write(fd, init_data, sizeof(init_data)) != sizeof(init_data)) {
        perror("Error writing to MPU6050");
        return -1;
    }
    return 0;
}

// Function to read accelerometer data
int read_accel_data(int fd, AccelData *data) {
    uint8_t buffer[6];
    if (read(fd, buffer, 6) != 6) {
        perror("Error reading accelerometer data");
        return -1;
    }

    // Combine high and low bytes for each axis
    int16_t x = (buffer[0] << 8) | buffer[1];
    int16_t y = (buffer[2] << 8) | buffer[3];
    int16_t z = (buffer[4] << 8) | buffer[5];

    // Scale to g
    data->x = (float)x / ACCEL_SCALE;
    data->y = (float)y / ACCEL_SCALE;
    data->z = (float)z / ACCEL_SCALE;

    return 0;
}

// Function to add data to the circular buffer
void add_to_buffer(AccelData data) {
    pthread_mutex_lock(&buffer_mutex);
    accel_buffer[buffer_index] = data;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
    if (buffer_count < BUFFER_SIZE) {
        buffer_count++;
    }
    pthread_mutex_unlock(&buffer_mutex);
}

// Function to get the latest data from the circular buffer
AccelData get_latest_data() {
    AccelData latest_data = accel_buffer[buffer_index];
    return latest_data;
}

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    program_running = 0;
    printf("Caught signal %d, exiting...\n", sig);
}

// Timer thread function
void *timer_thread(void *arg) {
    struct sigaction sa;
    struct itimerspec its;
    struct sigevent sev;
    struct sigaction old_sa;
    int timer_id;

    // Set up signal handler for SIGALRM
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGALRM, &sa, &old_sa) == -1) {
        perror("sigaction");
        pthread_exit(NULL);
    }

    // Set up timer
    timer_id = 0; // Use timer ID 0
    sev.sigev_notify = SIGEV_SIGNAL;
    sev.sigev_signo = SIGALRM;
    sev.sigev_value.sival_ptr = &timer_id;

    struct sigaction sa_timer;
    memset(&sa_timer, 0, sizeof(sa_timer));
    sa_timer.sa_handler = signal_handler;
    sigemptyset(&sa_timer.sa_mask);
    sa_timer.sa_flags = 0;
    if (sigaction(SIGALRM, &sa_timer, NULL) == -1) {
        perror("sigaction");
        pthread_exit(NULL);
    }

    struct sigaction sa_old;
    if (sigaction(SIGALRM, NULL, &sa_old) == -1) {
        perror("sigaction");
        pthread_exit(NULL);
    }

    struct sigaction sa_new;
    memset(&sa_new, 0, sizeof(sa_new));
    sa_new.sa_handler = signal_handler;
    sigemptyset(&sa_new.sa_mask);
    sa_new.sa_flags = 0;
    if (sigaction(SIGALRM, &sa_new, NULL) == -1) {
        perror("sigaction");
        pthread_exit(NULL);
    }

    while (program_running) {
        // Set timer interval to 10 ms (100 Hz)
        its.it_value.tv_sec = 0;
        its.it_value.tv_nsec = 10000000; // 10 ms
        its.it_interval.tv_sec = 0;
        its.it_interval.tv_nsec = 10000000; // 10 ms

        if (timer_settime(timer_id, 0, &its, NULL) == -1) {
            perror("timer_settime");
            break;
        }

        pause(); // Wait for signal
    }

    // Disable the timer
    its.it_value.tv_sec = 0;
    its.it_value.tv_nsec = 0;
    its.it_interval.tv_sec = 0;
    its.it_interval.tv_nsec = 0;
    if (timer_settime(timer_id, 0, &its, NULL) == -1) {
        perror("timer_settime");
    }

    // Restore the original signal handler
    if (sigaction(SIGALRM, &sa_old, NULL) == -1) {
        perror("sigaction");
    }

    pthread_exit(NULL);
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    i2c_fd = init_i2c(1, MPU6050_ADDR);
    if (i2c_fd < 0) {
        return 1;
    }

    // Initialize MPU6050
    if (init_mpu6050(i2c_fd) < 0) {
        close(i2c_fd);
        return 1;
    }

    // Create timer thread
    pthread_t timer_thread_id;
    if (pthread_create(&timer_thread_id, NULL, timer_thread, NULL) != 0) {
        perror("pthread_create");
        close(i2c_fd);
        return 1;
    }

    // Create sysfs interface
    FILE *latest_data_file = fopen("/sys/kernel/mpu6050_accel/latest", "w");
    if (latest_data_file == NULL) {
        perror("fopen");
        close(i2c_fd);
        pthread_join(timer_thread_id, NULL);
        return 1;
    }

    FILE *buffer_size_file = fopen("/sys/kernel/mpu6050_accel/buffer_size", "w");
    if (buffer_size_file == NULL) {
        perror("fopen");
        fclose(latest_data_file);
        close(i2c_fd);
        pthread_join(timer_thread_id, NULL);
        return 1;
    }

    fprintf(buffer_size_file, "%d", BUFFER_SIZE);
    fclose(buffer_size_file);

    // Main loop
    AccelData accel_data;
    while (program_running) {
        if (read_accel_data(i2c_fd, &accel_data) == 0) {
            add_to_buffer(accel_data);

            // Write latest data to sysfs file
            pthread_mutex_lock(&buffer_mutex);
            fprintf(latest_data_file, "%.6f %.6f %.6f\n", accel_data.x, accel_data.y, accel_data.z);
            fflush(latest_data_file);
            pthread_mutex_unlock(&buffer_mutex);
        } else {
            fprintf(stderr, "Error reading accelerometer data. Retrying...\n");
        }
        usleep(1000); // Sleep for 1 ms to avoid busy-waiting
    }

    // Cleanup
    pthread_join(timer_thread_id, NULL);
    fclose(latest_data_file);
    close(i2c_fd);
    pthread_mutex_destroy(&buffer_mutex);

