// Define GPIO pins for the relays
#define RELAY1_PIN 18
#define RELAY2_PIN 23
#define RELAY3_PIN 24
#define RELAY4_PIN 25

// Define GPIO chip name
#define GPIO_CHIP "gpiochip0"

// Global variables for GPIO lines and chip
struct gpiod_line *relay1_line = NULL;
struct gpiod_line *relay2_line = NULL;
struct gpiod_line *relay3_line = NULL;
struct gpiod_line *relay4_line = NULL;
struct gpiod_chip *gpio_chip = NULL;

// Function prototypes
int init_gpio(void);
int set_relay_state(int pin, int state);
int toggle_relay(int pin);
void cleanup_gpio(void);
void signal_handler(int sig);

// Structure to hold relay pin information
typedef struct {
    int pin;
    struct gpiod_line *line;
} relay_t;

// Array of relay structures
relay_t relays[] = {
    {RELAY1_PIN, NULL},
    {RELAY2_PIN, NULL},
    {RELAY3_PIN, NULL},
    {RELAY4_PIN, NULL}
};

int main(void) {
    // Install signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (init_gpio() != 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return 1;
    }

    // Main loop
    while (1) {
        // Toggle relays based on prime number intervals
        toggle_relay(RELAY1_PIN);
        sleep(2);
        toggle_relay(RELAY2_PIN);
        sleep(3);
        toggle_relay(RELAY3_PIN);
        sleep(5);
        toggle_relay(RELAY4_PIN);
        sleep(7);
    }

    return 0;
}

// Initialize GPIO lines and chip
int init_gpio(void) {
    int ret;

    // Open GPIO chip
    gpio_chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!gpio_chip) {
        perror("gpiod_chip_open_by_name");
        return -1;
    }

    // Request GPIO lines for each relay
    relay1_line = gpiod_chip_get_line(gpio_chip, RELAY1_PIN);
    if (!relay1_line) {
        perror("gpiod_chip_get_line (RELAY1_PIN)");
        goto cleanup;
    }

    relay2_line = gpiod_chip_get_line(gpio_chip, RELAY2_PIN);
    if (!relay2_line) {
        perror("gpiod_chip_get_line (RELAY2_PIN)");
        goto cleanup;
    }

    relay3_line = gpiod_chip_get_line(gpio_chip, RELAY3_PIN);
    if (!relay3_line) {
        perror("gpiod_chip_get_line (RELAY3_PIN)");
        goto cleanup;
    }

    relay4_line = gpiod_chip_get_line(gpio_chip, RELAY4_PIN);
    if (!relay4_line) {
        perror("gpiod_chip_get_line (RELAY4_PIN)");
        goto cleanup;
    }

    // Request GPIO lines for output
    ret = gpiod_line_request_output(relay1_line, "relay1", 0);
    if (ret < 0) {
        perror("gpiod_line_request_output (RELAY1_PIN)");
        goto cleanup;
    }

    ret = gpiod_line_request_output(relay2_line, "relay2", 0);
    if (ret < 0) {
        perror("gpiod_line_request_output (RELAY2_PIN)");
        goto cleanup;
    }

    ret = gpiod_line_request_output(relay3_line, "relay3", 0);
    if (ret < 0) {
        perror("gpiod_line_request_output (RELAY3_PIN)");
        goto cleanup;
    }

    ret = gpiod_line_request_output(relay4_line, "relay4", 0);
    if (ret < 0) {
        perror("gpiod_line_request_output (RELAY4_PIN)");
        goto cleanup;
    }

    return 0;

cleanup:
    cleanup_gpio();
    return -1;
}

// Set the state of a relay (0 = off, 1 = on)
int set_relay_state(int pin, int state) {
    int ret;
    struct gpiod_line *line = NULL;

    // Find the relay line based on the pin number
    for (int i = 0; i < sizeof(relays) / sizeof(relays[0]); i++) {
        if (relays[i].pin == pin) {
            line = relays[i].line;
            break;
        }
    }

    if (line == NULL) {
        fprintf(stderr, "Error: Relay pin %d not found.\n", pin);
        return -1;
    }

    // Set the line value
    ret = gpiod_line_set_value(line, state);
    if (ret < 0) {
        perror("gpiod_line_set_value");
        return -1;
    }

    return 0;
}

// Toggle the state of a relay
int toggle_relay(int pin) {
    int current_state;
    int new_state;

    // Get the current state of the relay
    current_state = gpiod_line_get_value(relays[pin == RELAY1_PIN ? 0 : (pin == RELAY2_PIN ? 1 : (pin == RELAY3_PIN ? 2 : 3)).line);
    if (current_state < 0) {
        perror("gpiod_line_get_value");
        return -1;
    }

    // Toggle the state
    new_state = !current_state;

    // Set the new state
    if (set_relay_state(pin, new_state) != 0) {
        fprintf(stderr, "Error toggling relay on pin %d.\n", pin);
        return -1;
    }

    return 0;
}

// Cleanup GPIO resources
void cleanup_gpio(void) {
    int ret;

    // Release GPIO lines
    if (relay1_line) {
        ret = gpiod_line_release(relay1_line);
        if (ret < 0) {
            perror("gpiod_line_release (RELAY1_PIN)");
        }
        relay1_line = NULL;
    }
    if (relay2_line) {
        ret = gpiod_line_release(relay2_line);
        if (ret < 0) {
            perror("gpiod_line_release (RELAY2_PIN)");
        }
        relay2_line = NULL;
    }
    if (relay3_line) {
        ret = gpiod_line_release(relay3_line);
        if (ret < 0) {
            perror("gpiod_line_release (RELAY3_PIN)");
        }
        relay3_line = NULL;
    }
    if (relay4_line) {
        ret = gpiod_line_release(relay4_line);
        if (ret < 0) {
            perror("gpiod_line_release (RELAY4_PIN)");
        }
        relay4_line = NULL;
    }

    // Close GPIO chip
    if (gpio_chip) {
        ret = gpiod_chip_close(gpio_chip);
        if (ret < 0) {
            perror("gpiod_chip_close");
        }
        gpio_chip = NULL;
    }
}

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    printf("Signal received (%d). Shutting down gracefully...\n", sig);

    // Turn off all relays
    set_relay_state(RELAY1_PIN, 0);
    set_relay_state(RELAY2_PIN, 0);
    set_relay_state(RELAY3_PIN, 0);
    set_relay_state(RELAY4_PIN, 0);

    // Cleanup GPIO resources
    cleanup_gpio();

    exit(0);
}

