#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <math.h>
#include <signal.h>
#include <string.h>

// MPU-6050 I2C address
#define MPU6050_ADDR 0x68

// MPU-6050 registers
#define PWR_MGMT_1 0x6B
#define WHO_AM_I 0x75
#define GYRO_XOUT_H 0x43

// Gyroscope sensitivity (for +-250 dps range)
#define GYRO_SENSITIVITY 131.0

// Angular velocity threshold (degrees/second)
#define VELOCITY_THRESHOLD 50.0

// Circular buffer size
#define BUFFER_SIZE 100

// Structure to hold gyroscope data
typedef struct {
    float x;
    float y;
    float z;
} GyroData;

// Global variables
int i2c_fd;
volatile sig_atomic_t program_running = 1;

// Circular buffer
GyroData gyro_buffer[BUFFER_SIZE];
int buffer_index = 0;

// Function prototypes
int init_i2c();
int init_mpu6050();
int read_gyro_data(int16_t *x, int16_t *y, int16_t *z);
float process_gyro_data(int16_t raw_x, int16_t raw_y, int16_t raw_z);
void add_to_buffer(float x, float y, float z);
float calculate_magnitude(float x, float y, float z);
void velocity_exceeded_callback(float x, float y, float z);
void signal_handler(int signum);

// Signal handler for graceful shutdown
void signal_handler(int signum) {
    if (signum == SIGINT) {
        printf("\nCaught SIGINT, exiting gracefully...\n");
        program_running = 0;
    }
}

// Initialize I2C communication
int init_i2c() {
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Error opening I2C device");
        return -1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        perror("Error setting I2C slave address");
        close(i2c_fd);
        return -1;
    }

    return 0;
}

// Initialize MPU-6050
int init_mpu6050() {
    // Wake up the MPU-6050 (clear sleep bit)
    uint8_t wake_up_data = 0x00;
    if (write(i2c_fd, &wake_up_data, 1) != 1) {
        perror("Error writing to PWR_MGMT_1 register");
        return -1;
    }
    usleep(10000); // Wait for the sensor to wake up

    // Verify device ID
    uint8_t who_am_i;
    if (write(i2c_fd, &WHO_AM_I, 1) != 1) {
        perror("Error writing to WHO_AM_I register");
        return -1;
    }
    if (read(i2c_fd, &who_am_i, 1) != 1) {
        perror("Error reading WHO_AM_I register");
        return -1;
    }

    if (who_am_i != 0x68) {
        fprintf(stderr, "Error: Incorrect WHO_AM_I value: 0x%02X\n", who_am_i);
        return -1;
    }

    printf("MPU-6050 initialized successfully.\n");
    return 0;
}

// Read raw gyroscope data
int read_gyro_data(int16_t *x, int16_t *y, int16_t *z) {
    uint8_t gyro_data[6];

    if (write(i2c_fd, &GYRO_XOUT_H, 1) != 1) {
        perror("Error writing to GYRO_XOUT_H register");
        return -1;
    }

    if (read(i2c_fd, gyro_data, 6) != 6) {
        perror("Error reading gyroscope data");
        return -1;
    }

    *x = (int16_t)((gyro_data[0] << 8) | gyro_data[1]);
    *y = (int16_t)((gyro_data[2] << 8) | gyro_data[3]);
    *z = (int16_t)((gyro_data[4] << 8) | gyro_data[5]);

    return 0;
}

// Process raw gyroscope data and convert to degrees/second
float process_gyro_data(int16_t raw_x, int16_t raw_y, int16_t raw_z) {
    float x = (float)raw_x / GYRO_SENSITIVITY;
    float y = (float)raw_y / GYRO_SENSITIVITY;
    float z = (float)raw_z / GYRO_SENSITIVITY;
    return x;
}

// Add data to the circular buffer
void add_to_buffer(float x, float y, float z) {
    gyro_buffer[buffer_index].x = x;
    gyro_buffer[buffer_index].y = y;
    gyro_buffer[buffer_index].z = z;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

// Calculate the magnitude of the angular velocity vector
float calculate_magnitude(float x, float y, float z) {
    return sqrt(x * x + y * y + z * z);
}

// Callback function for when velocity exceeds the threshold
void velocity_exceeded_callback(float x, float y, float z) {
    printf("Velocity exceeded threshold!\n");
    printf("X: %.2f deg/s, Y: %.2f deg/s, Z: %.2f deg/s\n", x, y, z);
}

int main() {
    // Install signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize I2C
    if (init_i2c() < 0) {
        return 1;
    }

    // Initialize MPU-6050
    if (init_mpu6050() < 0) {
        close(i2c_fd);
        return 1;
    }

    int16_t raw_x, raw_y, raw_z;
    float x, y, z, magnitude;

    printf("Starting data acquisition...\n");

    while (program_running) {
        // Read gyroscope data
        if (read_gyro_data(&raw_x, &raw_y, &raw_z) == 0) {
            // Process gyroscope data
            x = process_gyro_data(raw_x, raw_y, raw_z);
            y = process_gyro_data(raw_y, raw_z, raw_x);
            z = process_gyro_data(raw_z, raw_x, raw_y);

            // Add data to the circular buffer
            add_to_buffer(x, y, z);

            // Calculate the magnitude of the angular velocity vector
            magnitude = calculate_magnitude(x, y, z);

            // Check if the velocity exceeds the threshold
            if (magnitude > VELOCITY_THRESHOLD) {
                velocity_exceeded_callback(x, y, z);
            }
        } else {
            fprintf(stderr, "Error reading gyroscope data. Retrying...\n");
        }

        usleep(10000); // Delay for 10ms
    }

    // Close I2C device
    close(i2c_fd);

    printf("Program finished.\n");
    return 0;
}

