#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define UART_DEVICE "/dev/serial0"
#define BAUD_RATE 9600
#define CO2_COMMAND_LENGTH 9
#define CO2_COMMAND {0xFF, 0x01, 0x86, 0x00, 0x00, 0x00, 0x00, 0x00, 0x79}
#define READ_TIMEOUT_MS 1000
#define CO2_LOG_FILE "co2_log.json"
#define ERROR_LOG_FILE "co2_error.log"

int uart_handle;
volatile sig_atomic_t terminate = 0;

// Function to handle signals (SIGINT, SIGTERM)
void signal_handler(int sig) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", sig);
}

// Function to initialize pigpio
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Function to open the UART port
int open_uart(const char *device, int baud_rate) {
    int handle = serOpen(device, baud_rate, 0); //0 for default flags
    if (handle < 0) {
        fprintf(stderr, "Failed to open UART: %s\n", device);
        return -1;
    }
    return handle;
}

// Function to send the CO2 read command
int send_co2_command(int handle) {
    if (serWrite(handle, (char *)CO2_COMMAND, CO2_COMMAND_LENGTH) != CO2_COMMAND_LENGTH) {
        fprintf(stderr, "Failed to send CO2 command\n");
        return -1;
    }
    return 0;
}

// Function to read data from the UART port with timeout
int read_uart_data(int handle, char *buffer, int num_bytes) {
    int bytes_read = 0;
    int start_time = time_time();

    while (bytes_read < num_bytes && (time_time() - start_time) < READ_TIMEOUT_MS) {
        if (serDataAvailable(handle) > 0) {
            int available = serDataAvailable(handle);
            if (available > 0) {
                int result = serRead(handle, buffer + bytes_read, available);
                if (result > 0) {
                    bytes_read += result;
                } else {
                    fprintf(stderr, "Error reading from UART\n");
                    return -1;
                }
            }
        } else {
            gpioDelay(1); // Small delay to avoid busy-waiting
        }
    }

    if (bytes_read != num_bytes) {
        fprintf(stderr, "Timeout reading from UART\n");
        return -1;
    }

    return 0;
}

// Function to calculate the checksum
unsigned char calculate_checksum(const char *data, int length) {
    unsigned char checksum = 0;
    for (int i = 0; i < length; i++) {
        checksum += data[i];
    }
    return (unsigned char)(~checksum + 1);
}

// Function to validate the checksum
int validate_checksum(const char *data, int length) {
    unsigned char calculated_checksum = calculate_checksum(data, length);
    return (calculated_checksum == data[length]);
}

// Function to extract the CO2 concentration
int extract_co2(const char *data) {
    return (data[2] << 8) | data[3];
}

// Function to log data to a file
int log_data(const char *filename, const char *json_string) {
    FILE *fp = fopen(filename, "a");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", filename);
        return -1;
    }

    fprintf(fp, "%s\n", json_string);
    fclose(fp);
    return 0;
}

// Function to log errors to a file
int log_error(const char *filename, const char *error_message) {
    FILE *fp = fopen(filename, "a");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open error log file: %s\n", filename);
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "[%d-%02d-%02d %02d:%02d:%02d] %s\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, error_message);
    fclose(fp);
    return 0;
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (initialize_pigpio() != 0) {
        return 1;
    }

    // Open UART
    uart_handle = open_uart(UART_DEVICE, BAUD_RATE);
    if (uart_handle < 0) {
        gpioTerminate();
        return 1;
    }

    printf("CO2 Monitor started\n");

    while (!terminate) {
        char data[9];

        // Send CO2 read command
        if (send_co2_command(uart_handle) != 0) {
            log_error(ERROR_LOG_FILE, "Failed to send CO2 command");
            gpioDelay(5000); // Wait 5 seconds before retrying
            continue;
        }

        gpioDelay(100); // Wait for sensor to process the command

        // Read data from UART
        if (read_uart_data(uart_handle, data, 9) != 0) {
            log_error(ERROR_LOG_FILE, "Failed to read CO2 data");
            gpioDelay(5000); // Wait 5 seconds before retrying
            continue;
        }

        // Validate checksum
        if (!validate_checksum(data, 8)) {
            log_error(ERROR_LOG_FILE, "Checksum validation failed");
            gpioDelay(5000); // Wait 5 seconds before retrying
            continue;
        }

        // Extract CO2 concentration
        int co2_ppm = extract_co2(data);

        // Get timestamp
        time_t t = time(NULL);
        struct tm tm = *localtime(&t);
        long microseconds = (long)(t * 1000000 + (double)tm.tm_sec * 1000000 + (double)tm.tm_usec);

        // Create JSON string
        char json_string[256];
        snprintf(json_string, sizeof(json_string), "{\"timestamp\":%ld,\"co2_ppm\":%d,\"error\":false}\n", microseconds, co2_ppm);

        // Log data to file
        if (log_data(CO2_LOG_FILE, json_string) != 0) {
            fprintf(stderr, "Failed to log data to file\n");
        }

        // Print JSON to stdout
        printf("%s", json_string);

        gpioDelay(5000); // Wait 5 seconds
    }

    // Close UART
    serClose(uart_handle);

    // Terminate pigpio
    gpioTerminate();

    printf("CO2 Monitor terminated\n");

    return 0;
}

