#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>

// HMC5883L I2C address
#define HMC5883L_ADDR 0x1E

// HMC5883L registers
#define HMC5883L_CONFIG_A 0x00
#define HMC5883L_CONFIG_B 0x01
#define HMC5883L_MODE 0x02
#define HMC5883L_DATA_X_MSB 0x03

// GPIO pin for output
#define GPIO_PIN 17

// Target heading (degrees)
#define TARGET_HEADING 90.0

// Hard-iron offsets
#define X_OFFSET 100.0
#define Y_OFFSET -50.0

// Deviation threshold (degrees)
#define DEVIATION_THRESHOLD 10.0

// I2C bus
#define I2C_BUS 1

// Circular buffer size
#define BUFFER_SIZE 100

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Circular buffer
float heading_buffer[BUFFER_SIZE];
int buffer_index = 0;

// Function prototypes
int initialize_sensor();
int read_magnetometer_data(int16_t *x, int16_t *y, int16_t *z);
float calculate_heading(int16_t x, int16_t y);
void control_gpio(float heading);
void signal_handler(int signal);
void cleanup();

// Signal handler
void signal_handler(int signal) {
    terminate = 1;
    printf("Signal received, cleaning up...\n");
}

// Initialize the HMC5883L sensor
int initialize_sensor() {
    // Configure the sensor
    if (i2cWriteByteData(i2c_handle, HMC5883L_CONFIG_A, 0x70) < 0) {
        fprintf(stderr, "Error writing to CONFIG_A register\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, HMC5883L_CONFIG_B, 0x20) < 0) {
        fprintf(stderr, "Error writing to CONFIG_B register\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, HMC5883L_MODE, 0x00) < 0) {
        fprintf(stderr, "Error writing to MODE register\n");
        return -1;
    }

    return 0;
}

// Read magnetometer data
int read_magnetometer_data(int16_t *x, int16_t *y, int16_t *z) {
    char buffer[6];
    if (i2cReadI2CBlockData(i2c_handle, HMC5883L_DATA_X_MSB, buffer, 6) != 6) {
        fprintf(stderr, "Error reading magnetometer data\n");
        return -1;
    }

    *x = (int16_t)((buffer[0] << 8) | buffer[1]);
    *z = (int16_t)((buffer[2] << 8) | buffer[3]);
    *y = (int16_t)((buffer[4] << 8) | buffer[5]);

    return 0;
}

// Calculate heading in degrees
float calculate_heading(int16_t x, int16_t y) {
    float heading = atan2((float)y, (float)x) * 180 / M_PI;
    if (heading < 0) {
        heading += 360;
    }
    return heading;
}

// Control GPIO based on heading deviation
void control_gpio(float heading) {
    float compensated_heading = calculate_heading(x - X_OFFSET, y - Y_OFFSET);
    float deviation = fabs(compensated_heading - TARGET_HEADING);
    if (deviation > 180) {
        deviation = 360 - deviation;
    }

    if (deviation > DEVIATION_THRESHOLD) {
        gpioWrite(GPIO_PIN, 1); // HIGH
    } else {
        gpioWrite(GPIO_PIN, 0); // LOW
    }
}

// Cleanup resources
void cleanup() {
    gpioWrite(GPIO_PIN, 0); // Set GPIO low
    i2cClose(i2c_handle);
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, HMC5883L_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus\n");
        gpioTerminate();
        return 1;
    }

    // Initialize the sensor
    if (initialize_sensor() < 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        cleanup();
        return 1;
    }

    // Set GPIO pin as output
    gpioSetMode(GPIO_PIN, PI_OUTPUT);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int16_t x, y, z;
    float heading;

    // Main loop
    while (!terminate) {
        // Read magnetometer data
        if (read_magnetometer_data(&x, &y, &z) == 0) {
            // Calculate heading
            heading = calculate_heading(x, y);

            // Control GPIO
            control_gpio(heading);

            // Store heading in circular buffer
            heading_buffer[buffer_index] = heading;
            buffer_index = (buffer_index + 1) % BUFFER_SIZE;

            // Print heading (optional)
            printf("Heading: %.2f degrees\n", heading);
        } else {
            fprintf(stderr, "Failed to read magnetometer data. Retrying...\n");
        }

        // Delay
        gpioDelay(100); // 100 ms
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

