// I2C initialization function
int init_i2c(const char *bus) {
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C bus");
        return -1;
    }
    if (ioctl(fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        perror("Error setting I2C slave address");
        close(fd);
        return -1;
    }
    return fd;
}

// BH1750 initialization function
int init_bh1750(int fd) {
    unsigned char config_mode = 0x10; // Continuous high-resolution mode
    if (write(fd, &config_mode, 1) != 1) {
        perror("Error writing to BH1750");
        return -1;
    }
    usleep(120000); // Wait for conversion (at least 120ms)
    return 0;
}

// BH1750 reading function
int read_lux(int fd) {
    unsigned char buffer[2];
    if (read(fd, buffer, 2) != 2) {
        perror("Error reading from BH1750");
        return -1;
    }
    unsigned int raw_value = (buffer[0] << 8) | buffer[1];
    return raw_value;
}

// GPIO initialization function
int init_gpio(int gpio) {
    struct gpiod_line_request_config config;
    memset(&config, 0, sizeof(config));
    config.consumer = "lighting_system";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;

    struct gpiod_line *line = gpiod_chip_get_line(gpio_chip, gpio);
    if (!line) {
        perror("Error getting GPIO line");
        return -1;
    }

    if (gpiod_line_request(line, &config, 0) < 0) {
        perror("Error requesting GPIO line");
        gpiod_line_release(line);
        return -1;
    }

    return 0;
}

// GPIO value setting function
int set_gpio_value(int gpio, int value) {
    struct gpiod_line *line;

    if (gpio == RED_GPIO) {
        line = red_line;
    } else if (gpio == GREEN_GPIO) {
        line = green_line;
    } else if (gpio == BLUE_GPIO) {
        line = blue_line;
    } else {
        fprintf(stderr, "Invalid GPIO pin: %d\n", gpio);
        return -1;
    }

    if (gpiod_line_set_value(line, value) < 0) {
        perror("Error setting GPIO value");
        return -1;
    }
    return 0;
}

// GPIO cleanup function
void cleanup_gpio(void) {
    if (red_line) {
        gpiod_line_release(red_line);
    }
    if (green_line) {
        gpiod_line_release(green_line);
    }
    if (blue_line) {
        gpiod_line_release(blue_line);
    }
    if (gpio_chip) {
        gpiod_chip_close(gpio_chip);
    }
}

// Signal handler function
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, exiting...\n");
    keep_running = 0;
}

// Logging function
void log_data(time_t timestamp, float lux, int red_state, int green_state, int blue_state) {
    struct tm *timeinfo = localtime(&timestamp);
    char timestamp_str[20];
    strftime(timestamp_str, sizeof(timestamp_str), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, %.2f, %d, %d, %d\n", timestamp_str, lux, red_state, green_state, blue_state);
    fflush(log_file); // Ensure data is written to file immediately
}

int main() {
    // Signal handling setup
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // I2C setup
    i2c_fd = init_i2c(I2C_BUS);
    if (i2c_fd < 0) {
        fprintf(stderr, "I2C initialization failed. Exiting.\n");
        return 1;
    }

    // BH1750 setup
    if (init_bh1750(i2c_fd) < 0) {
        fprintf(stderr, "BH1750 initialization failed. Exiting.\n");
        close(i2c_fd);
        return 1;
    }

    // GPIO setup
    gpio_chip = gpiod_chip_open_by_name("gpiochip0");
    if (!gpio_chip) {
        perror("Error opening GPIO chip");
        close(i2c_fd);
        return 1;
    }

    if (init_gpio(RED_GPIO) < 0 || init_gpio(GREEN_GPIO) < 0 || init_gpio(BLUE_GPIO) < 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        cleanup_gpio();
        close(i2c_fd);
        return 1;
    }

    red_line = gpiod_chip_get_line(gpio_chip, RED_GPIO);
    green_line = gpiod_chip_get_line(gpio_chip, GREEN_GPIO);
    blue_line = gpiod_chip_get_line(gpio_chip, BLUE_GPIO);

    // Logging setup
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Error opening log file");
        cleanup_gpio();
        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (keep_running) {
        int raw_lux = read_lux(i2c_fd);
        if (raw_lux < 0) {
            fprintf(stderr, "Error reading lux value. Retrying in 1 second.\n");
            sleep(1);
            continue;
        }

        float lux = (float)raw_lux / 1.2;

        int red_state = 0, green_state = 0, blue_state = 0;

        if (lux < 50) {
            red_state = 1;
        } else if (lux >= 50 && lux < 150) {
            green_state = 1;
        } else if (lux >= 150 && lux < 300) {
            blue_state = 1;
        } else {
            red_state = 1;
            green_state = 1;
            blue_state = 1;
        }

        set_gpio_value(RED_GPIO, red_state);
        set_gpio_value(GREEN_GPIO, green_state);
        set_gpio_value(BLUE_GPIO, blue_state);

        time_t now = time(NULL);
        log_data(now, lux, red_state, green_state, blue_state);

        sleep(1);
    }

    // Cleanup
    cleanup_gpio();
    close(i2c_fd);
    fclose(log_file);

    return 0;
}

