#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// Motor A
#define MOTOR_A_IN1 17
#define MOTOR_A_IN2 18

// Motor B
#define MOTOR_B_IN3 22
#define MOTOR_B_IN4 23

// PWM frequency
#define PWM_FREQUENCY 1000

// Global flag for graceful shutdown
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT and SIGTERM
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, stopping motors and cleaning up...\n", signal);
}

// Function to set motor direction and speed
void set_motor_speed(int in1, int in2, int distance) {
    int direction = (distance < 50) ? 1 : 0; // 1 for forward, 0 for backward
    int pwm_value = 0;

    if (distance < 10) {
        pwm_value = 255;
    } else if (distance > 100) {
        pwm_value = 0;
    } else {
        pwm_value = 255 - (int)(((float)(distance - 10) / 90.0) * 255.0);
    }

    gpioWrite(in1, direction);
    gpioPWM(in2, pwm_value);
}

int main(int argc, char *argv[]) {
    int motor_a_distance, motor_b_distance;

    // Check for correct number of arguments
    if (argc != 3) {
        fprintf(stderr, "Usage: %s <motor_a_distance> <motor_b_distance>\n", argv[0]);
        return 1;
    }

    // Parse command-line arguments
    motor_a_distance = atoi(argv[1]);
    motor_b_distance = atoi(argv[2]);

    // Validate distance range
    if (motor_a_distance < 10 || motor_a_distance > 100 || motor_b_distance < 10 || motor_b_distance > 100) {
        fprintf(stderr, "Error: Distance values must be between 10 and 100.\n");
        return 1;
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(MOTOR_A_IN1, PI_OUTPUT);
    gpioSetMode(MOTOR_A_IN2, PI_OUTPUT);
    gpioSetMode(MOTOR_B_IN3, PI_OUTPUT);
    gpioSetMode(MOTOR_B_IN4, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(MOTOR_A_IN2, PWM_FREQUENCY);
    gpioSetPWMfrequency(MOTOR_B_IN4, PWM_FREQUENCY);

    // Set PWM range
    gpioSetPWMrange(MOTOR_A_IN2, 255);
    gpioSetPWMrange(MOTOR_B_IN4, 255);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main control loop
    while (program_running) {
        // Set motor A speed
        set_motor_speed(MOTOR_A_IN1, MOTOR_A_IN2, motor_a_distance);

        // Set motor B speed
        set_motor_speed(MOTOR_B_IN3, MOTOR_B_IN4, motor_b_distance);

        // Delay for 100 ms
        gpioDelay(100000); // 100 ms = 100000 us
    }

    // Stop motors
    gpioWrite(MOTOR_A_IN1, 0);
    gpioWrite(MOTOR_A_IN2, 0);
    gpioWrite(MOTOR_B_IN3, 0);
    gpioWrite(MOTOR_B_IN4, 0);

    // Clean up pigpio
    gpioTerminate();

    return 0;
}

