#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>
#include <signal.h>
#include <math.h>
#include <errno.h>

// MPU-6050 I2C address
#define MPU6050_ADDR 0x68

// MPU-6050 registers
#define MPU6050_PWR_MGMT_1 0x6B
#define MPU6050_ACCEL_XOUT_H 0x3B
#define MPU6050_GYRO_XOUT_H 0x43

// Servo PWM parameters
#define PWM_CHIP 2
#define PWM_NUM 0
#define PWM_PERIOD_NS 20000000 // 50 Hz (20ms period)
#define PWM_RANGE 2000        // PWM range (0-2000)

// Tilt threshold
#define TILT_THRESHOLD 10.0

// Exponential backoff parameters
#define MAX_RETRIES 3
#define MAX_DELAY_MS 100

// Global variables
int i2c_fd;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int init_mpu6050();
int read_raw_data(int16_t *accel_x, int16_t *accel_y, int16_t *accel_z, int16_t *gyro_x, int16_t *gyro_y, int16_t *gyro_z);
void convert_raw_data(int16_t accel_x, int16_t accel_y, int16_t accel_z, float *pitch, float *roll);
float calculate_servo_angle(float pitch, float roll);
int set_servo_angle(float angle);
int log_data(float pitch, float roll, float servo_angle);
void signal_handler(int sig);
int init_pwm();
int set_pwm_period(int period_ns);
int set_pwm_range(int range);

// I2C initialization function
int init_i2c() {
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Error opening I2C device");
        return -1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        perror("Error setting I2C slave address");
        close(i2c_fd);
        return -1;
    }

    return 0;
}

// MPU-6050 initialization function
int init_mpu6050() {
    uint8_t data[2];
    data[0] = MPU6050_PWR_MGMT_1;
    data[1] = 0x00; // Wake up the MPU-6050

    if (write(i2c_fd, data, 2) != 2) {
        perror("Error writing to MPU6050");
        return -1;
    }

    return 0;
}

// Read raw data from MPU-6050 with exponential backoff
int read_raw_data(int16_t *accel_x, int16_t *accel_y, int16_t *accel_z, int16_t *gyro_x, int16_t *gyro_y, int16_t *gyro_z) {
    uint8_t reg = MPU6050_ACCEL_XOUT_H;
    uint8_t data[14];
    int retries = 0;
    int delay_ms = 1;

    while (retries < MAX_RETRIES) {
        if (write(i2c_fd, &reg, 1) != 1) {
            perror("Error writing register address");
            retries++;
            usleep(delay_ms * 1000);
            delay_ms *= 2;
            if (delay_ms > MAX_DELAY_MS) delay_ms = MAX_DELAY_MS;
            continue;
        }

        if (read(i2c_fd, data, 14) != 14) {
            perror("Error reading data");
            retries++;
            usleep(delay_ms * 1000);
            delay_ms *= 2;
            if (delay_ms > MAX_DELAY_MS) delay_ms = MAX_DELAY_MS;
            continue;
        }

        *accel_x = (data[0] << 8) | data[1];
        *accel_y = (data[2] << 8) | data[3];
        *accel_z = (data[4] << 8) | data[5];
        *gyro_x = (data[8] << 8) | data[9];
        *gyro_y = (data[10] << 8) | data[11];
        *gyro_z = (data[12] << 8) | data[13];

        return 0; // Success
    }

    fprintf(stderr, "Failed to read data after %d retries\n", MAX_RETRIES);
    return -1; // Failure
}

// Convert raw data to pitch and roll angles
void convert_raw_data(int16_t accel_x, int16_t accel_y, int16_t accel_z, float *pitch, float *roll) {
    *pitch = atan2(accel_x, sqrt(accel_y * accel_y + accel_z * accel_z)) * 180 / M_PI;
    *roll = atan2(-accel_y, sqrt(accel_x * accel_x + accel_z * accel_z)) * 180 / M_PI;
}

// Calculate servo angle based on pitch and roll
float calculate_servo_angle(float pitch, float roll) {
    float angle = 90.0 + (pitch + roll) / 2.0; // Adjust as needed
    if (angle < 0) angle = 0;
    if (angle > 180) angle = 180;
    return angle;
}

// Set servo angle using PWM
int set_servo_angle(float angle) {
    int duty_cycle = (int)(angle * PWM_RANGE / 180.0);
    char path[64];
    int fd;
    char buf[64];

    // Set duty cycle
    snprintf(path, sizeof(path), "/sys/class/pwm/pwmchip%d/pwm%d/duty_cycle", PWM_CHIP, PWM_NUM);
    fd = open(path, O_WRONLY);
    if (fd < 0) {
        perror("Error opening duty_cycle file");
        return -1;
    }
    snprintf(buf, sizeof(buf), "%d", duty_cycle);
    if (write(fd, buf, strlen(buf)) < 0) {
        perror("Error writing to duty_cycle file");
        close(fd);
        return -1;
    }
    close(fd);

    return 0;
}

// Log data to file
int log_data(float pitch, float roll, float servo_angle) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(log_file, "%d-%02d-%02d %02d:%02d:%02d,%.2f,%.2f,%.2f\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec,
            pitch, roll, servo_angle);
    fflush(log_file);
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Initialize PWM
int init_pwm() {
    char path[64];
    int fd;
    char buf[64];

    // Export PWM channel
    snprintf(path, sizeof(path), "/sys/class/pwm/pwmchip%d/export", PWM_CHIP);
    fd = open(path, O_WRONLY);
    if (fd < 0) {
        if (errno == EBUSY) {
            fprintf(stderr, "PWM already exported\n");
        } else {
            perror("Error opening export file");
            return -1;
        }
    } else {
        snprintf(buf, sizeof(buf), "%d", PWM_NUM);
        if (write(fd, buf, strlen(buf)) < 0) {
            perror("Error writing to export file");
            close(fd);
            return -1;
        }
        close(fd);
    }

    // Set PWM period
    if (set_pwm_period(PWM_PERIOD_NS) != 0) return -1;

    // Set PWM range
    if (set_pwm_range(PWM_RANGE) != 0) return -1;

    return 0;
}

// Set PWM period
int set_pwm_period(int period_ns) {
    char path[64];
    int fd;
    char buf[64];

    snprintf(path, sizeof(path), "/sys/class/pwm/pwmchip%d/pwm%d/period", PWM_CHIP, PWM_NUM);
    fd = open(path, O_WRONLY);
    if (fd < 0) {
        perror("Error opening period file");
        return -1;
    }
    snprintf(buf, sizeof(buf), "%d", period_ns);
    if (write(fd, buf, strlen(buf)) < 0) {
        perror("Error writing to period file");
        close(fd);
        return -1;
    }
    close(fd);
    return 0;
}

// Set PWM range
int set_pwm_range(int range) {
    char path[64];
    int fd;
    char buf[64];

    snprintf(path, sizeof(path), "/sys/class/pwm/pwmchip%d/pwm%d/range", PWM_CHIP, PWM_NUM);
    fd = open(path, O_WRONLY);
    if (fd < 0) {
        perror("Error opening range file");
        return -1;
    }
    snprintf(buf, sizeof(buf), "%d", range);
    if (write(fd, buf, strlen(buf)) < 0) {
        perror("Error writing to range file");
        close(fd);
        return -1;
    }
    close(fd);
    return 0;
}

int main() {
    int16_t accel_x, accel_y, accel_z, gyro_x, gyro_y, gyro_z;
    float pitch, roll, servo_angle;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        return 1;
    }

    // Initialize MPU-6050
    if (init_mpu6050() != 0) {
        close(i2c_fd);
        return 1;
    }

    // Initialize PWM
    if (init_pwm() != 0) {
        close(i2c_fd);
        return 1;
    }

    // Open log file
    log_file = fopen("solar_tracker.log", "a");
    if (log_file == NULL) {
        perror("Error opening log file");
