        return 1;
    }

    // Main loop
    while (!terminate) {
        // Read raw data
        if (read_raw_data(&accel_x, &accel_y, &accel_z, &gyro_x, &gyro_y, &gyro_z) == 0) {
            // Convert raw data to pitch and roll
            convert_raw_data(accel_x, accel_y, accel_z, &pitch, &roll);

