#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins for the relays
#define RELAY1_GPIO 4
#define RELAY2_GPIO 17
#define RELAY3_GPIO 27
#define RELAY4_GPIO 22

// Define the schedule file name
#define SCHEDULE_FILE "lighting_schedule.txt"

// Define the PWM frequency and range
#define PWM_FREQUENCY 100
#define PWM_RANGE 100

// Define the transition duration in seconds
#define TRANSITION_DURATION 1800

// Structure to represent a schedule entry
typedef struct {
    int hour;
    int minute;
    int second;
    int relay_number;
    int on_off;
} schedule_entry_t;

// Global variables
static volatile int running = 1;
static FILE *schedule_file = NULL;

// Function prototypes
int read_schedule(const char *filename, schedule_entry_t **schedule, int *num_entries);
int load_schedule(const char *filename, schedule_entry_t **schedule, int *num_entries);
int check_schedule(const schedule_entry_t *schedule, int num_entries, int current_time);
void set_relay_state(int gpio_pin, int on_off);
void fade_relay(int gpio_pin, int target_duty_cycle, int current_duty_cycle, int elapsed_time, int transition_duration);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);

    // Turn off all relays
    set_relay_state(RELAY1_GPIO, 0);
    set_relay_state(RELAY2_GPIO, 0);
    set_relay_state(RELAY3_GPIO, 0);
    set_relay_state(RELAY4_GPIO, 0);

    // Release GPIO resources
    gpioTerminate();

    exit(0);
}

// Function to read the schedule from a file
int read_schedule(const char *filename, schedule_entry_t **schedule, int *num_entries) {
    FILE *file = fopen(filename, "r");
    if (file == NULL) {
        perror("Error opening schedule file");
        return -1;
    }

    // Determine the number of entries in the file
    int count = 0;
    char line[256];
    while (fgets(line, sizeof(line), file) != NULL) {
        count++;
    }
    rewind(file);

    // Allocate memory for the schedule entries
    *schedule = (schedule_entry_t *)malloc(count * sizeof(schedule_entry_t));
    if (*schedule == NULL) {
        perror("Error allocating memory for schedule");
        fclose(file);
        return -1;
    }
    *num_entries = count;

    // Read the schedule entries from the file
    for (int i = 0; i < count; i++) {
        if (fscanf(file, "%d:%d:%d,%d,%s", &(*schedule)[i].hour, &(*schedule)[i].minute, &(*schedule)[i].second, &(*schedule)[i].relay_number, &(*schedule)[i].on_off) != 5) {
            fprintf(stderr, "Error reading schedule entry %d\n", i + 1);
            fclose(file);
            free(*schedule);
            return -1;
        }
        if ((*schedule)[i].on_off != 0 && (*schedule)[i].on_off != 1) {
            fprintf(stderr, "Invalid on/off value in schedule entry %d\n", i + 1);
            fclose(file);
            free(*schedule);
            return -1;
        }
    }

    fclose(file);
    return 0;
}

// Function to load the schedule from a file
int load_schedule(const char *filename, schedule_entry_t **schedule, int *num_entries) {
    if (read_schedule(filename, schedule, num_entries) != 0) {
        return -1;
    }
    return 0;
}

// Function to check the schedule against the current time
int check_schedule(const schedule_entry_t *schedule, int num_entries, int current_time) {
    for (int i = 0; i < num_entries; i++) {
        int schedule_time = schedule[i].hour * 3600 + schedule[i].minute * 60 + schedule[i].second;
        if (schedule_time == current_time) {
            return schedule[i].on_off;
        }
    }
    return -1; // No match found
}

// Function to set the state of a relay
void set_relay_state(int gpio_pin, int on_off) {
    gpioWrite(gpio_pin, on_off);
}

// Function to fade the brightness of a relay using PWM
void fade_relay(int gpio_pin, int target_duty_cycle, int current_duty_cycle, int elapsed_time, int transition_duration) {
    if (elapsed_time < transition_duration) {
        int new_duty_cycle = current_duty_cycle + (target_duty_cycle - current_duty_cycle) * (elapsed_time / (float)transition_duration);
        if (new_duty_cycle < 0) new_duty_cycle = 0;
        if (new_duty_cycle > PWM_RANGE) new_duty_cycle = PWM_RANGE;
        gpioPWM(gpio_pin, new_duty_cycle);
    } else {
        gpioPWM(gpio_pin, target_duty_cycle);
    }
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as outputs
    gpioSetMode(RELAY1_GPIO, PI_OUTPUT);
    gpioSetMode(RELAY2_GPIO, PI_OUTPUT);
    gpioSetMode(RELAY3_GPIO, PI_OUTPUT);
    gpioSetMode(RELAY4_GPIO, PI_OUTPUT);

    // Set PWM frequency and range for each relay
    gpioSetPWMfrequency(RELAY1_GPIO, PWM_FREQUENCY);
    gpioSetPWMrange(RELAY1_GPIO, PWM_RANGE);
    gpioSetPWMfrequency(RELAY2_GPIO, PWM_FREQUENCY);
    gpioSetPWMrange(RELAY2_GPIO, PWM_RANGE);
    gpioSetPWMfrequency(RELAY3_GPIO, PWM_FREQUENCY);
    gpioSetPWMrange(RELAY3_GPIO, PWM_RANGE);
    gpioSetPWMfrequency(RELAY4_GPIO, PWM_FREQUENCY);
    gpioSetPWMrange(RELAY4_GPIO, PWM_RANGE);

    // Load the schedule
    schedule_entry_t *schedule = NULL;
    int num_entries = 0;
    if (load_schedule(SCHEDULE_FILE, &schedule, &num_entries) != 0) {
        gpioTerminate();
        return 1;
    }

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (running) {
        // Get the current time
        time_t current_time = time(NULL);
        struct tm *tm_info = localtime(&current_time);
        int current_hour = tm_info->tm_hour;
        int current_minute = tm_info->tm_min;
        int current_second = tm_info->tm_sec;
        int current_time_seconds = current_hour * 3600 + current_minute * 60 + current_second;

