#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// Define GPIO pins
#define TRIGGER_PIN 23
#define ECHO_PIN 24
#define BUZZER_PIN 18

// Define constants
#define SPEED_OF_SOUND 34300.0 // Speed of sound in cm/s
#define MIN_DISTANCE 2.0      // Minimum distance in cm
#define MAX_DISTANCE 30.0     // Maximum distance in cm
#define MIN_FREQUENCY 200.0   // Minimum frequency in Hz
#define MAX_FREQUENCY 2000.0  // Maximum frequency in Hz
#define TIMEOUT_US 50000       // Timeout in microseconds (50ms)

// Global variable for program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signal) {
    program_running = 0;
    fprintf(stderr, "\nCaught signal %d, stopping...\n", signal);
}

// Function to generate a 10us trigger pulse
void triggerSensor() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10 us
    gpioWrite(TRIGGER_PIN, 0);
}

// Function to measure the echo pulse width
long getPulseWidth() {
    long start_tick, end_tick, pulse_width;

    // Wait for echo to go high
    int count = 0;
    while (gpioRead(ECHO_PIN) == 0 && count < TIMEOUT_US) {
        count++;
        gpioDelay(1); // Small delay to avoid busy-waiting
    }

    if (count >= TIMEOUT_US) {
        fprintf(stderr, "Error: Echo signal timeout\n");
        return -1; // Timeout
    }

    start_tick = gpioTick();

    // Wait for echo to go low
    count = 0;
    while (gpioRead(ECHO_PIN) == 1 && count < TIMEOUT_US) {
        count++;
        gpioDelay(1);
    }

    if (count >= TIMEOUT_US) {
        fprintf(stderr, "Error: Echo signal timeout (low)\n");
        return -1; // Timeout
    }

    end_tick = gpioTick();

    pulse_width = end_tick - start_tick;
    if (pulse_width < 0) {
        pulse_width += 0xFFFFFFFF; // Handle tick rollover
    }

    return pulse_width;
}

// Function to calculate distance from pulse width
float calculateDistance(long pulse_width) {
    if (pulse_width < 0) return -1.0; // Indicate error
    return (pulse_width / 1000000.0) * SPEED_OF_SOUND / 2.0;
}

// Function to map distance to frequency
float mapDistanceToFrequency(float distance) {
    float frequency;

    if (distance < MIN_DISTANCE) {
        frequency = MIN_FREQUENCY;
    } else if (distance > MAX_DISTANCE) {
        frequency = MAX_FREQUENCY;
    } else {
        frequency = MIN_FREQUENCY + (distance - MIN_DISTANCE) * (MAX_FREQUENCY - MIN_FREQUENCY) / (MAX_DISTANCE - MIN_DISTANCE);
    }

    return frequency;
}

// Function to set the buzzer frequency
void setBuzzerFrequency(float frequency) {
    int range = 1000; // PWM range (0-1000)
    int duty_cycle = 500; // 50% duty cycle

    gpioSetPWMfrequency(BUZZER_PIN, (int)frequency);
    gpioPWM(BUZZER_PIN, duty_cycle);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(BUZZER_PIN, PI_OUTPUT);

    // Register signal handler for SIGINT
    signal(SIGINT, signal_handler);

    fprintf(stderr, "Theremin started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        // Trigger the sensor
        triggerSensor();

        // Get the pulse width
        long pulse_width = getPulseWidth();

        // Calculate the distance
        float distance = calculateDistance(pulse_width);

        // Map the distance to a frequency
        float frequency = mapDistanceToFrequency(distance);

        // Set the buzzer frequency
        if (distance > 0) {
            setBuzzerFrequency(frequency);
        } else {
            fprintf(stderr, "Error: Invalid distance reading\n");
            gpioPWM(BUZZER_PIN, 0); // Silence the buzzer on error
        }

        // Delay to avoid trigger/echo overlap
        gpioDelay(60000); // 60 ms
    }

    // Stop the buzzer
    gpioPWM(BUZZER_PIN, 0);

    // Deinitialize pigpio
    gpioTerminate();

    fprintf(stderr, "Theremin stopped.\n");

    return 0;
}

