#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins for RGB LED
#define RED_PIN   17
#define GREEN_PIN 22
#define BLUE_PIN  27

// Define PWM frequency
#define PWM_FREQUENCY 1000

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to set the RGB LED color using PWM
void set_led_color(float proximity) {
    // Map proximity to RGB values (common anode)
    int red_value   = (int)((1.0 - proximity) * 255.0);
    int green_value = (int)(proximity * 255.0);
    int blue_value  = 0; // Blue is always off in this example

    // Set PWM duty cycle for each color
    gpioPWM(RED_PIN,   red_value);
    gpioPWM(GREEN_PIN, green_value);
    gpioPWM(BLUE_PIN,  blue_value);
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins to output mode
    if (gpioSetMode(RED_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set RED_PIN to output mode\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(GREEN_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GREEN_PIN to output mode\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(BLUE_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set BLUE_PIN to output mode\n");
        gpioTerminate();
        return 1;
    }

    // Set PWM frequency for each pin
    if (gpioSetPWMfrequency(RED_PIN, PWM_FREQUENCY) != 0) {
        fprintf(stderr, "Failed to set PWM frequency for RED_PIN\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetPWMfrequency(GREEN_PIN, PWM_FREQUENCY) != 0) {
        fprintf(stderr, "Failed to set PWM frequency for GREEN_PIN\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetPWMfrequency(BLUE_PIN, PWM_FREQUENCY) != 0) {
        fprintf(stderr, "Failed to set PWM frequency for BLUE_PIN\n");
        gpioTerminate();
        return 1;
    }

    // Set PWM range (0-255)
    gpioSetPWMrange(RED_PIN, 255);
    gpioSetPWMrange(GREEN_PIN, 255);
    gpioSetPWMrange(BLUE_PIN, 255);

    // Register signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Main loop
    float proximity = 0.0;
    float increment = 0.01;
    while (program_running) {
        // Update proximity value (sine wave)
        proximity += increment;
        if (proximity > 1.0) {
            proximity = 0.0;
        }

        // Set LED color based on proximity
        set_led_color(proximity);

        // Delay for a short period
        usleep(10000); // 10ms
    }

    // Turn off the LED before exiting
    gpioPWM(RED_PIN, 0);
    gpioPWM(GREEN_PIN, 0);
    gpioPWM(BLUE_PIN, 0);

    // Terminate pigpio library
    gpioTerminate();

    return 0;
}

