#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <string.h>

// MPU-6050 I2C address
#define MPU6050_ADDR 0x68

// MPU-6050 registers
#define PWR_MGMT_1 0x6B
#define GYRO_XOUT_H 0x43

// Sensitivity scale factor for ±250 deg/s range
#define GYRO_SCALE_FACTOR 131.0

// Global variables
int i2c_fd = -1; // I2C file descriptor
FILE *log_file = NULL; // Log file pointer
volatile sig_atomic_t terminate = 0; // Termination flag

// Structure to hold gyroscope data
typedef struct {
    float x;
    float y;
    float z;
} gyro_data_t;

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating...\n", sig);
}

// Function to initialize the MPU-6050
int init_mpu6050(int fd) {
    // Wake up the sensor (clear sleep mode bit)
    uint8_t wake_data = 0x00;
    if (write(fd, &wake_data, 1) != 1) {
        fprintf(stderr, "Error writing to PWR_MGMT_1 register: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Function to read gyroscope data from the MPU-6050
int read_gyro_data(int fd, gyro_data_t *data) {
    uint8_t buffer[6];

    // Read 6 bytes of gyroscope data starting from GYRO_XOUT_H
    if (read(fd, buffer, 6) != 6) {
        fprintf(stderr, "Error reading gyroscope data: %s\n", strerror(errno));
        return -1;
    }

    // Combine high and low bytes for each axis
    int16_t gyro_x = (buffer[0] << 8) | buffer[1];
    int16_t gyro_y = (buffer[2] << 8) | buffer[3];
    int16_t gyro_z = (buffer[4] << 8) | buffer[5];

    // Convert to degrees per second
    data->x = (float)gyro_x / GYRO_SCALE_FACTOR;
    data->y = (float)gyro_y / GYRO_SCALE_FACTOR;
    data->z = (float)gyro_z / GYRO_SCALE_FACTOR;

    return 0;
}

// Function to log gyroscope data to a file
int log_data(FILE *fp, gyro_data_t data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (fprintf(fp, "%s,%.2f,%.2f,%.2f\n", timestamp, data.x, data.y, data.z) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        return -1;
    }

    fflush(fp); // Ensure data is written to disk immediately
    return 0;
}

int main() {
    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C bus
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C bus: %s\n", strerror(errno));
        return 1;
    }

    // Specify the address of the slave device
    if (ioctl(i2c_fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    // Initialize the MPU-6050
    if (init_mpu6050(i2c_fd) < 0) {
        close(i2c_fd);
        return 1;
    }

    // Open the log file in append mode
    log_file = fopen("gyro_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    gyro_data_t gyro_data;

    // Main loop
    while (!terminate) {
        // Read gyroscope data
        if (read_gyro_data(i2c_fd, &gyro_data) == 0) {
            // Log the data
            if (log_data(log_file, gyro_data) != 0) {
                terminate = 1; // Stop logging on error
            }
        } else {
            terminate = 1; // Stop logging on error
        }

        // Wait for 100 milliseconds
        usleep(100000); // 100 ms = 100000 microseconds
    }

    // Close the log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Close the I2C bus
    close(i2c_fd);

    fprintf(stderr, "Program terminated.\n");
    return 0;
}

