#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// Define GPIO pins
#define BUTTON_PIN 17
#define BUZZER_PIN 18

// Define melody
const int melody[] = {262, 294, 330, 349, 392, 440, 494, 523, 587, 659, 698, 784, 880, 988, 1047, 1175};
const int melody_length = sizeof(melody) / sizeof(melody[0]);

// Define debounce time (in milliseconds)
#define DEBOUNCE_TIME 50

// Define PWM frequency (in Hz)
#define PWM_FREQUENCY 1000

// Define PWM duty cycle (0-100)
#define PWM_DUTY_CYCLE 50

// Global flag to control melody playback
volatile int play_melody = 0;

// Function prototypes
void signal_handler(int signal);
void button_interrupt_handler(int gpio, int level, uint32_t tick, void *user_data);
void play_tone(int frequency);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    gpioPWM(BUZZER_PIN, 0); // Stop PWM
    gpioTerminate(); // Terminate pigpio
    exit(0);
}

// Interrupt handler for button press
void button_interrupt_handler(int gpio, int level, uint32_t tick, void *user_data) {
    static uint32_t last_tick = 0;
    uint32_t current_tick = gpioTick();

    // Debounce the button
    if (current_tick - last_tick > DEBOUNCE_TIME * 1000) {
        last_tick = current_tick;

        if (level == 0) { // Button pressed (active-low)
            play_melody = 1; // Start playing melody
        } else {
            // Button released
            if (play_melody) {
                play_melody = 0; // Stop playing melody
                gpioPWM(BUZZER_PIN, 0); // Stop PWM
            }
        }
    }
}

// Function to play a tone using PWM
void play_tone(int frequency) {
    if (frequency > 0) {
        gpioHardwarePWM(BUZZER_PIN, frequency, PWM_DUTY_CYCLE); // Set PWM frequency and duty cycle
    } else {
        gpioPWM(BUZZER_PIN, 0); // Stop PWM if frequency is 0
    }
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(BUTTON_PIN, PI_INPUT);
    gpioSetMode(BUZZER_PIN, PI_OUTPUT);

    // Enable pull-up resistor on the button pin
    gpioSetPullUpDown(BUTTON_PIN, PI_PUD_UP);

    // Set PWM frequency for the buzzer
    gpioSetPWMfrequency(BUZZER_PIN, PWM_FREQUENCY);

    // Set PWM range (0-100)
    gpioSetPWMrange(BUZZER_PIN, 100);

    // Set interrupt handler for the button
    if (gpioSetISRFuncEx(BUTTON_PIN, EITHER_EDGE, 0, button_interrupt_handler, NULL) != 0) {
        fprintf(stderr, "Failed to set interrupt handler\n");
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Musical doorbell running. Press Ctrl+C to exit.\n");

    // Main loop
    while (1) {
        if (play_melody) {
            for (int i = 0; i < melody_length; i++) {
                play_tone(melody[i]);
                gpioDelay(200); // Play each note for 200ms
            }
            play_melody = 0; // Stop after one complete cycle
        }
        gpioDelay(10); // Small delay to prevent busy-waiting
    }

    return 0;
}

