#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>
#include <errno.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_PIN 17
#define LOG_FILE "vibration_events.log"
#define WINDOW_SIZE 5

// Global variables
static volatile sig_atomic_t keep_running = 1;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *line = NULL;
static FILE *log_file = NULL;

// Function prototypes
void signal_handler(int sig);
int init_gpio(void);
int init_log_file(void);
void log_event(int value);
void check_earthquake(void);
void cleanup(void);

// Signal handler
void signal_handler(int sig) {
    if (sig == SIGINT || sig == SIGTERM) {
        fprintf(stderr, "Caught signal %d, exiting gracefully.\n", sig);
        keep_running = 0;
    }
}

// Initialize GPIO
int init_gpio(void) {
    struct gpiod_line_request_config config;

    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", GPIO_CHIP);
        return -1;
    }

    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        fprintf(stderr, "Error getting GPIO line %d\n", GPIO_PIN);
        gpiod_chip_close(chip);
        return -1;
    }

    memset(&config, 0, sizeof(config));
    config.consumer = "vibration_sensor";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT;

    if (gpiod_line_request(line, &config, 0) < 0) {
        fprintf(stderr, "Error requesting GPIO line %d as input\n", GPIO_PIN);
        gpiod_chip_close(chip);
        return -1;
    }

    return 0;
}

// Initialize log file
int init_log_file(void) {
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        return -1;
    }
    return 0;
}

// Log event to file
void log_event(int value) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    if (log_file) {
        fprintf(log_file, "%s %d\n", timestamp, value);
        fflush(log_file);
    } else {
        fprintf(stderr, "Log file not open, cannot log event %d\n", value);
    }
}

// Check for earthquake alert
void check_earthquake(void) {
    static int high_count = 0;
    static int high_indices[WINDOW_SIZE];
    static int high_index = 0;
    static int event_count = 0;
    static int events[WINDOW_SIZE];
    static int event_index = 0;

    events[event_index] = (gpiod_line_event_read(line) == 1) ? 1 : 0;
    event_index = (event_index + 1) % WINDOW_SIZE;
    event_count++;

    if (event_count < WINDOW_SIZE) {
        return;
    }

    if (events[event_index] == 1) {
        high_count++;
        high_indices[high_index] = event_index;
        high_index = (high_index + 1) % WINDOW_SIZE;
    } else {
        high_count--;
    }

    if (high_count >= 3) {
        time_t now = time(NULL);
        struct tm *t = localtime(&now);
        char timestamp[30];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

        printf("EARTHQUAKE ALERT: %s\n", timestamp);
    }
}

// Cleanup resources
void cleanup(void) {
    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (log_file) {
        fsync(fileno(log_file));
        fclose(log_file);
    }
}

int main(int argc, char *argv[]) {
    int timeout_ms = 1000; // Default timeout

    if (argc > 1) {
        timeout_ms = atoi(argv[1]);
        if (timeout_ms <= 0) {
            fprintf(stderr, "Invalid timeout value. Using default (%d ms).\n", timeout_ms);
            timeout_ms = 1000;
        }
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    if (init_gpio() < 0) {
        return 1;
    }

    if (init_log_file() < 0) {
        cleanup();
        return 1;
    }

    printf("Vibration sensor monitoring started. Timeout: %d ms. Press Ctrl+C to exit.\n", timeout_ms);

    while (keep_running) {
        int ret = gpiod_line_event_wait(line, timeout_ms);

        if (ret < 0) {
            fprintf(stderr, "Error waiting for event: %s\n", strerror(errno));
            break;
        } else if (ret == 0) {
            // Timeout occurred, check for earthquake
            check_earthquake();
        } else {
            // Event occurred, log it and check for earthquake
            log_event(gpiod_line_event_read(line));
            check_earthquake();
        }
    }

    cleanup();
    printf("Vibration sensor monitoring stopped.\n");
    return 0;
}

