#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <math.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

// LSM303DLHC I2C address
#define LSM303_ADDR 0x1E

// LSM303DLHC register addresses
#define CRA_REG_M 0x00
#define MR_REG_M 0x02
#define OUT_X_H_M 0x03
#define OUT_X_L_M 0x04
#define OUT_Z_H_M 0x05
#define OUT_Z_L_M 0x06
#define OUT_Y_H_M 0x07
#define OUT_Y_L_M 0x08

// Hard-iron calibration offsets
#define X_OFFSET 10.0f
#define Y_OFFSET -5.0f
#define Z_OFFSET 20.0f

// Global variables
int i2c_fd = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c(int address);
int write_register(int fd, uint8_t reg, uint8_t value);
int read_registers(int fd, uint8_t reg, uint8_t *data, int len);
int16_t combine_registers(uint8_t msb, uint8_t lsb);
float calibrate_magnetometer(int16_t raw_x, int16_t raw_y, int16_t raw_z);
float calculate_heading(float calibrated_x, float calibrated_y);
char* determine_direction(float heading);
void log_data(FILE *fp, float calibrated_x, float calibrated_y, float calibrated_z, float heading);
void signal_handler(int sig);

// Signal handler function
void signal_handler(int sig) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating...\n", sig);
}

// Initialize I2C communication
int init_i2c(int address) {
    int fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening I2C device: %s\n", strerror(errno));
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, address) < 0) {
        fprintf(stderr, "Error setting I2C slave address: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    return fd;
}

// Write a single byte to a register
int write_register(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2];
    buf[0] = reg;
    buf[1] = value;

    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "Error writing to register 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }

    return 0;
}

// Read multiple bytes from a register
int read_registers(int fd, uint8_t reg, uint8_t *data, int len) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "Error writing register address for read: %s\n", strerror(errno));
        return -1;
    }

    if (read(fd, data, len) != len) {
        fprintf(stderr, "Error reading from register 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }

    return 0;
}

// Combine two registers into a signed 16-bit integer
int16_t combine_registers(uint8_t msb, uint8_t lsb) {
    return (int16_t)((msb << 8) | lsb);
}

// Calibrate magnetometer data
float calibrate_magnetometer(int16_t raw_x, int16_t raw_y, int16_t raw_z) {
    return (float)raw_x + X_OFFSET, (float)raw_y + Y_OFFSET, (float)raw_z + Z_OFFSET;
}

// Calculate compass heading in degrees
float calculate_heading(float calibrated_x, float calibrated_y) {
    float heading = atan2f(calibrated_y, calibrated_x) * 180.0f / M_PI;
    if (heading < 0) {
        heading += 360.0f;
    }
    return heading;
}

// Determine compass direction
char* determine_direction(float heading) {
    if (heading >= 337.5f || heading < 22.5f) return "N";
    if (heading >= 22.5f && heading < 67.5f) return "NE";
    if (heading >= 67.5f && heading < 112.5f) return "E";
    if (heading >= 112.5f && heading < 157.5f) return "SE";
    if (heading >= 157.5f && heading < 202.5f) return "S";
    if (heading >= 202.5f && heading < 247.5f) return "SW";
    if (heading >= 247.5f && heading < 292.5f) return "W";
    if (heading >= 292.5f && heading < 337.5f) return "NW";
    return "Unknown";
}

// Log data to CSV file
void log_data(FILE *fp, float calibrated_x, float calibrated_y, float calibrated_z, float heading) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(fp, "%s,%.2f,%.2f,%.2f,%.2f\n", timestamp, calibrated_x, calibrated_y, calibrated_z, heading);
    fflush(fp); // Ensure data is written to disk immediately
}

int main() {
    // Install signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    i2c_fd = init_i2c(LSM303_ADDR);
    if (i2c_fd < 0) {
        return 1;
    }

    // Configure magnetometer
    if (write_register(i2c_fd, CRA_REG_M, 0x14) < 0) { // 15 Hz output data rate
        fprintf(stderr, "Failed to set output data rate. Continuing with default.\n");
    }
    if (write_register(i2c_fd, MR_REG_M, 0x00) < 0) { // Continuous conversion mode
        fprintf(stderr, "Failed to set continuous conversion mode. Continuing with default.\n");
    }

    // Open log file
    log_file = fopen("mag_log.csv", "a+");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    // Check if the file is empty and write the header if needed
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Calibrated X,Calibrated Y,Calibrated Z,Heading\n");
    }
    fseek(log_file, 0, SEEK_END); // Reset file pointer to the end for appending

    // Main loop
    while (!terminate) {
        uint8_t data[6];
        int16_t raw_x, raw_y, raw_z;
        float calibrated_x, calibrated_y, calibrated_z;
        float heading;
        char *direction;

        // Read magnetometer data
        if (read_registers(i2c_fd, OUT_X_H_M, data, 6) < 0) {
            fprintf(stderr, "Failed to read magnetometer data. Skipping sample.\n");
            sleep(1);
            continue;
        }

        // Combine registers
        raw_x = combine_registers(data[0], data[1]);
        raw_z = combine_registers(data[2], data[3]);
        raw_y = combine_registers(data[4], data[5]);

        // Calibrate data
        calibrated_x = (float)raw_x + X_OFFSET;
        calibrated_y = (float)raw_y + Y_OFFSET;
        calibrated_z = (float)raw_z + Z_OFFSET;

        // Calculate heading
        heading = calculate_heading(calibrated_x, calibrated_y);

        // Determine direction
        direction = determine_direction(heading);

        // Log data
        log_data(log_file, calibrated_x, calibrated_y, calibrated_z, heading);

        // Print heading and direction to console
        printf("Heading: %.2f degrees, Direction: %s\n", heading, direction);

        sleep(1);
    }

    // Cleanup
    close(i2c_fd);
    fclose(log_file);

    return 0;
}

