#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define TOUCH_GPIO 4
#define RELAY_GPIO 17
#define DEBOUNCE_DELAY_MS 200
#define LOG_FILE "relay_log.json"

volatile sig_atomic_t program_running = 1;

// Function to get the current timestamp in ISO 8601 format
char* get_iso8601_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    char *timestamp = (char*)malloc(25 * sizeof(char)); // Allocate memory for the timestamp string

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, 25, "%Y-%m-%dT%H:%M:%S%z", timeinfo);
    return timestamp;
}

// Function to log relay state to a JSON file
void log_relay_state(const char* timestamp, const char* state) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("Error opening log file");
        return;
    }

    fprintf(fp, "{\"timestamp\":\"%s\",\"relay_state\":\"%s\"}\n", timestamp, state);
    fclose(fp);
}

// Function to toggle the relay state
void toggle_relay(int gpio, int* current_state) {
    *current_state = !(*current_state);
    gpioWrite(gpio, *current_state);
}

// Callback function for touch sensor interrupts
void touch_callback(int gpio, int level, uint32_t tick, void *user) {
    static uint32_t last_tick = 0;
    uint32_t current_tick = gpioTick();

    if (current_tick - last_tick > DEBOUNCE_DELAY_MS * 1000) {
        char* timestamp = get_iso8601_timestamp();
        int relay_state = gpioRead(RELAY_GPIO);
        char* state_str = (relay_state == 1) ? "ON" : "OFF";

        log_relay_state(timestamp, state_str);
        free(timestamp);

        toggle_relay(RELAY_GPIO, (int*)user);
        last_tick = current_tick;
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TOUCH_GPIO, PI_INPUT);
    gpioSetMode(RELAY_GPIO, PI_OUTPUT);

    // Set pull-down resistor on touch sensor GPIO
    gpioSetPullUpDown(TOUCH_GPIO, PI_PUD_DOWN);

    // Initialize relay state to OFF
    int relay_state = 0;
    gpioWrite(RELAY_GPIO, relay_state);

    // Set interrupt callback for touch sensor
    if (gpioSetISRFuncEx(TOUCH_GPIO, RISING_EDGE, 0, touch_callback, &relay_state) != 0) {
        fprintf(stderr, "Failed to set ISR function\n");
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Relay control program started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        gpioDelay(100); // Reduce CPU usage
    }

    // Cleanup before exiting
    gpioWrite(RELAY_GPIO, 0); // Turn off relay
    log_relay_state(get_iso8601_timestamp(), "OFF");
    gpioTerminate();

    return 0;
}

