    gpioSetMode(RELAY_GPIO, PI_OUTPUT);

    // Set pull-down resistor on touch sensor GPIO
    gpioSetPullUpDown(TOUCH_GPIO, PI_PUD_DOWN);

    // Initialize relay state to OFF
    int relay_state = 0;
    gpioWrite(RELAY_GPIO, relay_state);

    // Set interrupt callback for touch sensor
    if (gpioSetISRFuncEx(TOUCH_GPIO, RISING_EDGE, 0, touch_callback, &relay_state) != 0) {
        fprintf(stderr, "Failed to set ISR function\n");
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Relay control program started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        gpioDelay(100); // Reduce CPU usage
    }

    // Cleanup before exiting
    gpioWrite(RELAY_GPIO, 0); // Turn off relay
    log_relay_state(get_iso8601_timestamp(), "OFF");
    gpioTerminate();

    return 0;
}

