#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <gpiod.h>

// Define GPIO pins for the relays
#define RELAY1_PIN 17
#define RELAY2_PIN 23
#define RELAY3_PIN 24
#define RELAY4_PIN 25

// Define the GPIO chip name
#define GPIO_CHIP "gpiochip0"

// Define the log file name
#define LOG_FILE "irrigation_log.txt"

// Global variables
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *lines[4];
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_gpio();
int generate_moisture_level();
void activate_relay(int relay_number);
void deactivate_relay(int relay_number);
void log_event(int relay_number, int moisture_level);
void signal_handler(int sig);
void cleanup();

// Signal handler function
void signal_handler(int sig) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", sig);
}

// Initialize GPIO lines
int initialize_gpio() {
    int ret;

    // Open the GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", GPIO_CHIP);
        return -1;
    }

    // Request GPIO lines as outputs
    lines[0] = gpiod_chip_get_line(chip, RELAY1_PIN);
    lines[1] = gpiod_chip_get_line(chip, RELAY2_PIN);
    lines[2] = gpiod_chip_get_line(chip, RELAY3_PIN);
    lines[3] = gpiod_chip_get_line(chip, RELAY4_PIN);

    for (int i = 0; i < 4; i++) {
        if (!lines[i]) {
            fprintf(stderr, "Error getting line %d (GPIO %d)\n", i + 1, (i == 0) ? RELAY1_PIN : ((i == 1) ? RELAY2_PIN : ((i == 2) ? RELAY3_PIN : RELAY4_PIN)));
            cleanup();
            return -1;
        }

        ret = gpiod_line_request_output(lines[i], NULL, 1); // 1 for inactive (OFF)
        if (ret < 0) {
            fprintf(stderr, "Error requesting line %d (GPIO %d) as output: %s\n", i + 1, (i == 0) ? RELAY1_PIN : ((i == 1) ? RELAY2_PIN : ((i == 2) ? RELAY3_PIN : RELAY4_PIN)), strerror(-ret));
            cleanup();
            return -1;
        }
    }

    return 0;
}

// Generate a simulated soil moisture level
int generate_moisture_level() {
    return rand() % 101;
}

// Activate a relay
void activate_relay(int relay_number) {
    if (relay_number < 1 || relay_number > 4) {
        fprintf(stderr, "Invalid relay number: %d\n", relay_number);
        return;
    }

    if (lines[relay_number - 1]) {
        if (gpiod_line_set_value(lines[relay_number - 1], 0) < 0) {
            fprintf(stderr, "Error setting line %d (GPIO %d) to 0: %s\n", relay_number, (relay_number == 1) ? RELAY1_PIN : ((relay_number == 2) ? RELAY2_PIN : ((relay_number == 3) ? RELAY3_PIN : RELAY4_PIN)), strerror(errno));
        } else {
            log_event(relay_number, generate_moisture_level());
        }
    }
}

// Deactivate a relay
void deactivate_relay(int relay_number) {
    if (relay_number < 1 || relay_number > 4) {
        fprintf(stderr, "Invalid relay number: %d\n", relay_number);
        return;
    }

    if (lines[relay_number - 1]) {
        if (gpiod_line_set_value(lines[relay_number - 1], 1) < 0) {
            fprintf(stderr, "Error setting line %d (GPIO %d) to 1: %s\n", relay_number, (relay_number == 1) ? RELAY1_PIN : ((relay_number == 2) ? RELAY2_PIN : ((relay_number == 3) ? RELAY3_PIN : RELAY4_PIN)), strerror(errno));
        }
    }
}

// Log an event to the log file
void log_event(int relay_number, int moisture_level) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    if (log_file) {
        fprintf(log_file, "%s - Relay %d - Moisture Level: %d\n", timestamp, relay_number, moisture_level);
        fflush(log_file);
    } else {
        fprintf(stderr, "Error: Log file not opened.\n");
    }
}

// Cleanup function
void cleanup() {
    printf("Cleaning up...\n");

    // Deactivate all relays
    for (int i = 0; i < 4; i++) {
        if (lines[i]) {
            deactivate_relay(i + 1);
            gpiod_line_release(lines[i]);
        }
    }

    // Close the GPIO chip
    if (chip) {
        gpiod_chip_close(chip);
    }

    // Close the log file
    if (log_file) {
        fclose(log_file);
    }

    printf("Cleanup complete.\n");
}

int main() {
    int moisture_level;
    int i;

    // Seed the random number generator
    srand(time(NULL));

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() < 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return 1;
    }

    // Open the log file
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        cleanup();
        return 1;
    }

    printf("Smart Irrigation System started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        moisture_level = generate_moisture_level();
        printf("Moisture Level: %d\n", moisture_level);

        if (moisture_level < 30) {
            printf("Moisture level low, activating relays...\n");
            for (i = 0; i < 4; i++) {
                activate_relay(i + 1);
                sleep(5);
                deactivate_relay(i + 1);
                sleep(1);
            }
        }

        sleep(10);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

