#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define VALVE_GPIO 17
#define NOZZLE_GPIO 18

// Define moisture threshold
#define MOISTURE_THRESHOLD 50

// Define servo pulse width limits
#define SERVO_MIN_PULSE_WIDTH 500
#define SERVO_MAX_PULSE_WIDTH 2500

// Define servo positions
#define SERVO_CLOSED 0
#define SERVO_OPEN 90

// Define nozzle angles
const int nozzle_angles[] = {0, 45, 90, 135, 180};
const int num_nozzle_angles = sizeof(nozzle_angles) / sizeof(nozzle_angles[0]);

// Global flag for signal handling
volatile sig_atomic_t program_running = 1;

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, stopping...\n", signal);
}

// Function to set servo pulse width with retry
int set_servo_pulse_width(int gpio, int pulse_width) {
    int retries = 3;
    int delay_ms = 100;
    int result;

    while (retries > 0) {
        result = gpioServo(gpio, pulse_width);
        if (result == 0) {
            return 0; // Success
        }
        fprintf(stderr, "Error setting servo pulse width for GPIO %d: %d. Retrying...\n", gpio, result);
        gpioDelay(delay_ms * 1000); // Delay in microseconds
        delay_ms *= 2; // Exponential backoff
        retries--;
    }

    fprintf(stderr, "Critical error: Failed to set servo pulse width for GPIO %d after multiple retries.\n", gpio);
    return -1; // Failure
}

// Function to open the water valve
int open_valve() {
    return set_servo_pulse_width(VALVE_GPIO, SERVO_OPEN * (SERVO_MAX_PULSE_WIDTH - SERVO_MIN_PULSE_WIDTH) / 180 + SERVO_MIN_PULSE_WIDTH);
}

// Function to close the water valve
int close_valve() {
    return set_servo_pulse_width(VALVE_GPIO, SERVO_CLOSED * (SERVO_MAX_PULSE_WIDTH - SERVO_MIN_PULSE_WIDTH) / 180 + SERVO_MIN_PULSE_WIDTH);
}

// Function to set the nozzle angle
int set_nozzle_angle(int angle) {
    return set_servo_pulse_width(NOZZLE_GPIO, angle * (SERVO_MAX_PULSE_WIDTH - SERVO_MIN_PULSE_WIDTH) / 180 + SERVO_MIN_PULSE_WIDTH);
}

// Function to perform the watering cycle
int perform_watering_cycle() {
    int i;

    // Open the valve
    if (open_valve() != 0) {
        fprintf(stderr, "Error opening valve. Aborting watering cycle.\n");
        return -1;
    }

    // Sweep the nozzle through all angles
    for (i = 0; i < num_nozzle_angles; i++) {
        if (set_nozzle_angle(nozzle_angles[i]) != 0) {
            fprintf(stderr, "Error setting nozzle angle %d. Continuing to next angle.\n", nozzle_angles[i]);
        }
        gpioDelay(2000000); // 2 seconds
    }

    // Hold the nozzle at the last angle for 5 seconds
    gpioDelay(5000000); // 5 seconds

    // Close the valve
    if (close_valve() != 0) {
        fprintf(stderr, "Error closing valve. Continuing to next cycle.\n");
    }

    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (program_running) {
        // Simulate soil moisture readings
        for (int moisture = 20; moisture <= 100; moisture += 20) {
            printf("Simulated moisture level: %d\n", moisture);

            // Check moisture level and perform watering cycle
            if (moisture < MOISTURE_THRESHOLD) {
                printf("Moisture level below threshold. Starting watering cycle.\n");
                if (perform_watering_cycle() != 0) {
                    fprintf(stderr, "Error during watering cycle. Continuing to next moisture level.\n");
                }
            } else {
                printf("Moisture level above threshold. Skipping watering cycle.\n");
            }

            // Wait before next moisture reading
            gpioDelay(5000000); // 5 seconds
        }
    }

    // Stop servos and terminate pigpio
    printf("Stopping servos and terminating pigpio...\n");
    set_servo_pulse_width(VALVE_GPIO, 0);
    set_servo_pulse_width(NOZZLE_GPIO, 0);
    gpioTerminate();

    printf("Program finished.\n");
    return 0;
}

