#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

// MPU-6050 I2C address
#define MPU6050_ADDR 0x68

// MPU-6050 registers
#define PWR_MGMT_1 0x6B
#define GYRO_XOUT_H 0x43

// Sensitivity scale factor for ±250 deg/sec range
#define GYRO_SCALE_FACTOR 131.0

// I2C bus file descriptor
int i2c_fd;

// File pointer for logging
FILE *log_file;

// Flag to indicate program termination
volatile sig_atomic_t terminate = 0;

// Signal handler for SIGINT and SIGTERM
void signal_handler(int sig) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating...\n", sig);
}

// Function to initialize the MPU-6050
int init_mpu6050() {
    uint8_t data[2];
    int retries = 3;

    // Wake up the sensor (clear sleep mode bit)
    data[0] = PWR_MGMT_1;
    data[1] = 0x00;

    while (retries > 0) {
        if (write(i2c_fd, data, 2) == 2) {
            return 0; // Success
        } else {
            fprintf(stderr, "Error writing to PWR_MGMT_1: %s\n", strerror(errno));
            retries--;
            usleep(10000); // Wait before retrying
        }
    }

    fprintf(stderr, "Failed to wake up MPU-6050 after multiple retries.\n");
    return -1; // Failure
}

// Function to read gyroscope data
int read_gyro_data(int16_t *x, int16_t *y, int16_t *z) {
    uint8_t data[6];
    int retries = 3;

    // Read 6 bytes starting from GYRO_XOUT_H
    while (retries > 0) {
        if (write(i2c_fd, (char *)&GYRO_XOUT_H, 1) == 1) {
            if (read(i2c_fd, data, 6) == 6) {
                // Combine high and low bytes for each axis
                *x = (int16_t)((data[0] << 8) | data[1]);
                *y = (int16_t)((data[2] << 8) | data[3]);
                *z = (int16_t)((data[4] << 8) | data[5]);
                return 0; // Success
            } else {
                fprintf(stderr, "Error reading gyroscope data: %s\n", strerror(errno));
                retries--;
                usleep(10000); // Wait before retrying
            }
        } else {
            fprintf(stderr, "Error writing to I2C device: %s\n", strerror(errno));
            retries--;
            usleep(10000); // Wait before retrying
        }
    }

    fprintf(stderr, "Failed to read gyroscope data after multiple retries.\n");
    return -1; // Failure
}

// Function to convert raw data to degrees per second
