#define GYRO_XOUT_H 0x43

// Sensitivity scale factor for ±250 deg/sec range
#define GYRO_SCALE_FACTOR 131.0

// I2C bus file descriptor
int i2c_fd;

// File pointer for logging
FILE *log_file;

// Flag to indicate program termination
volatile sig_atomic_t terminate = 0;

// Signal handler for SIGINT and SIGTERM
void signal_handler(int sig) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating...\n", sig);
}

// Function to initialize the MPU-6050
int init_mpu6050() {
    uint8_t data[2];
    int retries = 3;

    // Wake up the sensor (clear sleep mode bit)
    data[0] = PWR_MGMT_1;
    data[1] = 0x00;

    while (retries > 0) {
        if (write(i2c_fd, data, 2) == 2) {
            return 0; // Success
        } else {
            fprintf(stderr, "Error writing to PWR_MGMT_1: %s\n", strerror(errno));
            retries--;
            usleep(10000); // Wait before retrying
        }
    }

    fprintf(stderr, "Failed to wake up MPU-6050 after multiple retries.\n");
    return -1; // Failure
}

