        last_pulse_start = current_time;

        trigger_sensor();
        long pulse_width = measure_pulse_width();

        if (pulse_width > 0) {
            float distance = calculate_distance(pulse_width);
            log_distance(distance);
            printf("Distance: %.2f cm\n", distance);
        } else {
            log_distance(-1.0);
            fprintf(stderr, "Error: Timeout or invalid pulse width.\n");
        }

        gpioDelay(1000000); // 1 second delay
    }

    cleanup();
    return 0;
}

