#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Define GPIO pins for the relays
#define RELAY1_PIN 17
#define RELAY2_PIN 18
#define RELAY3_PIN 27
#define RELAY4_PIN 22

// Define the GPIO chip name
#define GPIO_CHIP "gpiochip0"

// Define the log file name
#define LOG_FILE "watering_log.txt"

// Global variables
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *lines[4];
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_gpio(void);
int set_relay_state(int relay_num, int state);
int log_watering_cycle(int relay_num);
void signal_handler(int sig);

// Signal handler function
void signal_handler(int sig) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", sig);
}

// Initialize GPIO lines
int init_gpio(void) {
    int i;
    struct gpiod_line_request_config config;

    // Open the GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    // Request GPIO lines as outputs
    for (i = 0; i < 4; i++) {
        int pin = (i == 0) ? RELAY1_PIN : ((i == 1) ? RELAY2_PIN : ((i == 2) ? RELAY3_PIN : RELAY4_PIN));
        lines[i] = gpiod_chip_get_line(chip, pin);
        if (!lines[i]) {
            perror("Error getting GPIO line");
            goto cleanup;
        }

        memset(&config, 0, sizeof(config));
        config.consumer = "relay_control";
        config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;

        if (gpiod_line_request(lines[i], &config, 0) < 0) {
            perror("Error requesting GPIO line");
            goto cleanup;
        }

        // Set initial state to HIGH (inactive)
        if (gpiod_line_set_value(lines[i], 1) < 0) {
            perror("Error setting GPIO line value");
            goto cleanup;
        }
    }

    return 0;

cleanup:
    for (i = 0; i < 4; i++) {
        if (lines[i]) {
            gpiod_line_release(lines[i]);
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    return -1;
}

// Set the state of a relay (0 = OFF, 1 = ON)
int set_relay_state(int relay_num, int state) {
    if (relay_num < 0 || relay_num > 3) {
        fprintf(stderr, "Invalid relay number: %d\n", relay_num);
        return -1;
    }

    if (gpiod_line_set_value(lines[relay_num], state) < 0) {
        perror("Error setting relay state");
        return -1;
    }

    return 0;
}

// Log the watering cycle to a file
int log_watering_cycle(int relay_num) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file == NULL) {
        log_file = fopen(LOG_FILE, "a");
        if (log_file == NULL) {
            perror("Error opening log file");
            return -1;
        }
    }

    fprintf(log_file, "%s - Relay %d activated\n", timestamp, relay_num + 1);
    fflush(log_file); // Ensure the log is written immediately

    return 0;
}

int main(void) {
    int i;
    time_t last_watering_time = 0;
    time_t current_time;
    int watering_cycle = 0;

    // Install signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (init_gpio() < 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return 1;
    }

    printf("Plant watering system started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        current_time = time(NULL);

        // Check if it's time to water
        if (difftime(current_time, last_watering_time) >= 86400) {
            printf("Watering cycle %d\n", watering_cycle + 1);

            for (i = 0; i < 4; i++) {
                if (set_relay_state(i, 0) < 0) {
                    fprintf(stderr, "Error deactivating relay %d\n", i + 1);
                }
                if (log_watering_cycle(i) < 0) {
                    fprintf(stderr, "Error logging watering cycle for relay %d\n", i + 1);
                }
                sleep(5);
                if (set_relay_state(i, 1) < 0) {
                    fprintf(stderr, "Error activating relay %d\n", i + 1);
                }
            }

            last_watering_time = current_time;
            watering_cycle++;
        }

        sleep(60); // Poll every 60 seconds
    }

    // Cleanup GPIO
    printf("Cleaning up GPIO...\n");
    for (i = 0; i < 4; i++) {
        if (lines[i]) {
            gpiod_line_release(lines[i]);
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (log_file) {
        fclose(log_file);
    }

    printf("Exiting.\n");
    return 0;
}

