#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

// Define GPIO pins for the relays
#define RELAY1_PIN 17
#define RELAY2_PIN 18
#define RELAY3_PIN 27
#define RELAY4_PIN 22

// Define PWM frequency
#define PWM_FREQUENCY 1000

// Define the log file name
#define LOG_FILE "smart_lighting.log"

// Global variable to track program termination
volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize_gpio();
int set_gpio_mode(int pin, int mode);
int set_pwm_frequency(int pin, int frequency);
int set_pwm_duty_cycle(int pin, int duty_cycle);
int log_event(const char *message);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT || signal == SIGTERM) {
        program_running = 0;
        log_event("Received termination signal. Shutting down...");
    }
}

// Function to initialize the pigpio library
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        log_event("pigpio initialisation failed");
        return -1;
    }
    log_event("pigpio initialised successfully");
    return 0;
}

// Function to set the mode of a GPIO pin
int set_gpio_mode(int pin, int mode) {
    if (gpioSetMode(pin, mode) != 0) {
        char message[100];
        sprintf(message, "Failed to set GPIO %d mode to %d", pin, mode);
        log_event(message);
        return -1;
    }
    char message[100];
    sprintf(message, "GPIO %d mode set to %d", pin, mode);
    log_event(message);
    return 0;
}

// Function to set the PWM frequency of a GPIO pin
int set_pwm_frequency(int pin, int frequency) {
    if (gpioSetPWMfrequency(pin, frequency) != 0) {
        char message[100];
        sprintf(message, "Failed to set PWM frequency of GPIO %d to %d Hz", pin, frequency);
        log_event(message);
        return -1;
    }
    char message[100];
    sprintf(message, "PWM frequency of GPIO %d set to %d Hz", pin, frequency);
    log_event(message);
    return 0;
}

// Function to set the PWM duty cycle of a GPIO pin
int set_pwm_duty_cycle(int pin, int duty_cycle) {
    if (gpioPWM(pin, duty_cycle) != 0) {
        char message[100];
        sprintf(message, "Failed to set PWM duty cycle of GPIO %d to %d", pin, duty_cycle);
        log_event(message);
        return -1;
    }
    char message[100];
    sprintf(message, "PWM duty cycle of GPIO %d set to %d", pin, duty_cycle);
    log_event(message);
    return 0;
}

// Function to log an event to the log file
int log_event(const char *message) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("Error opening log file");
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "[%d-%02d-%02d %02d:%02d:%02d] %s\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, message);
    fclose(fp);
    return 0;
}

int main() {
    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Set GPIO modes for the relay pins
    if (set_gpio_mode(RELAY1_PIN, PI_OUTPUT) != 0 ||
        set_gpio_mode(RELAY2_PIN, PI_OUTPUT) != 0 ||
        set_gpio_mode(RELAY3_PIN, PI_OUTPUT) != 0 ||
        set_gpio_mode(RELAY4_PIN, PI_OUTPUT) != 0) {
        gpioTerminate();
        return 1;
    }

    // Set PWM frequency for the relay pins
    if (set_pwm_frequency(RELAY1_PIN, PWM_FREQUENCY) != 0 ||
        set_pwm_frequency(RELAY2_PIN, PWM_FREQUENCY) != 0 ||
        set_pwm_frequency(RELAY3_PIN, PWM_FREQUENCY) != 0 ||
        set_pwm_frequency(RELAY4_PIN, PWM_FREQUENCY) != 0) {
        gpioTerminate();
        return 1;
    }

    // Sunrise simulation loop
    for (int duty_cycle = 0; duty_cycle <= 255 && program_running; duty_cycle++) {
        if (set_pwm_duty_cycle(RELAY1_PIN, duty_cycle) != 0 ||
            set_pwm_duty_cycle(RELAY2_PIN, duty_cycle) != 0 ||
            set_pwm_duty_cycle(RELAY3_PIN, duty_cycle) != 0 ||
            set_pwm_duty_cycle(RELAY4_PIN, duty_cycle) != 0) {
            gpioTerminate();
            return 1;
        }
        gpioDelay(1000); // 1-second delay
    }

    // Clean up and terminate pigpio
    log_event("Sunrise simulation complete. Terminating pigpio...");
    gpioTerminate();
    log_event("pigpio terminated successfully");

    return 0;
}

