#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

// MPU-6050 I2C address
#define MPU6050_ADDR 0x68

// MPU-6050 registers
#define PWR_MGMT_1 0x6B
#define SMPLRT_DIV 0x19
#define GYRO_CONFIG 0x1B
#define GYRO_XOUT_H 0x43
#define WHO_AM_I 0x75

// LED GPIO pin
#define LED_PIN 17

// Circular buffer size
#define BUFFER_SIZE 100

// Structure to store gyroscope data with timestamp
typedef struct {
    struct timespec timestamp;
    int16_t x;
    int16_t y;
    int16_t z;
} gyro_data_t;

// Circular buffer
gyro_data_t gyro_buffer[BUFFER_SIZE];
int buffer_index = 0;

// I2C handle
int i2c_handle;

// Function prototypes
int init_mpu6050();
int read_gyro_data(int16_t *x, int16_t *y, int16_t *z);
void process_gyro_data(int16_t x, int16_t y, int16_t z, float *x_dps, float *y_dps, float *z_dps);
void store_data(struct timespec timestamp, int16_t x, int16_t y, int16_t z);
void control_led(float x_dps, float y_dps, float z_dps);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    gpioWrite(LED_PIN, 0); // Turn off LED
    i2cClose(i2c_handle);
    gpioTerminate();
    exit(0);
}

// Initialize MPU-6050
int init_mpu6050() {
    // Wake up the sensor
    if (i2cWriteByteData(i2c_handle, PWR_MGMT_1, 0x00) < 0) {
        fprintf(stderr, "Error: Could not wake up MPU-6050\n");
        return -1;
    }
    gpioDelay(100); // Wait for sensor to wake up

    // Set sample rate divider
    if (i2cWriteByteData(i2c_handle, SMPLRT_DIV, 0x07) < 0) {
        fprintf(stderr, "Error: Could not set sample rate divider\n");
        return -1;
    }

    // Set full-scale range
    if (i2cWriteByteData(i2c_handle, GYRO_CONFIG, 0x00) < 0) {
        fprintf(stderr, "Error: Could not set full-scale range\n");
        return -1;
    }

    // Verify WHO_AM_I register
    int who_am_i = i2cReadByteData(i2c_handle, WHO_AM_I);
    if (who_am_i < 0) {
        fprintf(stderr, "Error: Could not read WHO_AM_I register\n");
        return -1;
    }
    if (who_am_i != 0x68) {
        fprintf(stderr, "Error: WHO_AM_I returned 0x%x, expected 0x68\n", who_am_i);
        return -1;
    }

    printf("MPU-6050 initialized successfully\n");
    return 0;
}

// Read gyroscope data
int read_gyro_data(int16_t *x, int16_t *y, int16_t *z) {
    char buffer[6];
    if (i2cReadI2CBlockData(i2c_handle, GYRO_XOUT_H, buffer, 6) < 0) {
        fprintf(stderr, "Error: Could not read gyroscope data\n");
        return -1;
    }

    *x = (int16_t)((buffer[0] << 8) | buffer[1]);
    *y = (int16_t)((buffer[2] << 8) | buffer[3]);
    *z = (int16_t)((buffer[4] << 8) | buffer[5]);

    return 0;
}

// Process gyroscope data (convert to degrees/second)
void process_gyro_data(int16_t x, int16_t y, int16_t z, float *x_dps, float *y_dps, float *z_dps) {
    *x_dps = (float)x / 131.0;
    *y_dps = (float)y / 131.0;
    *z_dps = (float)z / 131.0;
}

// Store data in circular buffer
void store_data(struct timespec timestamp, int16_t x, int16_t y, int16_t z) {
    gyro_buffer[buffer_index].timestamp = timestamp;
    gyro_buffer[buffer_index].x = x;
    gyro_buffer[buffer_index].y = y;
    gyro_buffer[buffer_index].z = z;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

// Control LED based on gyroscope data
void control_led(float x_dps, float y_dps, float z_dps) {
    if (abs(x_dps) > 250 || abs(y_dps) > 250 || abs(z_dps) > 250) {
        gpioWrite(LED_PIN, 1); // Turn on LED
    } else {
        gpioWrite(LED_PIN, 0); // Turn off LED
    }
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, MPU6050_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Could not open I2C bus\n");
        gpioTerminate();
        return 1;
    }

    // Initialize MPU-6050
    if (init_mpu6050() < 0) {
        fprintf(stderr, "Error: MPU-6050 initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set LED pin as output
    gpioSetMode(LED_PIN, PI_OUTPUT);
    gpioWrite(LED_PIN, 0); // Initially turn off the LED

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int16_t x, y, z;
    float x_dps, y_dps, z_dps;
    struct timespec timestamp;

    // Main loop
    while (1) {
        // Read gyroscope data
        if (read_gyro_data(&x, &y, &z) == 0) {
            // Process gyroscope data
            process_gyro_data(x, y, z, &x_dps, &y_dps, &z_dps);

            // Get timestamp
            clock_gettime(CLOCK_REALTIME, &timestamp);

            // Store data in circular buffer
            store_data(timestamp, x, y, z);

            // Control LED
            control_led(x_dps, y_dps, z_dps);

            // Print data (optional)
            printf("X: %d, Y: %d, Z: %d, X_DPS: %.2f, Y_DPS: %.2f, Z_DPS: %.2f\n", x, y, z, x_dps, y_dps, z_dps);
        } else {
            fprintf(stderr, "Error: Failed to read gyro data. Attempting to re-initialize...\n");
            // Attempt to re-initialize I2C and MPU-6050
            i2cClose(i2c_handle);
            i2c_handle = i2cOpen(1, MPU6050_ADDR, 0);
            if (i2c_handle < 0) {
                fprintf(stderr, "Error: Could not open I2C bus after re-initialization\n");
                gpioTerminate();
                return 1;
            }
            if (init_mpu6050() < 0) {
                fprintf(stderr, "Error: MPU-6050 re-initialisation failed\n");
                gpioTerminate();
                return 1;
            }
        }

        // Delay for 50 ms (20 Hz)
        gpioDelay(50);
    }

    return 0;
}

