void process_gyro_data(int16_t x, int16_t y, int16_t z, float *x_dps, float *y_dps, float *z_dps) {
    *x_dps = (float)x / 131.0;
    *y_dps = (float)y / 131.0;
    *z_dps = (float)z / 131.0;
}

// Store data in circular buffer
void store_data(struct timespec timestamp, int16_t x, int16_t y, int16_t z) {
    gyro_buffer[buffer_index].timestamp = timestamp;
    gyro_buffer[buffer_index].x = x;
    gyro_buffer[buffer_index].y = y;
    gyro_buffer[buffer_index].z = z;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

// Control LED based on gyroscope data
void control_led(float x_dps, float y_dps, float z_dps) {
    if (abs(x_dps) > 250 || abs(y_dps) > 250 || abs(z_dps) > 250) {
        gpioWrite(LED_PIN, 1); // Turn on LED
    } else {
        gpioWrite(LED_PIN, 0); // Turn off LED
    }
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, MPU6050_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Could not open I2C bus\n");
        gpioTerminate();
        return 1;
    }

    // Initialize MPU-6050
    if (init_mpu6050() < 0) {
        fprintf(stderr, "Error: MPU-6050 initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set LED pin as output
    gpioSetMode(LED_PIN, PI_OUTPUT);
    gpioWrite(LED_PIN, 0); // Initially turn off the LED

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int16_t x, y, z;
    float x_dps, y_dps, z_dps;
    struct timespec timestamp;

    // Main loop
    while (1) {
        // Read gyroscope data
        if (read_gyro_data(&x, &y, &z) == 0) {
            // Process gyroscope data
            process_gyro_data(x, y, z, &x_dps, &y_dps, &z_dps);

            // Get timestamp
            clock_gettime(CLOCK_REALTIME, &timestamp);

            // Store data in circular buffer
            store_data(timestamp, x, y, z);

            // Control LED
            control_led(x_dps, y_dps, z_dps);

            // Print data (optional)
            printf("X: %d, Y: %d, Z: %d, X_DPS: %.2f, Y_DPS: %.2f, Z_DPS: %.2f\n", x, y, z, x_dps, y_dps, z_dps);
        } else {
            fprintf(stderr, "Error: Failed to read gyro data. Attempting to re-initialize...\n");
            // Attempt to re-initialize I2C and MPU-6050
            i2cClose(i2c_handle);
            i2c_handle = i2cOpen(1, MPU6050_ADDR, 0);
            if (i2c_handle < 0) {
                fprintf(stderr, "Error: Could not open I2C bus after re-initialization\n");
                gpioTerminate();
                return 1;
            }
            if (init_mpu6050() < 0) {
                fprintf(stderr, "Error: MPU-6050 re-initialisation failed\n");
                gpioTerminate();
                return 1;
            }
        }

        // Delay for 50 ms (20 Hz)
        gpioDelay(50);
    }

    return 0;
}

