#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <fcntl.h>
#include <errno.h>

// Configuration
#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE SPI_MODE_0
#define SPI_BITS_PER_WORD 8
#define SPI_SPEED 1000000 // 1 MHz
#define CS_GPIO 8
#define GYRO_XOUT_H 0x43
#define GYRO_XOUT_L 0x44
#define GYRO_YOUT_H 0x45
#define GYRO_YOUT_L 0x46
#define GYRO_ZOUT_H 0x47
#define GYRO_ZOUT_L 0x48
#define GYRO_SCALE 131.0
#define LOG_FILE "gyro_log.txt"
#define RETRY_COUNT 3
#define RETRY_DELAY_MS 10

// Global variables
int spi_fd = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Structure to hold gyroscope data
typedef struct {
    float x_rate;
    float y_rate;
    float z_rate;
} gyro_data_t;

// Function prototypes
int spi_init(void);
int spi_transfer(unsigned char *tx_buf, unsigned char *rx_buf, int len);
int read_gyro_data(gyro_data_t *data);
void convert_raw_data(int16_t raw_data, float *rate);
int log_data(const gyro_data_t *data);
void signal_handler(int signal);
void cleanup(void);

// SPI Initialization
int spi_init(void) {
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }

    // Configure SPI mode
    int mode = SPI_MODE;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) == -1) {
        perror("Error setting SPI mode");
        close(spi_fd);
        return -1;
    }

    // Configure bits per word
    int bits = SPI_BITS_PER_WORD;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) == -1) {
        perror("Error setting bits per word");
        close(spi_fd);
        return -1;
    }

    // Configure SPI speed
    int speed = SPI_SPEED;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) == -1) {
        perror("Error setting SPI speed");
        close(spi_fd);
        return -1;
    }

    return 0;
}

// SPI Transfer with Chip Select Control
int spi_transfer(unsigned char *tx_buf, unsigned char *rx_buf, int len) {
    if (gpioWrite(CS_GPIO, 0) != 0) {
        fprintf(stderr, "Error setting CS low\n");
        return -1;
    }

    struct spi_ioc_transfer transfer = {
        .tx_buf = (unsigned long)tx_buf,
        .rx_buf = (unsigned long)rx_buf,
        .len = len,
        .delay_usecs = 0,
        .speed_hz = SPI_SPEED,
        .bits_per_word = SPI_BITS_PER_WORD,
    };

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &transfer) < 0) {
        perror("Error during SPI transfer");
        gpioWrite(CS_GPIO, 1);
        return -1;
    }

    if (gpioWrite(CS_GPIO, 1) != 0) {
        fprintf(stderr, "Error setting CS high\n");
        return -1;
    }

    return 0;
}

// Read Gyroscope Data
int read_gyro_data(gyro_data_t *data) {
    unsigned char tx_buf[7];
    unsigned char rx_buf[7];
    int16_t raw_x, raw_y, raw_z;

    // Construct the transmit buffer to read 6 bytes starting from GYRO_XOUT_H
    tx_buf[0] = GYRO_XOUT_H | 0x80; // Read command (MSB = 1)
    memset(rx_buf, 0, sizeof(rx_buf));

    for (int i = 0; i < RETRY_COUNT; ++i) {
        if (spi_transfer(tx_buf, rx_buf, 7) == 0) {
            // Combine the high and low bytes for each axis
            raw_x = (int16_t)((rx_buf[1] << 8) | rx_buf[2]);
            raw_y = (int16_t)((rx_buf[3] << 8) | rx_buf[4]);
            raw_z = (int16_t)((rx_buf[5] << 8) | rx_buf[6]);

            convert_raw_data(raw_x, &data->x_rate);
            convert_raw_data(raw_y, &data->y_rate);
            convert_raw_data(raw_z, &data->z_rate);

            return 0; // Success
        } else {
            fprintf(stderr, "SPI transfer failed, retrying (%d/%d)\n", i + 1, RETRY_COUNT);
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
        }
    }

    fprintf(stderr, "Failed to read gyro data after %d retries\n", RETRY_COUNT);
    return -1; // Failure
}

// Convert Raw Data to Degrees per Second
void convert_raw_data(int16_t raw_data, float *rate) {
    *rate = (float)raw_data / GYRO_SCALE;
}

// Log Data to File
int log_data(const gyro_data_t *data) {
    time_t now = time(NULL);
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);

    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", localtime(&now));
    snprintf(timestamp + strlen(timestamp), sizeof(timestamp) - strlen(timestamp), ".%09ldZ", ts.tv_nsec);

    fprintf(log_file, "%s,%.2f,%.2f,%.2f\n", timestamp, data->x_rate, data->y_rate, data->z_rate);
    fflush(log_file); // Ensure data is written immediately

    return 0;
}

// Signal Handler
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Cleanup Resources
void cleanup(void) {
    if (spi_fd != -1) {
        close(spi_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main(void) {
    gyro_data_t gyro_data;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set CS GPIO as output
    gpioSetMode(CS_GPIO, PI_OUTPUT);
    gpioWrite(CS_GPIO, 1); // Initialize CS to high

    // Initialize SPI
    if (spi_init() != 0) {
        fprintf(stderr, "SPI initialisation failed\n");
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        cleanup();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        if (read_gyro_data(&gyro_data) == 0) {
            log_data(&gyro_data);
        } else {
            fprintf(stderr, "Failed to read or log data\n");
        }

        gpioDelay(10000); // 10 ms delay
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

