#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>
#include <pigpio.h>

// Configuration
#define SPI_BUS 0
#define SPI_CHIP_SELECT_GPIO 8 // CE0
#define LED_GPIO 17
#define SPI_FREQUENCY 3900000 // 3.9 MHz
#define GYRO_XOUT_H 0x43
#define GYRO_YOUT_H 0x45
#define GYRO_ZOUT_H 0x47
#define SENSITIVITY 131.0f // LSB/deg/s
#define BUFFER_SIZE 64
#define MAX_ANGLE 200.0f
#define MIN_ANGLE -200.0f

// Data structure for gyroscope readings
typedef struct {
    struct timespec timestamp;
    float x;
    float y;
    float z;
} gyro_data_t;

// Circular buffer
gyro_data_t gyro_buffer[BUFFER_SIZE];
int buffer_index = 0;

// Global variables for SPI and GPIO
struct gpiod_chip *gpio_chip;
struct gpiod_line *cs_line;
int spi_handle;

// Function prototypes
int spi_init(int spi_bus, int spi_frequency);
int spi_transfer(uint8_t address, uint8_t *data, int len);
int read_gyro_data(float *x, float *y, float *z);
void add_to_buffer(float x, float y, float z);
void print_buffer();
void signal_handler(int signal);

// SPI Initialization
int spi_init(int spi_bus, int spi_frequency) {
    spi_handle = spiOpen(spi_bus, spi_frequency, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error opening SPI device: %d\n", spi_handle);
        return -1;
    }
    return 0;
}

// SPI Transfer with Chip Select Control
int spi_transfer(uint8_t address, uint8_t *data, int len) {
    int ret;
    uint8_t tx_buf[len + 1];
    uint8_t rx_buf[len + 1];

    // Set chip select low
    if (gpiod_line_set_value(cs_line, 0) < 0) {
        fprintf(stderr, "Error setting chip select low\n");
        return -1;
    }

    tx_buf[0] = address | 0x80; // Set MSB for read
    memcpy(tx_buf + 1, data, len);

    ret = spiXfer(spi_handle, (char *)tx_buf, (char *)rx_buf, len + 1);
    if (ret < 0) {
        fprintf(stderr, "SPI transfer error: %d\n", ret);
        gpiod_line_set_value(cs_line, 1); // Set chip select high on error
        return -1;
    }

    // Set chip select high
    if (gpiod_line_set_value(cs_line, 1) < 0) {
        fprintf(stderr, "Error setting chip select high\n");
        return -1;
    }

    memcpy(data, rx_buf + 1, len);
    return 0;
}

// Read Gyroscope Data
int read_gyro_data(float *x, float *y, float *z) {
    uint8_t data[6];
    int16_t raw_x, raw_y, raw_z;

    if (spi_transfer(GYRO_XOUT_H, data, 6) < 0) {
        fprintf(stderr, "Error reading gyro data\n");
        return -1;
    }

    raw_x = (data[0] << 8) | data[1];
    raw_y = (data[2] << 8) | data[3];
    raw_z = (data[4] << 8) | data[5];

    *x = (float)raw_x / SENSITIVITY;
    *y = (float)raw_y / SENSITIVITY;
    *z = (float)raw_z / SENSITIVITY;

    return 0;
}

// Add data to circular buffer
void add_to_buffer(float x, float y, float z) {
    clock_gettime(CLOCK_REALTIME, &gyro_buffer[buffer_index].timestamp);
    gyro_buffer[buffer_index].x = x;
    gyro_buffer[buffer_index].y = y;
    gyro_buffer[buffer_index].z = z;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

// Print the circular buffer as CSV
void print_buffer() {
    printf("Timestamp,X,Y,Z\n");
    for (int i = 0; i < BUFFER_SIZE; i++) {
        printf("%ld.%09ld,%.2f,%.2f,%.2f\n",
               gyro_buffer[i].timestamp.tv_sec,
               gyro_buffer[i].timestamp.tv_nsec,
               gyro_buffer[i].x,
               gyro_buffer[i].y,
               gyro_buffer[i].z);
    }
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    spiClose(spi_handle);
    gpiod_line_release(cs_line);
    gpiod_chip_close(gpio_chip);
    gpioTerminate();
    exit(0);
}

int main() {
    // Initialize GPIO
    gpio_chip = gpiod_chip_open_by_name("gpiochip0");
    if (!gpio_chip) {
        fprintf(stderr, "Error opening GPIO chip\n");
        return 1;
    }

    cs_line = gpiod_chip_get_line(gpio_chip, SPI_CHIP_SELECT_GPIO);
    if (!cs_line) {
        fprintf(stderr, "Error getting GPIO line %d\n", SPI_CHIP_SELECT_GPIO);
        gpiod_chip_close(gpio_chip);
        return 1;
    }

    if (gpiod_line_request_output(cs_line, "main", 1) < 0) {
        fprintf(stderr, "Error requesting GPIO line %d as output\n", SPI_CHIP_SELECT_GPIO);
        gpiod_chip_close(gpio_chip);
        return 1;
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        gpiod_line_release(cs_line);
        gpiod_chip_close(gpio_chip);
        return 1;
    }

    gpioSetMode(LED_GPIO, PI_OUTPUT);

    // Initialize SPI
    if (spi_init(SPI_BUS, SPI_FREQUENCY) < 0) {
        fprintf(stderr, "SPI initialisation failed\n");
        gpiod_line_release(cs_line);
        gpiod_chip_close(gpio_chip);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler
    signal(SIGINT, signal_handler);

    float x, y, z;
    int led_state = 0;

    while (1) {
        if (read_gyro_data(&x, &y, &z) == 0) {
            add_to_buffer(x, y, z);

            // Check for angle limits and blink LED
            if (x > MAX_ANGLE || x < MIN_ANGLE ||
                y > MAX_ANGLE || y < MIN_ANGLE ||
                z > MAX_ANGLE || z < MIN_ANGLE) {
                if (!led_state) {
                    gpioWrite(LED_GPIO, 1); // Turn LED on
                    led_state = 1;
                }
                gpioDelay(500); // Wait 500ms
                gpioWrite(LED_GPIO, 0); // Turn LED off
                led_state = 0;
            }
        } else {
            fprintf(stderr, "Error reading gyro data, retrying...\n");
        }

        gpioDelay(10); // Delay 10ms
    }

    return 0;
}

