#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

// Constants
#define I2C_BUS "/dev/i2c-1"
#define SI1145_ADDR 0x5A
#define AMBIENT_LIGHT_REG 0x20
#define PROXIMITY_REG 0x22
#define GPIO_CHIP "gpiochip0"
#define GPIO_LINE 17
#define PROXIMITY_THRESHOLD 100
#define RETRY_COUNT 3
#define RETRY_DELAY_MS 10
#define LOG_FILE "biometric_log.txt"

// Global variables
static int i2c_fd = -1;
static FILE *log_file = NULL;
static struct gpiod_chip *gpio_chip = NULL;
static struct gpiod_line *gpio_line_line = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int i2c_read_reg(int fd, uint8_t reg, uint8_t *data, int len);
int i2c_write_reg(int fd, uint8_t reg, uint8_t data);
int read_sensor_data(int fd, uint16_t *ambient_light, uint16_t *proximity);
void log_data(FILE *fp, uint16_t ambient_light, uint16_t proximity);
void control_led(struct gpiod_line *line, uint16_t proximity);
void signal_handler(int sig);
int setup_gpio(struct gpiod_chip **chip, struct gpiod_line **line);
void cleanup_gpio(struct gpiod_chip *chip, struct gpiod_line *line);

// I2C read function with retry
int i2c_read_reg(int fd, uint8_t reg, uint8_t *data, int len) {
    int retries = RETRY_COUNT;
    int result;

    while (retries > 0) {
        if (write(fd, &reg, 1) != 1) {
            perror("I2C write (register) failed");
            retries--;
            usleep(RETRY_DELAY_MS * 1000); // Convert ms to microseconds
            continue;
        }

        if (read(fd, data, len) != len) {
            perror("I2C read failed");
            retries--;
            usleep(RETRY_DELAY_MS * 1000);
            continue;
        }

        return 0; // Success
    }

    fprintf(stderr, "I2C read failed after %d retries\n", RETRY_COUNT);
    return -1; // Failure
}

// I2C write function with retry
int i2c_write_reg(int fd, uint8_t reg, uint8_t data) {
    int retries = RETRY_COUNT;
    int result;
    uint8_t buf[2];

    buf[0] = reg;
    buf[1] = data;

    while (retries > 0) {
        if (write(fd, buf, 2) != 2) {
            perror("I2C write failed");
            retries--;
            usleep(RETRY_DELAY_MS * 1000);
            continue;
        }
        return 0; // Success
    }

    fprintf(stderr, "I2C write failed after %d retries\n", RETRY_COUNT);
    return -1; // Failure
}

// Function to read sensor data
int read_sensor_data(int fd, uint16_t *ambient_light, uint16_t *proximity) {
    uint8_t data[4];

    if (i2c_read_reg(fd, AMBIENT_LIGHT_REG, data, 2) != 0) {
        fprintf(stderr, "Failed to read ambient light data\n");
        return -1;
    }

    if (i2c_read_reg(fd, PROXIMITY_REG, data + 2, 2) != 0) {
        fprintf(stderr, "Failed to read proximity data\n");
        return -1;
    }

    *ambient_light = (data[1] << 8) | data[0];
    *proximity = (data[3] << 8) | data[2];

    return 0;
}

// Function to log data to file
void log_data(FILE *fp, uint16_t ambient_light, uint16_t proximity) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);
    fprintf(fp, "%s,AmbientLight:%u,Proximity:%u\n", timestamp, ambient_light, proximity);
    fflush(fp); // Ensure data is written to disk immediately
}

// Function to control the LED
void control_led(struct gpiod_line *line, uint16_t proximity) {
    if (proximity > PROXIMITY_THRESHOLD) {
        if (gpiod_line_set_value(line, 1) != 0) {
            perror("Failed to set GPIO high");
        }
    } else {
        if (gpiod_line_set_value(line, 0) != 0) {
            perror("Failed to set GPIO low");
        }
    }
}

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Setup GPIO
int setup_gpio(struct gpiod_chip **chip, struct gpiod_line **line) {
    *chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!*chip) {
        perror("Failed to open GPIO chip");
        return -1;
    }

    *line = gpiod_chip_get_line(*chip, GPIO_LINE);
    if (!*line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(*chip);
        return -1;
    }

    if (gpiod_line_request_output(*line, "biometric", 0) != 0) {
        perror("Failed to request GPIO line for output");
        gpiod_chip_close(*chip);
        return -1;
    }

    return 0;
}

// Cleanup GPIO
void cleanup_gpio(struct gpiod_chip *chip, struct gpiod_line *line) {
    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
}

int main() {
    uint16_t ambient_light, proximity;

    // Signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, SI1145_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        close(i2c_fd);
        return 1;
    }

    // Setup GPIO
    if (setup_gpio(&gpio_chip, &gpio_line_line) != 0) {
        fprintf(stderr, "GPIO setup failed, continuing without LED control\n");
    }

    // Main loop
    while (!terminate) {
        if (read_sensor_data(i2c_fd, &ambient_light, &proximity) == 0) {
            log_data(log_file, ambient_light, proximity);
            if (gpio_line_line) {
                control_led(gpio_line_line, proximity);
            }
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }

        usleep(100 * 1000); // 100 ms
    }

    // Cleanup
    close(i2c_fd);
    fclose(log_file);
    if (gpio_line_line) {
        gpiod_line_set_value(gpio_line_line, 0); // Turn off LED
        gpiod_line_release(gpio_line_line);
    }
    if (gpio_chip) {
        gpiod_chip_close(gpio_chip);
    }

    return 0;
}

