// Constants
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 0
#define CS_PIN 8
#define SAMPLE_RATE 100 // Hz
#define SAMPLE_PERIOD_US (1000000 / SAMPLE_RATE) // microseconds
#define GYRO_X_REG 0x02
#define GYRO_Y_REG 0x04
#define GYRO_SENSITIVITY 200.0 // LSB/deg/s

// Global variables
int spi_handle;
FILE *fp;
volatile sig_atomic_t terminate = 0;

// Structure to hold gyroscope data
typedef struct {
    long long timestamp_us;
    int16_t x_rate;
    int16_t y_rate;
} gyro_data_t;

// Function prototypes
int init_spi();
int read_gyro_data(int16_t *x_rate, int16_t *y_rate);
void log_data(gyro_data_t data);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize SPI communication
int init_spi() {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "Error opening SPI channel: %d\n", spi_handle);
        return -1;
    }
    return 0;
}

// Read gyroscope data from SPI
int read_gyro_data(int16_t *x_rate, int16_t *y_rate) {
    char tx_buf[2];
    char rx_buf[2];
    int result;

    // Read X-axis data
    tx_buf[0] = GYRO_X_REG | 0x80; // Read bit set
    tx_buf[1] = 0x00; // Dummy byte

    result = spiXfer(spi_handle, tx_buf, rx_buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading X-axis data: %d\n", result);
        return -1;
    }

    *x_rate = (int16_t)((rx_buf[0] << 8) | rx_buf[1]);

    // Read Y-axis data
    tx_buf[0] = GYRO_Y_REG | 0x80; // Read bit set
    tx_buf[1] = 0x00; // Dummy byte

    result = spiXfer(spi_handle, tx_buf, rx_buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading Y-axis data: %d\n", result);
        return -1;
    }

    *y_rate = (int16_t)((rx_buf[0] << 8) | rx_buf[1]);

    return 0;
}

