void log_data(gyro_data_t data) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    long long timestamp_us = (long long)ts.tv_sec * 1000000 + ts.tv_nsec / 1000;

    fprintf(fp, "%lld,%d,%d\n", timestamp_us, data.x_rate, data.y_rate);
    fflush(fp); // Ensure data is written to disk immediately
}

int main() {
