    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set CS pin as output
    gpioSetMode(CS_PIN, PI_OUTPUT);
    gpioWrite(CS_PIN, 1); // Deactivate chip select initially

    // Initialize SPI
    if (init_spi() != 0) {
        gpioTerminate();
        return 1;
    }

    // Open CSV file for logging
    fp = fopen("gyro_data.csv", "w");
    if (fp == NULL) {
        fprintf(stderr, "Error opening gyro_data.csv\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Write CSV header
    fprintf(fp, "timestamp_us,X_rate,Y_rate\n");

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    int16_t x_rate, y_rate;
    gyro_data_t data;

    // Main loop
    while (!terminate) {
        // Read gyroscope data
        if (read_gyro_data(&x_rate, &y_rate) == 0) {
            // Get timestamp
            struct timespec ts;
            clock_gettime(CLOCK_REALTIME, &ts);
            data.timestamp_us = (long long)ts.tv_sec * 1000000 + ts.tv_nsec / 1000;
            data.x_rate = x_rate;
            data.y_rate = y_rate;

            // Log data
            log_data(data);
        } else {
            fprintf(stderr, "Failed to read gyro data. Re-initializing SPI...\n");
            // Attempt to re-initialize SPI
            spiClose(spi_handle);
            if (init_spi() != 0) {
                fprintf(stderr, "Failed to re-initialize SPI. Exiting.\n");
                terminate = 1; // Exit loop if re-initialization fails
            }
        }

        // Delay for approximately 10 ms (100 Hz sampling rate)
        gpioDelay(SAMPLE_PERIOD_US);
    }

    // Cleanup
    spiClose(spi_handle);
    fclose(fp);
    gpioTerminate();

    return 0;
}

