#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>
#include <string.h>

// Define GPIO pins
#define SENSOR_1_PIN 23
#define SENSOR_2_PIN 24
#define ALERT_PIN 17

// Define constants
#define ALERT_DURATION_MS 2000
#define DEBOUNCE_DELAY_MS 500

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;

// Function prototypes
void signal_handler(int signal);
void log_event(const char *message);
void sensor_callback(int gpio, int level, uint32_t tick);

// Signal handler function
void signal_handler(int signal) {
    running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);

    // Close the log file if it's open
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }

    // Set the alert pin LOW
    gpioWrite(ALERT_PIN, 0);

    // Terminate pigpio
    gpioTerminate();

    exit(0);
}

// Function to log events to a file
void log_event(const char *message) {
    if (log_file == NULL) {
        fprintf(stderr, "Error: Log file is not open.\n");
        return;
    }

    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s - %s\n", timestamp, message);
    fflush(log_file); // Ensure the log is written immediately
}

// Callback function for sensor events
void sensor_callback(int gpio, int level, uint32_t tick) {
    static uint32_t last_tick[2] = {0, 0}; // Store last tick for each sensor
    static int both_high = 0;
    static uint32_t both_high_start_tick = 0;

    int sensor_index = (gpio == SENSOR_1_PIN) ? 0 : 1;

    if (level == 1) { // Rising edge (sensor tilted)
        last_tick[sensor_index] = tick;

        if (gpio == SENSOR_1_PIN && gpioRead(SENSOR_2_PIN) == 1) {
            if (!both_high) {
                both_high = 1;
                both_high_start_tick = tick;
            }
        } else if (gpio == SENSOR_2_PIN && gpioRead(SENSOR_1_PIN) == 1) {
            if (!both_high) {
                both_high = 1;
                both_high_start_tick = tick;
            }
        }

        if (both_high) {
            uint32_t current_tick = gpioTick();
            if ((current_tick - both_high_start_tick) >= DEBOUNCE_DELAY_MS * 1000) {
                both_high = 0; // Reset flag after triggering alert
                gpioWrite(ALERT_PIN, 1); // Set alert pin HIGH
                log_event("Seismic event detected!");
                gpioDelay(ALERT_DURATION_MS); // Keep alert HIGH for 2 seconds
                gpioWrite(ALERT_PIN, 0); // Set alert pin LOW
            }
        }
    } else { // Falling edge (sensor returned to normal)
        if (both_high) {
            both_high = 0;
        }
    }
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(SENSOR_1_PIN, PI_INPUT);
    gpioSetMode(SENSOR_2_PIN, PI_INPUT);
    gpioSetMode(ALERT_PIN, PI_OUTPUT);

    // Set pull-down resistors (not directly supported by pigpio, but can be done in wiringPiSetupGpio)
    // gpioSetPullUpDown(SENSOR_1_PIN, PI_PUD_DOWN);
    // gpioSetPullUpDown(SENSOR_2_PIN, PI_PUD_DOWN);

    // Open the log file
    log_file = fopen("seismic_events.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Register callbacks for both sensors
    if (gpioSetAlertFuncEx(SENSOR_1_PIN, sensor_callback, NULL) != 0) {
        fprintf(stderr, "Error registering callback for sensor 1\n");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }
    if (gpioSetAlertFuncEx(SENSOR_2_PIN, sensor_callback, NULL) != 0) {
        fprintf(stderr, "Error registering callback for sensor 2\n");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    printf("Seismic monitoring started. Press Ctrl+C to exit.\n");

    // Main loop (keep the program running until a signal is received)
    while (running) {
        gpioDelay(100); // Sleep for 100ms to reduce CPU usage
    }

    // Cleanup (should not reach here if signal handler works correctly)
    fclose(log_file);
    gpioWrite(ALERT_PIN, 0);
    gpioTerminate();

    return 0;
}

