#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <time.h>
#include <pthread.h>
#include <stdbool.h>

// Define SPI parameters
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 0        // CPOL=0, CPHA=0

// Define GPIO pins
#define LED_PIN 17

// Define ADXRS290 register addresses
#define RATE_XL 0x02
#define RATE_XH 0x03

// Define sensitivity
#define SENSITIVITY 200.0 // LSB/deg/s

// Define circular buffer size
#define BUFFER_SIZE 100

// Define angular velocity threshold
#define THRESHOLD 20.0 // deg/s

// Structure to hold gyroscope data and timestamp
typedef struct {
    struct timespec timestamp;
    float angular_velocity;
} GyroData;

// Circular buffer structure
typedef struct {
    GyroData data[BUFFER_SIZE];
    int head;
    int tail;
    int count;
    pthread_mutex_t mutex;
} CircularBuffer;

// Global variables
int spi_handle;
CircularBuffer gyro_buffer;
bool running = true;

// Function prototypes
int spi_read_register(uint8_t address, uint16_t *data);
float convert_to_degrees_per_second(int16_t raw_data);
void add_to_buffer(CircularBuffer *buffer, float angular_velocity);
float get_latest_reading(CircularBuffer *buffer);
void control_led(float angular_velocity);
void signal_handler(int signal);
void *data_processing_thread(void *arg);

// SPI read function
int spi_read_register(uint8_t address, uint16_t *data) {
    char tx_buf[2];
    char rx_buf[2];

    // Set MSB of address to 1 for read operation
    tx_buf[0] = (address | 0x80);
    tx_buf[1] = 0x00; // Dummy byte for reading data

    int result = spiXfer(spi_handle, tx_buf, rx_buf, 2);
    if (result != 2) {
        fprintf(stderr, "SPI read error: %d\n", result);
        return -1;
    }

    *data = (rx_buf[0] << 8) | rx_buf[1];
    return 0;
}

// Convert raw data to degrees per second
float convert_to_degrees_per_second(int16_t raw_data) {
    return (float)raw_data / SENSITIVITY;
}

// Add data to circular buffer
void add_to_buffer(CircularBuffer *buffer, float angular_velocity) {
    clock_gettime(CLOCK_MONOTONIC, &buffer->data[buffer->head].timestamp);
    buffer->data[buffer->head].angular_velocity = angular_velocity;

    buffer->head = (buffer->head + 1) % BUFFER_SIZE;
    if (buffer->count < BUFFER_SIZE) {
        buffer->count++;
    } else {
        buffer->tail = (buffer->tail + 1) % BUFFER_SIZE;
    }
}

// Get the latest reading from the circular buffer
float get_latest_reading(CircularBuffer *buffer) {
    if (buffer->count == 0) {
        return 0.0;
    }
    int index = (buffer->head - 1 + BUFFER_SIZE) % BUFFER_SIZE;
    return buffer->data[index].angular_velocity;
}

// Control the LED based on angular velocity
void control_led(float angular_velocity) {
    if (abs(angular_velocity) > THRESHOLD) {
        gpioWrite(LED_PIN, 1); // Turn LED on
    } else {
        gpioWrite(LED_PIN, 0); // Turn LED off
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    running = false;
}

// Data processing thread function
void *data_processing_thread(void *arg) {
    while (running) {
        uint16_t raw_data;
        if (spi_read_register(RATE_XL, &raw_data) == 0) {
            int16_t combined_data = (int16_t)raw_data;
            float angular_velocity = convert_to_degrees_per_second(combined_data);
            add_to_buffer(&gyro_buffer, angular_velocity);
            control_led(angular_velocity);
        } else {
            fprintf(stderr, "Error reading gyroscope data.\n");
        }
        gpioDelay(10); // 10 ms delay
    }
    return NULL;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize SPI
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI initialisation failed\n");
        gpioTerminate();
        return 1;
    }

    // Initialize LED pin as output
    gpioSetMode(LED_PIN, PI_OUTPUT);
    gpioWrite(LED_PIN, 0); // Turn LED off initially

    // Initialize circular buffer
    gyro_buffer.head = 0;
    gyro_buffer.tail = 0;
    gyro_buffer.count = 0;
    pthread_mutex_init(&gyro_buffer.mutex, NULL);

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Create data processing thread
    pthread_t thread_id;
    if (pthread_create(&thread_id, NULL, data_processing_thread, NULL) != 0) {
        fprintf(stderr, "Failed to create data processing thread\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Main loop (keep the program running until a signal is received)
    while (running) {
        sleep(1); // Sleep for 1 second
    }

    // Clean up resources
    pthread_join(thread_id, NULL);
    pthread_mutex_destroy(&gyro_buffer.mutex);
    spiClose(spi_handle);
    gpioWrite(LED_PIN, 0); // Turn LED off
    gpioTerminate();

    return 0;
}

