#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <time.h>

// Define GPIO pins for the lamps
#define LAMP1_GPIO 17
#define LAMP2_GPIO 18
#define LAMP3_GPIO 27

// Define PWM frequency
#define PWM_FREQUENCY 100

// Global variable to store the fade duration
int fade_duration = 0;

// Function prototypes
void fade_lamp(int gpio, int duration);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);

    // Turn off all lamps
    gpioPWM(LAMP1_GPIO, 0);
    gpioPWM(LAMP2_GPIO, 0);
    gpioPWM(LAMP3_GPIO, 0);

    // Terminate pigpio
    gpioTerminate();

    exit(0);
}

// Function to fade a lamp
void fade_lamp(int gpio, int duration) {
    int i;
    int duty_cycle;

    printf("Fading lamp on GPIO %d for %d seconds...\n", gpio, duration);

    for (i = 255; i >= 0; i--) {
        duty_cycle = i;
        gpioPWM(gpio, duty_cycle);
        gpioDelay(duration * 1000000 / 256); // Delay in microseconds
    }

    printf("Lamp on GPIO %d faded to 0% duty cycle.\n", gpio);
}

int main(int argc, char *argv[]) {
    int i;

    // Check for command-line argument
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <fade_duration_seconds>\n", argv[0]);
        return 1;
    }

    // Validate the fade duration
    fade_duration = atoi(argv[1]);
    if (fade_duration < 1 || fade_duration > 3600) {
        fprintf(stderr, "Error: Fade duration must be between 1 and 3600 seconds.\n");
        return 1;
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins to output mode
    gpioSetMode(LAMP1_GPIO, PI_OUTPUT);
    gpioSetMode(LAMP2_GPIO, PI_OUTPUT);
    gpioSetMode(LAMP3_GPIO, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(LAMP1_GPIO, PWM_FREQUENCY);
    gpioSetPWMfrequency(LAMP2_GPIO, PWM_FREQUENCY);
    gpioSetPWMfrequency(LAMP3_GPIO, PWM_FREQUENCY);

    // Set PWM range
    gpioSetPWMrange(LAMP1_GPIO, 255);
    gpioSetPWMrange(LAMP2_GPIO, 255);
    gpioSetPWMrange(LAMP3_GPIO, 255);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Fade the lamps sequentially
    fade_lamp(LAMP1_GPIO, fade_duration);
    fade_lamp(LAMP2_GPIO, fade_duration);
    fade_lamp(LAMP3_GPIO, fade_duration);

    printf("Sunset simulation complete.\n");

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

