#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <gpiod.h>
#include <unistd.h>
#include <time.h>

// Define GPIO pins for the relays
#define RED_RELAY_PIN 17
#define YELLOW_RELAY_PIN 22
#define GREEN_RELAY_PIN 23
#define YELLOW_RELAY_PIN_2 24

// Define relay states
#define RELAY_ON 0
#define RELAY_OFF 1

// Global variable for the GPIO chip
struct gpiod_chip *chip;

// Signal handler function
void signal_handler(int sig)
{
    printf("\nCaught signal %d, cleaning up...\n", sig);

    // Release GPIO lines
    if (chip) {
        struct gpiod_line *red_line = gpiod_chip_get_line(chip, RED_RELAY_PIN);
        if (red_line) {
            gpiod_line_release(red_line);
        }

        struct gpiod_line *yellow_line = gpiod_chip_get_line(chip, YELLOW_RELAY_PIN);
        if (yellow_line) {
            gpiod_line_release(yellow_line);
        }

        struct gpiod_line *green_line = gpiod_chip_get_line(chip, GREEN_RELAY_PIN);
        if (green_line) {
            gpiod_line_release(green_line);
        }

        struct gpiod_line *yellow_line_2 = gpiod_chip_get_line(chip, YELLOW_RELAY_PIN_2);
        if (yellow_line_2) {
            gpiod_line_release(yellow_line_2);
        }

        gpiod_chip_close(chip);
    }

    exit(0);
}

int main()
{
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open the GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Error opening GPIO chip");
        return 1;
    }

    // Request GPIO lines for output
    struct gpiod_line *red_line = gpiod_chip_get_line(chip, RED_RELAY_PIN);
    if (!red_line) {
        perror("Error getting red relay line");
        gpiod_chip_close(chip);
        return 1;
    }

    struct gpiod_line *yellow_line = gpiod_chip_get_line(chip, YELLOW_RELAY_PIN);
    if (!yellow_line) {
        perror("Error getting yellow relay line");
        gpiod_line_release(red_line);
        gpiod_chip_close(chip);
        return 1;
    }

    struct gpiod_line *green_line = gpiod_chip_get_line(chip, GREEN_RELAY_PIN);
    if (!green_line) {
        perror("Error getting green relay line");
        gpiod_line_release(red_line);
        gpiod_line_release(yellow_line);
        gpiod_chip_close(chip);
        return 1;
    }

    struct gpiod_line *yellow_line_2 = gpiod_chip_get_line(chip, YELLOW_RELAY_PIN_2);
    if (!yellow_line_2) {
        perror("Error getting yellow relay line 2");
        gpiod_line_release(red_line);
        gpiod_line_release(yellow_line);
        gpiod_line_release(green_line);
        gpiod_chip_close(chip);
        return 1;
    }

    if (gpiod_line_request_output(red_line, "traffic_light", 0) < 0) {
        perror("Error requesting red relay line for output");
        gpiod_line_release(red_line);
        gpiod_line_release(yellow_line);
        gpiod_line_release(green_line);
        gpiod_line_release(yellow_line_2);
        gpiod_chip_close(chip);
        return 1;
    }

    if (gpiod_line_request_output(yellow_line, "traffic_light", 0) < 0) {
        perror("Error requesting yellow relay line for output");
        gpiod_line_release(red_line);
        gpiod_line_release(yellow_line);
        gpiod_line_release(green_line);
        gpiod_line_release(yellow_line_2);
        gpiod_chip_close(chip);
        return 1;
    }

    if (gpiod_line_request_output(green_line, "traffic_light", 0) < 0) {
        perror("Error requesting green relay line for output");
        gpiod_line_release(red_line);
        gpiod_line_release(yellow_line);
        gpiod_line_release(green_line);
        gpiod_line_release(yellow_line_2);
        gpiod_chip_close(chip);
        return 1;
    }

    if (gpiod_line_request_output(yellow_line_2, "traffic_light", 0) < 0) {
        perror("Error requesting yellow relay line 2 for output");
        gpiod_line_release(red_line);
        gpiod_line_release(yellow_line);
        gpiod_line_release(green_line);
        gpiod_line_release(yellow_line_2);
        gpiod_chip_close(chip);
        return 1;
    }

    // Main loop
    while (1) {
        // Red
        printf("Turning on Red\n");
        if (gpiod_line_set_value(red_line, RELAY_ON) < 0) {
            perror("Error setting red relay value");
            break;
        }
        if (gpiod_line_set_value(yellow_line, RELAY_OFF) < 0) {
            perror("Error setting yellow relay value");
            break;
        }
        if (gpiod_line_set_value(green_line, RELAY_OFF) < 0) {
            perror("Error setting green relay value");
            break;
        }
        if (gpiod_line_set_value(yellow_line_2, RELAY_OFF) < 0) {
