#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define RELAY_GPIO 17
#define I2C_BUS 1
#define MPR121_ADDR 0x5A
#define DEBOUNCE_DELAY_MS 100
#define TOUCH_STATUS_LSB 0x00
#define TOUCH_STATUS_MSB 0x01

// Global variables
static volatile int running = 1;
static int i2c_handle;
static FILE *log_file;
static int relay_state = 0; // 0 = off, 1 = on

// Function prototypes
void log_message(const char *message);
void signal_handler(int signal);
int initialize_mpr121();
int read_touch_status();
void toggle_relay();

// Function to log messages with timestamps
void log_message(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[26];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "[%s] %s\n", timestamp, message);
    fflush(log_file); // Ensure immediate write to file
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    log_message("Received signal, shutting down...");
}

// Function to initialize the MPR121
int initialize_mpr121() {
    int status;

    // Reset MPR121
    status = i2cWriteByteData(i2c_handle, 0x80, 0x63);
    if (status < 0) {
        log_message("Error resetting MPR121");
        return -1;
    }
    gpioDelay(10000); // 10ms delay

    // Stop mode
    status = i2cWriteByteData(i2c_handle, 0x5E, 0x00);
    if (status < 0) {
        log_message("Error setting MPR121 to stop mode");
        return -1;
    }
    gpioDelay(10000); // 10ms delay

    // Enable electrode 0
    status = i2cWriteByteData(i2c_handle, 0x5D, 0x01);
    if (status < 0) {
        log_message("Error enabling electrode 0");
        return -1;
    }
    gpioDelay(10000); // 10ms delay

    // Touch threshold
    status = i2cWriteByteData(i2c_handle, 0x41, 0x0A);
    if (status < 0) {
        log_message("Error setting touch threshold");
        return -1;
    }
    gpioDelay(10000); // 10ms delay

    // Release threshold
    status = i2cWriteByteData(i2c_handle, 0x42, 0x08);
    if (status < 0) {
        log_message("Error setting release threshold");
        return -1;
    }
    gpioDelay(10000); // 10ms delay

    // Debounce
    status = i2cWriteByteData(i2c_handle, 0x5B, 0x21);
    if (status < 0) {
        log_message("Error setting debounce");
        return -1;
    }
    gpioDelay(10000); // 10ms delay

    // Charge time
    status = i2cWriteByteData(i2c_handle, 0x5C, 0x0D);
    if (status < 0) {
        log_message("Error setting charge time");
        return -1;
    }
    gpioDelay(10000); // 10ms delay

    // Run mode
    status = i2cWriteByteData(i2c_handle, 0x5E, 0x0D);
    if (status < 0) {
        log_message("Error setting MPR121 to run mode");
        return -1;
    }
    gpioDelay(10000); // 10ms delay

    return 0;
}

// Function to read the touch status from the MPR121
int read_touch_status() {
    int lsb, msb;
    int status;

    lsb = i2cReadByteData(i2c_handle, TOUCH_STATUS_LSB);
    if (lsb < 0) {
        log_message("Error reading touch status LSB");
        return -1;
    }

    msb = i2cReadByteData(i2c_handle, TOUCH_STATUS_MSB);
    if (msb < 0) {
        log_message("Error reading touch status MSB");
        return -1;
    }

    return (msb << 8) | lsb;
}

// Function to toggle the relay state
void toggle_relay() {
    relay_state = !relay_state;
    gpioWrite(RELAY_GPIO, relay_state);
    char message[50];
    sprintf(message, "Relay toggled to %s", relay_state ? "ON" : "OFF");
    log_message(message);
}

int main() {
    int touch_status;
    int last_touch_status = 0; // Store the last touch status for debouncing
    time_t last_debounce_time = 0;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open log file
    log_file = fopen("touch_relay.log", "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        gpioTerminate();
        return 1;
    }

    log_message("Starting touch relay program");

    // Set GPIO17 as output and set initial state to LOW
    gpioSetMode(RELAY_GPIO, PI_OUTPUT);
    gpioWrite(RELAY_GPIO, 0);

    // Open I2C device
    i2c_handle = i2cOpen(I2C_BUS, MPR121_ADDR, 0);
    if (i2c_handle < 0) {
        log_message("Error opening I2C device");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    // Initialize MPR121
    if (initialize_mpr121() != 0) {
        log_message("MPR121 initialization failed");
        i2cClose(i2c_handle);
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (running) {
        touch_status = read_touch_status();
        if (touch_status < 0) {
            log_message("Error reading touch status, retrying...");
            gpioDelay(10000); // 10ms delay before retrying
            continue;
        }

        // Debouncing logic
        if ((touch_status & 0x01) && !(last_touch_status & 0x01)) {
            time_t now = time(NULL);
            if (now - last_debounce_time > (DEBOUNCE_DELAY_MS / 1000.0)) {
                toggle_relay();
                last_debounce_time = now;
            }
        }

        last_touch_status = touch_status;
        gpioDelay(10000); // 10ms delay
    }

    // Cleanup
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioWrite(RELAY_GPIO, 0); // Turn off relay on exit
    gpioTerminate();

    log_message("Program terminated");
    return 0;
}

