#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <signal.h>
#include <time.h>
#include <string.h>

// Define GPIO pins
#define FLAME_SENSOR_1 17
#define FLAME_SENSOR_2 22
#define FLAME_SENSOR_3 27
#define BUZZER 18
#define LED 23

// Debounce delay in milliseconds
#define DEBOUNCE_DELAY 50

// Global variables
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_flame_sensor(int gpio);
int debounce_sensor(int gpio);
void activate_alarm(int buzzer_gpio, int led_gpio);
void deactivate_alarm(int buzzer_gpio, int led_gpio);
void log_event(const char *message);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Function to read the flame sensor
int read_flame_sensor(int gpio) {
    return gpioRead(gpio);
}

// Function to debounce the sensor reading
int debounce_sensor(int gpio) {
    int count = 0;
    for (int i = 0; i < 3; i++) {
        if (read_flame_sensor(gpio) == 0) {
            count++;
        }
        gpioDelay(DEBOUNCE_DELAY * 1000); // Convert ms to microseconds
    }
    return (count == 3) ? 0 : 1; // Return 0 if all reads are LOW (flame detected), 1 otherwise
}

// Function to activate the alarm (buzzer and LED)
void activate_alarm(int buzzer_gpio, int led_gpio) {
    gpioWrite(buzzer_gpio, 1); // Turn on buzzer
    gpioWrite(led_gpio, 1);    // Turn on LED
}

// Function to deactivate the alarm (buzzer and LED)
void deactivate_alarm(int buzzer_gpio, int led_gpio) {
    gpioWrite(buzzer_gpio, 0); // Turn off buzzer
    gpioWrite(led_gpio, 0);    // Turn off LED
}

// Function to log an event to the log file
void log_event(const char *message) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    if (log_file != NULL) {
        fprintf(log_file, "%s: %s\n", timestamp, message);
        fflush(log_file); // Ensure the log is written immediately
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(FLAME_SENSOR_1, PI_INPUT);
    gpioSetMode(FLAME_SENSOR_2, PI_INPUT);
    gpioSetMode(FLAME_SENSOR_3, PI_INPUT);
    gpioSetMode(BUZZER, PI_OUTPUT);
    gpioSetMode(LED, PI_OUTPUT);

    // Open the log file
