#include <pigpio.h>

// Define GPIO pins for solenoids
#define SOLENOID_1_PIN 17
#define SOLENOID_2_PIN 27

// Define dispense duration in milliseconds
#define DISPENSE_DURATION_MS 1000

// Define delay between dispense cycles in seconds
#define DISPENSE_DELAY_S 5

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize_gpio();
void dispense_solenoid(int pin, int duration_ms);
void log_dispense_event(int pin1, int pin2, int duration_ms);
void deactivate_solenoids();
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("\nCtrl+C detected. Deactivating solenoids and exiting.\n");
        program_running = 0;
        deactivate_solenoids();
        gpioTerminate();
        exit(0);
    }
}

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if (gpioSetMode(SOLENOID_1_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", SOLENOID_1_PIN);
        return 1;
    }

    if (gpioSetMode(SOLENOID_2_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", SOLENOID_2_PIN);
        return 1;
    }

    return 0;
}

// Activate a solenoid for a specified duration
void dispense_solenoid(int pin, int duration_ms) {
    gpioWrite(pin, 1); // Activate solenoid
    gpioDelay(duration_ms * 1000); // Delay for specified duration (microseconds)
    gpioWrite(pin, 0); // Deactivate solenoid
}

// Log dispense event to file
void log_dispense_event(int pin1, int pin2, int duration_ms) {
    FILE *fp = fopen("dispense_log.txt", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening dispense_log.txt for writing\n");
        return;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d, Solenoid %d, Solenoid %d, Duration: %d ms\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, pin1, pin2, duration_ms);

    fclose(fp);
}

// Deactivate both solenoids
void deactivate_solenoids() {
    gpioWrite(SOLENOID_1_PIN, 0);
    gpioWrite(SOLENOID_2_PIN, 0);
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    printf("Pneumatic dispensing system started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        // Activate solenoid 1 for half the duration
        dispense_solenoid(SOLENOID_1_PIN, DISPENSE_DURATION_MS / 2);

        // Activate solenoid 2 for the remaining half
        dispense_solenoid(SOLENOID_2_PIN, DISPENSE_DURATION_MS / 2);

        // Log the dispense event
        log_dispense_event(SOLENOID_1_PIN, SOLENOID_2_PIN, DISPENSE_DURATION_MS);

        // Delay before the next dispense cycle
        gpioDelay(DISPENSE_DELAY_S * 1000000); // Delay in microseconds
    }

    // Deactivate solenoids before exiting
    deactivate_solenoids();
    gpioTerminate();

    return 0;
}

