#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// Motor A
#define MOTOR_A_FORWARD 17
#define MOTOR_A_BACKWARD 18

// Motor B
#define MOTOR_B_FORWARD 22
#define MOTOR_B_BACKWARD 23

// L298N Enable Pins
#define ENA 24
#define ENB 25

// Ultrasonic Sensor
#define TRIGGER_PIN 4
#define ECHO_PIN 17

// PID Constants
#define Kp 1.0
#define Ki 0.01
#define Kd 0.1

// Obstacle Avoidance Threshold
#define OBSTACLE_THRESHOLD 20.0

// Obstacle Avoidance Speed
#define OBSTACLE_SPEED 128

// Global Variables
static volatile int running = 1;
static FILE *log_file = NULL;

// Function Prototypes
void signal_handler(int signal);
int initialize_gpio();
float simulate_tilt_sensor();
float simulate_distance_sensor();
float pid_control(float error, float *integral, float *previous_error);
void set_motor_speed(int motor, int speed);
void log_data(float tilt_error, float distance, int motor_a_speed, int motor_b_speed);

// Signal Handler
void signal_handler(int signal) {
    running = 0;
    printf("\nCaught signal %d, stopping motors and exiting...\n", signal);

    // Stop motors
    set_motor_speed(1, 0); // Motor A
    set_motor_speed(2, 0); // Motor B

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
        printf("Log file closed.\n");
    }

    // Terminate pigpio
    gpioTerminate();
    printf("pigpio terminated.\n");

    exit(0);
}

// Initialize GPIO
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set motor control pins as outputs
    gpioSetMode(MOTOR_A_FORWARD, PI_OUTPUT);
    gpioSetMode(MOTOR_A_BACKWARD, PI_OUTPUT);
    gpioSetMode(MOTOR_B_FORWARD, PI_OUTPUT);
    gpioSetMode(MOTOR_B_BACKWARD, PI_OUTPUT);

    // Set enable pins as outputs and set HIGH
    gpioSetMode(ENA, PI_OUTPUT);
    gpioSetMode(ENB, PI_OUTPUT);
    gpioWrite(ENA, 1);
    gpioWrite(ENB, 1);

    // Set ultrasonic sensor pins
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);

    return 0;
}

// Simulate Tilt Sensor
float simulate_tilt_sensor() {
    return (float)(rand() % 21 - 10); // Random value between -10.0 and 10.0
}

// Simulate Distance Sensor
float simulate_distance_sensor() {
    return (float)(rand() % 400 + 2); // Random value between 2.0 and 400.0
}

// PID Control
float pid_control(float error, float *integral, float *previous_error) {
    float proportional = Kp * error;
    *integral += Ki * error;
    float derivative = Kd * (error - *previous_error);
    *previous_error = error;
    return proportional + *integral + derivative;
}

// Set Motor Speed
void set_motor_speed(int motor, int speed) {
    int forward_pin, backward_pin;

    if (motor == 1) {
        forward_pin = MOTOR_A_FORWARD;
        backward_pin = MOTOR_A_BACKWARD;
    } else if (motor == 2) {
        forward_pin = MOTOR_B_FORWARD;
        backward_pin = MOTOR_B_BACKWARD;
    } else {
        fprintf(stderr, "Invalid motor number: %d\n", motor);
        return;
    }

    if (speed > 255) speed = 255;
    if (speed < -255) speed = -255;

    if (speed > 0) {
        gpioWrite(forward_pin, 1);
        gpioWrite(backward_pin, 0);
        gpioPWM(forward_pin, speed);
    } else if (speed < 0) {
        gpioWrite(forward_pin, 0);
        gpioWrite(backward_pin, 1);
        gpioPWM(backward_pin, -speed);
    } else {
        gpioWrite(forward_pin, 0);
        gpioWrite(backward_pin, 0);
        gpioPWM(forward_pin, 0);
        gpioPWM(backward_pin, 0);
    }
}

// Log Data
void log_data(float tilt_error, float distance, int motor_a_speed, int motor_b_speed) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f,%.2f,%d,%d\n", timestamp, tilt_error, distance, motor_a_speed, motor_b_speed);
    fflush(log_file); // Ensure data is written to file immediately
}

int main() {
    // Initialize random seed
    srand(time(NULL));

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open log file
    log_file = fopen("balance_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    float tilt_error, integral = 0.0, previous_error = 0.0;
    float distance;
    int motor_a_speed, motor_b_speed;

    while (running) {
        // Simulate sensors
        tilt_error = simulate_tilt_sensor();
        distance = simulate_distance_sensor();

        // PID control
        float pid_output = pid_control(tilt_error, &integral, &previous_error);

        // Obstacle avoidance
        if (distance < OBSTACLE_THRESHOLD) {
            motor_a_speed = -OBSTACLE_SPEED; // Reverse Motor A
            motor_b_speed = -OBSTACLE_SPEED; // Reverse Motor B
        } else {
            motor_a_speed = (int)pid_output;
            motor_b_speed = (int)pid_output;
        }

        // Set motor speeds
        set_motor_speed(1, motor_a_speed);
        set_motor_speed(2, motor_b_speed);

        // Log data
        log_data(tilt_error, distance, motor_a_speed, motor_b_speed);

        // Delay
        gpioDelay(50); // 50 ms
    }

    return 0;
}

