#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <alsa/asoundlib.h>

// Define GPIO pins for RGB LED
#define RED_PIN   17
#define GREEN_PIN 18
#define BLUE_PIN  27

// Define ALSA parameters
#define SAMPLE_RATE 8000
#define NUM_CHANNELS 1
#define SAMPLE_SIZE 16 // bits
#define PERIOD_SIZE 1024

// Define color mapping parameters
#define MIN_AMPLITUDE 0.0
#define MAX_AMPLITUDE 1.0
#define MIN_TEMPERATURE 1000.0
#define MAX_TEMPERATURE 20000.0

// Define sensitivity scaling parameter
#define DEFAULT_SENSITIVITY 1.0

// Global variables
snd_pcm_t *pcm_handle;
int running = 1;
double sensitivity = DEFAULT_SENSITIVITY;

// Function prototypes
double calculate_rms(short *buffer, int buffer_size);
void map_amplitude_to_color(double amplitude, double temperature, int *red, int *green, int *blue);
void set_led_color(int red, int green, int blue);
void signal_handler(int signal);
int initialize_alsa();
void cleanup_alsa();

// Function to calculate RMS amplitude
double calculate_rms(short *buffer, int buffer_size) {
    double sum_of_squares = 0.0;
    for (int i = 0; i < buffer_size; i++) {
        sum_of_squares += (double)buffer[i] * buffer[i];
    }
    double mean_square = sum_of_squares / buffer_size;
    return sqrt(mean_square);
}

// Function to map amplitude to color (CIE 1931 color space approximation)
void map_amplitude_to_color(double amplitude, double temperature, int *red, int *green, int *blue) {
    // Clamp amplitude to the defined range
    amplitude = fmax(MIN_AMPLITUDE, fmin(MAX_AMPLITUDE, amplitude));

    // Map amplitude to temperature (Kelvin)
    temperature = MIN_TEMPERATURE + amplitude * (MAX_TEMPERATURE - MIN_TEMPERATURE);

    // Convert temperature to RGB (simplified approximation)
    double r, g, b;
    if (temperature < 660) {
        r = 1.0;
        g = (temperature - 550) / 110.0;
        b = 0.0;
    } else if (temperature < 1100) {
        r = (1100 - temperature) / 450.0;
        g = 1.0;
        b = 0.0;
    } else if (temperature < 1800) {
        r = 0.0;
        g = 1.0;
        b = (temperature - 1500) / 300.0;
    } else {
        r = 0.0;
        g = (2500 - temperature) / 700.0;
        b = 1.0;
    }

    // Apply sensitivity scaling
    r *= sensitivity;
    g *= sensitivity;
    b *= sensitivity;

    // Clamp RGB values to [0, 1]
    r = fmax(0.0, fmin(1.0, r));
    g = fmax(0.0, fmin(1.0, g));
    b = fmax(0.0, fmin(1.0, b));

    // Scale RGB values to [0, 255]
    *red = (int)(r * 255.0);
    *green = (int)(g * 255.0);
    *blue = (int)(b * 255.0);
}

// Function to set the RGB LED color using pigpio PWM
void set_led_color(int red, int green, int blue) {
    gpioPWM(RED_PIN, red);
    gpioPWM(GREEN_PIN, green);
    gpioPWM(BLUE_PIN, blue);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    running = 0;
}

// Function to initialize ALSA
int initialize_alsa() {
    snd_pcm_hw_params_t *hw_params;
    int err;

    // Open PCM device for capture
    if ((err = snd_pcm_open(&pcm_handle, "default", SND_PCM_STREAM_CAPTURE, 0)) < 0) {
        fprintf(stderr, "Error opening PCM device: %s\n", snd_strerror(err));
        return -1;
    }

    // Allocate hardware parameters object
    snd_pcm_hw_params_alloca(&hw_params);

    // Initialize hardware parameters
    if ((err = snd_pcm_hw_params_any(pcm_handle, hw_params)) < 0) {
        fprintf(stderr, "Error initializing hardware parameters: %s\n", snd_strerror(err));
        snd_pcm_close(pcm_handle);
        return -1;
    }

    // Set access type to interleaved
    if ((err = snd_pcm_hw_params_set_access(pcm_handle, hw_params, SND_PCM_ACCESS_RW_INTERLEAVED)) < 0) {
        fprintf(stderr, "Error setting access type: %s\n", snd_strerror(err));
        snd_pcm_close(pcm_handle);
        return -1;
    }

    // Set format
    if ((err = snd_pcm_hw_params_set_format(pcm_handle, hw_params, SND_PCM_FORMAT_S16_LE)) < 0) {
        fprintf(stderr, "Error setting format: %s\n", snd_strerror(err));
        snd_pcm_close(pcm_handle);
        return -1;
    }

    // Set number of channels
    if ((err = snd_pcm_hw_params_set_channels(pcm_handle, hw_params, NUM_CHANNELS)) < 0) {
        fprintf(stderr, "Error setting number of channels: %s\n", snd_strerror(err));
        snd_pcm_close(pcm_handle);
        return -1;
    }

    // Set sample rate
    int rate = SAMPLE_RATE;
    if ((err = snd_pcm_hw_params_set_rate_near(pcm_handle, hw_params, &rate, 0)) < 0) {
        fprintf(stderr, "Error setting sample rate: %s\n", snd_strerror(err));
        snd_pcm_close(pcm_handle);
        return -1;
    }
    if (rate != SAMPLE_RATE) {
        fprintf(stderr, "Warning: Sample rate adjusted to %d Hz\n", rate);
    }

    // Set period size
    snd_pcm_uframes_t period_size = PERIOD_SIZE;
    if ((err = snd_pcm_hw_params_set_period_size_near(pcm_handle, hw_params, &period_size, 0)) < 0) {
        fprintf(stderr, "Error setting period size: %s\n", snd_strerror(err));
        snd_pcm_close(pcm_handle);
        return -1;
    }

    // Apply hardware parameters
    if ((err = snd_pcm_hw_params(pcm_handle, hw_params)) < 0) {
        fprintf(stderr, "Error setting hardware parameters: %s\n", snd_strerror(err));
        snd_pcm_close(pcm_handle);
        return -1;
    }

    return 0;
}

// Function to cleanup ALSA
void cleanup_alsa() {
    if (pcm_handle) {
        snd_pcm_drain(pcm_handle);
        snd_pcm_close(pcm_handle);
    }
}

int main(int argc, char *argv[]) {
    // Parse command-line arguments
    if (argc > 1) {
        char *endptr;
        sensitivity = strtod(argv[1], &endptr);
        if (*endptr != '\0' || sensitivity <= 0.0) {
            fprintf(stderr, "Error: Invalid sensitivity value. Using default sensitivity.\n");
            sensitivity = DEFAULT_SENSITIVITY;
        }
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins to output mode
    gpioSetMode(RED_PIN, PI_OUTPUT);
    gpioSetMode(GREEN_PIN, PI_OUTPUT);
    gpioSetMode(BLUE_PIN, PI_OUTPUT);

    // Initialize ALSA
    if (initialize_alsa() != 0) {
        fprintf(stderr, "ALSA initialization failed. Using simulated audio.\n");
        snd_pcm_t *pcm_handle = NULL; // Dummy handle
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Allocate memory for audio buffer
    short *buffer = (short *)malloc(PERIOD_SIZE * sizeof(short));
    if (!buffer) {
        fprintf(stderr, "Error allocating memory for audio buffer\n");
        gpioTerminate();
        cleanup_alsa();
        return 1;
    }

    // Main loop
    while (running) {
        // Read audio data from ALSA
        int err = snd_pcm_readi(pcm_handle, buffer, PERIOD_SIZE);
        if (err < 0) {
            fprintf(stderr, "Error reading from PCM device: %s\n", snd_strerror(err));
            if (err == -EPIPE) {
                // EPIPE occurred, recover
                fprintf(stderr, "Recovering from EPIPE...\n");
                snd_pcm_prepare(pcm_handle);
            } else if (err == -ESTRPIPE) {
                // Stream suspended, resume
                fprintf(stderr, "Resuming stream...\n");
                snd_pcm_resume(pcm_handle);
            }
            continue; // Skip to the next iteration
        }

        // Calculate RMS amplitude
        double amplitude = calculate_rms(buffer, PERIOD_SIZE);

        // Map amplitude to color
        int red, green, blue;
        map_amplitude_to_color(amplitude, 0.0, &red, &green, &blue); // Temperature is not used in this simplified version

        // Set LED color
        set_led_color(red, green, blue);

        // Delay for 10 ms
        gpioDelay(10000); // 10000 microseconds = 10 milliseconds
    }

    // Cleanup
    free(buffer);
    gpioPWM(RED_PIN, 0);
    gpioPWM(GREEN_PIN, 0);
    gpioPWM(BLUE_PIN, 0);
    gpioTerminate();
    cleanup_alsa();

    return 0;
}

