#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>
#include <time.h>

// Define GPIO pins for the relays
#define RELAY1_PIN 17
#define RELAY2_PIN 27
#define RELAY3_PIN 22
#define RELAY4_PIN 23

// Define the duration of each phase in seconds
#define SUNRISE_DURATION 3600
#define DAYTIME_DURATION 21600
#define SUNSET_DURATION 3600
#define NIGHTTIME_DURATION 51840

// Global variables for GPIO chip and lines
struct gpiod_chip *chip;
struct gpiod_line *relay1_line;
struct gpiod_line *relay2_line;
struct gpiod_line *relay3_line;
struct gpiod_line *relay4_line;

// Function prototypes
int initialize_gpio();
void sunrise_phase();
void daytime_phase();
void sunset_phase();
void nighttime_phase();
void turn_off_relays();
void signal_handler(int sig);

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);
    turn_off_relays();
    exit(0);
}

// Function to initialize GPIO pins
int initialize_gpio() {
    // Open the GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    // Request GPIO lines for output
    relay1_line = gpiod_chip_get_line(chip, RELAY1_PIN);
    relay2_line = gpiod_chip_get_line(chip, RELAY2_PIN);
    relay3_line = gpiod_chip_get_line(chip, RELAY3_PIN);
    relay4_line = gpiod_chip_get_line(chip, RELAY4_PIN);

    if (!relay1_line || !relay2_line || !relay3_line || !relay4_line) {
        perror("Error getting GPIO line");
        gpiod_chip_close(chip);
        return -1;
    }

    if (gpiod_line_request_output(relay1_line, "sunset_simulator") < 0 ||
        gpiod_line_request_output(relay2_line, "sunset_simulator") < 0 ||
        gpiod_line_request_output(relay3_line, "sunset_simulator") < 0 ||
        gpiod_line_request_output(relay4_line, "sunset_simulator") < 0) {
        perror("Error requesting GPIO line for output");
        gpiod_chip_close(chip);
        return -1;
    }

    return 0;
}

// Function to simulate sunrise
void sunrise_phase() {
    printf("Starting sunrise phase...\n");
    for (int i = 0; i <= 100; i++) {
        if (gpiod_line_set_value(relay1_line, 0) < 0 ||
            gpiod_line_set_value(relay2_line, 0) < 0 ||
            gpiod_line_set_value(relay3_line, 0) < 0 ||
            gpiod_line_set_value(relay4_line, 0) < 0) {
            perror("Error setting GPIO line value");
            turn_off_relays();
            exit(1);
        }
        usleep(SUNRISE_DURATION * 1000000 / 100); // 100 steps over 1 hour
    }
    printf("Sunrise phase complete.\n");
}

// Function to simulate daytime
void daytime_phase() {
    printf("Starting daytime phase...\n");
    for (int i = 0; i < 100; i++) {
        if (gpiod_line_set_value(relay1_line, 1) < 0 ||
            gpiod_line_set_value(relay2_line, 1) < 0 ||
            gpiod_line_set_value(relay3_line, 1) < 0 ||
            gpiod_line_set_value(relay4_line, 1) < 0) {
            perror("Error setting GPIO line value");
            turn_off_relays();
            exit(1);
        }
        usleep(DAYTIME_DURATION * 1000000 / 100); // 100 steps over 6 hours
    }
    printf("Daytime phase complete.\n");
}

// Function to simulate sunset
void sunset_phase() {
    printf("Starting sunset phase...\n");
    for (int i = 100; i >= 0; i--) {
        if (gpiod_line_set_value(relay1_line, 0) < 0 ||
            gpiod_line_set_value(relay2_line, 0) < 0 ||
            gpiod_line_set_value(relay3_line, 0) < 0 ||
            gpiod_line_set_value(relay4_line, 0) < 0) {
            perror("Error setting GPIO line value");
            turn_off_relays();
            exit(1);
        }
        usleep(SUNSET_DURATION * 1000000 / 100); // 100 steps over 1 hour
    }
    printf("Sunset phase complete.\n");
}

// Function to simulate nighttime
void nighttime_phase() {
    printf("Starting nighttime phase...\n");
    for (int i = 0; i < 100; i++) {
        if (gpiod_line_set_value(relay1_line, 1) < 0 ||
            gpiod_line_set_value(relay2_line, 1) < 0 ||
            gpiod_line_set_value(relay3_line, 1) < 0 ||
            gpiod_line_set_value(relay4_line, 1) < 0) {
            perror("Error setting GPIO line value");
            turn_off_relays();
            exit(1);
        }
        usleep(NIGHTTIME_DURATION * 1000000 / 100); // 100 steps over 14.4 hours
    }
    printf("Nighttime phase complete.\n");
}

// Function to turn off all relays
void turn_off_relays() {
    printf("Turning off relays...\n");
    if (gpiod_line_set_value(relay1_line, 1) < 0 ||
        gpiod_line_set_value(relay2_line, 1) < 0 ||
        gpiod_line_set_value(relay3_line, 1) < 0 ||
        gpiod_line_set_value(relay4_line, 1) < 0) {
        perror("Error setting GPIO line value");
    }

    // Release GPIO lines
    gpiod_line_release(relay1_line);
    gpiod_line_release(relay2_line);
    gpiod_line_release(relay3_line);
    gpiod_line_release(relay4_line);

    // Close the GPIO chip
    gpiod_chip_close(chip);

    printf("Relays turned off and GPIO resources released.\n");
}

int main() {
    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() < 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return 1;
    }

    // Main loop
    while (1) {
        sunrise_phase();
        daytime_phase();
        sunset_phase();
        nighttime_phase();
    }

    return 0;
}

