#define VIDEO_DURATION_SEC 5

static volatile int running = 1;
static FILE *log_file = NULL;

// Function to generate a timestamp string in ISO 8601 format
char* generate_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    char *timestamp = (char*)malloc(21 * sizeof(char)); // Allocate memory for the timestamp string

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, 21, "%Y-%m-%dT%H:%M:%S%z", timeinfo);
    return timestamp;
}

// Function to create the video filename
char* create_filename() {
    char *timestamp = generate_timestamp();
    char *filename = (char*)malloc(64 * sizeof(char)); // Allocate memory for the filename
    snprintf(filename, 64, "%s%s.h264", VIDEO_DIR, timestamp);
    free(timestamp);
    return filename;
}

// Function to capture a video using raspivid
int capture_video(const char *filename) {
    char command[256];
    snprintf(command, sizeof(command), "raspivid -o %s -t %d000", filename, VIDEO_DURATION_SEC);
    int status = system(command);
    if (status == -1) {
        perror("Error executing raspivid");
        return -1;
    }
    return status;
}

// Function to log motion detection events
int log_motion(const char *timestamp) {
    if (log_file == NULL) {
        fprintf(stderr, "Log file is not open.\n");
        return -1;
    }

    fprintf(log_file, "%s Motion detected\n", timestamp);
    fflush(log_file); // Ensure the log is written immediately
    return 0;
}

// Function to handle motion detection
void handle_motion() {
    char *filename = create_filename();
    if (filename == NULL) {
        fprintf(stderr, "Failed to create filename.\n");
        return;
    }

    if (capture_video(filename) == 0) {
        char *timestamp = generate_timestamp();
        if (log_motion(timestamp) != 0) {
            fprintf(stderr, "Failed to log motion.\n");
        }
        free(timestamp);
    } else {
        fprintf(stderr, "Failed to capture video.\n");
    }

    free(filename);
}

// Signal handler for clean shutdown
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting gracefully.\n", signal);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pin as input
    gpioSetMode(GPIO_PIN, PI_INPUT);
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_UP); // Enable pull-up resistor

    // Create log directory if it doesn't exist
    struct stat st = {0};
    if (stat(LOG_DIR, &st) == -1) {
        if (mkdir(LOG_DIR, 0777) == -1) {
            perror("Error creating log directory");
            gpioTerminate();
            return 1;
        }
    }

    // Open log file
    log_file = fopen(LOG_DIR "motion_log.txt", "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        gpioTerminate();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    printf("Motion detection started. Press Ctrl+C to exit.\n");

    int last_state = 1; // Assume no obstacle initially (HIGH)
    unsigned int last_tick = 0;

    while (running) {
        int current_state = gpioRead(GPIO_PIN);
        unsigned int current_tick = gpioTick();

        if (current_state == 0 && last_state == 1) { // Transition from no obstacle to obstacle
            if (current_tick - last_tick > DEBOUNCE_DELAY_MS * 1000) { // Debounce
                handle_motion();
                last_tick = current_tick;
            }
        }

        last_state = current_state;
        gpioDelay(10); // Check every 10 ms
    }

    // Clean up
    fclose(log_file);
    gpioTerminate();

    return 0;
}

