#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

// MPU-6050 I2C address
#define MPU6050_ADDR 0x68

// MPU-6050 registers
#define PWR_MGMT_1 0x6B
#define SMPLRT_DIV 0x19
#define GYRO_CONFIG 0x1B
#define GYRO_XOUT_H 0x43

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_mpu6050();
int read_gyro_data(int16_t *x, int16_t *y, int16_t *z);
void convert_to_degrees_per_second(int16_t x, int16_t y, int16_t z, float *x_degps, float *y_degps, float *z_degps);
void log_data(float x_degps, float y_degps, float z_degps);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    terminate = 1;
}

// Function to initialize the MPU-6050
int initialize_mpu6050() {
    int status;

    // Wake up the MPU-6050
    status = i2cWriteByteData(i2c_handle, PWR_MGMT_1, 0x00);
    if (status != 0) {
        fprintf(stderr, "Error writing to PWR_MGMT_1: %d\n", status);
        return -1;
    }

    // Set sample rate divider to 125 Hz
    status = i2cWriteByteData(i2c_handle, SMPLRT_DIV, 0x07);
    if (status != 0) {
        fprintf(stderr, "Error writing to SMPLRT_DIV: %d\n", status);
        return -1;
    }

    // Set gyroscope full-scale range to ±250°/s
    status = i2cWriteByteData(i2c_handle, GYRO_CONFIG, 0x00);
    if (status != 0) {
        fprintf(stderr, "Error writing to GYRO_CONFIG: %d\n", status);
        return -1;
    }

    return 0;
}

// Function to read gyroscope data
int read_gyro_data(int16_t *x, int16_t *y, int16_t *z) {
    char buffer[6];
    int status;

    status = i2cReadI2CBlockData(i2c_handle, GYRO_XOUT_H, buffer, 6);
    if (status != 6) {
        fprintf(stderr, "Error reading gyro data: %d\n", status);
        return -1;
    }

    *x = (int16_t)((buffer[0] << 8) | buffer[1]);
    *y = (int16_t)((buffer[2] << 8) | buffer[3]);
    *z = (int16_t)((buffer[4] << 8) | buffer[5]);

    return 0;
}

// Function to convert raw data to degrees per second
void convert_to_degrees_per_second(int16_t x, int16_t y, int16_t z, float *x_degps, float *y_degps, float *z_degps) {
    *x_degps = (float)x / 131.0;
    *y_degps = (float)y / 131.0;
    *z_degps = (float)z / 131.0;
}

// Function to log data to a file
void log_data(float x_degps, float y_degps, float z_degps) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    fprintf(log_file, "%s.%03d,%.3f,%.3f,%.3f\n", timestamp, rawtime % 1000, x_degps, y_degps, z_degps);
    fflush(log_file); // Ensure data is written to disk immediately
}

int main() {
    int16_t x, y, z;
    float x_degps, y_degps, z_degps;
    int init_attempts = 0;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, MPU6050_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("gyro_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize MPU-6050 with retries
    while (init_attempts < 3) {
        if (initialize_mpu6050() == 0) {
            printf("MPU-6050 initialized successfully.\n");
            break;
        } else {
            fprintf(stderr, "MPU-6050 initialization failed. Attempt %d of 3.\n", init_attempts + 1);
            init_attempts++;
            gpioDelay(1000000); // Wait 1 second before retrying
        }
    }

    if (init_attempts == 3) {
        fprintf(stderr, "MPU-6050 initialization failed after 3 attempts. Exiting.\n");
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (!terminate) {
        if (read_gyro_data(&x, &y, &z) == 0) {
            convert_to_degrees_per_second(x, y, z, &x_degps, &y_degps, &z_degps);
            log_data(x_degps, y_degps, z_degps);
        } else {
            fprintf(stderr, "Error reading gyro data. Attempting re-initialization.\n");
            i2cClose(i2c_handle);
            i2c_handle = i2cOpen(1, MPU6050_ADDR, 0);
            if (i2c_handle < 0) {
                fprintf(stderr, "Error re-opening I2C bus: %d\n", i2c_handle);
                terminate = 1; // Exit if re-opening fails
            } else {
                if (initialize_mpu6050() != 0) {
                    fprintf(stderr, "MPU-6050 re-initialization failed.\n");
                    terminate = 1; // Exit if re-initialization fails
                }
            }
        }

        gpioDelay(10000); // 10 ms delay (100 Hz sampling rate)
    }

    // Cleanup
    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

