#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Define GPIO pins for the relays
#define RELAY1_PIN 4
#define RELAY2_PIN 17
#define RELAY3_PIN 27
#define RELAY4_PIN 22

// Define the log file name
#define LOG_FILE "irrigation_log.txt"

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to initialize the pigpio library
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Function to set the GPIO pin mode
int set_gpio_mode(int pin, int mode) {
    if (gpioSetMode(pin, mode) != 0) {
        fprintf(stderr, "Failed to set GPIO %d mode to %d\n", pin, mode);
        return -1;
    }
    return 0;
}

// Function to read the simulated moisture sensor value
int read_moisture_sensor(int zone) {
    return rand() % 101;
}

// Function to control the relay based on the moisture sensor reading
void control_relay(int pin, int moisture_level) {
    if (moisture_level < 30) {
        gpioWrite(pin, 0); // Activate relay (LOW)
    } else {
        gpioWrite(pin, 1); // Deactivate relay (HIGH)
    }
}

// Function to log the sensor reading, relay state, and timestamp to a file
int log_data(int zone, int moisture_level, int relay_state) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "%d,%d,%d,%s\n", zone, moisture_level, relay_state, timestamp);
    fclose(fp);
    return 0;
}

int main() {
    // Seed the random number generator
    srand(time(NULL));

    // Register the signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Initialize pigpio
    if (initialize_pigpio() != 0) {
        return 1;
    }

    // Set GPIO pin modes to output
    if (set_gpio_mode(RELAY1_PIN, PI_OUTPUT) != 0 ||
        set_gpio_mode(RELAY2_PIN, PI_OUTPUT) != 0 ||
        set_gpio_mode(RELAY3_PIN, PI_OUTPUT) != 0 ||
        set_gpio_mode(RELAY4_PIN, PI_OUTPUT) != 0) {
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (program_running) {
        // Read moisture sensor values and control relays
        int moisture1 = read_moisture_sensor(1);
        int moisture2 = read_moisture_sensor(2);
        int moisture3 = read_moisture_sensor(3);
        int moisture4 = read_moisture_sensor(4);

        control_relay(RELAY1_PIN, moisture1);
        control_relay(RELAY2_PIN, moisture2);
        control_relay(RELAY3_PIN, moisture3);
        control_relay(RELAY4_PIN, moisture4);

        // Log the data
        log_data(1, moisture1, gpioRead(RELAY1_PIN));
        log_data(2, moisture2, gpioRead(RELAY2_PIN));
        log_data(3, moisture3, gpioRead(RELAY3_PIN));
        log_data(4, moisture4, gpioRead(RELAY4_PIN));

        // Wait for 5 seconds
        gpioDelay(5000); // pigpio's delay function
    }

    // Deactivate all relays before exiting
    gpioWrite(RELAY1_PIN, 1);
    gpioWrite(RELAY2_PIN, 1);
    gpioWrite(RELAY3_PIN, 1);
    gpioWrite(RELAY4_PIN, 1);

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

