        return -1;
    }

    // Set data format to ±2g range and full resolution
    if (i2cWriteByteData(i2c_handle, DATA_FORMAT, 0x0B) < 0) {
        fprintf(stderr, "Error: Could not set data format\n");
        return -1;
    }

    return 0;
