#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pthread.h>
#include <pigpio.h>

// Define GPIO pins
#define TRIG_PIN 4
#define ECHO_PIN 18

// Define constants
#define SPEED_OF_SOUND 34300.0 // cm/s
#define MAX_DISTANCE 400.0    // cm
#define TIMEOUT_MS 100
#define WRAP_AROUND_MS 71600000

// Global variables
static volatile unsigned int rising_tick = 0;
static volatile unsigned int falling_tick = 0;
static volatile int echo_received = 0;
static volatile int timeout_flag = 0;
static FILE *log_file = NULL;
static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
static int running = 1;

// Function prototypes
void trigger_pulse();
void echo_rising_edge(int gpio, int level, uint32_t tick);
void echo_falling_edge(int gpio, int level, uint32_t tick);
double calculate_distance(unsigned int pulse_width_us);
void log_distance(double distance_cm);
void signal_handler(int signal);

// Interrupt callback functions
void echo_rising_edge(int gpio, int level, uint32_t tick) {
    pthread_mutex_lock(&mutex);
    rising_tick = tick;
    echo_received = 1;
    timeout_flag = 0; // Reset timeout flag
    pthread_mutex_unlock(&mutex);
}

void echo_falling_edge(int gpio, int level, uint32_t tick) {
    pthread_mutex_lock(&mutex);
    falling_tick = tick;
    pthread_mutex_unlock(&mutex);

    unsigned int pulse_width_us;
    pthread_mutex_lock(&mutex);
    pulse_width_us = falling_tick - rising_tick;
    pthread_mutex_unlock(&mutex);

    if (pulse_width_us > WRAP_AROUND_MS) {
        pulse_width_us = WRAP_AROUND_MS - rising_tick + falling_tick;
    }

    double distance_cm = calculate_distance(pulse_width_us);

    if (distance_cm > 0.0 && distance_cm <= MAX_DISTANCE) {
        log_distance(distance_cm);
    } else {
        fprintf(stderr, "Invalid distance measurement: %.2f cm\n", distance_cm);
    }
}

// Function to generate a 10 µs trigger pulse
void trigger_pulse() {
    gpioWrite(TRIG_PIN, 1);
    gpioDelay(10);
    gpioWrite(TRIG_PIN, 0);
}

// Function to calculate distance in centimeters
double calculate_distance(unsigned int pulse_width_us) {
    return (double)pulse_width_us * SPEED_OF_SOUND / 2000000.0; // Convert us to s and divide by 2
}

// Function to log distance to file
void log_distance(double distance_cm) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    long long timestamp_ns = (long long)ts.tv_sec * 1000000000LL + ts.tv_nsec;

    if (log_file != NULL) {
        fprintf(log_file, "%lld,%.2f\n", timestamp_ns, distance_cm);
        fflush(log_file); // Ensure data is written to disk immediately
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully.\n", signal);
    running = 0;

    // Cancel callbacks
    gpioSetAlertFuncEx(ECHO_PIN, NULL, NULL);

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate pigpio
    gpioTerminate();

    // Destroy mutex
    pthread_mutex_destroy(&mutex);

    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIG_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);

    // Set pull-down resistor on ECHO_PIN
    gpioSetPullUpDown(ECHO_PIN, PI_PUD_DOWN);

    // Open log file
    log_file = fopen("distance_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Register interrupt callbacks
    gpioSetAlertFuncEx(ECHO_PIN, echo_rising_edge, NULL);
    gpioSetAlertFuncEx(ECHO_PIN, echo_falling_edge, NULL);

    // Set signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (running) {
        trigger_pulse();
        gpioDelay(200); // Trigger every 200 ms

        // Timeout handling
        if (!echo_received && !timeout_flag) {
            timeout_flag = 1;
            fprintf(stderr, "Timeout: No echo received.\n");
        }
    }

    return 0;
}

