#define CTRL_REG4 0x23
#define OUT_X_L 0x28
#define BUZZER_GPIO 17
#define SAMPLE_RATE_HZ 100
#define SAMPLE_PERIOD_US (1000000 / SAMPLE_RATE_HZ)

// Global variables
int i2c_handle_1 = -1;
int i2c_handle_2 = -1;
volatile sig_atomic_t terminate = 0;

// Structure to hold accelerometer data
typedef struct {
    int16_t x;
    int16_t y;
    int16_t z;
} accelerometer_data_t;

// Function prototypes
int initialize_i2c(int bus, int addr);
int configure_lis3dh(int handle);
accelerometer_data_t read_acceleration(int handle);
float calculate_magnitude(accelerometer_data_t data);
void activate_buzzer(int gpio, int duration_ms);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Initializes the I2C bus and returns the I2C handle.
int initialize_i2c(int bus, int addr) {
    int handle = i2cOpen(bus, addr, 0);
    if (handle < 0) {
        fprintf(stderr, "Error opening I2C device at address 0x%02x: %d\n", addr, handle);
        return -1;
    }
    return handle;
}

// Configures the LIS3DH accelerometer.
int configure_lis3dh(int handle) {
    int result;

    // Set data rate to 100 Hz and enable all axes
    result = i2cWriteByteData(handle, CTRL_REG1, 0x77); // 0x77 = 0b01110111
    if (result < 0) {
        fprintf(stderr, "Error writing to CTRL_REG1: %d\n", result);
        return -1;
    }

    // Set full scale to ±2g
    result = i2cWriteByteData(handle, CTRL_REG4, 0x00); // 0x00 = 0b00000000
    if (result < 0) {
        fprintf(stderr, "Error writing to CTRL_REG4: %d\n", result);
        return -1;
    }

    return 0;
}

// Reads acceleration data from the LIS3DH.
accelerometer_data_t read_acceleration(int handle) {
    accelerometer_data_t data;
    char buffer[6];
    int result;

    result = i2cReadI2CBlockData(handle, OUT_X_L, buffer, 6);
    if (result < 0) {
        fprintf(stderr, "Error reading acceleration data: %d\n", result);
        data.x = 0; // Set to 0 to avoid garbage values
        data.y = 0;
        data.z = 0;
        return data;
    }

    data.x = (int16_t)((buffer[1] << 8) | buffer[0]);
    data.y = (int16_t)((buffer[3] << 8) | buffer[2]);
    data.z = (int16_t)((buffer[5] << 8) | buffer[4]);

    return data;
}

// Calculates the magnitude of the acceleration vector.
float calculate_magnitude(accelerometer_data_t data) {
    float x = (float)data.x / 16384.0f; // Convert to g
    float y = (float)data.y / 16384.0f;
    float z = (float)data.z / 16384.0f;
    return sqrt(x * x + y * y + z * z);
}

