// Motor 1 (X-axis) GPIO pins
#define MOTOR1_IN1 4
#define MOTOR1_IN2 17
#define MOTOR1_IN3 27
#define MOTOR1_IN4 22

// Motor 2 (Y-axis) GPIO pins
#define MOTOR2_IN1 5
#define MOTOR2_IN2 6
#define MOTOR2_IN3 13
#define MOTOR2_IN4 19

// Step delay in microseconds
#define STEP_DELAY 1000

// Steps per mm conversion factor
#define STEPS_PER_MM 10

// Global flag to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCtrl+C detected. Stopping motors and cleaning up...\n");
}

// Function to set the GPIO pins for a given motor step
void set_motor_pins(int motor, int step) {
    int in1, in2, in3, in4;

    if (motor == 1) {
        in1 = MOTOR1_IN1;
        in2 = MOTOR1_IN2;
        in3 = MOTOR1_IN3;
        in4 = MOTOR1_IN4;
    } else if (motor == 2) {
        in1 = MOTOR2_IN1;
        in2 = MOTOR2_IN2;
        in3 = MOTOR2_IN3;
        in4 = MOTOR2_IN4;
    } else {
        fprintf(stderr, "Error: Invalid motor number: %d\n", motor);
        return;
    }

    switch (step) {
        case 0:
            gpioWrite(in1, 1); gpioWrite(in2, 0); gpioWrite(in3, 0); gpioWrite(in4, 0);
            break;
        case 1:
            gpioWrite(in1, 0); gpioWrite(in2, 1); gpioWrite(in3, 0); gpioWrite(in4, 0);
            break;
        case 2:
            gpioWrite(in1, 0); gpioWrite(in2, 0); gpioWrite(in3, 1); gpioWrite(in4, 0);
            break;
        case 3:
            gpioWrite(in1, 0); gpioWrite(in2, 0); gpioWrite(in3, 0); gpioWrite(in4, 1);
            break;
        default:
            fprintf(stderr, "Error: Invalid step number: %d\n", step);
            break;
    }
}

// Function to move a motor a specified number of steps
void move_motor(int motor, int steps) {
    for (int i = 0; i < steps && program_running; i++) {
        int step = i % 4;
        set_motor_pins(motor, step);
        gpioDelay(STEP_DELAY);
    }
}

// Function to draw a square
void draw_square(int side_length_mm) {
    int steps = side_length_mm * STEPS_PER_MM;

    // Move X-axis
    move_motor(1, steps);

    // Move Y-axis
    move_motor(2, steps);

    // Move X-axis back
    move_motor(1, -steps);

    // Move Y-axis back
    move_motor(2, -steps);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as outputs
    int pins[] = {MOTOR1_IN1, MOTOR1_IN2, MOTOR1_IN3, MOTOR1_IN4, MOTOR2_IN1, MOTOR2_IN2, MOTOR2_IN3, MOTOR2_IN4};
    for (int i = 0; i < sizeof(pins) / sizeof(pins[0]); i++) {
        if (gpioSetMode(pins[i], PI_OUTPUT) != 0) {
            fprintf(stderr, "Failed to set GPIO %d as output\n", pins[i]);
            gpioTerminate();
            return 1;
        }
        gpioWrite(pins[i], 0); // Initialize all pins to LOW
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Draw a square with a side length of 50mm
    draw_square(50);

    // Stop motors and clean up
    printf("Stopping motors...\n");
    gpioWrite(MOTOR1_IN1, 0); gpioWrite(MOTOR1_IN2, 0); gpioWrite(MOTOR1_IN3, 0); gpioWrite(MOTOR1_IN4, 0);
    gpioWrite(MOTOR2_IN1, 0); gpioWrite(MOTOR2_IN2, 0); gpioWrite(MOTOR2_IN3, 0); gpioWrite(MOTOR2_IN4, 0);
    gpioTerminate();

    printf("Program terminated successfully.\n");
    return 0;
}

