    i2c_handle = i2cOpen(1, address, 0); // Bus 1, address, flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return i2c_handle;
}

// Configure the LIS3DH accelerometer
int config_lis3dh(int handle) {
    // Configure CTRL_REG1: ±2g range, 100 Hz output data rate, enable all axes
    if (i2cWriteByteData(handle, CTRL_REG1, 0x57) < 0) {
        fprintf(stderr, "Error writing to CTRL_REG1\n");
        return -1;
    }

    // Configure CTRL_REG4: High-resolution mode (12-bit), enable LSB
    if (i2cWriteByteData(handle, CTRL_REG4, 0x88) < 0) {
        fprintf(stderr, "Error writing to CTRL_REG4\n");
        return -1;
    }

    return 0;
}

// Read acceleration data from the LIS3DH
int read_acceleration(int handle, float *x, float *y, float *z) {
    char buffer[6];
    int16_t raw_x, raw_y, raw_z;

    if (i2cReadI2CBlockData(handle, OUT_X_L | 0x80, buffer, 6) != 6) {
        fprintf(stderr, "Error reading acceleration data\n");
        return -1;
    }

    // Combine high and low bytes, shift right 4 bits, and scale to g
    raw_x = (int16_t)((buffer[1] << 8) | buffer[0]);
    raw_y = (int16_t)((buffer[3] << 8) | buffer[2]);
    raw_z = (int16_t)((buffer[5] << 8) | buffer[4]);

    *x = (float)raw_x >> 4 * 0.0009765625f;
    *y = (float)raw_y >> 4 * 0.0009765625f;
    *z = (float)raw_z >> 4 * 0.0009765625f;

    return 0;
}

// Log an event to the log file
void log_event(float x, float y, float z) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s - X: %.4f g, Y: %.4f g, Z: %.4f g\n", timestamp, x, y, z);
    fflush(log_file); // Ensure data is written to disk immediately
}

int main(int argc, char *argv[]) {
    int opt;

    // Parse command-line arguments
    while ((opt = getopt(argc, argv, "a:t:")) != -1) {
        switch (opt) {
            case 'a':
                i2c_address = strtol(optarg, NULL, 16);
                if (i2c_address < 0x08 || i2c_address > 0x77) {
                    fprintf(stderr, "Invalid I2C address. Must be between 0x08 and 0x77.\n");
                    return 1;
                }
                break;
            case 't':
                threshold = strtof(optarg, NULL);
                if (threshold <= 0.0f) {
                    fprintf(stderr, "Invalid threshold. Must be greater than 0.\n");
                    return 1;
                }
                break;
            default:
                fprintf(stderr, "Usage: %s [-a i2c_address] [-t threshold]\n", argv[0]);
                return 1;
        }
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c(i2c_address) < 0) {
        gpioTerminate();
        return 1;
    }

    // Configure LIS3DH
    if (config_lis3dh(i2c_handle) < 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("/var/log/high_acceleration.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    float x, y, z;

    // Main loop
    while (!terminate) {
        // Read acceleration data
        if (read_acceleration(i2c_handle, &x, &y, &z) == 0) {
            // Check if acceleration exceeds threshold
            if (fabs(x) > threshold || fabs(y) > threshold || fabs(z) > threshold) {
                log_event(x, y, z);
                system("sudo shutdown -h now"); // Shutdown the system
                break; // Exit the loop after shutdown
            }
        } else {
            fprintf(stderr, "Error reading acceleration, using 0.0g values\n");
        }

        gpioDelay(100); // 100 ms delay
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioTerminate();
    fclose(log_file);

    return 0;
}

