#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// Define GPIO pins
#define LEFT_SENSOR 4
#define CENTER_SENSOR 17
#define RIGHT_SENSOR 27
#define ALERT_PIN 22

// Define motor control pins (placeholder)
#define MOTOR_FORWARD 18
#define MOTOR_BACKWARD 23
#define MOTOR_LEFT 24
#define MOTOR_RIGHT 25

// Define constants
#define BUFFER_SIZE 5
#define ALERT_DURATION 2 // seconds
#define POLL_INTERVAL 10 // milliseconds

// Structure to hold sensor readings
typedef struct {
    int left;
    int center;
    int right;
} SensorReadings;

// Circular buffer structure
typedef struct {
    SensorReadings readings[BUFFER_SIZE];
    int head;
    int count;
} CircularBuffer;

// Global variables
CircularBuffer buffer;
int running = 1;

// Function prototypes
void initialize_gpio();
SensorReadings read_sensors();
void update_circular_buffer(CircularBuffer *buffer, SensorReadings readings);
int check_center_sensor_consecutive_errors(CircularBuffer *buffer);
void control_motors(int left, int center, int right);
void alert();
void signal_handler(int signal);
void cleanup();

// Initialize GPIO pins
void initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        exit(1);
    }

    gpioSetMode(LEFT_SENSOR, PI_INPUT);
    gpioSetMode(CENTER_SENSOR, PI_INPUT);
    gpioSetMode(RIGHT_SENSOR, PI_INPUT);
    gpioSetMode(ALERT_PIN, PI_OUTPUT);

    // Motor control pins (placeholder)
    gpioSetMode(MOTOR_FORWARD, PI_OUTPUT);
    gpioSetMode(MOTOR_BACKWARD, PI_OUTPUT);
    gpioSetMode(MOTOR_LEFT, PI_OUTPUT);
    gpioSetMode(MOTOR_RIGHT, PI_OUTPUT);

    // Initialize circular buffer
    buffer.head = 0;
    buffer.count = 0;
}

// Read sensor values
SensorReadings read_sensors() {
    SensorReadings readings;
    readings.left = gpioRead(LEFT_SENSOR);
    readings.center = gpioRead(CENTER_SENSOR);
    readings.right = gpioRead(RIGHT_SENSOR);
    return readings;
}

// Update circular buffer with new sensor readings
void update_circular_buffer(CircularBuffer *buffer, SensorReadings readings) {
    buffer->readings[buffer->head] = readings;
    buffer->head = (buffer->head + 1) % BUFFER_SIZE;
    if (buffer->count < BUFFER_SIZE) {
        buffer->count++;
    }
}

// Check for consecutive center sensor errors
int check_center_sensor_consecutive_errors(CircularBuffer *buffer) {
    if (buffer->count < BUFFER_SIZE) return 0; // Not enough readings yet

    int consecutive_errors = 0;
    for (int i = 0; i < buffer->count; i++) {
        int index = (buffer->head - buffer->count + i + BUFFER_SIZE) % BUFFER_SIZE; // Calculate index in reverse order
        if (buffer->readings[index].center == 1) {
            consecutive_errors++;
        } else {
            break; // Reset counter if a valid reading is found
        }
    }

    return (consecutive_errors == buffer->count) ? 1 : 0;
}

// Control motors based on sensor readings
void control_motors(int left, int center, int right) {
    if (center == 0) { // Line detected by center sensor
        gpioWrite(MOTOR_FORWARD, 1);
        gpioWrite(MOTOR_BACKWARD, 0);
        gpioWrite(MOTOR_LEFT, 0);
        gpioWrite(MOTOR_RIGHT, 0);
    } else if (left == 0) { // Line detected by left sensor
        gpioWrite(MOTOR_FORWARD, 0);
        gpioWrite(MOTOR_BACKWARD, 0);
        gpioWrite(MOTOR_LEFT, 1);
        gpioWrite(MOTOR_RIGHT, 0);
    } else if (right == 0) { // Line detected by right sensor
        gpioWrite(MOTOR_FORWARD, 0);
        gpioWrite(MOTOR_BACKWARD, 0);
        gpioWrite(MOTOR_LEFT, 0);
        gpioWrite(MOTOR_RIGHT, 1);
    } else { // No line detected by any sensor
        gpioWrite(MOTOR_FORWARD, 0);
        gpioWrite(MOTOR_BACKWARD, 0);
        gpioWrite(MOTOR_LEFT, 0);
        gpioWrite(MOTOR_RIGHT, 0);
    }
}

// Activate alert (LED/buzzer)
void alert() {
    gpioWrite(ALERT_PIN, 1); // Turn on LED/buzzer
    gpioDelay(ALERT_DURATION * 1000000); // Wait for 2 seconds
    gpioWrite(ALERT_PIN, 0); // Turn off LED/buzzer
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    running = 0;
}

// Cleanup GPIO resources
void cleanup() {
    gpioWrite(ALERT_PIN, 0); // Ensure LED/buzzer is off
    gpioTerminate();
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    initialize_gpio();

    printf("Line-following robot started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        SensorReadings readings = read_sensors();
        update_circular_buffer(&buffer, readings);

        if (check_center_sensor_consecutive_errors(&buffer)) {
            alert();
        }

        control_motors(readings.left, readings.center, readings.right);

        gpioDelay(POLL_INTERVAL * 1000); // Poll every 10 ms
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

