#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define SI7210_ADDR 0x30
#define RELAY_GPIO 17
#define THRESHOLD_MT 5.0
#define SAMPLE_INTERVAL_MS 100
#define POLL_DELAY_US 1000 // 1 ms
#define MAX_POLL_ATTEMPTS 50

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_pigpio();
int initialize_i2c();
int read_si7210(int *field_raw);
float convert_to_millitesla(int field_raw);
int control_relay(int state);
int log_event(const char *message);
void signal_handler(int signal);

// Structure for configuration (optional)
typedef struct {
    int relay_pin;
    float threshold;
    int sample_interval;
} Config;

Config config = {RELAY_GPIO, THRESHOLD_MT, SAMPLE_INTERVAL_MS};

int main() {
    int field_raw;
    float field_mT;
    int relay_state = 0; // 0 = off, 1 = on

    // Install signal handler
    signal(SIGINT, signal_handler);

    // Initialize pigpio
    if (initialize_pigpio() != 0) {
        return 1;
    }

    // Initialize I2C
    if (initialize_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("magnetic_events.txt", "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_si7210(&field_raw) == 0) {
            // Convert to milliTesla
            field_mT = convert_to_millitesla(field_raw);

            // Log sensor reading
            char log_message[256];
            snprintf(log_message, sizeof(log_message), "Sensor reading: %.2f mT", field_mT);
            log_event(log_message);

            // Control relay
            if (field_mT > config.threshold) {
                if (relay_state == 0) {
                    if (control_relay(1) == 0) {
                        relay_state = 1;
                        log_event("Relay activated");
                    } else {
                        log_event("Error activating relay");
                    }
                }
            } else {
                if (relay_state == 1) {
                    if (control_relay(0) == 0) {
                        relay_state = 0;
                        log_event("Relay deactivated");
                    } else {
                        log_event("Error deactivating relay");
                    }
                }
            }
        } else {
            log_event("Error reading sensor data");
        }

        // Wait for the next sample
        gpioDelay(config.sample_interval * 1000); // Convert ms to us
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioWrite(RELAY_GPIO, 0); // Deactivate relay
    gpioTerminate();
    fclose(log_file);

    return 0;
}

// Initialize pigpio
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }
    gpioSetMode(RELAY_GPIO, PI_OUTPUT);
    gpioWrite(RELAY_GPIO, 0); // Ensure relay is initially off
    return 0;
}

// Initialize I2C
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SI7210_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        return 1;
    }
    return 0;
}

// Read Si7210 sensor data
int read_si7210(int *field_raw) {
    int retries = 3;
    while (retries > 0) {
        // Start one-shot measurement
        if (i2cWriteByteData(i2c_handle, 0xC1, 0x01) != 0) {
            log_event("Error writing to I2C device");
            gpioWrite(RELAY_GPIO, 0);
            gpioDelay(100000); // 100ms delay
            retries--;
            continue;
        }

        // Wait for measurement to complete (polling)
        int poll_count = 0;
        while (i2cReadByteData(i2c_handle, 0xC1) != 0 && poll_count < MAX_POLL_ATTEMPTS) {
            gpioDelay(POLL_DELAY_US);
            poll_count++;
        }

        if (poll_count >= MAX_POLL_ATTEMPTS) {
            log_event("Timeout waiting for measurement");
            gpioWrite(RELAY_GPIO, 0);
            gpioDelay(100000); // 100ms delay
            retries--;
            continue;
        }

        // Read sensor data
        char buffer[2];
        if (i2cReadI2CBlockData(i2c_handle, 0xC0, buffer, 2) != 2) {
            log_event("Error reading sensor data from I2C device");
            gpioWrite(RELAY_GPIO, 0);
            gpioDelay(100000); // 100ms delay
            retries--;
            continue;
        }

        // Combine bytes into signed 16-bit value
        *field_raw = (int16_t)((buffer[1] << 8) | buffer[0]);
        return 0; // Success
    }
    return 1; // Failure after retries
}

// Convert raw data to milliTesla
float convert_to_millitesla(int field_raw) {
    return (float)field_raw * 25.0 / 1000.0;
}

// Control relay
int control_relay(int state) {
    gpioWrite(RELAY_GPIO, state);
    return 0;
}

// Log event with timestamp
int log_event(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    fprintf(log_file, "%s: %s\n", timestamp, message);
    fflush(log_file); // Ensure immediate write
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    log_event("Received SIGINT, shutting down...");
}

