        if (i2cWriteByteData(i2c_handle, 0xC1, 0x01) != 0) {
            log_event("Error writing to I2C device");
            gpioWrite(RELAY_GPIO, 0);
            gpioDelay(100000); // 100ms delay
            retries--;
            continue;
        }

        // Wait for measurement to complete (polling)
        int poll_count = 0;
        while (i2cReadByteData(i2c_handle, 0xC1) != 0 && poll_count < MAX_POLL_ATTEMPTS) {
            gpioDelay(POLL_DELAY_US);
            poll_count++;
        }

        if (poll_count >= MAX_POLL_ATTEMPTS) {
            log_event("Timeout waiting for measurement");
            gpioWrite(RELAY_GPIO, 0);
            gpioDelay(100000); // 100ms delay
            retries--;
            continue;
        }

        // Read sensor data
        char buffer[2];
        if (i2cReadI2CBlockData(i2c_handle, 0xC0, buffer, 2) != 2) {
            log_event("Error reading sensor data from I2C device");
            gpioWrite(RELAY_GPIO, 0);
            gpioDelay(100000); // 100ms delay
            retries--;
            continue;
        }

        // Combine bytes into signed 16-bit value
        *field_raw = (int16_t)((buffer[1] << 8) | buffer[0]);
        return 0; // Success
    }
    return 1; // Failure after retries
}

// Convert raw data to milliTesla
float convert_to_millitesla(int field_raw) {
    return (float)field_raw * 25.0 / 1000.0;
}

// Control relay
int control_relay(int state) {
    gpioWrite(RELAY_GPIO, state);
    return 0;
}

// Log event with timestamp
int log_event(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    fprintf(log_file, "%s: %s\n", timestamp, message);
    fflush(log_file); // Ensure immediate write
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    log_event("Received SIGINT, shutting down...");
}

