#define PORT 5000
#define GPIO_PIN 18
#define LOG_FILE "relay_log.txt"

// Global variables for signal handling
volatile sig_atomic_t program_running = 1;
int server_socket = -1;
FILE *log_file = NULL;

// Function prototypes
int initialize_gpio();
int create_socket();
int bind_socket(int socket_fd, int port);
int listen_socket(int socket_fd);
int accept_connection(int socket_fd);
int read_command(int client_socket);
int process_command(int client_socket, const char *command);
int control_relay(int gpio_pin, const char *command);
int log_event(const char *event_message);
void signal_handler(int signal);
void cleanup();

// Function to initialize the pigpio library
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    gpioSetMode(GPIO_PIN, PI_OUTPUT);
    gpioWrite(GPIO_PIN, 0); // Initialize relay to OFF state
    return 0;
}

// Function to create a TCP socket
int create_socket() {
    int socket_fd = socket(AF_INET, SOCK_STREAM, 0);
    if (socket_fd == -1) {
        perror("Error creating socket");
        return -1;
    }
    return socket_fd;
}

// Function to bind the socket to a specific port
int bind_socket(int socket_fd, int port) {
    struct sockaddr_in server_address;
    server_address.sin_family = AF_INET;
    server_address.sin_addr.s_addr = INADDR_ANY;
    server_address.sin_port = htons(port);

    if (bind(socket_fd, (struct sockaddr *)&server_address, sizeof(server_address)) < 0) {
        perror("Error binding socket");
        return -1;
    }
    return 0;
}

// Function to listen for incoming connections
int listen_socket(int socket_fd) {
    if (listen(socket_fd, 3) < 0) {
        perror("Error listening on socket");
        return -1;
    }
    return 0;
}

// Function to accept a connection from a client
int accept_connection(int socket_fd) {
    struct sockaddr_in client_address;
    socklen_t client_len = sizeof(client_address);
    int client_socket = accept(socket_fd, (struct sockaddr *)&client_address, &client_len);
    if (client_socket < 0) {
        perror("Error accepting connection");
        return -1;
    }
    return client_socket;
}

// Function to read a command from the client
int read_command(int client_socket) {
    char buffer[1024];
    memset(buffer, 0, sizeof(buffer));
    ssize_t bytes_read = recv(client_socket, buffer, sizeof(buffer) - 1, 0);
    if (bytes_read < 0) {
        perror("Error receiving data");
        return -1;
    } else if (bytes_read == 0) {
        fprintf(stderr, "Client disconnected\n");
        return -1;
    }
    buffer[bytes_read] = '\0';
    return atoi(buffer);
}

// Function to process the received command
int process_command(int client_socket, const char *command) {
    if (strcmp(command, "ON") == 0) {
        return 1;
    } else if (strcmp(command, "OFF") == 0) {
        return 0;
    } else {
        return -1;
    }
}

// Function to control the relay
int control_relay(int gpio_pin, const char *command) {
    if (strcmp(command, "ON") == 0) {
        gpioWrite(gpio_pin, 1);
        return 0;
    } else if (strcmp(command, "OFF") == 0) {
        gpioWrite(gpio_pin, 0);
        return 0;
    } else {
        return -1;
    }
}

