        fprintf(log_file, "[%s] %s\n", timestamp, event_message);
        fflush(log_file); // Ensure the log is written immediately
        return 0;
    } else {
        fprintf(stderr, "Error: Log file not opened.\n");
        return -1;
    }
}

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

// Cleanup function to release resources
void cleanup() {
    printf("Cleaning up resources...\n");
    if (server_socket != -1) {
        close(server_socket);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioWrite(GPIO_PIN, 0); // Turn off relay
    gpioTerminate();
    printf("Cleanup complete. Exiting.\n");
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Create socket
    server_socket = create_socket();
    if (server_socket == -1) {
        cleanup();
        return 1;
    }

    // Bind socket
    if (bind_socket(server_socket, PORT) != 0) {
        cleanup();
        return 1;
    }

    // Listen for connections
    if (listen_socket(server_socket) != 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        cleanup();
        return 1;
    }

    printf("Relay control server started on port %d\n", PORT);

    while (program_running) {
        // Accept connection
        int client_socket = accept_connection(server_socket);
        if (client_socket == -1) {
            continue; // Continue listening for other connections
        }

        printf("Connection accepted\n");

        // Read command
        int command_result = read_command(client_socket);
        if (command_result == -1) {
            close(client_socket);
            continue;
        }

        char command[10];
        if (command_result == 1) {
            strcpy(command, "ON");
        } else if (command_result == 0) {
            strcpy(command, "OFF");
        } else {
            close(client_socket);
            continue;
        }

        // Process command
        int process_result = process_command(client_socket, command);

        if (process_result == 1) {
            // Control relay
            int control_result = control_relay(GPIO_PIN, command);
            if (control_result == 0) {
                log_event("Relay turned ON");
                printf("Relay turned ON\n");
            } else {
                log_event("Error controlling relay (ON)");
                fprintf(stderr, "Error controlling relay (ON)\n");
            }
        } else if (process_result == 0) {
            // Control relay
            int control_result = control_relay(GPIO_PIN, command);
            if (control_result == 0) {
                log_event("Relay turned OFF");
                printf("Relay turned OFF\n");
            } else {
                log_event("Error controlling relay (OFF)");
                fprintf(stderr, "Error controlling relay (OFF)\n");
            }
        } else {
            log_event("Invalid command received");
            fprintf(stderr, "Invalid command received\n");
        }

        // Close client socket
        close(client_socket);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

