int initialize_i2c(int bus, int addr) {
    int handle = i2cOpen(bus, addr, 0);
    if (handle < 0) {
        fprintf(stderr, "Failed to open I2C device at address 0x%02x: %s\n", addr, strerror(errno));
        return -1;
    }
    return handle;
}

// Function to send the measurement command
int send_measurement_command(int handle) {
    char command[2] = {MEASUREMENT_COMMAND_1, MEASUREMENT_COMMAND_2};
    int result = i2cWriteDevice(handle, command, 2);
    if (result != 0) {
        fprintf(stderr, "Failed to send measurement command: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Function to read flow data from the sensor
int read_flow_data(int handle, float *flow_rate) {
    char buffer[3];
    int result = i2cReadDevice(handle, buffer, 3);
    if (result != 3) {
        fprintf(stderr, "Failed to read flow data: %s\n", strerror(errno));
        return -1;
    }

    uint8_t crc = buffer[2];
    uint8_t data[2] = {buffer[0], buffer[1]};

    if (!validate_crc(data, crc)) {
        fprintf(stderr, "CRC validation failed\n");
        return -1;
    }

    // Convert to signed 16-bit big-endian
    int16_t raw_value = (data[0] << 8) | data[1];

    // Convert to ml/min
    *flow_rate = (float)raw_value * SCALE_FACTOR;

    return 0;
}

// Function to validate the CRC-8 checksum
int validate_crc(uint8_t data[], uint8_t crc) {
    uint8_t polynomial = 0x31;
    uint8_t crc_calculated = 0xFF;

    for (int i = 0; i < 2; i++) {
        crc_calculated ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc_calculated & 0x80) {
                crc_calculated = (crc_calculated << 1) ^ polynomial;
            } else {
                crc_calculated <<= 1;
            }
        }
    }

    return (crc_calculated == crc);
}

// Function to control the relay
void control_relay(int state) {
    gpioWrite(GPIO_RELAY, state);
}

// Function to log flow rates to a file
void log_flow_rates(float flow_rate1, float flow_rate2) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        return;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d.%03d, Sensor 1: %.2f ml/min, Sensor 2: %.2f ml/min\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, t % 1000,
            flow_rate1, flow_rate2);

    fclose(fp);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

// Cleanup function to release resources
void cleanup() {
    control_relay(0); // De-energize relay
    if (i2c_handle1 >= 0) {
        i2cClose(i2c_handle1);
    }
    if (i2c_handle2 >= 0) {
        i2cClose(i2c_handle2);
    }
    gpioTerminate();
    printf("Cleanup complete. Exiting.\n");
}

int main() {
    // Register signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (initialize_pigpio() != 0) {
        return 1;
    }

    // Initialize I2C
    i2c_handle1 = initialize_i2c(I2C_BUS, SENSOR1_ADDR);
    if (i2c_handle1 < 0) {
        cleanup();
        return 1;
    }

    i2c_handle2 = initialize_i2c(I2C_BUS, SENSOR2_ADDR);
    if (i2c_handle2 < 0) {
        cleanup();
        return 1;
    }

    // Send measurement command to both sensors
    if (send_measurement_command(i2c_handle1) != 0) {
        cleanup();
        return 1;
    }
    if (send_measurement_command(i2c_handle2) != 0) {
        cleanup();
        return 1;
    }

    // Configure GPIO 18 as output
    gpioSetMode(GPIO_RELAY, PI_OUTPUT);
    control_relay(0); // Initialize relay to de-energized state

    float flow_rate1, flow_rate2;

    // Main loop
    while (running) {
        // Read flow data from sensor 1
        if (read_flow_data(i2c_handle1, &flow_rate1) != 0) {
            fprintf(stderr, "Error reading sensor 1, skipping cycle\n");
        }

        // Read flow data from sensor 2
        if (read_flow_data(i2c_handle2, &flow_rate2) != 0) {
            fprintf(stderr, "Error reading sensor 2, skipping cycle\n");
        }

        // Control relay based on flow rates
        if (flow_rate1 < FLOW_THRESHOLD || flow_rate2 < FLOW_THRESHOLD) {
            control_relay(1); // Energize relay
        } else {
            control_relay(0); // De-energize relay
        }

        // Log flow rates
        log_flow_rates(flow_rate1, flow_rate2);

        // Wait for 100 ms
        gpioDelay(100);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

