#define MOTOR_IN2_PIN 24

// Define motor run time (seconds)
#define MOTOR_RUN_TIME 5

// Define dry period (seconds)
#define DRY_PERIOD 3

// Global variables
static volatile int running = 1;
static volatile int dry_count = 0;
static volatile int last_rain_state = 1; // Assume initially dry

// Function prototypes
void signal_handler(int signal);
int initialize_gpio();
int read_rain_sensor();
void close_window();
void stop_motor();
void log_message(int priority, const char *message);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    log_message(LOG_INFO, "Signal received, shutting down...");
    running = 0;
}

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        log_message(LOG_ERR, "pigpio initialisation failed");
        return 1;
    }

    gpioSetMode(RAIN_SENSOR_PIN, PI_INPUT);
    gpioSetPullUpDown(RAIN_SENSOR_PIN, PI_PUD_UP);

    gpioSetMode(MOTOR_ENA_PIN, PI_OUTPUT);
    gpioSetMode(MOTOR_IN1_PIN, PI_OUTPUT);
    gpioSetMode(MOTOR_IN2_PIN, PI_OUTPUT);

    stop_motor(); // Ensure motor is stopped on startup

    log_message(LOG_INFO, "GPIO initialisation complete");
    return 0;
}

