    if (gpioWrite(MOTOR_ENA_PIN, 1) != 0) {
        log_message(LOG_WARNING, "Failed to set ENA HIGH");
    }
    if (gpioWrite(MOTOR_IN1_PIN, 1) != 0) {
        log_message(LOG_WARNING, "Failed to set IN1 HIGH");
    }
    if (gpioWrite(MOTOR_IN2_PIN, 0) != 0) {
        log_message(LOG_WARNING, "Failed to set IN2 LOW");
    }
    gpioDelay(MOTOR_RUN_TIME * 1000); // Run motor for MOTOR_RUN_TIME seconds
    stop_motor();
    log_message(LOG_INFO, "Window closed.");
}

// Stop the motor
void stop_motor() {
    if (gpioWrite(MOTOR_ENA_PIN, 0) != 0) {
        log_message(LOG_WARNING, "Failed to set ENA LOW");
    }
    if (gpioWrite(MOTOR_IN1_PIN, 0) != 0) {
        log_message(LOG_WARNING, "Failed to set IN1 LOW");
    }
    if (gpioWrite(MOTOR_IN2_PIN, 0) != 0) {
        log_message(LOG_WARNING, "Failed to set IN2 LOW");
    }
    log_message(LOG_INFO, "Motor stopped.");
}

// Log messages to syslog
void log_message(int priority, const char *message) {
    syslog(priority, message);
}

int main() {
    // Open syslog
    openlog("rain_window", LOG_PID | LOG_CONS, LOG_USER);

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        closelog();
        return 1;
    }

    log_message(LOG_INFO, "Rain-actuated window controller started");

    // Main loop
    while (running) {
        int rain_detected = read_rain_sensor();

        if (rain_detected == 0 && last_rain_state == 1) {
            // Rising edge: dry to wet
            log_message(LOG_INFO, "Rain detected!");
            close_window();
            dry_count = 0; // Reset dry count after rain
        } else if (rain_detected == 1) {
            // Sensor is dry
            dry_count++;
            if (dry_count >= (DRY_PERIOD * 3)) {
                // Sensor has been dry for DRY_PERIOD seconds
                dry_count = 0; // Reset dry count
            }
        } else {
            // Sensor is wet
            dry_count = 0; // Reset dry count
        }

        last_rain_state = rain_detected;
        usleep(200000); // 200 ms delay
    }

    // Cleanup
    stop_motor();
    gpioTerminate();
    log_message(LOG_INFO, "Rain-actuated window controller stopped");
    closelog();

    return 0;
}

