// Define GPIO pins
#define SERVO_PIN 18
#define LOCK_BUTTON_PIN 21
#define UNLOCK_BUTTON_PIN 22

// Define pulse widths for locked and unlocked positions
#define LOCKED_PULSE_WIDTH 2000
#define UNLOCKED_PULSE_WIDTH 1000

// Debounce delay in milliseconds
#define DEBOUNCE_DELAY 50

// Global variable to track program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, stopping servo and exiting...\n", signal);
    gpioServo(SERVO_PIN, 0); // Stop the servo
    gpioTerminate();         // Terminate pigpio
    exit(0);
}

// Function to set the servo pulse width
int set_servo_pulse_width(int pin, int pulse_width) {
    int result = gpioServo(pin, pulse_width);
    if (result != 0) {
        fprintf(stderr, "Error setting servo pulse width: %d\n", result);
        return -1;
    }
    return 0;
}

// Function to handle button press and servo control
void handle_button_press(int button_pin, int pulse_width) {
    if (gpioRead(button_pin) == 0) { // Button is pressed (LOW)
        printf("Button %d pressed, setting servo to pulse width %d\n", button_pin, pulse_width);
        if (set_servo_pulse_width(SERVO_PIN, pulse_width) != 0) {
            fprintf(stderr, "Failed to set servo pulse width for button %d\n", button_pin);
        }
        // Debounce: Wait for button release and then a short delay
        while (gpioRead(button_pin) == 0 && program_running) {
            gpioDelay(1); // Small delay to prevent busy-waiting
        }
        gpioDelay(DEBOUNCE_DELAY * 1000); // Debounce delay
    }
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(SERVO_PIN, PI_OUTPUT);
    gpioSetMode(LOCK_BUTTON_PIN, PI_INPUT);
    gpioSetMode(UNLOCK_BUTTON_PIN, PI_INPUT);

    // Enable pull-up resistors on button pins
    gpioSetPullUpDown(LOCK_BUTTON_PIN, PI_PUD_UP);
    gpioSetPullUpDown(UNLOCK_BUTTON_PIN, PI_PUD_UP);

    // Set signal handler for Ctrl+C
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Door lock control program started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        handle_button_press(LOCK_BUTTON_PIN, LOCKED_PULSE_WIDTH);
        handle_button_press(UNLOCK_BUTTON_PIN, UNLOCKED_PULSE_WIDTH);
        gpioDelay(1); // Small delay to reduce CPU usage
    }

    // Cleanup (should not reach here if signal handler works correctly)
    gpioServo(SERVO_PIN, 0); // Stop the servo
    gpioTerminate();         // Terminate pigpio

    return 0;
}

