#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>
#include <string.h>

// Define GPIO pins
#define PIR_SENSOR_PIN 4
#define LED_PIN 17

// Define log file name
#define LOG_FILE "security_log.txt"

// Global variables
FILE *log_file = NULL;
int running = 1;

// Function prototypes
int initialize_gpio();
int read_pir_sensor();
int control_led(int state);
int log_event(const char *event_type, int duration);
void signal_handler(int signal);

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1; // Indicate failure
    }

    if (gpioSetMode(PIR_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set PIR sensor pin as input\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(LED_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set LED pin as output\n");
        gpioTerminate();
        return 1;
    }

    return 0; // Indicate success
}

// Function to read the PIR sensor
int read_pir_sensor() {
    return gpioRead(PIR_SENSOR_PIN);
}

// Function to control the LED
int control_led(int state) {
    gpioWrite(LED_PIN, state);
    return 0; // Indicate success
}

// Function to log events to a file
int log_event(const char *event_type, int duration) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s - %s - Duration: %d seconds\n", timestamp, event_type, duration);
        fflush(log_file); // Ensure data is written to disk immediately
        return 0; // Indicate success
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
        return 1; // Indicate failure
    }
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    running = 0;
    control_led(0); // Turn off the LED
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate(); // Release pigpio resources
    exit(0);
}

int main() {
    // Register signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1; // Exit if initialization fails
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    printf("Smart Security Light running. Press Ctrl+C to exit.\n");

    while (running) {
        // Read PIR sensor
        int motion_detected = read_pir_sensor();

        // Check for rising edge (motion detected)
        if (motion_detected == 1) {
            printf("Motion detected!\n");

            // Activate LED
            control_led(1);

            // Log event
            log_event("Activation", 0); // Duration is 0, will be updated later

            // Wait for 60 seconds
            gpioDelay(60000); // pigpioDelay takes milliseconds

            // Deactivate LED
            control_led(0);

            // Measure duration
            time_t start_time = time(NULL);
            while (running && (time(NULL) - start_time) < 60); // Wait for 60 seconds

            // Log event with duration
            log_event("Deactivation", 60);

            printf("Light deactivated.\n");
        }

        gpioDelay(100); // Poll every 100ms
    }

    // Cleanup (should not reach here if signal handler works correctly)
    control_led(0);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

