int read_touch_status();
void toggle_relay(int state);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize MPR121 sensor
int initialize_mpr121() {
    // Reset the MPR121
    if (i2cWriteByteData(i2c_handle, 0x80, 0x63) < 0) {
        fprintf(stderr, "Error: Failed to reset MPR121\n");
        return -1;
    }
    gpioDelay(100); // Wait for reset to complete

    // Configure baseline filtering (MHD/NHD/NCL/FDL)
    if (i2cWriteByteData(i2c_handle, 0x2B, 0x01) < 0) {
        fprintf(stderr, "Error: Failed to configure baseline filtering\n");
        return -1;
    }

    // Set debounce
    if (i2cWriteByteData(i2c_handle, 0x5B, 0x0A) < 0) {
        fprintf(stderr, "Error: Failed to set debounce\n");
        return -1;
    }

    // Set FFI/SFI/CDT
    if (i2cWriteByteData(i2c_handle, 0x2C, 0x01) < 0) {
        fprintf(stderr, "Error: Failed to set FFI/SFI/CDT\n");
        return -1;
    }

    // Set auto-config
    if (i2cWriteByteData(i2c_handle, 0x7B, 0x00) < 0) {
        fprintf(stderr, "Error: Failed to set auto-config (0x7B)\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, 0x7C, 0x00) < 0) {
        fprintf(stderr, "Error: Failed to set auto-config (0x7C)\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, 0x7D, 0x00) < 0) {
        fprintf(stderr, "Error: Failed to set auto-config (0x7D)\n");
        return -1;
    }

    // Enable all 12 electrodes
    if (i2cWriteByteData(i2c_handle, 0x5E, 0x0C) < 0) {
        fprintf(stderr, "Error: Failed to enable electrodes\n");
        return -1;
    }

    return 0;
}

// Read touch status from MPR121
int read_touch_status() {
    int touch_status = i2cReadWordData(i2c_handle, 0x00);
    if (touch_status < 0) {
        fprintf(stderr, "Error: Failed to read touch status\n");
        return -1;
    }
    return touch_status;
}

// Toggle the relay
void toggle_relay(int state) {
    gpioWrite(RELAY_GPIO, state);
    printf("Relay set to %d\n", state);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set relay GPIO as output
    gpioSetMode(RELAY_GPIO, PI_OUTPUT);
    toggle_relay(0); // Ensure relay is off on startup

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, MPR121_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C bus\n");
        gpioTerminate();
        return 1;
    }

    // Initialize MPR121
    if (initialize_mpr121() < 0) {
        fprintf(stderr, "Error: MPR121 initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int last_touch_state = 0;
    int current_touch_state = 0;
    unsigned long last_touch_time = 0;

    // Main loop
    while (!terminate) {
        current_touch_state = read_touch_status();
        if (current_touch_state < 0) {
            fprintf(stderr, "Error reading touch status, exiting...\n");
            break;
        }

        // Check for rising edge on electrode 0
        if ((current_touch_state & 0x0001) && !(last_touch_state & 0x0001)) {
            unsigned long now = gpioTick();
            if (now - last_touch_time > DEBOUNCE_MS * 1000) { // Debounce
                toggle_relay(1); // Turn relay ON
                last_touch_time = now;
            }
        } else if (!(current_touch_state & 0x0001) && (last_touch_state & 0x0001)) {
            // Check for falling edge on electrode 0
            toggle_relay(0); // Turn relay OFF
        }

        last_touch_state = current_touch_state;
        gpioDelay(10); // Small delay to avoid busy-waiting
    }

    // Clean up
    toggle_relay(0); // Ensure relay is off on exit
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

