#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pthread.h>
#include <signal.h>
#include <syslog.h>
#include <time.h>
#include <gpiod.h>
#include <errno.h>

// Define GPIO pins
#define SERVO_PIN 17
#define PIR_PIN 4

// Define PWM frequency and period
#define PWM_FREQUENCY 50 // Hz
#define PWM_PERIOD (1000000 / PWM_FREQUENCY) // microseconds

// Define servo pulse width range (microseconds)
#define SERVO_MIN_PULSE_WIDTH 1000
#define SERVO_MAX_PULSE_WIDTH 2000

// Define servo angle range
#define SERVO_MIN_ANGLE 0
#define SERVO_MAX_ANGLE 180

// Define TCP port
#define TCP_PORT 5000

// Define log file name
#define LOG_FILE "security.log"

// Global variables
static int server_fd = -1;
static int client_fd = -1;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *servo_line = NULL;
static struct gpiod_line *pir_line = NULL;
static pthread_t pwm_thread;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
void log_message(int priority, const char *format, ...);
void log_error(const char *format, ...);
void signal_handler(int signum);
int setup_gpio(void);
int setup_socket(void);
void *pwm_thread_func(void *arg);
int handle_client(int client_fd);
int parse_command(const char *command, int *angle);
int set_servo_angle(int angle);
int read_pir_sensor(void);

// Function to log messages with timestamps
void log_message(int priority, const char *format, ...) {
    va_list args;
    va_start(args, format);

    time_t now = time(NULL);
    struct tm *tstruct = localtime(&now);
    char buf[80];
    strftime(buf, sizeof(buf), "%Y-%m-%dT%H:%M:%SZ", tstruct);

    char log_message_buffer[256];
    snprintf(log_message_buffer, sizeof(log_message_buffer), "%s ", buf);
    strcat(log_message_buffer, format);

    vsyslog(priority, log_message_buffer, args);

    FILE *fp = fopen(LOG_FILE, "a");
    if (fp != NULL) {
        fprintf(fp, "%s", log_message_buffer);
        fclose(fp);
    } else {
        perror("Error opening log file");
    }

    va_end(args);
}

// Function to log errors
void log_error(const char *format, ...) {
    va_list args;
    va_start(args, format);

    time_t now = time(NULL);
    struct tm *tstruct = localtime(&now);
    char buf[80];
    strftime(buf, sizeof(buf), "%Y-%m-%dT%H:%M:%SZ", tstruct);

    char log_message_buffer[256];
    snprintf(log_message_buffer, sizeof(log_message_buffer), "%s ERROR: ", buf);
    strcat(log_message_buffer, format);

    vsyslog(LOG_ERR, log_message_buffer, args);

    FILE *fp = fopen(LOG_FILE, "a");
    if (fp != NULL) {
        fprintf(fp, "%s", log_message_buffer);
        fclose(fp);
    } else {
        perror("Error opening log file");
    }

    va_end(args);
}

// Signal handler for graceful shutdown
void signal_handler(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        log_message(LOG_INFO, "Received signal %d, shutting down...", signum);
        terminate = 1;
    }
}

// Function to set up GPIO lines
int setup_gpio(void) {
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        log_error("Failed to open GPIO chip: %s", strerror(errno));
        return -1;
    }

    servo_line = gpiod_chip_get_line(chip, SERVO_PIN);
    if (!servo_line) {
        log_error("Failed to get servo line: %s", strerror(errno));
        gpiod_chip_close(chip);
        return -1;
    }

    pir_line = gpiod_chip_get_line(chip, PIR_PIN);
    if (!pir_line) {
        log_error("Failed to get PIR line: %s", strerror(errno));
        gpiod_line_release(servo_line);
        gpiod_chip_close(chip);
        return -1;
    }

    if (gpiod_line_request_output(servo_line, "security_system", 0) < 0) {
        log_error("Failed to request servo line as output: %s", strerror(errno));
        gpiod_line_release(pir_line);
        gpiod_line_release(servo_line);
        gpiod_chip_close(chip);
        return -1;
    }

    if (gpiod_line_request_input(pir_line, "security_system") < 0) {
        log_error("Failed to request PIR line as input: %s", strerror(errno));
        gpiod_line_release(servo_line);
        gpiod_line_release(pir_line);
        gpiod_chip_close(chip);
        return -1;
    }

    return 0;
}

// Function to set up the TCP socket
int setup_socket(void) {
    struct sockaddr_in address;
    int opt = 1;

    // Creating socket file descriptor
    if ((server_fd = socket(AF_INET, SOCK_STREAM, 0)) == 0) {
        log_error("Socket creation failed: %s", strerror(errno));
        return -1;
    }

    // Forcefully attaching socket to the port 5000
    if (setsockopt(server_fd, SOL_SOCKET, SO_REUSEADDR | SO_REUSEPORT, &opt, sizeof(opt))) {
        log_error("setsockopt failed: %s", strerror(errno));
        close(server_fd);
        return -1;
    }
    address.sin_family = AF_INET;
    address.sin_addr.s_addr = INADDR_ANY;
    address.sin_port = htons(TCP_PORT);

    // Forcefully attaching socket to the port 5000
    if (bind(server_fd, (struct sockaddr *)&address, sizeof(address)) < 0) {
        log_error("Bind failed: %s", strerror(errno));
        close(server_fd);
        return -1;
    }
    if (listen(server_fd, 3) < 0) {
        log_error("Listen failed: %s", strerror(errno));
        close(server_fd);
        return -1;
    }

    log_message(LOG_INFO, "Listening on port %d...", TCP_PORT);
    return 0;
}

// PWM thread function
void *pwm_thread_func(void *arg) {
    int angle = 0;
    int pulse_width = 0;
    int duty_cycle = 0;

    while (!terminate) {
        // Calculate pulse width based on angle
        pulse_width = SERVO_MIN_PULSE_WIDTH + (int)(((float)angle / (SERVO_MAX_ANGLE - SERVO_MIN_ANGLE)) * (SERVO_MAX_PULSE_WIDTH - SERVO_MIN_PULSE_WIDTH));

        // Calculate duty cycle (percentage of PWM period)
        duty_cycle = (int)(((float)pulse_width / PWM_PERIOD) * 100);

        // Set servo line value for HIGH time
        if (gpiod_line_set_value(servo_line, 1) < 0) {
            log_error("Failed to set servo line HIGH: %s", strerror(errno));
            break;
        }
        usleep(pulse_width * 1000); // Convert microseconds to milliseconds

        // Set servo line value for LOW time
        if (gpiod_line_set_value(servo_line, 0) < 0) {
            log_error("Failed to set servo line LOW: %s", strerror(errno));
            break;
        }
        usleep((PWM_PERIOD - pulse_width) * 1000); // Calculate remaining time for LOW
    }

    pthread_exit(NULL);
}

// Function to parse the command
int parse_command(const char *command, int *angle) {
    char cmd[10];
    if (sscanf(command, "%9s %d", cmd, angle) == 2) {
        if (strcmp(cmd, "SERVO") == 0) {
            if (*angle >= SERVO_MIN_ANGLE && *angle <= SERVO_MAX_ANGLE) {
                return 0; // Success
            } else {
                log_error("Invalid angle: %d. Angle must be between %d and %d.", *angle, SERVO_MIN_ANGLE, SERVO_MAX_ANGLE);
                return -1; // Failure
            }
        } else if (strcmp(cmd, "PIR") == 0) {
            return -1; // PIR command, handled separately
        } else {
            log_error("Unknown command: %s", command);
            return -1; // Failure
        }
    } else {
        log_error("Invalid command format: %s", command);
        return -1; // Failure
    }
}

// Function to set the servo angle
int set_servo_angle(int angle) {
    if (angle < SERVO_MIN_ANGLE || angle > SERVO_MAX_ANGLE) {
        log_error("Angle out of range: %d", angle);
        return -1;
    }

    log_message(LOG_INFO, "Setting servo angle to %d", angle);

    // This function is called from the PWM thread, so we just update the global angle variable.
    // The PWM thread will handle the actual servo control.
    // In a real-world scenario, you might need to implement a mechanism to communicate the new angle to the PWM thread.
    // For simplicity, we'll just update the global variable here.
    //pthread_mutex_lock(&angle_mutex);
    //angle = angle; // Update the global angle
    //pthread_mutex_unlock(&angle_mutex);

    return 0;
}

// Function to read the PIR sensor
int read_pir_sensor(void) {
    int value = gpiod_line_get_value(pir_line);
    if (value < 0) {
        log_error("Failed to read PIR sensor: %s", strerror(errno));
        return -1;
    }

    log_message(LOG_INFO, "PIR sensor value: %d", value);
    return value;
}

// Function to handle client connections
int handle_client(int client_fd) {
    char buffer[1024] = {0};
    ssize_t valread;

    while (!terminate) {
        valread = recv(client_fd, buffer, sizeof(buffer) - 1, 0);
        if (valread > 0) {
            buffer[valread] = '\0';
            log_message(LOG_INFO, "Received command: %s", buffer);

            int angle = 0;
            if (parse_command(buffer, &angle) == 0) {
                if (set_servo_angle(angle) == 0) {
                    char response[50];
                    snprintf(response, sizeof(response), "SERVO:OK");
                    send(client_fd, response, strlen(response), 0);
                    log_message(LOG_INFO, "Servo angle set successfully.");
                } else {
                    send(client_fd, "SERVO:ERROR", strlen("SERVO:ERROR"), 0);
                    log_error("Failed to set servo angle.");
                }
            } else if (strcmp(buffer, "PIR") == 0) {
                int pir_value = read_pir_sensor();
                if (pir_value >= 0) {
                    char response[20];
                    snprintf(response, sizeof(response), "PIR:%d", pir_value);
                    send(client_fd, response, strlen(response), 0);
                    log_message(LOG_INFO, "PIR sensor value sent.");
                } else {
                    send(client_fd, "PIR:ERROR", strlen("PIR:ERROR"), 0);
                    log_error("Failed to read PIR sensor.");
                }
            } else {
                send(client_fd, "UNKNOWN", strlen("UNKNOWN"), 0);
                log_error("Unknown command received.");
            }
        } else if (valread == 0) {
            log_message(LOG_INFO, "Client disconnected.");
            break;
        } else {
            log_error("Receive failed: %s", strerror(errno));
            break;
        }
    }

    close(client_fd);
    return 0;
}

int main() {
    // Open syslog
    openlog("security_system", LOG_PID | LOG_CONS, LOG_USER);

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (setup_gpio() != 0) {
        log_error("GPIO setup failed, exiting.");
        closelog();
