#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Constants
#define I2C_BUS 1
#define BH1750_ADDR 0x23
#define GROW_LIGHT_GPIO 23
#define LUX_THRESHOLD 150.0
#define LOG_FILE "grow_log.txt"
#define SAMPLE_INTERVAL_MS 2000

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int read_bh1750(float *lux);
void control_relay(int state);
void log_data(float lux);
void signal_handler(int signal);
void cleanup();

// Structure for configuration (optional)
typedef struct {
    int i2c_bus;
    int bh1750_address;
    int grow_light_gpio;
    float lux_threshold;
    char *log_file_name;
    int sample_interval_ms;
} Config;

Config config = {
    I2C_BUS,
    BH1750_ADDR,
    GROW_LIGHT_GPIO,
    LUX_THRESHOLD,
    LOG_FILE,
    SAMPLE_INTERVAL_MS
};

int main() {
    float lux;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        fprintf(stderr, "I2C initialisation failed\n");
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen(config.log_file_name, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup();
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Read lux value
        if (read_bh1750(&lux) == 0) {
            // Control relay based on lux value
            if (lux < config.lux_threshold) {
                control_relay(1); // Turn on relay
            } else {
                control_relay(0); // Turn off relay
            }

            // Log data
            log_data(lux);
        } else {
            fprintf(stderr, "Failed to read lux value\n");
        }

        // Wait for the next sample
        gpioDelay(config.sample_interval_ms);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(config.i2c_bus, config.bh1750_address, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        return 1;
    }
    return 0;
}

// Read lux value from BH1750 sensor
int read_bh1750(float *lux) {
    char buf[2];
    int raw_value;

    // Send measurement command (High Resolution Mode)
    if (i2cWriteByte(i2c_handle, 0x20) != 0) {
        fprintf(stderr, "Failed to write measurement command\n");
        return 1;
    }

    // Wait for measurement to complete (at least 120 ms)
    gpioDelay(120);

    // Read 2 bytes of data
    if (i2cReadDevice(i2c_handle, buf, 2) != 2) {
        fprintf(stderr, "Failed to read data from sensor\n");
        return 1;
    }

    // Convert to lux
    raw_value = (buf[0] << 8) | buf[1];
    *lux = (float)raw_value / 1.2;

    return 0;
}

// Control the relay
void control_relay(int state) {
    gpioWrite(config.grow_light_gpio, state);
}

// Log data to file
void log_data(float lux) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp) - 1, "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s, %.2f\n", timestamp, lux);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Signal handler
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Cleanup resources
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioWrite(config.grow_light_gpio, 0); // Turn off relay on exit
    gpioTerminate();
}

