    if (initialize_gpio() < 0) {
        syslog(LOG_ERR, "GPIO initialization failed, exiting");
        closelog();
        return EXIT_FAILURE;
    }

    // Initialize I2C
    if (initialize_i2c() < 0) {
        syslog(LOG_ERR, "I2C initialization failed, exiting");
        cleanup_gpio();
        closelog();
        return EXIT_FAILURE;
    }

    // Tare the load cells
    syslog(LOG_INFO, "Taring load cells...");
    for (i = 0; i < TARE_READINGS; i++) {
        for (j = 0; j < 3; j++) {
            raw_values[j][i] = read_hx711((j == 0) ? HX711_DOUT_1 : ((j == 1) ? HX711_DOUT_2 : HX711_DOUT_3), (j == 0) ? HX711_SCK_1 : ((j == 1) ? HX711_SCK_2 : HX711_SCK_3));
            if (raw_values[j][i] < 0) {
                syslog(LOG_ERR, "Error reading HX711 %d during tare", j + 1);
                tare_offset = 0.0f; // Reset tare offset on error
                break;
            }
        }
        if (raw_values[0][i] < 0) break; // Exit tare loop on error
        usleep(10000); // 10 ms delay
    }

    if (raw_values[0][0] >= 0) {
        tare_offset = 0.0f;
        for (i = 0; i < TARE_READINGS; i++) {
            tare_offset += raw_values[0][i];
        }
        tare_offset /= TARE_READINGS;
        syslog(LOG_INFO, "Tare offset: %.2f", tare_offset);
    } else {
        syslog(LOG_ERR, "Tare failed, using default offset of 0.0");
    }

    // Main loop
    while (keep_running) {
        // Read weight from each load cell
        float total_weight = 0.0f;
        for (i = 0; i < 3; i++) {
            int sum = 0;
            for (j = 0; j < NUM_HX711_READINGS; j++) {
                raw_values[i][j] = read_hx711((i == 0) ? HX711_DOUT_1 : ((i == 1) ? HX711_DOUT_2 : HX711_DOUT_3), (i == 0) ? HX711_SCK_1 : ((i == 1) ? HX711_SCK_2 : HX711_SCK_3));
                if (raw_values[i][j] < 0) {
                    syslog(LOG_ERR, "Error reading HX711 %d", i + 1);
                    raw_values[i][j] = 0; // Set to 0 to avoid affecting average
                }
                sum += raw_values[i][j];
            }
            total_weight += calculate_weight(sum, tare_offset, scale);
        }

        // Read temperature
        temperature = read_temperature(i2c_fd);
        if (temperature < 0) {
            syslog(LOG_ERR, "Error reading temperature, using default value of 25.0");
            temperature = 25.0f;
        }

        // Control solenoid
        if (total_weight > threshold) {
            if (!solenoid_state) {
                syslog(LOG_INFO, "Weight above threshold, activating solenoid");
                if (control_solenoid(SOLENOID_PIN, 1) < 0) {
                    syslog(LOG_ERR, "Error activating solenoid");
                }
                solenoid_state = 1;
                usleep(duration * 1000); // Convert ms to us
                if (control_solenoid(SOLENOID_PIN, 0) < 0) {
                    syslog(LOG_ERR, "Error deactivating solenoid");
                }
                solenoid_state = 0;
            }
        }

        // Send data
        if (send_data(SENSOR_ID, total_weight, temperature) < 0) {
            syslog(LOG_ERR, "Error sending data");
        }

        syslog(LOG_INFO, "Weight: %.2f grams, Temperature: %.2f C", total_weight, temperature);

        usleep(500000); // 500 ms delay
    }

    // Cleanup
    syslog(LOG_INFO, "Cleaning up...");
    cleanup_gpio();
    cleanup_i2c();
    closelog();

    return EXIT_SUCCESS;
}

