#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <syslog.h>
#include <unistd.h>
#include <mosquitto.h>
#include <pigpio.h>

#define MQTT_BROKER "localhost"
#define MQTT_PORT 1883
#define MQTT_TOPIC "home/lights/control"
#define GPIO_PIN 17
#define RETRY_DELAY 5 // seconds

// Global variables
struct mosquitto *mosq = NULL;
int running = 1;

// Function prototypes
void signal_handler(int signum);
void connect_callback(struct mosquitto *mosq, void *userdata, int result);
void disconnect_callback(struct mosquitto *mosq, void *userdata, int rc);
void message_callback(struct mosquitto *mosq, void *userdata, const struct mosquitto_message *message);
int set_relay_state(int state);

// Signal handler for graceful shutdown
void signal_handler(int signum) {
    syslog(LOG_INFO, "Signal received, exiting...");
    running = 0;
}

// Callback function for successful MQTT connection
void connect_callback(struct mosquitto *mosq, void *userdata, int result) {
    if (result == MOSQ_ERR_SUCCESS) {
        syslog(LOG_INFO, "MQTT connected to %s:%d", MQTT_BROKER, MQTT_PORT);
        int subscribe_result = mosquitto_subscribe(mosq, NULL, MQTT_TOPIC, 0);
        if (subscribe_result != MOSQ_ERR_SUCCESS) {
            syslog(LOG_ERR, "Failed to subscribe to topic: %s", mosquitto_strerror(subscribe_result));
        }
    } else {
        syslog(LOG_ERR, "MQTT connection error: %s", mosquitto_connack_string(result));
    }
}

// Callback function for MQTT disconnection
void disconnect_callback(struct mosquitto *mosq, void *userdata, int rc) {
    syslog(LOG_INFO, "MQTT disconnected with code %d", rc);
}

// Callback function for received MQTT messages
void message_callback(struct mosquitto *mosq, void *userdata, const struct mosquitto_message *message) {
    syslog(LOG_INFO, "Received message on topic %s: %s", message->topic, (char *)message->payload);

    if (strcmp((char *)message->payload, "ON") == 0) {
        if (set_relay_state(1) != 0) {
            syslog(LOG_ERR, "Failed to set relay state to ON");
        }
    } else if (strcmp((char *)message->payload, "OFF") == 0) {
        if (set_relay_state(0) != 0) {
            syslog(LOG_ERR, "Failed to set relay state to OFF");
        }
    } else {
        syslog(LOG_ERR, "Invalid payload received: %s", (char *)message->payload);
    }
}

// Function to set the relay state using pigpio
int set_relay_state(int state) {
    if (gpioWrite(GPIO_PIN, state) != 0) {
        syslog(LOG_ERR, "Failed to write to GPIO %d", GPIO_PIN);
        return -1;
    }
    syslog(LOG_INFO, "Relay set to %s", state ? "ON" : "OFF");
    return 0;
}

int main() {
    // Initialize syslog
    openlog("relay_controller", LOG_PID | LOG_CONS, LOG_USER);

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        closelog();
        return 1;
    }

    // Set GPIO17 as an output and initialize to LOW (OFF)
    gpioSetMode(GPIO_PIN, PI_OUTPUT);
    gpioWrite(GPIO_PIN, 0);
    syslog(LOG_INFO, "GPIO %d initialized as output, initially OFF", GPIO_PIN);

    // Initialize libmosquitto
    mosquitto_lib_init();

    // Create a new mosquitto client instance
    mosq = mosquitto_new(NULL, true, NULL);
    if (!mosq) {
        syslog(LOG_ERR, "Failed to create mosquitto client instance");
        gpioTerminate();
        mosquitto_lib_cleanup();
        closelog();
        return 1;
    }

    // Set callback functions
    mosquitto_connect_callback_set(mosq, connect_callback);
    mosquitto_disconnect_callback_set(mosq, disconnect_callback);
    mosquitto_message_callback_set(mosq, message_callback);

    // Connect to the MQTT broker
    int connect_result = mosquitto_connect(mosq, MQTT_BROKER, MQTT_PORT, 60);
    if (connect_result != MOSQ_ERR_SUCCESS) {
        syslog(LOG_ERR, "Failed to connect to MQTT broker: %s", mosquitto_strerror(connect_result));
        mosquitto_destroy(mosq);
        mosquitto_lib_cleanup();
        gpioTerminate();
        closelog();
        return 1;
    }

    // Run the MQTT loop
    while (running) {
        int loop_result = mosquitto_loop(mosq, -1, 1); // -1 means loop forever, 1 means max 1 message processed per loop
        if (loop_result != MOSQ_ERR_SUCCESS) {
            syslog(LOG_ERR, "MQTT loop error: %s", mosquitto_strerror(loop_result));
            mosquitto_destroy(mosq);
            mosquitto_lib_cleanup();
            sleep(RETRY_DELAY);
            mosq = mosquitto_new(NULL, true, NULL);
            mosquitto_connect_callback_set(mosq, connect_callback);
            mosquitto_disconnect_callback_set(mosq, disconnect_callback);
            mosquitto_message_callback_set(mosq, message_callback);
            connect_result = mosquitto_connect(mosq, MQTT_BROKER, MQTT_PORT, 60);
            if (connect_result != MOSQ_ERR_SUCCESS) {
                syslog(LOG_ERR, "Failed to reconnect to MQTT broker: %s", mosquitto_strerror(connect_result));
                sleep(RETRY_DELAY);
                continue; // Skip the rest of the loop and retry connecting
            }
        }
    }

    // Cleanup
    mosquitto_disconnect(mosq);
    mosquitto_destroy(mosq);
    mosquitto_lib_cleanup();
    gpioWrite(GPIO_PIN, 0); // Ensure relay is OFF on exit
    gpioTerminate();
    closelog();

    return 0;
}

