// Define GPIO pins for the servos
#define SERVO1_PIN 7
#define SERVO2_PIN 8
#define SERVO3_PIN 9
#define SERVO4_PIN 10
#define SERVO5_PIN 11

// Define target pulse widths for each servo
#define SERVO1_WIDTH 1000
#define SERVO2_WIDTH 1500
#define SERVO3_WIDTH 2000
#define SERVO4_WIDTH 500
#define SERVO5_WIDTH 2500

// Function to set the pulse width for a servo
void set_servo_position(int pin, int pulse_width) {
    gpioServo(pin, pulse_width);
}

int main() {
    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1; // Exit with an error code
    }

    // Set the PWM frequency to 50 Hz (20 ms period)
    gpioSetPWMfrequency(SERVO1_PIN, 50);
    gpioSetPWMfrequency(SERVO2_PIN, 50);
    gpioSetPWMfrequency(SERVO3_PIN, 50);
    gpioSetPWMfrequency(SERVO4_PIN, 50);
    gpioSetPWMfrequency(SERVO5_PIN, 50);

    // Set the PWM range to 20000 (100% duty cycle)
    gpioSetPWMrange(SERVO1_PIN, 20000);
    gpioSetPWMrange(SERVO2_PIN, 20000);
    gpioSetPWMrange(SERVO3_PIN, 20000);
    gpioSetPWMrange(SERVO4_PIN, 20000);
    gpioSetPWMrange(SERVO5_PIN, 20000);

    // Set the pulse widths for each servo
    set_servo_position(SERVO1_PIN, SERVO1_WIDTH);
    set_servo_position(SERVO2_PIN, SERVO2_WIDTH);
    set_servo_position(SERVO3_PIN, SERVO3_WIDTH);
    set_servo_position(SERVO4_PIN, SERVO4_WIDTH);
    set_servo_position(SERVO5_PIN, SERVO5_WIDTH);

    // Wait for 3 seconds
    sleep(3);

    // Stop the PWM signals
    gpioServo(SERVO1_PIN, 0);
    gpioServo(SERVO2_PIN, 0);
    gpioServo(SERVO3_PIN, 0);
    gpioServo(SERVO4_PIN, 0);
    gpioServo(SERVO5_PIN, 0);

    // Release the pigpio library resources
    gpioTerminate();

    printf("Servo control program finished\n");
    return 0; // Exit successfully
}

