#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <pthread.h>
#include <time.h>
#include <math.h>

// Motor A
#define MOTOR_A_IN1 17
#define MOTOR_A_IN2 18
#define ENCODER_A_A 4
#define ENCODER_A_B 5

// Motor B
#define MOTOR_B_IN3 22
#define MOTOR_B_IN4 23
#define ENCODER_B_A 6
#define ENCODER_B_B 12

// PI Controller Gains
#define Kp 0.5
#define Ki 0.05

// Target Speed (RPM)
#define TARGET_SPEED 50.0

// PWM Frequency (Hz)
#define PWM_FREQUENCY 10000

// Stall Detection Timeout (seconds)
#define STALL_TIMEOUT 2

// Global Variables
volatile int encoder_a_count = 0;
volatile int encoder_b_count = 0;
double integral_a = 0.0;
double integral_b = 0.0;
double last_error_a = 0.0;
double last_error_b = 0.0;
int running = 1;

// Mutex for Encoder Counts
pthread_mutex_t encoder_mutex = PTHREAD_MUTEX_INITIALIZER;

// Function Prototypes
void encoder_a_isr(int gpio, int level, uint32_t tick, void *user);
void encoder_b_isr(int gpio, int level, uint32_t tick, void *user);
double calculate_rpm(int encoder_count);
double pi_controller(double setpoint, double actual_speed, double *integral, double *last_error, double Kp, double Ki);
void set_motor_speed(int motor_a_pwm, int motor_b_pwm);
void *control_loop(void *arg);
void signal_handler(int signal);

// Encoder A ISR
void encoder_a_isr(int gpio, int level, uint32_t tick, void *user)
{
    static uint32_t last_tick_a = 0;
    uint32_t current_tick = tick;
    int a_phase, b_phase;

    a_phase = gpioRead(ENCODER_A_A);
    b_phase = gpioRead(ENCODER_A_B);

    if (level == RISING_EDGE)
    {
        pthread_mutex_lock(&encoder_mutex);
        if (a_phase == b_phase)
        {
            encoder_a_count++;
        }
        else
        {
            encoder_a_count--;
        }
        pthread_mutex_unlock(&encoder_mutex);
    }
}

// Encoder B ISR
void encoder_b_isr(int gpio, int level, uint32_t tick, void *user)
{
    static uint32_t last_tick_b = 0;
    uint32_t current_tick = tick;
    int a_phase, b_phase;

    a_phase = gpioRead(ENCODER_B_A);
    b_phase = gpioRead(ENCODER_B_B);

    if (level == RISING_EDGE)
    {
        pthread_mutex_lock(&encoder_mutex);
        if (a_phase == b_phase)
        {
            encoder_b_count++;
        }
        else
        {
            encoder_b_count--;
        }
        pthread_mutex_unlock(&encoder_mutex);
    }
}

// Calculate RPM
double calculate_rpm(int encoder_count)
{
    return (double)encoder_count * 60.0 / 64.0;
}

// PI Controller
double pi_controller(double setpoint, double actual_speed, double *integral, double *last_error, double Kp, double Ki)
{
    double error = setpoint - actual_speed;
    double proportional = Kp * error;
    *integral += Ki * error;

    // Anti-windup clamping
    double integral_max = 255.0; // Maximum PWM duty cycle
    double integral_min = 0.0;
    if (*integral > integral_max)
    {
        *integral = integral_max;
    }
    else if (*integral < integral_min)
    {
        *integral = integral_min;
    }

    double output = proportional + *integral;
    *last_error = error;
    return output;
}

// Set Motor Speed
void set_motor_speed(int motor_a_pwm, int motor_b_pwm)
{
    gpioPWM(MOTOR_A_IN1, motor_a_pwm);
    gpioWrite(MOTOR_A_IN2, 0); // Ensure direction is set correctly
    gpioPWM(MOTOR_B_IN3, motor_b_pwm);
    gpioWrite(MOTOR_B_IN4, 0); // Ensure direction is set correctly
}

// Control Loop
void *control_loop(void *arg)
{
    struct timespec sleep_time;
    sleep_time.tv_sec = 0;
    sleep_time.tv_nsec = 100000000; // 100 ms

    while (running)
    {
        pthread_mutex_lock(&encoder_mutex);
        int encoder_a_count_local = encoder_a_count;
        int encoder_b_count_local = encoder_b_count;
        pthread_mutex_unlock(&encoder_mutex);

        double rpm_a = calculate_rpm(encoder_a_count_local);
        double rpm_b = calculate_rpm(encoder_b_count_local);

        double output_a = pi_controller(TARGET_SPEED, rpm_a, &integral_a, &last_error_a, Kp, Ki);
        double output_b = pi_controller(TARGET_SPEED, rpm_b, &integral_b, &last_error_b, Kp, Ki);

        // Clamp PWM duty cycle
        int pwm_a = (int)output_a;
        int pwm_b = (int)output_b;
        if (pwm_a > 255) pwm_a = 255;
        if (pwm_a < 0) pwm_a = 0;
        if (pwm_b > 255) pwm_b = 255;
        if (pwm_b < 0) pwm_b = 0;

        set_motor_speed(pwm_a, pwm_b);

        printf("Motor A: RPM = %.2f, PWM = %d\n", rpm_a, pwm_a);
        printf("Motor B: RPM = %.2f, PWM = %d\n", rpm_b, pwm_b);

        if (rpm_a == 0.0 && rpm_b == 0.0)
        {
