#define TARGET_SPEED 50.0

// PWM Frequency (Hz)
#define PWM_FREQUENCY 10000

// Stall Detection Timeout (seconds)
#define STALL_TIMEOUT 2

// Global Variables
volatile int encoder_a_count = 0;
volatile int encoder_b_count = 0;
double integral_a = 0.0;
double integral_b = 0.0;
double last_error_a = 0.0;
double last_error_b = 0.0;
int running = 1;

// Mutex for Encoder Counts
pthread_mutex_t encoder_mutex = PTHREAD_MUTEX_INITIALIZER;

// Function Prototypes
void encoder_a_isr(int gpio, int level, uint32_t tick, void *user);
void encoder_b_isr(int gpio, int level, uint32_t tick, void *user);
double calculate_rpm(int encoder_count);
double pi_controller(double setpoint, double actual_speed, double *integral, double *last_error, double Kp, double Ki);
void set_motor_speed(int motor_a_pwm, int motor_b_pwm);
void *control_loop(void *arg);
void signal_handler(int signal);

// Encoder A ISR
void encoder_a_isr(int gpio, int level, uint32_t tick, void *user)
{
    static uint32_t last_tick_a = 0;
    uint32_t current_tick = tick;
    int a_phase, b_phase;

    a_phase = gpioRead(ENCODER_A_A);
    b_phase = gpioRead(ENCODER_A_B);

    if (level == RISING_EDGE)
    {
        pthread_mutex_lock(&encoder_mutex);
        if (a_phase == b_phase)
        {
            encoder_a_count++;
        }
        else
        {
            encoder_a_count--;
        }
        pthread_mutex_unlock(&encoder_mutex);
    }
}

// Encoder B ISR
void encoder_b_isr(int gpio, int level, uint32_t tick, void *user)
{
    static uint32_t last_tick_b = 0;
    uint32_t current_tick = tick;
    int a_phase, b_phase;

    a_phase = gpioRead(ENCODER_B_A);
    b_phase = gpioRead(ENCODER_B_B);

    if (level == RISING_EDGE)
