#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// Constants
#define RELAY_GPIO 17
#define BH1750_ADDR 0x23
#define I2C_BUS 1
#define LUX_THRESHOLD_DUSK 50
#define LUX_THRESHOLD_DAWN 200
#define LUX_HYSTERESIS 10
#define LOG_FILE "chicken_coop_log.txt"
#define BH1750_START_MEASUREMENT 0x21
#define BH1750_ONE_TIME_HIGH_RES_MODE 0x10

// Global variables
static volatile int running = 1;
static int i2c_handle;
static FILE *log_file;

// Function prototypes
int initialize_pigpio();
int initialize_i2c();
int read_bh1750(int i2c_handle, float *lux);
int control_relay(int gpio_pin, int state);
int log_data(FILE *log_file, float lux, int relay_state);
void signal_handler(int signal);
void cleanup();

// Function to initialize pigpio
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Function to initialize I2C
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, BH1750_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to read lux value from BH1750 sensor
int read_bh1750(int i2c_handle, float *lux) {
    char buf[2];
    int result;

    // Send start measurement command
    result = i2cWriteByteData(i2c_handle, BH1750_START_MEASUREMENT, BH1750_ONE_TIME_HIGH_RES_MODE);
    if (result < 0) {
        fprintf(stderr, "Failed to send start measurement command: %d\n", result);
        return -1;
    }

    // Wait for measurement to complete (at least 180ms)
    gpioDelay(180000); // 180ms

    // Read 2 bytes of lux data
    result = i2cReadDevice(i2c_handle, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Failed to read lux data: %d\n", result);
        return -1;
    }

    // Convert raw data to lux
    unsigned int raw_value = (buf[0] << 8) | buf[1];
    *lux = (float)raw_value / 1.2;

    return 0;
}

// Function to control the relay
int control_relay(int gpio_pin, int state) {
    gpioWrite(gpio_pin, state);
    return 0;
}

// Function to log data to file
int log_data(FILE *log_file, float lux, int relay_state) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(log_file, "%s: Lux = %.2f, Relay = %s\n", timestamp, lux, relay_state ? "ON" : "OFF");
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

// Cleanup function to release resources
void cleanup() {
    printf("Cleaning up resources...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioWrite(RELAY_GPIO, 0); // Turn off relay
    gpioSetMode(RELAY_GPIO, PI_INPUT); // Set GPIO back to input
    gpioTerminate();
    if (log_file != NULL) {
        fclose(log_file);
    }
    printf("Cleanup complete.\n");
}

int main() {
    float lux;
    int relay_state = 0; // 0 = OFF, 1 = ON
    int prev_relay_state = 0;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (initialize_pigpio() != 0) {
        return 1;
    }

    // Initialize I2C
    if (initialize_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Set relay GPIO as output
    gpioSetMode(RELAY_GPIO, PI_OUTPUT);

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup();
        return 1;
    }

    printf("Smart Chicken Coop Lighting System started.\n");

    while (running) {
        // Read lux value
        if (read_bh1750(i2c_handle, &lux) == 0) {
            printf("Lux: %.2f\n", lux);

            // Control relay based on lux value and hysteresis
            if (lux < LUX_THRESHOLD_DUSK && relay_state == 0) {
                control_relay(RELAY_GPIO, 1);
                relay_state = 1;
                printf("Turning relay ON\n");
            } else if (lux > LUX_THRESHOLD_DAWN && relay_state == 1) {
                control_relay(RELAY_GPIO, 0);
                relay_state = 0;
                printf("Turning relay OFF\n");
            }

            // Log data
            log_data(log_file, lux, relay_state);

            // Update previous relay state
            prev_relay_state = relay_state;
        } else {
            fprintf(stderr, "Failed to read lux value\n");
            log_data(log_file, -1.0, 0); // Log error
        }

        // Wait 5 seconds
        gpioDelay(5000000); // 5 seconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

