#include <time.h>
#include <pigpio.h>
#include <pthread.h>
#include <string.h>

// Constants
#define FLOW_SENSOR_GPIO 17
#define SOLENOID_GPIO 27
#define PULSES_PER_LITER 450.0
#define DEBOUNCE_TIMEOUT 1000 // milliseconds
#define LOG_FILE "water_flow.log"

// Global variables
volatile int pulse_count = 0;
volatile unsigned long last_pulse_time = 0;
pthread_mutex_t pulse_mutex = PTHREAD_MUTEX_INITIALIZER;
FILE *log_file = NULL;

// Function prototypes
void pulse_callback(int gpio, int level, unsigned int tick, void *user_data);
double calculate_lpm(int pulses);
void control_solenoid(double lpm);
void log_data(double lpm, int solenoid_state);
void signal_handler(int signal);
int initialize();
void cleanup();

// Pulse callback function
void pulse_callback(int gpio, int level, unsigned int tick, void *user_data) {
    unsigned long current_time = gpioTick();

    if (level == PI_HIGH) {
        pthread_mutex_lock(&pulse_mutex);
        pulse_count++;
        pthread_mutex_unlock(&pulse_mutex);
        last_pulse_time = current_time;
    } else if (level == PI_LOW) {
        // Ignore falling edge
        return;
    }
}

// Calculate LPM
double calculate_lpm(int pulses) {
    return (double)pulses / PULSES_PER_LITER * 60.0;
}

// Control solenoid valve
void control_solenoid(double lpm) {
    static int solenoid_state = 1; // Initially open

    if (lpm > 5.0 && solenoid_state == 1) {
        gpioWrite(SOLENOID_GPIO, 0); // Close solenoid
        solenoid_state = 0;
        log_data(lpm, 0);
    } else if (lpm < 4.5 && solenoid_state == 0) {
        gpioWrite(SOLENOID_GPIO, 1); // Open solenoid
        solenoid_state = 1;
        log_data(lpm, 1);
    }
}

// Log data to file
void log_data(double lpm, int solenoid_state) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s, LPM: %.2f, Solenoid: %s\n", timestamp, lpm, solenoid_state ? "OPEN" : "CLOSED");
        fflush(log_file); // Ensure data is written to disk
    } else {
        fprintf(stderr, "Error: Log file not opened.\n");
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    log_data(0.0, 1); // Ensure solenoid is open on exit
    if (log_file != NULL) {
        fclose(log_file);
    }
    pthread_mutex_destroy(&pulse_mutex);
    gpioTerminate();
    exit(0);
}

// Initialization function
int initialize() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(FLOW_SENSOR_GPIO, PI_INPUT);
    gpioSetMode(SOLENOID_GPIO, PI_OUTPUT);
    gpioWrite(SOLENOID_GPIO, 1); // Initialize solenoid to open state

    // Set up interrupt with debounce
    if (gpioSetISRFuncEx(FLOW_SENSOR_GPIO, RISING_EDGE, DEBOUNCE_TIMEOUT, pulse_callback, NULL) != 0) {
        fprintf(stderr, "Failed to set ISR function\n");
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        gpioTerminate();
        return 1;
    }

    return 0;
}

// Cleanup function
void cleanup() {
    gpioWrite(SOLENOID_GPIO, 1); // Ensure solenoid is open
    if (log_file != NULL) {
        fclose(log_file);
    }
    pthread_mutex_destroy(&pulse_mutex);
    gpioTerminate();
}

int main() {
    if (initialize()) {
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (1) {
        pthread_mutex_lock(&pulse_mutex);
        int current_pulse_count = pulse_count;
        pulse_count = 0; // Reset pulse count
        pthread_mutex_unlock(&pulse_mutex);

        double lpm = calculate_lpm(current_pulse_count);
        printf("LPM: %.2f\n", lpm);
        log_data(lpm, gpioRead(SOLENOID_GPIO));
        control_solenoid(lpm);

        gpioDelay(1000); // Sample every 1 second
    }

    return 0;
}

