#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pigpio.h>

// Configuration structure
typedef struct {
    char server_ip[20];
    int server_port;
    float calibration_factor;
} Config;

// Global variables
int data_pin = 23;
int clock_pin = 24;
int servo_pin = 18;
int server_fd, new_socket;
Config config;

// Function prototypes
int read_hx711();
float calibrate_hx711(int raw_value, float calibration_factor);
int control_servo(int pulse_width);
int dispense_ingredient(float target_weight, float calibration_factor);
void log_dispensing_event(float target_weight, float actual_weight, const char *error_message);
int load_config(const char *filename, Config *config);
void signal_handler(int signum);

// HX711 read function with timeout
int read_hx711() {
    int count = 0;
    int data = 0;

    gpioSetMode(data_pin, PI_INPUT);
    gpioSetMode(clock_pin, PI_OUTPUT);

    // Wait for DATA pin to go low
    while (gpioRead(data_pin) == 1 && count < 1000) {
        gpioDelay(1); // 1 µs delay
        count++;
    }

    if (count >= 1000) {
        fprintf(stderr, "Error: HX711 timeout waiting for DATA pin to go low.\n");
        log_dispensing_event(0.0, 0.0, "HX711 timeout waiting for DATA pin to go low.");
        return -1; // Indicate timeout error
    }

    count = 0;
    while (count < 24) {
        gpioWrite(clock_pin, 1);
        gpioDelay(1); // 1 µs clock pulse
        data = data << 1;
        if (gpioRead(data_pin)) {
            data++;
        }
        gpioWrite(clock_pin, 0);
        gpioDelay(1); // 1 µs clock pulse
        count++;
    }

    // 25th pulse for gain setting (channel A, gain 128)
    gpioWrite(clock_pin, 1);
    gpioDelay(1); // 1 µs clock pulse
    gpioWrite(clock_pin, 0);
    gpioDelay(1); // 1 µs clock pulse

    // Convert to signed 2's complement
    if (data & 0x800000) {
        data |= 0xFF000000;
    }

    return data;
}

// HX711 calibration function
float calibrate_hx711(int raw_value, float calibration_factor) {
    return (float)raw_value / calibration_factor;
}

// Servo control function
int control_servo(int pulse_width) {
    if (pulse_width < 1000 || pulse_width > 2000) {
        fprintf(stderr, "Error: Invalid pulse width. Must be between 1000 and 2000.\n");
        log_dispensing_event(0.0, 0.0, "Invalid pulse width.");
        return -1;
    }

    gpioServo(servo_pin, pulse_width);
    return 0;
}

// Dispensing logic function
int dispense_ingredient(float target_weight, float calibration_factor) {
    int raw_value = read_hx711();
    if (raw_value == -1) {
        return -1; // HX711 read error
    }

    float actual_weight = calibrate_hx711(raw_value, calibration_factor);

    // Map target weight to pulse width (example mapping)
    int pulse_width = 1000 + (int)((target_weight / 100.0) * 1000.0); // Example: 0g -> 1000us, 100g -> 2000us

    if (control_servo(pulse_width) != 0) {
        return -1; // Servo control error
    }

    gpioDelay(1000); // Wait 1 second

    return (int)actual_weight;
}

// Logging function
void log_dispensing_event(float target_weight, float actual_weight, const char *error_message) {
    FILE *fp = fopen("dispensing_log.json", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not open dispensing_log.json for writing.\n");
        return;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "{\"timestamp\": \"%s\", \"target_weight\": %.2f, \"actual_weight\": %.2f, \"error_message\": \"%s\"}\n",
            timestamp, target_weight, actual_weight, error_message);

    fclose(fp);
}

// Configuration loading function
int load_config(const char *filename, Config *config) {
    FILE *fp = fopen(filename, "r");
    if (fp == NULL) {
        fprintf(stderr, "Warning: Could not open config.ini. Using default values.\n");
        config->server_ip[0] = '\0'; // Empty string
        config->server_port = 12345;
        config->calibration_factor = 1.0;
        return -1;
    }

    char line[256];
    while (fgets(line, sizeof(line), fp)) {
        if (strncmp(line, "server_ip", 9) == 0) {
            sscanf(line, "server_ip = %s", config->server_ip);
        } else if (strncmp(line, "server_port", 11) == 0) {
            sscanf(line, "server_port = %d", &config->server_port);
        } else if (strncmp(line, "calibration_factor", 16) == 0) {
            sscanf(line, "calibration_factor = %f", &config->calibration_factor);
        }
    }

    fclose(fp);
    return 0;
}

// Signal handler function
void signal_handler(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        printf("Received signal %d, shutting down...\n", signum);

        // Stop servo
        gpioServo(servo_pin, 0);

        // Close socket
        if (new_socket > 0) {
            close(new_socket);
        }
        if (server_fd > 0) {
            close(server_fd);
        }

        // Terminate pigpio
        gpioTerminate();

        exit(0);
    }
}

int main() {
    // Load configuration
    if (load_config("config.ini", &config) != 0) {
        fprintf(stderr, "Using default configuration values.\n");
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return 1;
    }

    // Set servo pin as output
    gpioSetMode(servo_pin, PI_OUTPUT);

    // Set PWM range and frequency
    gpioSetPWMrange(servo_pin, 2000);
    gpioSetPWMfrequency(servo_pin, 50);

    // Set signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Create socket
    server_fd = socket(AF_INET, SOCK_STREAM, 0);
    if (server_fd == 0) {
        fprintf(stderr, "Error: Socket creation failed.\n");
        log_dispensing_event(0.0, 0.0, "Socket creation failed.");
        gpioTerminate();
        return 1;
    }

    // Bind socket to address and port
    struct sockaddr_in address;
    address.sin_family = AF_INET;
    address.sin_addr.s_addr = INADDR_ANY;
    address.sin_port = htons(config.server_port);

    if (bind(server_fd, (struct sockaddr *)&address, sizeof(address)) < 0) {
        fprintf(stderr, "Error: Bind failed.\n");
        log_dispensing_event(0.0, 0.0, "Bind failed.");
        close(server_fd);
        gpioTerminate();
        return 1;
    }

    // Listen for connections
    if (listen(server_fd, 3) < 0) {
        fprintf(stderr, "Error: Listen failed.\n");
        log_dispensing_event(0.0, 0.0, "Listen failed.");
        close(server_fd);
        gpioTerminate();
        return 1;
    }

    printf("Server listening on port %d...\n", config.server_port);

    // Accept connection
    int addrlen = sizeof(address);
    new_socket = accept(server_fd, (struct sockaddr *)&address, (socklen_t*)&addrlen);
    if (new_socket < 0) {
        fprintf(stderr, "Error: Accept failed.\n");
        log_dispensing_event(0.0, 0.0, "Accept failed.");
        close(server_fd);
        gpioTerminate();
        return 1;
    }

    printf("Connection accepted.\n");

    // Main loop
    while (1) {
        float target_weight;
        char buffer[1024] = {0};

        // Receive target weight from client
        ssize_t bytes_received = recv(new_socket, buffer, sizeof(buffer) - 1, 0);
        if (bytes_received < 0) {
            fprintf(stderr, "Error: Receive failed.\n");
            log_dispensing_event(0.0, 0.0, "Receive failed.");
            break;
        } else if (bytes_received == 0) {
            printf("Client disconnected.\n");
            break;
        }

        buffer[bytes_received] = '\0';
        if (sscanf(buffer, "%f", &target_weight) != 1) {
            fprintf(stderr, "Error: Invalid target weight received.\n");
            log_dispensing_event(0.0, 0.0, "Invalid target weight received.");
            continue;
        }

        printf("Target weight: %.2f grams\n", target_weight);

        // Dispense ingredient
        int actual_weight = dispense_ingredient(target_weight, config.calibration_factor);

        if (actual_weight == -1) {
            log_dispensing_event(target_weight, 0.0, "Dispensing failed.");
        } else {
            float actual_weight_float = (float)actual_weight;
            printf("Actual weight: %.2f grams\n", actual_weight_float);

            // Send actual weight back to client
            char response[50];
            snprintf(response, sizeof(response), "%.2f", actual_weight_float);
            send(new_socket, response, strlen(response), 0);
        }
    }

    // Clean up
    close(new_socket);
    close(server_fd);
    gpioTerminate();

    return 0;
}

