#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>
#include <string.h>

// Define GPIO pins
#define TOUCH_SENSOR_PIN 4
#define RELAY_PIN 17

// Default debounce time (50 ms)
#define DEFAULT_DEBOUNCE_TIME 50

// Global variables
static volatile int running = 1;
static volatile int relay_state = 0; // 0 = OFF, 1 = ON
static int debounce_time = DEFAULT_DEBOUNCE_TIME;

// Function prototypes
void signal_handler(int signal);
void log_relay_state();
int debounce();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);

    // Turn off the relay
    gpioWrite(RELAY_PIN, 0);
    relay_state = 0;
    log_relay_state();

    // Release pigpio resources
    gpioTerminate();

    exit(0);
}

// Function to log relay state with timestamp
void log_relay_state() {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (relay_state == 1) {
        printf("%s Relay: ON\n", timestamp);
    } else {
        printf("%s Relay: OFF\n", timestamp);
    }
}

// Debounce function
int debounce() {
    int i;
    int stable_count = 0;
    int current_state = gpioRead(TOUCH_SENSOR_PIN);

    for (i = 0; i < (debounce_time * 1000) / 1000; ++i) {
        if (gpioRead(TOUCH_SENSOR_PIN) == current_state) {
            stable_count++;
        }
        gpioDelay(1); // Delay for 1 ms
    }

    return (stable_count >= (debounce_time * 1000) / 1000);
}

int main(int argc, char *argv[]) {
    int opt;

    // Parse command-line arguments
    while ((opt = getopt(argc, argv, "d:")) != -1) {
        switch (opt) {
            case 'd':
                debounce_time = atoi(optarg);
                if (debounce_time <= 0) {
                    fprintf(stderr, "Invalid debounce time. Using default value (%d ms).\n", DEFAULT_DEBOUNCE_TIME);
                    debounce_time = DEFAULT_DEBOUNCE_TIME;
                }
                break;
            default:
                fprintf(stderr, "Usage: %s [-d debounce_time_ms]\n", argv[0]);
                return 1;
        }
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    if (gpioSetMode(TOUCH_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", TOUCH_SENSOR_PIN);
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(RELAY_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", RELAY_PIN);
        gpioTerminate();
        return 1;
    }

    // Set initial relay state to OFF
    gpioWrite(RELAY_PIN, 0);
    relay_state = 0;
    log_relay_state();

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Touch-controlled relay switch. Press Ctrl+C to exit.\n");
    printf("Debounce time: %d ms\n", debounce_time);

    // Main loop
    while (running) {
        if (gpioRead(TOUCH_SENSOR_PIN) == 1) {
            if (debounce()) {
                // Toggle relay state
                relay_state = !relay_state;
                gpioWrite(RELAY_PIN, relay_state);
                log_relay_state();
                gpioDelay(100); // Debounce delay after toggle
            }
        }
        gpioDelay(10); // Small delay to reduce CPU usage
    }

    return 0;
}

