#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <termios.h>
#include <pigpio.h>
#include <unistd.h>

#define GPIO_PIN 18
#define PWM_FREQUENCY 50
#define MIN_PULSE_WIDTH 500
#define MAX_PULSE_WIDTH 2500
#define INITIAL_ANGLE 90

volatile sig_atomic_t program_running = 1;

void signal_handler(int signal) {
    program_running = 0;
    fprintf(stderr, "\nCaught signal %d, stopping PWM and exiting.\n", signal);
}

int main() {
    int angle = INITIAL_ANGLE;
    int pulse_width;
    struct termios term;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO18 to PWM output mode
    gpioSetMode(GPIO_PIN, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(GPIO_PIN, PWM_FREQUENCY);

    // Set PWM range (optional, but recommended)
    gpioSetPWMrange(GPIO_PIN, 1000000 / PWM_FREQUENCY); // Set range to 20ms / PWM period

    // Install signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Configure terminal for raw input
    if (tcgetattr(STDIN_FILENO, &term) != 0) {
        perror("tcgetattr");
        gpioTerminate();
        return 1;
    }

    term.c_lflag &= ~(ICANON | ECHO);
    term.c_cc[VMIN] = 0;  // Non-blocking read
    term.c_cc[VTIME] = 0; // No timeout

    if (tcsetattr(STDIN_FILENO, TCSANOW, &term) != 0) {
        perror("tcsetattr");
        gpioTerminate();
        return 1;
    }

    printf("Servo control program. Press '+' to increase angle, '-' to decrease, 'q' to quit.\n");

    while (program_running) {
        int c = getchar();

        if (c == '+') {
            angle += 10;
            if (angle > 180) {
                angle = 180;
            }
        } else if (c == '-') {
            angle -= 10;
            if (angle < 0) {
                angle = 0;
            }
        } else if (c == 'q') {
            program_running = 0;
        } else if (c != -1) {
            // Ignore other characters
            continue;
        }

        // Calculate pulse width
        pulse_width = (int)(MIN_PULSE_WIDTH + (angle / 180.0) * (MAX_PULSE_WIDTH - MIN_PULSE_WIDTH));

        // Set servo pulse width
        gpioServo(GPIO_PIN, pulse_width);

        // Print current angle
        printf("Current angle: %d degrees\n", angle);
    }

    // Stop PWM pulses
    gpioServo(GPIO_PIN, 0);

    // Restore terminal settings
    if (tcsetattr(STDIN_FILENO, TCSANOW, &term) != 0) {
        perror("tcsetattr");
    }

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

