#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <gpiod.h>

#define GPIO_CHIP_NAME "gpiochip0"
#define GPIO_PIN 17
#define DEBOUNCE_DELAY_NS 2000000 // 2 ms
#define LOG_FILE "motor_rpm.log"

static volatile int keep_running = 1;
static struct gpiod_chip *gpio_chip = NULL;
static struct gpiod_line *gpio_line = NULL;
static FILE *log_file = NULL;

// Function to handle signals (SIGINT, SIGTERM)
void signal_handler(int sig) {
    fprintf(stderr, "\nCaught signal %d, exiting gracefully.\n", sig);
    keep_running = 0;
}

// Function to initialize the GPIO line
int init_gpio(struct gpiod_chip **chip, struct gpiod_line **line) {
    int ret;

    *chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!*chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", GPIO_CHIP_NAME);
        return -1;
    }

    *line = gpiod_chip_get_line(*chip, GPIO_PIN);
    if (!*line) {
        fprintf(stderr, "Error getting GPIO line %d\n", GPIO_PIN);
        gpiod_chip_close(*chip);
        return -1;
    }

    ret = gpiod_line_request_input_flags(*line, "motor_rpm", GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_UP);
    if (ret < 0) {
        fprintf(stderr, "Error requesting GPIO line as input: %s\n", strerror(-ret));
        gpiod_chip_close(*chip);
        gpiod_line_release(*line);
        return -1;
    }

    return 0;
}

// Function to close the GPIO line and chip
void cleanup_gpio(struct gpiod_chip *chip, struct gpiod_line *line) {
    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
}

// Function to initialize the log file
int init_log_file(FILE **file) {
    *file = fopen(LOG_FILE, "a");
    if (!*file) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        return -1;
    }
    return 0;
}

// Function to close the log file
void cleanup_log_file(FILE *file) {
    if (file) {
        fflush(file);
        fclose(file);
    }
}

// Function to get the current timestamp in ISO 8601 format
void get_iso8601_timestamp(char *timestamp) {
    time_t rawtime;
    struct tm *info;
    time(&rawtime);
    info = gmtime(&rawtime);
    strftime(timestamp, 30, "%Y-%m-%dT%H:%M:%SZ", info);
}

// Function to log the RPM data to the file
void log_rpm_data(FILE *file, const char *timestamp, double rpm) {
    fprintf(file, "%s,%.2f\n", timestamp, rpm);
    fflush(file);
}

// Function to print the RPM to stdout
void print_rpm(double rpm) {
    printf("RPM: %.2f\n", rpm);
}

// Function to calculate RPM
double calculate_rpm(int pulse_count) {
    return (pulse_count / 5.0) * 60.0;
}

// Function to handle the rising edge event
void rising_edge_handler(int gpio, int value, uint32_t timestamp, void *user_data) {
    // Debounce delay
    struct timespec delay = {0, DEBOUNCE_DELAY_NS};
    nanosleep(&delay, NULL);

    // Increment the pulse count
    static int pulse_count = 0;
    pulse_count++;
}

int main() {
    int ret;
    struct gpiod_line_event_request *event_request = NULL;
    struct timespec start_time, current_time;
    double elapsed_time;
    char timestamp[30];
    int pulse_count = 0;

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (init_gpio(&gpio_chip, &gpio_line) != 0) {
        return 1;
    }

    // Initialize log file
    if (init_log_file(&log_file) != 0) {
        cleanup_gpio(gpio_chip, gpio_line);
        return 1;
    }

    // Create event request for rising edge detection
    event_request = gpiod_line_event_request(gpio_line, "motor_rpm_event", 0, (gpiod_line_event_handler_t)rising_edge_handler, NULL);
    if (!event_request) {
        fprintf(stderr, "Error creating event request: %s\n", strerror(errno));
        cleanup_gpio(gpio_chip, gpio_line);
        cleanup_log_file(log_file);
        return 1;
    }

    // Start the main loop
    while (keep_running) {
        // Record the start time
        clock_gettime(CLOCK_MONOTONIC, &start_time);

        // Wait for 5 seconds
        sleep(5);

        // Record the current time
        clock_gettime(CLOCK_MONOTONIC, &current_time);

        // Calculate the elapsed time
        elapsed_time = (current_time.tv_sec - start_time.tv_sec) + (current_time.tv_nsec - start_time.tv_nsec) / 1000000000.0;

