#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

// Define GPIO pins
#define TOUCH_SENSOR_PIN 4
#define RELAY_PIN 17

// Define constants
#define DEBOUNCE_DELAY_MS 50
#define FAILSAFE_TIMEOUT_S 10

// Global variables
volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize_gpio();
int read_touch_sensor();
int control_relay(int state);
void handle_touch_event();
void failsafe_timeout();
void signal_handler(int signal);

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if (gpioSetMode(TOUCH_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as input\n", TOUCH_SENSOR_PIN);
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(RELAY_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", RELAY_PIN);
        gpioTerminate();
        return 1;
    }

    return 0;
}

// Function to read the touch sensor
int read_touch_sensor() {
    int value = gpioRead(TOUCH_SENSOR_PIN);
    if (value < 0) {
        fprintf(stderr, "Error reading GPIO%d\n", TOUCH_SENSOR_PIN);
        return -1; // Indicate error
    }
    return value;
}

// Function to control the relay
int control_relay(int state) {
    if (gpioWrite(RELAY_PIN, state) != 0) {
        fprintf(stderr, "Failed to write to GPIO%d\n", RELAY_PIN);
        return 1; // Indicate error
    }
    return 0;
}

// Function to handle touch events
void handle_touch_event() {
    int touch_state = read_touch_sensor();
    if (touch_state < 0) {
        return; // Error reading sensor, exit function
    }

    if (touch_state == 1) {
        // Toggle relay state
        int current_relay_state = gpioRead(RELAY_PIN);
        int new_relay_state = (current_relay_state == 0) ? 1 : 0;
        if (control_relay(new_relay_state) != 0) {
            fprintf(stderr, "Failed to toggle relay\n");
        }
    }
}

// Function to handle failsafe timeout
void failsafe_timeout() {
    printf("Failsafe triggered: Disabling relay\n");
    if (control_relay(0) != 0) {
        fprintf(stderr, "Failed to disable relay in failsafe\n");
    }
}

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting...\n", signal);
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    time_t last_touch_time = 0;

    // Main loop
    while (program_running) {
        int touch_state = read_touch_sensor();
        if (touch_state < 0) {
            fprintf(stderr, "Error reading touch sensor, exiting\n");
            break;
        }

        if (touch_state == 1) {
            time_t current_time = time(NULL);
            if (difftime(current_time, last_touch_time) >= FAILSAFE_TIMEOUT_S) {
                failsafe_timeout();
                last_touch_time = current_time; // Reset timer after failsafe
            }
            handle_touch_event();
            last_touch_time = current_time;
        }

        gpioDelay(DEBOUNCE_DELAY_MS * 1000); // Debounce delay
    }

    // Cleanup
    printf("Cleaning up...\n");
    control_relay(0); // Ensure relay is OFF
    gpioTerminate();

    return 0;
}

