#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

// Define GPIO pins
#define VALVE_PWM_PIN 18
#define VALVE_ENABLE_PIN 23
#define FLOW_SENSOR_PIN 24

// Define constants
#define PULSES_PER_LITER 450.0
#define CONTROL_INTERVAL_MS 100
#define PWM_FREQUENCY 1000 // Hz
#define PWM_RANGE 255
#define Kp 1.0

// Global variables
volatile int pulse_count = 0;
double target_flow_rate = 0.0;
FILE *log_file = NULL;

// Function prototypes
void pulse_counter_isr(int gpio, int level, uint32_t tick, void *user_data);
double calculate_flow_rate(int pulse_count);
int control_valve(double flow_rate, double target_flow_rate);
void log_data(double flow_rate, int valve_position);
void signal_handler(int signal);

// Interrupt service routine for pulse counting
void pulse_counter_isr(int gpio, int level, uint32_t tick, void *user_data)
{
    if (level == PI_HIGH) // Rising edge
    {
        pulse_count++;
    }
}

// Function to calculate flow rate in L/min
double calculate_flow_rate(int pulse_count)
{
    return (double)pulse_count / PULSES_PER_LITER * 60.0;
}

// Function to control the valve using a proportional controller
int control_valve(double flow_rate, double target_flow_rate)
{
    double error = target_flow_rate - flow_rate;
    double duty_cycle = Kp * error;

    // Clamp the duty cycle to the range [0, 255]
    if (duty_cycle < 0)
    {
        duty_cycle = 0;
    }
    else if (duty_cycle > 255)
    {
        duty_cycle = 255;
    }

    gpioPWM(VALVE_PWM_PIN, (int)duty_cycle);
    return (int)duty_cycle;
}

// Function to log data to a CSV file
void log_data(double flow_rate, int valve_position)
{
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    long timestamp_ms = (ts.tv_sec * 1000) + (ts.tv_nsec / 1000000);

    fprintf(log_file, "%ld,%.2f,%d\n", timestamp_ms, flow_rate, valve_position);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal)
{
    printf("Caught signal %d, cleaning up...\n", signal);

    // Disable the valve
    gpioWrite(VALVE_ENABLE_PIN, 0);
    gpioPWM(VALVE_PWM_PIN, 0);

    // Close the log file
    if (log_file != NULL)
    {
        fclose(log_file);
    }

    // Terminate pigpio
    gpioTerminate();

    exit(0);
}

int main(int argc, char *argv[])
{
    // Parse command-line arguments
    if (argc != 2)
    {
        fprintf(stderr, "Usage: %s <target_flow_rate_Lmin>\n", argv[0]);
        return 1;
    }

    char *endptr;
    target_flow_rate = strtod(argv[1], &endptr);

    if (*endptr != '\0' || target_flow_rate <= 0)
    {
        fprintf(stderr, "Error: Invalid target flow rate. Please provide a positive number.\n");
        return 1;
    }

    // Initialize pigpio
    if (gpioInitialise() < 0)
    {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(VALVE_PWM_PIN, PI_OUTPUT);
    gpioSetMode(VALVE_ENABLE_PIN, PI_OUTPUT);
    gpioSetMode(FLOW_SENSOR_PIN, PI_INPUT);

    // Enable the valve
    gpioWrite(VALVE_ENABLE_PIN, 1);

    // Set PWM frequency
    gpioSetPWMfrequency(VALVE_PWM_PIN, PWM_FREQUENCY);
    gpioSetPWMrange(VALVE_PWM_PIN, PWM_RANGE);

    // Register interrupt service routine
    if (gpioSetISRFuncEx(FLOW_SENSOR_PIN, RISING_EDGE, 0, pulse_counter_isr, NULL) != 0)
    {
        fprintf(stderr, "Failed to register ISR\n");
        gpioTerminate();
        return 1;
    }

    // Open the log file
    log_file = fopen("flow_log.csv", "a");
    if (log_file == NULL)
    {
        fprintf(stderr, "Failed to open log file\n");
        gpioTerminate();
        return 1;
    }

    // Write header to log file if it's a new file
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0)
    {
        fprintf(log_file, "timestamp_ms,flow_rate_Lmin,valve_position\n");
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main control loop
    while (1)
    {
        // Read pulse count
        int current_pulse_count = pulse_count;
        pulse_count = 0; // Reset pulse count for the next interval

        // Calculate flow rate
        double flow_rate = calculate_flow_rate(current_pulse_count);

        // Control the valve
        int valve_position = control_valve(flow_rate, target_flow_rate);

        // Log data
        log_data(flow_rate, valve_position);

        // Wait for the next control interval
        gpioDelay(CONTROL_INTERVAL_MS);
    }

    return 0;
}

