#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pthread.h>
#include <pigpio.h>

// Motor 1
#define MOTOR1_ENA 23
#define MOTOR1_IN1 24
#define MOTOR1_IN2 25
#define MOTOR1_A 5
#define MOTOR1_B 6

// Motor 2
#define MOTOR2_ENB 12
#define MOTOR2_IN3 16
#define MOTOR2_IN4 20
#define MOTOR2_A 26
#define MOTOR2_B 19

// PID Gains
#define KP 1.0
#define KI 0.1
#define KD 0.01

// Target RPMs
#define TARGET_RPM1 60.0
#define TARGET_RPM2 60.0

// PWM Frequency (Hz)
#define PWM_FREQUENCY 100

// Sample Time (ms)
#define SAMPLE_TIME 100

// Encoder Pulses per Revolution
#define ENCODER_PPR 600.0

// Mutexes for Encoder Counts
pthread_mutex_t encoder1_mutex = PTHREAD_MUTEX_INITIALIZER;
pthread_mutex_t encoder2_mutex = PTHREAD_MUTEX_INITIALIZER;

// Encoder Counts
volatile int encoder1_count = 0;
volatile int encoder2_count = 0;

// Global Variables for PID
double integral1 = 0.0;
double integral2 = 0.0;
double previous_error1 = 0.0;
double previous_error2 = 0.0;

// File Pointer for Logging
FILE *log_file = NULL;

// Function Prototypes
void *monitor_encoder1(void *arg);
void *monitor_encoder2(void *arg);
double calculate_rpm(int encoder_count);
double pid_control(double setpoint, double actual_value, double *integral, double *previous_error, double kp, double ki, double kd);
void set_motor_speed(int motor_ena, int in1, int in2, double duty_cycle);
void stop_motor(int motor_ena, int in1, int in2);
void signal_handler(int signal);

// Encoder Monitoring Threads
void *monitor_encoder1(void *arg) {
    int gpio_a = MOTOR1_A;
    int gpio_b = MOTOR1_B;
    int level_a, level_b;
    int last_level_a = gpioRead(gpio_a);
    int last_level_b = gpioRead(gpio_b);

    while (1) {
        level_a = gpioRead(gpio_a);
        level_b = gpioRead(gpio_b);

        if (level_a != last_level_a) {
            if (level_a != level_b) {
                pthread_mutex_lock(&encoder1_mutex);
                encoder1_count++;
                pthread_mutex_unlock(&encoder1_mutex);
            } else {
                pthread_mutex_lock(&encoder1_mutex);
                encoder1_count--;
                pthread_mutex_unlock(&encoder1_mutex);
            }
            last_level_a = level_a;
        }
        gpioDelay(1); // Small delay to prevent busy-waiting
    }
    return NULL;
}

void *monitor_encoder2(void *arg) {
    int gpio_a = MOTOR2_A;
    int gpio_b = MOTOR2_B;
    int level_a, level_b;
    int last_level_a = gpioRead(gpio_a);
    int last_level_b = gpioRead(gpio_b);

    while (1) {
        level_a = gpioRead(gpio_a);
        level_b = gpioRead(gpio_b);

        if (level_a != last_level_a) {
            if (level_a != level_b) {
                pthread_mutex_lock(&encoder2_mutex);
                encoder2_count++;
                pthread_mutex_unlock(&encoder2_mutex);
            } else {
                pthread_mutex_lock(&encoder2_mutex);
                encoder2_count--;
                pthread_mutex_unlock(&encoder2_mutex);
            }
            last_level_a = level_a;
        }
        gpioDelay(1); // Small delay to prevent busy-waiting
    }
    return NULL;
}

// Calculate RPM from Encoder Count
double calculate_rpm(int encoder_count) {
    return (double)encoder_count / ENCODER_PPR * 60.0 / SAMPLE_TIME * 1000.0;
}

// PID Control Function
double pid_control(double setpoint, double actual_value, double *integral, double *previous_error, double kp, double ki, double kd) {
    double error = setpoint - actual_value;
    *integral += error * SAMPLE_TIME / 1000.0;
    double derivative = (error - *previous_error) / (SAMPLE_TIME / 1000.0);
    double output = kp * error + ki * (*integral) + kd * derivative;
    *previous_error = error;
    return output;
}

// Set Motor Speed using PWM
void set_motor_speed(int motor_ena, int in1, int in2, double duty_cycle) {
    if (duty_cycle < 0.0) duty_cycle = 0.0;
    if (duty_cycle > 1.0) duty_cycle = 1.0;

    gpioWrite(in1, 1);
    gpioWrite(in2, 0);

    gpioPWM(motor_ena, (int)(duty_cycle * 255.0)); // pigpio PWM range is 0-255
}

// Stop Motor
void stop_motor(int motor_ena, int in1, int in2) {
    gpioWrite(in1, 0);
    gpioWrite(in2, 0);
    gpioPWM(motor_ena, 0);
}

// Signal Handler for Graceful Shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);

    // Stop Motors
    stop_motor(MOTOR1_ENA, MOTOR1_IN1, MOTOR1_IN2);
    stop_motor(MOTOR2_ENB, MOTOR2_IN3, MOTOR2_IN4);

    // Release GPIO Lines
    gpioSetMode(MOTOR1_ENA, PI_INPUT);
    gpioSetMode(MOTOR1_IN1, PI_INPUT);
    gpioSetMode(MOTOR1_IN2, PI_INPUT);
    gpioSetMode(MOTOR2_ENB, PI_INPUT);
    gpioSetMode(MOTOR2_IN3, PI_INPUT);
    gpioSetMode(MOTOR2_IN4, PI_INPUT);

    // Close pigpio
    gpioTerminate();

    // Close Log File
    if (log_file != NULL) {
        fclose(log_file);
    }

    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO Modes
    gpioSetMode(MOTOR1_ENA, PI_OUTPUT);
    gpioSetMode(MOTOR1_IN1, PI_OUTPUT);
    gpioSetMode(MOTOR1_IN2, PI_OUTPUT);
    gpioSetMode(MOTOR2_ENB, PI_OUTPUT);
    gpioSetMode(MOTOR2_IN3, PI_OUTPUT);
    gpioSetMode(MOTOR2_IN4, PI_OUTPUT);

    // Set PWM Frequency
    gpioSetPWMfrequency(MOTOR1_ENA, PWM_FREQUENCY);
    gpioSetPWMfrequency(MOTOR2_ENB, PWM_FREQUENCY);

    // Open Log File
    log_file = fopen("motor_log.csv", "w");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Write Header Row
    fprintf(log_file, "Timestamp,Motor1_RPM,Motor2_RPM,Motor1_P,Motor1_I,Motor1_D,Motor1_Output,Motor2_P,Motor2_I,Motor2_D,Motor2_Output\n");

    // Install Signal Handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Create Encoder Monitoring Threads
    pthread_t encoder1_thread, encoder2_thread;
    if (pthread_create(&encoder1_thread, NULL, monitor_encoder1, NULL) != 0) {
        fprintf(stderr, "Error creating encoder 1 thread!\n");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }
    if (pthread_create(&encoder2_thread, NULL, monitor_encoder2, NULL) != 0) {
        fprintf(stderr, "Error creating encoder 2 thread!\n");
        pthread_cancel(encoder1_thread);
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    // Main Control Loop
    while (1) {
        // Get Encoder Counts
        pthread_mutex_lock(&encoder1_mutex);
        int encoder1_count_local = encoder1_count;
        pthread_mutex_unlock(&encoder1_mutex);

        pthread_mutex_lock(&encoder2_mutex);
        int encoder2_count_local = encoder2_count;
        pthread_mutex_unlock(&encoder2_mutex);

        // Calculate RPM
        double rpm1 = calculate_rpm(encoder1_count_local);
        double rpm2 = calculate_rpm(encoder2_count_local);

        // PID Control
        double pid_output1 = pid_control(TARGET_RPM1, rpm1, &integral1, &previous_error1, KP, KI, KD);
        double pid_output2 = pid_control(TARGET_RPM2, rpm2, &integral2, &previous_error2, KP, KI, KD);

        // Set Motor Speeds
        set_motor_speed(MOTOR1_ENA, MOTOR1_IN1, MOTOR1_IN2, pid_output1);
        set_motor_speed(MOTOR2_ENB, MOTOR2_IN3, MOTOR2_IN4, pid_output2);

        // Log Data
        time_t rawtime;
        struct tm *timeinfo;
        time(&rawtime);
        timeinfo = localtime(&rawtime);
        char timestamp[80];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

        fprintf(log_file, "%s,%.2f,%.2f,%.2f,%.2f,%.2f,%.2f,%.2f,%.2f,%.2f,%.2f\n",
                timestamp, rpm1, rpm2, KP * (TARGET_RPM1 - rpm1), KI * integral1, KD * ((TARGET_RPM1 - rpm1) - previous_error1), pid_output1,
                KP * (TARGET_RPM2 - rpm2), KI * integral2, KD * ((TARGET_RPM2 - rpm2) - previous_error2), pid_output2);
        fflush(log_file);

        // Delay for Sample Time
        gpioDelay(SAMPLE_TIME);
    }

    // Cleanup (should not reach here in normal operation due to signal handler)
    pthread_cancel(encoder1_thread);
    pthread_cancel(encoder2_thread);
    pthread_join(encoder1_thread, NULL);
    pthread_join(encoder2_thread, NULL);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

