    gpioSetMode(MOTOR1_ENA, PI_INPUT);
    gpioSetMode(MOTOR1_IN1, PI_INPUT);
    gpioSetMode(MOTOR1_IN2, PI_INPUT);
    gpioSetMode(MOTOR2_ENB, PI_INPUT);
    gpioSetMode(MOTOR2_IN3, PI_INPUT);
    gpioSetMode(MOTOR2_IN4, PI_INPUT);

    // Close pigpio
    gpioTerminate();

    // Close Log File
    if (log_file != NULL) {
        fclose(log_file);
    }

    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO Modes
    gpioSetMode(MOTOR1_ENA, PI_OUTPUT);
    gpioSetMode(MOTOR1_IN1, PI_OUTPUT);
    gpioSetMode(MOTOR1_IN2, PI_OUTPUT);
    gpioSetMode(MOTOR2_ENB, PI_OUTPUT);
    gpioSetMode(MOTOR2_IN3, PI_OUTPUT);
    gpioSetMode(MOTOR2_IN4, PI_OUTPUT);

    // Set PWM Frequency
    gpioSetPWMfrequency(MOTOR1_ENA, PWM_FREQUENCY);
    gpioSetPWMfrequency(MOTOR2_ENB, PWM_FREQUENCY);

    // Open Log File
    log_file = fopen("motor_log.csv", "w");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Write Header Row
    fprintf(log_file, "Timestamp,Motor1_RPM,Motor2_RPM,Motor1_P,Motor1_I,Motor1_D,Motor1_Output,Motor2_P,Motor2_I,Motor2_D,Motor2_Output\n");

    // Install Signal Handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Create Encoder Monitoring Threads
    pthread_t encoder1_thread, encoder2_thread;
    if (pthread_create(&encoder1_thread, NULL, monitor_encoder1, NULL) != 0) {
        fprintf(stderr, "Error creating encoder 1 thread!\n");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }
    if (pthread_create(&encoder2_thread, NULL, monitor_encoder2, NULL) != 0) {
        fprintf(stderr, "Error creating encoder 2 thread!\n");
        pthread_cancel(encoder1_thread);
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    // Main Control Loop
    while (1) {
        // Get Encoder Counts
        pthread_mutex_lock(&encoder1_mutex);
        int encoder1_count_local = encoder1_count;
        pthread_mutex_unlock(&encoder1_mutex);

        pthread_mutex_lock(&encoder2_mutex);
        int encoder2_count_local = encoder2_count;
        pthread_mutex_unlock(&encoder2_mutex);

        // Calculate RPM
        double rpm1 = calculate_rpm(encoder1_count_local);
        double rpm2 = calculate_rpm(encoder2_count_local);

        // PID Control
        double pid_output1 = pid_control(TARGET_RPM1, rpm1, &integral1, &previous_error1, KP, KI, KD);
        double pid_output2 = pid_control(TARGET_RPM2, rpm2, &integral2, &previous_error2, KP, KI, KD);

        // Set Motor Speeds
        set_motor_speed(MOTOR1_ENA, MOTOR1_IN1, MOTOR1_IN2, pid_output1);
        set_motor_speed(MOTOR2_ENB, MOTOR2_IN3, MOTOR2_IN4, pid_output2);

        // Log Data
        time_t rawtime;
        struct tm *timeinfo;
        time(&rawtime);
        timeinfo = localtime(&rawtime);
        char timestamp[80];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

        fprintf(log_file, "%s,%.2f,%.2f,%.2f,%.2f,%.2f,%.2f,%.2f,%.2f,%.2f,%.2f\n",
                timestamp, rpm1, rpm2, KP * (TARGET_RPM1 - rpm1), KI * integral1, KD * ((TARGET_RPM1 - rpm1) - previous_error1), pid_output1,
                KP * (TARGET_RPM2 - rpm2), KI * integral2, KD * ((TARGET_RPM2 - rpm2) - previous_error2), pid_output2);
        fflush(log_file);

        // Delay for Sample Time
        gpioDelay(SAMPLE_TIME);
    }

    // Cleanup (should not reach here in normal operation due to signal handler)
    pthread_cancel(encoder1_thread);
    pthread_cancel(encoder2_thread);
    pthread_join(encoder1_thread, NULL);
    pthread_join(encoder2_thread, NULL);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

