#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Define constants
#define I2C_BUS 1
#define MPR121_ADDR 0x5A
#define RELAY_GPIO 17
#define SOFT_RESET_CMD 0x80
#define ELE_CFG_REG 0x5E
#define TOUCH_STATUS_L 0x00
#define TOUCH_STATUS_H 0x01
#define RELEASE_STATUS_L 0x02
#define RELEASE_STATUS_H 0x03
#define TOUCH_THRESHOLD_REG 0x41
#define RELEASE_THRESHOLD_REG 0x42

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_mpr121();
int read_touch_status();
void control_relay(int state);
void log_relay_state(int state);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Initialize MPR121 sensor
int initialize_mpr121() {
    // Soft reset
    if (i2cWriteByteData(i2c_handle, SOFT_RESET_CMD, 0x63) < 0) {
        fprintf(stderr, "Error: Soft reset failed\n");
        return -1;
    }
    gpioDelay(100000); // Wait 100ms

    // Configure electrode filtering (example: enable all electrodes)
    if (i2cWriteByteData(i2c_handle, ELE_CFG_REG, 0x0C) < 0) {
        fprintf(stderr, "Error: Electrode configuration failed\n");
        return -1;
    }

    // Set touch and release thresholds for all electrodes
    for (int i = 0; i < 12; i++) {
        if (i2cWriteByteData(i2c_handle, TOUCH_THRESHOLD_REG + 2 * i, 40) < 0) {
            fprintf(stderr, "Error: Setting touch threshold failed for electrode %d\n", i);
            return -1;
        }
        if (i2cWriteByteData(i2c_handle, RELEASE_THRESHOLD_REG + 2 * i, 20) < 0) {
            fprintf(stderr, "Error: Setting release threshold failed for electrode %d\n", i);
            return -1;
        }
    }

    // Enable run mode
    if (i2cWriteByteData(i2c_handle, 0x5B, 0x01) < 0) {
        fprintf(stderr, "Error: Enabling run mode failed\n");
        return -1;
    }

    return 0;
}

// Read touch status from MPR121
int read_touch_status() {
    int touch_status_l, touch_status_h;

    touch_status_l = i2cReadByteData(i2c_handle, TOUCH_STATUS_L);
    if (touch_status_l < 0) {
        fprintf(stderr, "Error: Reading touch status low byte failed\n");
        return -1;
    }

    touch_status_h = i2cReadByteData(i2c_handle, TOUCH_STATUS_H);
    if (touch_status_h < 0) {
        fprintf(stderr, "Error: Reading touch status high byte failed\n");
        return -1;
    }

    return (touch_status_h << 8) | touch_status_l;
}

// Control the relay
void control_relay(int state) {
    gpioWrite(RELAY_GPIO, state);
}

// Log relay state to file
void log_relay_state(int state) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(log_file, "%d-%02d-%02d %02d:%02d:%02d Relay state: %s\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec,
            state ? "ON" : "OFF");
    fflush(log_file);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, MPR121_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: I2C open failed\n");
        gpioTerminate();
        return 1;
    }

    // Initialize MPR121 sensor
    if (initialize_mpr121() < 0) {
        fprintf(stderr, "Error: MPR121 initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set relay GPIO as output
    gpioSetMode(RELAY_GPIO, PI_OUTPUT);

    // Open log file
    log_file = fopen("relay_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    int last_touch_state = 0;
    while (!terminate) {
        int touch_status = read_touch_status();
        if (touch_status < 0) {
            fprintf(stderr, "Error: Failed to read touch status\n");
            break; // Exit loop on error
        }

        int current_touch_state = (touch_status > 0) ? 1 : 0;

        if (current_touch_state != last_touch_state) {
            control_relay(current_touch_state);
            log_relay_state(current_touch_state);
            last_touch_state = current_touch_state;
        }

        gpioDelay(50000); // 50ms delay
    }

    // Cleanup
    control_relay(0); // Turn off relay
    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

