#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Define GPIO pins for the valves
#define VALVE1_GPIO 17
#define VALVE2_GPIO 18

// Define GPIO chip name
#define GPIO_CHIP "gpiochip0"

// Define log file name
#define LOG_FILE "valve_log.txt"

// Global variables for GPIO lines and chip
struct gpiod_line *valve1_line = NULL;
struct gpiod_line *valve2_line = NULL;
struct gpiod_chip *gpio_chip = NULL;
FILE *log_file = NULL;

// Function prototypes
int initialize_gpio(void);
int activate_valve(int gpio_pin, int duration_ms);
int deactivate_valve(int gpio_pin);
int log_event(int gpio_pin, int duration_ms);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);

    // Deactivate valves
    deactivate_valve(VALVE1_GPIO);
    deactivate_valve(VALVE2_GPIO);

    // Release GPIO lines
    if (valve1_line) {
        gpiod_line_release(valve1_line);
    }
    if (valve2_line) {
        gpiod_line_release(valve2_line);
    }

    // Close GPIO chip
    if (gpio_chip) {
        gpiod_chip_close(gpio_chip);
    }

    // Close log file
    if (log_file) {
        fclose(log_file);
    }

    exit(0);
}

// Initialize GPIO lines
int initialize_gpio(void) {
    int ret;

    // Open GPIO chip
    gpio_chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!gpio_chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    // Request GPIO lines for output
    valve1_line = gpiod_chip_get_line(gpio_chip, VALVE1_GPIO);
    if (!valve1_line) {
        perror("Error getting GPIO line for Valve 1");
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    valve2_line = gpiod_chip_get_line(gpio_chip, VALVE2_GPIO);
    if (!valve2_line) {
        perror("Error getting GPIO line for Valve 2");
        gpiod_line_release(valve1_line);
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    ret = gpiod_line_request_output(valve1_line, "valve1", 0); // Initial value LOW (closed)
    if (ret < 0) {
        perror("Error requesting GPIO line for Valve 1 as output");
        gpiod_line_release(valve2_line);
        gpiod_line_release(valve1_line);
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    ret = gpiod_line_request_output(valve2_line, "valve2", 0); // Initial value LOW (closed)
    if (ret < 0) {
        perror("Error requesting GPIO line for Valve 2 as output");
        gpiod_line_release(valve1_line);
        gpiod_line_release(valve2_line);
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    return 0;
}

// Activate a valve for a specified duration
int activate_valve(int gpio_pin, int duration_ms) {
    int ret;

    // Set GPIO pin HIGH to activate the valve
    ret = gpiod_line_set_value(gpio_pin == VALVE1_GPIO ? valve1_line : valve2_line, 1);
    if (ret < 0) {
        perror("Error setting GPIO line value");
        return -1;
    }

    // Log the event
    if (log_event(gpio_pin, duration_ms) != 0) {
        fprintf(stderr, "Error logging valve activation event.\n");
    }

    // Wait for the specified duration
    usleep(duration_ms * 1000); // Convert milliseconds to microseconds

    return 0;
}

// Deactivate a valve
int deactivate_valve(int gpio_pin) {
    int ret;

    // Set GPIO pin LOW to deactivate the valve
    ret = gpiod_line_set_value(gpio_pin == VALVE1_GPIO ? valve1_line : valve2_line, 0);
    if (ret < 0) {
        perror("Error setting GPIO line value");
        return -1;
    }

    return 0;
}

// Log valve activation event to file
int log_event(int gpio_pin, int duration_ms) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    // Get current time
    time(&rawtime);
    timeinfo = localtime(&rawtime);

    // Format timestamp in ISO 8601 format
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    // Open log file in append mode
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Error opening log file");
        return -1;
    }

    // Write log entry
    fprintf(log_file, "%s - Valve %d activated for %d ms\n", timestamp, gpio_pin, duration_ms);

    // Close log file
    fclose(log_file);

    return 0;
}

int main(void) {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return 1;
    }

    printf("Automated Greenhouse Valve Control System\n");

    // Main loop
    while (1) {
        // Activate Valve 1
        if (activate_valve(VALVE1_GPIO, 500) != 0) {
            fprintf(stderr, "Error activating Valve 1.\n");
        }

        // Pause for 5 seconds
        sleep(5);

        // Activate Valve 2
        if (activate_valve(VALVE2_GPIO, 1000) != 0) {
            fprintf(stderr, "Error activating Valve 2.\n");
        }

        // Pause for 10 seconds
        sleep(10);
    }

    return 0;
}

