    usleep(duration_ms * 1000); // Convert milliseconds to microseconds

    return 0;
}

// Deactivate a valve
int deactivate_valve(int gpio_pin) {
    int ret;

    // Set GPIO pin LOW to deactivate the valve
    ret = gpiod_line_set_value(gpio_pin == VALVE1_GPIO ? valve1_line : valve2_line, 0);
    if (ret < 0) {
        perror("Error setting GPIO line value");
        return -1;
    }

    return 0;
}

// Log valve activation event to file
int log_event(int gpio_pin, int duration_ms) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    // Get current time
    time(&rawtime);
    timeinfo = localtime(&rawtime);

    // Format timestamp in ISO 8601 format
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    // Open log file in append mode
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Error opening log file");
        return -1;
    }

    // Write log entry
    fprintf(log_file, "%s - Valve %d activated for %d ms\n", timestamp, gpio_pin, duration_ms);

    // Close log file
    fclose(log_file);

    return 0;
}

int main(void) {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return 1;
    }

    printf("Automated Greenhouse Valve Control System\n");

    // Main loop
    while (1) {
        // Activate Valve 1
        if (activate_valve(VALVE1_GPIO, 500) != 0) {
            fprintf(stderr, "Error activating Valve 1.\n");
        }

        // Pause for 5 seconds
        sleep(5);

        // Activate Valve 2
        if (activate_valve(VALVE2_GPIO, 1000) != 0) {
            fprintf(stderr, "Error activating Valve 2.\n");
        }

        // Pause for 10 seconds
        sleep(10);
    }

    return 0;
}

