#define MPR121_ADDR 0x5A
#define RELAY_GPIO 17
#define TOUCH_STATUS_REG_L 0x00
#define TOUCH_STATUS_REG_H 0x01
#define TOUCH_THRESHOLD_REG 0x10
#define RELEASE_THRESHOLD_REG 0x0A
#define FILTER_REG 0x20
#define ELECTRODE_CURRENT_REG 0x01
#define ELE_EN_REG 0x20

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_mpr121();
int read_touch_status();
void toggle_relay(int current_state);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Function to initialize the MPR121
int initialize_mpr121() {
    int status;

    // Stop mode
    status = i2cWriteByteData(i2c_handle, ELE_EN_REG, 0x00);
    if (status < 0) {
        fprintf(stderr, "Error writing to ELE_EN_REG (stop mode): %d\n", status);
        return -1;
    }
    gpioDelay(1); // Small delay after writing

    // Set touch and release thresholds for all electrodes
    for (int i = 0; i < 12; i++) {
        status = i2cWriteByteData(i2c_handle, TOUCH_THRESHOLD_REG + 2 * i, 0x10);
        if (status < 0) {
            fprintf(stderr, "Error writing to touch threshold register %d: %d\n", i, status);
            return -1;
        }
        status = i2cWriteByteData(i2c_handle, RELEASE_THRESHOLD_REG + 2 * i, 0x0A);
        if (status < 0) {
            fprintf(stderr, "Error writing to release threshold register %d: %d\n", i, status);
            return -1;
        }
        gpioDelay(1);
    }

    // Configure filter and charge time
    status = i2cWriteByteData(i2c_handle, FILTER_REG, 0x20); // Filter configuration
    if (status < 0) {
        fprintf(stderr, "Error writing to FILTER_REG: %d\n", status);
        return -1;
    }
    gpioDelay(1);

    status = i2cWriteByteData(i2c_handle, ELECTRODE_CURRENT_REG, 0x01); // Electrode current configuration
    if (status < 0) {
        fprintf(stderr, "Error writing to ELECTRODE_CURRENT_REG: %d\n", status);
        return -1;
    }
    gpioDelay(1);

    // Enter run mode
    status = i2cWriteByteData(i2c_handle, ELE_EN_REG, 0x0C); // Enable all 12 electrodes
    if (status < 0) {
        fprintf(stderr, "Error writing to ELE_EN_REG (run mode): %d\n", status);
        return -1;
    }
    gpioDelay(1);

    gpioDelay(100); // Wait for stabilization

    return 0;
}

