int read_touch_status() {
    int status_l, status_h;

    status_l = i2cReadByteData(i2c_handle, TOUCH_STATUS_REG_L);
    if (status_l < 0) {
        fprintf(stderr, "Error reading TOUCH_STATUS_REG_L: %d\n", status_l);
        return -1;
    }

    status_h = i2cReadByteData(i2c_handle, TOUCH_STATUS_REG_H);
    if (status_h < 0) {
        fprintf(stderr, "Error reading TOUCH_STATUS_REG_H: %d\n", status_h);
        return -1;
    }

    return (status_h << 8) | status_l;
}

// Function to toggle the relay
void toggle_relay(int current_state) {
    int new_state = !current_state;
    gpioWrite(RELAY_GPIO, new_state);
    printf("Relay toggled to %d\n", new_state);
}

int main() {
    int touch_status;
    int relay_state = 0; // 0 = off, 1 = on

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, MPR121_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize MPR121
    if (initialize_mpr121() != 0) {
        fprintf(stderr, "MPR121 initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set relay GPIO as output
    gpioSetMode(RELAY_GPIO, PI_OUTPUT);
    gpioWrite(RELAY_GPIO, relay_state); // Initialize relay to off

    // Set up signal handling for Ctrl+C and SIGTERM
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Touch sensor and relay control started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        touch_status = read_touch_status();
        if (touch_status > 0) {
            toggle_relay(relay_state);
            relay_state = !relay_state; // Update relay state
        }
        gpioDelay(100); // Delay 100ms
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioWrite(RELAY_GPIO, 0); // Turn off relay on exit
    gpioTerminate();

    return 0;
}

