#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

// Define GPIO pins
#define PIR_SENSOR_1 17
#define PIR_SENSOR_2 22
#define RELAY_PIN 18

// Define constants
#define UNLOCK_DURATION_MS 500
#define RATE_LIMIT_DURATION_S 2
#define POLL_INTERVAL_MS 50

// Global variables
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
void signal_handler(int signal);
void log_event(const char *event_type, int gpio_pin);
void unlock_door();
void rate_limit_timer();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Function to log events to a file
void log_event(const char *event_type, int gpio_pin) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    long milliseconds = ts.tv_nsec / 1000000;

    fprintf(log_file, "%ld.%03ld - GPIO %d - %s\n", ts.tv_sec, milliseconds, gpio_pin, event_type);
    fflush(log_file); // Ensure immediate write to file
}

// Function to unlock the door
void unlock_door() {
    gpioWrite(RELAY_PIN, 1); // Activate relay (unlock)
    gpioDelay(UNLOCK_DURATION_MS * 1000); // Delay for unlock duration
    gpioWrite(RELAY_PIN, 0); // Deactivate relay (lock)
    log_event("Door Unlocked", RELAY_PIN);
}

// Function to implement rate limiting
void rate_limit_timer() {
    gpioDelay(RATE_LIMIT_DURATION_S * 1000000); // Delay for rate limit duration
    log_event("Rate Limit Expired", -1); // Log rate limit expiration
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(PIR_SENSOR_1, PI_INPUT);
    gpioSetMode(PIR_SENSOR_2, PI_INPUT);
    gpioSetMode(RELAY_PIN, PI_OUTPUT);

    // Set pull-down resistors for PIR sensors
    gpioSetPullUpDown(PIR_SENSOR_1, PI_PUD_DOWN);
    gpioSetPullUpDown(PIR_SENSOR_2, PI_PUD_DOWN);

    // Initialize log file
    log_file = fopen("door_events.log", "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        gpioTerminate();
        return 1;
    }

    // Register signal handler for graceful shutdown
    signal(SIGINT, signal_handler);

    printf("Door strike control system started. Press Ctrl+C to exit.\n");

    int last_state_1 = 0;
    int last_state_2 = 0;
    time_t last_unlock_time = 0;

    // Main loop
    while (!terminate) {
        // Read PIR sensor values
        int current_state_1 = gpioRead(PIR_SENSOR_1);
        int current_state_2 = gpioRead(PIR_SENSOR_2);

        // Check for rising edge on PIR sensor 1
        if (current_state_1 == 1 && last_state_1 == 0) {
            time_t now = time(NULL);
            if (difftime(now, last_unlock_time) >= RATE_LIMIT_DURATION_S) {
                log_event("Motion Detected", PIR_SENSOR_1);
                unlock_door();
                last_unlock_time = now;
            } else {
                log_event("Rate Limited", PIR_SENSOR_1);
            }
        }

        // Check for rising edge on PIR sensor 2
        if (current_state_2 == 1 && last_state_2 == 0) {
            time_t now = time(NULL);
            if (difftime(now, last_unlock_time) >= RATE_LIMIT_DURATION_S) {
                log_event("Motion Detected", PIR_SENSOR_2);
                unlock_door();
                last_unlock_time = now;
            } else {
                log_event("Rate Limited", PIR_SENSOR_2);
            }
        }

        // Update last known states
        last_state_1 = current_state_1;
        last_state_2 = current_state_2;

        // Poll interval
        gpioDelay(POLL_INTERVAL_MS * 1000);
    }

    // Cleanup
    printf("Cleaning up...\n");
    fclose(log_file);
    gpioWrite(RELAY_PIN, 0); // Ensure relay is off
    gpioTerminate();

    return 0;
}

