#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

// Define GPIO pins for the vibration motors
#define MOTOR1_PIN 17
#define MOTOR2_PIN 27

// Structure to represent a haptic feedback pattern
typedef struct {
    int motor1_duty_cycle;
    int motor2_duty_cycle;
    int duration_ms;
} HapticPattern;

// Global flag to signal program termination
volatile sig_atomic_t shutdown = 0;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signal) {
    shutdown = 1;
    printf("\nCaught signal %d, stopping motors and exiting gracefully...\n", signal);
}

// Function to generate a random haptic feedback pattern
HapticPattern generate_pattern() {
    HapticPattern pattern;

    // Generate random duty cycles for each motor (0-255)
    pattern.motor1_duty_cycle = rand() % 256;
    pattern.motor2_duty_cycle = rand() % 256;

    // Generate a random duration between 50 and 200 ms
    pattern.duration_ms = (rand() % 151) + 50;

    return pattern;
}

// Function to play a haptic feedback pattern
void play_pattern(HapticPattern pattern) {
    // Set the PWM duty cycle for each motor
    gpioPWM(MOTOR1_PIN, pattern.motor1_duty_cycle);
    gpioPWM(MOTOR2_PIN, pattern.motor2_duty_cycle);

    // Delay for the specified duration
    gpioDelay(pattern.duration_ms * 1000); // Convert ms to microseconds

    // Stop the motors after the delay
    gpioPWM(MOTOR1_PIN, 0);
    gpioPWM(MOTOR2_PIN, 0);
}

int main() {
    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as outputs
    gpioSetMode(MOTOR1_PIN, PI_OUTPUT);
    gpioSetMode(MOTOR2_PIN, PI_OUTPUT);

    // Seed the random number generator
    srand(time(NULL));

    // Register the signal handler for SIGINT
    signal(SIGINT, signal_handler);

    printf("Haptic feedback system started. Press Ctrl+C to exit.\n");

    // Main loop to generate and play patterns
    while (!shutdown) {
        // Generate a random pattern
        HapticPattern pattern = generate_pattern();

        // Play the pattern
        play_pattern(pattern);
    }

    // Stop the motors before exiting
    gpioPWM(MOTOR1_PIN, 0);
    gpioPWM(MOTOR2_PIN, 0);

    // Terminate the pigpio library
    gpioTerminate();

    printf("Haptic feedback system stopped.\n");

    return 0;
}

