#include <pigpio.h>

// Define GPIO pins
#define HX711_DATA_PIN 4
#define HX711_CLOCK_PIN 17
#define SOLENOID_PIN 27

// Define constants
#define CALIBRATION_FILE "calibration.txt"
#define WEIGHT_LOG_FILE "weight_log.txt"
#define CALIBRATION_SAMPLES 100
#define CALIBRATION_THRESHOLD 10.0 // kg
#define TIMEOUT_US 500000 // 0.5 seconds

// Global variables
static volatile int running = 1;
static FILE *calibration_file = NULL;
static FILE *weight_log_file = NULL;
static double scale_factor = 1.0;
static double offset = 0.0;

// Function prototypes
int read_hx711();
double convert_to_weight(int raw_value);
int load_calibration_data();
int save_calibration_data();
int calibrate_sensor();
void control_solenoid(double weight);
void log_weight(double weight);
void signal_handler(int signal);

// Function to read data from HX711
int read_hx711() {
    int data = 0;
    int i;
    gpioWrite(HX711_CLOCK_PIN, 0);
    gpioDelay(1);

    // Wait for data pin to go low
    int timeout_count = 0;
    while (gpioRead(HX711_DATA_PIN) == 1) {
        gpioDelay(1); // Small delay to prevent busy-waiting
        timeout_count++;
        if (timeout_count > (TIMEOUT_US / 1000)) { // Check every 1ms
            fprintf(stderr, "Timeout waiting for HX711 data.\n");
            return -1; // Timeout
        }
    }

    for (i = 0; i < 24; i++) {
        gpioWrite(HX711_CLOCK_PIN, 1);
        gpioDelay(1);
        data = data << 1;
        if (gpioRead(HX711_DATA_PIN)) {
            data++;
        }
        gpioWrite(HX711_CLOCK_PIN, 0);
        gpioDelay(1);
    }

    // 25th pulse for gain setting (channel A, gain 128)
    gpioWrite(HX711_CLOCK_PIN, 1);
    gpioDelay(1);
    gpioWrite(HX711_CLOCK_PIN, 0);
    gpioDelay(1);

    data = data ^ 0x800000; // Convert to signed 24-bit integer

    return data;
}

// Function to convert raw value to weight
double convert_to_weight(int raw_value) {
    return (raw_value - offset) / scale_factor;
}

// Function to load calibration data from file
int load_calibration_data() {
    calibration_file = fopen(CALIBRATION_FILE, "r");
    if (calibration_file == NULL) {
        fprintf(stderr, "Error: Could not open calibration file %s. Using default values.\n", CALIBRATION_FILE);
        return -1;
    }

    if (fscanf(calibration_file, "%lf %lf", &scale_factor, &offset) != 2) {
        fprintf(stderr, "Error: Invalid calibration data in %s. Using default values.\n", CALIBRATION_FILE);
        fclose(calibration_file);
        calibration_file = NULL;
        return -1;
    }

    printf("Calibration data loaded: scale_factor=%.2f, offset=%.2f\n", scale_factor, offset);
    return 0;
}

// Function to save calibration data to file
int save_calibration_data() {
    calibration_file = fopen(CALIBRATION_FILE, "w");
    if (calibration_file == NULL) {
        fprintf(stderr, "Error: Could not open calibration file %s for writing.\n", CALIBRATION_FILE);
        return -1;
    }

    fprintf(calibration_file, "%.6f %.6f", scale_factor, offset);
    fclose(calibration_file);
    calibration_file = NULL;
    printf("Calibration data saved: scale_factor=%.2f, offset=%.2f\n", scale_factor, offset);
    return 0;
}

// Function to calibrate the sensor
int calibrate_sensor() {
    printf("Starting calibration...\n");
    double sum = 0.0;
    for (int i = 0; i < CALIBRATION_SAMPLES; i++) {
        int raw_value = read_hx711();
        if (raw_value == -1) {
            fprintf(stderr, "Error: Timeout during calibration sample %d.\n", i + 1);
            return -1;
        }
        sum += raw_value;
        gpioDelay(10); // Small delay between samples
    }

    offset = sum / CALIBRATION_SAMPLES;
    printf("Calibration complete. Offset: %.2f\n", offset);
    return 0;
}

// Function to control the solenoid lock
void control_solenoid(double weight) {
    if (weight > CALIBRATION_THRESHOLD) {
        gpioWrite(SOLENOID_PIN, 1); // Lock
        printf("Weight exceeds threshold. Locking solenoid.\n");
    } else {
        gpioWrite(SOLENOID_PIN, 0); // Unlock
        printf("Weight below threshold. Unlocking solenoid.\n");
    }
}

// Function to log weight data to file
void log_weight(double weight) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    weight_log_file = fopen(WEIGHT_LOG_FILE, "a");
    if (weight_log_file == NULL) {
        fprintf(stderr, "Error: Could not open weight log file %s for writing.\n", WEIGHT_LOG_FILE);
        return;
    }

    fprintf(weight_log_file, "%s, Weight: %.2f kg\n", timestamp, weight);
    fclose(weight_log_file);
    weight_log_file = NULL;
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("Caught signal %d. Exiting gracefully.\n", signal);
    running = 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(HX711_DATA_PIN, PI_INPUT);
    gpioSetMode(HX711_CLOCK_PIN, PI_OUTPUT);
    gpioSetMode(SOLENOID_PIN, PI_OUTPUT);

    // Load calibration data
    if (load_calibration_data() != 0) {
        fprintf(stderr, "Using default calibration values.\n");
    }

    // Calibrate the sensor
    if (calibrate_sensor() != 0) {
        fprintf(stderr, "Calibration failed. Using default offset.\n");
    }

    // Save calibration data
    if (save_calibration_data() != 0) {
        fprintf(stderr, "Error saving calibration data.\n");
    }

    // Set up signal handler
    signal(SIGINT, signal_handler);

    // Main loop
    while (running) {
        int raw_value = read_hx711();
        if (raw_value != -1) {
            double weight = convert_to_weight(raw_value);
            printf("Raw: %d, Weight: %.2f kg\n", raw_value, weight);
            control_solenoid(weight);
            log_weight(weight);
        } else {
            fprintf(stderr, "Error: Failed to read HX711 value.\n");
        }

        gpioDelay(500); // 500 ms delay
    }

    // Clean up
    gpioWrite(SOLENOID_PIN, 0); // Ensure solenoid is unlocked on exit
    gpioTerminate();

    return 0;
}

