#define MOTOR_FORWARD 1
#define MOTOR_BACKWARD 0
#define MOTOR_STOP 2

// Define PWM frequency and duty cycle
#define PWM_FREQUENCY 1000
#define PWM_DUTY_CYCLE 150

// Define debounce parameters
#define DEBOUNCE_READINGS 5
#define DEBOUNCE_INTERVAL_MS 50

// Define motor run time
#define MOTOR_RUN_TIME_S 5

// Global variable to track program state for signal handling
volatile sig_atomic_t program_running = 1;

// Function prototypes
int read_rain_sensor();
int debounce_rain_sensor();
void close_window();
void stop_motor();
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT || signal == SIGTERM) {
        syslog(LOG_INFO, "Received signal %d, stopping motor and exiting.", signal);
        stop_motor();
        gpioTerminate();
        closelog();
        program_running = 0;
        exit(0);
    }
}

// Function to read the rain sensor
int read_rain_sensor() {
    return gpioRead(RAIN_SENSOR_PIN);
}

// Function to debounce the rain sensor
int debounce_rain_sensor() {
    int low_count = 0;
    for (int i = 0; i < DEBOUNCE_READINGS; i++) {
        if (read_rain_sensor() == 0) {
            low_count++;
        }
        gpioDelay(DEBOUNCE_INTERVAL_MS * 1000); // Convert ms to microseconds
    }
    return (low_count >= 3) ? 0 : 1; // Return 0 if rain detected, 1 otherwise
}

// Function to close the window
void close_window() {
    syslog(LOG_INFO, "Closing window.");
    gpioWrite(MOTOR_IN1_PIN, MOTOR_FORWARD);
    gpioWrite(MOTOR_IN2_PIN, MOTOR_BACKWARD);
    gpioPWM(MOTOR_PWM_PIN, PWM_DUTY_CYCLE);
    gpioDelay(MOTOR_RUN_TIME_S * 1000000); // Convert seconds to microseconds
    stop_motor();
    syslog(LOG_INFO, "Window closed.");
}

// Function to stop the motor
void stop_motor() {
    gpioWrite(MOTOR_IN1_PIN, MOTOR_STOP);
    gpioWrite(MOTOR_IN2_PIN, MOTOR_STOP);
    gpioPWM(MOTOR_PWM_PIN, 0);
    syslog(LOG_INFO, "Motor stopped.");
}

int main() {
    // Initialize syslog
    openlog("window_control", LOG_PID | LOG_CONS, LOG_USER);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        closelog();
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(RAIN_SENSOR_PIN, PI_INPUT);
    gpioSetMode(MOTOR_IN1_PIN, PI_OUTPUT);
    gpioSetMode(MOTOR_IN2_PIN, PI_OUTPUT);
    gpioSetMode(MOTOR_PWM_PIN, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(MOTOR_PWM_PIN, PWM_FREQUENCY);

    syslog(LOG_INFO, "Window control program started.");

    // Main loop
    while (program_running) {
        if (debounce_rain_sensor() == 0) {
            close_window();
        }
        gpioDelay(60 * 1000000); // Wait 60 seconds
    }

    // Cleanup (should not reach here if signal handler works correctly)
    stop_motor();
    gpioTerminate();
    closelog();
    return 0;
}

