#define HX711_SCK 24
#define SOLENOID_PIN 17

// Define weight threshold (in grams)
#define WEIGHT_THRESHOLD 100.0

// Define solenoid activation time (in seconds)
#define SOLENOID_ACTIVATION_TIME 5

// Define timeout for HX711 read (in milliseconds)
#define HX711_TIMEOUT 100

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;

// Function prototypes
long read_hx711();
double convert_to_grams(long raw_value);
void activate_solenoid();
void log_event(double weight);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);

    // Disable solenoid lock
    gpioWrite(SOLENOID_PIN, 0);

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate pigpio
    gpioTerminate();

    exit(0);
}

// Function to read data from HX711
long read_hx711() {
    long count = 0;
    int i;

    gpioSetMode(HX711_DT, PI_INPUT);
    gpioSetMode(HX711_SCK, PI_OUTPUT);

    // Wait for DT to go low
    int timeout_counter = 0;
    while (gpioRead(HX711_DT) == 1) {
        gpioDelay(1); // Small delay to prevent busy-waiting
        timeout_counter++;
        if (timeout_counter > HX711_TIMEOUT) {
            fprintf(stderr, "Error: HX711 DT line stuck high.\n");
            return -1; // Indicate error
        }
    }

    // Read 24 bits of data
    for (i = 0; i < 24; i++) {
        gpioWrite(HX711_SCK, 1);
        gpioDelay(1); // Small delay
        count = count << 1;
        if (gpioRead(HX711_DT) == 1) {
            count++;
        }
        gpioWrite(HX711_SCK, 0);
        gpioDelay(1); // Small delay
    }

    // Pulse SCK 25th time to set the gain to 128
    gpioWrite(HX711_SCK, 1);
    gpioDelay(1); // Small delay
    gpioWrite(HX711_SCK, 0);
    gpioDelay(1); // Small delay

    // Convert to signed 2's complement
    if (count & 0x800000) {
        count |= ~0xffffff;
    }

    return count;
}

// Function to convert raw HX711 value to grams (example calibration)
double convert_to_grams(long raw_value) {
    // Replace with your actual calibration values
    double scale_factor = 1000.0; // Example scale factor
    double offset = 0.0; // Example offset
