#define SOLENOID_PIN 27

// Define constants
#define CALIBRATION_FILE "calibration.txt"
#define LOG_FILE "security.log"
#define WEIGHT_THRESHOLD 5.0 // kg
#define SOLENOID_ON_TIME 5 // seconds
#define TIMEOUT_MS 100

// Global variables
static volatile int running = 1;
static float calibration_factor = 0.0;

// Function prototypes
int read_hx711();
float convert_to_kg(int raw_value, float calibration_factor);
int calibrate_load_cell(float known_weight);
int log_event(float weight);
int control_solenoid(int state);
int load_calibration_factor();
int save_calibration_factor(float calibration_factor);
void signal_handler(int signal);

// Function to read raw data from HX711
int read_hx711() {
    int data = 0;
    int i;

    gpioSetMode(HX711_DATA_PIN, PI_INPUT);
    gpioSetMode(HX711_CLOCK_PIN, PI_OUTPUT);

    // Wait for data line to go low
    int timeout_counter = 0;
    while (gpioRead(HX711_DATA_PIN) == 1) {
        gpioDelay(1); // Wait 1 microsecond
        timeout_counter++;
        if (timeout_counter > TIMEOUT_MS) {
            fprintf(stderr, "Error: HX711 data line timeout\n");
            return -1; // Indicate timeout error
        }
    }

    // Read 24 bits of data
    for (i = 0; i < 24; i++) {
        gpioWrite(HX711_CLOCK_PIN, 1);
        gpioDelay(1); // Clock high delay
        data = data << 1;
        if (gpioRead(HX711_DATA_PIN)) {
            data++;
        }
        gpioWrite(HX711_CLOCK_PIN, 0);
        gpioDelay(1); // Clock low delay
    }

    // Pulse the clock pin 1 more time to set the gain to 128
    gpioWrite(HX711_CLOCK_PIN, 1);
    gpioDelay(1);
    gpioWrite(HX711_CLOCK_PIN, 0);
    gpioDelay(1);

    // Convert to signed 24-bit integer
    if (data & 0x800000) {
        data |= 0xFF000000;
    }

    return data;
}

// Function to convert raw value to kilograms
float convert_to_kg(int raw_value, float calibration_factor) {
    return (float)raw_value / calibration_factor;
}

// Function to calibrate the load cell
int calibrate_load_cell(float known_weight) {
    int raw_value;
    float calibration_factor;

    printf("Place the known weight (%.2f kg) on the load cell.\n", known_weight);
    gpioDelay(5000); // Wait 5 seconds for the user to place the weight

    raw_value = read_hx711();
    if (raw_value == -1) {
        fprintf(stderr, "Error: Failed to read raw value during calibration.\n");
        return -1;
    }

    calibration_factor = (float)raw_value / known_weight;

    if (save_calibration_factor(calibration_factor) != 0) {
        fprintf(stderr, "Error: Failed to save calibration factor.\n");
        return -1;
    }

    printf("Calibration factor saved. New calibration factor: %.2f\n", calibration_factor);
    return 0;
}

// Function to load the calibration factor from file
int load_calibration_factor() {
    FILE *fp = fopen(CALIBRATION_FILE, "r");
    if (fp == NULL) {
        fprintf(stderr, "Error: Calibration file not found. Please calibrate the load cell.\n");
        return -1;
    }

    if (fscanf(fp, "%f", &calibration_factor) != 1) {
        fprintf(stderr, "Error: Failed to read calibration factor from file.\n");
        fclose(fp);
        return -1;
    }

    fclose(fp);
    printf("Calibration factor loaded: %.2f\n", calibration_factor);
    return 0;
}

// Function to save the calibration factor to file
int save_calibration_factor(float calibration_factor) {
    FILE *fp = fopen(CALIBRATION_FILE, "w");
    if (fp == NULL) {
        fprintf(stderr, "Error: Failed to open calibration file for writing.\n");
        return -1;
    }

    if (fprintf(fp, "%f", calibration_factor) < 0) {
        fprintf(stderr, "Error: Failed to write calibration factor to file.\n");
        fclose(fp);
        return -1;
    }

    fclose(fp);
    return 0;
}

