int log_event(float weight) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error: Failed to open log file for writing.\n");
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d - Weight: %.2f kg\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, weight);

    fclose(fp);
    return 0;
}

// Function to control the solenoid
int control_solenoid(int state) {
    gpioSetMode(SOLENOID_PIN, PI_OUTPUT);
    gpioWrite(SOLENOID_PIN, state);
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    running = 0;
    control_solenoid(0); // Unlock the solenoid
    gpioTerminate(); // Terminate pigpio
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Load calibration factor
    if (load_calibration_factor() != 0) {
        fprintf(stderr, "Error: Failed to load calibration factor. Exiting.\n");
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Weight-based Door Lock System\n");

    while (running) {
        // Read raw value from HX711
        int raw_value = read_hx711();
        if (raw_value == -1) {
            fprintf(stderr, "Error: Failed to read raw value. Retrying...\n");
            gpioDelay(100); // Wait before retrying
            continue;
