#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <gpiod.h>

// Define GPIO pins
#define SENSOR_PIN 16
#define RELAY_PIN 20

// Define log file path
#define LOG_FILE "relay_events.log"

// Global variables for GPIO chip and lines
struct gpiod_chip *chip;
struct gpiod_line *sensor_line;
struct gpiod_line *relay_line;

// Function prototypes
int read_sensor();
int toggle_relay(int current_state);
int log_event(int relay_state);
void signal_handler(int sig);

// Signal handler function
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);

    // Release GPIO lines
    if (sensor_line) {
        gpiod_line_release(sensor_line);
    }
    if (relay_line) {
        gpiod_line_release(relay_line);
    }

    // Close GPIO chip
    if (chip) {
        gpiod_chip_close(chip);
    }

    exit(0);
}

// Function to read the sensor value
int read_sensor() {
    int value = gpiod_line_get_value(sensor_line);
    if (value < 0) {
        fprintf(stderr, "Error reading sensor value: %d\n", value);
        return -1; // Indicate error
    }
    return value;
}

// Function to toggle the relay state
int toggle_relay(int current_state) {
    int new_state = !current_state;
    int ret = gpiod_line_set_value(relay_line, new_state);
    if (ret < 0) {
        fprintf(stderr, "Error setting relay value: %d\n", ret);
        return -1; // Indicate error
    }
    return new_state;
}

// Function to log the event to a file
int log_event(int relay_state) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        return -1; // Indicate error
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", tm);

    fprintf(fp, "%s, Relay State: %s\n", timestamp, relay_state ? "ON" : "OFF");
    fclose(fp);
    return 0;
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", "gpiochip0");
        return 1;
    }

    // Get sensor line
    sensor_line = gpiod_chip_get_line(chip, SENSOR_PIN);
    if (!sensor_line) {
        fprintf(stderr, "Error getting sensor line %d\n", SENSOR_PIN);
        gpiod_chip_close(chip);
        return 1;
    }

    // Get relay line
    relay_line = gpiod_chip_get_line(chip, RELAY_PIN);
    if (!relay_line) {
        fprintf(stderr, "Error getting relay line %d\n", RELAY_PIN);
        gpiod_line_release(sensor_line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Request sensor line as input
    struct gpiod_line_request_config sensor_config;
    memset(&sensor_config, 0, sizeof(sensor_config));
    sensor_config.consumer = "sensor";
    sensor_config.request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT;

    int ret = gpiod_line_request_bulk_inputs(sensor_line, &sensor_config, 1);
    if (ret < 0) {
        fprintf(stderr, "Error requesting sensor line as input: %d\n", ret);
        gpiod_line_release(sensor_line);
        gpiod_line_release(relay_line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Request relay line as output
    struct gpiod_line_request_config relay_config;
    memset(&relay_config, 0, sizeof(relay_config));
