        gpiod_chip_close(gpio_chip);
        return -1;
    }

    ret = gpiod_line_request_input(pir_line, "motion_detector");
    if (ret < 0) {
        perror("Error requesting PIR sensor line as input");
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    // Request buzzer pin as output
    buzzer_line = gpiod_chip_get_line(gpio_chip, BUZZER_PIN);
    if (!buzzer_line) {
        perror("Error getting buzzer line");
        gpiod_line_release(pir_line);
        gpiod_chip_close(gpio_chip);
        return -1;
    }

