{
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (init_gpio() < 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return 1;
    }

    printf("Motion detector started. Press Ctrl+C to exit.\n");

    // Main loop
    while (keep_running) {
        int motion_detected = read_pir_sensor();
        if (motion_detected < 0) {
            fprintf(stderr, "Error reading PIR sensor. Continuing.\n");
            usleep(100000); // Sleep for 100ms to avoid spamming errors
            continue;
        }

        if (motion_detected) {
            printf("Motion detected!\n");
            if (log_motion() < 0) {
                fprintf(stderr, "Error logging motion. Continuing.\n");
            }
            if (activate_buzzer() < 0) {
                fprintf(stderr, "Error activating buzzer. Continuing.\n");
            }
            usleep(2000000); // Buzzer on for 2 seconds
            if (deactivate_buzzer() < 0) {
                fprintf(stderr, "Error deactivating buzzer. Continuing.\n");
            }
        }

        usleep(100000); // Check every 100ms
    }

    return 0;
}

