#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>
#include <errno.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_LINE 18
#define CONFIG_FILE "watering.conf"

// Global flag to signal program termination
volatile sig_atomic_t program_running = 1;

// Structure to hold GPIO chip and line information
typedef struct {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
} gpio_context_t;

// Function prototypes
int read_config(const char *filename, int *duration);
int gpio_init(gpio_context_t *context);
int valve_on(gpio_context_t *context);
int valve_off(gpio_context_t *context);
void signal_handler(int sig);
void cleanup(gpio_context_t *context);

// Signal handler function
void signal_handler(int sig) {
    if (sig == SIGINT || sig == SIGTERM) {
        program_running = 0;
        fprintf(stderr, "Signal received, shutting down...\n");
    }
}

// Function to read the watering duration from the configuration file
int read_config(const char *filename, int *duration) {
    FILE *fp = fopen(filename, "r");
    if (fp == NULL) {
        fprintf(stderr, "Error opening config file: %s\n", strerror(errno));
        return -1;
    }

    char line[256];
    if (fgets(line, sizeof(line), fp) == NULL) {
        fprintf(stderr, "Error reading config file: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    fclose(fp);

    // Parse the line
    char *key = strstr(line, "duration=");
    if (key == NULL) {
        fprintf(stderr, "Invalid config file format\n");
        return -1;
    }

    char *value = key + strlen("duration=");
    char *endptr;
    *duration = strtol(value, &endptr, 10);

    if (*endptr != '\0' && *endptr != '\n') {
        fprintf(stderr, "Invalid duration value\n");
        return -1;
    }

    if (*duration <= 0 || *duration > 3600) {
        fprintf(stderr, "Duration out of range (1-3600 seconds)\n");
        return -1;
    }

    return 0;
}

// Function to initialize the GPIO line
int gpio_init(gpio_context_t *context) {
    context->chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!context->chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", strerror(errno));
        return -1;
    }

    context->line = gpiod_chip_get_line(context->chip, GPIO_LINE);
    if (!context->line) {
        fprintf(stderr, "Error getting GPIO line: %s\n", strerror(errno));
        gpiod_chip_close(context->chip);
        return -1;
    }

    struct gpiod_line_request_config config;
    memset(&config, 0, sizeof(config));
    config.consumer = "watering_system";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;
    config.flags = 0; // Active low
    config.value = 0; // Initial value: off

    if (gpiod_line_request(context->line, &config, 0) < 0) {
        fprintf(stderr, "Error requesting GPIO line: %s\n", strerror(errno));
        gpiod_chip_close(context->chip);
        return -1;
    }

    return 0;
}

// Function to turn the valve on
int valve_on(gpio_context_t *context) {
    if (gpiod_line_set_value(context->line, 1) < 0) {
        fprintf(stderr, "Error setting GPIO line high: %s\n", strerror(errno));
        return -1;
    }
    printf("Valve ON\n");
    return 0;
}

// Function to turn the valve off
int valve_off(gpio_context_t *context) {
    if (gpiod_line_set_value(context->line, 0) < 0) {
        fprintf(stderr, "Error setting GPIO line low: %s\n", strerror(errno));
        return -1;
    }
    printf("Valve OFF\n");
    return 0;
}

// Function to clean up GPIO resources
void cleanup(gpio_context_t *context) {
    if (context->line) {
        gpiod_line_release(context->line);
    }
    if (context->chip) {
        gpiod_chip_close(context->chip);
    }
}

int main() {
    gpio_context_t gpio_context = {0};
    int duration;

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Read configuration
    if (read_config(CONFIG_FILE, &duration) != 0) {
        fprintf(stderr, "Failed to read configuration. Exiting.\n");
        cleanup(&gpio_context);
        return 1;
    }

    printf("Using duration: %d seconds\n", duration);

    // Initialize GPIO
    if (gpio_init(&gpio_context) != 0) {
        fprintf(stderr, "Failed to initialize GPIO. Exiting.\n");
        cleanup(&gpio_context);
        return 1;
    }

    // Turn valve on
    if (valve_on(&gpio_context) != 0) {
        fprintf(stderr, "Failed to turn valve on. Exiting.\n");
        cleanup(&gpio_context);
        return 1;
    }

    // Wait for the configured duration
    sleep(duration);

    // Turn valve off
    if (valve_off(&gpio_context) != 0) {
        fprintf(stderr, "Failed to turn valve off. Exiting.\n");
        cleanup(&gpio_context);
        return 1;
    }

    // Clean up GPIO resources
    cleanup(&gpio_context);

    printf("Watering system finished.\n");
    return 0;
}

