#define MIDDLE_SENSOR_PIN 17
#define RIGHT_SENSOR_PIN 27

#define LEFT_MOTOR_IN1 22
#define LEFT_MOTOR_IN2 23
#define RIGHT_MOTOR_IN3 24
#define RIGHT_MOTOR_IN4 25

#define PWM_FREQUENCY 1000 // 1 kHz

// Define motor speeds
#define BASE_SPEED 150
#define TURN_SPEED (BASE_SPEED / 2)

// Global variables
FILE *log_file;
int running = 1;

// Function prototypes
int initialize_gpio();
int read_sensors();
void control_motors(int left_speed, int right_speed);
void log_data(int left_sensor, int middle_sensor, int right_sensor, int left_speed, int right_speed);
void signal_handler(int signal);

// Structure to hold sensor data
typedef struct {
    int left;
    int middle;
    int right;
} SensorData;

// Structure to hold motor data
typedef struct {
    int left_speed;
    int right_speed;
} MotorData;

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize pigpio
    if (initialize_gpio() != 0) {
        fprintf(stderr, "Failed to initialize pigpio. Exiting.\n");
        return 1;
    }

    // Open log file
    log_file = fopen("trace_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file. Exiting.\n");
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (running) {
        // Read sensor data
        SensorData sensors = read_sensors();

        // Determine motor speeds based on sensor readings
        MotorData motor_data;
        if (sensors.middle == 0) {
            motor_data.left_speed = BASE_SPEED;
            motor_data.right_speed = BASE_SPEED;
        } else if (sensors.left == 0) {
            motor_data.left_speed = TURN_SPEED;
            motor_data.right_speed = BASE_SPEED;
        } else if (sensors.right == 0) {
            motor_data.left_speed = BASE_SPEED;
            motor_data.right_speed = TURN_SPEED;
        } else {
            motor_data.left_speed = 0;
            motor_data.right_speed = 0;
        }

