        gpioWrite(RIGHT_MOTOR_IN4, 0);
        gpioPWM(RIGHT_MOTOR_IN3, right_speed);
    } else {
        gpioWrite(RIGHT_MOTOR_IN3, 0);
        gpioWrite(RIGHT_MOTOR_IN4, 0);
    }
}

// Log data to file
void log_data(int left_sensor, int middle_sensor, int right_sensor, int left_speed, int right_speed) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", timeinfo);

    fprintf(log_file, "%s,%d,%d,%d,%d,%d\n", timestamp, left_sensor, middle_sensor, right_sensor, left_speed, right_speed);
    fflush(log_file); // Ensure data is written to file immediately
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("Ctrl+C pressed. Exiting gracefully.\n");
    running = 0;
}

