#define MOTOR2_PULSE_DURATION 300

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, stopping motors and exiting...\n", signal);
}

// Function to pulse a motor
void pulse_motor(int gpio, int duration_ms) {
    gpioWrite(gpio, 1); // Turn motor on
    gpioDelay(duration_ms * 1000); // Delay for specified duration (microseconds)
    gpioWrite(gpio, 0); // Turn motor off
}

int main() {
    // Register signal handlers for SIGINT and SIGTERM
    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        perror("Failed to register SIGINT handler");
        return 1;
