    // Set GPIO pins as outputs
    gpioSetMode(MOTOR1_GPIO, PI_OUTPUT);
    gpioSetMode(MOTOR2_GPIO, PI_OUTPUT);

    printf("Haptic feedback system started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        pulse_motor(MOTOR1_GPIO, MOTOR1_PULSE_DURATION);
        pulse_motor(MOTOR2_GPIO, MOTOR2_PULSE_DURATION);
    }

    // Stop motors and release GPIO lines
    gpioWrite(MOTOR1_GPIO, 0);
    gpioWrite(MOTOR2_GPIO, 0);
    gpioTerminate();

    printf("Haptic feedback system stopped.\n");

    return 0;
}

