#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>
#include <zmq.h>
#include <errno.h>

// Define GPIO pins
#define SOUND_SENSOR_PIN 17
#define LED_PIN 27

// Define ZeroMQ address and topic
#define ZMQ_ADDRESS "tcp://*:5555"
#define ZMQ_TOPIC "SOUND_ALERTS"

// Define debounce delay (in milliseconds)
#define DEBOUNCE_DELAY_MS 50

// Global variables for GPIO chip and lines
struct gpiod_chip *chip;
struct gpiod_line *sound_line;
struct gpiod_line *led_line;

// Global variable for ZeroMQ context
void *context = NULL;
void *publisher = NULL;
void *subscriber = NULL;

// Function prototypes
int init_gpio(void);
int init_zmq(void);
void cleanup_gpio(void);
void cleanup_zmq(void);
void signal_handler(int sig);

// Function to initialize GPIO pins
int init_gpio(void) {
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    sound_line = gpiod_chip_get_line(chip, SOUND_SENSOR_PIN);
    if (!sound_line) {
        perror("Error getting sound sensor line");
        gpiod_chip_close(chip);
        return -1;
    }

    led_line = gpiod_chip_get_line(chip, LED_PIN);
    if (!led_line) {
        perror("Error getting LED line");
        gpiod_line_release(sound_line);
        gpiod_chip_close(chip);
        return -1;
    }

    struct gpiod_line_request_config config;
    memset(&config, 0, sizeof(config));
    config.consumer = "sound_alarm";

    // Request sound sensor pin as input
    if (gpiod_line_request(sound_line, &config, GPIOD_LINE_REQUEST_DIRECTION_INPUT) < 0) {
        perror("Error requesting sound sensor line");
        gpiod_line_release(led_line);
        gpiod_line_release(sound_line);
        gpiod_chip_close(chip);
        return -1;
    }

    // Request LED pin as output
    if (gpiod_line_request(led_line, &config, GPIOD_LINE_REQUEST_DIRECTION_OUTPUT) < 0) {
        perror("Error requesting LED line");
        gpiod_line_release(sound_line);
        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
        return -1;
    }

    return 0;
}

// Function to initialize ZeroMQ
int init_zmq(void) {
    context = zmq_ctx_new();
    if (!context) {
        perror("Error creating ZeroMQ context");
        return -1;
    }

    if (strcmp(getenv("MODE"), "sound_sensor") == 0) {
        publisher = zmq_socket(context, ZMQ_PUB);
        if (!publisher) {
            perror("Error creating ZeroMQ publisher socket");
            zmq_ctx_destroy(context);
            return -1;
        }

        int rc = zmq_bind(publisher, ZMQ_ADDRESS);
        if (rc != 0) {
            perror("Error binding ZeroMQ publisher socket");
            zmq_close(publisher);
            zmq_ctx_destroy(context);
            return -1;
        }
    } else {
        subscriber = zmq_socket(context, ZMQ_SUB);
        if (!subscriber) {
            perror("Error creating ZeroMQ subscriber socket");
            zmq_ctx_destroy(context);
            return -1;
        }

        int rc = zmq_connect(subscriber, ZMQ_ADDRESS);
        if (rc != 0) {
            perror("Error connecting ZeroMQ subscriber socket");
            zmq_close(subscriber);
            zmq_ctx_destroy(context);
            return -1;
        }

        rc = zmq_setsockopt(subscriber, ZMQ_SUBSCRIBE, ZMQ_TOPIC, strlen(ZMQ_TOPIC));
        if (rc != 0) {
            perror("Error setting ZeroMQ subscriber options");
            zmq_close(subscriber);
            zmq_ctx_destroy(context);
            return -1;
        }
    }

    return 0;
}

// Function to cleanup GPIO pins
void cleanup_gpio(void) {
    if (sound_line) {
        gpiod_line_release(sound_line);
    }
    if (led_line) {
        gpiod_line_release(led_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
}

// Function to cleanup ZeroMQ sockets and context
void cleanup_zmq(void) {
    if (publisher) {
        zmq_close(publisher);
    }
    if (subscriber) {
        zmq_close(subscriber);
    }
    if (context) {
        zmq_ctx_destroy(context);
    }
}

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    printf("Caught signal %d, cleaning up...\n", sig);
    cleanup_gpio();
    cleanup_zmq();
    exit(0);
}

int main(int argc, char *argv[]) {
    // Set the mode based on the command-line argument
    if (argc > 1) {
        setenv("MODE", argv[1], 1);
    } else {
        fprintf(stderr, "Usage: %s <mode> (sound_sensor or alarm_node)\n", argv[0]);
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (init_gpio() != 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return 1;
    }

    // Initialize ZeroMQ
    if (init_zmq() != 0) {
        fprintf(stderr, "ZeroMQ initialization failed. Exiting.\n");
        cleanup_gpio();
        return 1;
    }

    if (strcmp(getenv("MODE"), "sound_sensor") == 0) {
        // Sound sensor mode
        printf("Sound sensor mode started.\n");
        while (1) {
            // Read sound sensor value
            int value = gpiod_line_get_value(sound_line);
            if (value < 0) {
                perror("Error reading sound sensor value");
                break;
            }

            // Check if sound is detected (active-low)
            if (value == 0) {
                // Publish alert via ZeroMQ
                zmq_msg_t message;
                zmq_msg_init_size(&message, strlen(ZMQ_TOPIC));
                memcpy(zmq_msg_data(&message), ZMQ_TOPIC, zmq_msg_size(&message));

                int rc = zmq_msg_send(&message, publisher, 0);
                if (rc == -1) {
                    perror("Error sending ZeroMQ message");
                    break;
                }

                zmq_msg_close(&message);

                // Debounce delay
                struct timespec delay;
                delay.tv_sec = 0;
                delay.tv_nsec = DEBOUNCE_DELAY_MS * 1000000; // Convert milliseconds to nanoseconds
                nanosleep(&delay, NULL);
            }

            // Small delay to avoid busy-waiting
            struct timespec sleep_time;
            sleep_time.tv_sec = 0;
            sleep_time.tv_nsec = 10 * 1000000; // 10 milliseconds
            nanosleep(&sleep_time, NULL);
        }
    } else {
        // Alarm node mode
        printf("Alarm node mode started.\n");
        while (1) {
            // Receive message from ZeroMQ
            zmq_msg_t message;
            zmq_msg_init(&message);
            int rc = zmq_msg_recv(&message, subscriber, 0);
            if (rc == -1) {
                perror("Error receiving ZeroMQ message");
                break;
            }

            // Check if the received message matches the topic
            if (strncmp(ZMQ_TOPIC, zmq_msg_data(&message), strlen(ZMQ_TOPIC)) == 0) {
                // Activate LED for 1 second
                if (gpiod_line_set_value(led_line, 1) < 0) {
                    perror("Error setting LED value");
                    break;
                }
                struct timespec led_on_time;
                led_on_time.tv_sec = 1;
                led_on_time.tv_nsec = 0;
                nanosleep(&led_on_time, NULL);

                if (gpiod_line_set_value(led_line, 0) < 0) {
                    perror("Error setting LED value");
                    break;
                }
            }

            zmq_msg_close(&message);
        }
    }

    // Cleanup and exit
    cleanup_gpio();
    cleanup_zmq();
    return 0;
}

