static unsigned int pulse_buffer[MAX_PULSES];
static int pulse_count = 0;
static int last_tick = 0;
static struct mosquitto *mosq = NULL;
static pthread_mutex_t pulse_mutex = PTHREAD_MUTEX_INITIALIZER;

// Function prototypes
void signal_handler(int sig);
int init_gpio();
int init_mqtt();
void ir_callback(int gpio, int level, uint32_t tick);
int decode_nec(unsigned int *pulses, int count, unsigned int *address, unsigned int *command);
int validate_checksum(unsigned int address, unsigned int command);
int publish_mqtt(unsigned int address, unsigned int command);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    syslog(LOG_INFO, "Signal received, exiting...");
    running = 0;
}

// Initialize GPIO using pigpio
int init_gpio() {
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        return -1;
    }

    gpioSetMode(GPIO_PIN, PI_INPUT);
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_UP);

    return 0;
}

// Initialize MQTT client using paho-mqtt
int init_mqtt() {
    mosquitto_lib_init();
    mosq = mosquitto_new(NULL, true, NULL);
    if (!mosq) {
        syslog(LOG_ERR, "Failed to create mosquitto instance");
        return -1;
    }

    int rc = mosquitto_connect(mosq, MQTT_HOST, MQTT_PORT, 60);
    if (rc != MOSQ_ERR_SUCCESS) {
        syslog(LOG_ERR, "Failed to connect to MQTT broker: %s", mosquitto_strerror(rc));
        mosquitto_destroy(mosq);
        mosquitto_lib_cleanup();
        return -1;
    }

    mosquitto_loop_start(mosq);
    return 0;
}

// Callback function for IR signal changes
void ir_callback(int gpio, int level, uint32_t tick) {
    if (level != PI_OFF) {
        return; // Ignore rising edges
    }

    pthread_mutex_lock(&pulse_mutex);
    if (pulse_count < MAX_PULSES) {
        pulse_buffer[pulse_count++] = tick;
    } else {
        syslog(LOG_WARNING, "Pulse buffer overflow");
    }
    pthread_mutex_unlock(&pulse_mutex);
}

// Decode NEC IR signal
int decode_nec(unsigned int *pulses, int count, unsigned int *address, unsigned int *command) {
    if (count < 34) {
        syslog(LOG_WARNING, "Too few pulses to decode NEC");
        return -1;
    }

    if (pulses[0] - last_tick < NEC_HEADER_MARK * 0.8 || pulses[0] - last_tick > NEC_HEADER_MARK * 1.2) {
        syslog(LOG_WARNING, "Invalid header mark");
        return -1;
    }

    if (pulses[1] - pulses[0] < NEC_HEADER_SPACE * 0.8 || pulses[1] - pulses[0] > NEC_HEADER_SPACE * 1.2) {
        syslog(LOG_WARNING, "Invalid header space");
        return -1;
    }

    unsigned int data = 0;
    for (int i = 2; i < 34; i += 2) {
        if (pulses[i + 1] - pulses[i] > NEC_SPACE_1 * 0.8) {
            data = (data << 1) | 1;
        } else if (pulses[i + 1] - pulses[i] > NEC_SPACE_0 * 0.8 && pulses[i + 1] - pulses[i] < NEC_SPACE_0 * 1.2) {
            data = (data << 1) | 0;
        } else {
            syslog(LOG_WARNING, "Invalid bit space");
            return -1;
        }
    }

    *address = data & 0xFFFF;
    *command = (data >> 16) & 0xFFFF;

    return 0;
}

// Validate NEC checksum
int validate_checksum(unsigned int address, unsigned int command) {
    return ((address ^ (address >> 8)) == ((command >> 8) ^ command));
}

// Publish decoded command to MQTT broker
int publish_mqtt(unsigned int address, unsigned int command) {
    char payload[100];
    snprintf(payload, sizeof(payload), "{\"address\": 0x%04X, \"command\": 0x%04X}", address, command);

    int rc = mosquitto_publish(mosq, NULL, MQTT_TOPIC, strlen(payload), payload, 0, false);
    if (rc != MOSQ_ERR_SUCCESS) {
        syslog(LOG_ERR, "Failed to publish message: %s", mosquitto_strerror(rc));
        return -1;
    }

    return 0;
}

// Cleanup resources before exiting
void cleanup() {
    syslog(LOG_INFO, "Cleaning up...");
    if (mosq) {
        mosquitto_disconnect(mosq);
        mosquitto_destroy(mosq);
        mosquitto_lib_cleanup();
    }
    gpioTerminate();
    closelog();
    pthread_mutex_destroy(&pulse_mutex);
}

