    // Initialize syslog
    openlog("ir_decoder", LOG_PID | LOG_CONS, LOG_USER);

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (init_gpio() != 0) {
        syslog(LOG_ERR, "GPIO initialization failed, exiting");
        cleanup();
        return 1;
    }

    // Initialize MQTT
    if (init_mqtt() != 0) {
        syslog(LOG_ERR, "MQTT initialization failed, exiting");
        cleanup();
        return 1;
    }

    // Set up alert callback
    gpioSetAlertFuncEx(GPIO_PIN, ir_callback, NULL);

    syslog(LOG_INFO, "IR decoder started");

    while (running) {
        if (pulse_count >= 34) {
            unsigned int address, command;
            pthread_mutex_lock(&pulse_mutex);
            if (decode_nec(pulse_buffer, pulse_count, &address, &command) == 0) {
                if (validate_checksum(address, command)) {
                    syslog(LOG_INFO, "Decoded address: 0x%04X, command: 0x%04X", address, command);
                    if (publish_mqtt(address, command) != 0) {
                        syslog(LOG_ERR, "Failed to publish MQTT message");
                    }
                } else {
