#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <signal.h>
#include <errno.h>
#include <math.h>

#define I2C_DEVICE "/dev/i2c-1"
#define MULTICAST_ADDR "239.255.255.250"
#define MULTICAST_PORT 5005
#define NUM_SENSORS 4

// Sensor addresses
const int sensor_addresses[NUM_SENSORS] = {0x23, 0x24, 0x25, 0x26};

// Global flag for signal handling
volatile sig_atomic_t terminate = 0;

// Signal handler function
void signal_handler(int sig) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating...\n", sig);
}

// Function to read light level from a BH1750FVI sensor
float read_bh1750(int fd, int address) {
    unsigned char data[2];
    int result;

    // Write the One-Time High-Resolution mode command
    result = write(fd, "\x20", 1);
    if (result != 1) {
        fprintf(stderr, "Error writing to I2C device at address 0x%02X: %s\n", address, strerror(errno));
        return NAN;
    }

    // Wait for conversion (at least 180ms)
    usleep(180000); // 180ms

    // Read 2 bytes of data
    result = read(fd, data, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading from I2C device at address 0x%02X: %s\n", address, strerror(errno));
        return NAN;
    }

    // Convert big-endian data to lux
    unsigned int raw_value = (data[0] << 8) | data[1];
    float lux = (float)raw_value / 1.2;

    return lux;
}

// Function to format sensor data into a string
char* format_sensor_data(float lux1, float lux2, float lux3, float lux4) {
    char *buffer = malloc(256 * sizeof(char)); // Allocate memory for the string
    if (buffer == NULL) {
        fprintf(stderr, "Memory allocation error\n");
        return NULL;
    }
    snprintf(buffer, 256, "1,%.2f;2,%.2f;3,%.2f;4,%.2f", lux1, lux2, lux3, lux4);
    return buffer;
}

// Function to send data via UDP multicast
int send_udp_multicast(const char *data) {
    int sockfd;
    struct sockaddr_in addr;
    int ttl = 1;

    // Create socket
    sockfd = socket(AF_INET, SOCK_DGRAM, 0);
    if (sockfd < 0) {
        fprintf(stderr, "Error creating socket: %s\n", strerror(errno));
        return -1;
    }

    // Set TTL for multicast
    if (setsockopt(sockfd, IPPROTO_IP, IP_MULTICAST_TTL, (void *)&ttl, sizeof(ttl)) < 0) {
        fprintf(stderr, "Error setting TTL: %s\n", strerror(errno));
        close(sockfd);
        return -1;
    }

    // Configure destination address
    memset(&addr, 0, sizeof(addr));
    addr.sin_family = AF_INET;
    addr.sin_addr.s_addr = inet_addr(MULTICAST_ADDR);
    addr.sin_port = htons(MULTICAST_PORT);

    // Send data
    if (sendto(sockfd, data, strlen(data), 0, (struct sockaddr *)&addr, sizeof(addr)) < 0) {
        fprintf(stderr, "Error sending data: %s\n", strerror(errno));
        close(sockfd);
        return -1;
    }

    // Close socket
    close(sockfd);
    return 0;
}

int main() {
    int i2c_fds[NUM_SENSORS];
    float lux_values[NUM_SENSORS];
    char *data_string;
    int i;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C devices
    for (i = 0; i < NUM_SENSORS; i++) {
        char filename[20];
        snprintf(filename, 19, I2C_DEVICE);
        i2c_fds[i] = open(filename, O_RDWR);
        if (i2c_fds[i] < 0) {
            fprintf(stderr, "Error opening I2C device %s: %s\n", filename, strerror(errno));
            lux_values[i] = NAN; // Set to NaN to indicate error
            continue;
        }

        // Set I2C slave address
        if (ioctl(i2c_fds[i], I2C_SLAVE, sensor_addresses[i]) < 0) {
            fprintf(stderr, "Error setting I2C slave address 0x%02X: %s\n", sensor_addresses[i], strerror(errno));
            lux_values[i] = NAN; // Set to NaN to indicate error
            close(i2c_fds[i]);
            continue;
        }
    }

    // Main loop
    while (!terminate) {
        // Read light levels from each sensor
        for (i = 0; i < NUM_SENSORS; i++) {
            if (!isnan(lux_values[i])) {
                lux_values[i] = read_bh1750(i2c_fds[i], sensor_addresses[i]);
            }
        }

        // Format sensor data
        data_string = format_sensor_data(lux_values[0], lux_values[1], lux_values[2], lux_values[3]);
        if (data_string != NULL) {
            // Send data via UDP multicast
            if (send_udp_multicast(data_string) != 0) {
                fprintf(stderr, "Error sending UDP multicast data\n");
            }

            // Free allocated memory
            free(data_string);
        }

        // Wait for 1 second
        sleep(1);
    }

    // Close I2C devices
    for (i = 0; i < NUM_SENSORS; i++) {
        if (i2c_fds[i] >= 0) {
            close(i2c_fds[i]);
        }
    }

    return 0;
}

