#include <signal.h>
#include <errno.h>

#define I2C_BUS "/dev/i2c-1"
#define I2C_ADDRESS 0x28
#define LOG_FILE "airflow_log.txt"
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 100

volatile sig_atomic_t program_running = 1;
int i2c_fd = -1;
FILE *log_file = NULL;

void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

int i2c_read_flow(int fd, uint16_t *flow_raw) {
    unsigned char buffer[2];
    int retries = 0;
    int bytes_read;

    while (retries < MAX_RETRIES) {
        if (write(fd, "", 0) != 0) {
            fprintf(stderr, "Error starting I2C transaction: %s\n", strerror(errno));
            retries++;
            usleep(RETRY_DELAY_MS * 1000);
            continue;
        }

        bytes_read = read(fd, buffer, 2);
        if (bytes_read == 2) {
            *flow_raw = (buffer[0] << 8) | buffer[1];
            return 0; // Success
        } else {
            fprintf(stderr, "I2C read error: %s (bytes read: %d, retries: %d)\n", strerror(errno), bytes_read, retries);
            retries++;
            usleep(RETRY_DELAY_MS * 1000);
        }
    }

    fprintf(stderr, "Failed to read flow data after %d retries.\n", MAX_RETRIES);
    return -1; // Failure
}

float convert_to_slpm(uint16_t raw_flow) {
    return (raw_flow - 3277) * 0.1;
}

int log_flow_data(float flow_rate) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (log_file == NULL) {
        fprintf(stderr, "Log file is not open.\n");
        return -1;
    }

    if (fprintf(log_file, "%s, %.2f SLPM\n", timestamp, flow_rate) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        return -1;
    }

    fflush(log_file);
    return 0;
}

int main() {
    uint16_t raw_flow;
    float flow_rate;

    // Install signal handler
    signal(SIGINT, signal_handler);

    // Open I2C device
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C device: %s\n", strerror(errno));
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDRESS) < 0) {
        fprintf(stderr, "Error setting I2C slave address: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    printf("Airflow monitoring started. Press Ctrl+C to exit.\n");

    while (program_running) {
        if (i2c_read_flow(i2c_fd, &raw_flow) == 0) {
            flow_rate = convert_to_slpm(raw_flow);
            if (log_flow_data(flow_rate) != 0) {
                fprintf(stderr, "Error logging flow data.\n");
            }
        } else {
            fprintf(stderr, "Error reading flow data.\n");
        }

        sleep(1);
    }

    // Cleanup
    close(i2c_fd);
    fclose(log_file);

    printf("Airflow monitoring stopped.\n");
    return 0;
}

