#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

// AS7341 I2C Address
#define AS7341_ADDR 0x39

// AS7341 Register Addresses
#define AS7341_WHO_AM_I 0x24
#define AS7341_ENABLE 0x80
#define AS7341_CFG6 0xAF
#define AS7341_SP_EN 0x70
#define AS7341_F1DATAH 0x60
#define AS7341_F1DATAL 0x61
#define AS7341_F2DATAH 0x62
#define AS7341_F2DATAL 0x63
#define AS7341_F3DATAH 0x64
#define AS7341_F3DATAL 0x65
#define AS7341_F4DATAH 0x66
#define AS7341_F4DATAL 0x67
#define AS7341_F5DATAH 0x68
#define AS7341_F5DATAL 0x69
#define AS7341_F6DATAH 0x6A
#define AS7341_F6DATAL 0x6B
#define AS7341_F7DATAH 0x6C
#define AS7341_F7DATAL 0x6D
#define AS7341_F8DATAH 0x6E
#define AS7341_F8DATAL 0x6F
#define AS7341_CDATAH 0x72
#define AS7341_CDATAL 0x73
#define AS7341_NIRDATAH 0x74
#define AS7341_NIRDATAL 0x75

// I2C File Descriptor
int i2c_fd = -1;

// Log File Pointer
FILE *log_file = NULL;

// Function Prototypes
int i2c_write_reg(int fd, uint8_t reg, uint8_t value);
int i2c_read_reg(int fd, uint8_t reg, uint8_t *value);
int as7341_init(int fd);
int as7341_read_channels(int fd, uint16_t *channels);
float as7341_calculate_lux(uint16_t *channels);
int log_data(FILE *fp, uint16_t *channels, float lux);
void signal_handler(int sig);

// Signal Handler
void signal_handler(int sig) {
    fprintf(stderr, "\nCaught signal %d, cleaning up...\n", sig);
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    exit(0);
}

// I2C Write Register Function
int i2c_write_reg(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2];
    buf[0] = reg;
    buf[1] = value;
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "Error writing to I2C device: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// I2C Read Register Function
int i2c_read_reg(int fd, uint8_t reg, uint8_t *value) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "Error writing register address to I2C device: %s\n", strerror(errno));
        return -1;
    }
    if (read(fd, value, 1) != 1) {
        fprintf(stderr, "Error reading from I2C device: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// AS7341 Initialization Function
int as7341_init(int fd) {
    uint8_t who_am_i;

    // Verify WHO_AM_I register
    if (i2c_read_reg(fd, AS7341_WHO_AM_I, &who_am_i) != 0) {
        fprintf(stderr, "Error reading WHO_AM_I register\n");
        return -1;
    }
    if (who_am_i != 0x19) {
        fprintf(stderr, "WHO_AM_I register returned 0x%02X, expected 0x19\n", who_am_i);
        return -1;
    }

    // Enable the sensor
    if (i2c_write_reg(fd, AS7341_ENABLE, 0x01) != 0) {
        fprintf(stderr, "Error enabling sensor\n");
        return -1;
    }

    // Configure SMUX for spectral readings
    if (i2c_write_reg(fd, AS7341_CFG6, 0x00) != 0) {
        fprintf(stderr, "Error configuring SMUX\n");
        return -1;
    }

    // Enable spectral measurement
    if (i2c_write_reg(fd, AS7341_SP_EN, 0x01) != 0) {
        fprintf(stderr, "Error enabling spectral measurement\n");
        return -1;
    }

    return 0;
}

// AS7341 Read Channels Function
int as7341_read_channels(int fd, uint16_t *channels) {
    uint8_t data[2];
    int i;

    for (i = 0; i < 10; i++) {
        uint8_t reg_addr;
        switch (i) {
            case 0: reg_addr = AS7341_F1DATAH; break;
            case 1: reg_addr = AS7341_F2DATAH; break;
            case 2: reg_addr = AS7341_F3DATAH; break;
            case 3: reg_addr = AS7341_F4DATAH; break;
            case 4: reg_addr = AS7341_F5DATAH; break;
            case 5: reg_addr = AS7341_F6DATAH; break;
            case 6: reg_addr = AS7341_F7DATAH; break;
            case 7: reg_addr = AS7341_F8DATAH; break;
            case 8: reg_addr = AS7341_CDATAH; break;
            case 9: reg_addr = AS7341_NIRDATAH; break;
            default: fprintf(stderr, "Invalid channel index\n"); return -1;
        }

        if (i2c_read_reg(fd, reg_addr, &data[0]) != 0) {
            fprintf(stderr, "Error reading high byte from channel %d\n", i);
            return -1;
        }
        if (i2c_read_reg(fd, reg_addr + 1, &data[1]) != 0) {
            fprintf(stderr, "Error reading low byte from channel %d\n", i);
            return -1;
        }

        channels[i] = (data[0] << 8) | data[1];
    }

    return 0;
}

// AS7341 Calculate Lux Function
float as7341_calculate_lux(uint16_t *channels) {
    // Simplified lux approximation (replace with a more accurate formula if needed)
    float lux = (float)channels[8] * 0.01; // Using Clear channel for approximation
    return lux;
}

// Log Data Function
int log_data(FILE *fp, uint16_t *channels, float lux) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(fp, "%s,%u,%u,%u,%u,%u,%u,%u,%u,%u,%u,%.2f\n",
            timestamp, channels[0], channels[1], channels[2], channels[3], channels[4],
            channels[5], channels[6], channels[7], channels[8], channels[9], lux);
    fflush(fp); // Ensure data is written to file immediately
    return 0;
}

int main() {
    uint16_t channels[10];
    float lux;

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open I2C device
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C device: %s\n", strerror(errno));
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, AS7341_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    // Initialize AS7341 sensor
    if (as7341_init(i2c_fd) != 0) {
        fprintf(stderr, "AS7341 initialization failed\n");
        close(i2c_fd);
        return 1;
    }

    // Open log file
    log_file = fopen("spectral_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (1) {
        // Read sensor data
        if (as7341_read_channels(i2c_fd, channels) == 0) {
            // Calculate lux
            lux = as7341_calculate_lux(channels);

            // Log data
            if (log_data(log_file, channels, lux) != 0) {
                fprintf(stderr, "Error logging data\n");
            }
        } else {
            fprintf(stderr, "Error reading sensor data\n");
        }

        // Wait 5 seconds
        sleep(5);
    }

    // The following lines will never be reached due to the infinite loop.
    // However, they are included for completeness and to demonstrate proper cleanup.
    close(i2c_fd);
    fclose(log_file);
    return 0;
}

