typedef struct {
    double x_g;
    double y_g;
    double z_g;
} sensor_data_t;

// Global variables
int i2c_fd = -1;
int i2c_address = DEFAULT_I2C_ADDRESS;
int interval = DEFAULT_INTERVAL;
char *filename = DEFAULT_FILENAME;
FILE *data_file = NULL;
FILE *error_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int i2c_read_data(int fd, uint8_t reg_addr, uint8_t *data, int len);
int i2c_write_data(int fd, uint8_t reg_addr, uint8_t data);
sensor_data_t read_sensor_data(int fd);
void log_data(FILE *fp, sensor_data_t data);
void log_error(FILE *fp, const char *message);
void signal_handler(int sig);
int setup();
void cleanup();

// I2C read function with retry and error handling
int i2c_read_data(int fd, uint8_t reg_addr, uint8_t *data, int len) {
    int retries = 0;
    int result;

    while (retries < MAX_RETRIES) {
        if (ioctl(fd, I2C_SLAVE, i2c_address) < 0) {
            log_error(error_file, "Failed to acquire bus access and/or talk to slave.");
            retries++;
            usleep(BACKOFF_MS * 1000); // Exponential backoff
            continue;
        }

        if (write(fd, &reg_addr, 1) != 1) {
            log_error(error_file, "Failed to write register address.");
            retries++;
            usleep(BACKOFF_MS * 1000);
            continue;
        }

        result = read(fd, data, len);
        if (result == len) {
            return 0; // Success
        } else {
            log_error(error_file, "Failed to read data from sensor.");
            retries++;
            usleep(BACKOFF_MS * 1000);
        }
    }

    log_error(error_file, "Max retries reached for I2C read.");
    return -1; // Failure
}

// I2C write function with retry and error handling
int i2c_write_data(int fd, uint8_t reg_addr, uint8_t data) {
    int retries = 0;
    int result;

    while (retries < MAX_RETRIES) {
        if (ioctl(fd, I2C_SLAVE, i2c_address) < 0) {
