#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <signal.h>
#include <errno.h>
#include <stdint.h>

#define I2C_ADDR 0x23
#define I2C_BUS "/dev/i2c-1"
#define MULTICAST_ADDR "239.255.255.250"
#define MULTICAST_PORT 5000
#define TTL 1

int i2c_fd = -1;
int udp_socket = -1;

// Function to initialize the BH1750 sensor
int init_bh1750(int fd) {
    uint8_t power_on_cmd = 0x01;
    uint8_t continuous_high_res_cmd = 0x10;

    if (write(fd, &power_on_cmd, 1) != 1) {
        perror("Failed to send power-on command");
        return -1;
    }
    usleep(20000); // Wait 20ms

    if (write(fd, &continuous_high_res_cmd, 1) != 1) {
        perror("Failed to send continuous high-resolution mode command");
        return -1;
    }
    usleep(20000); // Wait 20ms

    return 0;
}

// Function to read the raw light value from the BH1750 sensor
int read_bh1750(int fd, uint16_t *raw_value) {
    uint8_t buffer[2];

    if (read(fd, buffer, 2) != 2) {
        perror("Failed to read light value");
        return -1;
    }

    // Convert big-endian to host byte order
    *raw_value = (buffer[0] << 8) | buffer[1];

    return 0;
}

// Function to convert the raw light value to lux
float convert_to_lux(uint16_t raw_value) {
    return (float)raw_value / 1.2;
}

// Function to send the lux value over UDP multicast
int send_udp_multicast(float lux_value) {
    struct sockaddr_in addr;
    socklen_t addrlen = sizeof(addr);
    char buffer[32];

    // Format the lux value as a string
    snprintf(buffer, sizeof(buffer), "%.2f", lux_value);

    // Configure the multicast address
    memset(&addr, 0, sizeof(addr));
    addr.sin_family = AF_INET;
    addr.sin_addr.s_addr = inet_addr(MULTICAST_ADDR);
    addr.sin_port = htons(MULTICAST_PORT);

    // Set the TTL for the multicast packet
    int ttl = TTL;
    if (setsockopt(udp_socket, IPPROTO_IP, IP_MULTICAST_TTL, &ttl, sizeof(ttl)) < 0) {
        perror("Failed to set TTL");
        return -1;
    }

    // Send the data
    if (sendto(udp_socket, buffer, strlen(buffer), 0, (struct sockaddr *)&addr, addrlen) < 0) {
        perror("Failed to send UDP multicast");
        return -1;
    }

    return 0;
}

// Signal handler for SIGINT and SIGTERM
void signal_handler(int signum) {
    printf("Caught signal %d, cleaning up...\n", signum);

    // Close the I2C file descriptor if it's open
    if (i2c_fd != -1) {
        close(i2c_fd);
    }

    // Close the UDP socket if it's open
    if (udp_socket != -1) {
        close(udp_socket);
    }

    exit(0);
}

int main() {
    uint16_t raw_value;
    float lux_value;

    // Register signal handlers for SIGINT and SIGTERM
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open the I2C device
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    // Set the I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    // Initialize the BH1750 sensor
    if (init_bh1750(i2c_fd) < 0) {
        close(i2c_fd);
        return 1;
    }

    // Create the UDP socket
    udp_socket = socket(AF_INET, SOCK_DGRAM, 0);
    if (udp_socket < 0) {
        perror("Failed to create UDP socket");
        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (1) {
        // Read the raw light value
        if (read_bh1750(i2c_fd, &raw_value) < 0) {
            fprintf(stderr, "Error reading sensor, retrying in 1 second...\n");
            sleep(1);
            continue; // Retry the loop
        }

        // Convert the raw value to lux
        lux_value = convert_to_lux(raw_value);

        // Send the lux value over UDP multicast
        if (send_udp_multicast(lux_value) < 0) {
            fprintf(stderr, "Error sending UDP multicast, retrying in 1 second...\n");
            sleep(1);
            continue; // Retry the loop
        }

        // Wait for 1 second
        sleep(1);
    }

    return 0;
}

