    udp_socket = socket(AF_INET, SOCK_DGRAM, 0);
    if (udp_socket < 0) {
        perror("Failed to create UDP socket");
        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (1) {
        // Read the raw light value
        if (read_bh1750(i2c_fd, &raw_value) < 0) {
            fprintf(stderr, "Error reading sensor, retrying in 1 second...\n");
            sleep(1);
            continue; // Retry the loop
        }

        // Convert the raw value to lux
        lux_value = convert_to_lux(raw_value);

        // Send the lux value over UDP multicast
        if (send_udp_multicast(lux_value) < 0) {
            fprintf(stderr, "Error sending UDP multicast, retrying in 1 second...\n");
            sleep(1);
            continue; // Retry the loop
        }

        // Wait for 1 second
        sleep(1);
    }

    return 0;
}

