#include <signal.h>
#include <pigpio.h>

#define UART_DEVICE "/dev/ttyS0"
#define BAUD_RATE 921600
#define MAGIC_WORD_LENGTH 8
#define MAX_FRAME_SIZE 4096
#define MAX_OBJECTS 100
#define CSV_FILE "radar_data.csv"

// Structure to hold radar data
typedef struct {
    time_t timestamp;
    int object_index;
    float range_m;
    float velocity_mps;
} RadarData;

// Global variables
int uart_handle;
FILE *csv_file;
volatile sig_atomic_t terminate = 0;

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "\nCaught signal %d, terminating gracefully...\n", signal);
    terminate = 1;
}

// Function to initialize the UART
int init_uart() {
    uart_handle = serOpen(UART_DEVICE, BAUD_RATE, 0); // 0 for default flags
    if (uart_handle < 0) {
        fprintf(stderr, "Error opening UART: %d\n", uart_handle);
        return -1;
    }
    return 0;
}

// Function to read data from the UART
int read_uart_data(char *buffer, int max_size) {
    int bytes_read = serRead(uart_handle, buffer, max_size);
    if (bytes_read < 0) {
        fprintf(stderr, "Error reading from UART: %d\n", bytes_read);
        return -1;
    }
    return bytes_read;
}

// Function to synchronize on the magic word
int synchronize_magic_word(const char *buffer, int buffer_size) {
    if (buffer_size < MAGIC_WORD_LENGTH) {
        return 0; // Not enough data to check
    }

    for (int i = 0; i <= buffer_size - MAGIC_WORD_LENGTH; ++i) {
        if (memcmp(buffer + i, "\x02\x04\x03\x06\x08\x05\x07\x09", MAGIC_WORD_LENGTH) == 0) {
            return i; // Return the offset of the magic word
        }
    }
    return -1; // Magic word not found
}

// Function to parse the TLV payload
int parse_tlv_payload(const char *buffer, int buffer_size, int magic_word_offset, RadarData *radar_data, int *num_objects) {
    int offset = magic_word_offset + MAGIC_WORD_LENGTH;
    int tlv_type, tlv_length;

    while (offset < buffer_size) {
        if (offset + 4 > buffer_size) {
            fprintf(stderr, "Error: TLV length field out of bounds\n");
            return -1;
        }

        tlv_type = *((unsigned short *)(buffer + offset));
        tlv_length = *((unsigned short *)(buffer + offset + 2));

        offset += 4;

        if (offset + tlv_length > buffer_size) {
            fprintf(stderr, "Error: TLV data out of bounds\n");
            return -1;
        }

        // Example: Assuming TLV type 1 contains range and velocity data
        if (tlv_type == 1) {
            // Assuming range is at offset 0 and velocity at offset 4 (float)
            radar_data[*num_objects].range_m = *((float *)(buffer + offset));
            radar_data[*num_objects].velocity_mps = *((float *)(buffer + offset + 4));

            // Get current timestamp
            radar_data[*num_objects].timestamp = time(NULL);
            radar_data[*num_objects].object_index = *num_objects;

            (*num_objects)++;

            if (*num_objects >= MAX_OBJECTS) {
                fprintf(stderr, "Warning: Maximum number of objects reached\n");
                break;
            }
        }

        offset += tlv_length;
    }

    return 0;
}

// Function to write data to the CSV file
int write_to_csv(const RadarData *radar_data, int num_objects) {
    for (int i = 0; i < num_objects; ++i) {
        fprintf(csv_file, "%ld,%d,%.2f,%.2f\n", radar_data[i].timestamp, radar_data[i].object_index, radar_data[i].range_m, radar_data[i].velocity_mps);
    }
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize UART
    if (init_uart() != 0) {
        gpioTerminate();
        return 1;
    }

    // Open CSV file
    csv_file = fopen(CSV_FILE, "a");
    if (csv_file == NULL) {
        fprintf(stderr, "Error opening CSV file\n");
        serClose(uart_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    char buffer[MAX_FRAME_SIZE];
    int num_objects = 0;
    RadarData radar_data[MAX_OBJECTS];
    int bytes_read;
    int magic_word_offset;

    // Main loop
    while (!terminate) {
        bytes_read = read_uart_data(buffer, MAX_FRAME_SIZE);
        if (bytes_read > 0) {
            magic_word_offset = synchronize_magic_word(buffer, bytes_read);
            if (magic_word_offset >= 0) {
                num_objects = 0; // Reset object count for each frame
                if (parse_tlv_payload(buffer, bytes_read, magic_word_offset, radar_data, &num_objects) == 0) {
                    write_to_csv(radar_data, num_objects);
                    fflush(csv_file); // Flush the buffer to ensure data is written
                } else {
                    fprintf(stderr, "Error parsing TLV payload\n");
                }
            } else {
                //fprintf(stderr, "Magic word not found\n"); //Commented out to reduce verbosity
            }
        } else if (bytes_read < 0) {
            fprintf(stderr, "Error reading from UART, retrying...\n");
            gpioDelay(100); // Wait before retrying
        }

        gpioDelay(1); // Small delay to prevent busy-waiting
    }

    // Cleanup
    serClose(uart_handle);
    fclose(csv_file);
    gpioTerminate();

    return 0;
}

