#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <termios.h>
#include <unistd.h>
#include <errno.h>
#include <signal.h>
#include <sys/select.h>
#include <time.h>

#define UART_DEVICE "/dev/serial0"
#define BAUD_RATE B115200
#define TIMEOUT_SEC 2
#define MAX_LINE_LENGTH 256

volatile sig_atomic_t program_running = 1;
int uart_fd = -1;

void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

int configure_uart(int fd) {
    struct termios tty;

    if (tcgetattr(fd, &tty) != 0) {
        perror("tcgetattr failed");
        return -1;
    }

    tty.c_cflag = BAUD_RATE | CS8 | CLOCAL | CREAD;  // 8N1
    tty.c_iflag = IGNPAR;                           // Ignore parity errors
    tty.c_oflag = 0;
    tty.c_lflag = 0;                               // Non-canonical mode
    tty.c_cc[VMIN] = 0;                              // Read at least 0 characters
    tty.c_cc[VTIME] = 5;                             // Wait for 0.5 seconds (5 * 0.1s)

    if (tcsetattr(fd, TCSANOW, &tty) != 0) {
        perror("tcsetattr failed");
        return -1;
    }

    return 0;
}

int read_radar_data(int fd, char *buffer, size_t buffer_size) {
    fd_set readfds;
    struct timeval timeout;
    int bytes_read;

    FD_ZERO(&readfds);
    FD_SET(fd, &readfds);

    timeout.tv_sec = TIMEOUT_SEC;
    timeout.tv_usec = 0;

    int select_result = select(fd + 1, &readfds, NULL, NULL, &timeout);

    if (select_result == -1) {
        perror("select failed");
        return -1;
    } else if (select_result == 0) {
        // Timeout occurred
        return 0;
    } else {
        bytes_read = read(fd, buffer, buffer_size - 1);
        if (bytes_read == -1) {
            perror("read failed");
            return -1;
        } else {
            buffer[bytes_read] = '\0';
            return bytes_read;
        }
    }
}

int parse_radar_data(const char *line) {
    char *timestamp_str, *range_str;
    long timestamp;
    float range;

    timestamp_str = strtok((char *)line, ",");
    range_str = strtok(NULL, "\n");

    if (timestamp_str == NULL || range_str == NULL) {
        fprintf(stderr, "Error: Invalid data format\n");
        return -1;
    }

    if (sscanf(timestamp_str, "%ld", &timestamp) != 1) {
        fprintf(stderr, "Error: Invalid timestamp format\n");
        return -1;
    }

    if (sscanf(range_str, "%f", &range) != 1) {
        fprintf(stderr, "Error: Invalid range format\n");
        return -1;
    }

    if (range < 0.0 || range > 10.0) {
        fprintf(stderr, "Error: Range out of bounds (0.0 - 10.0 meters)\n");
        return -1;
    }

    return 0;
}

void log_detection(long timestamp, float range) {
    time_t rawtime = timestamp;
    struct tm *timeinfo;
    char timestamp_str[20];

    timeinfo = localtime(&rawtime);
    strftime(timestamp_str, sizeof(timestamp_str), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("Timestamp: %s, Range: %.2f meters\n", timestamp_str, range);
}

int main() {
    char line_buffer[MAX_LINE_LENGTH];
    int bytes_read;
    char *timestamp_str, *range_str;
    long timestamp;
    float range;

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    uart_fd = open(UART_DEVICE, O_RDWR | O_NOCTTY | O_NONBLOCK);
    if (uart_fd == -1) {
        perror("open failed");
        return EXIT_FAILURE;
    }

    if (configure_uart(uart_fd) != 0) {
        close(uart_fd);
        return EXIT_FAILURE;
    }

    printf("Radar data acquisition started...\n");

    while (program_running) {
        bytes_read = read_radar_data(uart_fd, line_buffer, MAX_LINE_LENGTH);

        if (bytes_read > 0) {
            if (parse_radar_data(line_buffer) == 0) {
                timestamp = strtol(strtok((char *)line_buffer, ","), NULL, 10);
                range = strtof(strtok(NULL, "\n"), NULL);
                log_detection(timestamp, range);
            }
        }
    }

    close(uart_fd);
    printf("Radar data acquisition stopped.\n");

    return EXIT_SUCCESS;
}

